/// Public `RootSource` declaration.
pub const HoistedRootSource = struct {
    index: u32,
    expr: CIR.Expr.Idx,
};

/// Source location of a checked root that must be published for later compiler stages.
pub const RootSource = union(enum(u8)) {
    def: CIR.Def.Idx,
    expr: CIR.Expr.Idx,
    statement: CIR.Statement.Idx,
    required_binding: u32,
    hoisted: HoistedRootSource,
};

/// Public `RootRequest` declaration.
pub const RootRequest = struct {
    order: u32,
    module_idx: u32,
    kind: RootRequestKind,
    source: RootSource,
    /// Exact checked root selected for this request. Compile-time roots can
    /// share a source expression, so source and broad request kind are not an
    /// identity.
    compile_time_root: ?ComptimeRootId = null,
    checked_type: CheckedTypeId,
    abi: RootAbi,
    exposure: RootExposure,
    procedure_template: ?canonical.ProcedureTemplateRef = null,
    procedure_binding: ?TopLevelProcedureBindingRef = null,
    procedure_use: ?ProcedureUseTemplate = null,
    root_evidence: ?CheckedEvidenceSpan = null,
};

/// Public `LoweringEntrypointRequest` declaration.
pub const LoweringEntrypointRequest = union(enum) {
    root: RootRequest,
};

/// Public `RootRequestTable` declaration.
pub const RootRequestTable = struct {
    requests: []RootRequest = &.{},
    runtime_requests: []RootRequest = &.{},
    /// Compile-time requests sorted by same-module stored-constant
    /// dependencies. This slice is the durable same-module compile-time
    /// evaluation schedule consumed by checking finalization; temporary
    /// dependency edges used to compute it are not stored.
    compile_time_requests: []RootRequest = &.{},

    pub const Serialized = extern struct {
        requests: SerializedSlice(RootRequest) = .{},
        runtime_requests: SerializedSlice(RootRequest) = .{},
        compile_time_requests: SerializedSlice(RootRequest) = .{},
        const Serde = artifact_serialize.SliceStoreSerde(RootRequestTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    pub fn fromModule(
        allocator: Allocator,
        module: TypedCIR.Module,
        artifact_key: CheckedModuleArtifactKey,
        names: *const canonical.CanonicalNameStore,
        checked_types: *CheckedTypePublication,
        compile_time_roots: *const CompileTimeRootTable,
        procedure_templates: *const CheckedProcedureTemplateTable,
        entry_wrappers: *const EntryWrapperTable,
        relation_substitutions: *const PlatformRelationTypeSubstitutions,
        platform_app_relation: ?PlatformAppRelationKey,
        platform_required_declarations: *const PlatformRequiredDeclarationTable,
        platform_required_bindings: *const PlatformRequiredBindingTable,
        provided_exports: *const ProvidedExportTable,
        checked_bodies: *const CheckedBodyStore,
        resolved_value_refs: *const ResolvedValueRefTable,
        top_level_values: *const TopLevelValueTable,
        top_level_procedure_bindings: *const TopLevelProcedureBindingTable,
        callable_eval_templates: *const CallableEvalTemplateTable,
        hoisted_constants: *const HoistedConstTable,
        template_root_evidence: []const artifact_serialize.Span,
        explicit_roots: []const ExplicitRootRequestInput,
    ) Allocator.Error!RootRequestTable {
        var requests = std.ArrayList(RootRequest).empty;
        errdefer requests.deinit(allocator);

        const relation_blocked_exprs = try allocator.alloc(?bool, checked_bodies.exprCount());
        defer allocator.free(relation_blocked_exprs);
        @memset(relation_blocked_exprs, null);

        for (explicit_roots) |root| {
            if (!explicitRootMatchesCheckedRootKind(procedure_templates, compile_time_roots, root)) continue;
            if (!explicitCompileTimeRootRequestIsEligible(compile_time_roots, root)) continue;
            const source_checked_type = try checkedTypeIdForRootSource(allocator, module, checked_types, root.source);
            const backing = explicitRootBackingProcedure(
                procedure_templates,
                compile_time_roots,
                entry_wrappers,
                root.source,
                root.kind,
                source_checked_type,
            );
            try appendRoot(&requests, allocator, .{
                .module_idx = module.moduleIndex(),
                .kind = root.kind,
                .source = root.source,
                .compile_time_root = backing.compile_time_root,
                .checked_type = backing.checked_type,
                .abi = root.abi,
                .exposure = root.exposure,
                .procedure_template = backing.template,
            });
        }

        try appendPublishedEntrypointRoots(
            &requests,
            allocator,
            module,
            names,
            checked_types,
            procedure_templates,
            provided_exports,
            top_level_values,
            top_level_procedure_bindings,
            relation_substitutions,
            platform_app_relation,
            platform_required_declarations,
        );

        for (platform_required_bindings.bindings, 0..) |binding, i| {
            switch (binding.value_use) {
                .procedure_value => |procedure_use| try appendRoot(&requests, allocator, .{
                    .module_idx = module.moduleIndex(),
                    .kind = .platform_required_binding,
                    .source = .{ .required_binding = @intCast(i) },
                    .checked_type = platformRequiredBindingCheckedType(binding),
                    .abi = .platform,
                    .exposure = .platform_required,
                    .procedure_use = procedure_use.procedure,
                    .root_evidence = procedure_use.root_evidence,
                }),
                .const_value => {},
            }
        }

        for (compile_time_roots.roots) |root| {
            if (!compileTimeRootRequestIsEligible(root)) continue;
            if (compileTimeCallableRootIsProcedureReference(checked_bodies, resolved_value_refs, root)) {
                continue;
            }
            if (compileTimeRootDependsOnUnboundPlatformRequirement(
                checked_bodies,
                resolved_value_refs,
                root,
                relation_blocked_exprs,
            )) {
                continue;
            }
            if (compileTimeRootHasRootRequest(requests.items, root)) {
                continue;
            }
            try appendRoot(&requests, allocator, .{
                .module_idx = root.module_idx,
                .kind = switch (root.kind) {
                    .constant, .hoisted_constant, .numeral_conversion, .quote_conversion, .field_default => .compile_time_constant,
                    .callable_binding => .compile_time_callable,
                    .expect => .test_expect,
                },
                .source = root.source,
                .compile_time_root = root.id,
                .checked_type = entryWrapperForRoot(entry_wrappers, root.id).checked_fn_root,
                .abi = switch (root.kind) {
                    .expect => .test_expect,
                    .constant, .hoisted_constant, .callable_binding, .numeral_conversion, .quote_conversion, .field_default => .compile_time,
                },
                .exposure = .private,
                .procedure_template = templateForEntryWrapperRoot(entry_wrappers, root.id),
            });
        }

        if (template_root_evidence.len != procedure_templates.templates.len) {
            checkedArtifactInvariant("template root evidence and procedure template tables had different lengths", .{});
        }
        for (requests.items) |*request| {
            if (request.root_evidence != null) continue;
            const template_ref = request.procedure_template orelse continue;
            if (!checkedArtifactKeyEql(checkedArtifactKeyFromArtifactRef(template_ref.artifact), artifact_key)) {
                checkedArtifactInvariant("root procedure template belonged to a different checked artifact", .{});
            }
            request.root_evidence = .{
                .checked_module = artifact_key,
                .span = template_root_evidence[@intFromEnum(template_ref.template)],
            };
        }

        const all_requests = try requests.toOwnedSlice(allocator);
        errdefer allocator.free(all_requests);

        const runtime_requests = try collectRuntimeRootRequests(allocator, all_requests);
        errdefer allocator.free(runtime_requests);

        if (!module.moduleEnvConst().topLevelDemandDependenciesReady()) {
            checkedArtifactInvariant("checked module had no top-level demand dependencies", .{});
        }
        const compile_time_requests = try collectCompileTimeRootRequests(
            allocator,
            all_requests,
            module.moduleIndex(),
            artifact_key,
            module.moduleEnvConst().topLevelDemandDependencies(),
            compile_time_roots,
            procedure_templates,
            resolved_value_refs,
            top_level_procedure_bindings,
            platform_required_bindings,
            callable_eval_templates,
            hoisted_constants,
        );
        verifyCompileTimeRequestsScheduled(compile_time_requests, compile_time_roots);

        return .{
            .requests = all_requests,
            .runtime_requests = runtime_requests,
            .compile_time_requests = compile_time_requests,
        };
    }

    pub fn deinit(self: *RootRequestTable, allocator: Allocator) void {
        allocator.free(self.compile_time_requests);
        allocator.free(self.runtime_requests);
        allocator.free(self.requests);
        self.* = .{};
    }
};

fn explicitRootMatchesCheckedRootKind(
    procedure_templates: *const CheckedProcedureTemplateTable,
    compile_time_roots: *const CompileTimeRootTable,
    root: ExplicitRootRequestInput,
) bool {
    if (procedureTemplateForRootSource(procedure_templates, root.source) != null) {
        return root.kind != .compile_time_constant and root.kind != .compile_time_callable;
    }

    return compileTimeRootIdForSourceAndRequestKind(compile_time_roots, root.source, root.kind) != null;
}

fn explicitCompileTimeRootRequestIsEligible(
    compile_time_roots: *const CompileTimeRootTable,
    root: ExplicitRootRequestInput,
) bool {
    const root_id = compileTimeRootIdForSourceAndRequestKind(compile_time_roots, root.source, root.kind) orelse return true;
    const compile_time_root = compile_time_roots.root(root_id);
    return compileTimeRootRequestIsEligible(compile_time_root);
}

fn compileTimeRootIdForSourceAndRequestKind(
    compile_time_roots: *const CompileTimeRootTable,
    source: RootSource,
    request_kind: RootRequestKind,
) ?ComptimeRootId {
    for (compile_time_roots.roots) |root| {
        if (!rootSourceMatches(root.source, source)) continue;
        if (!compileTimeRootKindMatchesRequest(root.kind, request_kind)) continue;
        return root.id;
    }
    return null;
}

fn collectRuntimeRootRequests(
    allocator: Allocator,
    requests: []const RootRequest,
) Allocator.Error![]RootRequest {
    var runtime_requests = std.ArrayList(RootRequest).empty;
    errdefer runtime_requests.deinit(allocator);

    for (requests) |request| {
        if (request.abi == .compile_time) continue;
        try runtime_requests.append(allocator, request);
    }

    return try runtime_requests.toOwnedSlice(allocator);
}

const CompileTimeRequestScheduleEntry = struct {
    request: RootRequest,
    root_id: ComptimeRootId,
    original_order: u32,
};

fn collectScheduledFieldDefaultRoots(
    allocator: Allocator,
    compile_time_roots: *const CompileTimeRootTable,
    entries: []const CompileTimeRequestScheduleEntry,
) Allocator.Error![]ComptimeRootId {
    var roots = std.ArrayList(ComptimeRootId).empty;
    errdefer roots.deinit(allocator);
    for (entries) |entry| {
        if (compile_time_roots.root(entry.root_id).kind == .field_default) {
            try roots.append(allocator, entry.root_id);
        }
    }
    return try roots.toOwnedSlice(allocator);
}

fn collectCompileTimeRootRequests(
    allocator: Allocator,
    requests: []const RootRequest,
    module_idx: u32,
    artifact_key: CheckedModuleArtifactKey,
    top_level_demand_dependencies: []const TopLevelDemandDependency,
    compile_time_roots: *const CompileTimeRootTable,
    procedure_templates: *const CheckedProcedureTemplateTable,
    resolved_value_refs: *const ResolvedValueRefTable,
    top_level_procedure_bindings: *const TopLevelProcedureBindingTable,
    platform_required_bindings: *const PlatformRequiredBindingTable,
    callable_eval_templates: *const CallableEvalTemplateTable,
    hoisted_constants: *const HoistedConstTable,
) Allocator.Error![]RootRequest {
    var entries = std.ArrayList(CompileTimeRequestScheduleEntry).empty;
    defer entries.deinit(allocator);

    for (requests) |request| {
        if (request.abi != .compile_time) continue;
        const root_id = compileTimeRootIdForRequest(compile_time_roots, request);
        try entries.append(allocator, .{
            .request = request,
            .root_id = root_id,
            .original_order = @intCast(entries.items.len),
        });
    }

    var scheduler = try CompileTimeRequestScheduler.init(
        allocator,
        module_idx,
        artifact_key,
        top_level_demand_dependencies,
        compile_time_roots,
        procedure_templates,
        resolved_value_refs,
        top_level_procedure_bindings,
        platform_required_bindings,
        callable_eval_templates,
        hoisted_constants,
        entries.items,
    );
    defer scheduler.deinit();

    return try scheduler.sortedRequests();
}

const CompileTimeRequestScheduler = struct {
    allocator: Allocator,
    module_idx: u32,
    artifact_key: CheckedModuleArtifactKey,
    top_level_demand_dependencies: []const TopLevelDemandDependency,
    compile_time_roots: *const CompileTimeRootTable,
    procedure_templates: *const CheckedProcedureTemplateTable,
    resolved_value_refs: *const ResolvedValueRefTable,
    top_level_procedure_bindings: *const TopLevelProcedureBindingTable,
    platform_required_bindings: *const PlatformRequiredBindingTable,
    callable_eval_templates: *const CallableEvalTemplateTable,
    hoisted_constants: *const HoistedConstTable,
    entries: []const CompileTimeRequestScheduleEntry,
    field_default_roots: []const ComptimeRootId,
    root_to_request_index: []?usize,
    dependents: []std.ArrayList(usize),
    indegrees: []u32,
    emitted: []bool,
    visited_templates: []u32,
    seen_edges: std.AutoHashMap(u64, void),
    visit: u32 = 0,
    current_request_index: usize = 0,
    current_root_id: ComptimeRootId = undefined, // Set before dependency collection for each scheduled root.

    fn init(
        allocator: Allocator,
        module_idx: u32,
        artifact_key: CheckedModuleArtifactKey,
        top_level_demand_dependencies: []const TopLevelDemandDependency,
        compile_time_roots: *const CompileTimeRootTable,
        procedure_templates: *const CheckedProcedureTemplateTable,
        resolved_value_refs: *const ResolvedValueRefTable,
        top_level_procedure_bindings: *const TopLevelProcedureBindingTable,
        platform_required_bindings: *const PlatformRequiredBindingTable,
        callable_eval_templates: *const CallableEvalTemplateTable,
        hoisted_constants: *const HoistedConstTable,
        entries: []const CompileTimeRequestScheduleEntry,
    ) Allocator.Error!CompileTimeRequestScheduler {
        const field_default_roots = try collectScheduledFieldDefaultRoots(allocator, compile_time_roots, entries);
        errdefer allocator.free(field_default_roots);

        const root_to_request_index = try allocator.alloc(?usize, compile_time_roots.roots.len);
        errdefer allocator.free(root_to_request_index);
        @memset(root_to_request_index, null);

        const dependents = try allocator.alloc(std.ArrayList(usize), entries.len);
        errdefer allocator.free(dependents);
        for (dependents) |*list| list.* = .empty;

        const indegrees = try allocator.alloc(u32, entries.len);
        errdefer allocator.free(indegrees);
        @memset(indegrees, 0);

        const emitted = try allocator.alloc(bool, entries.len);
        errdefer allocator.free(emitted);
        @memset(emitted, false);

        const visited_templates = try allocator.alloc(u32, procedure_templates.templates.len);
        errdefer allocator.free(visited_templates);
        @memset(visited_templates, 0);

        for (entries, 0..) |entry, i| {
            const root_index = @intFromEnum(entry.root_id);
            if (root_index >= root_to_request_index.len) {
                checkedArtifactInvariant("compile-time request root id was outside the root table", .{});
            }
            if (root_to_request_index[root_index] != null) {
                checkedArtifactInvariant("compile-time root was requested more than once", .{});
            }
            root_to_request_index[root_index] = i;
        }

        return .{
            .allocator = allocator,
            .module_idx = module_idx,
            .artifact_key = artifact_key,
            .top_level_demand_dependencies = top_level_demand_dependencies,
            .compile_time_roots = compile_time_roots,
            .procedure_templates = procedure_templates,
            .resolved_value_refs = resolved_value_refs,
            .top_level_procedure_bindings = top_level_procedure_bindings,
            .platform_required_bindings = platform_required_bindings,
            .callable_eval_templates = callable_eval_templates,
            .hoisted_constants = hoisted_constants,
            .entries = entries,
            .field_default_roots = field_default_roots,
            .root_to_request_index = root_to_request_index,
            .dependents = dependents,
            .indegrees = indegrees,
            .emitted = emitted,
            .visited_templates = visited_templates,
            .seen_edges = std.AutoHashMap(u64, void).init(allocator),
        };
    }

    fn deinit(self: *CompileTimeRequestScheduler) void {
        self.seen_edges.deinit();
        self.allocator.free(self.visited_templates);
        self.allocator.free(self.emitted);
        self.allocator.free(self.indegrees);
        for (self.dependents) |*list| list.deinit(self.allocator);
        self.allocator.free(self.dependents);
        self.allocator.free(self.root_to_request_index);
        self.allocator.free(self.field_default_roots);
        self.* = undefined;
    }

    fn sortedRequests(self: *CompileTimeRequestScheduler) Allocator.Error![]RootRequest {
        try self.buildEdges();

        var sorted = std.ArrayList(RootRequest).empty;
        errdefer sorted.deinit(self.allocator);

        while (sorted.items.len < self.entries.len) {
            const next = self.nextReadyRequestIndex() orelse {
                checkedArtifactInvariant("compile-time root dependency cycle reached request scheduling", .{});
            };
            self.emitted[next] = true;
            try sorted.append(self.allocator, self.entries[next].request);

            for (self.dependents[next].items) |dependent| {
                if (self.indegrees[dependent] == 0) {
                    checkedArtifactInvariant("compile-time root dependency edge underflowed during scheduling", .{});
                }
                self.indegrees[dependent] -= 1;
            }
        }

        return try sorted.toOwnedSlice(self.allocator);
    }

    fn nextReadyRequestIndex(self: *const CompileTimeRequestScheduler) ?usize {
        for (self.entries, 0..) |_, i| {
            if (self.emitted[i]) continue;
            if (self.indegrees[i] != 0) continue;
            return i;
        }
        return null;
    }

    fn buildEdges(self: *CompileTimeRequestScheduler) Allocator.Error!void {
        for (self.entries, 0..) |entry, i| {
            self.current_request_index = i;
            self.current_root_id = entry.root_id;

            if (self.field_default_roots.len != 0 and self.compile_time_roots.root(entry.root_id).kind != .field_default) {
                for (self.field_default_roots) |field_default_root| {
                    try self.addUnconditionalRootDependency(field_default_root);
                }
            }

            self.beginDependencyVisit();
            const template_ref = entry.request.procedure_template orelse {
                checkedArtifactInvariant("compile-time root request had no entry wrapper template", .{});
            };
            try self.collectTemplateDependencies(template_ref);
        }
    }

    fn beginDependencyVisit(self: *CompileTimeRequestScheduler) void {
        self.visit +%= 1;
        if (self.visit != 0) return;
        @memset(self.visited_templates, 0);
        self.visit = 1;
    }

    fn collectTemplateDependencies(
        self: *CompileTimeRequestScheduler,
        template_ref: canonical.ProcedureTemplateRef,
    ) Allocator.Error!void {
        if (!checkedArtifactKeyEql(checkedArtifactKeyFromArtifactRef(template_ref.artifact), self.artifact_key)) return;
        const index = @intFromEnum(template_ref.template);
        if (index >= self.visited_templates.len) {
            checkedArtifactInvariant("compile-time request dependency referenced an unknown local procedure template", .{});
        }
        if (self.visited_templates[index] == self.visit) return;
        self.visited_templates[index] = self.visit;

        const template = self.procedure_templates.get(template_ref.template);
        try self.collectResolvedRefDependencies(template.resolved_value_refs);
    }

    fn collectResolvedRefDependencies(
        self: *CompileTimeRequestScheduler,
        refs: ResolvedValueRefTableRef,
    ) Allocator.Error!void {
        const end = refs.start + refs.len;
        if (end > self.resolved_value_refs.template_refs.len) {
            checkedArtifactInvariant("compile-time request dependency ref span was outside the checked table", .{});
        }
        for (self.resolved_value_refs.template_refs[refs.start..end]) |ref_id| {
            const raw = @intFromEnum(ref_id);
            if (raw >= self.resolved_value_refs.records.len) {
                checkedArtifactInvariant("compile-time request dependency ref id was outside the checked table", .{});
            }
            try self.collectResolvedRefDependency(self.resolved_value_refs.records[raw].ref);
        }
    }

    fn collectResolvedRefDependency(
        self: *CompileTimeRequestScheduler,
        ref: ResolvedValueRef,
    ) Allocator.Error!void {
        switch (ref) {
            .top_level_const => |const_use| try self.addConstUseDependency(const_use),
            .selected_hoisted_const => |selected| try self.addConstUseDependency(selected.const_use),
            .top_level_proc,
            .promoted_top_level_proc,
            => |procedure| try self.collectProcedureUseDependencies(procedure),
            .platform_required_const => |required| try self.addConstUseDependency(required.const_use),
            .platform_required_proc => |required| try self.collectProcedureUseDependencies(required.procedure),
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            .local_proc,
            .imported_const,
            .imported_proc,
            .hosted_proc,
            .platform_required_declaration,
            .platform_required_checked_error,
            => {},
        }
    }

    fn collectProcedureUseDependencies(
        self: *CompileTimeRequestScheduler,
        procedure: ProcedureUseTemplate,
    ) Allocator.Error!void {
        switch (procedure.binding) {
            .top_level => |top_level| {
                if (!checkedArtifactKeyEql(top_level.artifact, self.artifact_key)) return;
                const binding = self.top_level_procedure_bindings.get(top_level.binding);
                try self.collectProcedureBindingDependencies(binding.body);
            },
            .platform_required => |required| try self.collectPlatformRequiredProcedureDependencies(required),
            .imported,
            .hosted,
            => {},
        }
    }

    fn collectProcedureBindingDependencies(
        self: *CompileTimeRequestScheduler,
        body: ProcedureBindingBody,
    ) Allocator.Error!void {
        switch (body) {
            .direct_template => |direct| try self.collectCallableTemplateDependencies(direct.template),
            .callable_eval_template => |template_id| {
                const template = self.callable_eval_templates.get(template_id);
                try self.addRootDependency(template.root);
            },
        }
    }

    fn collectCallableTemplateDependencies(
        self: *CompileTimeRequestScheduler,
        template: canonical.CallableProcedureTemplateRef,
    ) Allocator.Error!void {
        switch (template) {
            .checked => |checked_template| try self.collectTemplateDependencies(checked_template),
            .lifted,
            .synthetic,
            => checkedArtifactInvariant("checked compile-time dependency referenced a post-check template", .{}),
        }
    }

    fn collectPlatformRequiredProcedureDependencies(
        self: *CompileTimeRequestScheduler,
        required: RequiredAppProcedureRef,
    ) Allocator.Error!void {
        if (!checkedArtifactKeyEql(required.artifact, self.artifact_key)) return;
        const binding = self.platform_required_bindings.lookupByBindingId(@intFromEnum(required.procedure_binding)) orelse {
            checkedArtifactInvariant("platform-required procedure dependency referenced a missing binding", .{});
        };
        switch (binding.value_use) {
            .procedure_value => |procedure| try self.collectProcedureUseDependencies(procedure.procedure),
            .const_value => |const_value| try self.addConstUseDependency(const_value.const_use),
        }
    }

    fn addConstUseDependency(
        self: *CompileTimeRequestScheduler,
        const_use: ConstUseTemplate,
    ) Allocator.Error!void {
        const root_id = self.rootForConstRef(const_use.const_ref) orelse return;
        const own_hoisted_root = switch (const_use.const_ref.owner) {
            .hoisted_expr => true,
            .top_level_binding => false,
        };
        if (root_id == self.current_root_id and own_hoisted_root) return;
        try self.addRootDependency(root_id);
    }

    fn rootForConstRef(
        self: *CompileTimeRequestScheduler,
        const_ref: ConstRef,
    ) ?ComptimeRootId {
        if (!checkedArtifactKeyEql(const_ref.artifact, self.artifact_key)) return null;
        return switch (const_ref.owner) {
            .top_level_binding => |top_level| blk: {
                if (top_level.module_idx != self.module_idx) {
                    checkedArtifactInvariant("local top-level const dependency had mismatched module index", .{});
                }
                break :blk self.compile_time_roots.lookupIdByPattern(top_level.pattern) orelse
                    checkedArtifactInvariant("local const dependency had no compile-time root", .{});
            },
            .hoisted_expr => |hoisted| blk: {
                if (hoisted.module_idx != self.module_idx) {
                    checkedArtifactInvariant("local hoisted const dependency had mismatched module index", .{});
                }
                const entry = self.hoisted_constants.lookupByExpr(hoisted.expr) orelse
                    checkedArtifactInvariant("local hoisted const dependency had no hoisted const entry", .{});
                break :blk entry.root;
            },
        };
    }

    fn addRootDependency(
        self: *CompileTimeRequestScheduler,
        dependency_root: ComptimeRootId,
    ) Allocator.Error!void {
        if (dependency_root == self.current_root_id) return;
        if (!self.rootDependencyIsStrict(dependency_root)) return;
        try self.addUnconditionalRootDependency(dependency_root);
    }

    fn addUnconditionalRootDependency(
        self: *CompileTimeRequestScheduler,
        dependency_root: ComptimeRootId,
    ) Allocator.Error!void {
        if (dependency_root == self.current_root_id) return;
        const raw = @intFromEnum(dependency_root);
        if (raw >= self.root_to_request_index.len) {
            checkedArtifactInvariant("compile-time root dependency was outside the root table", .{});
        }
        const dependency_index = self.root_to_request_index[raw] orelse return;
        const edge_key = dependencyEdgeKey(dependency_index, self.current_request_index);
        const edge = try self.seen_edges.getOrPut(edge_key);
        if (edge.found_existing) return;
        edge.value_ptr.* = {};
        try self.dependents[dependency_index].append(self.allocator, self.current_request_index);
        self.indegrees[self.current_request_index] += 1;
    }

    fn rootDependencyIsStrict(
        self: *const CompileTimeRequestScheduler,
        dependency_root: ComptimeRootId,
    ) bool {
        const dependent = self.compile_time_roots.root(self.current_root_id);
        const dependency = self.compile_time_roots.root(dependency_root);
        return switch (dependent.source) {
            .def => |dependent_def| switch (dependency.source) {
                .def => |dependency_def| can.DependencyGraph.hasDependency(
                    self.top_level_demand_dependencies,
                    dependent_def,
                    dependency_def,
                ),
                .expr, .statement, .required_binding, .hoisted => true,
            },
            .expr, .statement, .required_binding, .hoisted => true,
        };
    }

    fn dependencyEdgeKey(
        dependency_index: usize,
        dependent_index: usize,
    ) u64 {
        if (dependency_index > std.math.maxInt(u32) or dependent_index > std.math.maxInt(u32)) {
            checkedArtifactInvariant("compile-time dependency edge index exceeded scheduler key capacity", .{});
        }
        return (@as(u64, @intCast(dependency_index)) << 32) | @as(u64, @intCast(dependent_index));
    }
};

fn compileTimeRootIdForRequest(
    compile_time_roots: *const CompileTimeRootTable,
    request: RootRequest,
) ComptimeRootId {
    const root_id = request.compile_time_root orelse {
        checkedArtifactInvariant("compile-time request had no exact compile-time root identity", .{});
    };
    const raw = @intFromEnum(root_id);
    if (raw >= compile_time_roots.roots.len) {
        checkedArtifactInvariant("compile-time request root identity was outside the checked root table", .{});
    }
    const root = compile_time_roots.roots[raw];
    if (root.id != root_id or
        !compileTimeRootKindMatchesRequest(root.kind, request.kind) or
        !rootSourceMatches(root.source, request.source))
    {
        checkedArtifactInvariant("compile-time request identity did not match its checked root", .{});
    }
    return root_id;
}

fn verifyCompileTimeRequestsScheduled(
    requests: []const RootRequest,
    compile_time_roots: *const CompileTimeRootTable,
) void {
    if (builtin.mode != .Debug) return;
    for (requests, 0..) |request, i| {
        if (request.abi != .compile_time) {
            std.debug.panic("checked artifact invariant violated: scheduled compile-time requests contained a non compile-time request", .{});
        }
        const root_id = compileTimeRootIdForRequest(compile_time_roots, request);
        for (requests[0..i]) |previous| {
            const previous_id = compileTimeRootIdForRequest(compile_time_roots, previous);
            if (previous_id == root_id) {
                std.debug.panic("checked artifact invariant violated: compile-time root was scheduled more than once", .{});
            }
        }
    }
}

/// Which graph the concreteness walk is inspecting: the value graph (type
/// variables are NOT concrete) or a nominal declaration's backing template
/// (rigids there are the declaration's formals, standing for args the walk
/// already checked at the application, so they count as concrete).
const ConcreteRootWalk = enum { value_graph, decl_template };

fn checkedTypeIsConcreteCompileTimeRoot(
    allocator: Allocator,
    checked_types: *const CheckedTypeStore,
    root: CheckedTypeId,
) Allocator.Error!bool {
    var active = collections.DenseMap(CheckedTypeId, void).init(allocator);
    defer active.deinit();
    return try checkedTypeIsConcreteCompileTimeRootInner(.value_graph, checked_types, root, &active);
}

fn checkedTypeIsConcreteCompileTimeRootInner(
    comptime walk: ConcreteRootWalk,
    checked_types: *const CheckedTypeStore,
    root: CheckedTypeId,
    active: *collections.DenseMap(CheckedTypeId, void),
) Allocator.Error!bool {
    if (active.contains(root)) return true;
    try active.put(root, {});
    defer _ = active.remove(root);

    const index = @intFromEnum(root);
    if (index >= checked_types.payloads.items.len) {
        checkedArtifactInvariant("compile-time root checked type id is out of range", .{});
    }
    return switch (checked_types.payload(@enumFromInt(index))) {
        .pending => checkedArtifactInvariant("compile-time root checked type was pending", .{}),
        .err => false,
        .flex => false,
        .rigid => walk == .decl_template,
        .empty_record,
        .empty_tag_union,
        => true,
        .alias => |alias| (try checkedTypeSpanIsConcreteCompileTimeRoot(walk, checked_types, alias.args, active)) and
            try checkedTypeIsConcreteCompileTimeRootInner(walk, checked_types, alias.backing, active),
        .record => |record| (try checkedFieldTypesAreConcreteCompileTimeRoots(walk, checked_types, record.fields, active)) and
            try checkedTypeIsConcreteCompileTimeRootInner(walk, checked_types, record.ext, active),
        .record_unbound => |fields| checkedFieldTypesAreConcreteCompileTimeRoots(walk, checked_types, fields, active),
        .tuple => |items| checkedTypeSpanIsConcreteCompileTimeRoot(walk, checked_types, items, active),
        .nominal => |nominal| blk: {
            if (!try checkedTypeSpanIsConcreteCompileTimeRoot(walk, checked_types, nominal.args, active)) break :blk false;
            switch (nominal.representation) {
                .builtin => |builtin_type| switch (builtinRuntimeEncoding(builtin_type)) {
                    .primitive,
                    .list,
                    .box,
                    .dict,
                    .set,
                    .parse_tag_union_spec,
                    .fields,
                    .field,
                    => break :blk true,
                    .bool_tag_union,
                    .try_nominal,
                    .iterator,
                    .crypto_sha256_digest,
                    .crypto_sha256_hasher,
                    .crypto_blake3_digest,
                    .crypto_blake3_hasher,
                    => {},
                },
                .opaque_without_backing => break :blk true,
                .local_declaration,
                .imported_declaration,
                .local_box_payload_capability,
                .imported_box_payload_capability,
                => {},
            }
            const backing = checked_types.nominalBackingTemplateForPayload(nominal) orelse break :blk true;
            // Declaration formals stand for the args checked above, so they
            // count as concrete while walking the backing template.
            break :blk try checkedTypeIsConcreteCompileTimeRootInner(.decl_template, checked_types, backing, active);
        },
        // A function scheme is a concrete compile-time root exactly when its
        // args and return contain no identity variables.
        .function => |function| (try checkedTypeSpanIsConcreteCompileTimeRoot(walk, checked_types, function.args, active)) and
            try checkedTypeIsConcreteCompileTimeRootInner(walk, checked_types, function.ret, active),
        .tag_union => |tag_union| (try checkedTagsAreConcreteCompileTimeRoots(walk, checked_types, tag_union.tags, active)) and
            try checkedTypeIsConcreteCompileTimeRootInner(walk, checked_types, tag_union.ext, active),
    };
}

fn checkedTypeSpanIsConcreteCompileTimeRoot(
    comptime walk: ConcreteRootWalk,
    checked_types: *const CheckedTypeStore,
    items: []const CheckedTypeId,
    active: *collections.DenseMap(CheckedTypeId, void),
) Allocator.Error!bool {
    for (items) |item| {
        if (!try checkedTypeIsConcreteCompileTimeRootInner(walk, checked_types, item, active)) return false;
    }
    return true;
}

fn checkedFieldTypesAreConcreteCompileTimeRoots(
    comptime walk: ConcreteRootWalk,
    checked_types: *const CheckedTypeStore,
    fields: []const CheckedRecordField,
    active: *collections.DenseMap(CheckedTypeId, void),
) Allocator.Error!bool {
    for (fields) |field| {
        if (field.kind.tag == .undetermined) return false;
        if (!try checkedTypeIsConcreteCompileTimeRootInner(walk, checked_types, field.ty, active)) return false;
    }
    return true;
}

test "compile-time roots reject undetermined record field kinds" {
    const allocator = std.testing.allocator;
    var store = CheckedTypeStore{};
    defer store.deinit(allocator);

    const leaf: CheckedTypeId = @enumFromInt(@as(u32, @intCast(store.payloads.items.len)));
    try store.payloads.append(allocator, try store.commitPayload(allocator, .empty_record));

    const root: CheckedTypeId = @enumFromInt(@as(u32, @intCast(store.payloads.items.len)));
    const fields = try allocator.alloc(CheckedRecordField, 1);
    fields[0] = .{
        .name = testIndexId(canonical.RecordFieldLabelId, 7),
        .ty = leaf,
        .kind = .undetermined(leaf),
    };
    try store.payloads.append(allocator, try store.commitPayload(allocator, .{ .record_unbound = fields }));

    try std.testing.expect(!try checkedTypeIsConcreteCompileTimeRoot(allocator, &store, root));
}

fn checkedTagsAreConcreteCompileTimeRoots(
    comptime walk: ConcreteRootWalk,
    checked_types: *const CheckedTypeStore,
    tags: []const CheckedTag,
    active: *collections.DenseMap(CheckedTypeId, void),
) Allocator.Error!bool {
    for (tags) |tag| {
        if (!try checkedTypeSpanIsConcreteCompileTimeRoot(walk, checked_types, tag.argsSlice(checked_types), active)) return false;
    }
    return true;
}

fn checkedTypeContainsError(
    allocator: Allocator,
    checked_types: *const CheckedTypeStore,
    root: CheckedTypeId,
) Allocator.Error!bool {
    var scan = CheckedTypeErrorScan{ .checked_types = checked_types };
    var traversal = CheckedTypeErrorTraversal.init(allocator, &scan);
    defer traversal.deinit();
    return traversal.visit(root);
}

const CheckedTypeErrorTraversal = checked_traverse.BoolPredicateTraversal(CheckedTypeId, CheckedTypeErrorScan);

const CheckedTypeErrorScan = struct {
    checked_types: *const CheckedTypeStore,

    pub fn visit(
        self: *CheckedTypeErrorScan,
        traversal: anytype,
        root: CheckedTypeId,
    ) Allocator.Error!bool {
        const index = @intFromEnum(root);
        if (index >= self.checked_types.payloads.items.len) {
            checkedArtifactInvariant("checked error-type scan referenced a missing type payload", .{});
        }
        return switch (self.checked_types.payload(root)) {
            .pending => checkedArtifactInvariant("checked error-type scan reached pending payload", .{}),
            .err => true,
            .empty_record, .empty_tag_union => false,
            .flex => |variable| checkedConstraintsContainError(traversal, variable.constraints),
            .rigid => |variable| checkedConstraintsContainError(traversal, variable.constraints),
            .alias => |alias| (try traversal.visit(alias.backing)) or
                try checkedTypeSliceContainsError(traversal, alias.args),
            .record => |record| (try checkedFieldsContainError(traversal, record.fields)) or
                try traversal.visit(record.ext),
            .record_unbound => |fields| checkedFieldsContainError(traversal, fields),
            .tuple => |items| checkedTypeSliceContainsError(traversal, items),
            .nominal => |nominal| blk: {
                if (try checkedTypeSliceContainsError(traversal, nominal.args)) break :blk true;
                const backing = self.checked_types.nominalBackingTemplateForPayload(nominal) orelse break :blk false;
                break :blk try traversal.visit(backing);
            },
            .function => |function| (try checkedTypeSliceContainsError(traversal, function.args)) or
                try traversal.visit(function.ret),
            .tag_union => |tag_union| (try checkedTagsContainError(traversal, tag_union.tags)) or
                try traversal.visit(tag_union.ext),
        };
    }
};

fn checkedConstraintsContainError(
    traversal: *CheckedTypeErrorTraversal,
    constraints: []const CheckedStaticDispatchConstraint,
) Allocator.Error!bool {
    for (constraints) |constraint| {
        if (try traversal.visit(constraint.fn_ty)) return true;
    }
    return false;
}

fn checkedTypeSliceContainsError(
    traversal: *CheckedTypeErrorTraversal,
    roots: []const CheckedTypeId,
) Allocator.Error!bool {
    for (roots) |root| {
        if (try traversal.visit(root)) return true;
    }
    return false;
}

fn checkedFieldsContainError(
    traversal: *CheckedTypeErrorTraversal,
    fields: []const CheckedRecordField,
) Allocator.Error!bool {
    for (fields) |field| {
        if (field.kind.undeterminedVariable()) |variable| {
            if (try traversal.visit(variable)) return true;
        }
        if (try traversal.visit(field.ty)) return true;
    }
    return false;
}

fn checkedTagsContainError(
    traversal: *CheckedTypeErrorTraversal,
    tags: []const CheckedTag,
) Allocator.Error!bool {
    for (tags) |tag| {
        if (try checkedTypeSliceContainsError(traversal, tag.argsSlice(traversal.context.checked_types))) return true;
    }
    return false;
}

fn compileTimeRootRequestIsEligible(root: CompileTimeRoot) bool {
    return switch (root.request_eligibility) {
        .pending => checkedArtifactInvariant("compile-time root request eligibility was pending", .{}),
        .eligible => true,
        .ineligible => false,
    };
}

fn compileTimeRootHasRootRequest(
    requests: []const RootRequest,
    root: CompileTimeRoot,
) bool {
    for (requests) |request| {
        if (request.abi != .compile_time) continue;
        if (request.compile_time_root == root.id) return true;
    }
    return false;
}

/// An exact checked procedure lookup already carries the callable identity
/// that compile-time evaluation would rediscover. Keep its callable binding
/// pending for runtime demand instead of scheduling an evaluator wrapper.
fn compileTimeCallableRootIsProcedureReference(
    checked_bodies: *const CheckedBodyStore,
    resolved_value_refs: *const ResolvedValueRefTable,
    root: CompileTimeRoot,
) bool {
    if (root.kind != .callable_binding) return false;
    const root_expr = checked_bodies.expr(root.expr).data;
    if (root_expr != .lookup_local and root_expr != .lookup_external and root_expr != .lookup_required) return false;
    const ref_id = resolved_value_refs.lookupIdByCheckedExpr(root.expr) orelse
        checkedArtifactInvariant("checked callable lookup root had no resolved value reference", .{});
    const raw = @intFromEnum(ref_id);
    if (raw >= resolved_value_refs.records.len) {
        checkedArtifactInvariant("checked callable lookup root resolved reference was outside the checked table", .{});
    }
    return switch (resolved_value_refs.records[raw].ref) {
        .top_level_proc,
        .imported_proc,
        .hosted_proc,
        .platform_required_proc,
        .promoted_top_level_proc,
        => true,
        .local_param,
        .local_value,
        .local_mutable_version,
        .pattern_binder,
        .local_proc,
        .selected_hoisted_const,
        .top_level_const,
        .imported_const,
        .platform_required_declaration,
        .platform_required_checked_error,
        .platform_required_const,
        => false,
    };
}

fn compileTimeRootKindMatchesRequest(
    root_kind: CompileTimeRootKind,
    request_kind: RootRequestKind,
) bool {
    return switch (root_kind) {
        .constant, .hoisted_constant => request_kind == .compile_time_constant,
        .callable_binding => request_kind == .compile_time_callable,
        .expect => request_kind == .test_expect,
        .numeral_conversion, .quote_conversion, .field_default => request_kind == .compile_time_constant,
    };
}

fn verifyRootRequestSubsets(root_requests: RootRequestTable) void {
    if (builtin.mode != .Debug) return;

    var runtime_index: usize = 0;
    var compile_time_count: usize = 0;

    for (root_requests.requests) |request| {
        if (request.abi == .compile_time) {
            compile_time_count += 1;
        } else {
            if (runtime_index >= root_requests.runtime_requests.len) {
                std.debug.panic("checked artifact invariant violated: runtime root request subset is missing an entry", .{});
            }
            if (!std.meta.eql(root_requests.runtime_requests[runtime_index], request)) {
                std.debug.panic("checked artifact invariant violated: runtime root request subset is out of order", .{});
            }
            runtime_index += 1;
        }
    }

    if (runtime_index != root_requests.runtime_requests.len) {
        std.debug.panic("checked artifact invariant violated: runtime root request subset has extra entries", .{});
    }
    if (compile_time_count != root_requests.compile_time_requests.len) {
        std.debug.panic("checked artifact invariant violated: compile-time root request subset has extra entries", .{});
    }
    for (root_requests.compile_time_requests) |request| {
        if (request.abi != .compile_time) {
            std.debug.panic("checked artifact invariant violated: compile-time root request subset contains a runtime request", .{});
        }
        if (!rootRequestSliceContains(root_requests.requests, request)) {
            std.debug.panic("checked artifact invariant violated: compile-time root request subset contains an unknown request", .{});
        }
    }
}

fn rootRequestSliceContains(requests: []const RootRequest, needle: RootRequest) bool {
    for (requests) |request| {
        if (std.meta.eql(request, needle)) return true;
    }
    return false;
}

fn rootSourceMatches(a: RootSource, b: RootSource) bool {
    if (std.meta.activeTag(a) != std.meta.activeTag(b)) return false;
    return switch (a) {
        .def => |def| def == b.def,
        .expr => |expr| expr == b.expr,
        .statement => |statement| statement == b.statement,
        .required_binding => |binding| binding == b.required_binding,
        .hoisted => |hoisted| hoisted.index == b.hoisted.index and hoisted.expr == b.hoisted.expr,
    };
}

fn compileTimeRootDependsOnUnboundPlatformRequirement(
    checked_bodies: *const CheckedBodyStore,
    resolved_value_refs: *const ResolvedValueRefTable,
    root: CompileTimeRoot,
    relation_blocked_exprs: []?bool,
) bool {
    return switch (root.kind) {
        .constant,
        .hoisted_constant,
        .callable_binding,
        .numeral_conversion,
        .quote_conversion,
        .field_default,
        => exprDependsOnUnboundPlatformRequirement(
            checked_bodies,
            resolved_value_refs,
            root.expr,
            relation_blocked_exprs,
        ),
        .expect => false,
    };
}

fn exprDependsOnUnboundPlatformRequirement(
    checked_bodies: *const CheckedBodyStore,
    resolved_value_refs: *const ResolvedValueRefTable,
    expr_id: CheckedExprId,
    relation_blocked_exprs: []?bool,
) bool {
    const index = @intFromEnum(expr_id);
    if (relation_blocked_exprs[index]) |cached| return cached;

    const data = checked_bodies.expr(@enumFromInt(index)).data;
    const result = switch (data) {
        .lookup_local => |lookup| resolvedRefIsUnboundPlatformRequirement(resolved_value_refs, lookup.resolved),
        .lookup_external,
        .lookup_required,
        => |ref_id| resolvedRefIsUnboundPlatformRequirement(resolved_value_refs, ref_id),
        .str,
        .list,
        .tuple,
        => |items| exprSpanDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, items, relation_blocked_exprs),
        .match_ => |match| blk: {
            if (exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, match.cond, relation_blocked_exprs)) break :blk true;
            for (match.branches) |branch| {
                if (branch.guard) |guard| {
                    if (exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, guard, relation_blocked_exprs)) break :blk true;
                }
                if (exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, branch.value, relation_blocked_exprs)) break :blk true;
            }
            break :blk false;
        },
        .if_ => |if_| blk: {
            for (if_.branches) |branch| {
                if (exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, branch.cond, relation_blocked_exprs)) break :blk true;
                if (exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, branch.body, relation_blocked_exprs)) break :blk true;
            }
            break :blk exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, if_.final_else, relation_blocked_exprs);
        },
        .call => |call| blk: {
            if (exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, call.func, relation_blocked_exprs)) break :blk true;
            break :blk exprSpanDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, call.args, relation_blocked_exprs);
        },
        .record => |record| blk: {
            if (record.ext) |ext| {
                if (exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, ext, relation_blocked_exprs)) break :blk true;
            }
            for (record.fields) |field| {
                if (exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, field.value, relation_blocked_exprs)) break :blk true;
            }
            break :blk false;
        },
        .block => |block| blk: {
            for (block.statements) |statement| {
                if (statementDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, statement, relation_blocked_exprs)) break :blk true;
            }
            break :blk exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, block.final_expr, relation_blocked_exprs);
        },
        .tag => |tag| exprSpanDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, tag.args, relation_blocked_exprs),
        .nominal => |nominal| exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, nominal.backing_expr, relation_blocked_exprs),
        .closure => |closure| exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, closure.lambda, relation_blocked_exprs),
        .lambda => |lambda| exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, lambda.body, relation_blocked_exprs),
        .interpolation => |interpolation| blk: {
            if (exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, interpolation.first, relation_blocked_exprs)) break :blk true;
            for (interpolation.parts) |part| {
                if (exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, part.value, relation_blocked_exprs)) break :blk true;
                if (exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, part.following_segment, relation_blocked_exprs)) break :blk true;
            }
            break :blk false;
        },
        .binop => |binop| exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, binop.lhs, relation_blocked_exprs) or
            exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, binop.rhs, relation_blocked_exprs),
        .unary_minus,
        .unary_not,
        .dbg,
        .expect,
        => |child| exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, child, relation_blocked_exprs),
        .expect_err => |expect_err| exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, expect_err.expr, relation_blocked_exprs),
        .field_access => |access| exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, access.receiver, relation_blocked_exprs),
        .structural_eq => |eq| exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, eq.lhs, relation_blocked_exprs) or
            exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, eq.rhs, relation_blocked_exprs),
        .structural_hash => |h| exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, h.value, relation_blocked_exprs) or
            exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, h.hasher, relation_blocked_exprs),
        .tuple_access => |access| exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, access.tuple, relation_blocked_exprs),
        .break_ => false,
        .return_ => |ret| exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, ret.expr, relation_blocked_exprs),
        .for_ => |for_| exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, for_.expr, relation_blocked_exprs) or
            exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, for_.body, relation_blocked_exprs),
        .run_low_level => |run| exprSpanDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, run.args, relation_blocked_exprs),
        .pending,
        .numeral,
        .str_from_quote,
        .str_segment,
        .bytes_literal,
        .empty_list,
        .empty_record,
        .zero_argument_tag,
        .dispatch_call,
        .method_eq,
        .type_dispatch_call,
        .hosted_lambda,
        .runtime_error,
        .crash,
        .ellipsis,
        .anno_only,
        => false,
    };

    relation_blocked_exprs[index] = result;
    return result;
}

fn exprSpanDependsOnUnboundPlatformRequirement(
    checked_bodies: *const CheckedBodyStore,
    resolved_value_refs: *const ResolvedValueRefTable,
    exprs: []const CheckedExprId,
    relation_blocked_exprs: []?bool,
) bool {
    for (exprs) |expr_id| {
        if (exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, expr_id, relation_blocked_exprs)) return true;
    }
    return false;
}

fn statementDependsOnUnboundPlatformRequirement(
    checked_bodies: *const CheckedBodyStore,
    resolved_value_refs: *const ResolvedValueRefTable,
    statement_id: CheckedStatementId,
    relation_blocked_exprs: []?bool,
) bool {
    return switch (checked_bodies.statement(statement_id).data) {
        .decl => |statement| exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, statement.expr, relation_blocked_exprs),
        .var_ => |statement| exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, statement.expr, relation_blocked_exprs),
        .var_uninitialized => false,
        .reassign => |statement| exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, statement.expr, relation_blocked_exprs),
        .dbg,
        .expr,
        .expect,
        => |expr| exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, expr, relation_blocked_exprs),
        .for_ => |for_| exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, for_.expr, relation_blocked_exprs) or
            exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, for_.body, relation_blocked_exprs),
        .while_ => |while_| exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, while_.cond, relation_blocked_exprs) or
            exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, while_.body, relation_blocked_exprs),
        .infinite_loop => |loop| exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, loop.cond, relation_blocked_exprs) or
            exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, loop.body, relation_blocked_exprs),
        .breakable_loop => |loop| exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, loop.cond, relation_blocked_exprs) or
            exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, loop.body, relation_blocked_exprs),
        .return_ => |ret| exprDependsOnUnboundPlatformRequirement(checked_bodies, resolved_value_refs, ret.expr, relation_blocked_exprs),
        .pending,
        .crash,
        .break_,
        .import_,
        .alias_decl,
        .where_alias_decl,
        .nominal_decl,
        .type_anno,
        .type_var_alias,
        .runtime_error,
        => false,
    };
}

fn resolvedRefIsUnboundPlatformRequirement(
    resolved_value_refs: *const ResolvedValueRefTable,
    maybe_ref: ?ResolvedValueRefId,
) bool {
    const ref_id = maybe_ref orelse return false;
    const index = @intFromEnum(ref_id);
    std.debug.assert(index < resolved_value_refs.records.len);
    return switch (resolved_value_refs.records[index].ref) {
        .platform_required_declaration => true,
        .local_param,
        .local_value,
        .local_mutable_version,
        .pattern_binder,
        .local_proc,
        .selected_hoisted_const,
        .top_level_const,
        .imported_const,
        .top_level_proc,
        .imported_proc,
        .hosted_proc,
        .platform_required_checked_error,
        .platform_required_const,
        .platform_required_proc,
        .promoted_top_level_proc,
        => false,
    };
}

fn appendPublishedEntrypointRoots(
    requests: *std.ArrayList(RootRequest),
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *const canonical.CanonicalNameStore,
    checked_types: *CheckedTypePublication,
    procedure_templates: *const CheckedProcedureTemplateTable,
    provided_exports: *const ProvidedExportTable,
    top_level_values: *const TopLevelValueTable,
    top_level_procedure_bindings: *const TopLevelProcedureBindingTable,
    relation_substitutions: *const PlatformRelationTypeSubstitutions,
    platform_app_relation: ?PlatformAppRelationKey,
    platform_required_declarations: *const PlatformRequiredDeclarationTable,
) Allocator.Error!void {
    const module_env = module.moduleEnvConst();

    const provided_runtime_roots_ready = module_env.module_kind != .platform or
        platform_required_declarations.declarations.len == 0 or
        platform_app_relation != null;
    if (provided_runtime_roots_ready) {
        for (provided_exports.exports) |provided| {
            switch (provided) {
                .procedure => |procedure| {
                    const checked_type = try relation_substitutions.specializeRoot(
                        allocator,
                        names,
                        &checked_types.store,
                        procedure.checked_type,
                    );
                    try appendRoot(requests, allocator, .{
                        .module_idx = module.moduleIndex(),
                        .kind = .provided_export,
                        .source = .{ .def = procedure.def },
                        .checked_type = checked_type,
                        .abi = .platform,
                        .exposure = .exported,
                        .procedure_template = procedureTemplateForTopLevelBinding(top_level_procedure_bindings, procedure.binding),
                        .procedure_binding = procedure.binding,
                    });
                },
                .data => {},
            }
        }
    }

    switch (module_env.module_kind) {
        .default_app => {
            const main_ident = module_env.idents.main_bang;
            const main_node_idx = module_env.getExposedValueNodeIndexById(main_ident) orelse {
                if (builtin.mode == .Debug) {
                    std.debug.panic(
                        "checked artifact invariant violated: default app main! has no published root definition",
                        .{},
                    );
                }
                unreachable;
            };
            const main_def: CIR.Def.Idx = @enumFromInt(@as(u32, @intCast(main_node_idx)));
            const checked_type = try checkedTypeIdForRootSource(allocator, module, checked_types, .{ .def = main_def });
            if (try checkedTypeContainsError(allocator, &checked_types.store, checked_type)) return;
            try appendRoot(requests, allocator, .{
                .module_idx = module.moduleIndex(),
                .kind = .runtime_entrypoint,
                .source = .{ .def = main_def },
                .checked_type = checked_type,
                .abi = .roc,
                .exposure = .exported,
                .procedure_template = requiredProcedureTemplateForRootSource(procedure_templates, .{ .def = main_def }),
            });
        },
        .app => try appendExposedAppProcedureRoots(
            requests,
            allocator,
            module,
            checked_types,
            top_level_values,
            top_level_procedure_bindings,
        ),
        .type_module,
        .package,
        .platform,
        .hosted,
        .module,
        .malformed,
        => {},
    }
}

fn appendExposedAppProcedureRoots(
    requests: *std.ArrayList(RootRequest),
    allocator: Allocator,
    module: TypedCIR.Module,
    checked_types: *const CheckedTypePublication,
    top_level_values: *const TopLevelValueTable,
    top_level_procedure_bindings: *const TopLevelProcedureBindingTable,
) Allocator.Error!void {
    const module_env = module.moduleEnvConst();
    var exposed_iter = module_env.common.exposed_items.iterator();
    while (exposed_iter.next()) |entry| {
        const raw_node_idx = entry.target.valueDefNode() orelse continue;
        if (raw_node_idx >= module.nodeCount()) {
            checkedArtifactInvariant(
                "checked artifact invariant violated: app exposed item {s} points at out-of-range node {d}",
                .{ module_env.getIdent(@bitCast(entry.ident_idx)), raw_node_idx },
            );
        }
        const node_idx: CIR.Node.Idx = @enumFromInt(raw_node_idx);
        if (module.nodeTag(node_idx) != .def) continue;

        const def_idx: CIR.Def.Idx = @enumFromInt(raw_node_idx);
        const top_level = top_level_values.lookupByDef(def_idx) orelse {
            checkedArtifactInvariant("app exposed value definition had no top-level value entry", .{});
        };
        const procedure_binding = switch (top_level.value) {
            .procedure_binding => |binding| binding,
            .const_ref => continue,
        };
        try appendRoot(requests, allocator, .{
            .module_idx = module.moduleIndex(),
            .kind = .runtime_entrypoint,
            .source = .{ .def = def_idx },
            .checked_type = try checkedTypeIdForRootSource(allocator, module, checked_types, .{ .def = def_idx }),
            .abi = .roc,
            .exposure = .exported,
            .procedure_template = procedureTemplateForTopLevelBinding(top_level_procedure_bindings, procedure_binding),
            .procedure_binding = procedure_binding,
        });
    }
}

fn procedureTemplateForRootSource(
    procedure_templates: *const CheckedProcedureTemplateTable,
    source: RootSource,
) ?canonical.ProcedureTemplateRef {
    return switch (source) {
        .def => |def_idx| procedure_templates.lookupByDef(def_idx),
        .expr,
        .statement,
        .required_binding,
        .hoisted,
        => null,
    };
}

fn procedureTemplateForTopLevelBinding(
    top_level_procedure_bindings: *const TopLevelProcedureBindingTable,
    binding_ref: TopLevelProcedureBindingRef,
) ?canonical.ProcedureTemplateRef {
    const binding = top_level_procedure_bindings.get(binding_ref);
    return switch (binding.body) {
        .direct_template => |direct| switch (direct.template) {
            .checked => |template| template,
            .synthetic => |synthetic| synthetic.template,
            .lifted => checkedArtifactInvariant("checked root binding referenced lifted procedure before post-check lowering", .{}),
        },
        .callable_eval_template => null,
    };
}

fn requiredProcedureTemplateForRootSource(
    procedure_templates: *const CheckedProcedureTemplateTable,
    source: RootSource,
) canonical.ProcedureTemplateRef {
    return procedureTemplateForRootSource(procedure_templates, source) orelse {
        if (builtin.mode == .Debug) {
            std.debug.panic("checked artifact invariant violated: root procedure source has no checked procedure template", .{});
        }
        unreachable;
    };
}

const RootBackingProcedure = struct {
    checked_type: CheckedTypeId,
    template: canonical.ProcedureTemplateRef,
    compile_time_root: ?ComptimeRootId,
};

fn explicitRootBackingProcedure(
    procedure_templates: *const CheckedProcedureTemplateTable,
    compile_time_roots: *const CompileTimeRootTable,
    entry_wrappers: *const EntryWrapperTable,
    source: RootSource,
    request_kind: RootRequestKind,
    source_checked_type: CheckedTypeId,
) RootBackingProcedure {
    if (procedureTemplateForRootSource(procedure_templates, source)) |template| {
        return .{ .checked_type = source_checked_type, .template = template, .compile_time_root = null };
    }

    const root_id = compileTimeRootIdForSourceAndRequestKind(compile_time_roots, source, request_kind) orelse {
        checkedArtifactInvariant("explicit root has no checked procedure template or entry wrapper", .{});
    };
    const wrapper = entryWrapperForRoot(entry_wrappers, root_id);
    return .{ .checked_type = wrapper.checked_fn_root, .template = wrapper.template, .compile_time_root = root_id };
}

fn checkedTypeIdForRootSource(
    allocator: Allocator,
    module: TypedCIR.Module,
    checked_types: *const CheckedTypePublication,
    source: RootSource,
) Allocator.Error!CheckedTypeId {
    const var_ = switch (source) {
        .def => |def_idx| module.defType(def_idx),
        .expr => |expr_idx| module.exprType(expr_idx),
        .statement => |statement_idx| ModuleEnv.varFrom(statement_idx),
        .hoisted => checkedArtifactInvariant("internal hoisted root source reached external root source type lookup", .{}),
        .required_binding => |binding_idx| blk: {
            const module_env = module.moduleEnvConst();
            if (binding_idx >= module_env.requires_types.items.items.len) {
                if (builtin.mode == .Debug) {
                    std.debug.panic(
                        "checked artifact invariant violated: explicit required-binding root {d} is out of range",
                        .{binding_idx},
                    );
                }
                unreachable;
            }
            break :blk ModuleEnv.varFrom(module_env.requires_types.items.items[binding_idx].type_anno);
        },
    };
    return checkedTypeIdForVar(allocator, module, checked_types, var_);
}

fn platformRequiredBindingCheckedType(binding: PlatformRequiredBinding) CheckedTypeId {
    return switch (binding.value_use) {
        .const_value => |const_use| const_use.const_use.requested_source_ty_payload orelse {
            checkedArtifactInvariant("platform-required const binding missing relation-owned requested payload", .{});
        },
        .procedure_value => |procedure_use| procedure_use.procedure.source_fn_ty_payload orelse {
            checkedArtifactInvariant("platform-required procedure binding missing relation-owned requested payload", .{});
        },
    };
}

fn checkedTypeIdForVar(
    _: Allocator,
    module: TypedCIR.Module,
    checked_types: *const CheckedTypePublication,
    var_: Var,
) Allocator.Error!CheckedTypeId {
    return checked_types.rootForSourceVar(module, var_) orelse {
        if (builtin.mode == .Debug) {
            std.debug.panic("checked artifact invariant violated: root request type was not published", .{});
        }
        unreachable;
    };
}

const RootRequestWithoutOrder = struct {
    module_idx: u32,
    kind: RootRequestKind,
    source: RootSource,
    compile_time_root: ?ComptimeRootId = null,
    checked_type: CheckedTypeId,
    abi: RootAbi,
    exposure: RootExposure,
    procedure_template: ?canonical.ProcedureTemplateRef = null,
    procedure_binding: ?TopLevelProcedureBindingRef = null,
    procedure_use: ?ProcedureUseTemplate = null,
    root_evidence: ?CheckedEvidenceSpan = null,
};

fn appendRoot(
    requests: *std.ArrayList(RootRequest),
    allocator: Allocator,
    request: RootRequestWithoutOrder,
) Allocator.Error!void {
    try requests.append(allocator, .{
        .order = @intCast(requests.items.len),
        .module_idx = request.module_idx,
        .kind = request.kind,
        .source = request.source,
        .compile_time_root = request.compile_time_root,
        .checked_type = request.checked_type,
        .abi = request.abi,
        .exposure = request.exposure,
        .procedure_template = request.procedure_template,
        .procedure_binding = request.procedure_binding,
        .procedure_use = request.procedure_use,
        .root_evidence = request.root_evidence,
    });
}

fn templateForEntryWrapperRoot(
    entry_wrappers: *const EntryWrapperTable,
    root: ComptimeRootId,
) canonical.ProcedureTemplateRef {
    return entryWrapperForRoot(entry_wrappers, root).template;
}

fn entryWrapperForRoot(
    entry_wrappers: *const EntryWrapperTable,
    root: ComptimeRootId,
) EntryWrapper {
    const wrapper = entry_wrappers.lookupByRoot(root) orelse {
        if (builtin.mode == .Debug) {
            std.debug.panic("checked artifact invariant violated: compile-time/test root has no entry wrapper", .{});
        }
        unreachable;
    };
    return wrapper;
}

fn topLevelExprIsAlreadyProcedure(expr: CIR.Expr) bool {
    return expr == .e_lambda or expr == .e_closure or expr == .e_anno_only or expr == .e_hosted_lambda;
}

fn sourceTypeIsFunction(module: TypedCIR.Module, var_: Var) bool {
    return module.typeStoreConst().varResolvesToFunction(var_);
}

fn isHostedProcedureExpr(expr: CIR.Expr) bool {
    return expr == .e_hosted_lambda;
}

fn intrinsicForProcedureDef(module: TypedCIR.Module, def_idx: CIR.Def.Idx) ?IntrinsicId {
    return static_dispatch.intrinsicForProcedureDef(module, def_idx);
}

fn iteratorProcedureForDef(module: TypedCIR.Module, def_idx: CIR.Def.Idx) ?IteratorProcedureId {
    return static_dispatch.iteratorProcedureForDef(module, def_idx);
}

/// Record the reachability semantics introduced by the canonical
/// BuiltinLowLevel transform while the explicit CIR low-level node is still
/// available. Post-check stages consume this field directly from procedure
/// uses.
fn runtimeResultProvenanceForProcedureDef(
    module: TypedCIR.Module,
    def_idx: CIR.Def.Idx,
) ?RuntimeResultProvenance {
    const op = module.moduleEnvConst().providedLowLevelForDef(def_idx) orelse return null;
    return if (op == .list_get_unsafe) .list_element_read else null;
}

pub const CheckedBodyId = checked_ids.CheckedBodyId;
pub const CheckedExprId = checked_ids.CheckedExprId;
pub const CheckedPatternId = checked_ids.CheckedPatternId;
pub const CheckedStatementId = checked_ids.CheckedStatementId;
pub const CheckedExhaustivenessSiteId = checked_ids.CheckedExhaustivenessSiteId;
pub const CheckedTypeId = checked_ids.CheckedTypeId;
pub const ConstStore = const_store.ConstStore;
pub const ConstNodeId = const_store.ConstNodeId;
pub const ConstFnId = const_store.ConstFnId;
pub const ConstValue = const_store.ConstValue;
pub const ConstScalar = const_store.ConstScalar;
pub const ConstList = const_store.ConstList;
pub const ConstNamedType = const_store.NamedType;
pub const CheckedTypeSchemeId = checked_ids.CheckedTypeSchemeId;
pub const StaticDispatchPlanId = static_dispatch.StaticDispatchPlanId;
pub const IteratorForPlanId = static_dispatch.IteratorForPlanId;
/// Public `PatternBinderId` declaration.
pub const PatternBinderId = checked_ids.PatternBinderId;
/// Public `CaptureId` declaration.
pub const CaptureId = checked_ids.CaptureId;
/// Public `OptionalId` declaration: the one inline optional-id encoding used
/// by checked-artifact data (see `checked_ids.OptionalId`).
pub const OptionalId = checked_ids.OptionalId;
/// Public `CheckedVarNameId` declaration.
pub const CheckedVarNameId = checked_ids.CheckedVarNameId;
/// Inline optional `canonical.ModuleIdentityId`.
pub const OptionalModuleIdentityId = OptionalId(canonical.ModuleIdentityId);
/// Inline optional `CheckedTypeId` used by undetermined record-field kinds.
pub const OptionalCheckedTypeId = OptionalId(CheckedTypeId);
/// Inline optional `CheckedVarNameId`.
pub const OptionalVarNameId = OptionalId(CheckedVarNameId);

/// Public `CheckedTypeRoot` declaration.
