/// POD form of `CheckedRecordType`: `fields` is a range into `record_field_pool`.
pub const StoredRecord = struct {
    fields: CheckedTypeRange = .{},
    ext: CheckedTypeId,
};

/// POD form of `CheckedFunctionType`: `args` is a range into `type_id_pool`.
pub const StoredFunction = struct {
    kind: CheckedFunctionKind,
    args: CheckedTypeRange = .{},
    ret: CheckedTypeId,
};

/// POD form of `CheckedTagUnionType`: `tags` is a range into `tag_pool`.
pub const StoredTagUnion = struct {
    tags: CheckedTypeRange = .{},
    ext: CheckedTypeId,
};

/// Internal, relocation-invariant (POD) form of `CheckedTypePayload`: variant
/// slices are replaced by ranges into the store's flat pools. The public
/// `CheckedTypePayload` (with slices) is reconstructed on demand by `payload`.
pub const StoredCheckedTypePayload = union(enum) {
    pending,
    err,
    flex: StoredTypeVariable,
    rigid: StoredTypeVariable,
    alias: StoredAlias,
    record: StoredRecord,
    record_unbound: CheckedTypeRange,
    tuple: CheckedTypeRange,
    nominal: StoredNominal,
    function: StoredFunction,
    empty_record,
    tag_union: StoredTagUnion,
    empty_tag_union,
};

/// Materialize the public read-form `CheckedTypePayload` from its stored POD
/// form. `pool_owner` must expose `typeIdPool()`, `recordFieldPool()`,
/// `constraintPool()`, `tagPool()`, and `varName(OptionalVarNameId)` accessors (both
/// `CheckedTypeStore` and `CheckedTypeStoreView` do). Slice fields alias the
/// pools; no allocation.
///
/// ALIASING INVARIANT: the returned slices point INTO the store's pools. On a
/// frozen/deserialized store the pools are immutable (buffer-backed), so this is
/// unconditionally safe—the common case (all post-load consumers: lowering, glue).
/// During CONSTRUCTION the pools are growable `ArrayList`s, so a build-time caller
/// must not retain a returned slice across a subsequent pool-growing call
/// (`appendTypeIds`/`commitPayload`/…), which may reallocate and dangle it; snapshot
/// or `dupe` first (as `cloneCheckedTypeRootSubstituting` and `instantiateNominalBacking`
/// do). The append helpers `assert(!serialized)` to mark that growth boundary.
fn reconstructCheckedTypePayload(pool_owner: anytype, stored: StoredCheckedTypePayload) CheckedTypePayload {
    return switch (stored) {
        .pending => .pending,
        .err => .err,
        .empty_record => .empty_record,
        .empty_tag_union => .empty_tag_union,
        .flex => |v| .{ .flex = reconstructCheckedTypeVariable(pool_owner, v) },
        .rigid => |v| .{ .rigid = reconstructCheckedTypeVariable(pool_owner, v) },
        .alias => |a| .{ .alias = .{
            .name = a.name,
            .origin_module = a.origin_module,
            .owner_module = a.owner_module,
            .source_decl = a.source_decl,
            .builtin_origin = a.builtin_origin,
            .backing = a.backing,
            .args = pool_owner.typeIdPool()[a.args.start .. a.args.start + a.args.len],
        } },
        .record => |r| .{ .record = .{
            .fields = pool_owner.recordFieldPool()[r.fields.start .. r.fields.start + r.fields.len],
            .ext = r.ext,
        } },
        .record_unbound => |range| .{
            .record_unbound = pool_owner.recordFieldPool()[range.start .. range.start + range.len],
        },
        .tuple => |range| .{
            .tuple = pool_owner.typeIdPool()[range.start .. range.start + range.len],
        },
        .nominal => |n| .{ .nominal = .{
            .name = n.name,
            .origin_module = n.origin_module,
            .owner_module = n.owner_module,
            .source_decl = n.source_decl,
            .builtin = n.builtin,
            .is_opaque = n.is_opaque,
            .representation = n.representation,
            .args = pool_owner.typeIdPool()[n.args.start .. n.args.start + n.args.len],
            .padding_field_types = pool_owner.typeIdPool()[n.padding_field_types.start .. n.padding_field_types.start + n.padding_field_types.len],
            .declared_fields = pool_owner.declaredFieldPool()[n.declared_fields.start .. n.declared_fields.start + n.declared_fields.len],
        } },
        .function => |f| .{ .function = .{
            .kind = f.kind,
            .args = pool_owner.typeIdPool()[f.args.start .. f.args.start + f.args.len],
            .ret = f.ret,
        } },
        .tag_union => |tu| .{ .tag_union = .{
            .tags = pool_owner.tagPool()[tu.tags.start .. tu.tags.start + tu.tags.len],
            .ext = tu.ext,
        } },
    };
}

fn reconstructCheckedTypeVariable(pool_owner: anytype, v: StoredTypeVariable) CheckedTypeVariable {
    return .{
        .name = pool_owner.varName(v.name),
        .constraints = pool_owner.constraintPool()[v.constraints.start .. v.constraints.start + v.constraints.len],
        .numeric_default_phase = v.numeric_default_phase,
        .row_default = v.row_default,
    };
}

/// Public `CheckedTypeStoreView` declaration.
///
/// Immutable read interface over a `CheckedTypeStore`'s flat data, carrying the
/// side pools so reconstructed payloads (`payload`) and range accessors
/// (`CheckedTag.argsSlice`, `CheckedTypeScheme.generalizedVars`,
/// `CheckedNominalDeclaration.formalArgs`) resolve without the owning store.
/// Default empty interner for a default-initialized (`.{}`) view, so the
/// non-optional `var_names` pointer always points at a valid (empty) interner.
var empty_view_var_names: canonical.NameInterner = .{};

/// Borrowed, read-only view over a `CheckedTypeStore`'s relocated slices plus its
/// `var_names` interner, so type accessors can resolve ids without holding the owning
/// store (used by both a live store and a deserialized, buffer-backed one).
pub const CheckedTypeStoreView = struct {
    roots: []const CheckedTypeRoot = &.{},
    schemes: []const CheckedTypeScheme = &.{},
    stored_payloads: []const StoredCheckedTypePayload = &.{},
    nominal_declarations: []const CheckedNominalDeclaration = &.{},
    type_id_pool: []const CheckedTypeId = &.{},
    record_field_pool: []const CheckedRecordField = &.{},
    declared_field_pool: []const CheckedDeclaredField = &.{},
    nominal_record_field_pool: []const CheckedNominalRecordField = &.{},
    constraint_pool: []const CheckedStaticDispatchConstraint = &.{},
    tag_pool: []const CheckedTag = &.{},
    var_names: *const canonical.NameInterner = &empty_view_var_names,

    /// The shared flat pool of `CheckedTypeId`s backing range fields.
    pub fn typeIdPool(self: CheckedTypeStoreView) []const CheckedTypeId {
        return self.type_id_pool;
    }

    /// The shared flat pool of record fields backing record range fields.
    pub fn recordFieldPool(self: CheckedTypeStoreView) []const CheckedRecordField {
        return self.record_field_pool;
    }

    /// The shared flat pool of declared nominal record fields.
    pub fn declaredFieldPool(self: CheckedTypeStoreView) []const CheckedDeclaredField {
        return self.declared_field_pool;
    }

    /// The shared flat pool of declared-order nominal record fields.
    pub fn nominalRecordFieldPool(self: CheckedTypeStoreView) []const CheckedNominalRecordField {
        return self.nominal_record_field_pool;
    }

    /// The shared flat pool of static-dispatch constraints.
    pub fn constraintPool(self: CheckedTypeStoreView) []const CheckedStaticDispatchConstraint {
        return self.constraint_pool;
    }

    /// The shared flat pool of (range-form) tags.
    pub fn tagPool(self: CheckedTypeStoreView) []const CheckedTag {
        return self.tag_pool;
    }

    /// Text of a stored variable name id, or null when absent.
    pub fn varName(self: CheckedTypeStoreView, id: OptionalVarNameId) ?[]const u8 {
        const name_id = id.get() orelse return null;
        return self.var_names.getText(@intFromEnum(name_id));
    }

    /// Number of stored payloads (checked type roots).
    pub fn payloadCount(self: CheckedTypeStoreView) usize {
        return self.stored_payloads.len;
    }

    /// Materialize the public read-form payload for `id`. Slice fields alias the
    /// view's pools; no allocation.
    pub fn payload(self: CheckedTypeStoreView, id: CheckedTypeId) CheckedTypePayload {
        const index: usize = @intFromEnum(id);
        if (index >= self.stored_payloads.len) {
            checkedArtifactInvariant("checked type payload id is out of range", .{});
        }
        return reconstructCheckedTypePayload(self, self.stored_payloads[index]);
    }

    /// Looks up a published checked type root by canonical source type key.
    pub fn rootForKey(self: CheckedTypeStoreView, key: canonical.CanonicalTypeKey) ?CheckedTypeId {
        for (self.roots) |root| {
            if (std.meta.eql(root.key.bytes, key.bytes)) return root.id;
        }
        return null;
    }

    /// Looks up a published checked source scheme by canonical scheme key.
    pub fn schemeForKey(self: CheckedTypeStoreView, key: canonical.CanonicalTypeSchemeKey) ?CheckedTypeScheme {
        for (self.schemes) |scheme| {
            if (std.meta.eql(scheme.key.bytes, key.bytes)) return scheme;
        }
        return null;
    }

    /// Returns the canonical key for a checked type root in this view.
    pub fn rootKey(self: CheckedTypeStoreView, root: CheckedTypeId) canonical.CanonicalTypeKey {
        const index: usize = @intFromEnum(root);
        if (index >= self.roots.len) {
            checkedArtifactInvariant("checked type view root key lookup referenced a missing root", .{});
        }
        return self.roots[index].key;
    }

    /// Returns whether a const producer root is already concrete for constant
    /// instantiation keys: no unresolved variables remain in any reachable
    /// compile-time value slot, including function argument and return types.
    pub fn isConcreteConstProducerScheme(
        self: CheckedTypeStoreView,
        allocator: Allocator,
        root: CheckedTypeId,
    ) Allocator.Error!bool {
        var active = collections.DenseMap(CheckedTypeId, void).init(allocator);
        defer active.deinit();
        return try checkedTypeViewIsConcreteConstProducerSchemeInner(self, root, &active);
    }

    pub fn nominalDeclaration(
        self: CheckedTypeStoreView,
        nominal: canonical.NominalTypeKey,
    ) ?CheckedNominalDeclaration {
        for (self.nominal_declarations) |declaration| {
            if (canonicalNominalTypeKeyEql(declaration.nominal, nominal)) return declaration;
        }
        return null;
    }

    pub fn nominalDeclarationById(
        self: CheckedTypeStoreView,
        id: CheckedNominalDeclarationId,
    ) CheckedNominalDeclaration {
        const index: usize = @intFromEnum(id);
        if (index >= self.nominal_declarations.len) {
            checkedArtifactInvariant("checked nominal declaration id is out of range", .{});
        }
        const declaration = self.nominal_declarations[index];
        if (declaration.id != id) {
            checkedArtifactInvariant("checked nominal declaration id disagrees with declaration slot", .{});
        }
        return declaration;
    }

    pub fn nominalDeclarationForPayload(
        self: CheckedTypeStoreView,
        nominal: CheckedNominalType,
    ) ?CheckedNominalDeclaration {
        return self.nominalDeclaration(checkedNominalTypeKey(nominal));
    }

    pub fn nominalBackingTemplateForPayload(
        self: CheckedTypeStoreView,
        nominal: CheckedNominalType,
    ) ?CheckedTypeId {
        if (nominal.representation == .opaque_without_backing) return null;
        if (nominal.builtin) |builtin_nominal| {
            if (!builtinNominalHasDeclarationBacking(builtin_nominal)) return null;
        }
        const declaration = self.nominalDeclarationForPayload(nominal) orelse {
            checkedArtifactInvariant("checked nominal payload referenced a missing nominal declaration", .{});
        };
        return declaration.backing;
    }
};

/// A checked type graph together with the canonical names that own its labels.
pub const CheckedTypeSourceView = struct {
    names: *const canonical.CanonicalNameStore,
    view: CheckedTypeStoreView,
};

/// Compare record field labels that may come from different canonical name stores.
pub fn recordFieldLabelsMatch(
    source_names: *const canonical.CanonicalNameStore,
    source_field: canonical.RecordFieldLabelId,
    target_names: *const canonical.CanonicalNameStore,
    target_field: canonical.RecordFieldLabelId,
) bool {
    if (source_names == target_names and source_field == target_field) return true;
    return Ident.textEql(
        source_names.recordFieldLabelText(source_field),
        target_names.recordFieldLabelText(target_field),
    );
}

/// Compare tag labels that may come from different canonical name stores.
pub fn tagLabelsMatch(
    source_names: *const canonical.CanonicalNameStore,
    source_tag: canonical.TagLabelId,
    target_names: *const canonical.CanonicalNameStore,
    target_tag: canonical.TagLabelId,
) bool {
    if (source_names == target_names and source_tag == target_tag) return true;
    return Ident.textEql(
        source_names.tagLabelText(source_tag),
        target_names.tagLabelText(target_tag),
    );
}

/// Find a record field payload child by label while walking aliases and row tails.
pub fn checkedTypeRecordFieldChild(
    source: CheckedTypeSourceView,
    root: CheckedTypeId,
    target_names: *const canonical.CanonicalNameStore,
    target_field: canonical.RecordFieldLabelId,
) ?CheckedTypeId {
    var current = root;
    while (true) {
        const payload = checkedTypeViewResolvedPayload(source.view, current) orelse return null;
        current = payload.root;
        switch (payload.payload) {
            .record => |record| {
                for (record.fields) |field| {
                    if (recordFieldLabelsMatch(source.names, field.name, target_names, target_field)) return field.ty;
                }
                current = record.ext;
            },
            .record_unbound => |fields| {
                for (fields) |field| {
                    if (recordFieldLabelsMatch(source.names, field.name, target_names, target_field)) return field.ty;
                }
                return null;
            },
            .pending,
            .err,
            .flex,
            .rigid,
            .alias,
            .tuple,
            .nominal,
            .function,
            .empty_record,
            .tag_union,
            .empty_tag_union,
            => return null,
        }
    }
}

/// Find a tag payload child by tag label and payload index while walking aliases and row tails.
pub fn checkedTypeTagPayloadChild(
    source: CheckedTypeSourceView,
    root: CheckedTypeId,
    target_names: *const canonical.CanonicalNameStore,
    target_tag: canonical.TagLabelId,
    payload_index: u32,
) ?CheckedTypeId {
    const raw_payload_index: usize = @intCast(payload_index);
    var current = root;
    while (true) {
        const payload = checkedTypeViewResolvedPayload(source.view, current) orelse return null;
        current = payload.root;
        switch (payload.payload) {
            .tag_union => |tag_union| {
                for (tag_union.tags) |tag| {
                    if (!tagLabelsMatch(source.names, tag.name, target_names, target_tag)) continue;
                    const tag_args = tag.argsSlice(source.view);
                    if (raw_payload_index >= tag_args.len) return null;
                    return tag_args[raw_payload_index];
                }
                current = tag_union.ext;
            },
            .pending,
            .err,
            .flex,
            .rigid,
            .alias,
            .record,
            .record_unbound,
            .tuple,
            .nominal,
            .function,
            .empty_record,
            .empty_tag_union,
            => return null,
        }
    }
}

const ResolvedCheckedTypePayload = struct {
    root: CheckedTypeId,
    payload: CheckedTypePayload,
};

fn checkedTypeViewResolvedPayload(
    view: CheckedTypeStoreView,
    root: CheckedTypeId,
) ?ResolvedCheckedTypePayload {
    var current = root;
    while (true) {
        const index: usize = @intFromEnum(current);
        if (index >= view.payloadCount()) {
            checkedArtifactInvariant("checked type source child lookup referenced a missing root", .{});
        }
        const payload = view.payload(@enumFromInt(index));
        switch (payload) {
            .alias => |alias| current = alias.backing,
            .nominal => |nominal| current = view.nominalBackingTemplateForPayload(nominal) orelse return null,
            .pending => checkedArtifactInvariant("checked type source child lookup reached a pending payload", .{}),
            .err,
            .flex,
            .rigid,
            .record,
            .record_unbound,
            .tuple,
            .function,
            .empty_record,
            .tag_union,
            .empty_tag_union,
            => return .{
                .root = current,
                .payload = payload,
            },
        }
    }
}

fn checkedTypeViewIsConcreteConstProducerSchemeInner(
    checked_types: CheckedTypeStoreView,
    root: CheckedTypeId,
    active: *collections.DenseMap(CheckedTypeId, void),
) Allocator.Error!bool {
    if (active.contains(root)) return true;
    try active.put(root, {});
    defer _ = active.remove(root);

    const index: usize = @intFromEnum(root);
    if (index >= checked_types.payloads.len) {
        checkedArtifactInvariant("const producer checked type view id is out of range", .{});
    }
    return switch (checked_types.payload(@enumFromInt(index))) {
        .pending => checkedArtifactInvariant("const producer checked type view was pending", .{}),
        .flex, .rigid => |variable| variable.row_default != null,
        .empty_record,
        .empty_tag_union,
        => true,
        .alias => |alias| (try checkedTypeViewIsConcreteConstProducerSchemeInner(checked_types, alias.backing, active)) and
            try checkedTypeViewSpanIsConcreteConstProducerScheme(checked_types, alias.args, active),
        .record => |record| (try checkedTypeViewRecordFieldsAreConcreteConstProducerScheme(checked_types, record.fields, active)) and
            try checkedTypeViewIsConcreteConstProducerSchemeInner(checked_types, record.ext, active),
        .record_unbound => |fields| checkedTypeViewRecordFieldsAreConcreteConstProducerScheme(checked_types, fields, active),
        .tuple => |items| checkedTypeViewSpanIsConcreteConstProducerScheme(checked_types, items, active),
        .nominal => |nominal| blk: {
            if (!try checkedTypeViewSpanIsConcreteConstProducerScheme(checked_types, nominal.args, active)) break :blk false;
            if (nominal.builtin != null) break :blk true;
            const backing = checked_types.nominalBackingTemplateForPayload(nominal) orelse break :blk true;
            break :blk try checkedTypeViewIsConcreteConstProducerSchemeInner(checked_types, backing, active);
        },
        // Concrete exactly when args and return carry no undefaulted identity
        // variables; the recursion decides that, so no separate flag is needed.
        .function => |function| (try checkedTypeViewSpanIsConcreteConstProducerScheme(checked_types, function.args, active)) and
            try checkedTypeViewIsConcreteConstProducerSchemeInner(checked_types, function.ret, active),
        .tag_union => |tag_union| (try checkedTypeViewTagsAreConcreteConstProducerScheme(checked_types, tag_union.tags, active)) and
            try checkedTypeViewIsConcreteConstProducerSchemeInner(checked_types, tag_union.ext, active),
    };
}

fn checkedTypeViewSpanIsConcreteConstProducerScheme(
    checked_types: CheckedTypeStoreView,
    items: []const CheckedTypeId,
    active: *collections.DenseMap(CheckedTypeId, void),
) Allocator.Error!bool {
    for (items) |item| {
        if (!try checkedTypeViewIsConcreteConstProducerSchemeInner(checked_types, item, active)) return false;
    }
    return true;
}

fn checkedTypeViewRecordFieldsAreConcreteConstProducerScheme(
    checked_types: CheckedTypeStoreView,
    fields: []const CheckedRecordField,
    active: *collections.DenseMap(CheckedTypeId, void),
) Allocator.Error!bool {
    for (fields) |field| {
        if (field.kind.undeterminedVariable()) |variable| {
            if (!try checkedTypeViewIsConcreteConstProducerSchemeInner(checked_types, variable, active)) return false;
        }
        if (!try checkedTypeViewIsConcreteConstProducerSchemeInner(checked_types, field.ty, active)) return false;
    }
    return true;
}

fn checkedTypeViewTagsAreConcreteConstProducerScheme(
    checked_types: CheckedTypeStoreView,
    tags: []const CheckedTag,
    active: *collections.DenseMap(CheckedTypeId, void),
) Allocator.Error!bool {
    for (tags) |tag| {
        if (!try checkedTypeViewSpanIsConcreteConstProducerScheme(checked_types, tag.argsSlice(checked_types), active)) return false;
    }
    return true;
}

/// Public `CheckedNominalDeclaration` declaration.
///
/// `fa_start`/`fa_len` are a range into `CheckedTypeStore.type_id_pool` (POD).
/// Use `formalArgs` to obtain the backing slice.
pub const CheckedNominalDeclaration = struct {
    id: CheckedNominalDeclarationId,
    nominal: canonical.NominalTypeKey,
    /// CIR statement index of the declaration in its (content-identified)
    /// declaring module. A decl LOCATOR for reading declared field order from
    /// the module's CIR—never part of identity. Stable across artifacts
    /// because equal content identities imply byte-identical module source.
    source_statement: u32,
    declaration_root: CheckedTypeId,
    backing: CheckedTypeId,
    fa_start: u32 = 0,
    fa_len: u32 = 0,

    /// Range into `CheckedTypeStore.type_id_pool` for the resolved types of the
    /// declaration's unnamed (`_` / `_name`) padding fields, in declared order.
    /// Consumed by Monotype to reserve layout padding; excluded from the backing
    /// row. Use `paddingFieldTypes` to obtain the backing slice.
    pf_start: u32 = 0,
    pf_len: u32 = 0,

    /// Range into `CheckedTypeStore.declared_field_pool` for the source-declared
    /// nominal record field order.
    df_start: u32 = 0,
    df_len: u32 = 0,

    /// Range into `CheckedTypeStore.nominal_record_field_pool` for the
    /// declaration's top-level record field sequence.
    rf_start: u32 = 0,
    rf_len: u32 = 0,

    /// The declaration's formal args within its store's `type_id_pool`.
    pub fn formalArgs(self: CheckedNominalDeclaration, pool_owner: anytype) []const CheckedTypeId {
        return pool_owner.typeIdPool()[self.fa_start .. self.fa_start + self.fa_len];
    }

    /// The declaration's padding field types within its store's `type_id_pool`.
    pub fn paddingFieldTypes(self: CheckedNominalDeclaration, pool_owner: anytype) []const CheckedTypeId {
        return pool_owner.typeIdPool()[self.pf_start .. self.pf_start + self.pf_len];
    }

    /// The declaration's source-declared nominal record field order.
    pub fn declaredFields(self: CheckedNominalDeclaration, pool_owner: anytype) []const CheckedDeclaredField {
        return pool_owner.declaredFieldPool()[self.df_start .. self.df_start + self.df_len];
    }

    /// The declaration's top-level record field sequence.
    pub fn declaredRecordFields(self: CheckedNominalDeclaration, pool_owner: anytype) []const CheckedNominalRecordField {
        return pool_owner.nominalRecordFieldPool()[self.rf_start .. self.rf_start + self.rf_len];
    }
};

const CheckedSourceTypeRoot = struct {
    source_var: Var,
    checked_root: CheckedTypeId,
};

const CheckedStructuralRootEntry = struct {
    domain: CheckedStructuralKeyDomain,
    root: CheckedTypeId,
    next_plus_one: u32,
};

const CheckedTypePublication = struct {
    store: CheckedTypeStore,
    source_type_roots: []CheckedSourceTypeRoot = &.{},

    pub fn rootForSourceVar(self: *const CheckedTypePublication, module: TypedCIR.Module, var_: Var) ?CheckedTypeId {
        const resolved = module.typeStoreConst().resolveVar(var_).var_;
        var low: usize = 0;
        var high: usize = self.source_type_roots.len;
        const needle = @intFromEnum(resolved);
        while (low < high) {
            const mid = low + (high - low) / 2;
            const entry = self.source_type_roots[mid];
            const candidate = @intFromEnum(entry.source_var);
            if (candidate == needle) return entry.checked_root;
            if (candidate < needle) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return null;
    }

    fn deinitIndex(self: *CheckedTypePublication, allocator: Allocator) void {
        allocator.free(self.source_type_roots);
        self.source_type_roots = &.{};
    }

    fn deinit(self: *CheckedTypePublication, allocator: Allocator) void {
        self.deinitIndex(allocator);
        self.store.deinit(allocator);
    }
};

/// Public `CheckedTypeStore` declaration.
///
/// Recursive types are stored as cyclic `CheckedTypeId` graphs with no implicit
/// tree structure, so every traversal of a store root must guard against cycles.
/// New `CheckedTypeId` traversals must be expressed through `checked_traverse.zig`
/// (`BoolPredicateTraversal`, `ReserveThenFillTraversal`, or `DigestTraversal`),
/// which own the visited/active memo and guarantee the memo is written before a
/// root is descended. Hand-rolled visited/active sets are prohibited: they make
/// "read the memo but forget the write" compile cleanly and only fail on
/// recursive inputs.
pub const CheckedTypeStore = struct {
    /// Transient projection state (never serialized): non-null while a
    /// nominal use's backing template is being projected. Nested template
    /// references (including mutual recursion between declarations) must
    /// share this private id space so in-progress cycles close on their
    /// pending ids; when null, a nominal use forks a fresh private space—
    /// sharing template ids ACROSS uses would let Monotype's instantiation
    /// graphs bind one use's formals to another use's monos.
    template_use_active: ?*std.AutoHashMap(Var, CheckedTypeId) = null,
    /// Build-only canonical-key index. Paths that must preserve an explicit
    /// identity instance reserve a distinct root without consulting this map;
    /// ordinary structural interning resolves to the first root for the key.
    root_index: std.AutoHashMapUnmanaged(canonical.CanonicalTypeKey, CheckedTypeId) = .empty,
    /// Build-only immediate-payload interner. The fast hash selects a collision
    /// chain; equality is always checked against the stored payload, so this is
    /// exact even if two distinct payloads have the same hash. Child ids are
    /// already interned, making this the DAG's structural-consing index.
    structural_root_heads: std.AutoHashMapUnmanaged(u64, u32) = .empty,
    structural_root_entries: std.ArrayListUnmanaged(CheckedStructuralRootEntry) = .empty,
    roots: std.ArrayList(CheckedTypeRoot) = .empty,
    schemes: std.ArrayList(CheckedTypeScheme) = .empty,
    payloads: std.ArrayList(StoredCheckedTypePayload) = .empty,
    nominal_declarations: std.ArrayList(CheckedNominalDeclaration) = .empty,
    /// Flat pool of `CheckedTypeId`s for alias/nominal/function args, tuples,
    /// tag args, scheme generalized vars, and decl formal args.
    type_id_pool: std.ArrayList(CheckedTypeId) = .empty,
    /// Flat pool of record fields backing record/record_unbound payloads.
    record_field_pool: std.ArrayList(CheckedRecordField) = .empty,
    /// Flat pool of source-declared nominal record layout fields.
    declared_field_pool: std.ArrayList(CheckedDeclaredField) = .empty,
    /// Flat pool of declared-order nominal record fields.
    nominal_record_field_pool: std.ArrayList(CheckedNominalRecordField) = .empty,
    /// Flat pool of static-dispatch constraints backing flex/rigid variables.
    constraint_pool: std.ArrayList(CheckedStaticDispatchConstraint) = .empty,
    /// Flat pool of (range-form) tags backing tag_union payloads.
    tag_pool: std.ArrayList(CheckedTag) = .empty,
    /// Interner backing variable names.
    var_names: canonical.NameInterner = .{},
    /// True for a store reconstructed from a serialized buffer (pools point into
    /// buffer-owned memory and must not be freed).
    serialized: bool = false,

    /// Build-only projection state that is never serialized; null on a
    /// frozen store.
    pub const serde_transient_fields = [_][]const u8{
        "template_use_active",
        "root_index",
        "structural_root_heads",
        "structural_root_entries",
    };

    /// The shared flat pool of `CheckedTypeId`s backing range fields.
    pub fn typeIdPool(self: *const CheckedTypeStore) []const CheckedTypeId {
        return self.type_id_pool.items;
    }

    /// The shared flat pool of record fields backing record range fields.
    pub fn recordFieldPool(self: *const CheckedTypeStore) []const CheckedRecordField {
        return self.record_field_pool.items;
    }

    /// The shared flat pool of declared nominal record fields.
    pub fn declaredFieldPool(self: *const CheckedTypeStore) []const CheckedDeclaredField {
        return self.declared_field_pool.items;
    }

    /// The shared flat pool of declared-order nominal record fields.
    pub fn nominalRecordFieldPool(self: *const CheckedTypeStore) []const CheckedNominalRecordField {
        return self.nominal_record_field_pool.items;
    }

    /// The shared flat pool of static-dispatch constraints.
    pub fn constraintPool(self: *const CheckedTypeStore) []const CheckedStaticDispatchConstraint {
        return self.constraint_pool.items;
    }

    /// The shared flat pool of (range-form) tags.
    pub fn tagPool(self: *const CheckedTypeStore) []const CheckedTag {
        return self.tag_pool.items;
    }

    /// Text of a stored variable name id, or null when absent.
    pub fn varName(self: *const CheckedTypeStore, id: OptionalVarNameId) ?[]const u8 {
        const name_id = id.get() orelse return null;
        return self.var_names.getText(@intFromEnum(name_id));
    }

    /// Number of stored payloads (checked type roots).
    pub fn payloadCount(self: *const CheckedTypeStore) usize {
        return self.payloads.items.len;
    }

    /// Materialize the public read-form payload for `id`. Slice fields alias the
    /// store's pools; no allocation.
    pub fn payload(self: *const CheckedTypeStore, id: CheckedTypeId) CheckedTypePayload {
        const index: usize = @intFromEnum(id);
        if (index >= self.payloads.items.len) {
            checkedArtifactInvariant("checked type payload id is out of range", .{});
        }
        return reconstructCheckedTypePayload(self, self.payloads.items[index]);
    }

    /// Append `ids` to `type_id_pool`, returning their range.
    fn appendTypeIds(self: *CheckedTypeStore, allocator: Allocator, ids: []const CheckedTypeId) Allocator.Error!CheckedTypeRange {
        // Pools only grow during construction. A frozen (deserialized) store's pools
        // alias buffer memory and must never be appended to—this catches such a bug,
        // and is the boundary where build-time aliasing slices could be invalidated
        // (see the `argsSlice`/`payload`/`formalArgs` aliasing-invariant docs).
        std.debug.assert(!self.serialized);
        return artifact_serialize.appendSpan(CheckedTypeRange, CheckedTypeId, &self.type_id_pool, allocator, ids);
    }

    /// Append `fields` to `record_field_pool`, returning their range.
    fn appendRecordFields(self: *CheckedTypeStore, allocator: Allocator, fields: []const CheckedRecordField) Allocator.Error!CheckedTypeRange {
        std.debug.assert(!self.serialized);
        return artifact_serialize.appendSpan(CheckedTypeRange, CheckedRecordField, &self.record_field_pool, allocator, fields);
    }

    /// Append `fields` to `declared_field_pool`, returning their range.
    fn appendDeclaredFields(self: *CheckedTypeStore, allocator: Allocator, fields: []const CheckedDeclaredField) Allocator.Error!CheckedTypeRange {
        std.debug.assert(!self.serialized);
        return artifact_serialize.appendSpan(CheckedTypeRange, CheckedDeclaredField, &self.declared_field_pool, allocator, fields);
    }

    /// Append `fields` to `nominal_record_field_pool`, returning their range.
    fn appendNominalRecordFields(self: *CheckedTypeStore, allocator: Allocator, fields: []const CheckedNominalRecordField) Allocator.Error!CheckedTypeRange {
        std.debug.assert(!self.serialized);
        return artifact_serialize.appendSpan(CheckedTypeRange, CheckedNominalRecordField, &self.nominal_record_field_pool, allocator, fields);
    }

    /// Append `constraints` to `constraint_pool`, returning their range.
    fn appendConstraints(self: *CheckedTypeStore, allocator: Allocator, constraints: []const CheckedStaticDispatchConstraint) Allocator.Error!CheckedTypeRange {
        std.debug.assert(!self.serialized);
        return artifact_serialize.appendSpan(CheckedTypeRange, CheckedStaticDispatchConstraint, &self.constraint_pool, allocator, constraints);
    }

    /// Intern a variable name, returning its optional interner id (`.none`
    /// for an unnamed variable).
    fn internVarName(self: *CheckedTypeStore, allocator: Allocator, name: ?[]const u8) Allocator.Error!OptionalVarNameId {
        const text = name orelse return .none;
        return .some(@enumFromInt(try self.var_names.insert(allocator, text)));
    }

    /// Convert a build-form variable into stored form, copying its constraints
    /// into the pool and interning its name. Frees the build constraints/name.
    fn commitVariable(self: *CheckedTypeStore, allocator: Allocator, variable: CheckedTypeVariable) Allocator.Error!StoredTypeVariable {
        const name_id = try self.internVarName(allocator, variable.name);
        if (variable.name) |name| allocator.free(name);
        const constraints = try self.appendConstraints(allocator, variable.constraints);
        if (variable.constraints.len != 0) allocator.free(variable.constraints);
        return .{
            .name = name_id,
            .constraints = constraints,
            .numeric_default_phase = variable.numeric_default_phase,
            .row_default = variable.row_default,
        };
    }

    /// Convert a build-form payload into stored form, copying all slices into the
    /// store's pools and freeing the build memory. Takes ownership of `build`.
    fn commitPayload(self: *CheckedTypeStore, allocator: Allocator, build: CheckedTypePayloadBuild) Allocator.Error!StoredCheckedTypePayload {
        return switch (build) {
            .pending => .pending,
            .err => .err,
            .empty_record => .empty_record,
            .empty_tag_union => .empty_tag_union,
            .flex => |v| .{ .flex = try self.commitVariable(allocator, v) },
            .rigid => |v| .{ .rigid = try self.commitVariable(allocator, v) },
            .alias => |a| blk: {
                const args = try self.appendTypeIds(allocator, a.args);
                if (a.args.len != 0) allocator.free(a.args);
                break :blk .{ .alias = .{
                    .name = a.name,
                    .origin_module = a.origin_module,
                    .owner_module = a.owner_module,
                    .source_decl = a.source_decl,
                    .builtin_origin = a.builtin_origin,
                    .backing = a.backing,
                    .args = args,
                } };
            },
            .record => |r| blk: {
                const fields = try self.appendRecordFields(allocator, r.fields);
                if (r.fields.len != 0) allocator.free(r.fields);
                break :blk .{ .record = .{ .fields = fields, .ext = r.ext } };
            },
            .record_unbound => |fields| blk: {
                const range = try self.appendRecordFields(allocator, fields);
                if (fields.len != 0) allocator.free(fields);
                break :blk .{ .record_unbound = range };
            },
            .tuple => |elems| blk: {
                const range = try self.appendTypeIds(allocator, elems);
                if (elems.len != 0) allocator.free(elems);
                break :blk .{ .tuple = range };
            },
            .nominal => |n| blk: {
                const args = try self.appendTypeIds(allocator, n.args);
                if (n.args.len != 0) allocator.free(n.args);
                const padding_field_types = try self.appendTypeIds(allocator, n.padding_field_types);
                if (n.padding_field_types.len != 0) allocator.free(n.padding_field_types);
                const declared_fields = try self.appendDeclaredFields(allocator, n.declared_fields);
                if (n.declared_fields.len != 0) allocator.free(n.declared_fields);
                break :blk .{ .nominal = .{
                    .name = n.name,
                    .origin_module = n.origin_module,
                    .owner_module = n.owner_module,
                    .source_decl = n.source_decl,
                    .builtin = n.builtin,
                    .is_opaque = n.is_opaque,
                    .representation = n.representation,
                    .args = args,
                    .padding_field_types = padding_field_types,
                    .declared_fields = declared_fields,
                } };
            },
            .function => |f| blk: {
                const args = try self.appendTypeIds(allocator, f.args);
                if (f.args.len != 0) allocator.free(f.args);
                break :blk .{ .function = .{
                    .kind = f.kind,
                    .args = args,
                    .ret = f.ret,
                } };
            },
            .tag_union => |tu| blk: {
                const tags_start: u32 = @intCast(self.tag_pool.items.len);
                try self.tag_pool.ensureUnusedCapacity(allocator, tu.tags.len);
                for (tu.tags) |tag| {
                    const args = try self.appendTypeIds(allocator, tag.args);
                    if (tag.args.len != 0) allocator.free(tag.args);
                    self.tag_pool.appendAssumeCapacity(.{
                        .name = tag.name,
                        .args_start = args.start,
                        .args_len = args.len,
                    });
                }
                if (tu.tags.len != 0) allocator.free(tu.tags);
                break :blk .{ .tag_union = .{
                    .tags = .{ .start = tags_start, .len = @intCast(tu.tags.len) },
                    .ext = tu.ext,
                } };
            },
        };
    }

    /// Set a stored nominal payload's representation in place.
    fn setNominalRepresentation(self: *CheckedTypeStore, id: CheckedTypeId, representation: CheckedNominalRepresentationRef) void {
        const index: usize = @intFromEnum(id);
        if (index >= self.payloads.items.len) {
            checkedArtifactInvariant("nominal representation publication referenced a missing payload", .{});
        }
        if (self.payloads.items[index] != .nominal) {
            checkedArtifactInvariant("nominal representation publication source payload was not nominal", .{});
        }
        self.payloads.items[index].nominal.representation = representation;
    }

    pub fn fromModule(
        allocator: Allocator,
        module: TypedCIR.Module,
        names: *canonical.CanonicalNameStore,
        current_owner: ModuleId,
        imports: []const PublishImportArtifact,
        available: []const ImportedModuleView,
        source_nodes: *const CheckedSourceNodes,
    ) Allocator.Error!CheckedTypePublication {
        const import_views = CheckedImportViews{
            .current_owner = current_owner,
            .direct = imports,
            .available = available,
        };
        var store = CheckedTypeStore{};
        errdefer store.deinit(allocator);
        var active = CheckedSourceTypeRoots.init(allocator);
        defer active.deinit();
        var local_type_declarations = try LocalTypeDeclarationIndex.init(allocator, module, source_nodes);
        defer local_type_declarations.deinit();
        var top_level_defs = try TopLevelDefPatternIndex.init(allocator, module);
        defer top_level_defs.deinit(allocator);
        const module_env = module.moduleEnvConst();

        var node_idx: u32 = 0;
        while (node_idx < module.nodeCount()) : (node_idx += 1) {
            // Every source-marked expr/pattern node gets a published type
            // root, matching exactly what `CheckedBodyStore.fromModule`
            // demands. That includes nodes checking rewrote to runtime
            // errors (tag `.malformed`, e.g. via ambiguity poisoning): their
            // type vars are real, and the body store still publishes the
            // node so the user-facing diagnostics survive to reporting.
            if (source_nodes.hasExpr(@enumFromInt(node_idx))) {
                const expr_idx: CIR.Expr.Idx = @enumFromInt(node_idx);
                _ = try appendCheckedTypeRoot(allocator, module, names, import_views, &store, &active, module.exprType(expr_idx));
                const expr = module.expr(expr_idx).data;
                if (expr == .e_call) {
                    if (expr.e_call.constraint_fn_var) |constraint_fn_var| {
                        _ = try appendCheckedTypeRoot(allocator, module, names, import_views, &store, &active, constraint_fn_var);
                    }
                } else if (expr == .e_field_access) {
                    const field_access = expr.e_field_access;
                    var position: u32 = 0;
                    while (position < field_access.segments.len) : (position += 1) {
                        const segment_idx = module_env.store.fieldAccessSegmentAt(field_access.segments, position);
                        _ = try appendCheckedTypeRoot(
                            allocator,
                            module,
                            names,
                            import_views,
                            &store,
                            &active,
                            ModuleEnv.varFrom(segment_idx),
                        );
                    }
                }
            } else if (source_nodes.hasPattern(@enumFromInt(node_idx))) {
                const pattern_source_var = checkedPatternSourceTypeVar(module, &top_level_defs, @enumFromInt(node_idx));
                _ = try appendCheckedTypeRoot(
                    allocator,
                    module,
                    names,
                    import_views,
                    &store,
                    &active,
                    pattern_source_var,
                );
            }
        }

        // Static-dispatch evidence resolves constrained scheme instantiations
        // after type publication. Publish each recorded fresh variable now so
        // evidence nodes can name the exact concrete dispatcher type by a
        // checked type id rather than retaining checker-only variables.
        for (module_env.scheme_use_pairs.items.items) |pair| {
            _ = try appendCheckedTypeRoot(
                allocator,
                module,
                names,
                import_views,
                &store,
                &active,
                @enumFromInt(pair.fresh_var),
            );
        }
        for (module_env.generated_codec_derivations.items.items) |derivation| {
            inline for (.{
                derivation.source_constraint_fn_var,
                derivation.source_runtime_fn_var,
                derivation.source_shape_var,
                derivation.source_encoding_var,
                derivation.source_state_var,
                derivation.source_error_var,
                derivation.constraint_fn_var,
                derivation.runtime_fn_var,
                derivation.shape_var,
                derivation.encoding_var,
                derivation.state_var,
                derivation.error_var,
            }) |raw_var| {
                _ = try appendCheckedTypeRoot(
                    allocator,
                    module,
                    names,
                    import_views,
                    &store,
                    &active,
                    @enumFromInt(raw_var),
                );
            }
            const calls = module_env.generated_codec_calls.items.items[derivation.calls_start..][0..derivation.calls_len];
            for (calls) |call| {
                inline for (.{ call.dispatcher_var, call.callable_var, call.evidence_var }) |raw_var| {
                    _ = try appendCheckedTypeRoot(
                        allocator,
                        module,
                        names,
                        import_views,
                        &store,
                        &active,
                        @enumFromInt(raw_var),
                    );
                }
                if (call.subject_var != ModuleEnv.GeneratedCodecCall.no_subject_var) {
                    _ = try appendCheckedTypeRoot(
                        allocator,
                        module,
                        names,
                        import_views,
                        &store,
                        &active,
                        @enumFromInt(call.subject_var),
                    );
                }
            }
        }
        for (module_env.store.sliceStatements(module_env.all_statements)) |statement_idx| {
            if (!source_nodes.hasStatement(statement_idx)) continue;
            switch (module.getStatement(statement_idx)) {
                .s_alias_decl => _ = try appendCheckedTypeRoot(allocator, module, names, import_views, &store, &active, ModuleEnv.varFrom(statement_idx)),
                .s_nominal_decl => |nominal| try appendCheckedNominalDeclarationFromStatement(
                    allocator,
                    module,
                    names,
                    import_views,
                    &store,
                    &active,
                    &local_type_declarations,
                    statement_idx,
                    nominal.header,
                    nominal.anno,
                    nominal.is_opaque,
                ),
                .s_decl,
                .s_var,
                .s_var_uninitialized,
                .s_reassign,
                .s_crash,
                .s_dbg,
                .s_expr,
                .s_expect,
                .s_for,
                .s_while,
                .s_infinite_loop,
                .s_breakable_loop,
                .s_break,
                .s_return,
                .s_import,
                .s_where_alias_decl,
                .s_type_anno,
                .s_type_var_alias,
                .s_runtime_error,
                => {},
            }
        }

        for (module.requiresTypes()) |required_type| {
            const required_var = ModuleEnv.varFrom(required_type.type_anno);
            const root = try appendCheckedTypeRoot(allocator, module, names, import_views, &store, &active, required_var);
            const scheme_key = try canonical_type_keys.schemeFromVar(
                allocator,
                module.typeStoreConst(),
                module.moduleEnvConst(),
                required_var,
            );
            if (findCheckedTypeScheme(store.schemes.items, scheme_key) == null) {
                const scheme_id: CheckedTypeSchemeId = @enumFromInt(@as(u32, @intCast(store.schemes.items.len)));
                try store.schemes.append(allocator, .{
                    .id = scheme_id,
                    .key = scheme_key,
                    .root = root,
                });
            }

            const aliases = module_env.for_clause_aliases.sliceRange(required_type.type_aliases);
            for (aliases) |alias| {
                const alias_statement = module_env.store.getStatement(alias.alias_stmt_idx);
                if (alias_statement != .s_alias_decl) {
                    checkedArtifactInvariant("platform for-clause alias metadata referenced a non-alias statement", .{});
                }
                const alias_anno = alias_statement.s_alias_decl.anno;
                _ = try appendCheckedTypeRoot(allocator, module, names, import_views, &store, &active, ModuleEnv.varFrom(alias.alias_stmt_idx));
                _ = try appendCheckedTypeRoot(allocator, module, names, import_views, &store, &active, ModuleEnv.varFrom(alias_anno));
            }
        }

        try appendStaticDispatchTypeRoots(allocator, module, names, import_views, source_nodes, &store, &active);

        // Evidence nodes retain exact checked callable instantiations. Publish
        // every fresh type participating in a recorded scheme use, including
        // the constraint function that identifies a selected dispatch target.
        for (module_env.scheme_uses.items.items) |record| {
            if (record.slot_kind == @intFromEnum(ModuleEnv.SchemeUseRecord.Slot.dispatch_target)) {
                _ = try appendCheckedTypeRoot(allocator, module, names, import_views, &store, &active, @enumFromInt(record.slot_data));
            }
            const pairs = module_env.scheme_use_pairs.items.items[record.pairs_start .. record.pairs_start + record.pairs_len];
            for (pairs) |pair| {
                _ = try appendCheckedTypeRoot(allocator, module, names, import_views, &store, &active, @enumFromInt(pair.fresh_var));
            }
        }

        for (module_env.store.sliceDefs(module_env.global_value_defs)) |def_idx| {
            const root = try appendCheckedTypeRoot(allocator, module, names, import_views, &store, &active, module.defType(def_idx));
            const scheme_key = try canonical_type_keys.schemeFromVar(
                allocator,
                module.typeStoreConst(),
                module.moduleEnvConst(),
                module.defType(def_idx),
            );
            if (findCheckedTypeScheme(store.schemes.items, scheme_key) == null) {
                const scheme_id: CheckedTypeSchemeId = @enumFromInt(@as(u32, @intCast(store.schemes.items.len)));
                try store.schemes.append(allocator, .{
                    .id = scheme_id,
                    .key = scheme_key,
                    .root = root,
                });
            }
        }

        // Self-containment (issue #9983 / Option A): the published declaration
        // table so far holds only THIS module's own declarations. Standalone
        // consumers (glue) read an artifact without loading the declaring
        // module's artifact, so embed a copy of every imported nominal
        // declaration reachable from the published types, keyed by stable
        // content identity.
        try embedReachableImportedNominalDecls(allocator, &store, names, import_views);

        const source_type_roots = try sourceTypeRootsFromIndex(allocator, &active);
        errdefer allocator.free(source_type_roots);

        return .{
            .store = store,
            .source_type_roots = source_type_roots,
        };
    }

    pub fn view(self: *const CheckedTypeStore) CheckedTypeStoreView {
        return .{
            .roots = self.roots.items,
            .schemes = self.schemes.items,
            .stored_payloads = self.payloads.items,
            .nominal_declarations = self.nominal_declarations.items,
            .type_id_pool = self.type_id_pool.items,
            .record_field_pool = self.record_field_pool.items,
            .declared_field_pool = self.declared_field_pool.items,
            .nominal_record_field_pool = self.nominal_record_field_pool.items,
            .constraint_pool = self.constraint_pool.items,
            .tag_pool = self.tag_pool.items,
            .var_names = &self.var_names,
        };
    }

    pub fn rootForKey(self: *const CheckedTypeStore, key: canonical.CanonicalTypeKey) ?CheckedTypeId {
        if (!self.serialized) return self.root_index.get(key);

        // Serialized stores are immutable views and intentionally do not carry
        // the construction index.
        for (self.roots.items) |root| {
            if (std.meta.eql(root.key.bytes, key.bytes)) return root.id;
        }
        return null;
    }

    pub fn rootContainsIdentityVariables(self: *const CheckedTypeStore, root: CheckedTypeId) bool {
        const index: usize = @intFromEnum(root);
        if (index >= self.roots.items.len) {
            checkedArtifactInvariant("checked identity metadata referenced a missing root", .{});
        }
        return self.roots.items[index].contains_identity_variables;
    }

    fn indexRoot(
        self: *CheckedTypeStore,
        allocator: Allocator,
        root: CheckedTypeRoot,
    ) Allocator.Error!void {
        const entry = try self.root_index.getOrPut(allocator, root.key);
        if (!entry.found_existing) entry.value_ptr.* = root.id;
    }

    fn structuralRootForPayload(
        self: *const CheckedTypeStore,
        domain: CheckedStructuralKeyDomain,
        fingerprint: u64,
        build_payload: CheckedTypePayloadBuild,
    ) ?CheckedTypeId {
        var entry_plus_one = self.structural_root_heads.get(fingerprint) orelse return null;
        while (entry_plus_one != 0) {
            const entry = self.structural_root_entries.items[entry_plus_one - 1];
            if (entry.domain == domain and
                checkedTypePayloadBuildEqlStored(build_payload, self.payload(entry.root), self)) return entry.root;
            entry_plus_one = entry.next_plus_one;
        }
        return null;
    }

    fn indexStructuralRoot(
        self: *CheckedTypeStore,
        allocator: Allocator,
        domain: CheckedStructuralKeyDomain,
        root: CheckedTypeId,
        fingerprint: u64,
    ) Allocator.Error!void {
        const head = try self.structural_root_heads.getOrPut(allocator, fingerprint);
        if (!head.found_existing) head.value_ptr.* = 0;
        errdefer {
            if (!head.found_existing) _ = self.structural_root_heads.remove(fingerprint);
        }
        const previous_plus_one = head.value_ptr.*;
        const entry_index: u32 = @intCast(self.structural_root_entries.items.len);
        try self.structural_root_entries.append(allocator, .{
            .domain = domain,
            .root = root,
            .next_plus_one = previous_plus_one,
        });
        // Set the head only after the entry exists.
        head.value_ptr.* = entry_index + 1;
    }

    pub fn schemeForKey(self: *const CheckedTypeStore, key: canonical.CanonicalTypeSchemeKey) ?CheckedTypeScheme {
        for (self.schemes.items) |scheme| {
            if (std.meta.eql(scheme.key.bytes, key.bytes)) return scheme;
        }
        return null;
    }

    pub fn appendSyntheticFunctionRoot(
        self: *CheckedTypeStore,
        allocator: Allocator,
        kind: CheckedFunctionKind,
        args: []const CheckedTypeId,
        ret: CheckedTypeId,
    ) Allocator.Error!CheckedTypeId {
        const finalized_kind = finalizedFunctionKind(kind);
        var contains_identity_variables = self.rootContainsIdentityVariables(ret);
        for (args) |arg| {
            contains_identity_variables = contains_identity_variables or self.rootContainsIdentityVariables(arg);
        }
        const build_payload = CheckedTypePayloadBuild{ .function = .{
            .kind = finalized_kind,
            .args = args,
            .ret = ret,
        } };
        const fingerprint = if (!contains_identity_variables)
            checkedTypePayloadStructuralFingerprint(.synthetic_function, build_payload)
        else
            null;
        if (fingerprint) |value| {
            if (self.structuralRootForPayload(.synthetic_function, value, build_payload)) |existing| return existing;
        }
        const key = syntheticFunctionTypeKey(self, finalized_kind, args, ret);
        if (!contains_identity_variables) {
            if (self.rootForKey(key)) |existing| return existing;
        }

        const id: CheckedTypeId = @enumFromInt(@as(u32, @intCast(self.roots.items.len)));
        try self.roots.ensureUnusedCapacity(allocator, 1);
        try self.payloads.ensureUnusedCapacity(allocator, 1);
        const args_range = try self.appendTypeIds(allocator, args);

        const root = CheckedTypeRoot{
            .id = id,
            .key = key,
            .contains_identity_variables = contains_identity_variables,
        };
        self.roots.appendAssumeCapacity(root);
        self.payloads.appendAssumeCapacity(.{ .function = .{
            .kind = finalized_kind,
            .args = args_range,
            .ret = ret,
        } });
        errdefer {
            _ = self.payloads.pop();
            _ = self.roots.pop();
        }
        try self.indexRoot(allocator, root);
        if (fingerprint) |value| try self.indexStructuralRoot(allocator, .synthetic_function, id, value);

        try self.ensureSyntheticSchemeForRoot(allocator, id, key);
        return id;
    }

    pub fn appendSyntheticPayloadRoot(
        self: *CheckedTypeStore,
        allocator: Allocator,
        names: *const canonical.CanonicalNameStore,
        build_payload: CheckedTypePayloadBuild,
    ) Allocator.Error!CheckedTypeId {
        var owned_payload = build_payload;
        var payload_owned = true;
        errdefer if (payload_owned) deinitCheckedTypePayloadBuild(allocator, &owned_payload);

        const structurally_internable = !checkedTypePayloadBuildContainsIdentityVariables(self, owned_payload);
        const fingerprint = if (structurally_internable)
            checkedTypePayloadStructuralFingerprint(.checked_payload, owned_payload)
        else
            null;
        if (fingerprint) |value| {
            if (self.structuralRootForPayload(.checked_payload, value, owned_payload)) |existing| {
                deinitCheckedTypePayloadBuild(allocator, &owned_payload);
                payload_owned = false;
                return existing;
            }
        }

        const key_info = try checkedTypePayloadKeyBuild(allocator, names, self, owned_payload);
        if (!key_info.contains_identity_variables) {
            if (self.rootForKey(key_info.key)) |existing| {
                deinitCheckedTypePayloadBuild(allocator, &owned_payload);
                payload_owned = false;
                return existing;
            }
        }

        const id: CheckedTypeId = @enumFromInt(@as(u32, @intCast(self.roots.items.len)));
        try self.roots.ensureUnusedCapacity(allocator, 1);
        try self.payloads.ensureUnusedCapacity(allocator, 1);

        const stored = try self.commitPayload(allocator, owned_payload);
        payload_owned = false;
        const root = CheckedTypeRoot{
            .id = id,
            .key = key_info.key,
            .contains_identity_variables = key_info.contains_identity_variables,
        };
        self.roots.appendAssumeCapacity(root);
        self.payloads.appendAssumeCapacity(stored);
        errdefer {
            _ = self.payloads.pop();
            _ = self.roots.pop();
        }
        try self.indexRoot(allocator, root);
        if (fingerprint) |value| try self.indexStructuralRoot(allocator, .checked_payload, id, value);

        try self.ensureSyntheticSchemeForRoot(allocator, id, key_info.key);
        return id;
    }

    pub fn ensureEmptyRecordRoot(
        self: *CheckedTypeStore,
        allocator: Allocator,
        names: *const canonical.CanonicalNameStore,
    ) Allocator.Error!CheckedTypeId {
        const key = try checkedTypePayloadKeyBuild(allocator, names, self, .empty_record);
        if (self.rootForKey(key)) |existing| {
            if (self.payload(existing) != .empty_record) try self.replaceTypeRootPayload(allocator, existing, .empty_record);
            return existing;
        }
        return try self.appendSyntheticPayloadRoot(allocator, names, .empty_record);
    }

    pub fn ensureEmptyTagUnionRoot(
        self: *CheckedTypeStore,
        allocator: Allocator,
        names: *const canonical.CanonicalNameStore,
    ) Allocator.Error!CheckedTypeId {
        const key = try checkedTypePayloadKeyBuild(allocator, names, self, .empty_tag_union);
        if (self.rootForKey(key)) |existing| {
            if (self.payload(existing) != .empty_tag_union) try self.replaceTypeRootPayload(allocator, existing, .empty_tag_union);
            return existing;
        }
        return try self.appendSyntheticPayloadRoot(allocator, names, .empty_tag_union);
    }

    /// Reserve a checked type root whose payload will be filled after recursive
    /// cloning has finished.
    pub fn reserveSyntheticTypeRoot(
        self: *CheckedTypeStore,
        allocator: Allocator,
        key: canonical.CanonicalTypeKey,
        contains_identity_variables: bool,
    ) Allocator.Error!CheckedTypeId {
        if (!contains_identity_variables) {
            if (self.rootForKey(key)) |existing| return existing;
        }

        return try self.reserveDistinctSyntheticTypeRoot(allocator, key, contains_identity_variables);
    }

    /// Reserve a distinct checked type root even when another root has the same
    /// structural key. Checked instantiations can share a key while carrying
    /// different explicit identity-variable solutions, so projection paths that
    /// preserve one source instance must keep its payload address distinct.
    fn reserveDistinctSyntheticTypeRoot(
        self: *CheckedTypeStore,
        allocator: Allocator,
        key: canonical.CanonicalTypeKey,
        contains_identity_variables: bool,
    ) Allocator.Error!CheckedTypeId {
        const id: CheckedTypeId = @enumFromInt(@as(u32, @intCast(self.roots.items.len)));
        try self.roots.ensureUnusedCapacity(allocator, 1);
        try self.payloads.ensureUnusedCapacity(allocator, 1);

        const root = CheckedTypeRoot{
            .id = id,
            .key = key,
            .contains_identity_variables = contains_identity_variables,
        };
        self.roots.appendAssumeCapacity(root);
        self.payloads.appendAssumeCapacity(.pending);
        try self.indexRoot(allocator, root);

        return id;
    }

    /// Fill a previously reserved checked type root with its explicit payload.
    pub fn fillSyntheticTypeRoot(
        self: *CheckedTypeStore,
        allocator: Allocator,
        root: CheckedTypeId,
        build_payload: CheckedTypePayloadBuild,
    ) Allocator.Error!void {
        const index: usize = @intFromEnum(root);
        if (index >= self.payloads.items.len) {
            checkedArtifactInvariant("synthetic checked type fill referenced a missing root", .{});
        }
        if (self.payloads.items[index] != .pending) {
            checkedArtifactInvariant("synthetic checked type fill referenced an already-filled root", .{});
        }

        var owned_payload = build_payload;
        errdefer deinitCheckedTypePayloadBuild(allocator, &owned_payload);
        const stored = try self.commitPayload(allocator, owned_payload);
        self.payloads.items[index] = stored;
        errdefer self.payloads.items[index] = .pending;
        try self.ensureSyntheticSchemeForRoot(allocator, root, self.roots.items[index].key);
    }

    pub fn replaceTypeRootPayload(
        self: *CheckedTypeStore,
        allocator: Allocator,
        root: CheckedTypeId,
        build_payload: CheckedTypePayloadBuild,
    ) Allocator.Error!void {
        const index: usize = @intFromEnum(root);
        if (index >= self.payloads.items.len) {
            checkedArtifactInvariant("checked type payload replacement referenced a missing root", .{});
        }

        var owned_payload = build_payload;
        var payload_owned = true;
        errdefer if (payload_owned) deinitCheckedTypePayloadBuild(allocator, &owned_payload);
        const stored = try self.commitPayload(allocator, owned_payload);
        payload_owned = false;
        self.payloads.items[index] = stored;
        try self.ensureSyntheticSchemeForRoot(allocator, root, self.roots.items[index].key);
    }

    pub fn nominalDeclaration(
        self: *const CheckedTypeStore,
        nominal: canonical.NominalTypeKey,
    ) ?CheckedNominalDeclaration {
        for (self.nominal_declarations.items) |declaration| {
            if (canonicalNominalTypeKeyEql(declaration.nominal, nominal)) return declaration;
        }
        return null;
    }

    pub fn nominalDeclarationById(
        self: *const CheckedTypeStore,
        id: CheckedNominalDeclarationId,
    ) CheckedNominalDeclaration {
        return self.view().nominalDeclarationById(id);
    }

    pub fn nominalDeclarationForPayload(
        self: *const CheckedTypeStore,
        nominal: CheckedNominalType,
    ) ?CheckedNominalDeclaration {
        return self.nominalDeclaration(checkedNominalTypeKey(nominal));
    }

    pub fn nominalBackingTemplateForPayload(
        self: *const CheckedTypeStore,
        nominal: CheckedNominalType,
    ) ?CheckedTypeId {
        if (nominal.representation == .opaque_without_backing) return null;
        if (nominal.builtin) |builtin_nominal| {
            if (!builtinNominalHasDeclarationBacking(builtin_nominal)) return null;
        }
        const declaration = self.nominalDeclarationForPayload(nominal) orelse {
            checkedArtifactInvariant("checked nominal payload referenced a missing nominal declaration", .{});
        };
        return declaration.backing;
    }

    pub fn ensureInstantiatedNominalBackingRootForPayload(
        self: *CheckedTypeStore,
        allocator: Allocator,
        names: *const canonical.CanonicalNameStore,
        nominal: CheckedNominalType,
    ) Allocator.Error!?CheckedTypeId {
        if (nominal.representation == .opaque_without_backing) return null;
        if (nominal.builtin) |builtin_nominal| {
            if (!builtinNominalHasDeclarationBacking(builtin_nominal)) return null;
        }
        const declaration = self.nominalDeclarationForPayload(nominal) orelse {
            checkedArtifactInvariant("checked nominal payload referenced a missing nominal declaration", .{});
        };
        return try self.ensureInstantiatedNominalBackingRoot(allocator, names, declaration, nominal.args);
    }

    pub fn ensureInstantiatedNominalBackingRoot(
        self: *CheckedTypeStore,
        allocator: Allocator,
        names: *const canonical.CanonicalNameStore,
        declaration: CheckedNominalDeclaration,
        actual_args: []const CheckedTypeId,
    ) Allocator.Error!CheckedTypeId {
        const formal_args = declaration.formalArgs(self);
        if (formal_args.len != actual_args.len) {
            checkedArtifactInvariant("nominal backing instantiation arity did not match declaration", .{});
        }
        if (checkedTypeIdSliceEql(formal_args, actual_args)) return declaration.backing;

        var active = collections.DenseMap(CheckedTypeId, CheckedTypeId).init(allocator);
        defer active.deinit();

        // formalArgs and nominal args alias type_id_pool, which cloning may grow/reallocate; copy.
        const formals_copy = try allocator.dupe(CheckedTypeId, formal_args);
        defer allocator.free(formals_copy);
        const actuals_copy = try allocator.dupe(CheckedTypeId, actual_args);
        defer allocator.free(actuals_copy);

        return try self.cloneCheckedTypeRootSubstituting(
            allocator,
            names,
            declaration.backing,
            formals_copy,
            actuals_copy,
            &active,
        );
    }

    /// Instantiate a declaration's unnamed padding field types with `actual_args`,
    /// returning a freshly-allocated slice the caller owns (in declared order).
    /// Mirrors `ensureInstantiatedNominalBackingRoot` for the padding channel so a
    /// type-parameterized padding field reserves its instantiated size.
    pub fn ensureInstantiatedPaddingFieldTypes(
        self: *CheckedTypeStore,
        allocator: Allocator,
        names: *const canonical.CanonicalNameStore,
        declaration: CheckedNominalDeclaration,
        actual_args: []const CheckedTypeId,
    ) Allocator.Error![]const CheckedTypeId {
        const padding_field_types = declaration.paddingFieldTypes(self);
        if (padding_field_types.len == 0) return &.{};
        const formal_args = declaration.formalArgs(self);
        if (formal_args.len != actual_args.len) {
            checkedArtifactInvariant("nominal padding instantiation arity did not match declaration", .{});
        }
        const out = try allocator.alloc(CheckedTypeId, padding_field_types.len);
        errdefer allocator.free(out);
        if (checkedTypeIdSliceEql(formal_args, actual_args)) {
            @memcpy(out, padding_field_types);
            return out;
        }

        // paddingFieldTypes/formalArgs/actualArgs may alias type_id_pool, which cloning may
        // grow/reallocate; copy before the substitution loop.
        const padding_copy = try allocator.dupe(CheckedTypeId, padding_field_types);
        defer allocator.free(padding_copy);
        const formals_copy = try allocator.dupe(CheckedTypeId, formal_args);
        defer allocator.free(formals_copy);
        const actuals_copy = try allocator.dupe(CheckedTypeId, actual_args);
        defer allocator.free(actuals_copy);

        var active = collections.DenseMap(CheckedTypeId, CheckedTypeId).init(allocator);
        defer active.deinit();
        for (padding_copy, 0..) |padding_ty, i| {
            out[i] = try self.cloneCheckedTypeRootSubstituting(
                allocator,
                names,
                padding_ty,
                formals_copy,
                actuals_copy,
                &active,
            );
        }
        return out;
    }

    pub fn ensureSchemeForRoot(
        self: *CheckedTypeStore,
        allocator: Allocator,
        root: CheckedTypeId,
    ) Allocator.Error!canonical.CanonicalTypeSchemeKey {
        const key = self.roots.items[@intFromEnum(root)].key;
        const scheme_key = syntheticSchemeKeyForType(key);
        try self.ensureSyntheticSchemeForRoot(allocator, root, key);
        return scheme_key;
    }

    fn ensureSyntheticSchemeForRoot(
        self: *CheckedTypeStore,
        allocator: Allocator,
        root: CheckedTypeId,
        key: canonical.CanonicalTypeKey,
    ) Allocator.Error!void {
        const scheme_key = syntheticSchemeKeyForType(key);
        if (self.schemeForKey(scheme_key) != null) return;

        try self.schemes.append(allocator, .{
            .id = @enumFromInt(@as(u32, @intCast(self.schemes.items.len))),
            .key = scheme_key,
            .root = root,
        });
    }

    pub fn deinit(self: *CheckedTypeStore, allocator: Allocator) void {
        self.structural_root_entries.deinit(allocator);
        self.structural_root_heads.deinit(allocator);
        self.root_index.deinit(allocator);
        if (!self.serialized) {
            self.nominal_declarations.deinit(allocator);
            self.payloads.deinit(allocator);
            self.schemes.deinit(allocator);
            self.roots.deinit(allocator);
            self.type_id_pool.deinit(allocator);
            self.record_field_pool.deinit(allocator);
            self.declared_field_pool.deinit(allocator);
            self.nominal_record_field_pool.deinit(allocator);
            self.constraint_pool.deinit(allocator);
            self.tag_pool.deinit(allocator);
            self.var_names.deinit(allocator);
        }
        self.* = .{};
    }

    /// Relocatable serialized form. Every field is a `SafeList`-equivalent POD
    /// slice (or nested `NameInterner.Serialized`), so the store relocates with a
    /// fixed number of base-pointer fixups independent of stored data size.
    pub const Serialized = extern struct {
        roots: SerializedSlice(CheckedTypeRoot) = .{},
        schemes: SerializedSlice(CheckedTypeScheme) = .{},
        payloads: SerializedSlice(StoredCheckedTypePayload) = .{},
        nominal_declarations: SerializedSlice(CheckedNominalDeclaration) = .{},
        type_id_pool: SerializedSlice(CheckedTypeId) = .{},
        record_field_pool: SerializedSlice(CheckedRecordField) = .{},
        declared_field_pool: SerializedSlice(CheckedDeclaredField) = .{},
        nominal_record_field_pool: SerializedSlice(CheckedNominalRecordField) = .{},
        constraint_pool: SerializedSlice(CheckedStaticDispatchConstraint) = .{},
        tag_pool: SerializedSlice(CheckedTag) = .{},
        var_names: canonical.NameInterner.Serialized,

        comptime {
            // 13 = 10 `SerializedSlice` fields + 3 for the nested `var_names`
            // (`SerialStringInterner.Serialized` = 3 `SafeList` base pointers). The
            // count is the true total fixups, independent of stored data size.
            std.debug.assert(artifact_serialize.relocatablePointerCount(Serialized) == 13);
        }

        const Serde = artifact_serialize.SliceStoreSerde(CheckedTypeStore, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    fn cloneCheckedTypeRootSubstituting(
        self: *CheckedTypeStore,
        allocator: Allocator,
        names: *const canonical.CanonicalNameStore,
        source: CheckedTypeId,
        formals: []const CheckedTypeId,
        actuals: []const CheckedTypeId,
        active: *collections.DenseMap(CheckedTypeId, CheckedTypeId),
    ) Allocator.Error!CheckedTypeId {
        if (formals.len != actuals.len) {
            checkedArtifactInvariant("checked type substitution arity mismatch", .{});
        }
        for (formals, actuals) |formal, actual| {
            if (source == formal) return actual;
        }
        if (active.get(source)) |existing| return existing;

        const source_index: usize = @intFromEnum(source);
        if (source_index >= self.payloads.items.len or source_index >= self.roots.items.len) {
            checkedArtifactInvariant("checked type substitution referenced a missing source root {} with {} payloads and {} roots", .{
                source_index,
                self.payloads.items.len,
                self.roots.items.len,
            });
        }

        // A closed root cannot contain any formal. Reusing it is both the
        // semantic result and the DAG-preserving representation; hashing and
        // cloning it would manufacture an equal tree for no substitution.
        if (!self.rootContainsIdentityVariables(source)) return source;

        const key_info = try substitutedCheckedTypeKeyInfo(allocator, names, self, source, formals, actuals);
        if (!key_info.contains_identity_variables) {
            if (self.rootForKey(key_info.key)) |existing| return existing;
        }

        const target = try self.reserveSyntheticTypeRoot(
            allocator,
            key_info.key,
            key_info.contains_identity_variables,
        );
        try active.put(source, target);
        errdefer _ = active.remove(source);

        // Snapshot the source into owned build memory: recursion below appends to
        // the store's pools, which can reallocate slices that alias them.
        var snapshot = try self.snapshotStoredPayload(allocator, self.payloads.items[source_index]);
        defer deinitCheckedTypePayloadBuild(allocator, &snapshot);
        if (snapshot == .function and @intFromEnum(snapshot.function.ret) >= self.payloads.items.len) {
            checkedArtifactInvariant("checked type substitution reached function root {} with missing ret {} and {} payloads", .{
                source_index,
                @intFromEnum(snapshot.function.ret),
                self.payloads.items.len,
            });
        }
        const cloned_payload = try self.cloneCheckedTypePayloadSubstituting(
            allocator,
            names,
            snapshot,
            formals,
            actuals,
            active,
        );
        try self.fillSyntheticTypeRoot(allocator, target, cloned_payload);
        return target;
    }

    /// Deep-copy the immediate slices of a stored payload into owned build-form
    /// memory (one level; nested type ids are left as references). The result
    /// must be freed with `deinitCheckedTypePayloadBuild`.
    fn snapshotStoredPayload(
        self: *const CheckedTypeStore,
        allocator: Allocator,
        stored: StoredCheckedTypePayload,
    ) Allocator.Error!CheckedTypePayloadBuild {
        const read = reconstructCheckedTypePayload(self, stored);
        return switch (read) {
            .pending => .pending,
            .err => .err,
            .empty_record => .empty_record,
            .empty_tag_union => .empty_tag_union,
            .flex => |v| .{ .flex = try snapshotCheckedTypeVariable(allocator, v) },
            .rigid => |v| .{ .rigid = try snapshotCheckedTypeVariable(allocator, v) },
            .alias => |a| .{ .alias = .{
                .name = a.name,
                .origin_module = a.origin_module,
                .owner_module = a.owner_module,
                .source_decl = a.source_decl,
                .builtin_origin = a.builtin_origin,
                .backing = a.backing,
                .args = try allocator.dupe(CheckedTypeId, a.args),
            } },
            .record => |r| .{ .record = .{
                .fields = try allocator.dupe(CheckedRecordField, r.fields),
                .ext = r.ext,
            } },
            .record_unbound => |fields| .{ .record_unbound = try allocator.dupe(CheckedRecordField, fields) },
            .tuple => |elems| .{ .tuple = try allocator.dupe(CheckedTypeId, elems) },
            .nominal => |n| .{ .nominal = .{
                .name = n.name,
                .origin_module = n.origin_module,
                .owner_module = n.owner_module,
                .source_decl = n.source_decl,
                .builtin = n.builtin,
                .is_opaque = n.is_opaque,
                .representation = n.representation,
                .args = try allocator.dupe(CheckedTypeId, n.args),
                .padding_field_types = try allocator.dupe(CheckedTypeId, n.padding_field_types),
                .declared_fields = try allocator.dupe(CheckedDeclaredField, n.declared_fields),
            } },
            .function => |f| .{ .function = .{
                .kind = f.kind,
                .args = try allocator.dupe(CheckedTypeId, f.args),
                .ret = f.ret,
            } },
            .tag_union => |tu| blk: {
                const tags = try allocator.alloc(CheckedTagBuild, tu.tags.len);
                for (tags) |*tag| tag.* = .{ .name = undefined, .args = &.{} };
                errdefer {
                    for (tags) |tag| allocator.free(tag.args);
                    allocator.free(tags);
                }
                for (tu.tags, 0..) |tag, i| {
                    tags[i] = .{ .name = tag.name, .args = try allocator.dupe(CheckedTypeId, tag.argsSlice(self)) };
                }
                break :blk .{ .tag_union = .{ .tags = tags, .ext = tu.ext } };
            },
        };
    }

    fn cloneCheckedTypePayloadSubstituting(
        self: *CheckedTypeStore,
        allocator: Allocator,
        names: *const canonical.CanonicalNameStore,
        build_payload: CheckedTypePayloadBuild,
        formals: []const CheckedTypeId,
        actuals: []const CheckedTypeId,
        active: *collections.DenseMap(CheckedTypeId, CheckedTypeId),
    ) Allocator.Error!CheckedTypePayloadBuild {
        return switch (build_payload) {
            .pending => checkedArtifactInvariant("checked type substitution reached pending payload", .{}),
            .err => .err,
            .empty_record => .empty_record,
            .empty_tag_union => .empty_tag_union,
            .flex => |flex| .{ .flex = .{
                .name = if (flex.name) |name| try allocator.dupe(u8, name) else null,
                .constraints = try self.cloneCheckedStaticDispatchConstraintsSubstituting(allocator, names, flex.constraints, formals, actuals, active),
                .numeric_default_phase = flex.numeric_default_phase,
                .row_default = flex.row_default,
            } },
            .rigid => |rigid| .{ .rigid = .{
                .name = if (rigid.name) |name| try allocator.dupe(u8, name) else null,
                .constraints = try self.cloneCheckedStaticDispatchConstraintsSubstituting(allocator, names, rigid.constraints, formals, actuals, active),
                .numeric_default_phase = rigid.numeric_default_phase,
                .row_default = rigid.row_default,
            } },
            .alias => |alias| .{ .alias = .{
                .name = alias.name,
                .origin_module = alias.origin_module,
                .owner_module = alias.owner_module,
                .source_decl = alias.source_decl,
                .builtin_origin = alias.builtin_origin,
                .backing = try self.cloneCheckedTypeRootSubstituting(allocator, names, alias.backing, formals, actuals, active),
                .args = try self.cloneCheckedTypeIdSliceSubstituting(allocator, names, alias.args, formals, actuals, active),
            } },
            .record => |record| .{ .record = .{
                .fields = try self.cloneCheckedRecordFieldsSubstituting(allocator, names, record.fields, formals, actuals, active),
                .ext = try self.cloneCheckedTypeRootSubstituting(allocator, names, record.ext, formals, actuals, active),
            } },
            .record_unbound => |fields| .{
                .record_unbound = try self.cloneCheckedRecordFieldsSubstituting(allocator, names, fields, formals, actuals, active),
            },
            .tuple => |elems| .{
                .tuple = try self.cloneCheckedTypeIdSliceSubstituting(allocator, names, elems, formals, actuals, active),
            },
            .nominal => |nominal| .{ .nominal = .{
                .name = nominal.name,
                .origin_module = nominal.origin_module,
                .owner_module = nominal.owner_module,
                .source_decl = nominal.source_decl,
                .builtin = nominal.builtin,
                .is_opaque = nominal.is_opaque,
                .representation = nominal.representation,
                .args = try self.cloneCheckedTypeIdSliceSubstituting(allocator, names, nominal.args, formals, actuals, active),
                .padding_field_types = try self.cloneCheckedTypeIdSliceSubstituting(allocator, names, nominal.padding_field_types, formals, actuals, active),
                .declared_fields = try allocator.dupe(CheckedDeclaredField, nominal.declared_fields),
            } },
            .function => |function| try self.cloneCheckedFunctionTypeSubstituting(allocator, names, function, formals, actuals, active),
            .tag_union => |tag_union| .{ .tag_union = .{
                .tags = try self.cloneCheckedTagsSubstituting(allocator, names, tag_union.tags, formals, actuals, active),
                .ext = try self.cloneCheckedTypeRootSubstituting(allocator, names, tag_union.ext, formals, actuals, active),
            } },
        };
    }

    fn cloneCheckedTypeIdSliceSubstituting(
        self: *CheckedTypeStore,
        allocator: Allocator,
        names: *const canonical.CanonicalNameStore,
        ids: []const CheckedTypeId,
        formals: []const CheckedTypeId,
        actuals: []const CheckedTypeId,
        active: *collections.DenseMap(CheckedTypeId, CheckedTypeId),
    ) Allocator.Error![]const CheckedTypeId {
        if (ids.len == 0) return &.{};
        const out = try allocator.alloc(CheckedTypeId, ids.len);
        errdefer allocator.free(out);
        for (ids, 0..) |id, i| {
            out[i] = try self.cloneCheckedTypeRootSubstituting(allocator, names, id, formals, actuals, active);
        }
        return out;
    }

    fn cloneCheckedRecordFieldsSubstituting(
        self: *CheckedTypeStore,
        allocator: Allocator,
        names: *const canonical.CanonicalNameStore,
        fields: []const CheckedRecordField,
        formals: []const CheckedTypeId,
        actuals: []const CheckedTypeId,
        active: *collections.DenseMap(CheckedTypeId, CheckedTypeId),
    ) Allocator.Error![]const CheckedRecordField {
        if (fields.len == 0) return &.{};
        const out = try allocator.alloc(CheckedRecordField, fields.len);
        errdefer allocator.free(out);
        for (fields, 0..) |field, i| {
            out[i] = .{
                .name = field.name,
                .ty = try self.cloneCheckedTypeRootSubstituting(allocator, names, field.ty, formals, actuals, active),
                .kind = if (field.kind.undeterminedVariable()) |variable|
                    .undetermined(try self.cloneCheckedTypeRootSubstituting(allocator, names, variable, formals, actuals, active))
                else
                    field.kind,
            };
        }
        return out;
    }

    fn cloneCheckedTagsSubstituting(
        self: *CheckedTypeStore,
        allocator: Allocator,
        names: *const canonical.CanonicalNameStore,
        tags: []const CheckedTagBuild,
        formals: []const CheckedTypeId,
        actuals: []const CheckedTypeId,
        active: *collections.DenseMap(CheckedTypeId, CheckedTypeId),
    ) Allocator.Error![]const CheckedTagBuild {
        if (tags.len == 0) return &.{};
        const out = try allocator.alloc(CheckedTagBuild, tags.len);
        for (out) |*tag| tag.* = .{ .name = undefined, .args = &.{} };
        errdefer {
            for (out) |tag| allocator.free(tag.args);
            allocator.free(out);
        }
        for (tags, 0..) |tag, i| {
            out[i] = .{
                .name = tag.name,
                .args = try self.cloneCheckedTypeIdSliceSubstituting(allocator, names, tag.args, formals, actuals, active),
            };
        }
        return out;
    }

    fn cloneCheckedStaticDispatchConstraintsSubstituting(
        self: *CheckedTypeStore,
        allocator: Allocator,
        names: *const canonical.CanonicalNameStore,
        constraints: []const CheckedStaticDispatchConstraint,
        formals: []const CheckedTypeId,
        actuals: []const CheckedTypeId,
        active: *collections.DenseMap(CheckedTypeId, CheckedTypeId),
    ) Allocator.Error![]const CheckedStaticDispatchConstraint {
        if (constraints.len == 0) return &.{};
        const out = try allocator.alloc(CheckedStaticDispatchConstraint, constraints.len);
        errdefer allocator.free(out);
        for (constraints, 0..) |constraint, i| {
            out[i] = .{
                .fn_name = constraint.fn_name,
                .fn_ty = try self.cloneCheckedTypeRootSubstituting(allocator, names, constraint.fn_ty, formals, actuals, active),
                .origin = constraint.origin,
            };
        }
        return out;
    }

    fn cloneCheckedFunctionTypeSubstituting(
        self: *CheckedTypeStore,
        allocator: Allocator,
        names: *const canonical.CanonicalNameStore,
        function: CheckedFunctionType,
        formals: []const CheckedTypeId,
        actuals: []const CheckedTypeId,
        active: *collections.DenseMap(CheckedTypeId, CheckedTypeId),
    ) Allocator.Error!CheckedTypePayloadBuild {
        const args = try self.cloneCheckedTypeIdSliceSubstituting(allocator, names, function.args, formals, actuals, active);
        errdefer allocator.free(args);
        const ret = try self.cloneCheckedTypeRootSubstituting(allocator, names, function.ret, formals, actuals, active);

        return .{ .function = .{
            .kind = finalizedFunctionKind(function.kind),
            .args = args,
            .ret = ret,
        } };
    }

    fn checkedTypeSliceContainsIdentityVariables(
        self: *const CheckedTypeStore,
        allocator: Allocator,
        roots: []const CheckedTypeId,
    ) Allocator.Error!bool {
        var context = CheckedTypeIdentityScan{ .store = self };
        return try checked_traverse.checkedTypeSliceContainsIdentityVariables(
            CheckedTypeId,
            CheckedTypeIdentityScan,
            allocator,
            &context,
            roots,
        );
    }

    fn checkedTypeContainsIdentityVariables(
        self: *const CheckedTypeStore,
        allocator: Allocator,
        root: CheckedTypeId,
    ) Allocator.Error!bool {
        var context = CheckedTypeIdentityScan{ .store = self };
        return try checked_traverse.checkedTypeContainsIdentityVariables(
            CheckedTypeId,
            CheckedTypeIdentityScan,
            allocator,
            &context,
            root,
        );
    }
};

const CheckedTypeIdentityScan = struct {
    store: *const CheckedTypeStore,

    pub fn visit(
        self: *@This(),
        traversal: anytype,
        root: CheckedTypeId,
    ) Allocator.Error!bool {
        const index: usize = @intFromEnum(root);
        if (index >= self.store.payloads.items.len) {
            checkedArtifactInvariant("checked type identity scan referenced a missing payload", .{});
        }
        return try checked_traverse.checkedTypePayloadContainsIdentityVariables(
            .forbid,
            traversal,
            self.store,
            root,
            self.store.payload(root),
            self,
        );
    }
};

fn snapshotCheckedTypeVariable(allocator: Allocator, variable: CheckedTypeVariable) Allocator.Error!CheckedTypeVariable {
    const name = if (variable.name) |name_text| try allocator.dupe(u8, name_text) else null;
    errdefer if (name) |owned| allocator.free(owned);
    const constraints = try allocator.dupe(CheckedStaticDispatchConstraint, variable.constraints);
    return .{
        .name = name,
        .constraints = constraints,
        .numeric_default_phase = variable.numeric_default_phase,
        .row_default = variable.row_default,
    };
}

fn deinitCheckedTagsBuild(allocator: Allocator, tags: []const CheckedTagBuild) void {
    for (tags) |tag| allocator.free(tag.args);
    allocator.free(tags);
}

/// Free a build-form payload's individually-allocated slices/name.
fn deinitCheckedTypePayloadBuild(allocator: Allocator, payload: *CheckedTypePayloadBuild) void {
    switch (payload.*) {
        .pending,
        .err,
        .empty_record,
        .empty_tag_union,
        => {},
        .flex => |flex| {
            if (flex.name) |name| allocator.free(name);
            allocator.free(flex.constraints);
        },
        .rigid => |rigid| {
            if (rigid.name) |name| allocator.free(name);
            allocator.free(rigid.constraints);
        },
        .alias => |alias| allocator.free(alias.args),
        .record => |record| allocator.free(record.fields),
        .record_unbound => |fields| allocator.free(fields),
        .tuple => |elems| allocator.free(elems),
        .nominal => |nominal| {
            allocator.free(nominal.args);
            allocator.free(nominal.padding_field_types);
            allocator.free(nominal.declared_fields);
        },
        .function => |function| allocator.free(function.args),
        .tag_union => |tag_union| deinitCheckedTagsBuild(allocator, tag_union.tags),
    }
    payload.* = .pending;
}

const LocalTypeDeclarationIndex = struct {
    const FinalizedRelativeName = union(enum) {
        unique: CIR.Statement.Idx,
        ambiguous,
    };

    finalized_by_relative_name: std.AutoHashMap(Ident.Idx, FinalizedRelativeName),

    fn init(
        allocator: Allocator,
        module: TypedCIR.Module,
        source_nodes: *const CheckedSourceNodes,
    ) Allocator.Error!LocalTypeDeclarationIndex {
        var finalized_by_relative_name = std.AutoHashMap(Ident.Idx, FinalizedRelativeName).init(allocator);
        errdefer finalized_by_relative_name.deinit();

        const module_env = module.moduleEnvConst();
        for (module_env.store.sliceStatements(module_env.all_statements)) |statement_idx| {
            if (!source_nodes.hasStatement(statement_idx)) continue;
            const statement = module.getStatement(statement_idx);
            const header_idx, const anno_idx = switch (statement) {
                .s_alias_decl => |alias| .{ alias.header, alias.anno },
                .s_nominal_decl => |nominal| .{ nominal.header, nominal.anno },
                .s_decl,
                .s_var,
                .s_var_uninitialized,
                .s_reassign,
                .s_crash,
                .s_dbg,
                .s_expr,
                .s_expect,
                .s_for,
                .s_while,
                .s_infinite_loop,
                .s_breakable_loop,
                .s_break,
                .s_return,
                .s_import,
                .s_where_alias_decl,
                .s_type_anno,
                .s_type_var_alias,
                .s_runtime_error,
                => continue,
            };
            if (anno_idx == .placeholder) continue;

            const header = module.moduleEnvConst().store.getTypeHeader(header_idx);
            if (finalized_by_relative_name.getPtr(header.relative_name)) |existing| {
                switch (existing.*) {
                    .unique => |existing_stmt| if (existing_stmt != statement_idx) {
                        existing.* = .ambiguous;
                    },
                    .ambiguous => {},
                }
            } else {
                try finalized_by_relative_name.put(header.relative_name, .{ .unique = statement_idx });
            }
        }

        return .{ .finalized_by_relative_name = finalized_by_relative_name };
    }

    fn deinit(self: *LocalTypeDeclarationIndex) void {
        self.finalized_by_relative_name.deinit();
    }

    fn finalizedStatementForReference(
        self: *const LocalTypeDeclarationIndex,
        module: TypedCIR.Module,
        statement_idx: CIR.Statement.Idx,
    ) CIR.Statement.Idx {
        const statement = module.getStatement(statement_idx);
        const header_idx, const anno_idx = switch (statement) {
            .s_alias_decl => |alias| .{ alias.header, alias.anno },
            .s_nominal_decl => |nominal| .{ nominal.header, nominal.anno },
            .s_decl,
            .s_var,
            .s_var_uninitialized,
            .s_reassign,
            .s_crash,
            .s_dbg,
            .s_expr,
            .s_expect,
            .s_for,
            .s_while,
            .s_infinite_loop,
            .s_breakable_loop,
            .s_break,
            .s_return,
            .s_import,
            .s_where_alias_decl,
            .s_type_anno,
            .s_type_var_alias,
            .s_runtime_error,
            => checkedArtifactInvariant("checked declaration template lookup referenced a non-type declaration", .{}),
        };
        if (anno_idx != .placeholder) return statement_idx;

        const header = module.moduleEnvConst().store.getTypeHeader(header_idx);
        return switch (self.finalized_by_relative_name.get(header.relative_name) orelse {
            checkedArtifactInvariant("checked declaration template lookup referenced an unfinalized associated type placeholder", .{});
        }) {
            .unique => |finalized| finalized,
            .ambiguous => checkedArtifactInvariant("checked declaration template lookup referenced an ambiguous associated type placeholder", .{}),
        };
    }
};

fn appendCheckedNominalDeclarationFromStatement(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    imports: CheckedImportViews,
    store: *CheckedTypeStore,
    active: *CheckedSourceTypeRoots,
    local_type_declarations: *const LocalTypeDeclarationIndex,
    statement_idx: CIR.Statement.Idx,
    header_idx: CIR.TypeHeader.Idx,
    anno_idx: CIR.TypeAnno.Idx,
    _: bool,
) Allocator.Error!void {
    if (anno_idx == .placeholder) return;
    if (!localNominalDeclarationIsValid(module, statement_idx)) return;

    const statement_root = try appendCheckedTypeRoot(
        allocator,
        module,
        names,
        imports,
        store,
        active,
        ModuleEnv.varFrom(statement_idx),
    );
    const statement_root_index: usize = @intFromEnum(statement_root);
    if (statement_root_index >= store.payloads.items.len) {
        checkedArtifactInvariant("nominal declaration referenced a missing checked type root", .{});
    }

    const statement_payload = store.payloads.items[statement_root_index];
    if (statement_payload != .nominal) {
        checkedArtifactInvariant(
            "nominal declaration statement root was not a nominal checked type (source content {s})",
            .{@tagName(module.typeStoreConst().resolveVar(ModuleEnv.varFrom(statement_idx)).desc.content)},
        );
    }
    const statement_nominal = statement_payload.nominal;

    const module_env = module.moduleEnvConst();
    const header = module_env.store.getTypeHeader(header_idx);
    const header_args = module_env.store.sliceTypeAnnos(header.args);

    const formal_args = if (header_args.len == 0) &.{} else blk: {
        const out = try allocator.alloc(CheckedTypeId, header_args.len);
        errdefer allocator.free(out);
        for (header_args, 0..) |arg_anno, i| {
            out[i] = try appendCheckedTypeRoot(
                allocator,
                module,
                names,
                imports,
                store,
                active,
                ModuleEnv.varFrom(arg_anno),
            );
        }
        break :blk out;
    };
    var formal_args_owned = formal_args.len != 0;
    errdefer if (formal_args_owned) allocator.free(formal_args);

    const declaration_formals = if (header_args.len == 0) &.{} else blk: {
        const out = try allocator.alloc(DeclarationFormal, header_args.len);
        errdefer allocator.free(out);
        for (header_args, formal_args, 0..) |arg_anno, formal_arg, i| {
            const arg = module_env.store.getTypeAnno(arg_anno);
            out[i] = .{
                .name = switch (arg) {
                    .rigid_var => |rigid| rigid.name,
                    .apply,
                    .rigid_var_lookup,
                    .underscore,
                    .lookup,
                    .tag_union,
                    .tag,
                    .tuple,
                    .record,
                    .@"fn",
                    .parens,
                    .malformed,
                    => checkedArtifactInvariant("nominal declaration header argument was not a rigid type variable", .{}),
                },
                .root = formal_arg,
            };
        }
        break :blk out;
    };
    defer if (declaration_formals.len != 0) allocator.free(declaration_formals);

    const declared_record_fields = try declaredRecordFieldsFromDeclarationAnno(
        allocator,
        module,
        names,
        imports,
        store,
        active,
        local_type_declarations,
        declaration_formals,
        anno_idx,
    );
    defer if (declared_record_fields.len != 0) allocator.free(declared_record_fields);

    const backing = try appendCheckedTypeRootFromDeclarationAnno(
        allocator,
        module,
        names,
        imports,
        store,
        active,
        local_type_declarations,
        declaration_formals,
        anno_idx,
    );
    const padding_field_types = try paddingFieldTypesFromDeclaredRecordFields(allocator, declared_record_fields);
    var padding_field_types_owned = padding_field_types.len != 0;
    errdefer if (padding_field_types_owned) allocator.free(padding_field_types);

    const declared_fields = try declaredFieldsFromDeclarationAnno(
        allocator,
        module,
        names,
        padding_field_types,
        anno_idx,
    );
    var declared_fields_owned = declared_fields.len != 0;
    errdefer if (declared_fields_owned) allocator.free(declared_fields);

    const nominal_payload = CheckedTypePayloadBuild{ .nominal = .{
        .name = statement_nominal.name,
        .origin_module = statement_nominal.origin_module,
        .owner_module = statement_nominal.owner_module,
        .source_decl = @intFromEnum(statement_idx),
        .builtin = statement_nominal.builtin,
        .is_opaque = statement_nominal.is_opaque,
        .representation = if (statement_nominal.builtin) |builtin_id|
            .{ .builtin = builtin_id }
        else
            .{ .local_declaration = localNominalDeclarationIdForStatement(module, statement_idx) },
        .args = formal_args,
        .padding_field_types = padding_field_types,
        .declared_fields = declared_fields,
    } };
    formal_args_owned = false;
    padding_field_types_owned = false;
    declared_fields_owned = false;

    const declaration_root = try appendNominalDeclarationRootPayload(
        allocator,
        names,
        store,
        nominal_payload,
    );
    try appendCheckedNominalDeclarationFromPayload(allocator, store, declaration_root, backing, declared_record_fields);
}

const DeclarationFormal = struct {
    name: Ident.Idx,
    root: CheckedTypeId,
};

fn declarationFormalRoot(formals: []const DeclarationFormal, name: Ident.Idx) ?CheckedTypeId {
    for (formals) |formal| {
        if (formal.name == name) return formal.root;
    }
    return null;
}

fn appendCheckedTypeRootFromDeclarationAnno(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    imports: CheckedImportViews,
    store: *CheckedTypeStore,
    active: *CheckedSourceTypeRoots,
    local_type_declarations: *const LocalTypeDeclarationIndex,
    declaration_formals: []const DeclarationFormal,
    anno_idx: CIR.TypeAnno.Idx,
) Allocator.Error!CheckedTypeId {
    const module_env = module.moduleEnvConst();
    const anno = module_env.store.getTypeAnno(anno_idx);
    return switch (anno) {
        .tag_union => |tag_union| blk: {
            const tags = try checkedTagsFromDeclarationAnnoSpan(
                allocator,
                module,
                names,
                imports,
                store,
                active,
                local_type_declarations,
                declaration_formals,
                tag_union.tags,
            );
            errdefer deinitCheckedTagsBuild(allocator, tags);
            const ext = if (tag_union.ext) |ext_anno|
                try appendCheckedTypeRootFromDeclarationAnno(allocator, module, names, imports, store, active, local_type_declarations, declaration_formals, ext_anno)
            else
                try appendExplicitCheckedTypePayload(allocator, names, store, .empty_tag_union);
            break :blk try appendExplicitCheckedTypePayload(allocator, names, store, .{ .tag_union = .{
                .tags = tags,
                .ext = ext,
            } });
        },
        .record => |record| blk: {
            const fields = try checkedRecordFieldsFromDeclarationAnnoSpan(
                allocator,
                module,
                names,
                imports,
                store,
                active,
                local_type_declarations,
                declaration_formals,
                record.fields,
            );
            errdefer allocator.free(fields);
            const ext = if (record.ext) |ext_anno|
                try appendCheckedTypeRootFromDeclarationAnno(allocator, module, names, imports, store, active, local_type_declarations, declaration_formals, ext_anno)
            else
                try appendExplicitCheckedTypePayload(allocator, names, store, .empty_record);
            break :blk try appendExplicitCheckedTypePayload(allocator, names, store, .{ .record = .{
                .fields = fields,
                .ext = ext,
            } });
        },
        .tuple => |tuple| blk: {
            const elems = try checkedTypeIdsFromDeclarationAnnoSpan(
                allocator,
                module,
                names,
                imports,
                store,
                active,
                local_type_declarations,
                declaration_formals,
                tuple.elems,
            );
            errdefer allocator.free(elems);
            break :blk try appendExplicitCheckedTypePayload(allocator, names, store, .{ .tuple = elems });
        },
        .@"fn" => |func| blk: {
            const args = try checkedTypeIdsFromDeclarationAnnoSpan(
                allocator,
                module,
                names,
                imports,
                store,
                active,
                local_type_declarations,
                declaration_formals,
                func.args,
            );
            errdefer allocator.free(args);
            const ret = try appendCheckedTypeRootFromDeclarationAnno(
                allocator,
                module,
                names,
                imports,
                store,
                active,
                local_type_declarations,
                declaration_formals,
                func.ret,
            );
            break :blk try appendExplicitCheckedTypePayload(allocator, names, store, .{ .function = .{
                .kind = if (func.effectful) .effectful else .pure,
                .args = args,
                .ret = ret,
            } });
        },
        .parens => |parens| try appendCheckedTypeRootFromDeclarationAnno(
            allocator,
            module,
            names,
            imports,
            store,
            active,
            local_type_declarations,
            declaration_formals,
            parens.anno,
        ),
        .lookup => |lookup| switch (lookup.base) {
            .local => |local| blk: {
                const finalized = local_type_declarations.finalizedStatementForReference(module, local.decl_idx);
                const result = try appendCheckedTypeRoot(
                    allocator,
                    module,
                    names,
                    imports,
                    store,
                    active,
                    ModuleEnv.varFrom(finalized),
                );
                break :blk result;
            },
            .builtin,
            .external,
            .pending,
            => try appendCheckedTypeRoot(allocator, module, names, imports, store, active, ModuleEnv.varFrom(anno_idx)),
        },
        .apply => |apply| blk: {
            const actual_args = try checkedTypeIdsFromDeclarationAnnoSpan(
                allocator,
                module,
                names,
                imports,
                store,
                active,
                local_type_declarations,
                declaration_formals,
                apply.args,
            );
            var actual_args_owned = actual_args.len > 0;
            errdefer if (actual_args_owned) allocator.free(actual_args);
            switch (apply.base) {
                .local => |local| {
                    const finalized = local_type_declarations.finalizedStatementForReference(module, local.decl_idx);
                    if (actual_args.len == 0) {
                        break :blk try appendCheckedTypeRoot(
                            allocator,
                            module,
                            names,
                            imports,
                            store,
                            active,
                            ModuleEnv.varFrom(finalized),
                        );
                    }
                    switch (module.getStatement(finalized)) {
                        .s_alias_decl => {
                            const result = try appendInstantiatedAliasDeclarationApplication(
                                allocator,
                                module,
                                names,
                                imports,
                                store,
                                active,
                                local_type_declarations,
                                finalized,
                                actual_args,
                            );
                            if (actual_args_owned) {
                                allocator.free(actual_args);
                                actual_args_owned = false;
                            }
                            break :blk result;
                        },
                        .s_nominal_decl => if (finalized != local.decl_idx) {
                            checkedArtifactInvariant("checked declaration template generic nominal application referenced an associated-type placeholder", .{});
                        },
                        .s_decl,
                        .s_var,
                        .s_var_uninitialized,
                        .s_reassign,
                        .s_crash,
                        .s_dbg,
                        .s_expr,
                        .s_expect,
                        .s_for,
                        .s_while,
                        .s_infinite_loop,
                        .s_breakable_loop,
                        .s_break,
                        .s_return,
                        .s_import,
                        .s_where_alias_decl,
                        .s_type_anno,
                        .s_type_var_alias,
                        .s_runtime_error,
                        => checkedArtifactInvariant("checked declaration template generic application referenced a non-type declaration", .{}),
                    }
                },
                .builtin,
                .external,
                .pending,
                => {
                    const generic_root = try appendCheckedTypeRoot(
                        allocator,
                        module,
                        names,
                        imports,
                        store,
                        active,
                        ModuleEnv.varFrom(anno_idx),
                    );
                    const result = if (actual_args.len == 0)
                        generic_root
                    else
                        try appendInstantiatedNamedApplicationFromTemplate(
                            allocator,
                            names,
                            store,
                            generic_root,
                            actual_args,
                        );
                    if (actual_args_owned) {
                        allocator.free(actual_args);
                        actual_args_owned = false;
                    }
                    break :blk result;
                },
            }
            if (actual_args_owned) {
                allocator.free(actual_args);
                actual_args_owned = false;
            }
            break :blk try appendCheckedTypeRoot(allocator, module, names, imports, store, active, ModuleEnv.varFrom(anno_idx));
        },
        .rigid_var => |rigid| if (declarationFormalRoot(declaration_formals, rigid.name)) |formal|
            formal
        else
            try appendCheckedTypeRoot(allocator, module, names, imports, store, active, ModuleEnv.varFrom(anno_idx)),
        .underscore,
        => try appendCheckedTypeRoot(allocator, module, names, imports, store, active, ModuleEnv.varFrom(anno_idx)),
        .rigid_var_lookup => |lookup| blk: {
            const source = module_env.store.getTypeAnno(lookup.ref);
            switch (source) {
                .rigid_var => |rigid| if (declarationFormalRoot(declaration_formals, rigid.name)) |formal| break :blk formal,
                .apply,
                .rigid_var_lookup,
                .underscore,
                .lookup,
                .tag_union,
                .tag,
                .tuple,
                .record,
                .@"fn",
                .parens,
                .malformed,
                => {},
            }
            break :blk try appendCheckedTypeRoot(allocator, module, names, imports, store, active, ModuleEnv.varFrom(lookup.ref));
        },
        .tag,
        .malformed,
        => try appendCheckedTypeRoot(allocator, module, names, imports, store, active, ModuleEnv.varFrom(anno_idx)),
    };
}

fn appendInstantiatedNamedApplicationFromTemplate(
    allocator: Allocator,
    names: *const canonical.CanonicalNameStore,
    store: *CheckedTypeStore,
    generic_root: CheckedTypeId,
    actual_args: []const CheckedTypeId,
) Allocator.Error!CheckedTypeId {
    const generic_payload = store.payload(generic_root);
    return switch (generic_payload) {
        .alias => |alias| blk: {
            if (alias.args.len != actual_args.len) {
                checkedArtifactInvariant("checked declaration template alias application arity mismatch", .{});
            }

            const formals = try allocator.dupe(CheckedTypeId, alias.args);
            defer allocator.free(formals);

            var active = collections.DenseMap(CheckedTypeId, CheckedTypeId).init(allocator);
            defer active.deinit();
            const backing = try store.cloneCheckedTypeRootSubstituting(
                allocator,
                names,
                alias.backing,
                formals,
                actual_args,
                &active,
            );

            const payload_args = if (actual_args.len == 0) &.{} else try allocator.dupe(CheckedTypeId, actual_args);
            errdefer if (payload_args.len != 0) allocator.free(payload_args);

            break :blk try appendExplicitCheckedTypePayload(allocator, names, store, .{ .alias = .{
                .name = alias.name,
                .origin_module = alias.origin_module,
                .owner_module = alias.owner_module,
                .source_decl = alias.source_decl,
                .builtin_origin = alias.builtin_origin,
                .backing = backing,
                .args = payload_args,
            } });
        },
        .nominal => |nominal| blk: {
            if (nominal.args.len != actual_args.len) {
                checkedArtifactInvariant("checked declaration template nominal application arity mismatch", .{});
            }

            const formals = try allocator.dupe(CheckedTypeId, nominal.args);
            defer allocator.free(formals);

            var active = collections.DenseMap(CheckedTypeId, CheckedTypeId).init(allocator);
            defer active.deinit();
            const padding_field_types = try store.cloneCheckedTypeIdSliceSubstituting(
                allocator,
                names,
                nominal.padding_field_types,
                formals,
                actual_args,
                &active,
            );
            errdefer if (padding_field_types.len != 0) allocator.free(padding_field_types);

            const payload_args = if (actual_args.len == 0) &.{} else try allocator.dupe(CheckedTypeId, actual_args);
            errdefer if (payload_args.len != 0) allocator.free(payload_args);
            const declared_fields = if (nominal.declared_fields.len == 0) &.{} else try allocator.dupe(CheckedDeclaredField, nominal.declared_fields);
            errdefer if (declared_fields.len != 0) allocator.free(declared_fields);

            break :blk try appendExplicitCheckedTypePayload(allocator, names, store, .{ .nominal = .{
                .name = nominal.name,
                .origin_module = nominal.origin_module,
                .owner_module = nominal.owner_module,
                .source_decl = nominal.source_decl,
                .builtin = nominal.builtin,
                .is_opaque = nominal.is_opaque,
                .representation = nominal.representation,
                .args = payload_args,
                .padding_field_types = padding_field_types,
                .declared_fields = declared_fields,
            } });
        },
        .pending,
        .err,
        .flex,
        .rigid,
        .record,
        .record_unbound,
        .tuple,
        .function,
        .empty_record,
        .tag_union,
        .empty_tag_union,
        => checkedArtifactInvariant("checked declaration template application did not resolve to a named type", .{}),
    };
}

fn appendInstantiatedAliasDeclarationApplication(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    imports: CheckedImportViews,
    store: *CheckedTypeStore,
    active: *CheckedSourceTypeRoots,
    local_type_declarations: *const LocalTypeDeclarationIndex,
    statement_idx: CIR.Statement.Idx,
    actual_args: []const CheckedTypeId,
) Allocator.Error!CheckedTypeId {
    const statement = module.getStatement(statement_idx);
    const alias = switch (statement) {
        .s_alias_decl => |alias| alias,
        .s_decl,
        .s_var,
        .s_var_uninitialized,
        .s_reassign,
        .s_crash,
        .s_dbg,
        .s_expr,
        .s_expect,
        .s_for,
        .s_while,
        .s_infinite_loop,
        .s_breakable_loop,
        .s_break,
        .s_return,
        .s_import,
        .s_nominal_decl,
        .s_where_alias_decl,
        .s_type_anno,
        .s_type_var_alias,
        .s_runtime_error,
        => checkedArtifactInvariant("checked declaration template alias application resolved to a non-alias declaration", .{}),
    };
    if (alias.anno == .placeholder) {
        checkedArtifactInvariant("checked declaration template alias application resolved to an unfinalized alias declaration", .{});
    }

    const module_env = module.moduleEnvConst();
    const header = module_env.store.getTypeHeader(alias.header);
    const header_args = module_env.store.sliceTypeAnnos(header.args);
    if (header_args.len != actual_args.len) {
        checkedArtifactInvariant("checked declaration template alias application arity mismatch", .{});
    }

    const declaration_formals = if (header_args.len == 0) &.{} else blk: {
        const out = try allocator.alloc(DeclarationFormal, header_args.len);
        errdefer allocator.free(out);
        for (header_args, actual_args, 0..) |arg_anno, actual_arg, i| {
            const arg = module_env.store.getTypeAnno(arg_anno);
            out[i] = .{
                .name = switch (arg) {
                    .rigid_var => |rigid| rigid.name,
                    .apply,
                    .rigid_var_lookup,
                    .underscore,
                    .lookup,
                    .tag_union,
                    .tag,
                    .tuple,
                    .record,
                    .@"fn",
                    .parens,
                    .malformed,
                    => checkedArtifactInvariant("alias declaration header argument was not a rigid type variable", .{}),
                },
                .root = actual_arg,
            };
        }
        break :blk out;
    };
    defer if (declaration_formals.len != 0) allocator.free(declaration_formals);

    const generic_root = try appendCheckedTypeRoot(
        allocator,
        module,
        names,
        imports,
        store,
        active,
        ModuleEnv.varFrom(statement_idx),
    );
    const generic_payload = store.payload(generic_root);
    if (generic_payload != .alias) {
        checkedArtifactInvariant("checked declaration template alias application root was not an alias", .{});
    }
    const generic_alias = generic_payload.alias;
    const alias_name = generic_alias.name;
    const origin_module = generic_alias.origin_module;
    const owner_module = generic_alias.owner_module;
    const source_decl = generic_alias.source_decl;
    const builtin_origin = generic_alias.builtin_origin;
    const backing = try appendCheckedTypeRootFromDeclarationAnno(
        allocator,
        module,
        names,
        imports,
        store,
        active,
        local_type_declarations,
        declaration_formals,
        alias.anno,
    );

    const payload_args = if (actual_args.len == 0) &.{} else try allocator.dupe(CheckedTypeId, actual_args);
    errdefer if (payload_args.len != 0) allocator.free(payload_args);

    return try appendExplicitCheckedTypePayload(allocator, names, store, .{ .alias = .{
        .name = alias_name,
        .origin_module = origin_module,
        .owner_module = owner_module,
        .source_decl = source_decl,
        .builtin_origin = builtin_origin,
        .backing = backing,
        .args = payload_args,
    } });
}

fn checkedTypeIdsFromDeclarationAnnoSpan(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    imports: CheckedImportViews,
    store: *CheckedTypeStore,
    active: *CheckedSourceTypeRoots,
    local_type_declarations: *const LocalTypeDeclarationIndex,
    declaration_formals: []const DeclarationFormal,
    span: CIR.TypeAnno.Span,
) Allocator.Error![]const CheckedTypeId {
    const annos = module.moduleEnvConst().store.sliceTypeAnnos(span);
    if (annos.len == 0) return &.{};
    const out = try allocator.alloc(CheckedTypeId, annos.len);
    errdefer allocator.free(out);
    for (annos, 0..) |anno, i| {
        out[i] = try appendCheckedTypeRootFromDeclarationAnno(allocator, module, names, imports, store, active, local_type_declarations, declaration_formals, anno);
    }
    return out;
}

fn checkedRecordFieldsFromDeclarationAnnoSpan(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    imports: CheckedImportViews,
    store: *CheckedTypeStore,
    active: *CheckedSourceTypeRoots,
    local_type_declarations: *const LocalTypeDeclarationIndex,
    declaration_formals: []const DeclarationFormal,
    span: CIR.TypeAnno.RecordField.Span,
) Allocator.Error![]const CheckedRecordField {
    const fields = module.moduleEnvConst().store.sliceAnnoRecordFields(span);
    if (fields.len == 0) return &.{};
    // Unnamed (`_` / `_name`) fields are layout padding, not real fields; they
    // stay in the canonical record annotation (declared order) but are excluded
    // from the backing row here so they are never name-resolved or unified.
    var named_count: usize = 0;
    for (fields) |field_idx| {
        const field = module.moduleEnvConst().store.getAnnoRecordField(field_idx);
        if (field.is_unnamed) continue;
        named_count += 1;
    }
    if (named_count == 0) return &.{};
    const out = try allocator.alloc(CheckedRecordField, named_count);
    errdefer allocator.free(out);
    var out_index: usize = 0;
    for (fields) |field_idx| {
        const field = module.moduleEnvConst().store.getAnnoRecordField(field_idx);
        if (field.is_unnamed) continue;
        out[out_index] = .{
            .name = try names.internRecordFieldIdent(module.identStoreConst(), field.name),
            .ty = try appendCheckedTypeRootFromDeclarationAnno(allocator, module, names, imports, store, active, local_type_declarations, declaration_formals, field.ty),
            // The annotation pins the kind concretely (design.md "Field
            // Kinds"): `?:` publishes `optional`, `??` publishes `defaulted`
            // with this module's canonical identity (design.md "Defaulted
            // Fields"), plain `:` publishes `required`. `?:` and `??` never
            // combine—canonicalization rejects `a ?: T ?? d` outright.
            .kind = if (field.is_optional)
                .optional
            else if (field.default_value) |default_expr_idx|
                .defaultedFromParts(
                    try names.internModuleIdentity(module.moduleEnvConst().moduleIdentityHash(module.moduleEnvConst().selfModuleIdentity())),
                    @intFromEnum(default_expr_idx),
                )
            else
                .required,
        };
        out_index += 1;
    }
    return out;
}

/// Records a nominal declaration's top-level record fields in declared order.
/// Named fields refer to backing row entries by label; unnamed (`_` / `_name`)
/// fields carry their resolved type because they are layout padding, excluded
/// from the backing row.
fn declaredRecordFieldsFromDeclarationAnno(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    imports: CheckedImportViews,
    store: *CheckedTypeStore,
    active: *CheckedSourceTypeRoots,
    local_type_declarations: *const LocalTypeDeclarationIndex,
    declaration_formals: []const DeclarationFormal,
    anno_idx: CIR.TypeAnno.Idx,
) Allocator.Error![]const CheckedNominalRecordField {
    // The backing record may be wrapped in parentheses; unwrap before reading its
    // fields (mirrors the parens handling in appendCheckedTypeRootFromDeclarationAnno).
    var record_anno = anno_idx;
    const record = while (true) {
        switch (module.moduleEnvConst().store.getTypeAnno(record_anno)) {
            .parens => |parens| record_anno = parens.anno,
            .record => |record| break record,
            .apply,
            .rigid_var,
            .rigid_var_lookup,
            .underscore,
            .lookup,
            .tag_union,
            .tag,
            .tuple,
            .@"fn",
            .malformed,
            => return &.{},
        }
    };
    const fields = module.moduleEnvConst().store.sliceAnnoRecordFields(record.fields);
    if (fields.len == 0) return &.{};
    const out = try allocator.alloc(CheckedNominalRecordField, fields.len);
    errdefer allocator.free(out);
    for (fields, 0..) |field_idx, index| {
        const field = module.moduleEnvConst().store.getAnnoRecordField(field_idx);
        out[index] = if (field.is_unnamed)
            .{ .padding = try appendCheckedTypeRootFromDeclarationAnno(allocator, module, names, imports, store, active, local_type_declarations, declaration_formals, field.ty) }
        else
            .{ .named = try names.internRecordFieldIdent(module.identStoreConst(), field.name) };
    }
    return out;
}

fn paddingFieldTypesFromDeclaredRecordFields(
    allocator: Allocator,
    declared_record_fields: []const CheckedNominalRecordField,
) Allocator.Error![]const CheckedTypeId {
    var padding_count: usize = 0;
    for (declared_record_fields) |field| {
        switch (field) {
            .named => {},
            .padding => padding_count += 1,
        }
    }
    if (padding_count == 0) return &.{};

    const out = try allocator.alloc(CheckedTypeId, padding_count);
    errdefer allocator.free(out);
    var out_index: usize = 0;
    for (declared_record_fields) |field| {
        switch (field) {
            .named => {},
            .padding => |ty| {
                out[out_index] = ty;
                out_index += 1;
            },
        }
    }
    return out;
}

fn declaredFieldsFromDeclarationAnno(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    padding_field_types: []const CheckedTypeId,
    anno_idx: CIR.TypeAnno.Idx,
) Allocator.Error![]const CheckedDeclaredField {
    var record_anno = anno_idx;
    const record = while (true) {
        const anno = module.moduleEnvConst().store.getTypeAnno(record_anno);
        if (anno == .parens) {
            record_anno = anno.parens.anno;
        } else if (anno == .record) {
            break anno.record;
        } else return &.{};
    };
    const fields = module.moduleEnvConst().store.sliceAnnoRecordFields(record.fields);
    if (fields.len == 0) return &.{};

    const out = try allocator.alloc(CheckedDeclaredField, fields.len);
    errdefer allocator.free(out);
    var padding_cursor: u32 = 0;
    for (fields, 0..) |field_idx, i| {
        const field = module.moduleEnvConst().store.getAnnoRecordField(field_idx);
        out[i] = if (field.is_unnamed) blk: {
            if (padding_cursor >= padding_field_types.len) {
                checkedArtifactInvariant("nominal declaration had more unnamed fields than recorded padding types", .{});
            }
            defer padding_cursor += 1;
            break :blk .{ .padding = padding_cursor };
        } else .{
            .named = try names.internRecordFieldIdent(module.identStoreConst(), field.name),
        };
    }
    if (padding_cursor != padding_field_types.len) {
        checkedArtifactInvariant("nominal declaration recorded padding types that were missing from declared field order", .{});
    }
    return out;
}

fn checkedTagsFromDeclarationAnnoSpan(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    imports: CheckedImportViews,
    store: *CheckedTypeStore,
    active: *CheckedSourceTypeRoots,
    local_type_declarations: *const LocalTypeDeclarationIndex,
    declaration_formals: []const DeclarationFormal,
    span: CIR.TypeAnno.Span,
) Allocator.Error![]const CheckedTagBuild {
    const annos = module.moduleEnvConst().store.sliceTypeAnnos(span);
    if (annos.len == 0) return &.{};
    const out = try allocator.alloc(CheckedTagBuild, annos.len);
    for (out) |*tag| tag.* = .{ .name = undefined, .args = &.{} };
    errdefer deinitCheckedTagsBuild(allocator, out);

    for (annos, 0..) |anno_idx, i| {
        const anno = module.moduleEnvConst().store.getTypeAnno(anno_idx);
        const tag = switch (anno) {
            .tag => |tag| tag,
            .apply,
            .rigid_var,
            .rigid_var_lookup,
            .underscore,
            .lookup,
            .tag_union,
            .tuple,
            .record,
            .@"fn",
            .parens,
            .malformed,
            => checkedArtifactInvariant("nominal declaration tag union contained a non-tag annotation", .{}),
        };
        out[i] = .{
            .name = try names.internTagIdent(module.identStoreConst(), tag.name),
            .args = try checkedTypeIdsFromDeclarationAnnoSpan(
                allocator,
                module,
                names,
                imports,
                store,
                active,
                local_type_declarations,
                declaration_formals,
                tag.args,
            ),
        };
    }
    return out;
}

fn checkedTypeIdsContainIdentityVariables(
    allocator: Allocator,
    store: *const CheckedTypeStore,
    ids: []const CheckedTypeId,
) Allocator.Error!bool {
    var context = CheckedTypeIdentityScan{ .store = store };
    return try checked_traverse.checkedTypeSliceContainsIdentityVariables(
        CheckedTypeId,
        CheckedTypeIdentityScan,
        allocator,
        &context,
        ids,
    );
}

fn checkedTypeContainsIdentityVariablesPayloads(
    allocator: Allocator,
    store: *const CheckedTypeStore,
    root: CheckedTypeId,
) Allocator.Error!bool {
    var context = CheckedTypeIdentityScan{ .store = store };
    return try checked_traverse.checkedTypeContainsIdentityVariables(
        CheckedTypeId,
        CheckedTypeIdentityScan,
        allocator,
        &context,
        root,
    );
}

fn appendExplicitCheckedTypePayload(
    allocator: Allocator,
    names: *const canonical.CanonicalNameStore,
    store: *CheckedTypeStore,
    build_payload: CheckedTypePayloadBuild,
) Allocator.Error!CheckedTypeId {
    var owned_payload = build_payload;
    var payload_owned = true;
    errdefer if (payload_owned) deinitCheckedTypePayloadBuild(allocator, &owned_payload);

    const structurally_internable = !checkedTypePayloadBuildContainsIdentityVariables(store, owned_payload);
    const fingerprint = if (structurally_internable)
        checkedTypePayloadStructuralFingerprint(.checked_payload, owned_payload)
    else
        null;
    if (fingerprint) |value| {
        if (store.structuralRootForPayload(.checked_payload, value, owned_payload)) |existing| {
            deinitCheckedTypePayloadBuild(allocator, &owned_payload);
            payload_owned = false;
            return existing;
        }
    }

    const key_info = try checkedTypePayloadKeyBuild(allocator, names, store, owned_payload);
    if (!key_info.contains_identity_variables) {
        if (store.rootForKey(key_info.key)) |existing| {
            deinitCheckedTypePayloadBuild(allocator, &owned_payload);
            payload_owned = false;
            return existing;
        }
    }

    const id: CheckedTypeId = @enumFromInt(@as(u32, @intCast(store.roots.items.len)));
    try store.roots.ensureUnusedCapacity(allocator, 1);
    try store.payloads.ensureUnusedCapacity(allocator, 1);
    const stored = try store.commitPayload(allocator, owned_payload);
    payload_owned = false;
    const root = CheckedTypeRoot{
        .id = id,
        .key = key_info.key,
        .contains_identity_variables = key_info.contains_identity_variables,
    };
    store.roots.appendAssumeCapacity(root);
    store.payloads.appendAssumeCapacity(stored);
    try store.indexRoot(allocator, root);
    if (fingerprint) |value| try store.indexStructuralRoot(allocator, .checked_payload, id, value);
    return id;
}

fn appendNominalDeclarationRootPayload(
    allocator: Allocator,
    names: *const canonical.CanonicalNameStore,
    store: *CheckedTypeStore,
    build_payload: CheckedTypePayloadBuild,
) Allocator.Error!CheckedTypeId {
    var owned_payload = build_payload;
    var payload_owned = true;
    errdefer if (payload_owned) deinitCheckedTypePayloadBuild(allocator, &owned_payload);

    if (owned_payload != .nominal) {
        checkedArtifactInvariant("nominal declaration root payload was not nominal", .{});
    }
    const nominal = owned_payload.nominal;

    const key_info = try checkedTypePayloadKeyBuild(allocator, names, store, owned_payload);
    if (store.rootForKey(key_info.key)) |existing| {
        const index: usize = @intFromEnum(existing);
        if (index >= store.payloads.items.len) {
            checkedArtifactInvariant("nominal declaration root key referenced a missing payload", .{});
        }
        if (store.payloads.items[index] != .nominal) {
            checkedArtifactInvariant("nominal declaration key collided with a non-nominal payload", .{});
        }
        const existing_nominal = store.payloads.items[index].nominal;
        // The canonical key already includes the semantic formal-arg shapes.
        // The checked root ids can differ when the same nominal declaration is
        // reached through a declaration root and a use-site root.
        if (existing_nominal.name != nominal.name or
            existing_nominal.origin_module != nominal.origin_module or
            !checkedArtifactKeyEql(existing_nominal.owner_module, nominal.owner_module) or
            existing_nominal.is_opaque != nominal.is_opaque)
        {
            checkedArtifactInvariant("nominal declaration key collided with a different nominal payload", .{});
        }

        if (existing_nominal.builtin == nominal.builtin) {
            deinitCheckedTypePayloadBuild(allocator, &owned_payload);
            payload_owned = false;
            return existing;
        }

        const stored = try store.commitPayload(allocator, owned_payload);
        payload_owned = false;
        store.payloads.items[index] = stored;
        return existing;
    }

    const id: CheckedTypeId = @enumFromInt(@as(u32, @intCast(store.roots.items.len)));
    try store.roots.ensureUnusedCapacity(allocator, 1);
    try store.payloads.ensureUnusedCapacity(allocator, 1);
    const stored = try store.commitPayload(allocator, owned_payload);
    payload_owned = false;
    const root = CheckedTypeRoot{
        .id = id,
        .key = key_info.key,
        .contains_identity_variables = key_info.contains_identity_variables,
    };
    store.roots.appendAssumeCapacity(root);
    store.payloads.appendAssumeCapacity(stored);
    try store.indexRoot(allocator, root);
    return id;
}

fn checkedTypePayloadKeyBuild(
    allocator: Allocator,
    names: *const canonical.CanonicalNameStore,
    store: *const CheckedTypeStore,
    payload: CheckedTypePayloadBuild,
) Allocator.Error!canonical_type_keys.TypeKeyInfo {
    var builder = SubstitutedCheckedTypeKeyBuilder.init(allocator, names, store, &.{}, &.{});
    defer builder.deinit();
    try builder.writePayloadBuild(payload);
    return .{
        .key = .{ .bytes = builder.hasher.finalResult() },
        .contains_identity_variables = builder.identity_variables.count() != 0,
    };
}

fn appendCheckedNominalDeclarationFromPayload(
    allocator: Allocator,
    store: *CheckedTypeStore,
    root: CheckedTypeId,
    backing: CheckedTypeId,
    declared_record_fields: []const CheckedNominalRecordField,
) Allocator.Error!void {
    const declarations = &store.nominal_declarations;
    const index: usize = @intFromEnum(root);
    if (index >= store.payloads.items.len) {
        checkedArtifactInvariant("nominal declaration referenced a missing checked type root", .{});
    }
    const root_payload = store.payload(root);
    if (root_payload != .nominal) {
        checkedArtifactInvariant("nominal declaration root was not a nominal checked type", .{});
    }
    const nominal = root_payload.nominal;

    const nominal_key = canonical.NominalTypeKey{
        .module = nominal.origin_module,
        .type_name = nominal.name,
        .source_decl = nominal.source_decl,
    };
    for (declarations.items) |existing| {
        if (canonicalNominalTypeKeyEql(existing.nominal, nominal_key)) {
            if (existing.backing == backing and
                checkedTypeRootKeySliceEql(store, existing.formalArgs(store), nominal.args) and
                checkedTypeRootKeySliceEql(store, existing.paddingFieldTypes(store), nominal.padding_field_types) and
                checkedDeclaredFieldSliceEql(existing.declaredFields(store), nominal.declared_fields) and
                checkedNominalRecordFieldRootKeySliceEql(store, existing.declaredRecordFields(store), declared_record_fields))
            {
                return;
            }
            checkedArtifactInvariant("checked artifact attempted to publish conflicting nominal declarations", .{});
        }
    }

    // nominal.args / nominal.padding_field_types alias type_id_pool; copy before
    // appending into that pool (appends may reallocate and dangle the aliases).
    const args_copy = try allocator.dupe(CheckedTypeId, nominal.args);
    defer allocator.free(args_copy);
    const padding_copy = try allocator.dupe(CheckedTypeId, nominal.padding_field_types);
    defer allocator.free(padding_copy);
    const declared_copy = try allocator.dupe(CheckedDeclaredField, nominal.declared_fields);
    defer allocator.free(declared_copy);
    const fa = try store.appendTypeIds(allocator, args_copy);
    const pf = try store.appendTypeIds(allocator, padding_copy);
    const df = try store.appendDeclaredFields(allocator, declared_copy);
    const rf = try store.appendNominalRecordFields(allocator, declared_record_fields);
    try declarations.append(allocator, .{
        .id = @enumFromInt(@as(u32, @intCast(declarations.items.len))),
        .nominal = nominal_key,
        .source_statement = nominal.source_decl orelse
            checkedArtifactInvariant("checked nominal declaration payload had no source declaration", .{}),
        .declaration_root = root,
        .backing = backing,
        .fa_start = fa.start,
        .fa_len = fa.len,
        .pf_start = pf.start,
        .pf_len = pf.len,
        .df_start = df.start,
        .df_len = df.len,
        .rf_start = rf.start,
        .rf_len = rf.len,
    });
}

fn checkedTypeIdSliceEql(a: []const CheckedTypeId, b: []const CheckedTypeId) bool {
    if (a.len != b.len) return false;
    for (a, b) |left, right| {
        if (left != right) return false;
    }
    return true;
}

fn checkedDeclaredFieldSliceEql(a: []const CheckedDeclaredField, b: []const CheckedDeclaredField) bool {
    if (a.len != b.len) return false;
    for (a, b) |left, right| {
        switch (left) {
            .named => |left_name| switch (right) {
                .named => |right_name| if (left_name != right_name) return false,
                .padding => return false,
            },
            .padding => |left_index| switch (right) {
                .named => return false,
                .padding => |right_index| if (left_index != right_index) return false,
            },
        }
    }
    return true;
}

fn checkedTypeRootKeySliceEql(store: *const CheckedTypeStore, a: []const CheckedTypeId, b: []const CheckedTypeId) bool {
    if (a.len != b.len) return false;
    for (a, b) |left, right| {
        const left_index: usize = @intFromEnum(left);
        const right_index: usize = @intFromEnum(right);
        if (left_index >= store.roots.items.len or right_index >= store.roots.items.len) {
            checkedArtifactInvariant("nominal declaration compared a missing checked type root", .{});
        }
        if (!std.meta.eql(store.roots.items[left_index].key.bytes, store.roots.items[right_index].key.bytes)) return false;
    }
    return true;
}

const CheckedStructuralKeyDomain = enum {
    source,
    checked_payload,
    synthetic_function,
};

fn checkedTypePayloadStructuralFingerprint(
    domain: CheckedStructuralKeyDomain,
    payload: CheckedTypePayloadBuild,
) u64 {
    var hasher = std.hash.Wyhash.init(0x726f635f74797065);
    std.hash.autoHash(&hasher, domain);
    std.hash.autoHashStrat(&hasher, payload, .DeepRecursive);
    return hasher.final();
}

fn checkedTypePayloadBuildContainsIdentityVariables(
    store: *const CheckedTypeStore,
    payload: CheckedTypePayloadBuild,
) bool {
    return switch (payload) {
        .pending => true,
        .flex, .rigid => true,
        .err, .empty_record, .empty_tag_union => false,
        .alias => |alias| blk: {
            if (store.rootContainsIdentityVariables(alias.backing)) break :blk true;
            for (alias.args) |arg| {
                if (store.rootContainsIdentityVariables(arg)) break :blk true;
            }
            break :blk false;
        },
        .record => |record| blk: {
            for (record.fields) |field| {
                if (field.kind.undeterminedVariable()) |variable| {
                    if (store.rootContainsIdentityVariables(variable)) break :blk true;
                }
                if (store.rootContainsIdentityVariables(field.ty)) break :blk true;
            }
            break :blk store.rootContainsIdentityVariables(record.ext);
        },
        .record_unbound => |fields| blk: {
            for (fields) |field| {
                if (field.kind.undeterminedVariable()) |variable| {
                    if (store.rootContainsIdentityVariables(variable)) break :blk true;
                }
                if (store.rootContainsIdentityVariables(field.ty)) break :blk true;
            }
            break :blk false;
        },
        .tuple => |items| blk: {
            for (items) |item| {
                if (store.rootContainsIdentityVariables(item)) break :blk true;
            }
            break :blk false;
        },
        .nominal => |nominal| blk: {
            for (nominal.args) |arg| {
                if (store.rootContainsIdentityVariables(arg)) break :blk true;
            }
            for (nominal.padding_field_types) |padding| {
                if (store.rootContainsIdentityVariables(padding)) break :blk true;
            }
            break :blk false;
        },
        .function => |function| blk: {
            for (function.args) |arg| {
                if (store.rootContainsIdentityVariables(arg)) break :blk true;
            }
            break :blk store.rootContainsIdentityVariables(function.ret);
        },
        .tag_union => |tag_union| blk: {
            for (tag_union.tags) |tag| {
                for (tag.args) |arg| {
                    if (store.rootContainsIdentityVariables(arg)) break :blk true;
                }
            }
            break :blk store.rootContainsIdentityVariables(tag_union.ext);
        },
    };
}

fn checkedRecordFieldSliceEql(a: []const CheckedRecordField, b: []const CheckedRecordField) bool {
    if (a.len != b.len) return false;
    for (a, b) |left, right| {
        if (left.name != right.name or left.ty != right.ty or !std.meta.eql(left.kind, right.kind)) return false;
    }
    return true;
}

fn checkedTagBuildSliceEqlStored(
    build_tags: []const CheckedTagBuild,
    stored_tags: []const CheckedTag,
    store: *const CheckedTypeStore,
) bool {
    if (build_tags.len != stored_tags.len) return false;
    for (build_tags, stored_tags) |build_tag, stored_tag| {
        if (build_tag.name != stored_tag.name or
            !checkedTypeIdSliceEql(build_tag.args, stored_tag.argsSlice(store)))
        {
            return false;
        }
    }
    return true;
}

fn checkedTypePayloadBuildEqlStored(
    build: CheckedTypePayloadBuild,
    stored: CheckedTypePayload,
    store: *const CheckedTypeStore,
) bool {
    return switch (build) {
        .pending => stored == .pending,
        .err => stored == .err,
        .empty_record => stored == .empty_record,
        .empty_tag_union => stored == .empty_tag_union,
        .flex, .rigid => checkedArtifactInvariant(
            "identity-bearing payload reached the closed structural interner",
            .{},
        ),
        .alias => |left| blk: {
            if (stored != .alias) break :blk false;
            const right = stored.alias;
            break :blk left.name == right.name and
                left.origin_module == right.origin_module and
                checkedArtifactKeyEql(left.owner_module, right.owner_module) and
                left.source_decl == right.source_decl and
                left.builtin_origin == right.builtin_origin and
                left.backing == right.backing and
                checkedTypeIdSliceEql(left.args, right.args);
        },
        .record => |left| blk: {
            if (stored != .record) break :blk false;
            const right = stored.record;
            break :blk left.ext == right.ext and checkedRecordFieldSliceEql(left.fields, right.fields);
        },
        .record_unbound => |left| blk: {
            if (stored != .record_unbound) break :blk false;
            break :blk checkedRecordFieldSliceEql(left, stored.record_unbound);
        },
        .tuple => |left| blk: {
            if (stored != .tuple) break :blk false;
            break :blk checkedTypeIdSliceEql(left, stored.tuple);
        },
        .nominal => |left| blk: {
            if (stored != .nominal) break :blk false;
            const right = stored.nominal;
            break :blk left.name == right.name and
                left.origin_module == right.origin_module and
                checkedArtifactKeyEql(left.owner_module, right.owner_module) and
                left.source_decl == right.source_decl and
                left.builtin == right.builtin and
                left.is_opaque == right.is_opaque and
                std.meta.eql(left.representation, right.representation) and
                checkedTypeIdSliceEql(left.args, right.args) and
                checkedTypeIdSliceEql(left.padding_field_types, right.padding_field_types);
        },
        .function => |left| blk: {
            if (stored != .function) break :blk false;
            const right = stored.function;
            break :blk finalizedFunctionKind(left.kind) == finalizedFunctionKind(right.kind) and
                left.ret == right.ret and
                checkedTypeIdSliceEql(left.args, right.args);
        },
        .tag_union => |left| blk: {
            if (stored != .tag_union) break :blk false;
            const right = stored.tag_union;
            break :blk left.ext == right.ext and
                checkedTagBuildSliceEqlStored(left.tags, right.tags, store);
        },
    };
}

fn checkedNominalRecordFieldRootKeySliceEql(
    store: *const CheckedTypeStore,
    a: []const CheckedNominalRecordField,
    b: []const CheckedNominalRecordField,
) bool {
    if (a.len != b.len) return false;
    for (a, b) |left, right| {
        switch (left) {
            .named => |left_name| switch (right) {
                .named => |right_name| if (left_name != right_name) return false,
                .padding => return false,
            },
            .padding => |left_ty| switch (right) {
                .named => return false,
                .padding => |right_ty| if (!checkedTypeRootKeySliceEql(store, &.{left_ty}, &.{right_ty})) return false,
            },
        }
    }
    return true;
}

const OwnerNominalDecl = struct {
    view: ImportedModuleView,
    decl: CheckedNominalDeclaration,
};

fn importedViewForKey(imports: CheckedImportViews, key: CheckedModuleArtifactKey) ?ImportedModuleView {
    for (imports.direct) |import| {
        if (checkedArtifactKeyEql(import.key, key)) return import.view;
    }
    for (imports.available) |view| {
        if (checkedArtifactKeyEql(view.key, key)) return view;
    }
    for (imports.relations) |view| {
        if (checkedArtifactKeyEql(view.key, key)) return view;
    }
    return null;
}

/// Find the imported artifact view + declaration for a nominal using the
/// explicit representation carried by the payload. Missing declaration-backed
/// owners are producer bugs: a published artifact must be self-contained.
fn ownerViewAndDeclForImportedNominal(
    imports: CheckedImportViews,
    owner_module: ModuleId,
    source_decl: ?u32,
    representation: CheckedNominalRepresentationRef,
) ?OwnerNominalDecl {
    return switch (representation) {
        .builtin => blk: {
            const view = importedViewForKey(imports, owner_module) orelse return null;
            const source_statement = source_decl orelse return null;
            for (view.checked_types.nominal_declarations) |declaration| {
                if (declaration.source_statement != source_statement) continue;
                break :blk .{ .view = view, .decl = declaration };
            }
            break :blk null;
        },
        .imported_declaration => |imported| blk: {
            const view = importedViewForKey(imports, imported.artifact) orelse return null;
            break :blk .{ .view = view, .decl = view.checked_types.nominalDeclarationById(imported.declaration) };
        },
        .imported_box_payload_capability => |capability_ref| blk: {
            const view = importedViewForKey(imports, capability_ref.artifact) orelse return null;
            const capability = view.interface_capabilities.boxPayloadCapability(capability_ref.capability);
            const decl = view.checked_types.nominalDeclaration(capability.nominal) orelse
                checkedArtifactInvariant("imported box payload capability referenced missing nominal declaration", .{});
            break :blk .{ .view = view, .decl = decl };
        },
        .local_declaration,
        .local_box_payload_capability,
        .opaque_without_backing,
        => null,
    };
}

/// Project one imported nominal declaration (its declaration-root nominal
/// payload, backing template, formals, declared record fields, and padding)
/// from its owner view into `store`, and register it in the local declaration
/// table. `appendCheckedNominalDeclarationFromPayload` deduplicates by content
/// key and asserts equal-key-equal-content, so a redundant call is a no-op.
fn embedOneImportedNominalDecl(
    allocator: Allocator,
    store: *CheckedTypeStore,
    names: *canonical.CanonicalNameStore,
    owner_view: ImportedModuleView,
    owner_decl: CheckedNominalDeclaration,
) Allocator.Error!void {
    var projector = CheckedTypeStoreImportProjector.init(allocator, store, names, owner_view);
    defer projector.deinit();

    const local_root = try projector.project(owner_decl.declaration_root);

    const owner_fields = owner_decl.declaredRecordFields(&owner_view.checked_types);
    const local_fields = if (owner_fields.len == 0) &[_]CheckedNominalRecordField{} else blk: {
        const out = try allocator.alloc(CheckedNominalRecordField, owner_fields.len);
        errdefer allocator.free(out);
        for (owner_fields, out) |owner_field, *local_field| {
            local_field.* = switch (owner_field) {
                .named => |label| .{ .named = try projector.remapRecordField(label) },
                .padding => |ty| .{ .padding = try projector.project(ty) },
            };
        }
        break :blk out;
    };
    defer if (local_fields.len != 0) allocator.free(local_fields);

    const local_backing = try projector.project(owner_decl.backing);
    try appendCheckedNominalDeclarationFromPayload(allocator, store, local_root, local_backing, local_fields);
}

/// Ensure the artifact's declaration table holds a copy of every IMPORTED
/// nominal declaration reachable from the published checked types (see the
/// call site in `fromModule` for why). Fixpoint over `store.payloads`:
/// projecting a backing can surface further imported nominals (e.g. an opaque
/// whose backing uses `List`); those are appended and scanned in turn, so a
/// single forward scan that re-reads the length reaches the transitive closure.
fn embedReachableImportedNominalDecls(
    allocator: Allocator,
    store: *CheckedTypeStore,
    names: *canonical.CanonicalNameStore,
    imports: CheckedImportViews,
) Allocator.Error!void {
    var i: usize = 0;
    while (i < store.payloads.items.len) : (i += 1) {
        // Read only scalar identity fields: the payload's slice fields alias
        // pools that projection below can reallocate.
        const payload = store.payloads.items[i];
        if (payload != .nominal) continue;
        const nominal = payload.nominal;
        const origin_module = nominal.origin_module;
        const owner_module = nominal.owner_module;
        const type_name = nominal.name;
        const source_decl = nominal.source_decl;
        const builtin_nominal = nominal.builtin;
        const representation = nominal.representation;

        const key = canonical.NominalTypeKey{
            .module = origin_module,
            .type_name = type_name,
            .source_decl = source_decl,
        };
        // Already declared locally (this module's own declaration) or already
        // embedded on an earlier iteration.
        if (store.nominalDeclaration(key) != null) continue;

        const owner = ownerViewAndDeclForImportedNominal(imports, owner_module, source_decl, representation) orelse
            switch (representation) {
                .opaque_without_backing => continue,
                .builtin => {
                    if (builtin_nominal) |builtin_decl| {
                        if (!builtinNominalHasDeclarationBacking(builtin_decl)) continue;
                    }
                    checkedArtifactInvariant("checked type publication could not embed reachable builtin nominal declaration", .{});
                },
                .local_declaration,
                .local_box_payload_capability,
                => checkedArtifactInvariant("checked type publication had local nominal payload without local declaration", .{}),
                .imported_declaration,
                .imported_box_payload_capability,
                => checkedArtifactInvariant("checked type publication could not embed reachable imported nominal declaration", .{}),
            };

        try embedOneImportedNominalDecl(allocator, store, names, owner.view, owner.decl);
    }
}

fn substitutedCheckedTypeKey(
    allocator: Allocator,
    names: *const canonical.CanonicalNameStore,
    store: *const CheckedTypeStore,
    source: CheckedTypeId,
    formals: []const CheckedTypeId,
    actuals: []const CheckedTypeId,
) Allocator.Error!canonical.CanonicalTypeKey {
    return (try substitutedCheckedTypeKeyInfo(allocator, names, store, source, formals, actuals)).key;
}

fn substitutedCheckedTypeKeyInfo(
    allocator: Allocator,
    names: *const canonical.CanonicalNameStore,
    store: *const CheckedTypeStore,
    source: CheckedTypeId,
    formals: []const CheckedTypeId,
    actuals: []const CheckedTypeId,
) Allocator.Error!canonical_type_keys.TypeKeyInfo {
    if (formals.len != actuals.len) {
        checkedArtifactInvariant("checked type substitution key arity mismatch", .{});
    }

    var builder = SubstitutedCheckedTypeKeyBuilder.init(allocator, names, store, formals, actuals);
    defer builder.deinit();
    try builder.writeType(source);
    return .{
        .key = .{ .bytes = builder.hasher.finalResult() },
        .contains_identity_variables = builder.identity_variables.count() != 0,
    };
}

const SubstitutedCheckedTypeKeyBuilder = struct {
    allocator: Allocator,
    names: *const canonical.CanonicalNameStore,
    store: *const CheckedTypeStore,
    formals: []const CheckedTypeId,
    actuals: []const CheckedTypeId,
    hasher: std.crypto.hash.sha2.Sha256,
    active: collections.DenseMap(CheckedTypeId, u32),
    identity_variables: collections.DenseMap(CheckedTypeId, u32),

    const RecordFieldForKey = struct {
        name: canonical.RecordFieldLabelId,
        ty: CheckedTypeId,
        kind: CheckedFieldKind,
    };

    const TagForKey = struct {
        name: canonical.TagLabelId,
        args: []const CheckedTypeId,
    };

    fn init(
        allocator: Allocator,
        names: *const canonical.CanonicalNameStore,
        store: *const CheckedTypeStore,
        formals: []const CheckedTypeId,
        actuals: []const CheckedTypeId,
    ) SubstitutedCheckedTypeKeyBuilder {
        return .{
            .allocator = allocator,
            .names = names,
            .store = store,
            .formals = formals,
            .actuals = actuals,
            .hasher = std.crypto.hash.sha2.Sha256.init(.{}),
            .active = collections.DenseMap(CheckedTypeId, u32).init(allocator),
            .identity_variables = collections.DenseMap(CheckedTypeId, u32).init(allocator),
        };
    }

    fn deinit(self: *SubstitutedCheckedTypeKeyBuilder) void {
        self.identity_variables.deinit();
        self.active.deinit();
    }

    fn substitutedRoot(self: *const SubstitutedCheckedTypeKeyBuilder, source: CheckedTypeId) CheckedTypeId {
        for (self.formals, self.actuals) |formal, actual| {
            if (source == formal and source != actual) return actual;
        }
        return source;
    }

    fn writeType(self: *SubstitutedCheckedTypeKeyBuilder, source: CheckedTypeId) Allocator.Error!void {
        const id = self.substitutedRoot(source);
        const raw: usize = @intFromEnum(id);
        if (raw >= self.store.payloadCount()) {
            checkedArtifactInvariant("checked type substitution key referenced missing payload {d} with {d} payloads", .{ raw, self.store.payloadCount() });
        }

        switch (self.store.payload(@enumFromInt(raw))) {
            .flex => |flex| return try self.writeIdentityVariable(id, "flex", flex.name, flex.constraints),
            .rigid => |rigid| return try self.writeIdentityVariable(id, "rigid", rigid.name, rigid.constraints),
            .pending,
            .err,
            .alias,
            .record,
            .record_unbound,
            .tuple,
            .nominal,
            .function,
            .empty_record,
            .tag_union,
            .empty_tag_union,
            => {},
        }

        if (self.active.get(id)) |slot| {
            self.writeTag("cycle");
            self.writeU32(slot);
            return;
        }

        const slot: u32 = @intCast(self.active.count());
        try self.active.put(id, slot);
        try self.writePayload(self.store.payload(@enumFromInt(raw)));
        _ = self.active.remove(id);
    }

    fn writeIdentityVariable(
        self: *SubstitutedCheckedTypeKeyBuilder,
        root: CheckedTypeId,
        comptime tag: []const u8,
        name: ?[]const u8,
        constraints: []const CheckedStaticDispatchConstraint,
    ) Allocator.Error!void {
        if (self.identity_variables.get(root)) |slot| {
            self.writeTag("identity_var_ref");
            self.writeU32(slot);
            return;
        }

        const slot: u32 = @intCast(self.identity_variables.count());
        try self.identity_variables.put(root, slot);
        self.writeTag(tag);
        self.writeU32(@intFromEnum(root));
        self.writeU32(slot);
        self.writeBool(name != null);
        if (name) |text| self.writeBytes(text);
        try self.writeConstraints(constraints);
    }

    fn writePayload(self: *SubstitutedCheckedTypeKeyBuilder, payload: CheckedTypePayload) Allocator.Error!void {
        switch (payload) {
            .pending => checkedArtifactInvariant("checked type substitution key reached pending payload", .{}),
            .err => self.writeTag("err"),
            .flex,
            .rigid,
            => checkedArtifactInvariant("checked type substitution key reached identity payload without root identity", .{}),
            .alias => |alias| {
                self.writeTag("alias");
                self.writeNamedSourceIdentity(alias.origin_module, alias.name, alias.source_decl);
                self.writeCheckedModuleOwner(alias.owner_module);
                try self.writeType(alias.backing);
                self.writeU32(@intCast(alias.args.len));
                for (alias.args) |arg| try self.writeType(arg);
            },
            .record_unbound => |fields| {
                self.writeTag("record_unbound");
                try self.writeNormalizedRecordFields(fields, null);
            },
            .record => |record| try self.writeNormalizedRecordPayload(record.fields, record.ext),
            .tuple => |tuple| {
                self.writeTag("tuple");
                self.writeU32(@intCast(tuple.len));
                for (tuple) |elem| try self.writeType(elem);
            },
            .nominal => |nominal| {
                self.writeTag("nominal");
                self.writeNamedSourceIdentity(nominal.origin_module, nominal.name, nominal.source_decl);
                self.writeCheckedModuleOwner(nominal.owner_module);
                self.writeBool(nominal.is_opaque);
                self.writeU32(@intCast(nominal.args.len));
                for (nominal.args) |arg| try self.writeType(arg);
                self.writeU32(@intCast(nominal.padding_field_types.len));
                for (nominal.padding_field_types) |padding_type| try self.writeType(padding_type);
                self.writeDeclaredFields(nominal.declared_fields);
            },
            .function => |func| {
                switch (finalizedFunctionKind(func.kind)) {
                    .pure => self.writeTag("fn_pure"),
                    .effectful => self.writeTag("fn_effectful"),
                    .unbound => unreachable,
                }
                self.writeBool(try self.typeSliceContainsIdentityVariables(func.args) or
                    try self.typeContainsIdentityVariables(func.ret));
                self.writeU32(@intCast(func.args.len));
                for (func.args) |arg| try self.writeType(arg);
                try self.writeType(func.ret);
            },
            .empty_record => self.writeTag("empty_record"),
            .tag_union => |tag_union| try self.writeNormalizedTagUnionPayload(tag_union.tags, tag_union.ext),
            .empty_tag_union => self.writeTag("[]"),
        }
    }

    /// Like `writePayload`, but for a build-form payload (uncommitted, with
    /// build-form tags). Produces identical key bytes; only `tag_union` differs.
    fn writePayloadBuild(self: *SubstitutedCheckedTypeKeyBuilder, payload: CheckedTypePayloadBuild) Allocator.Error!void {
        switch (payload) {
            .tag_union => |tag_union| {
                var tags = std.ArrayList(TagForKey).empty;
                defer tags.deinit(self.allocator);
                for (tag_union.tags) |tag| {
                    try tags.append(self.allocator, .{ .name = tag.name, .args = tag.args });
                }
                try self.writeNormalizedTagUnionFromHead(tags.items, tag_union.ext);
            },
            inline .pending,
            .err,
            .flex,
            .rigid,
            .alias,
            .record,
            .record_unbound,
            .tuple,
            .nominal,
            .function,
            .empty_record,
            .empty_tag_union,
            => |inner, tag| try self.writePayload(@unionInit(CheckedTypePayload, @tagName(tag), inner)),
        }
    }

    fn appendRecordFieldsForKey(
        self: *SubstitutedCheckedTypeKeyBuilder,
        fields: *std.ArrayList(RecordFieldForKey),
        source: []const CheckedRecordField,
    ) Allocator.Error!void {
        for (source) |field| {
            try fields.append(self.allocator, .{
                .name = field.name,
                .ty = self.substitutedRoot(field.ty),
                .kind = if (field.kind.undeterminedVariable()) |variable|
                    .undetermined(self.substitutedRoot(variable))
                else
                    field.kind,
            });
        }
    }

    fn writeNormalizedRecordFields(
        self: *SubstitutedCheckedTypeKeyBuilder,
        head: []const CheckedRecordField,
        ext: ?CheckedTypeId,
    ) Allocator.Error!void {
        var fields = std.ArrayList(RecordFieldForKey).empty;
        defer fields.deinit(self.allocator);
        try self.appendRecordFieldsForKey(&fields, head);

        var tail = if (ext) |tail_id| self.substitutedRoot(tail_id) else null;
        var seen = collections.DenseMap(CheckedTypeId, void).init(self.allocator);
        defer seen.deinit();
        while (tail) |tail_id| {
            if (self.active.contains(tail_id)) break;
            if (seen.contains(tail_id)) break;
            try seen.put(tail_id, {});
            const raw: usize = @intFromEnum(tail_id);
            if (raw >= self.store.payloadCount()) {
                checkedArtifactInvariant("checked type substitution key row normalization referenced missing record tail", .{});
            }
            switch (self.store.payload(@enumFromInt(raw))) {
                .empty_record => {
                    tail = null;
                    break;
                },
                .record => |record| {
                    try self.appendRecordFieldsForKey(&fields, record.fields);
                    tail = self.substitutedRoot(record.ext);
                },
                .record_unbound => |record_fields| {
                    try self.appendRecordFieldsForKey(&fields, record_fields);
                    tail = null;
                },
                .pending,
                .err,
                .flex,
                .rigid,
                .alias,
                .tuple,
                .nominal,
                .function,
                .tag_union,
                .empty_tag_union,
                => break,
            }
        }

        std.mem.sort(RecordFieldForKey, fields.items, self, recordFieldForKeyLessThan);
        self.writeU32(@intCast(fields.items.len));
        for (fields.items, 0..) |field, index| {
            if (index > 0 and self.names.recordFieldLabelTextEql(fields.items[index - 1].name, field.name)) {
                checkedArtifactInvariant("checked type substitution key row normalization found duplicate record fields", .{});
            }
            self.writeBytes(self.names.recordFieldLabelText(field.name));
            try self.writeCheckedFieldKind(field.kind);
            try self.writeType(field.ty);
        }
        if (tail) |tail_id| {
            try self.writeType(tail_id);
        } else {
            self.writeTag("empty_record");
        }
    }

    fn writeNormalizedRecordPayload(
        self: *SubstitutedCheckedTypeKeyBuilder,
        head: []const CheckedRecordField,
        ext: CheckedTypeId,
    ) Allocator.Error!void {
        var fields = std.ArrayList(RecordFieldForKey).empty;
        defer fields.deinit(self.allocator);
        try self.appendRecordFieldsForKey(&fields, head);

        var tail: ?CheckedTypeId = self.substitutedRoot(ext);
        var seen = collections.DenseMap(CheckedTypeId, void).init(self.allocator);
        defer seen.deinit();
        while (tail) |tail_id| {
            if (self.active.contains(tail_id)) break;
            if (seen.contains(tail_id)) break;
            try seen.put(tail_id, {});
            const raw: usize = @intFromEnum(tail_id);
            if (raw >= self.store.payloadCount()) {
                checkedArtifactInvariant("checked type substitution key row normalization referenced missing record tail", .{});
            }
            switch (self.store.payload(@enumFromInt(raw))) {
                .empty_record => {
                    tail = null;
                    break;
                },
                .record => |record| {
                    try self.appendRecordFieldsForKey(&fields, record.fields);
                    tail = self.substitutedRoot(record.ext);
                },
                .record_unbound => |record_fields| {
                    try self.appendRecordFieldsForKey(&fields, record_fields);
                    tail = null;
                },
                .pending,
                .err,
                .flex,
                .rigid,
                .alias,
                .tuple,
                .nominal,
                .function,
                .tag_union,
                .empty_tag_union,
                => break,
            }
        }

        std.mem.sort(RecordFieldForKey, fields.items, self, recordFieldForKeyLessThan);
        if (tail == null and fields.items.len == 0) {
            self.writeTag("empty_record");
            return;
        }

        self.writeTag("record");
        self.writeU32(@intCast(fields.items.len));
        for (fields.items, 0..) |field, index| {
            if (index > 0 and self.names.recordFieldLabelTextEql(fields.items[index - 1].name, field.name)) {
                checkedArtifactInvariant("checked type substitution key row normalization found duplicate record fields", .{});
            }
            self.writeBytes(self.names.recordFieldLabelText(field.name));
            try self.writeCheckedFieldKind(field.kind);
            try self.writeType(field.ty);
        }
        if (tail) |tail_id| {
            try self.writeType(tail_id);
        } else {
            self.writeTag("empty_record");
        }
    }

    fn appendTagsForKey(
        self: *SubstitutedCheckedTypeKeyBuilder,
        tags: *std.ArrayList(TagForKey),
        source: []const CheckedTag,
    ) Allocator.Error!void {
        for (source) |tag| {
            try tags.append(self.allocator, .{
                .name = tag.name,
                .args = tag.argsSlice(self.store),
            });
        }
    }

    fn writeNormalizedTagUnionPayload(
        self: *SubstitutedCheckedTypeKeyBuilder,
        head: []const CheckedTag,
        ext: CheckedTypeId,
    ) Allocator.Error!void {
        var head_tags = std.ArrayList(TagForKey).empty;
        defer head_tags.deinit(self.allocator);
        try self.appendTagsForKey(&head_tags, head);
        try self.writeNormalizedTagUnionFromHead(head_tags.items, ext);
    }

    fn writeNormalizedTagUnionFromHead(
        self: *SubstitutedCheckedTypeKeyBuilder,
        head: []const TagForKey,
        ext: CheckedTypeId,
    ) Allocator.Error!void {
        var tags = std.ArrayList(TagForKey).empty;
        defer tags.deinit(self.allocator);
        try tags.appendSlice(self.allocator, head);

        var tail: ?CheckedTypeId = self.substitutedRoot(ext);
        var seen = collections.DenseMap(CheckedTypeId, void).init(self.allocator);
        defer seen.deinit();
        while (tail) |tail_id| {
            if (self.active.contains(tail_id)) break;
            if (seen.contains(tail_id)) break;
            try seen.put(tail_id, {});
            const raw: usize = @intFromEnum(tail_id);
            if (raw >= self.store.payloadCount()) {
                checkedArtifactInvariant("checked type substitution key row normalization referenced missing tag tail", .{});
            }
            switch (self.store.payload(@enumFromInt(raw))) {
                .empty_tag_union => {
                    tail = null;
                    break;
                },
                .tag_union => |tag_union| {
                    try self.appendTagsForKey(&tags, tag_union.tags);
                    tail = self.substitutedRoot(tag_union.ext);
                },
                .pending,
                .err,
                .flex,
                .rigid,
                .alias,
                .record,
                .record_unbound,
                .tuple,
                .nominal,
                .function,
                .empty_record,
                => break,
            }
        }

        std.mem.sort(TagForKey, tags.items, self, tagForKeyLessThan);
        if (tail == null and tags.items.len == 0) {
            self.writeTag("[]");
            return;
        }

        self.writeTag("tag_union");
        self.writeU32(@intCast(tags.items.len));
        for (tags.items, 0..) |tag, index| {
            if (index > 0 and self.names.tagLabelTextEql(tags.items[index - 1].name, tag.name)) {
                checkedArtifactInvariant("checked type substitution key row normalization found duplicate tags", .{});
            }
            self.writeBytes(self.names.tagLabelText(tag.name));
            self.writeU32(@intCast(tag.args.len));
            for (tag.args) |arg| try self.writeType(arg);
        }
        if (tail) |tail_id| {
            try self.writeType(tail_id);
        } else {
            self.writeTag("[]");
        }
    }

    fn typeSliceContainsIdentityVariables(
        self: *SubstitutedCheckedTypeKeyBuilder,
        roots: []const CheckedTypeId,
    ) Allocator.Error!bool {
        var context = SubstitutedCheckedTypeIdentityScan{ .builder = self };
        return try checked_traverse.checkedTypeSliceContainsIdentityVariables(
            CheckedTypeId,
            SubstitutedCheckedTypeIdentityScan,
            self.allocator,
            &context,
            roots,
        );
    }

    fn typeContainsIdentityVariables(
        self: *SubstitutedCheckedTypeKeyBuilder,
        root: CheckedTypeId,
    ) Allocator.Error!bool {
        var context = SubstitutedCheckedTypeIdentityScan{ .builder = self };
        return try checked_traverse.checkedTypeContainsIdentityVariables(
            CheckedTypeId,
            SubstitutedCheckedTypeIdentityScan,
            self.allocator,
            &context,
            root,
        );
    }

    fn recordFieldForKeyLessThan(self: *SubstitutedCheckedTypeKeyBuilder, lhs: RecordFieldForKey, rhs: RecordFieldForKey) bool {
        return self.names.recordFieldLabelTextLessThan(lhs.name, rhs.name);
    }

    fn tagForKeyLessThan(self: *SubstitutedCheckedTypeKeyBuilder, lhs: TagForKey, rhs: TagForKey) bool {
        return self.names.tagLabelTextLessThan(lhs.name, rhs.name);
    }

    fn writeConstraints(
        self: *SubstitutedCheckedTypeKeyBuilder,
        constraints: []const CheckedStaticDispatchConstraint,
    ) Allocator.Error!void {
        self.writeU32(@intCast(constraints.len));
        for (constraints) |constraint| {
            self.writeBytes(self.names.methodNameText(constraint.fn_name));
            try self.writeType(constraint.fn_ty);
            self.writeTag(@tagName(constraint.origin));
            self.writeBool(constraint.binopNegated());
            const maybe_num_literal = constraint.numeralInfo();
            self.writeBool(maybe_num_literal != null);
            if (maybe_num_literal) |num_literal| {
                self.hasher.update(&num_literal.keyBytes());
            }
        }
    }

    fn writeDeclaredFields(
        self: *SubstitutedCheckedTypeKeyBuilder,
        fields: []const CheckedDeclaredField,
    ) void {
        self.writeU32(@intCast(fields.len));
        for (fields) |field| {
            switch (field) {
                .named => |name| {
                    self.writeTag("named");
                    self.writeBytes(self.names.recordFieldLabelText(name));
                },
                .padding => |index| {
                    self.writeTag("padding");
                    self.writeU32(index);
                },
            }
        }
    }

    fn writeTag(self: *SubstitutedCheckedTypeKeyBuilder, tag: []const u8) void {
        self.writeBytes(tag);
    }

    fn writeBytes(self: *SubstitutedCheckedTypeKeyBuilder, bytes: []const u8) void {
        self.writeU32(@intCast(bytes.len));
        self.hasher.update(bytes);
    }

    fn writeBool(self: *SubstitutedCheckedTypeKeyBuilder, value: bool) void {
        const byte: u8 = if (value) 1 else 0;
        self.hasher.update(std.mem.asBytes(&byte));
    }

    fn writeCheckedFieldKind(
        self: *SubstitutedCheckedTypeKeyBuilder,
        kind: CheckedFieldKind,
    ) Allocator.Error!void {
        // Keep this byte-for-byte aligned with canonical_type_keys.zig's
        // `writeFieldPresenceForKey`.
        switch (kind.tag) {
            .required => self.writeBool(false),
            .optional => self.writeTag("presence_optional_field"),
            .defaulted => {
                const origin_module = kind.default.origin() orelse
                    checkedArtifactInvariant("checked defaulted field kind carried no default identity", .{});
                self.writeTag("field_default");
                self.writeBytes(self.names.moduleIdentityBytes(origin_module));
                self.writeU32(kind.default.expr_node);
            },
            .undetermined => {
                const variable = kind.undeterminedVariable() orelse
                    checkedArtifactInvariant("checked undetermined field kind carried no variable identity", .{});
                self.writeTag("presence_variable");
                try self.writeType(variable);
            },
            .err => self.writeTag("err"),
        }
    }

    fn writeOptionalU32(self: *SubstitutedCheckedTypeKeyBuilder, value: ?u32) void {
        self.writeBool(value != null);
        if (value) |v| self.writeU32(v);
    }

    fn writeNamedSourceIdentity(self: *SubstitutedCheckedTypeKeyBuilder, origin_module: canonical.ModuleIdentityId, name: canonical.TypeNameId, source_decl: ?u32) void {
        self.writeBytes(self.names.moduleIdentityBytes(origin_module));
        self.writeOptionalU32(source_decl);
        if (source_decl == null) {
            self.writeBytes(self.names.typeNameText(name));
        }
    }

    fn writeCheckedModuleOwner(self: *SubstitutedCheckedTypeKeyBuilder, owner_module: ModuleId) void {
        self.writeBytes(owner_module.bytes[0..]);
    }

    fn writeU32(self: *SubstitutedCheckedTypeKeyBuilder, value: u32) void {
        self.hasher.update(&.{
            @as(u8, @truncate(value)),
            @as(u8, @truncate(value >> 8)),
            @as(u8, @truncate(value >> 16)),
            @as(u8, @truncate(value >> 24)),
        });
    }
};

const SubstitutedCheckedTypeIdentityScan = struct {
    builder: *SubstitutedCheckedTypeKeyBuilder,

    pub fn visit(
        self: *@This(),
        traversal: anytype,
        source: CheckedTypeId,
    ) Allocator.Error!bool {
        const id = self.builder.substitutedRoot(source);
        if (id != source) return try traversal.visit(id);

        const raw: usize = @intFromEnum(id);
        if (raw >= self.builder.store.payloadCount()) {
            checkedArtifactInvariant("checked type substitution key identity scan referenced missing payload", .{});
        }
        return try checked_traverse.checkedTypePayloadContainsIdentityVariables(
            .forbid,
            traversal,
            self.builder.store,
            id,
            self.builder.store.payload(@enumFromInt(raw)),
            self,
        );
    }
};

/// The identity payload nodes (flex/rigid) reachable from `root`, in the exact
/// first-encounter order `SubstitutedCheckedTypeKeyBuilder` assigns them
/// canonical slots. The index in the returned slice IS that slot, so it pairs
/// with the app-recorded identity solution at the same slot: the checked-type
/// key digest and the solver-var key digest enumerate identities identically.
/// Traversal reuses the key builder itself, so the ordering is shared by
/// construction rather than mirrored by hand. Caller owns the returned slice.
fn collectCheckedIdentityRootsInKeyOrder(
    allocator: Allocator,
    store: *const CheckedTypeStore,
    names: *const canonical.CanonicalNameStore,
    root: CheckedTypeId,
) Allocator.Error![]CheckedTypeId {
    var builder = SubstitutedCheckedTypeKeyBuilder.init(allocator, names, store, &.{}, &.{});
    defer builder.deinit();
    try builder.writeType(root);

    const roots = try allocator.alloc(CheckedTypeId, builder.identity_variables.count());
    errdefer allocator.free(roots);
    var it = builder.identity_variables.iterator();
    while (it.next()) |entry| {
        roots[entry.value_ptr.*] = entry.key_ptr.*;
    }
    return roots;
}

fn appendStaticDispatchTypeRoots(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    imports: CheckedImportViews,
    source_nodes: *const CheckedSourceNodes,
    store: *CheckedTypeStore,
    active: *CheckedSourceTypeRoots,
) Allocator.Error!void {
    var node_idx: u32 = 0;
    while (node_idx < module.nodeCount()) : (node_idx += 1) {
        const tag = module.nodeTag(@enumFromInt(node_idx));
        if (tag != .expr_dispatch_call and
            tag != .expr_interpolation and
            tag != .expr_type_dispatch_call and
            tag != .expr_method_eq) continue;

        const expr_idx: CIR.Expr.Idx = @enumFromInt(node_idx);
        if (!source_nodes.hasExpr(expr_idx)) continue;
        const expr = module.expr(expr_idx);
        switch (expr.data) {
            .e_dispatch_call => |dispatch_call| {
                _ = try appendCheckedTypeRoot(allocator, module, names, imports, store, active, module.exprType(dispatch_call.receiver));
                _ = try appendCheckedTypeRoot(allocator, module, names, imports, store, active, dispatch_call.constraint_fn_var);
            },
            .e_interpolation => |interpolation| {
                _ = try appendCheckedTypeRoot(allocator, module, names, imports, store, active, module.exprType(expr_idx));
                _ = try appendCheckedTypeRoot(
                    allocator,
                    module,
                    names,
                    imports,
                    store,
                    active,
                    interpolation.dispatcher_var orelse checkedArtifactInvariant("checked interpolation expression had no static dispatch dispatcher type", .{}),
                );
                _ = try appendCheckedTypeRoot(
                    allocator,
                    module,
                    names,
                    imports,
                    store,
                    active,
                    interpolation.constraint_fn_var orelse checkedArtifactInvariant("checked interpolation expression had no static dispatch constraint type", .{}),
                );
                _ = try appendCheckedTypeRoot(
                    allocator,
                    module,
                    names,
                    imports,
                    store,
                    active,
                    interpolation.step_fn_var orelse checkedArtifactInvariant("checked interpolation expression had no generated step function type", .{}),
                );
            },
            .e_type_dispatch_call => |dispatch_call| {
                _ = try appendCheckedTypeRoot(allocator, module, names, imports, store, active, typeDispatchOwnerVar(module, dispatch_call.type_dispatch_stmt));
                _ = try appendCheckedTypeRoot(allocator, module, names, imports, store, active, dispatch_call.constraint_fn_var);
            },
            .e_method_eq => |eq| {
                _ = try appendCheckedTypeRoot(allocator, module, names, imports, store, active, module.exprType(eq.lhs));
                _ = try appendCheckedTypeRoot(allocator, module, names, imports, store, active, eq.constraint_fn_var);
            },
            .e_num,
            .e_frac_f32,
            .e_frac_f64,
            .e_dec,
            .e_dec_small,
            .e_num_from_numeral,
            .e_typed_int,
            .e_typed_frac,
            .e_typed_num_from_numeral,
            .e_str_segment,
            .e_str,
            .e_bytes_literal,
            .e_lookup_local,
            .e_lookup_external,
            .e_lookup_associated_local,
            .e_lookup_associated,
            .e_lookup_associated_resolved,
            .e_lookup_required,
            .e_list,
            .e_empty_list,
            .e_tuple,
            .e_match,
            .e_if,
            .e_call,
            .e_record,
            .e_empty_record,
            .e_block,
            .e_tag,
            .e_nominal,
            .e_nominal_external,
            .e_zero_argument_tag,
            .e_closure,
            .e_lambda,
            .e_binop,
            .e_unary_minus,
            .e_unary_not,
            .e_field_access,
            .e_method_call,
            .e_structural_eq,
            .e_structural_hash,
            .e_type_method_call,
            .e_tuple_access,
            .e_runtime_error,
            .e_crash,
            .e_dbg,
            .e_expect_err,
            .e_expect,
            .e_ellipsis,
            .e_anno_only,
            .e_derived_method,
            .e_return,
            .e_break,
            .e_for,
            .e_hosted_lambda,
            .e_run_low_level,
            => unreachable,
        }
    }

    for (module.moduleEnvConst().for_loop_dispatch_plans.items.items) |plan| {
        if (!source_nodes.hasRawLoop(plan.node_idx)) continue;
        _ = try appendCheckedTypeRoot(allocator, module, names, imports, store, active, @enumFromInt(plan.iter_fn_var));
        _ = try appendCheckedTypeRoot(allocator, module, names, imports, store, active, @enumFromInt(plan.next_fn_var));
        _ = try appendCheckedTypeRoot(allocator, module, names, imports, store, active, @enumFromInt(plan.step_topology.one_payload_var));
        _ = try appendCheckedTypeRoot(allocator, module, names, imports, store, active, @enumFromInt(plan.step_topology.skip_payload_var));
    }

    for (module.moduleEnvConst().store.literalDispatchPlans()) |plan| {
        switch (plan.dispatchResolution()) {
            .builtin_direct, .checked_error => continue,
            .custom_dispatch, .specialization_dispatch => {},
            .unresolved => checkedArtifactInvariant(
                "unresolved literal dispatch plan reached checked type publication",
                .{},
            ),
        }
        // Custom and specialization-time conversion expressions need both the
        // target and callable roots. Direct builtins need neither.
        _ = try appendCheckedTypeRoot(allocator, module, names, imports, store, active, @enumFromInt(plan.target_var));
        _ = try appendCheckedTypeRoot(allocator, module, names, imports, store, active, @enumFromInt(plan.fn_var));
    }
}

fn syntheticFunctionTypeKey(
    store: *const CheckedTypeStore,
    kind: CheckedFunctionKind,
    args: []const CheckedTypeId,
    ret: CheckedTypeId,
) canonical.CanonicalTypeKey {
    const finalized_kind = finalizedFunctionKind(kind);
    var hasher = std.crypto.hash.sha2.Sha256.init(.{});
    hashByteSlice(&hasher, "checked_synthetic_function");
    hashByteSlice(&hasher, @tagName(finalized_kind));
    hashU32(&hasher, @intCast(args.len));
    for (args) |arg| {
        hasher.update(&store.roots.items[@intFromEnum(arg)].key.bytes);
    }
    hasher.update(&store.roots.items[@intFromEnum(ret)].key.bytes);
    return .{ .bytes = hasher.finalResult() };
}

fn syntheticSchemeKeyForType(key: canonical.CanonicalTypeKey) canonical.CanonicalTypeSchemeKey {
    var hasher = std.crypto.hash.sha2.Sha256.init(.{});
    hashByteSlice(&hasher, "checked_synthetic_type_scheme");
    hasher.update(&key.bytes);
    return .{ .bytes = hasher.finalResult() };
}

const SourceTypeGraphFacts = struct {
    contains_identity_variables: bool = false,
    contains_cycle: bool = false,

    fn merge(self: *SourceTypeGraphFacts, other: SourceTypeGraphFacts) void {
        self.contains_identity_variables = self.contains_identity_variables or other.contains_identity_variables;
        self.contains_cycle = self.contains_cycle or other.contains_cycle;
    }
};

const SourceTypeGraphFactsContext = struct {
    module: TypedCIR.Module,

    pub fn activeDepth(_: *@This()) u32 {
        // The traversal's back-edge depth is immaterial for these two facts;
        // only the existence of a back edge matters.
        return 0;
    }

    pub fn backEdgeFact(_: *@This(), _: u32) SourceTypeGraphFacts {
        return .{ .contains_cycle = true };
    }

    fn mergeVar(self: *@This(), traversal: anytype, facts: *SourceTypeGraphFacts, var_: Var) Allocator.Error!void {
        facts.merge(try traversal.visit(self.module.typeStoreConst().resolveVar(var_).var_));
    }

    fn mergeVars(self: *@This(), traversal: anytype, facts: *SourceTypeGraphFacts, vars: []const Var) Allocator.Error!void {
        for (vars) |var_| try self.mergeVar(traversal, facts, var_);
    }

    pub fn visit(self: *@This(), traversal: anytype, root: Var) Allocator.Error!SourceTypeGraphFacts {
        const types_store = self.module.typeStoreConst();
        const resolved = types_store.resolveVar(root);
        std.debug.assert(resolved.var_ == root);

        if (resolved.desc.flags.empty_tag_union_is_default) {
            return .{ .contains_identity_variables = true };
        }

        var facts: SourceTypeGraphFacts = .{};
        switch (resolved.desc.content) {
            .err, .field_presence => {},
            .flex, .rigid => facts.contains_identity_variables = true,
            .alias => |alias| {
                try self.mergeVar(traversal, &facts, types_store.getAliasBackingVar(alias));
                try self.mergeVars(traversal, &facts, types_store.sliceAliasArgs(alias));
            },
            .structure => |structure| switch (structure) {
                .empty_record, .empty_tag_union => {},
                .tuple => |tuple| try self.mergeVars(traversal, &facts, types_store.sliceVars(tuple.elems)),
                .nominal_type => |nominal| try self.mergeVars(traversal, &facts, types_store.sliceNominalArgs(nominal)),
                .fn_pure, .fn_effectful, .fn_unbound => |function| {
                    try self.mergeVars(traversal, &facts, types_store.sliceVars(function.args));
                    try self.mergeVar(traversal, &facts, function.ret);
                },
                .record => |record| {
                    for (types_store.getRecordFieldsSlice(record.fields).items(.presence)) |presence| {
                        switch (presence.decode()) {
                            .required => |type_var| try self.mergeVar(traversal, &facts, type_var),
                            .unknown => |unknown| {
                                try self.mergeVar(traversal, &facts, unknown.presence);
                                try self.mergeVar(traversal, &facts, unknown.var_);
                            },
                        }
                    }
                    try self.mergeVar(traversal, &facts, record.ext);
                },
                .record_unbound => |fields| {
                    for (types_store.getRecordFieldsSlice(fields).items(.presence)) |presence| {
                        switch (presence.decode()) {
                            .required => |type_var| try self.mergeVar(traversal, &facts, type_var),
                            .unknown => |unknown| {
                                try self.mergeVar(traversal, &facts, unknown.presence);
                                try self.mergeVar(traversal, &facts, unknown.var_);
                            },
                        }
                    }
                },
                .tag_union => |tag_union| {
                    const tags = types_store.getTagsSlice(tag_union.tags);
                    for (tags.items(.args)) |args| {
                        try self.mergeVars(traversal, &facts, types_store.sliceVars(args));
                    }
                    try self.mergeVar(traversal, &facts, tag_union.ext);
                },
            },
        }
        return facts;
    }
};

const SourceTypeGraphAnalysis = struct {
    active: std.AutoHashMap(Var, u32),
    completed: std.AutoHashMap(Var, SourceTypeGraphFacts),

    fn init(allocator: Allocator) SourceTypeGraphAnalysis {
        return .{
            .active = std.AutoHashMap(Var, u32).init(allocator),
            .completed = std.AutoHashMap(Var, SourceTypeGraphFacts).init(allocator),
        };
    }

    fn deinit(self: *SourceTypeGraphAnalysis) void {
        self.completed.deinit();
        self.active.deinit();
    }

    fn analyze(
        self: *SourceTypeGraphAnalysis,
        module: TypedCIR.Module,
        var_: Var,
    ) Allocator.Error!SourceTypeGraphFacts {
        std.debug.assert(self.active.count() == 0);
        var context = SourceTypeGraphFactsContext{ .module = module };
        var traversal = checked_traverse.MemoizedFactTraversal(Var, SourceTypeGraphFacts, SourceTypeGraphFactsContext).init(
            &self.active,
            &self.completed,
            &context,
        );
        const facts = try traversal.visit(module.typeStoreConst().resolveVar(var_).var_);
        std.debug.assert(self.active.count() == 0);
        return facts;
    }
};

const CheckedSourceTypeRoots = struct {
    roots: std.AutoHashMap(Var, CheckedTypeId),
    graph_analysis: SourceTypeGraphAnalysis,

    fn init(allocator: Allocator) CheckedSourceTypeRoots {
        return .{
            .roots = std.AutoHashMap(Var, CheckedTypeId).init(allocator),
            .graph_analysis = SourceTypeGraphAnalysis.init(allocator),
        };
    }

    fn deinit(self: *CheckedSourceTypeRoots) void {
        self.graph_analysis.deinit();
        self.roots.deinit();
    }

    fn get(self: *const CheckedSourceTypeRoots, var_: Var) ?CheckedTypeId {
        return self.roots.get(var_);
    }

    fn put(self: *CheckedSourceTypeRoots, var_: Var, root: CheckedTypeId) Allocator.Error!void {
        try self.roots.put(var_, root);
    }

    fn ensureUnusedCapacity(self: *CheckedSourceTypeRoots, additional_count: u32) Allocator.Error!void {
        try self.roots.ensureUnusedCapacity(additional_count);
    }

    fn remove(self: *CheckedSourceTypeRoots, var_: Var) bool {
        return self.roots.remove(var_);
    }

    fn analyze(self: *CheckedSourceTypeRoots, module: TypedCIR.Module, var_: Var) Allocator.Error!SourceTypeGraphFacts {
        return try self.graph_analysis.analyze(module, var_);
    }
};

fn appendCheckedTypeRoot(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    imports: CheckedImportViews,
    store: *CheckedTypeStore,
    active: *CheckedSourceTypeRoots,
    var_: Var,
) Allocator.Error!CheckedTypeId {
    return appendCheckedTypeRootWithRowDefault(allocator, module, names, imports, store, active, var_, null);
}

fn appendCheckedTypeRootWithRowDefault(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    imports: CheckedImportViews,
    store: *CheckedTypeStore,
    active: *CheckedSourceTypeRoots,
    var_: Var,
    row_default: ?RowDefault,
) Allocator.Error!CheckedTypeId {
    const resolved = module.typeStoreConst().resolveVar(var_);
    const resolved_var = resolved.var_;

    // The checker explicitly marks an otherwise-unresolved identity when it
    // closes that identity to `[]`. Preserve the surviving root as a checked
    // variable and carry `[]` only as its row default.
    if (resolved.desc.flags.empty_tag_union_is_default) {
        if (active.get(resolved_var)) |id| {
            applyCheckedTypeRowDefault(store, id, row_default);
            return id;
        }

        const key_info = try canonical_type_keys.fromVarInfo(
            allocator,
            module.typeStoreConst(),
            module.moduleEnvConst(),
            resolved_var,
        );
        const id: CheckedTypeId = @enumFromInt(@as(u32, @intCast(store.roots.items.len)));
        const root = CheckedTypeRoot{
            .id = id,
            .key = key_info.key,
            .contains_identity_variables = key_info.contains_identity_variables,
        };
        try store.roots.append(allocator, root);
        errdefer _ = store.roots.pop();
        try store.payloads.append(allocator, .pending);
        errdefer _ = store.payloads.pop();
        try store.indexRoot(allocator, root);
        try active.put(resolved_var, id);
        errdefer _ = active.remove(resolved_var);

        const stored = try store.commitPayload(allocator, .{ .flex = .{
            .row_default = .empty_tag_union,
        } });
        store.payloads.items[@intFromEnum(id)] = stored;
        return id;
    }

    if (active.get(resolved_var)) |id| {
        applyCheckedTypeRowDefault(store, id, row_default);
        return id;
    }

    const graph_facts = try active.analyze(module, resolved_var);
    if (!graph_facts.contains_identity_variables and !graph_facts.contains_cycle) {
        // Closed acyclic source graphs need no provisional root: publish their
        // children first, then hash-cons the immediate payload from interned
        // child ids. Repeated fresh solver graphs therefore stop here without
        // another recursive canonical digest.
        var build_payload = try copyCheckedTypePayload(
            allocator,
            module,
            names,
            imports,
            store,
            active,
            resolved.desc.content,
        );
        var payload_owned = true;
        errdefer if (payload_owned) deinitCheckedTypePayloadBuild(allocator, &build_payload);

        try active.ensureUnusedCapacity(1);
        const fingerprint = checkedTypePayloadStructuralFingerprint(.source, build_payload);
        if (store.structuralRootForPayload(.source, fingerprint, build_payload)) |existing| {
            deinitCheckedTypePayloadBuild(allocator, &build_payload);
            payload_owned = false;
            applyCheckedTypeRowDefault(store, existing, row_default);
            active.roots.putAssumeCapacityNoClobber(resolved_var, existing);
            return existing;
        }

        const key_info = try canonical_type_keys.fromVarInfo(
            allocator,
            module.typeStoreConst(),
            module.moduleEnvConst(),
            resolved_var,
        );
        std.debug.assert(!key_info.contains_identity_variables);
        if (store.rootForKey(key_info.key)) |existing| {
            deinitCheckedTypePayloadBuild(allocator, &build_payload);
            payload_owned = false;
            applyCheckedTypeRowDefault(store, existing, row_default);
            active.roots.putAssumeCapacityNoClobber(resolved_var, existing);
            return existing;
        }

        const id: CheckedTypeId = @enumFromInt(@as(u32, @intCast(store.roots.items.len)));
        try store.roots.ensureUnusedCapacity(allocator, 1);
        try store.payloads.ensureUnusedCapacity(allocator, 1);
        const stored = try store.commitPayload(allocator, build_payload);
        payload_owned = false;
        const root = CheckedTypeRoot{
            .id = id,
            .key = key_info.key,
            .contains_identity_variables = false,
        };
        store.roots.appendAssumeCapacity(root);
        store.payloads.appendAssumeCapacity(stored);
        applyCheckedTypeRowDefault(store, id, row_default);
        try store.indexRoot(allocator, root);
        try store.indexStructuralRoot(allocator, .source, id, fingerprint);
        active.roots.putAssumeCapacityNoClobber(resolved_var, id);
        return id;
    }

    const key_info = try canonical_type_keys.fromVarInfo(
        allocator,
        module.typeStoreConst(),
        module.moduleEnvConst(),
        resolved_var,
    );
    if (!key_info.contains_identity_variables) {
        if (store.rootForKey(key_info.key)) |id| {
            applyCheckedTypeRowDefault(store, id, row_default);
            try active.put(resolved_var, id);
            return id;
        }
    }

    const id: CheckedTypeId = @enumFromInt(@as(u32, @intCast(store.roots.items.len)));
    const root = CheckedTypeRoot{
        .id = id,
        .key = key_info.key,
        .contains_identity_variables = key_info.contains_identity_variables,
    };
    try store.roots.append(allocator, root);
    errdefer _ = store.roots.pop();
    try store.payloads.append(allocator, .pending);
    errdefer _ = store.payloads.pop();
    try store.indexRoot(allocator, root);

    try active.put(resolved_var, id);
    errdefer _ = active.remove(resolved_var);
    var build_payload = try copyCheckedTypePayload(
        allocator,
        module,
        names,
        imports,
        store,
        active,
        resolved.desc.content,
    );
    errdefer deinitCheckedTypePayloadBuild(allocator, &build_payload);

    const stored = try store.commitPayload(allocator, build_payload);
    store.payloads.items[@intFromEnum(id)] = stored;
    applyCheckedTypeRowDefault(store, id, row_default);
    return id;
}

fn applyCheckedTypeRowDefault(
    store: *CheckedTypeStore,
    id: CheckedTypeId,
    row_default: ?RowDefault,
) void {
    const default = row_default orelse return;
    const index = @intFromEnum(id);
    if (index >= store.payloads.items.len) checkedArtifactInvariant("checked row default referenced a missing type payload", .{});
    switch (store.payloads.items[index]) {
        .pending => {},
        .flex => |*variable| setStoredTypeVariableRowDefault(variable, default),
        .rigid => |*variable| setStoredTypeVariableRowDefault(variable, default),
        .err,
        .alias,
        .record,
        .record_unbound,
        .tuple,
        .nominal,
        .function,
        .empty_record,
        .tag_union,
        .empty_tag_union,
        => {},
    }
}

fn setStoredTypeVariableRowDefault(variable: *StoredTypeVariable, row_default: RowDefault) void {
    if (variable.constraints.len != 0) {
        checkedArtifactInvariant("checked row default was assigned to a constrained type variable", .{});
    }
    if (variable.row_default) |existing| {
        if (existing != row_default) checkedArtifactInvariant("checked row variable received incompatible defaults", .{});
        return;
    }
    variable.row_default = row_default;
}

fn sourceTypeRootsFromIndex(
    allocator: Allocator,
    index: *const CheckedSourceTypeRoots,
) Allocator.Error![]CheckedSourceTypeRoot {
    if (index.roots.count() == 0) return &.{};
    const out = try allocator.alloc(CheckedSourceTypeRoot, index.roots.count());
    var it = index.roots.iterator();
    var i: usize = 0;
    while (it.next()) |entry| : (i += 1) {
        out[i] = .{
            .source_var = entry.key_ptr.*,
            .checked_root = entry.value_ptr.*,
        };
    }
    std.mem.sort(CheckedSourceTypeRoot, out, {}, checkedSourceTypeRootLessThan);
    return out;
}

fn checkedSourceTypeRootLessThan(_: void, a: CheckedSourceTypeRoot, b: CheckedSourceTypeRoot) bool {
    return @intFromEnum(a.source_var) < @intFromEnum(b.source_var);
}

fn copyCheckedTypePayload(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    imports: CheckedImportViews,
    store: *CheckedTypeStore,
    active: *CheckedSourceTypeRoots,
    content: types.Content,
) Allocator.Error!CheckedTypePayloadBuild {
    return switch (content) {
        .err => .err,
        .flex => |flex| .{ .flex = .{
            .name = try copyOptionalIdentText(allocator, module, flex.name),
            .constraints = try copyCheckedStaticDispatchConstraints(allocator, module, names, imports, store, active, flex.constraints),
            .numeric_default_phase = numericDefaultPhaseForFlex(module, flex),
            .row_default = null,
        } },
        .rigid => |rigid| .{ .rigid = .{
            .name = try copyIdentText(allocator, module, rigid.name),
            .constraints = try copyCheckedStaticDispatchConstraints(allocator, module, names, imports, store, active, rigid.constraints),
            .numeric_default_phase = numericDefaultPhaseForConstraints(module, rigid.constraints),
            .row_default = null,
        } },
        .alias => |alias| .{ .alias = .{
            .name = try names.internTypeIdent(module.identStoreConst(), alias.ident.ident_idx),
            .origin_module = try names.internModuleIdentity(module.moduleEnvConst().moduleIdentityHash(alias.origin_module)),
            .owner_module = checkedNamedTypeOwnerForSource(module, imports, alias.origin_module),
            .source_decl = alias.source_decl.toOptional(),
            .builtin_origin = alias.source_decl.originIsBuiltin(),
            .backing = try appendCheckedTypeRoot(allocator, module, names, imports, store, active, module.typeStoreConst().getAliasBackingVar(alias)),
            .args = try copyCheckedTypeRange(allocator, module, names, imports, store, active, module.typeStoreConst().sliceAliasArgs(alias)),
        } },
        // The checked artifact models required fields only, so a presence
        // variable never becomes a standalone checked type. Poison to err if one
        // is ever reached rather than inventing an unrepresentable payload.
        .field_presence => .err,
        .structure => |flat| try copyCheckedFlatType(allocator, module, names, imports, store, active, flat),
    };
}

fn numericDefaultPhaseForFlex(module: TypedCIR.Module, flex: types.Flex) ?NumericDefaultPhase {
    return numericDefaultPhaseForConstraints(module, flex.constraints);
}

fn numericDefaultPhaseForConstraints(
    module: TypedCIR.Module,
    constraints_range: types.StaticDispatchConstraint.SafeList.Range,
) ?NumericDefaultPhase {
    const constraints = module.typeStoreConst().sliceStaticDispatchConstraints(constraints_range);
    const idents = module.commonIdents();
    return types.literal_defaulting.numericDefaultPhase(.{
        .plus = idents.plus,
        .minus = idents.minus,
        .times = idents.times,
        .div_by = idents.div_by,
        .div_trunc_by = idents.div_trunc_by,
        .rem_by = idents.rem_by,
        .negate = idents.negate,
    }, .{
        .from_numeral = idents.from_numeral,
        .from_quote = idents.from_quote,
        .from_interpolation = idents.from_interpolation,
    }, constraints);
}

fn copyCheckedFlatType(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    imports: CheckedImportViews,
    store: *CheckedTypeStore,
    active: *CheckedSourceTypeRoots,
    flat: types.FlatType,
) Allocator.Error!CheckedTypePayloadBuild {
    return switch (flat) {
        .empty_record => .empty_record,
        .empty_tag_union => .empty_tag_union,
        .record_unbound => |fields| .{
            .record_unbound = try copyCheckedRecordFields(allocator, module, names, imports, store, active, fields),
        },
        .record => |record| blk: {
            if (record.fields.len() == 0 and checkedRecordExtIsEmpty(module, record.ext)) {
                break :blk .empty_record;
            }
            break :blk .{ .record = .{
                .fields = try copyCheckedRecordFields(allocator, module, names, imports, store, active, record.fields),
                .ext = try appendCheckedTypeRootWithRowDefault(allocator, module, names, imports, store, active, record.ext, .empty_record),
            } };
        },
        .tuple => |tuple| .{
            .tuple = try copyCheckedTypeRange(allocator, module, names, imports, store, active, module.typeStoreConst().sliceVars(tuple.elems)),
        },
        .nominal_type => |nominal| blk: {
            const builtin_nominal = categorizeBuiltinNominal(module, imports, nominal);
            break :blk .{
                .nominal = .{
                    .name = try names.internTypeIdent(module.identStoreConst(), nominal.ident.ident_idx),
                    .origin_module = try names.internModuleIdentity(module.moduleEnvConst().moduleIdentityHash(nominal.origin_module)),
                    .owner_module = checkedNamedTypeOwnerForSource(module, imports, nominal.origin_module),
                    .source_decl = nominal.sourceDeclOptional(),
                    .builtin = builtin_nominal,
                    .is_opaque = nominal.isOpaque(),
                    .representation = try checkedNominalRepresentationForSourceNominal(module, names, imports, nominal, builtin_nominal),
                    .args = try copyCheckedTypeRange(allocator, module, names, imports, store, active, module.typeStoreConst().sliceNominalArgs(nominal)),
                    // Padding lives on the nominal declaration (built from its source
                    // annotation), not on usage payloads copied from the internal
                    // type store, which carry no unnamed-field information.
                    .padding_field_types = &.{},
                    .declared_fields = &.{},
                },
            };
        },
        .fn_pure => |func| .{ .function = try copyCheckedFunctionType(allocator, module, names, imports, store, active, .pure, func) },
        .fn_effectful => |func| .{ .function = try copyCheckedFunctionType(allocator, module, names, imports, store, active, .effectful, func) },
        .fn_unbound => |func| .{ .function = try copyCheckedFunctionType(allocator, module, names, imports, store, active, .pure, func) },
        .tag_union => |tag_union| blk: {
            if (tag_union.tags.len() == 0 and checkedTagUnionExtIsEmpty(module, tag_union.ext)) {
                break :blk .empty_tag_union;
            }
            break :blk .{ .tag_union = .{
                .tags = try copyCheckedTags(allocator, module, names, imports, store, active, tag_union.tags),
                .ext = try appendCheckedTypeRootWithRowDefault(allocator, module, names, imports, store, active, tag_union.ext, .empty_tag_union),
            } };
        },
    };
}

fn checkedRecordExtIsEmpty(module: TypedCIR.Module, ext: Var) bool {
    return switch (module.typeStoreConst().resolveVar(ext).desc.content) {
        .structure => |flat| flat == .empty_record,
        .flex, .rigid, .alias, .field_presence, .err => false,
    };
}

fn checkedTagUnionExtIsEmpty(module: TypedCIR.Module, ext: Var) bool {
    return switch (module.typeStoreConst().resolveVar(ext).desc.content) {
        .structure => |flat| flat == .empty_tag_union,
        .flex, .rigid, .alias, .field_presence, .err => false,
    };
}

fn copyCheckedFunctionType(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    imports: CheckedImportViews,
    store: *CheckedTypeStore,
    active: *CheckedSourceTypeRoots,
    kind: CheckedFunctionKind,
    func: types.Func,
) Allocator.Error!CheckedFunctionType {
    const args = try copyCheckedTypeRange(allocator, module, names, imports, store, active, module.typeStoreConst().sliceVars(func.args));
    const ret = try appendCheckedTypeRoot(allocator, module, names, imports, store, active, func.ret);
    return .{
        .kind = finalizedFunctionKind(kind),
        .args = args,
        .ret = ret,
    };
}

fn copyCheckedTypeRange(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    imports: CheckedImportViews,
    store: *CheckedTypeStore,
    active: *CheckedSourceTypeRoots,
    vars: []const Var,
) Allocator.Error![]const CheckedTypeId {
    if (vars.len == 0) return &.{};
    const out = try allocator.alloc(CheckedTypeId, vars.len);
    errdefer allocator.free(out);
    for (vars, 0..) |var_, i| {
        out[i] = try appendCheckedTypeRoot(allocator, module, names, imports, store, active, var_);
    }
    return out;
}

fn checkedNamedTypeOwnerForSource(
    module: TypedCIR.Module,
    imports: CheckedImportViews,
    origin_module: base.ModuleIdentity.Idx,
) ModuleId {
    const module_env = module.moduleEnvConst();
    if (origin_module == module_env.selfModuleIdentity()) return imports.current_owner;

    return checkedImportedOwnerForOriginHash(imports, module_env.moduleIdentityHash(origin_module));
}

fn checkedImportedOwnerForOriginHash(
    imports: CheckedImportViews,
    origin_hash: *const [32]u8,
) ModuleId {
    var found: ?ModuleId = null;

    for (imports.direct) |import| {
        if (!importedViewIdentityMatches(import.view, origin_hash)) continue;
        found = checkedUniqueOwnerArtifact(found, import.key);
    }
    for (imports.available) |view| {
        if (!importedViewIdentityMatches(view, origin_hash)) continue;
        found = checkedUniqueOwnerArtifact(found, view.key);
    }

    return found orelse checkedArtifactInvariant(
        "checked named type source origin had no available checked owner artifact {any}",
        .{origin_hash.*},
    );
}

fn checkedUniqueOwnerArtifact(existing: ?ModuleId, next: ModuleId) ModuleId {
    if (existing) |found| {
        if (!checkedArtifactKeyEql(found, next)) {
            checkedArtifactInvariant("checked named type source origin resolved to multiple owner artifacts", .{});
        }
        return found;
    }
    return next;
}

fn copyCheckedRecordFields(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    imports: CheckedImportViews,
    store: *CheckedTypeStore,
    active: *CheckedSourceTypeRoots,
    range: types.RecordField.SafeMultiList.Range,
) Allocator.Error![]const CheckedRecordField {
    const fields = module.typeStoreConst().getRecordFieldsSlice(range);
    const field_names = fields.items(.name);
    const field_presences = fields.items(.presence);
    if (field_names.len == 0) return &.{};

    const out = try allocator.alloc(CheckedRecordField, field_names.len);
    errdefer allocator.free(out);
    for (field_names, field_presences, 0..) |field_name, field_presence, i| {
        // Publish the independent value and kind axes; see design.md "Field Kinds".
        var kind: CheckedFieldKind = .required;
        const ty: CheckedTypeId = switch (field_presence.decode()) {
            .required => |type_var| try appendCheckedTypeRoot(allocator, module, names, imports, store, active, type_var),
            .unknown => |unknown| switch (module.typeStoreConst().resolveVar(unknown.presence).desc.content) {
                .field_presence => |fp| blk: {
                    switch (fp) {
                        .required => {},
                        .defaulted => |id| kind = .defaultedFromParts(
                            try names.internModuleIdentity(module.moduleEnvConst().moduleIdentityHash(id.origin_module)),
                            id.expr_node,
                        ),
                        .optional => kind = .optional,
                    }
                    break :blk try appendCheckedTypeRoot(allocator, module, names, imports, store, active, unknown.var_);
                },
                // A still-flex kind here is a SCHEME INTERIOR. Preserve its
                // checked identity separately from the payload type so each
                // Monotype instantiation can solve the kind from its concrete
                // call interface before choosing the slot representation.
                .flex => blk: {
                    kind = .undetermined(try appendCheckedTypeRoot(
                        allocator,
                        module,
                        names,
                        imports,
                        store,
                        active,
                        unknown.presence,
                    ));
                    break :blk try appendCheckedTypeRoot(allocator, module, names, imports, store, active, unknown.var_);
                },
                // A poisoned presence var (a presence mismatch merges to err,
                // unify.zig `unifyFieldPresence`) poisons the KIND axis while
                // preserving the field's independent VALUE axis. Keeping both
                // explicit also preserves the solver key's `"err"` + value
                // encoding at the checked boundary.
                .err => blk: {
                    kind = .err;
                    break :blk try appendCheckedTypeRoot(allocator, module, names, imports, store, active, unknown.var_);
                },
                // A presence variable may only hold a committed
                // `.field_presence` kind, a still-undetermined `.flex`, or a
                // poisoned `.err` (same inventory as the canonical key
                // writer's `writeFieldPresenceForKey`).
                .rigid, .alias, .structure => checkedArtifactInvariant("checked publication reached a field presence variable holding non-presence content", .{}),
            },
        };
        out[i] = .{
            .name = try names.internRecordFieldIdent(module.identStoreConst(), field_name),
            .ty = ty,
            .kind = kind,
        };
    }
    return out;
}

fn copyCheckedTags(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    imports: CheckedImportViews,
    store: *CheckedTypeStore,
    active: *CheckedSourceTypeRoots,
    range: types.Tag.SafeMultiList.Range,
) Allocator.Error![]const CheckedTagBuild {
    const tags = module.typeStoreConst().getTagsSlice(range);
    const tag_names = tags.items(.name);
    const tag_args = tags.items(.args);
    if (tag_names.len == 0) return &.{};

    const out = try allocator.alloc(CheckedTagBuild, tag_names.len);
    for (out) |*tag| tag.* = .{ .name = undefined, .args = &.{} };
    errdefer {
        for (out[0..tag_names.len]) |tag| allocator.free(tag.args);
        allocator.free(out);
    }
    for (tag_names, tag_args, 0..) |tag_name, arg_range, i| {
        out[i] = .{
            .name = try names.internTagIdent(module.identStoreConst(), tag_name),
            .args = try copyCheckedTypeRange(allocator, module, names, imports, store, active, module.typeStoreConst().sliceVars(arg_range)),
        };
    }
    return out;
}

fn copyCheckedStaticDispatchConstraints(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    imports: CheckedImportViews,
    store: *CheckedTypeStore,
    active: *CheckedSourceTypeRoots,
    range: types.StaticDispatchConstraint.SafeList.Range,
) Allocator.Error![]const CheckedStaticDispatchConstraint {
    const constraints = module.typeStoreConst().sliceStaticDispatchConstraints(range);
    if (constraints.len == 0) return &.{};

    const out = try allocator.alloc(CheckedStaticDispatchConstraint, constraints.len);
    errdefer allocator.free(out);
    for (constraints, 0..) |constraint, i| {
        out[i] = .{
            .fn_name = try names.internMethodIdent(module.identStoreConst(), constraint.fn_name),
            .fn_ty = try appendCheckedTypeRoot(allocator, module, names, imports, store, active, constraint.fn_var),
            .origin = constraint.origin,
        };
    }
    return out;
}

fn categorizeBuiltinNominal(module: TypedCIR.Module, imports: CheckedImportViews, nominal: types.NominalType) ?CheckedBuiltinNominal {
    if (!nominal.originIsBuiltin()) return null;

    const source_decl = nominal.sourceDeclOptional() orelse return null;
    const module_env = module.moduleEnvConst();
    const origin_hash = module_env.moduleIdentityHash(nominal.origin_module);

    if (module_env.module_role == .builtin and moduleEnvIdentityMatches(module_env, origin_hash)) {
        return checkedBuiltinNominalForSourceDecl(module_env, source_decl);
    }
    if (checkedBuiltinNominalForImportedSource(imports.direct, origin_hash, source_decl)) |builtin_nominal| return builtin_nominal;
    if (checkedBuiltinNominalForAvailableSource(imports.available, origin_hash, source_decl)) |builtin_nominal| return builtin_nominal;
    return null;
}

fn checkedBuiltinNominalForImportedSource(
    imports: []const PublishImportArtifact,
    origin_hash: *const [32]u8,
    source_decl: u32,
) ?CheckedBuiltinNominal {
    var found: ?CheckedBuiltinNominal = null;
    for (imports) |import| {
        if (checkedBuiltinNominalForView(import.view, origin_hash, source_decl)) |builtin_nominal| {
            if (found) |existing| {
                if (existing != builtin_nominal) {
                    checkedArtifactInvariant("checked builtin nominal source resolved to multiple builtin declarations", .{});
                }
            } else {
                found = builtin_nominal;
            }
        }
    }
    return found;
}

fn checkedBuiltinNominalForAvailableSource(
    views: []const ImportedModuleView,
    origin_hash: *const [32]u8,
    source_decl: u32,
) ?CheckedBuiltinNominal {
    var found: ?CheckedBuiltinNominal = null;
    for (views) |view| {
        if (checkedBuiltinNominalForView(view, origin_hash, source_decl)) |builtin_nominal| {
            if (found) |existing| {
                if (existing != builtin_nominal) {
                    checkedArtifactInvariant("checked builtin nominal source resolved to multiple builtin declarations", .{});
                }
            } else {
                found = builtin_nominal;
            }
        }
    }
    return found;
}

fn checkedBuiltinNominalForView(view: ImportedModuleView, origin_hash: *const [32]u8, source_decl: u32) ?CheckedBuiltinNominal {
    if (!importedViewIdentityMatches(view, origin_hash)) return null;
    if (sourceDeclTypeIdent(view.module_env, source_decl) == null) return null;
    if (view.module_env.module_role != .builtin) return null;
    return checkedBuiltinNominalForSourceDecl(view.module_env, source_decl);
}

fn checkedBuiltinNominalForSourceDecl(module_env: *const ModuleEnv, source_decl: u32) ?CheckedBuiltinNominal {
    if (module_env.module_role != .builtin) return null;
    const type_ident = sourceDeclTypeIdent(module_env, source_decl) orelse return null;
    return checkedBuiltinNominalForIdent(module_env, type_ident);
}

fn sourceDeclTypeIdent(module_env: *const ModuleEnv, source_decl: u32) ?base.Ident.Idx {
    if (source_decl >= module_env.store.nodes.len()) return null;
    const node: CIR.Node.Idx = @enumFromInt(source_decl);
    const node_tag = module_env.store.nodes.get(node).tag;
    if (node_tag != .statement_alias_decl and node_tag != .statement_nominal_decl) return null;
    const statement_idx: CIR.Statement.Idx = @enumFromInt(source_decl);
    const statement = module_env.store.getStatement(statement_idx);
    const header_idx = if (statement == .s_nominal_decl)
        statement.s_nominal_decl.header
    else if (statement == .s_alias_decl)
        statement.s_alias_decl.header
    else
        return null;
    return module_env.store.getTypeHeader(header_idx).name;
}

fn checkedBuiltinNominalForIdent(module_env: *const ModuleEnv, ident: base.Ident.Idx) ?CheckedBuiltinNominal {
    const common = module_env.idents;
    if (ident.eql(common.bool) or ident.eql(common.bool_type)) return .bool;
    if (ident.eql(common.@"try") or ident.eql(common.builtin_try)) return .try_;
    if (ident.eql(common.str) or ident.eql(common.builtin_str)) return .str;
    if (ident.eql(common.u8) or ident.eql(common.u8_type)) return .u8;
    if (ident.eql(common.i8) or ident.eql(common.i8_type)) return .i8;
    if (ident.eql(common.u16) or ident.eql(common.u16_type)) return .u16;
    if (ident.eql(common.i16) or ident.eql(common.i16_type)) return .i16;
    if (ident.eql(common.u32) or ident.eql(common.u32_type)) return .u32;
    if (ident.eql(common.i32) or ident.eql(common.i32_type)) return .i32;
    if (ident.eql(common.u64) or ident.eql(common.u64_type)) return .u64;
    if (ident.eql(common.i64) or ident.eql(common.i64_type)) return .i64;
    if (ident.eql(common.u128) or ident.eql(common.u128_type)) return .u128;
    if (ident.eql(common.i128) or ident.eql(common.i128_type)) return .i128;
    if (ident.eql(common.f32) or ident.eql(common.f32_type)) return .f32;
    if (ident.eql(common.f64) or ident.eql(common.f64_type)) return .f64;
    if (ident.eql(common.dec) or ident.eql(common.dec_type)) return .dec;
    if (ident.eql(common.u8x16_type)) return .u8x16;
    if (ident.eql(common.i8x16_type)) return .i8x16;
    if (ident.eql(common.u16x8_type)) return .u16x8;
    if (ident.eql(common.i16x8_type)) return .i16x8;
    if (ident.eql(common.u32x4_type)) return .u32x4;
    if (ident.eql(common.i32x4_type)) return .i32x4;
    if (ident.eql(common.u64x2_type)) return .u64x2;
    if (ident.eql(common.i64x2_type)) return .i64x2;
    if (ident.eql(common.list) or ident.eql(common.builtin_list)) return .list;
    if (ident.eql(common.box) or ident.eql(common.builtin_box)) return .box;
    if (ident.eql(common.dict) or ident.eql(common.builtin_dict)) return .dict;
    if (ident.eql(common.set) or ident.eql(common.builtin_set)) return .set;
    if (ident.eql(common.iter) or ident.eql(common.builtin_iter)) return .iter;
    if (ident.eql(common.builtin_encoding_parse_tag_union_spec)) return .parse_tag_union_spec;
    if (ident.eql(common.builtin_encoding_field_names)) return .fields;
    if (ident.eql(common.builtin_encoding_field_name)) return .field;
    if (ident.eql(common.builtin_crypto_sha256_digest)) return .crypto_sha256_digest;
    if (ident.eql(common.builtin_crypto_sha256_hasher)) return .crypto_sha256_hasher;
    if (ident.eql(common.builtin_crypto_blake3_digest)) return .crypto_blake3_digest;
    if (ident.eql(common.builtin_crypto_blake3_hasher)) return .crypto_blake3_hasher;
    return null;
}

fn testTypeDeclSourceDeclForIdent(module_env: *const ModuleEnv, type_ident: base.Ident.Idx) error{MissingTestTypeDecl}!u32 {
    for (module_env.store.sliceStatements(module_env.all_statements)) |statement_idx| {
        const source_decl = @intFromEnum(statement_idx);
        const candidate = sourceDeclTypeIdent(module_env, source_decl) orelse continue;
        if (candidate.eql(type_ident)) return source_decl;
    }
    return error.MissingTestTypeDecl;
}

const ExpectSingleNominalBackingPayloadError = Allocator.Error || error{
    WriteFailed,
    TestExpectedEqual,
    TestUnexpectedResult,
    CorruptEmbeddedBuiltins,
    ExpectedNominalStatement,
    ExpectedNominalRoot,
    ExpectedNominalPayload,
    ExpectedNominalBacking,
};

fn expectSingleNominalBackingPayload(allocator: Allocator, module_name: []const u8, source: []const u8, expected: CheckedTypePayload) ExpectSingleNominalBackingPayloadError!void {
    const testing = std.testing;
    const TestEnv = @import("test/TestEnv.zig");

    var test_env = try TestEnv.init(module_name, source);
    defer test_env.deinit();
    try test_env.assertNoErrors();

    const source_modules = [_]TypedCIR.Modules.SourceModule{
        .{ .precompiled = test_env.module_env },
    };
    var modules = try TypedCIR.Modules.init(allocator, &source_modules);
    defer modules.deinit();

    const module = modules.module(0);
    const module_env = module.moduleEnvConst();
    var names = canonical.CanonicalNameStore.init(allocator);
    defer names.deinit();
    try internLoweringVisibleNames(module_env, &names);

    const module_name_id = try names.internModuleName(module_env.module_name);
    const display_module_name = try names.internModuleIdent(module.identStoreConst(), module_env.display_module_name_idx);
    const qualified_module_name = try names.internModuleIdent(module.identStoreConst(), module_env.qualified_module_ident);
    const module_identity = ModuleIdentity{
        .stable_hash = computeStableModuleIdentityHash(module_env),
        .module_idx = module.moduleIndex(),
        .module_name = module_name_id,
        .display_module_name = display_module_name,
        .qualified_module_name = qualified_module_name,
        .kind = module_env.module_kind,
    };
    _ = try names.internModuleIdentity(&module_identity.stable_hash);

    var checking_context_identity = try CheckingContextIdentity.fromModule(allocator, module, &.{}, null, null, &.{});
    defer checking_context_identity.deinit(allocator);
    const artifact_key = CheckedModuleArtifactKey.computeFromSourceHash(
        hashModuleSourceInputs(module_env),
        module_identity,
        checking_context_identity,
        &.{},
    );

    var source_nodes = try CheckedSourceNodes.init(allocator, module);
    defer source_nodes.deinit(allocator);

    var publication = try CheckedTypeStore.fromModule(allocator, module, &names, artifact_key, &.{}, &.{}, &source_nodes);
    defer publication.deinit(allocator);

    const nominal_stmt = for (module_env.store.sliceStatements(module_env.all_statements)) |statement_idx| {
        switch (module_env.store.getStatement(statement_idx)) {
            .s_nominal_decl => break statement_idx,
            .s_decl,
            .s_var,
            .s_var_uninitialized,
            .s_reassign,
            .s_crash,
            .s_dbg,
            .s_expr,
            .s_expect,
            .s_for,
            .s_while,
            .s_infinite_loop,
            .s_breakable_loop,
            .s_break,
            .s_return,
            .s_import,
            .s_alias_decl,
            .s_where_alias_decl,
            .s_type_anno,
            .s_type_var_alias,
            .s_runtime_error,
            => {},
        }
    } else return error.ExpectedNominalStatement;

    const nominal_root = publication.rootForSourceVar(module, ModuleEnv.varFrom(nominal_stmt)) orelse return error.ExpectedNominalRoot;
    const nominal_payload = publication.store.payload(nominal_root);
    if (nominal_payload != .nominal) return error.ExpectedNominalPayload;
    const nominal = nominal_payload.nominal;
    const backing = publication.store.nominalBackingTemplateForPayload(nominal) orelse return error.ExpectedNominalBacking;
    try testing.expectEqual(expected, publication.store.payload(backing));
}

