fn moduleEnvIdentityMatches(module_env: *const ModuleEnv, origin_hash: *const [32]u8) bool {
    const env_hash = module_env.contentIdentityHash() orelse return false;
    return base.ModuleIdentity.eql(env_hash, origin_hash);
}

fn checkedNominalRepresentationForSourceNominal(
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    imports: CheckedImportViews,
    nominal: types.NominalType,
    builtin_nominal: ?CheckedBuiltinNominal,
) Allocator.Error!CheckedNominalRepresentationRef {
    if (builtin_nominal) |builtin_id| return .{ .builtin = builtin_id };

    const module_env = module.moduleEnvConst();
    const source_decl = nominal.sourceDeclOptional();
    if (nominal.origin_module == module_env.selfModuleIdentity()) {
        const statement = source_decl orelse
            checkedArtifactInvariant("checked local nominal representation had no source declaration", .{});
        return .{ .local_declaration = localNominalDeclarationIdForStatement(module, @enumFromInt(statement)) };
    }

    const origin_hash = module_env.moduleIdentityHash(nominal.origin_module);
    const type_name = try names.internTypeIdent(module.identStoreConst(), nominal.ident.ident_idx);
    return .{ .imported_declaration = importedNominalDeclarationRefForSourceNominal(
        names,
        imports,
        origin_hash,
        type_name,
        source_decl orelse checkedArtifactInvariant("checked imported nominal representation had no source declaration", .{}),
    ) };
}

/// Resolve the artifact + declaration that owns an imported nominal type:
/// the declaring module by 32-byte content identity, the declaration by its
/// full nominal key.
fn importedNominalDeclarationRefForSourceNominal(
    names: *const canonical.CanonicalNameStore,
    imports: CheckedImportViews,
    origin_hash: *const [32]u8,
    type_name: canonical.TypeNameId,
    source_decl: u32,
) ImportedNominalDeclarationRef {
    const type_text = names.typeNameText(type_name);
    var found: ?ImportedNominalDeclarationRef = null;

    for (imports.direct) |import| {
        if (!importedViewIdentityMatches(import.view, origin_hash)) continue;
        for (import.view.checked_types.nominal_declarations) |declaration| {
            if (!Ident.textEql(import.view.canonical_names.typeNameText(declaration.nominal.type_name), type_text)) continue;
            if (declaration.source_statement != source_decl) continue;
            const next = ImportedNominalDeclarationRef{
                .artifact = import.key,
                .declaration = declaration.id,
            };
            if (found) |existing| {
                if (!checkedArtifactKeyEql(existing.artifact, next.artifact) or existing.declaration != next.declaration) {
                    checkedArtifactInvariant("checked nominal representation import declaration resolution was ambiguous", .{});
                }
            } else {
                found = next;
            }
        }
    }
    for (imports.available) |view| {
        if (!importedViewIdentityMatches(view, origin_hash)) continue;
        for (view.checked_types.nominal_declarations) |declaration| {
            if (!Ident.textEql(view.canonical_names.typeNameText(declaration.nominal.type_name), type_text)) continue;
            if (declaration.source_statement != source_decl) continue;
            const next = ImportedNominalDeclarationRef{
                .artifact = view.key,
                .declaration = declaration.id,
            };
            if (found) |existing| {
                if (!checkedArtifactKeyEql(existing.artifact, next.artifact) or existing.declaration != next.declaration) {
                    checkedArtifactInvariant("checked nominal representation import declaration resolution was ambiguous", .{});
                }
            } else {
                found = next;
            }
        }
    }

    return found orelse checkedArtifactInvariant(
        "checked nominal representation referenced a missing imported nominal declaration for owner identity {any} type {s} statement {d}",
        .{ origin_hash.*, type_text, source_decl },
    );
}

fn localNominalDeclarationIdForStatement(
    module: TypedCIR.Module,
    statement_idx: CIR.Statement.Idx,
) CheckedNominalDeclarationId {
    var next_id: u32 = 0;
    const module_env = module.moduleEnvConst();
    for (module_env.store.sliceStatements(module_env.all_statements)) |candidate| {
        const statement = module.getStatement(candidate);
        if (statement != .s_nominal_decl) continue;
        const nominal = statement.s_nominal_decl;
        if (nominal.anno == .placeholder) continue;
        if (!localNominalDeclarationIsValid(module, candidate)) continue;
        const id: CheckedNominalDeclarationId = @enumFromInt(next_id);
        next_id += 1;
        if (candidate == statement_idx) return id;
    }
    checkedArtifactInvariant("checked nominal declaration statement had no declaration id", .{});
}

fn localNominalDeclarationIsValid(
    module: TypedCIR.Module,
    statement_idx: CIR.Statement.Idx,
) bool {
    const types_store = module.typeStoreConst();
    const decl_idx = types_store.lookupNominalDeclByKey(
        module.moduleEnvConst().selfModuleIdentity(),
        @intFromEnum(statement_idx),
    ) orelse checkedArtifactInvariant("checked local nominal declaration had no checker declaration entry", .{});
    return types_store.getNominalDecl(decl_idx).isValid();
}

fn copyOptionalIdentText(
    allocator: Allocator,
    module: TypedCIR.Module,
    ident: ?Ident.Idx,
) Allocator.Error!?[]const u8 {
    const idx = ident orelse return null;
    return try copyIdentText(allocator, module, idx);
}

fn copyIdentText(
    allocator: Allocator,
    module: TypedCIR.Module,
    idx: Ident.Idx,
) Allocator.Error![]const u8 {
    return try allocator.dupe(u8, module.getIdent(idx));
}

fn findCheckedTypeScheme(schemes: []const CheckedTypeScheme, key: canonical.CanonicalTypeSchemeKey) ?CheckedTypeSchemeId {
    for (schemes) |scheme| {
        if (std.meta.eql(scheme.key.bytes, key.bytes)) return scheme.id;
    }
    return null;
}

/// Public `CheckedBody` declaration.
pub const CheckedBody = struct {
    id: CheckedBodyId,
    root_expr: CheckedExprId,
    owner_template: canonical.ProcedureTemplateRef,
};

/// Public `CheckedPatternBinder` declaration.
pub const CheckedPatternBinder = struct {
    id: PatternBinderId,
    pattern: CheckedPatternId,
    reassignable: bool,
};

/// Public `CheckedStringLiteralId` declaration.
pub const CheckedStringLiteralId = checked_ids.CheckedStringLiteralId;

/// Public `CheckedRecordExprField` declaration.
pub const CheckedRecordExprField = struct {
    label: canonical.RecordFieldLabelId,
    value: CheckedExprId,
};

/// The published access operation of one record-field path segment
/// (design.md "Field Kinds (All-Dynamic Optional Fields)"): `required` is a
/// plain inline-slot projection; `optional` is a `.?` access whose lowering
/// tests the field's tagged slot at runtime.
pub const CheckedFieldAccessMode = enum(u8) {
    required,
    optional,
};

/// One source-ordered segment of a checked record-field access path.
///
/// `success_ty` is the checked type of this path prefix's successful payload—
/// for `.?` segments too, the field's VALUE type, never the slot or Try
/// wrapper. The enclosing checked expression owns the observable type of the
/// complete path (one flat `Try(τ, [MissingField])` when any segment's `mode`
/// is `optional`).
pub const CheckedFieldAccessSegment = struct {
    field_name: canonical.RecordFieldLabelId,
    success_ty: CheckedTypeId,
    source_region: base.Region,
    mode: CheckedFieldAccessMode,
    /// How Monotype may reach this segment's slot in its receiver: through an
    /// ordinary record field, or through the private backing record of an
    /// opaque nominal defined in the current module. Computed per segment:
    /// the first segment's receiver is the access expression's receiver, and
    /// each later segment's receiver is the previous segment's successful
    /// value.
    backing_access: CheckedFieldBackingAccess,
};

/// Public `CheckedIfBranch` declaration.
pub const CheckedIfBranch = struct {
    cond: CheckedExprId,
    body: CheckedExprId,
};

/// Public `CheckedMatchBranchPattern` declaration (read form).
///
/// `binder_remaps` is a range into `CheckedBodyStore.binder_remap_pool` (POD).
/// Use `binderRemapsSlice` to obtain the backing slice.
pub const CheckedMatchBranchPattern = struct {
    pattern: CheckedPatternId,
    degenerate: bool,
    bn_start: u32 = 0,
    bn_len: u32 = 0,

    /// The branch pattern's alternative binder remaps within its store's
    /// `binder_remap_pool`.
    pub fn binderRemapsSlice(self: CheckedMatchBranchPattern, pool_owner: anytype) []const CheckedAlternativeBinderRemap {
        return pool_owner.binderRemapPool()[self.bn_start .. self.bn_start + self.bn_len];
    }
};

/// Public `CheckedAlternativeBinderRemap` declaration.
pub const CheckedAlternativeBinderRemap = struct {
    candidate_binder: PatternBinderId,
    representative_binder: PatternBinderId,
};

/// Public `CheckedMatchBranch` declaration (read form).
///
/// `patterns` is a range into `CheckedBodyStore.match_branch_pattern_pool` (POD).
/// Use `patternsSlice` to obtain the backing slice.
pub const CheckedMatchBranch = struct {
    pt_start: u32 = 0,
    pt_len: u32 = 0,
    value: CheckedExprId,
    guard: ?CheckedExprId,

    /// The match branch's patterns within its store's `match_branch_pattern_pool`.
    pub fn patternsSlice(self: CheckedMatchBranch, pool_owner: anytype) []const CheckedMatchBranchPattern {
        return pool_owner.matchBranchPatternPool()[self.pt_start .. self.pt_start + self.pt_len];
    }
};

/// Kinds of checked sites that can be evaluated for comptime exhaustiveness.
pub const CheckedComptimeSiteKind = enum {
    match,
    destructure,
};

/// Describes whether an exhaustiveness site remains pending, can run at runtime, or is handled at compile time.
pub const ExhaustivenessResolutionPolicy = union(enum) {
    compile_time_replaced_by_root: ComptimeRootId,
    compile_time_only,
    runtime_reachable,
    not_pending,
};

/// Checked owner that establishes the diagnostic and dependency context for an exhaustiveness site.
pub const CheckedExhaustivenessSiteOwner = union(enum) {
    procedure_template: canonical.ProcedureTemplateRef,
    root: ComptimeRootId,
};

/// Checked exhaustiveness metadata preserved for comptime evaluation and diagnostics.
pub const CheckedExhaustivenessSite = struct {
    id: CheckedExhaustivenessSiteId,
    kind: CheckedComptimeSiteKind,
    region: base.Region,
    owner: ?CheckedExhaustivenessSiteOwner = null,
    checked_expr: ?CheckedExprId = null,
    checked_pattern: ?CheckedPatternId = null,
    policy: ExhaustivenessResolutionPolicy,
};

/// Table of checked exhaustiveness sites keyed by checked expressions or patterns.
pub const CheckedExhaustivenessSiteTable = struct {
    sites: []CheckedExhaustivenessSite = &.{},

    pub fn lookupByMatchExpr(self: *const CheckedExhaustivenessSiteTable, expr: CheckedExprId) ?CheckedExhaustivenessSiteId {
        for (self.sites) |site| {
            if (site.checked_expr != null and site.checked_expr.? == expr) return site.id;
        }
        return null;
    }

    pub fn lookupByDestructurePattern(self: *const CheckedExhaustivenessSiteTable, pattern: CheckedPatternId) ?CheckedExhaustivenessSiteId {
        for (self.sites) |site| {
            if (site.checked_pattern != null and site.checked_pattern.? == pattern) return site.id;
        }
        return null;
    }

    pub fn get(self: *const CheckedExhaustivenessSiteTable, id: CheckedExhaustivenessSiteId) CheckedExhaustivenessSite {
        const raw = @intFromEnum(id);
        if (raw >= self.sites.len) checkedArtifactInvariant("checked exhaustiveness site id out of range", .{});
        return self.sites[raw];
    }

    pub fn deinit(self: *CheckedExhaustivenessSiteTable, allocator: Allocator) void {
        allocator.free(self.sites);
        self.* = .{};
    }

    pub const Serialized = extern struct {
        sites: SerializedSlice(CheckedExhaustivenessSite) = .{},

        const Serde = artifact_serialize.SliceStoreSerde(CheckedExhaustivenessSiteTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };
};

