pub const ResolvedValueRefRecord = struct {
    expr: CheckedExprId,
    ref: ResolvedValueRef,
    checked_ty: CheckedTypeId,
    scope_depth: u32,
};

/// Public `ResolvedValueRefTable` declaration.
pub const ResolvedValueRefTable = struct {
    records: []ResolvedValueRefRecord = &.{},
    by_checked_expr: []?ResolvedValueRefId = &.{},
    template_refs: []ResolvedValueRefId = &.{},

    pub const Serialized = extern struct {
        records: SerializedSlice(ResolvedValueRefRecord) = .{},
        by_checked_expr: SerializedSlice(?ResolvedValueRefId) = .{},
        template_refs: SerializedSlice(ResolvedValueRefId) = .{},
        const Serde = artifact_serialize.SliceStoreSerde(ResolvedValueRefTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    pub fn fromModule(
        allocator: Allocator,
        modules: *const TypedCIR.Modules,
        module_idx: u32,
        artifact_key: CheckedModuleArtifactKey,
        imports: []const PublishImportArtifact,
        available_artifacts: []const ImportedModuleView,
        templates: *const CheckedProcedureTemplateTable,
        hosted_procs: *const HostedProcTable,
        platform_required_declarations: *const PlatformRequiredDeclarationTable,
        platform_required_bindings: *const PlatformRequiredBindingTable,
        top_level_values: *const TopLevelValueTable,
        hoisted_constants: *const HoistedConstTable,
        checked_types: *const CheckedTypePublication,
        checked_bodies: *const CheckedBodyStore,
        synthetic_expr_origins: []const SyntheticExprOriginRecord,
    ) Allocator.Error!ResolvedValueRefTable {
        const module = modules.module(module_idx);
        var records = std.ArrayList(ResolvedValueRefRecord).empty;
        errdefer records.deinit(allocator);

        var local_pattern_roles = try LocalPatternRoleIndex.init(allocator, module, checked_bodies);
        defer local_pattern_roles.deinit(allocator);

        const by_checked_expr = try allocator.alloc(?ResolvedValueRefId, checked_bodies.exprCount());
        errdefer allocator.free(by_checked_expr);
        @memset(by_checked_expr, null);

        var node_idx: u32 = 0;
        while (node_idx < module.nodeCount()) : (node_idx += 1) {
            const tag = module.nodeTag(@enumFromInt(node_idx));
            if (tag == .expr_associated_lookup_local or tag == .expr_associated_lookup) {
                checkedArtifactInvariant("unresolved associated lookup reached resolved value publication", .{});
            }
            if (tag != .expr_var and
                tag != .expr_external_lookup and
                tag != .expr_associated_lookup_resolved and
                tag != .expr_required_lookup) continue;

            const expr_idx: CIR.Expr.Idx = @enumFromInt(node_idx);
            const checked_expr = checked_bodies.exprIdForSource(expr_idx) orelse continue;
            var resolved_ref = try categorizeValueRef(
                allocator,
                module,
                artifact_key,
                expr_idx,
                imports,
                available_artifacts,
                templates,
                hosted_procs,
                platform_required_declarations,
                platform_required_bindings,
                top_level_values,
                hoisted_constants,
                &local_pattern_roles,
                checked_bodies,
            );
            const checked_type_key = try canonical_type_keys.fromVar(
                allocator,
                module.typeStoreConst(),
                module.moduleEnvConst(),
                module.exprType(expr_idx),
            );
            const checked_ty = checked_types.rootForSourceVar(module, module.exprType(expr_idx)) orelse {
                if (builtin.mode == .Debug) {
                    std.debug.panic("checked artifact invariant violated: resolved value ref type root was not published", .{});
                }
                unreachable;
            };
            try attachUseTypePayload(&resolved_ref, checked_type_key, checked_ty);

            const id: ResolvedValueRefId = @enumFromInt(@as(u32, @intCast(records.items.len)));
            try records.append(allocator, .{
                .expr = checked_expr,
                .ref = resolved_ref,
                .checked_ty = checked_ty,
                .scope_depth = 0,
            });
            by_checked_expr[@intFromEnum(checked_expr)] = id;
        }

        try appendSyntheticLocalLookupRefs(
            allocator,
            &records,
            by_checked_expr,
            checked_bodies,
            hoisted_constants,
            synthetic_expr_origins,
        );
        validateAllLookupRefsResolved(checked_bodies, by_checked_expr);

        return .{
            .records = try records.toOwnedSlice(allocator),
            .by_checked_expr = by_checked_expr,
        };
    }

    pub fn lookupIdByCheckedExpr(self: *const ResolvedValueRefTable, expr: CheckedExprId) ?ResolvedValueRefId {
        const raw = @intFromEnum(expr);
        if (raw >= self.by_checked_expr.len) return null;
        return self.by_checked_expr[raw];
    }

    pub fn deinit(self: *ResolvedValueRefTable, allocator: Allocator) void {
        allocator.free(self.template_refs);
        allocator.free(self.by_checked_expr);
        allocator.free(self.records);
        self.* = .{};
    }
};
/// Short name for the resolved checked value table.
pub const ResolvedValueTable = ResolvedValueRefTable;

const CheckedExprDataCategory = enum {
    local_lookup,
    external_lookup,
    required_lookup,
    match_expr,
    other,
};

fn checkedExprDataCategory(tag: std.meta.Tag(CheckedExprData)) CheckedExprDataCategory {
    return switch (tag) {
        .lookup_local => .local_lookup,
        .lookup_external => .external_lookup,
        .lookup_required => .required_lookup,
        .match_ => .match_expr,
        .pending,
        .numeral,
        .str_from_quote,
        .str_segment,
        .str,
        .bytes_literal,
        .list,
        .empty_list,
        .tuple,
        .if_,
        .call,
        .record,
        .empty_record,
        .block,
        .tag,
        .nominal,
        .zero_argument_tag,
        .closure,
        .lambda,
        .binop,
        .unary_minus,
        .unary_not,
        .field_access,
        .dispatch_call,
        .interpolation,
        .structural_eq,
        .structural_hash,
        .method_eq,
        .type_dispatch_call,
        .tuple_access,
        .runtime_error,
        .crash,
        .dbg,
        .expect_err,
        .expect,
        .ellipsis,
        .anno_only,
        .break_,
        .return_,
        .for_,
        .hosted_lambda,
        .run_low_level,
        => .other,
    };
}

fn appendSyntheticLocalLookupRefs(
    allocator: Allocator,
    records: *std.ArrayList(ResolvedValueRefRecord),
    by_checked_expr: []?ResolvedValueRefId,
    checked_bodies: *const CheckedBodyStore,
    hoisted_constants: *const HoistedConstTable,
    synthetic_expr_origins: []const SyntheticExprOriginRecord,
) Allocator.Error!void {
    for (synthetic_expr_origins) |origin_record| {
        switch (origin_record.origin) {
            .pattern_extraction_result_lookup => |origin| {
                const raw_expr = @intFromEnum(origin_record.expr);
                if (raw_expr >= checked_bodies.exprCount()) {
                    checkedArtifactInvariant("synthetic lookup origin referenced an expression out of range", .{});
                }
                if (by_checked_expr[raw_expr] != null) {
                    checkedArtifactInvariant("synthetic lookup origin was resolved more than once", .{});
                }

                const expr = checked_bodies.expr(origin_record.expr);
                if (checkedExprDataCategory(std.meta.activeTag(expr.data)) != .local_lookup) {
                    checkedArtifactInvariant("synthetic lookup origin pointed at a non-lookup expression", .{});
                }
                const lookup = expr.data.lookup_local;
                if (lookup.resolved != null) {
                    checkedArtifactInvariant("synthetic lookup local already had a resolved ref before ref publication", .{});
                }
                if (lookup.pattern != origin.result_pattern) {
                    checkedArtifactInvariant("synthetic lookup origin target did not match lookup pattern", .{});
                }
                const binder = checked_bodies.patternBinderForCheckedPattern(origin.result_pattern) orelse {
                    checkedArtifactInvariant("synthetic lookup local referenced a pattern without a checked binder", .{});
                };
                const hoisted = hoisted_constants.lookupByPattern(origin.result_pattern) orelse {
                    checkedArtifactInvariant("synthetic pattern-extraction lookup had no selected hoisted const entry", .{});
                };

                const id: ResolvedValueRefId = @enumFromInt(@as(u32, @intCast(records.items.len)));
                try records.append(allocator, .{
                    .expr = expr.id,
                    .ref = selectedHoistedConstUse(hoisted, .{ .binder = binder }),
                    .checked_ty = expr.ty,
                    .scope_depth = 0,
                });
                by_checked_expr[raw_expr] = id;
            },
            .pattern_extraction_wrapper => {
                const raw_expr = @intFromEnum(origin_record.expr);
                if (raw_expr >= checked_bodies.exprCount()) {
                    checkedArtifactInvariant("synthetic wrapper origin referenced an expression out of range", .{});
                }
                if (checkedExprDataCategory(std.meta.activeTag(checked_bodies.expr(origin_record.expr).data)) != .match_expr) {
                    checkedArtifactInvariant("synthetic wrapper origin pointed at a non-match expression", .{});
                }
            },
        }
    }
}

fn validateAllLookupRefsResolved(
    checked_bodies: *const CheckedBodyStore,
    by_checked_expr: []const ?ResolvedValueRefId,
) void {
    for (0..checked_bodies.exprCount()) |raw_expr| {
        const expr_id: CheckedExprId = @enumFromInt(@as(u32, @intCast(raw_expr)));
        const expr = checked_bodies.expr(expr_id);
        const is_lookup = switch (checkedExprDataCategory(std.meta.activeTag(expr.data))) {
            .local_lookup, .external_lookup, .required_lookup => true,
            .match_expr, .other => false,
        };
        if (!is_lookup) continue;
        if (raw_expr >= by_checked_expr.len or by_checked_expr[raw_expr] == null) {
            checkedArtifactInvariant("checked lookup expression has no resolved value ref", .{});
        }
    }
}

fn categorizeValueRef(
    _: Allocator,
    module: TypedCIR.Module,
    artifact_key: CheckedModuleArtifactKey,
    expr_idx: CIR.Expr.Idx,
    imports: []const PublishImportArtifact,
    available_artifacts: []const ImportedModuleView,
    _: *const CheckedProcedureTemplateTable,
    hosted_procs: *const HostedProcTable,
    platform_required_declarations: *const PlatformRequiredDeclarationTable,
    platform_required_bindings: *const PlatformRequiredBindingTable,
    top_level_values: *const TopLevelValueTable,
    hoisted_constants: *const HoistedConstTable,
    local_pattern_roles: *const LocalPatternRoleIndex,
    checked_bodies: *const CheckedBodyStore,
) Allocator.Error!ResolvedValueRef {
    const expr = module.expr(expr_idx);
    return switch (expr.data) {
        .e_lookup_local => |local| categorizeLocalValueRef(
            module,
            artifact_key,
            local.pattern_idx,
            hosted_procs,
            top_level_values,
            hoisted_constants,
            local_pattern_roles,
            checked_bodies,
        ),
        .e_lookup_external => |external| categorizeImportedValueRef(
            module,
            external.module_idx,
            external.target_node_idx,
            imports,
        ),
        .e_lookup_associated_resolved => |resolved| categorizeResolvedAssociatedValueRef(
            module,
            artifact_key,
            resolved.module_identity,
            resolved.target_def_idx,
            imports,
            available_artifacts,
            hosted_procs,
            top_level_values,
        ),
        .e_lookup_associated_local, .e_lookup_associated => checkedArtifactInvariant("unresolved associated lookup reached value-ref categorization", .{}),
        .e_lookup_required => |required| categorizeRequiredValueRef(
            required.requires_idx.toU32(),
            platform_required_declarations,
            platform_required_bindings,
        ),
        .e_num,
        .e_frac_f32,
        .e_frac_f64,
        .e_dec,
        .e_dec_small,
        .e_num_from_numeral,
        .e_typed_int,
        .e_typed_frac,
        .e_typed_num_from_numeral,
        .e_str_segment,
        .e_str,
        .e_bytes_literal,
        .e_list,
        .e_empty_list,
        .e_tuple,
        .e_match,
        .e_if,
        .e_call,
        .e_record,
        .e_empty_record,
        .e_block,
        .e_tag,
        .e_nominal,
        .e_nominal_external,
        .e_zero_argument_tag,
        .e_closure,
        .e_lambda,
        .e_binop,
        .e_unary_minus,
        .e_unary_not,
        .e_field_access,
        .e_method_call,
        .e_dispatch_call,
        .e_interpolation,
        .e_structural_eq,
        .e_structural_hash,
        .e_method_eq,
        .e_type_method_call,
        .e_type_dispatch_call,
        .e_tuple_access,
        .e_runtime_error,
        .e_crash,
        .e_dbg,
        .e_expect_err,
        .e_expect,
        .e_ellipsis,
        .e_anno_only,
        .e_derived_method,
        .e_break,
        .e_return,
        .e_for,
        .e_hosted_lambda,
        .e_run_low_level,
        => {
            if (builtin.mode == .Debug) {
                std.debug.panic(
                    "checked artifact invariant violated: expression {d} is not a value reference",
                    .{@intFromEnum(expr_idx)},
                );
            }
            unreachable;
        },
    };
}

fn attachUseTypePayload(
    ref: *ResolvedValueRef,
    key: canonical.CanonicalTypeKey,
    checked_ty: CheckedTypeId,
) Allocator.Error!void {
    switch (ref.*) {
        .top_level_const => |*use| {
            use.requested_source_ty_template = key;
            use.requested_source_ty_payload = checked_ty;
        },
        .imported_const => |*use| {
            use.requested_source_ty_template = key;
            use.requested_source_ty_payload = checked_ty;
        },
        .selected_hoisted_const => |*selected| {
            selected.const_use.requested_source_ty_template = key;
            selected.const_use.requested_source_ty_payload = checked_ty;
        },
        .platform_required_const => |*required| {
            if (required.const_use.requested_source_ty_payload == null) {
                checkedArtifactInvariant("platform-required const use missing relation-owned requested payload", .{});
            }
        },
        .top_level_proc => |*use| {
            use.source_fn_ty_template = key;
            use.source_fn_ty_payload = checked_ty;
        },
        .imported_proc => |*use| {
            use.source_fn_ty_template = key;
            use.source_fn_ty_payload = checked_ty;
        },
        .hosted_proc => |*use| {
            use.source_fn_ty_template = key;
            use.source_fn_ty_payload = checked_ty;
        },
        .platform_required_proc => |*required| {
            if (required.procedure.source_fn_ty_payload == null) {
                checkedArtifactInvariant("platform-required procedure use missing relation-owned requested payload", .{});
            }
        },
        .promoted_top_level_proc => |*use| {
            use.source_fn_ty_template = key;
            use.source_fn_ty_payload = checked_ty;
        },
        .local_param,
        .local_value,
        .local_mutable_version,
        .pattern_binder,
        .local_proc,
        .platform_required_declaration,
        .platform_required_checked_error,
        => {},
    }
}

fn categorizeLocalValueRef(
    module: TypedCIR.Module,
    artifact_key: CheckedModuleArtifactKey,
    pattern: CIR.Pattern.Idx,
    hosted_procs: *const HostedProcTable,
    top_level_values: *const TopLevelValueTable,
    hoisted_constants: *const HoistedConstTable,
    local_pattern_roles: *const LocalPatternRoleIndex,
    checked_bodies: *const CheckedBodyStore,
) ResolvedValueRef {
    const checked_pattern = checked_bodies.patternIdForSource(pattern) orelse {
        if (builtin.mode == .Debug) {
            std.debug.panic(
                "checked artifact invariant violated: local lookup pattern {d} has no checked pattern id",
                .{@intFromEnum(pattern)},
            );
        }
        unreachable;
    };

    if (top_level_values.lookupByPattern(checked_pattern)) |entry| {
        if (entry.pattern != checked_pattern) {
            if (builtin.mode == .Debug) {
                std.debug.panic(
                    "checked artifact invariant violated: top-level pattern index {d} resolved to mismatched entry",
                    .{@intFromEnum(pattern)},
                );
            }
            unreachable;
        }

        return categorizeTopLevelValueRef(module, artifact_key, entry, hosted_procs);
    }

    const binder = checked_bodies.patternBinderForSource(pattern) orelse {
        if (builtin.mode == .Debug) {
            std.debug.panic(
                "checked artifact invariant violated: local lookup pattern {d} has no checked pattern binder",
                .{@intFromEnum(pattern)},
            );
        }
        unreachable;
    };

    if (hoisted_constants.lookupByPattern(checked_pattern)) |hoisted| {
        return selectedHoistedConstUse(hoisted, .{ .binder = binder });
    }

    if (local_pattern_roles.isLambdaArg(pattern)) {
        return .{ .local_param = .{ .binder = binder } };
    }

    if (local_pattern_roles.statementRole(pattern)) |role| {
        switch (role) {
            .mutable_version => return .{ .local_mutable_version = .{ .binder = binder } },
            .local_proc => |expr| return .{ .local_proc = .{ .binder = binder, .expr = expr } },
            .local_value => return .{ .local_value = .{ .binder = binder } },
        }
    }

    if (patternIsBinder(module, pattern)) {
        return .{ .pattern_binder = .{ .binder = binder } };
    }

    if (builtin.mode == .Debug) {
        std.debug.panic(
            "checked artifact invariant violated: local lookup pattern {d} has no categorized binding",
            .{@intFromEnum(pattern)},
        );
    }
    unreachable;
}

fn categorizeTopLevelValueRef(
    module: TypedCIR.Module,
    artifact_key: CheckedModuleArtifactKey,
    entry: TopLevelValueEntry,
    hosted_procs: *const HostedProcTable,
) ResolvedValueRef {
    return switch (entry.value) {
        .const_ref => |const_ref| .{ .top_level_const = .{
            .const_ref = const_ref,
            .requested_source_ty_template = .{},
        } },
        .procedure_binding => |binding| if (hostedProcForDef(hosted_procs, entry.def)) |hosted|
            .{ .hosted_proc = .{
                .binding = .{ .hosted = .{
                    .module_idx = hosted.module_idx,
                    .def = hosted.def_idx,
                    .proc = hosted.proc,
                    .template = hosted.template,
                } },
                .source_fn_ty_template = .{},
                .intrinsic = null,
                .iterator_procedure = null,
                .runtime_result_provenance = null,
            } }
        else
            .{ .top_level_proc = .{
                .binding = .{ .top_level = .{
                    .artifact = artifact_key,
                    .binding = binding,
                } },
                .source_fn_ty_template = .{},
                .intrinsic = intrinsicForProcedureDef(module, entry.def),
                .iterator_procedure = iteratorProcedureForDef(module, entry.def),
                .runtime_result_provenance = runtimeResultProvenanceForProcedureDef(module, entry.def),
            } },
    };
}

fn selectedHoistedConstUse(
    entry: HoistedConstEntry,
    local: LocalBindingRef,
) ResolvedValueRef {
    return .{ .selected_hoisted_const = .{
        .local = local,
        .const_use = .{
            .const_ref = entry.const_ref,
            .requested_source_ty_template = .{},
        },
    } };
}

fn categorizeImportedValueRef(
    module: TypedCIR.Module,
    import_idx: CIR.Import.Idx,
    target_node_idx: u32,
    imports: []const PublishImportArtifact,
) ResolvedValueRef {
    const resolved_module_idx = module.resolvedImportModule(import_idx) orelse {
        if (builtin.mode == .Debug) {
            std.debug.panic(
                "checked artifact invariant violated: external lookup import {d} has no resolved module",
                .{@intFromEnum(import_idx)},
            );
        }
        unreachable;
    };
    const import_artifact = publishImportForModule(imports, resolved_module_idx) orelse {
        if (builtin.mode == .Debug) {
            std.debug.panic(
                "checked artifact invariant violated: external lookup import {d} resolved to module {d} without a published artifact key",
                .{ @intFromEnum(import_idx), resolved_module_idx },
            );
        }
        unreachable;
    };

    const target_def: CIR.Def.Idx = @enumFromInt(@as(u32, @intCast(target_node_idx)));
    if (importedProcedureBindingForDef(import_artifact.view, target_def)) |binding| {
        return .{ .imported_proc = .{
            .binding = .{ .imported = binding.binding },
            .source_fn_ty_template = .{},
            .intrinsic = binding.intrinsic,
            .iterator_procedure = binding.iterator_procedure,
            .runtime_result_provenance = binding.runtime_result_provenance,
        } };
    }

    if (importedConstTemplateForDef(import_artifact.view, target_def)) |const_template| {
        return .{ .imported_const = .{
            .const_ref = const_template.const_ref,
            .requested_source_ty_template = .{},
        } };
    }

    if (builtin.mode == .Debug) {
        std.debug.panic(
            "checked artifact invariant violated: external lookup target {d} in module {d} was not exported by the imported checked artifact",
            .{ target_node_idx, resolved_module_idx },
        );
    }
    unreachable;
}

fn categorizeResolvedAssociatedValueRef(
    module: TypedCIR.Module,
    artifact_key: CheckedModuleArtifactKey,
    module_identity: base.ModuleIdentity.Idx,
    target_def: CIR.Def.Idx,
    imports: []const PublishImportArtifact,
    available_artifacts: []const ImportedModuleView,
    hosted_procs: *const HostedProcTable,
    top_level_values: *const TopLevelValueTable,
) ResolvedValueRef {
    if (module_identity == module.moduleEnvConst().selfModuleIdentity()) {
        const entry = top_level_values.lookupByDef(target_def) orelse
            return checkedArtifactInvariant("resolved local associated lookup target is not a top-level value", .{});
        return categorizeTopLevelValueRef(module, artifact_key, entry, hosted_procs);
    }

    const origin_hash = module.moduleEnvConst().moduleIdentityHash(module_identity);
    const target_view = importedViewForOriginHash(imports, available_artifacts, origin_hash) orelse
        checkedArtifactInvariant("resolved associated lookup target has no available checked artifact", .{});

    if (importedProcedureBindingForDef(target_view, target_def)) |binding| {
        return .{ .imported_proc = .{
            .binding = .{ .imported = binding.binding },
            .source_fn_ty_template = .{},
            .intrinsic = binding.intrinsic,
            .iterator_procedure = binding.iterator_procedure,
            .runtime_result_provenance = binding.runtime_result_provenance,
        } };
    }

    if (importedConstTemplateForDef(target_view, target_def)) |const_template| {
        return .{ .imported_const = .{
            .const_ref = const_template.const_ref,
            .requested_source_ty_template = .{},
        } };
    }

    return checkedArtifactInvariant("resolved associated lookup target was not exported by its checked artifact", .{});
}

fn importedViewForOriginHash(
    imports: []const PublishImportArtifact,
    available_artifacts: []const ImportedModuleView,
    origin_hash: *const base.ModuleIdentity.Hash,
) ?ImportedModuleView {
    var found: ?ImportedModuleView = null;
    for (imports) |import| {
        if (!importedViewIdentityMatches(import.view, origin_hash)) continue;
        found = uniqueImportedView(found, import.view);
    }
    for (available_artifacts) |view| {
        if (!importedViewIdentityMatches(view, origin_hash)) continue;
        found = uniqueImportedView(found, view);
    }
    return found;
}

fn uniqueImportedView(existing: ?ImportedModuleView, next: ImportedModuleView) ImportedModuleView {
    if (existing) |found| {
        if (!checkedArtifactKeyEql(found.key, next.key)) {
            checkedArtifactInvariant("module identity resolved to multiple checked artifacts", .{});
        }
        return found;
    }
    return next;
}

fn importedProcedureBindingForDef(view: ImportedModuleView, def: CIR.Def.Idx) ?ImportedProcedureBindingView {
    for (view.exported_procedure_bindings.bindings) |binding| {
        if (binding.binding.def == def) return binding;
    }
    return null;
}

fn importedConstTemplateForDef(view: ImportedModuleView, def: CIR.Def.Idx) ?ImportedConstTemplateView {
    for (view.exported_const_templates.templates) |template| {
        if (template.def == def) return template;
    }
    return null;
}

fn collectPublishedExportDefs(
    allocator: Allocator,
    module: TypedCIR.Module,
) Allocator.Error![]CIR.Def.Idx {
    const module_env = module.moduleEnvConst();
    var defs = std.ArrayList(CIR.Def.Idx).empty;
    errdefer defs.deinit(allocator);

    const node_count = module.nodeCount();
    const seen = try allocator.alloc(bool, node_count);
    defer allocator.free(seen);
    @memset(seen, false);

    for (module_env.store.sliceDefs(module_env.exports)) |def_idx| {
        try appendPublishedExportDef(allocator, &defs, seen, def_idx);
    }

    var exposed_iter = module_env.common.exposed_items.iterator();
    while (exposed_iter.next()) |entry| {
        const raw_node_idx: u32 = entry.target.valueDefNode() orelse continue;
        if (raw_node_idx >= node_count) {
            if (builtin.mode == .Debug) {
                std.debug.panic(
                    "checked artifact invariant violated: exposed item {s} points at out-of-range node {d}",
                    .{ module_env.getIdent(@bitCast(entry.ident_idx)), raw_node_idx },
                );
            }
            unreachable;
        }

        const node_idx: CIR.Node.Idx = @enumFromInt(raw_node_idx);
        if (module.nodeTag(node_idx) != .def) continue;
        try appendPublishedExportDef(allocator, &defs, seen, @enumFromInt(raw_node_idx));
    }

    return try defs.toOwnedSlice(allocator);
}

fn appendPublishedExportDef(
    allocator: Allocator,
    defs: *std.ArrayList(CIR.Def.Idx),
    seen: []bool,
    def_idx: CIR.Def.Idx,
) Allocator.Error!void {
    const raw = @intFromEnum(def_idx);
    if (raw >= seen.len) {
        if (builtin.mode == .Debug) {
            std.debug.panic(
                "checked artifact invariant violated: published export def {d} is outside the module node store",
                .{raw},
            );
        }
        unreachable;
    }
    if (seen[raw]) return;
    seen[raw] = true;
    try defs.append(allocator, def_idx);
}

fn publishImportForModule(imports: []const PublishImportArtifact, module_idx: u32) ?PublishImportArtifact {
    for (imports) |import_artifact| {
        if (import_artifact.module_idx == module_idx) return import_artifact;
    }
    return null;
}

fn categorizeRequiredValueRef(
    requires_idx: u32,
    platform_required_declarations: *const PlatformRequiredDeclarationTable,
    platform_required_bindings: *const PlatformRequiredBindingTable,
) ResolvedValueRef {
    const binding = platformBindingForRequiredIndex(platform_required_bindings, requires_idx) orelse {
        if (platform_required_bindings.isCheckedError(requires_idx)) {
            return .platform_required_checked_error;
        }
        const declaration = platform_required_declarations.lookupByRequiredIndex(requires_idx) orelse {
            if (builtin.mode == .Debug) {
                std.debug.panic(
                    "checked artifact invariant violated: required lookup {d} has no platform declaration",
                    .{requires_idx},
                );
            }
            unreachable;
        };
        return .{ .platform_required_declaration = declaration.id };
    };

    return switch (binding.value_use) {
        .const_value => |const_use| .{ .platform_required_const = .{
            .binding = binding.id,
            .const_use = const_use.const_use,
        } },
        .procedure_value => |procedure_use| .{ .platform_required_proc = .{
            .binding = binding.id,
            .procedure = procedure_use.procedure,
            .root_evidence = procedure_use.root_evidence,
        } },
    };
}

const TopLevelDefPatternIndex = struct {
    by_pattern: []?CIR.Def.Idx = &.{},

    fn init(allocator: Allocator, module: TypedCIR.Module) Allocator.Error!TopLevelDefPatternIndex {
        const by_pattern = try allocator.alloc(?CIR.Def.Idx, module.nodeCount());
        @memset(by_pattern, null);
        const module_env = module.moduleEnvConst();
        for (module_env.store.sliceDefs(module_env.global_value_defs)) |def_idx| {
            by_pattern[@intFromEnum(module.def(def_idx).pattern.idx)] = def_idx;
        }
        return .{ .by_pattern = by_pattern };
    }

    fn defForPattern(self: *const TopLevelDefPatternIndex, pattern: CIR.Pattern.Idx) ?CIR.Def.Idx {
        const raw = @intFromEnum(pattern);
        if (raw >= self.by_pattern.len) return null;
        return self.by_pattern[raw];
    }

    fn deinit(self: *TopLevelDefPatternIndex, allocator: Allocator) void {
        allocator.free(self.by_pattern);
        self.* = .{};
    }
};

fn checkedPatternSourceTypeVar(module: TypedCIR.Module, top_level_defs: *const TopLevelDefPatternIndex, pattern: CIR.Pattern.Idx) Var {
    if (top_level_defs.defForPattern(pattern)) |def_idx| {
        return module.defType(def_idx);
    }
    return module.patternType(pattern);
}

fn hostedProcForDef(table: *const HostedProcTable, def_idx: CIR.Def.Idx) ?HostedProc {
    for (table.procs) |proc| {
        if (proc.def_idx == def_idx) return proc;
    }
    return null;
}

fn platformBindingForRequiredIndex(table: *const PlatformRequiredBindingTable, requires_idx: u32) ?PlatformRequiredBinding {
    return table.lookupByRequiredIndex(requires_idx);
}

const LocalPatternStatementRole = union(enum) {
    mutable_version,
    local_proc: CheckedExprId,
    local_value,
};

const LocalPatternRoleIndex = struct {
    lambda_args: []bool = &.{},
    statement_roles: []?LocalPatternStatementRole = &.{},

    fn init(
        allocator: Allocator,
        module: TypedCIR.Module,
        checked_bodies: *const CheckedBodyStore,
    ) Allocator.Error!LocalPatternRoleIndex {
        const node_count = module.nodeCount();
        const lambda_args = try allocator.alloc(bool, node_count);
        errdefer allocator.free(lambda_args);
        const statement_roles = try allocator.alloc(?LocalPatternStatementRole, node_count);
        errdefer allocator.free(statement_roles);
        @memset(lambda_args, false);
        @memset(statement_roles, null);

        var node_idx: u32 = 0;
        while (node_idx < node_count) : (node_idx += 1) {
            const node: CIR.Node.Idx = @enumFromInt(node_idx);
            const node_tag = module.nodeTag(node);
            if (node_tag == .statement_decl) {
                const statement: CIR.Statement.Idx = @enumFromInt(node_idx);
                if (checked_bodies.source_node_map.statement(statement) == null) continue;
                const statement_data = module.getStatement(statement);
                if (statement_data != .s_decl) unreachable;
                const decl = statement_data.s_decl;
                const role: LocalPatternStatementRole = if (isLocalProcExpr(module, decl.expr))
                    .{ .local_proc = checked_bodies.exprIdForSource(decl.expr) orelse
                        checkedArtifactInvariant("checked local procedure declaration has no checked expression", .{}) }
                else
                    .local_value;
                putStatementRole(statement_roles, node_count, decl.pattern, role);
            } else if (node_tag == .statement_var) {
                const statement: CIR.Statement.Idx = @enumFromInt(node_idx);
                if (checked_bodies.source_node_map.statement(statement) == null) continue;
                const statement_data = module.getStatement(statement);
                if (statement_data != .s_var) unreachable;
                putStatementRole(statement_roles, node_count, statement_data.s_var.pattern_idx, .mutable_version);
            } else if (node_tag == .statement_var_uninitialized) {
                const statement: CIR.Statement.Idx = @enumFromInt(node_idx);
                if (checked_bodies.source_node_map.statement(statement) == null) continue;
                const statement_data = module.getStatement(statement);
                if (statement_data != .s_var_uninitialized) unreachable;
                putStatementRole(statement_roles, node_count, statement_data.s_var_uninitialized.pattern_idx, .mutable_version);
            } else if (node_tag == .expr_lambda) {
                const expr_idx: CIR.Expr.Idx = @enumFromInt(node_idx);
                if (checked_bodies.exprIdForSource(expr_idx) == null) continue;
                const expr = module.expr(@enumFromInt(node_idx));
                if (expr.data != .e_lambda) unreachable;
                for (module.slicePatterns(expr.data.e_lambda.args)) |arg| {
                    const raw_pattern = @intFromEnum(arg);
                    if (raw_pattern >= node_count) {
                        checkedArtifactInvariant("checked artifact invariant violated: lambda argument pattern is out of range", .{});
                    }
                    lambda_args[raw_pattern] = true;
                }
            }
        }

        verifyLocalPatternRoles(lambda_args, statement_roles);

        return .{
            .lambda_args = lambda_args,
            .statement_roles = statement_roles,
        };
    }

    fn putStatementRole(
        statement_roles: []?LocalPatternStatementRole,
        node_count: usize,
        pattern: CIR.Pattern.Idx,
        role: LocalPatternStatementRole,
    ) void {
        const raw_pattern = @intFromEnum(pattern);
        if (raw_pattern >= node_count) {
            checkedArtifactInvariant("checked artifact invariant violated: local statement pattern is out of range", .{});
        }
        if (statement_roles[raw_pattern]) |existing| {
            if (!localPatternStatementRoleEql(existing, role)) {
                checkedArtifactInvariant("checked artifact invariant violated: local statement pattern has conflicting roles", .{});
            }
            return;
        }
        statement_roles[raw_pattern] = role;
    }

    fn localPatternStatementRoleEql(a: LocalPatternStatementRole, b: LocalPatternStatementRole) bool {
        if (std.meta.activeTag(a) != std.meta.activeTag(b)) return false;
        return switch (a) {
            .mutable_version,
            .local_value,
            => true,
            .local_proc => |a_expr| a_expr == b.local_proc,
        };
    }

    fn verifyLocalPatternRoles(
        lambda_args: []const bool,
        statement_roles: []const ?LocalPatternStatementRole,
    ) void {
        if (builtin.mode != .Debug) return;

        for (lambda_args, statement_roles, 0..) |is_lambda_arg, maybe_statement_role, raw_pattern| {
            if (is_lambda_arg and maybe_statement_role != null) {
                std.debug.panic(
                    "checked artifact invariant violated: local pattern {d} is both a lambda argument and statement binding",
                    .{raw_pattern},
                );
            }
        }
    }

    fn isLambdaArg(self: *const LocalPatternRoleIndex, pattern: CIR.Pattern.Idx) bool {
        const raw = @intFromEnum(pattern);
        if (raw >= self.lambda_args.len) {
            checkedArtifactInvariant("checked artifact invariant violated: lambda argument lookup pattern is out of range", .{});
        }
        return self.lambda_args[raw];
    }

    fn statementRole(self: *const LocalPatternRoleIndex, pattern: CIR.Pattern.Idx) ?LocalPatternStatementRole {
        const raw = @intFromEnum(pattern);
        if (raw >= self.statement_roles.len) {
            checkedArtifactInvariant("checked artifact invariant violated: local statement lookup pattern is out of range", .{});
        }
        return self.statement_roles[raw];
    }

    fn deinit(self: *LocalPatternRoleIndex, allocator: Allocator) void {
        allocator.free(self.statement_roles);
        allocator.free(self.lambda_args);
        self.* = .{};
    }
};

fn patternIsBinder(module: TypedCIR.Module, pattern: CIR.Pattern.Idx) bool {
    const raw = @intFromEnum(pattern);
    if (raw >= module.nodeCount()) {
        checkedArtifactInvariant("checked artifact invariant violated: binder lookup pattern is out of range", .{});
    }
    const tag = module.nodeTag(@enumFromInt(raw));
    return tag == .pattern_identifier or
        tag == .pattern_as or
        tag == .pattern_applied_tag or
        tag == .pattern_nominal or
        tag == .pattern_nominal_external or
        tag == .pattern_record_destructure or
        tag == .pattern_list or
        tag == .pattern_tuple;
}

fn isLocalProcExpr(module: TypedCIR.Module, expr_idx: CIR.Expr.Idx) bool {
    const expr = module.expr(expr_idx);
    return expr.data == .e_lambda or expr.data == .e_closure;
}

/// A generalized local function scope collected while walking template
/// bodies: `constraint(depth, k)` resolutions index the innermost enclosing
/// scope's canonical evidence params at depth 0, walking outward to the
/// template's own params.
pub const DispatchRefScope = struct {
    /// Enclosing generalized-local scope, or `null` for the template itself.
    parent: ?DispatchScopeId,
    /// The local function's scheme root var (its decl pattern var).
    scheme_var: Var,
    /// Published checked root of `scheme_var`; specialization evidence paths
    /// are authored relative to this exact callable shape.
    scheme_root: CheckedTypeId,
    /// Checked local-function expression that owns this scope.
    checked_expr: CheckedExprId,
    /// The scope's ordered dispatch requirements in the shared params pool.
    evidence_params: artifact_serialize.Span = .{},
};

/// Stable identity of a generalized-local dispatch scope within a checked
/// module artifact.
pub const DispatchScopeId = checked_ids.DispatchScopeId;

/// Scope owning a checked dispatch reference. The template root is a real
/// variant, never an integer value that can be mistaken for a local scope id.
pub const DispatchScope = union(enum) {
    root,
    generalized: DispatchScopeId,
};

/// Checked relation shape Monotype must instantiate before specializing the
/// scope that owns a dispatch reference.
pub const DispatchRelationKind = enum(u8) {
    callable_result,
    conversion,
};

/// A checker-authored type relation needed to close a procedure interface
/// before Monotype chooses a specialization identity. These records contain
/// no executable-body semantics: they preserve checked equalities, procedure
/// results, ordinary call edges, and generalized local-procedure
/// instantiations.
pub const SpecializationInterfaceRelation = struct {
    scope: DispatchScope,
    data: Data,

    pub const Data = union(enum) {
        type_equality: struct {
            left: CheckedTypeId,
            right: CheckedTypeId,
        },
        procedure: struct {
            fn_ty: CheckedTypeId,
            body_ret_ty: CheckedTypeId,
            owns_scope: bool,
        },
        call: struct {
            callable_ty: CheckedTypeId,
            callee_ty: CheckedTypeId,
            ret_ty: CheckedTypeId,
            args: artifact_serialize.Span,
            direct_target: ?ResolvedValueRefId,
        },
        local_proc_use: ResolvedValueRefId,
    };
};

const CollectedSchemeUseSite = struct {
    record_idx: u32,
    checked_expr: CheckedExprId,
};

const CollectedScopeConstructionSite = struct {
    scope: DispatchScopeId,
    checked_expr: CheckedExprId,
};

/// Build-time-only per-template data collected by
/// `sealCheckedProcedureTemplateRefs` for the total-resolution pass; never
/// serialized (mono looks iterator plans up by node and receives evidence
/// chains from its requesting edges).
const TemplateIteratorRefs = struct {
    /// Parallel to `templates.templates`; each span indexes `pool`.
    spans: []artifact_serialize.Span = &.{},
    pool: []static_dispatch.IteratorForPlanId = &.{},
    /// Generalized-local-function scopes, pooled across templates.
    scopes: []DispatchRefScope = &.{},
    /// Scope of each collected dispatch plan ref (parallel to
    /// `StaticDispatchPlanTable.template_refs`).
    plan_scopes: []DispatchScope = &.{},
    /// Scope of each collected value ref (parallel to
    /// `ResolvedValueRefTable.template_refs`).
    value_ref_scopes: []DispatchScope = &.{},
    /// Scope of each collected iterator plan ref (parallel to `pool`).
    iterator_scopes: []DispatchScope = &.{},
    /// Expression-position function instantiation sites, grouped per template.
    scheme_use_spans: []artifact_serialize.Span = &.{},
    scheme_use_sites: []CollectedSchemeUseSite = &.{},
    /// Scope of each collected scheme-use site (parallel to
    /// `scheme_use_sites`).
    scheme_use_scopes: []DispatchScope = &.{},
    /// Generalized nested-procedure construction sites, grouped per template.
    scope_site_spans: []artifact_serialize.Span = &.{},
    scope_sites: []CollectedScopeConstructionSite = &.{},

    fn deinit(self: *TemplateIteratorRefs, allocator: Allocator) void {
        allocator.free(self.spans);
        allocator.free(self.pool);
        allocator.free(self.scopes);
        allocator.free(self.plan_scopes);
        allocator.free(self.value_ref_scopes);
        allocator.free(self.iterator_scopes);
        allocator.free(self.scheme_use_spans);
        allocator.free(self.scheme_use_sites);
        allocator.free(self.scheme_use_scopes);
        allocator.free(self.scope_site_spans);
        allocator.free(self.scope_sites);
        self.* = .{};
    }
};

fn sealCheckedProcedureTemplateRefs(
    allocator: Allocator,
    module: TypedCIR.Module,
    checked_types: *const CheckedTypePublication,
    checked_bodies: *const CheckedBodyStore,
    entry_wrappers: *const EntryWrapperTable,
    templates: *CheckedProcedureTemplateTable,
    static_dispatch_plans: *static_dispatch.StaticDispatchPlanTable,
    method_registry: *static_dispatch.MethodRegistry,
    resolved_value_refs: *ResolvedValueRefTable,
    template_iterator_refs: *TemplateIteratorRefs,
) Allocator.Error!void {
    // Generalized local functions with dispatch obligations: entering one
    // while collecting pushes an evidence scope. Declarations map to their
    // pattern scheme; expression-position functions stored in a containing
    // value map to the pristine scheme instantiated at that construction edge.
    var local_schemes = std.AutoHashMap(u32, Var).init(allocator);
    defer local_schemes.deinit();
    var nested_function_uses = std.AutoHashMap(u32, u32).init(allocator);
    defer nested_function_uses.deinit();
    {
        const types_store = module.typeStoreConst();

        var raw_node: u32 = 0;
        while (raw_node < module.nodeCount()) : (raw_node += 1) {
            if (module.nodeTag(@enumFromInt(raw_node)) != .statement_decl) continue;
            const statement: CIR.Statement.Idx = @enumFromInt(raw_node);
            const statement_data = module.getStatement(statement);
            if (statement_data != .s_decl) continue;
            const decl = statement_data.s_decl;
            const expr_data = module.expr(decl.expr).data;
            if (expr_data != .e_lambda and expr_data != .e_closure) continue;
            const pattern_var = ModuleEnv.varFrom(decl.pattern);
            if (types_store.resolveVar(pattern_var).desc.rank != .generalized) continue;
            const checked_expr = checked_bodies.exprIdForSource(decl.expr) orelse continue;
            try local_schemes.put(@intFromEnum(checked_expr), pattern_var);
        }

        for (module.moduleEnvConst().scheme_uses.items.items, 0..) |record, record_idx| {
            if (record.slot_kind != @intFromEnum(ModuleEnv.SchemeUseRecord.Slot.nested_function_use)) continue;
            const checked_expr = checked_bodies.exprIdForSource(@enumFromInt(record.node_idx)) orelse continue;
            try local_schemes.put(@intFromEnum(checked_expr), @enumFromInt(record.scheme_root));
            try nested_function_uses.put(@intFromEnum(checked_expr), @intCast(record_idx));
        }
    }

    var collector = CheckedTemplateRefCollector.init(
        allocator,
        module,
        checked_types,
        checked_bodies,
        static_dispatch_plans,
        &local_schemes,
        &nested_function_uses,
    );
    defer collector.deinit();

    // Flatten each template's collected refs into the two shared per-table pools,
    // recording each template's sub-range. Growing the pools as lists keeps the pass
    // amortized-O(1) per template; both tables then take ownership of the finished
    // pool as a single slice.
    var value_ref_pool = std.ArrayList(ResolvedValueRefId).empty;
    errdefer value_ref_pool.deinit(allocator);
    var dispatch_ref_pool = std.ArrayList(static_dispatch.StaticDispatchPlanId).empty;
    errdefer dispatch_ref_pool.deinit(allocator);
    var iterator_ref_pool = std.ArrayList(static_dispatch.IteratorForPlanId).empty;
    errdefer iterator_ref_pool.deinit(allocator);
    var value_ref_scope_pool = std.ArrayList(DispatchScope).empty;
    errdefer value_ref_scope_pool.deinit(allocator);
    var dispatch_ref_scope_pool = std.ArrayList(DispatchScope).empty;
    errdefer dispatch_ref_scope_pool.deinit(allocator);
    var dispatch_relation_kind_pool = std.ArrayList(DispatchRelationKind).empty;
    errdefer dispatch_relation_kind_pool.deinit(allocator);
    var iterator_scope_pool = std.ArrayList(DispatchScope).empty;
    errdefer iterator_scope_pool.deinit(allocator);
    var scheme_use_pool = std.ArrayList(CollectedSchemeUseSite).empty;
    errdefer scheme_use_pool.deinit(allocator);
    var scheme_use_scope_pool = std.ArrayList(DispatchScope).empty;
    errdefer scheme_use_scope_pool.deinit(allocator);
    var scope_site_pool = std.ArrayList(CollectedScopeConstructionSite).empty;
    errdefer scope_site_pool.deinit(allocator);
    var specialization_relation_pool = std.ArrayList(SpecializationInterfaceRelation).empty;
    errdefer specialization_relation_pool.deinit(allocator);
    var specialization_type_pool = std.ArrayList(CheckedTypeId).empty;
    errdefer specialization_type_pool.deinit(allocator);
    const iterator_spans = try allocator.alloc(artifact_serialize.Span, templates.templates.len);
    errdefer allocator.free(iterator_spans);
    const scheme_use_spans = try allocator.alloc(artifact_serialize.Span, templates.templates.len);
    errdefer allocator.free(scheme_use_spans);
    const scope_site_spans = try allocator.alloc(artifact_serialize.Span, templates.templates.len);
    errdefer allocator.free(scope_site_spans);

    for (templates.templates, 0..) |*template, template_index| {
        collector.clear();

        switch (template.body) {
            .checked_body => |body_id| {
                const body = checked_bodies.body(body_id);
                collector.template_root_expr = body.root_expr;
                try collector.collectExpr(body.root_expr);
            },
            .entry_wrapper => |wrapper_id| {
                const wrapper = entry_wrappers.get(wrapper_id);
                try collector.collectExpr(wrapper.body_expr);
                try collector.appendProcedureRelation(
                    wrapper.body_expr,
                    template.checked_fn_root,
                    checked_bodies.expr(wrapper.body_expr).ty,
                    true,
                );
            },
            .intrinsic_wrapper => {},
        }

        var seen_local_uses = collections.DenseMap(ResolvedValueRefId, void).init(allocator);
        defer seen_local_uses.deinit();
        for (collector.value_refs.items, collector.value_ref_scopes.items) |ref_id, use_scope| {
            const seen = try seen_local_uses.getOrPut(ref_id);
            if (seen.found_existing) continue;
            const record = resolved_value_refs.records[@intFromEnum(ref_id)];
            if (checked_bodies.exprContainsDiagnosticError(record.expr)) continue;
            try collector.specialization_relations.append(allocator, .{
                .scope = use_scope,
                .data = .{ .type_equality = .{
                    .left = record.checked_ty,
                    .right = checked_bodies.expr(record.expr).ty,
                } },
            });
            const local = switch (record.ref) {
                .local_param,
                .local_value,
                .local_mutable_version,
                .pattern_binder,
                => |binding| {
                    const binder_pattern = checked_bodies.patternBinder(binding.binder).pattern;
                    try collector.specialization_relations.append(allocator, .{
                        .scope = use_scope,
                        .data = .{ .type_equality = .{
                            .left = record.checked_ty,
                            .right = checked_bodies.pattern(binder_pattern).ty,
                        } },
                    });
                    continue;
                },
                .local_proc => |local| local,
                .selected_hoisted_const,
                .top_level_const,
                .imported_const,
                .top_level_proc,
                .imported_proc,
                .hosted_proc,
                .platform_required_declaration,
                .platform_required_checked_error,
                .platform_required_const,
                .platform_required_proc,
                .promoted_top_level_proc,
                => continue,
            };
            if (collector.scope_by_checked_expr.get(local.expr) == null) {
                try collector.specialization_relations.append(allocator, .{
                    .scope = use_scope,
                    .data = .{ .type_equality = .{
                        .left = record.checked_ty,
                        .right = checked_bodies.expr(local.expr).ty,
                    } },
                });
                continue;
            }
            try collector.specialization_relations.append(allocator, .{
                .scope = use_scope,
                .data = .{ .local_proc_use = ref_id },
            });
        }

        template.resolved_value_refs = try artifact_serialize.appendSpan(ResolvedValueRefTableRef, ResolvedValueRefId, &value_ref_pool, allocator, collector.value_refs.items);
        template.static_dispatch_plans = try artifact_serialize.appendSpan(@TypeOf(template.static_dispatch_plans), static_dispatch.StaticDispatchPlanId, &dispatch_ref_pool, allocator, collector.dispatch_refs.items);
        const specialization_type_base: u32 = @intCast(specialization_type_pool.items.len);
        try specialization_type_pool.appendSlice(allocator, collector.specialization_types.items);
        const specialization_relation_start: u32 = @intCast(specialization_relation_pool.items.len);
        try specialization_relation_pool.ensureUnusedCapacity(allocator, collector.specialization_relations.items.len);
        for (collector.specialization_relations.items) |raw_relation| {
            var relation = raw_relation;
            switch (relation.data) {
                .call => |*call| call.args.start += specialization_type_base,
                .type_equality, .procedure, .local_proc_use => {},
            }
            specialization_relation_pool.appendAssumeCapacity(relation);
        }
        template.specialization_interface_relations = .{
            .start = specialization_relation_start,
            .len = @intCast(collector.specialization_relations.items.len),
        };
        for (collector.dispatch_refs.items) |plan_id| {
            const plan = static_dispatch_plans.plans[@intFromEnum(plan_id)];
            var kind: DispatchRelationKind = .callable_result;
            for (plan.argsSlice(static_dispatch_plans)) |operand| switch (operand) {
                .generated_numeral, .generated_quote => kind = .conversion,
                .checked_expr, .generated_interpolation_iter => {},
            };
            try dispatch_relation_kind_pool.append(allocator, kind);
        }
        iterator_spans[template_index] = try artifact_serialize.appendSpan(artifact_serialize.Span, static_dispatch.IteratorForPlanId, &iterator_ref_pool, allocator, collector.iterator_refs.items);
        scheme_use_spans[template_index] = try artifact_serialize.appendSpan(artifact_serialize.Span, CollectedSchemeUseSite, &scheme_use_pool, allocator, collector.scheme_use_sites.items);
        scope_site_spans[template_index] = try artifact_serialize.appendSpan(artifact_serialize.Span, CollectedScopeConstructionSite, &scope_site_pool, allocator, collector.scope_sites.items);
        try value_ref_scope_pool.appendSlice(allocator, collector.value_ref_scopes.items);
        try dispatch_ref_scope_pool.appendSlice(allocator, collector.dispatch_ref_scopes.items);
        try iterator_scope_pool.appendSlice(allocator, collector.iterator_ref_scopes.items);
        try scheme_use_scope_pool.appendSlice(allocator, collector.scheme_use_scopes.items);
    }

    resolved_value_refs.template_refs = try value_ref_pool.toOwnedSlice(allocator);
    static_dispatch_plans.template_refs = try dispatch_ref_pool.toOwnedSlice(allocator);
    templates.dispatch_ref_scopes = try allocator.dupe(DispatchScope, dispatch_ref_scope_pool.items);
    templates.dispatch_relation_kinds = try dispatch_relation_kind_pool.toOwnedSlice(allocator);
    templates.dispatch_scopes = try allocator.dupe(DispatchRefScope, collector.scopes.items);
    templates.specialization_interface_relations = try specialization_relation_pool.toOwnedSlice(allocator);
    templates.specialization_interface_types = try specialization_type_pool.toOwnedSlice(allocator);
    publishLocalProcedureDispatchScopes(resolved_value_refs, &collector.scope_by_checked_expr);
    publishLocalMethodDispatchScopes(method_registry, &collector.scope_by_checked_expr);
    template_iterator_refs.* = .{
        .spans = iterator_spans,
        .pool = try iterator_ref_pool.toOwnedSlice(allocator),
        .scopes = try allocator.dupe(DispatchRefScope, collector.scopes.items),
        .plan_scopes = try dispatch_ref_scope_pool.toOwnedSlice(allocator),
        .value_ref_scopes = try value_ref_scope_pool.toOwnedSlice(allocator),
        .iterator_scopes = try iterator_scope_pool.toOwnedSlice(allocator),
        .scheme_use_spans = scheme_use_spans,
        .scheme_use_sites = try scheme_use_pool.toOwnedSlice(allocator),
        .scheme_use_scopes = try scheme_use_scope_pool.toOwnedSlice(allocator),
        .scope_site_spans = scope_site_spans,
        .scope_sites = try scope_site_pool.toOwnedSlice(allocator),
    };
}

/// Attach the producer-owned dispatch scope identity to every use of a local
/// procedure. A generalized local procedure may own a scope even when its
/// checker-ordered evidence list is empty, so presence is determined by the checked
/// scope table rather than by evidence count.
fn publishLocalProcedureDispatchScopes(
    resolved_value_refs: *ResolvedValueRefTable,
    scope_by_checked_expr: *const collections.DenseMap(CheckedExprId, DispatchScopeId),
) void {
    for (resolved_value_refs.records) |*record| {
        if (record.ref != .local_proc) continue;
        const local = &record.ref.local_proc;

        local.dispatch_scope = scope_by_checked_expr.get(local.expr);
    }
}

fn publishLocalMethodDispatchScopes(
    method_registry: *static_dispatch.MethodRegistry,
    scope_by_checked_expr: *const collections.DenseMap(CheckedExprId, DispatchScopeId),
) void {
    for (method_registry.entries) |*entry| {
        if (entry.target.kind != .local_proc) continue;
        const local = &entry.target.kind.local_proc;

        local.dispatch_scope = scope_by_checked_expr.get(local.expr);
    }
}

/// Resolve every static-dispatch plan and instantiation-site obligation to an
/// explicit `direct` / `constraint(k)` / `structural` / `checked_error`
/// resolution, and publish each template's evidence params.
///
/// Runs after `sealCheckedProcedureTemplateRefs` so plans and value refs are
/// grouped per template: `constraint(k)` indexes the enclosing template's
/// canonical evidence-param list. Concrete dispatchers resolve through the
/// checked registry; where-var dispatchers resolve to their param index;
/// evidence for call edges comes from the checker's persisted
/// `SchemeUseRecord`s, whose fresh vars are resolved against the
/// settled type store.
const EvidencePass = struct {
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    checked_types: *const CheckedTypePublication,
    checked_bodies: *const CheckedBodyStore,
    local_method_registry: *const static_dispatch.MethodRegistry,
    import_views: CheckedImportViews,
    plan_table: *static_dispatch.StaticDispatchPlanTable,
    templates: *CheckedProcedureTemplateTable,
    resolved_value_refs: *const ResolvedValueRefTable,
    build_data: *const static_dispatch.PlanTableBuildData,
    template_iterator_refs: *const TemplateIteratorRefs,
    entry_wrappers: *const EntryWrapperTable,
    compile_time_roots: *const CompileTimeRootTable,
    platform_requirement_solutions: []const requirement_solution.SolutionInput,
    platform_requirement_root_evidence: []artifact_serialize.Span,
    template_root_evidence: []artifact_serialize.Span,

    types: *const types.Store,

    /// Value-use record index by source node, including explicit shared uses.
    value_use_by_node: std.AutoHashMap(u32, u32),
    /// dispatch_target record index by the discharged edge's raw fn var.
    target_by_fn_var: std.AutoHashMap(u32, u32),
    /// Source node by checked expr (reverse of `exprIdForSource`).
    source_by_checked_expr: std.AutoHashMap(u32, u32),
    /// Generalized local VALUE decls (non-lambda exprs, e.g. an `if` choosing
    /// between closures): scheme param var root -> decl pattern. Monotype
    /// lowers such decls inline at the single type their uses unify to, so a
    /// body plan's obligation resolves through a representative use record.
    local_value_scheme_by_var: std.AutoHashMap(u32, u32),
    /// First value_use record per looked-up pattern.
    value_use_record_by_pattern: std.AutoHashMap(u32, u32),
    /// Memoized evidence node per dispatch_target record.
    node_by_record: std.AutoHashMap(u32, static_dispatch.EvidenceNodeId),
    /// Hash buckets and collision chains for structurally interned evidence
    /// nodes. Every durable `EvidenceNodeId` is therefore an exact evidence
    /// identity, independent of which checker record requested it.
    evidence_node_buckets: std.AutoHashMap(u64, static_dispatch.EvidenceNodeId),
    evidence_node_next: std.ArrayList(?static_dispatch.EvidenceNodeId),
    record_in_progress: std.AutoHashMap(u32, void),
    /// Site-evidence dedupe (a checked expr can be reachable from two
    /// templates, e.g. a const body and its entry wrapper).
    site_seen: std.AutoHashMap(u32, void),

    evidence_nodes: std.ArrayList(static_dispatch.EvidenceNode),
    evidence_refs: std.ArrayList(static_dispatch.CheckedEvidence),
    site_evidence: std.ArrayList(static_dispatch.SiteEvidenceEntry),
    evidence_params_pool: std.ArrayList(static_dispatch.EvidenceParamRecord),
    evidence_param_paths: std.ArrayList(static_dispatch.EvidencePathStep),

    enum_scratch: dispatch_evidence.Scratch,
    /// Canonical evidence params per collected local-function scope,
    /// enumerated on demand (slices owned by the pass).
    scope_params: collections.DenseMap(DispatchScopeId, []EvidenceParam),
    /// Scratch backing for the chain currently being resolved against.
    chain_scratch: std.ArrayList([]const EvidenceParam),
    /// Per-plan / per-iterator-plan visited flags: a plan reachable from two
    /// templates (const body + entry wrapper) resolves once, and the final
    /// sweep resolves whatever no template reached (chain-free).
    plan_resolved: []bool = &.{},
    iterator_plan_resolved: []bool = &.{},
    /// Explicit shared-var use records deferred during template walks because
    /// the current chain did not bind every obligation.
    deferred_use_sites: std.ArrayListUnmanaged(struct { record_idx: u32, site_key: u32 }) = .empty,
    /// The param chain in scope while resolving a site's evidence entries, so
    /// a fresh var that settled onto an enclosing where-var forwards as
    /// `constraint(depth, k)`. Index 0 is the innermost generalized callable.
    current_chain: []const []const EvidenceParam = &.{},

    const EvidenceParam = dispatch_evidence.EvidenceParam;

    fn init(
        allocator: Allocator,
        module: TypedCIR.Module,
        names: *canonical.CanonicalNameStore,
        checked_types: *const CheckedTypePublication,
        checked_bodies: *const CheckedBodyStore,
        local_method_registry: *const static_dispatch.MethodRegistry,
        import_views: CheckedImportViews,
        plan_table: *static_dispatch.StaticDispatchPlanTable,
        templates: *CheckedProcedureTemplateTable,
        resolved_value_refs: *const ResolvedValueRefTable,
        build_data: *const static_dispatch.PlanTableBuildData,
        template_iterator_refs: *const TemplateIteratorRefs,
        entry_wrappers: *const EntryWrapperTable,
        compile_time_roots: *const CompileTimeRootTable,
        platform_requirement_solutions: []const requirement_solution.SolutionInput,
        platform_requirement_root_evidence: []artifact_serialize.Span,
        template_root_evidence: []artifact_serialize.Span,
    ) EvidencePass {
        if (platform_requirement_solutions.len != platform_requirement_root_evidence.len) {
            checkedArtifactInvariant("platform requirement solutions and root evidence output had different lengths", .{});
        }
        return .{
            .allocator = allocator,
            .module = module,
            .names = names,
            .checked_types = checked_types,
            .checked_bodies = checked_bodies,
            .local_method_registry = local_method_registry,
            .import_views = import_views,
            .plan_table = plan_table,
            .templates = templates,
            .resolved_value_refs = resolved_value_refs,
            .build_data = build_data,
            .template_iterator_refs = template_iterator_refs,
            .entry_wrappers = entry_wrappers,
            .compile_time_roots = compile_time_roots,
            .platform_requirement_solutions = platform_requirement_solutions,
            .platform_requirement_root_evidence = platform_requirement_root_evidence,
            .template_root_evidence = template_root_evidence,
            .types = module.typeStoreConst(),
            .value_use_by_node = std.AutoHashMap(u32, u32).init(allocator),
            .target_by_fn_var = std.AutoHashMap(u32, u32).init(allocator),
            .source_by_checked_expr = std.AutoHashMap(u32, u32).init(allocator),
            .local_value_scheme_by_var = std.AutoHashMap(u32, u32).init(allocator),
            .value_use_record_by_pattern = std.AutoHashMap(u32, u32).init(allocator),
            .node_by_record = std.AutoHashMap(u32, static_dispatch.EvidenceNodeId).init(allocator),
            .evidence_node_buckets = std.AutoHashMap(u64, static_dispatch.EvidenceNodeId).init(allocator),
            .evidence_node_next = .empty,
            .record_in_progress = std.AutoHashMap(u32, void).init(allocator),
            .site_seen = std.AutoHashMap(u32, void).init(allocator),
            .evidence_nodes = .empty,
            .evidence_refs = .empty,
            .site_evidence = .empty,
            .evidence_params_pool = .empty,
            .evidence_param_paths = .empty,
            .enum_scratch = .{},
            .scope_params = collections.DenseMap(DispatchScopeId, []EvidenceParam).init(allocator),
            .chain_scratch = .empty,
        };
    }

    fn deinit(self: *EvidencePass) void {
        self.allocator.free(self.plan_resolved);
        self.allocator.free(self.iterator_plan_resolved);
        self.deferred_use_sites.deinit(self.allocator);
        self.value_use_by_node.deinit();
        self.target_by_fn_var.deinit();
        self.source_by_checked_expr.deinit();
        self.local_value_scheme_by_var.deinit();
        self.value_use_record_by_pattern.deinit();
        self.node_by_record.deinit();
        self.evidence_node_buckets.deinit();
        self.evidence_node_next.deinit(self.allocator);
        self.record_in_progress.deinit();
        self.site_seen.deinit();
        self.evidence_nodes.deinit(self.allocator);
        self.evidence_refs.deinit(self.allocator);
        self.site_evidence.deinit(self.allocator);
        self.evidence_params_pool.deinit(self.allocator);
        self.evidence_param_paths.deinit(self.allocator);
        self.enum_scratch.deinit(self.allocator);
        var scope_lists = self.scope_params.valueIterator();
        while (scope_lists.next()) |list| {
            for (list.*) |param| self.allocator.free(param.path);
            self.allocator.free(list.*);
        }
        self.scope_params.deinit();
        self.chain_scratch.deinit(self.allocator);
    }

    fn run(self: *EvidencePass) Allocator.Error!void {
        self.plan_resolved = try self.allocator.alloc(bool, self.plan_table.plans.len);
        @memset(self.plan_resolved, false);
        self.iterator_plan_resolved = try self.allocator.alloc(bool, self.plan_table.iterator_for_plans.len);
        @memset(self.iterator_plan_resolved, false);

        try self.buildIndexes();
        try self.linkGeneratedCodecCalls();

        var params = std.ArrayListUnmanaged(EvidenceParam).empty;
        defer params.deinit(self.allocator);

        // by_def maps source defs to templates.
        var template_defs = std.AutoHashMap(u32, CIR.Def.Idx).init(self.allocator);
        defer template_defs.deinit();
        for (self.templates.by_def) |entry| {
            try template_defs.put(@intFromEnum(entry.template.template), entry.def);
        }

        // Publish every template schema before resolving any target edge. A
        // local target may appear later in table order, but its callable-path
        // evidence classification must still consume a complete producer
        // schema rather than depend on visitation order.
        for (self.templates.templates) |*template| {
            try self.enumerateTemplateParams(template.*, &template_defs, &params);
            template.evidence_params = try self.appendEvidenceParams(params.items);
        }
        for (self.templates.dispatch_scopes, 0..) |*scope, raw_scope| {
            const scope_id: DispatchScopeId = @enumFromInt(@as(u32, @intCast(raw_scope)));
            const scope_params = try self.paramsForScope(scope_id, scope.scheme_var);
            scope.evidence_params = try self.appendEvidenceParams(scope_params);
        }
        self.templates.evidence_params_pool = try self.evidence_params_pool.toOwnedSlice(self.allocator);
        self.templates.evidence_param_paths = try self.evidence_param_paths.toOwnedSlice(self.allocator);

        for (self.templates.templates, 0..) |*template, template_index| {
            try self.enumerateTemplateParams(template.*, &template_defs, &params);

            const plan_start = template.static_dispatch_plans.start;
            const plan_refs = self.plan_table.template_refs[plan_start .. plan_start + template.static_dispatch_plans.len];
            for (plan_refs, 0..) |plan_id, i| {
                const chain = try self.chainFor(self.template_iterator_refs.plan_scopes[plan_start + i], params.items);
                try self.resolvePlan(plan_id, chain, false);
            }

            const iter_span = self.template_iterator_refs.spans[template_index];
            for (self.template_iterator_refs.pool[iter_span.start .. iter_span.start + iter_span.len], 0..) |iter_plan_id, i| {
                const chain = try self.chainFor(self.template_iterator_refs.iterator_scopes[iter_span.start + i], params.items);
                try self.resolveIteratorPlan(iter_plan_id, chain, false);
            }

            const value_ref_start = template.resolved_value_refs.start;
            const value_refs = self.resolved_value_refs.template_refs[value_ref_start .. value_ref_start + template.resolved_value_refs.len];
            for (value_refs, 0..) |ref_id, i| {
                const chain = try self.chainFor(self.template_iterator_refs.value_ref_scopes[value_ref_start + i], params.items);
                try self.emitSiteEvidence(ref_id, chain);
            }

            const scheme_use_span = self.template_iterator_refs.scheme_use_spans[template_index];
            const scheme_use_sites = self.template_iterator_refs.scheme_use_sites[scheme_use_span.start .. scheme_use_span.start + scheme_use_span.len];
            for (scheme_use_sites, 0..) |site, i| {
                const chain = try self.chainFor(self.template_iterator_refs.scheme_use_scopes[scheme_use_span.start + i], params.items);
                try self.emitSchemeUseSiteEvidence(site.record_idx, @intFromEnum(site.checked_expr), chain);
            }

            const scope_site_span = self.template_iterator_refs.scope_site_spans[template_index];
            const scope_sites = self.template_iterator_refs.scope_sites[scope_site_span.start .. scope_site_span.start + scope_site_span.len];
            for (scope_sites) |site| {
                try self.emitScopeConstructionEvidence(site, params.items);
            }
        }

        if (self.template_root_evidence.len != self.templates.templates.len) {
            checkedArtifactInvariant("template root evidence output and procedure template tables had different lengths", .{});
        }
        for (self.templates.templates, self.template_root_evidence) |template, *out| {
            params.clearRetainingCapacity();
            try self.enumerateTemplateParams(template, &template_defs, &params);
            var entries = std.ArrayListUnmanaged(static_dispatch.CheckedEvidence).empty;
            defer entries.deinit(self.allocator);
            try entries.ensureTotalCapacity(self.allocator, params.items.len);
            self.current_chain = &.{};
            for (params.items) |param| {
                const evidence = (try self.evidenceForVar(
                    param,
                    param.dispatcher_var,
                    param.constraint.fn_var,
                    true,
                )) orelse checkedArtifactInvariant(
                    "procedure template root evidence remained unresolved after checking",
                    .{},
                );
                entries.appendAssumeCapacity(evidence);
            }
            out.* = try self.appendEvidenceRefs(entries.items);
        }

        // Root edges are their templates' only callers (nothing instantiates
        // a compile-time root). Resolve each pattern'd root's evidence now—
        // the chain is empty, so every obligation lands on a chain-free
        // resolution (concrete target, mono-default owner, structural,
        // vacuous)—published as site evidence keyed by the root's body
        // expression for the drain and const-eval entries to consume.
        for (self.compile_time_roots.roots) |root| {
            const source_pattern = root.source_pattern orelse continue;
            params.clearRetainingCapacity();
            try self.enumerateParams(ModuleEnv.varFrom(source_pattern), &params);
            if (params.items.len == 0) continue;
            const site_key = @intFromEnum(root.expr);
            if (self.site_seen.contains(site_key)) continue;
            var entries = std.ArrayListUnmanaged(static_dispatch.CheckedEvidence).empty;
            defer entries.deinit(self.allocator);
            try entries.ensureTotalCapacity(self.allocator, params.items.len);
            for (params.items) |param| {
                entries.appendAssumeCapacity((try self.evidenceForVar(param, param.dispatcher_var, param.constraint.fn_var, true)).?);
            }
            const span = try self.appendEvidenceRefs(entries.items);
            try self.site_seen.put(site_key, {});
            try self.site_evidence.append(self.allocator, .{ .key = site_key, .start = span.start, .len = span.len });
        }

        // A platform requirement invokes an app procedure without a source
        // expression use site in the eventual platform module. Resolve that
        // root edge here, while the app checker's solved requirement variable
        // and exact target records are still available, and carry only the
        // finished evidence vector across the checked-artifact boundary.
        for (self.platform_requirement_solutions, self.platform_requirement_root_evidence) |solution, *out| {
            out.* = .{};
            if (!solution.is_function or try solutionVarsReachErr(self.allocator, self.module, solution)) continue;

            params.clearRetainingCapacity();
            try self.enumerateParams(solution.solved_var, &params);
            var entries = std.ArrayListUnmanaged(static_dispatch.CheckedEvidence).empty;
            defer entries.deinit(self.allocator);
            try entries.ensureTotalCapacity(self.allocator, params.items.len);
            self.current_chain = &.{};
            for (params.items) |param| {
                const evidence = (try self.evidenceForVar(
                    param,
                    param.dispatcher_var,
                    param.constraint.fn_var,
                    true,
                )) orelse checkedArtifactInvariant(
                    "platform requirement root evidence remained unresolved after checking",
                    .{},
                );
                entries.appendAssumeCapacity(evidence);
            }
            out.* = try self.appendEvidenceRefs(entries.items);
        }

        // Explicit shared-var use sites no template chain fully bound resolve
        // chain-free here. A site an overlapping template already emitted is
        // skipped by `site_seen`.
        {
            var i: usize = 0;
            while (i < self.deferred_use_sites.items.len) : (i += 1) {
                const deferred = self.deferred_use_sites.items[i];
                if (self.site_seen.contains(deferred.site_key)) continue;
                self.current_chain = &.{};
                const span = (try self.evidenceRefsForRecord(deferred.record_idx, true)).?;
                if (span.len == 0) continue;
                try self.site_seen.put(deferred.site_key, {});
                try self.site_evidence.append(self.allocator, .{ .key = deferred.site_key, .start = span.start, .len = span.len });
            }
        }

        // Plans no template reached (dead code, expressions outside any
        // template) still leave publication with a definitive resolution:
        // resolve them chain-free, exactly like root edges.
        for (0..self.plan_table.plans.len) |raw| {
            if (self.plan_resolved[raw]) continue;
            try self.resolvePlan(@enumFromInt(raw), &.{}, true);
        }
        for (0..self.plan_table.iterator_for_plans.len) |raw| {
            if (self.iterator_plan_resolved[raw]) continue;
            try self.resolveIteratorPlan(@enumFromInt(raw), &.{}, true);
        }

        std.mem.sort(static_dispatch.SiteEvidenceEntry, self.site_evidence.items, {}, siteEvidenceLessThan);

        self.plan_table.evidence_nodes = try self.evidence_nodes.toOwnedSlice(self.allocator);
        self.plan_table.evidence_refs = try self.evidence_refs.toOwnedSlice(self.allocator);
        self.plan_table.site_evidence = try self.site_evidence.toOwnedSlice(self.allocator);
    }

    fn enumerateTemplateParams(
        self: *EvidencePass,
        template: CheckedProcedureTemplate,
        template_defs: *const std.AutoHashMap(u32, CIR.Def.Idx),
        params: *std.ArrayListUnmanaged(EvidenceParam),
    ) Allocator.Error!void {
        params.clearRetainingCapacity();
        if (template_defs.get(@intFromEnum(template.template_id))) |def_idx| {
            try self.enumerateParams(ModuleEnv.varFrom(def_idx), params);
            return;
        }
        switch (template.body) {
            // An entry wrapper evaluates a compile-time root; plans inside the
            // root's body resolve against the root definition's own scheme.
            .entry_wrapper => |wrapper_id| {
                const wrapper = self.entry_wrappers.get(wrapper_id);
                const root = self.compile_time_roots.root(wrapper.root);
                if (root.source_pattern) |source_pattern| {
                    try self.enumerateParams(ModuleEnv.varFrom(source_pattern), params);
                }
                // Expression roots (REPL lines, eval snippets) have no pattern
                // and no callers, so their obligations are chain-free.
            },
            .checked_body, .intrinsic_wrapper => {},
        }
    }

    fn buildIndexes(self: *EvidencePass) Allocator.Error!void {
        const module_env = self.module.moduleEnvConst();
        for (module_env.scheme_uses.items.items, 0..) |record, i| {
            switch (@as(ModuleEnv.SchemeUseRecord.Slot, @enumFromInt(record.slot_kind))) {
                .value_use, .shared_value_use => {
                    // Re-checks can record the same instantiation twice; keep
                    // the first.
                    const entry = try self.value_use_by_node.getOrPut(record.node_idx);
                    if (!entry.found_existing) entry.value_ptr.* = @intCast(i);
                },
                .dispatch_target => {
                    // `slot_data` is the raw constraint-function var: checking
                    // guarantees exactly one selected-target instantiation per
                    // logical edge. Resolving it through union-find would
                    // collapse distinct evidence records whose callable
                    // signatures later unify.
                    const entry = try self.target_by_fn_var.getOrPut(record.slot_data);
                    if (entry.found_existing) {
                        checkedArtifactInvariant("duplicate raw dispatch-target evidence identity", .{});
                    }
                    entry.value_ptr.* = @intCast(i);
                },
                .nested_function_use => {},
            }
        }

        var raw_node: u32 = 0;
        while (raw_node < self.module.nodeCount()) : (raw_node += 1) {
            if (!isExprNodeTag(self.module.nodeTag(@enumFromInt(raw_node)))) continue;
            const checked = self.checked_bodies.exprIdForSource(@enumFromInt(raw_node)) orelse continue;
            try self.source_by_checked_expr.put(@intFromEnum(checked), raw_node);
        }

        const global_value_defs = module_env.store.sliceDefs(module_env.global_value_defs);

        // Generalized local VALUE decls and one representative use record per
        // looked-up pattern (see `local_value_scheme_by_var`).
        for (module_env.scheme_uses.items.items, 0..) |record, i| {
            if (record.slot_kind != @intFromEnum(ModuleEnv.SchemeUseRecord.Slot.value_use)) continue;
            if (self.module.nodeTag(@enumFromInt(record.node_idx)) != .expr_var) continue;
            const lookup = self.module.expr(@enumFromInt(record.node_idx)).data.e_lookup_local;
            const entry = try self.value_use_record_by_pattern.getOrPut(@intFromEnum(lookup.pattern_idx));
            if (!entry.found_existing) entry.value_ptr.* = @intCast(i);
        }
        {
            var scheme_params = std.ArrayListUnmanaged(EvidenceParam).empty;
            defer scheme_params.deinit(self.allocator);
            raw_node = 0;
            while (raw_node < self.module.nodeCount()) : (raw_node += 1) {
                if (self.module.nodeTag(@enumFromInt(raw_node)) != .statement_decl) continue;
                const statement: CIR.Statement.Idx = @enumFromInt(raw_node);
                const statement_data = self.module.getStatement(statement);
                if (statement_data != .s_decl) continue;
                try self.mapValueSchemeParams(statement_data.s_decl.pattern, statement_data.s_decl.expr, &scheme_params);
            }
            // Top-level generalized VALUE defs (e.g. an `if` choosing between
            // closures) lower inline at their single use type exactly like
            // local value decls; their body plans resolve through use records
            // the same way.
            for (global_value_defs) |def_idx| {
                const def = module_env.store.getDef(def_idx);
                try self.mapValueSchemeParams(def.pattern, def.expr, &scheme_params);
            }
        }
    }

    fn linkGeneratedCodecCalls(self: *EvidencePass) Allocator.Error!void {
        const module_env = self.module.moduleEnvConst();
        const source_derivations = module_env.generated_codec_derivations.items.items;
        if (source_derivations.len != self.plan_table.generated_codec_derivations.len) {
            checkedArtifactInvariant("generated codec source and artifact derivation counts differed", .{});
        }
        for (source_derivations, self.plan_table.generated_codec_derivations) |source_derivation, derivation| {
            const source_calls = module_env.generated_codec_calls.items.items[source_derivation.calls_start..][0..source_derivation.calls_len];
            const artifact_calls = self.plan_table.generated_codec_calls[derivation.calls.start..][0..derivation.calls.len];
            if (source_calls.len != artifact_calls.len) {
                checkedArtifactInvariant("generated codec source and artifact derivation call counts differed", .{});
            }
            for (artifact_calls, source_calls) |*call, source_call| {
                const owner = (try self.methodOwnerForSourceContent(@enumFromInt(source_call.dispatcher_var))) orelse continue;
                const target = self.lookupMethodTargetAcrossViews(owner, call.method) orelse continue;
                const evidence_var: Var = @enumFromInt(source_call.evidence_var);
                switch (target.kind) {
                    .procedure, .local_proc => {
                        const node_id = try self.evidenceNodeForTarget(target, call.dispatcher_ty, evidence_var, .derivation);
                        call.nested = switch (self.evidence_nodes.items[@intFromEnum(node_id)].nested) {
                            .resolved => |span| span,
                            .from_callable => checkedArtifactInvariant(
                                "generated codec method evidence was not resolved at its checked call edge",
                                .{},
                            ),
                        };
                    },
                    .structural => |kind| {
                        const expected_kind: static_dispatch.GeneratedCodecDerivationKind = switch (kind) {
                            .parser => .parser,
                            .encoder => .encoder,
                            .equality, .hash, .map, .map_effectful => checkedArtifactInvariant("non-codec structural method reached a generated codec contract", .{}),
                        };
                        call.generated_codec_derivation = try self.generatedCodecDerivationForCall(
                            expected_kind,
                            call.dispatcher_ty,
                            derivation,
                        ) orelse
                            checkedArtifactInvariant("structural generated codec call had no checked nested derivation", .{});
                    },
                }
            }
        }
    }

    fn enumerateParams(self: *EvidencePass, root: Var, out: *std.ArrayListUnmanaged(EvidenceParam)) Allocator.Error!void {
        try dispatch_evidence.enumerateEvidenceParams(self.allocator, self.types, root, &self.enum_scratch, out);
    }

    /// The param chain at `scope_id`: the scope's own params first (depth 0),
    /// each enclosing local scope outward, then the template's params. The
    /// returned slice aliases `chain_scratch` and is valid until the next call.
    fn chainFor(self: *EvidencePass, scope_ref: DispatchScope, template_params: []const EvidenceParam) Allocator.Error![]const []const EvidenceParam {
        self.chain_scratch.clearRetainingCapacity();
        var current: ?DispatchScopeId = switch (scope_ref) {
            .root => null,
            .generalized => |id| id,
        };
        while (current) |id| {
            const scope = self.template_iterator_refs.scopes[@intFromEnum(id)];
            try self.chain_scratch.append(self.allocator, try self.paramsForScope(id, scope.scheme_var));
            current = scope.parent;
        }
        try self.chain_scratch.append(self.allocator, template_params);
        return self.chain_scratch.items;
    }

    fn paramsForScope(self: *EvidencePass, scope_id: DispatchScopeId, scheme_var: Var) Allocator.Error![]const EvidenceParam {
        const entry = try self.scope_params.getOrPut(scope_id);
        if (entry.found_existing) return entry.value_ptr.*;
        var params = std.ArrayListUnmanaged(EvidenceParam).empty;
        errdefer params.deinit(self.allocator);
        try self.enumerateParams(scheme_var, &params);
        var owned_path_count: usize = 0;
        errdefer for (params.items[0..owned_path_count]) |param| self.allocator.free(param.path);
        for (params.items) |*param| {
            param.path = try self.allocator.dupe(static_dispatch.EvidencePathStep, param.path);
            owned_path_count += 1;
        }
        entry.value_ptr.* = try params.toOwnedSlice(self.allocator);
        return entry.value_ptr.*;
    }

    fn appendEvidenceParams(self: *EvidencePass, params: []const EvidenceParam) Allocator.Error!artifact_serialize.Span {
        const idents = self.module.identStoreConst();
        const pool_start: u32 = @intCast(self.evidence_params_pool.items.len);
        for (params) |param| {
            const path_start: u32 = @intCast(self.evidence_param_paths.items.len);
            for (param.path) |path_step| {
                var converted = path_step;
                switch (path_step.stepKind()) {
                    .record_field => converted.data = @intFromEnum(try self.names.internRecordFieldIdent(idents, @bitCast(path_step.data))),
                    .tag_payload_tag => converted.data = @intFromEnum(try self.names.internTagIdent(idents, @bitCast(path_step.data))),
                    .fn_arg,
                    .fn_ret,
                    .alias_arg,
                    .alias_backing,
                    .nominal_arg,
                    .nominal_backing,
                    .tuple_elem,
                    .tag_payload_index,
                    => {},
                }
                try self.evidence_param_paths.append(self.allocator, converted);
            }
            try self.evidence_params_pool.append(self.allocator, .{
                .method = try self.names.internMethodIdent(idents, param.constraint.fn_name),
                .dispatcher_ty = self.checked_types.rootForSourceVar(self.module, param.dispatcher_var) orelse
                    checkedArtifactInvariant("checked evidence parameter dispatcher type was not published", .{}),
                .runtime_dictionary = param.constraint.origin.literalKind() == null,
                .structural = self.structuralKindForMethodIdent(param.constraint.fn_name),
                .pathless_default_phase = if (param.path.len == 0) self.pathlessDefaultPhaseForParam(param) else null,
                .path = .{ .start = path_start, .len = @intCast(param.path.len) },
            });
        }
        return .{ .start = pool_start, .len = @intCast(params.len) };
    }

    fn pathlessDefaultPhaseForParam(self: *EvidencePass, param: EvidenceParam) ?NumericDefaultPhase {
        const resolved = self.types.resolveVar(param.dispatcher_var);
        const constraints = switch (resolved.desc.content) {
            .flex => |flex| flex.constraints,
            .rigid => |rigid| rigid.constraints,
            .alias, .field_presence, .structure, .err => return null,
        };
        return numericDefaultPhaseForConstraints(self.module, constraints);
    }

    /// The canonical `(depth, index)` of `dispatcher_root`'s `method`
    /// obligation in the chain, searching innermost-out.
    fn chainParamIndex(self: *EvidencePass, chain: []const []const EvidenceParam, dispatcher_root: Var, method: canonical.MethodNameId) Allocator.Error!?static_dispatch.EvidenceChainIndex {
        for (chain, 0..) |params, depth| {
            if (try self.paramIndexFor(params, dispatcher_root, method)) |k| {
                return .{ .depth = @intCast(depth), .index = @intCast(k) };
            }
        }
        return null;
    }

    /// Exact method-target lookup across every registry this publication can
    /// see: the local registry, the direct import views, then the available
    /// views. (Snapshot-style compiles pass the builtin module only as a
    /// direct import, so searching `available` alone misses every
    /// builtin-owned method.)
    fn lookupMethodTargetAcrossViews(self: *EvidencePass, owner: static_dispatch.MethodOwner, method: canonical.MethodNameId) ?static_dispatch.MethodTarget {
        if (static_dispatch.lookupCheckedMethodTarget(self.names, self.local_method_registry, &.{}, owner, method)) |target| {
            return target;
        }
        var one_view: [1]ImportedModuleView = undefined;
        for (self.import_views.available) |available| {
            if (moduleViewIsSuperseded(available, self.import_views.relations, self.import_views.direct)) continue;
            one_view[0] = available;
            if (static_dispatch.lookupCheckedMethodTarget(self.names, self.local_method_registry, one_view[0..1], owner, method)) |target| {
                return target;
            }
        }
        for (self.import_views.relations) |relation| {
            one_view[0] = relation;
            if (static_dispatch.lookupCheckedMethodTarget(self.names, self.local_method_registry, one_view[0..1], owner, method)) |target| {
                return target;
            }
        }
        for (self.import_views.direct) |import| {
            one_view[0] = import.view;
            if (static_dispatch.lookupCheckedMethodTarget(self.names, self.local_method_registry, one_view[0..1], owner, method)) |target| {
                return target;
            }
        }
        return null;
    }

    /// Map a generalized VALUE decl's scheme param roots to its pattern for
    /// use-record obligation resolution (lambda-form decls are evidence
    /// scopes instead).
    fn mapValueSchemeParams(
        self: *EvidencePass,
        pattern: CIR.Pattern.Idx,
        expr: CIR.Expr.Idx,
        scheme_params: *std.ArrayListUnmanaged(EvidenceParam),
    ) Allocator.Error!void {
        const expr_data = self.module.expr(expr).data;
        if (expr_data == .e_lambda or expr_data == .e_closure) return;
        const pattern_var = ModuleEnv.varFrom(pattern);
        if (self.types.resolveVar(pattern_var).desc.rank != .generalized) return;
        scheme_params.clearRetainingCapacity();
        try self.enumerateParams(pattern_var, scheme_params);
        for (scheme_params.items) |param| {
            const root = self.types.resolveVar(param.dispatcher_var).var_;
            const entry = try self.local_value_scheme_by_var.getOrPut(@intFromEnum(root));
            if (!entry.found_existing) entry.value_ptr.* = @intFromEnum(pattern);
        }
    }

    /// The canonical param index of `dispatcher_root`'s `method` obligation.
    fn paramIndexFor(self: *EvidencePass, params: []const EvidenceParam, dispatcher_root: Var, method: canonical.MethodNameId) Allocator.Error!?u32 {
        const idents = self.module.identStoreConst();
        for (params, 0..) |param, k| {
            if (self.types.resolveVar(param.dispatcher_var).var_ != dispatcher_root) continue;
            if (try self.names.internMethodIdent(idents, param.constraint.fn_name) != method) continue;
            return @intCast(k);
        }
        return null;
    }

    fn resolvePlan(self: *EvidencePass, plan_id: static_dispatch.StaticDispatchPlanId, chain: []const []const EvidenceParam, commit_unpinned: bool) Allocator.Error!void {
        const raw = @intFromEnum(plan_id);
        const plan = &self.plan_table.plans[raw];
        if (self.plan_resolved[raw]) return;

        const src = self.build_data.plan_sources[raw];
        const structural_kind: ?static_dispatch.StructuralKind = switch (plan.result_mode) {
            .value => null,
            .equality => |eq| if (eq.structural_allowed) .equality else null,
            .hash => |hash| if (hash.structural_allowed) .hash else null,
            .parser_for => |parser_for| if (parser_for.structural_allowed) .parser else null,
            .encoder_for => |encoder_for| if (encoder_for.structural_allowed) .encoder else null,
            .map => |map| if (map.structural_allowed) .map else null,
            .map_effectful => |map| if (map.structural_allowed) .map_effectful else null,
        };
        // Nested evidence built for this plan's target forwards enclosing
        // where-vars against the same chain.
        self.current_chain = chain;
        defer self.current_chain = &.{};
        plan.resolution = (try self.resolveObligation(
            src.dispatcher_var,
            plan.dispatcher_ty,
            plan.method,
            structural_kind,
            src.constraint_fn_var,
            chain,
            commit_unpinned,
        )) orelse return;
        self.plan_resolved[raw] = true;
    }

    fn resolveIteratorPlan(self: *EvidencePass, plan_id: static_dispatch.IteratorForPlanId, chain: []const []const EvidenceParam, commit_unpinned: bool) Allocator.Error!void {
        const raw = @intFromEnum(plan_id);
        const plan = &self.plan_table.iterator_for_plans[raw];
        if (self.iterator_plan_resolved[raw]) return;

        const src = self.build_data.iterator_plan_sources[raw];
        self.current_chain = chain;
        defer self.current_chain = &.{};
        plan.iter.resolution = (try self.resolveObligation(
            src.iter_dispatcher_var,
            plan.iter.dispatcher_ty,
            plan.iter.method,
            null,
            src.iter_fn_var,
            chain,
            commit_unpinned,
        )) orelse return;
        // The iterator type is the `iter` callable's return: dispatch `next`
        // on it.
        const next_dispatcher = self.iteratorNextDispatcherVar(src.iter_fn_var);
        plan.next.resolution = if (next_dispatcher) |dispatcher_var|
            (try self.resolveObligation(
                dispatcher_var,
                plan.next.dispatcher_ty,
                plan.next.method,
                null,
                src.next_fn_var,
                chain,
                commit_unpinned,
            )) orelse return
        else
            // A non-function `iter` callable only occurs on checked errors.
            .checked_error;
        self.iterator_plan_resolved[raw] = true;
    }

    fn iteratorNextDispatcherVar(self: *EvidencePass, iter_fn_var: Var) ?Var {
        const resolved = self.types.resolveVar(iter_fn_var);
        const func = resolved.desc.content.unwrapFunc() orelse return null;
        return func.ret;
    }

    /// Resolve one dispatch obligation: `method` dispatched on
    /// `dispatcher_var`, with `constraint_fn_var` keying the discharge record
    /// that carries the chosen target's own nested obligations.
    /// Resolve one dispatch obligation. With `commit_unpinned = false`
    /// (template walks), an obligation the given chain does not bind returns
    /// null so a template whose scheme DOES bind it (template plan-ref spans
    /// can overlap) or the final chain-free sweep resolves it instead. With
    /// `commit_unpinned = true` the result is total.
    fn resolveObligation(
        self: *EvidencePass,
        dispatcher_var: Var,
        dispatcher_ty: CheckedTypeId,
        method: canonical.MethodNameId,
        structural_kind: ?static_dispatch.StructuralKind,
        constraint_fn_var: ?Var,
        chain: []const []const EvidenceParam,
        commit_unpinned: bool,
    ) Allocator.Error!?static_dispatch.CheckedCallResolution {
        if (constraint_fn_var) |fn_var| {
            if (self.types.varStaticDispatchRejected(fn_var)) return .checked_error;
        }

        const resolved = self.types.resolveVar(dispatcher_var);

        // Builtin containers have ordinary registry methods for parser_for and
        // encoder_for, but checking can deliberately discharge an obligation
        // through the generated structural codec path instead. Preserve that
        // exact producer decision: the derivation records the original
        // constraint-function variable that selected it.
        if (structural_kind) |kind| {
            const derivation_kind: ?static_dispatch.GeneratedCodecDerivationKind = switch (kind) {
                .parser => .parser,
                .encoder => .encoder,
                .equality, .hash, .map, .map_effectful => null,
            };
            if (derivation_kind) |expected_kind| {
                if (constraint_fn_var) |fn_var| {
                    if (self.generatedCodecDerivationForSourceConstraint(fn_var, expected_kind) != null) {
                        return .{ .structural = try self.structuralDerivation(kind, constraint_fn_var) };
                    }
                }
            }
        }

        // A generalized VALUE decl's scheme param may LOOK concrete here:
        // compile-time finalization defaults the pristine var (e.g. to Dec)
        // after uses were instantiated. The uses are the truth—they carry
        // the type each inline lowering actually runs at—so resolve through
        // a representative use record before trusting the var's content.
        if (self.local_value_scheme_by_var.get(@intFromEnum(resolved.var_))) |pattern_raw| {
            if (self.value_use_record_by_pattern.get(pattern_raw)) |record_idx| {
                const module_env = self.module.moduleEnvConst();
                const record = module_env.scheme_uses.items.items[record_idx];
                const pairs = module_env.scheme_use_pairs.items.items[record.pairs_start .. record.pairs_start + record.pairs_len];
                if (self.pairForResolved(pairs, resolved.var_)) |fresh| {
                    if (self.types.resolveVar(fresh).var_ != resolved.var_) {
                        const fresh_fn: ?Var = if (constraint_fn_var) |fn_var| self.pairForResolved(pairs, self.types.resolveVar(fn_var).var_) else null;
                        const fresh_dispatcher_ty = self.checked_types.rootForSourceVar(self.module, fresh) orelse
                            checkedArtifactInvariant("checked dispatch use instantiation type was not published", .{});
                        return self.resolveObligation(fresh, fresh_dispatcher_ty, method, structural_kind, fresh_fn orelse constraint_fn_var, chain, true);
                    }
                }
            }
        }

        switch (resolved.desc.content) {
            // A different checker diagnostic can poison the value that owns
            // this receiver after the dispatch itself checked successfully.
            // The explicit rejection map above remains the sole authority for
            // dispatch-specific failures; `.err` is the separate value-error
            // fence and must never be inferred from the callable or its return.
            // A presence variable is not a dispatch target and carries no
            // obligations—treat it as inert like `.err`.
            .err, .field_presence => return .checked_error,
            .flex => |flex| return self.resolveVarObligation(resolved.var_, dispatcher_ty, flex.constraints, method, structural_kind, constraint_fn_var, chain, commit_unpinned),
            .rigid => |rigid| return self.resolveVarObligation(resolved.var_, dispatcher_ty, rigid.constraints, method, structural_kind, constraint_fn_var, chain, commit_unpinned),
            .alias, .structure => {
                if (try self.methodOwnerForSourceContent(resolved.var_)) |owner| {
                    if (self.lookupMethodTargetAcrossViews(owner, method)) |target| {
                        return try self.resolutionForMethodTarget(target, structural_kind, dispatcher_ty, constraint_fn_var);
                    }
                    // The dispatcher has an owner, checking passed, and no
                    // registry-visible view declares the method: the checker
                    // discharged the obligation with the derived structural
                    // implementation. Value dispatches cannot discharge
                    // structurally, so a miss there is a publication bug
                    // (every view the checker resolved against is searched
                    // above).
                    if (structural_kind) |kind| return .{ .structural = try self.structuralDerivation(kind, constraint_fn_var) };
                    std.debug.panic("publication could not resolve a checked dispatch target for an owned method", .{});
                }
                // No owner head: a genuinely structural shape.
                if (structural_kind) |kind| return .{ .structural = try self.structuralDerivation(kind, constraint_fn_var) };
                checkedArtifactInvariant("ownerless non-structural dispatch reached publication without an explicit rejection", .{});
            },
        }
    }

    fn generatedCodecDerivationForSourceConstraint(
        self: *EvidencePass,
        constraint_fn_var: Var,
        expected_kind: static_dispatch.GeneratedCodecDerivationKind,
    ) ?static_dispatch.GeneratedCodecDerivationId {
        const source_derivations = self.module.moduleEnvConst().generated_codec_derivations.items.items;
        if (source_derivations.len != self.plan_table.generated_codec_derivations.len) {
            checkedArtifactInvariant("generated codec source and artifact derivation counts differed", .{});
        }

        const constraint_root = self.types.resolveVar(constraint_fn_var).var_;
        var found: ?static_dispatch.GeneratedCodecDerivationId = null;
        for (source_derivations, self.plan_table.generated_codec_derivations, 0..) |source, derivation, index| {
            const kind: static_dispatch.GeneratedCodecDerivationKind = switch (@as(ModuleEnv.GeneratedCodecDerivation.Kind, @enumFromInt(source.kind))) {
                .parser => .parser,
                .encoder => .encoder,
            };
            if (kind != expected_kind or
                self.types.resolveVar(@enumFromInt(source.source_constraint_fn_var)).var_ != constraint_root)
            {
                continue;
            }

            const candidate: static_dispatch.GeneratedCodecDerivationId = @enumFromInt(@as(u32, @intCast(index)));
            if (found) |existing| {
                if (!self.generatedCodecDerivationsSemanticallyEql(
                    self.plan_table.generated_codec_derivations[@intFromEnum(existing)],
                    derivation,
                )) {
                    checkedArtifactInvariant("one checked codec constraint produced conflicting derivations", .{});
                }
            } else {
                found = candidate;
            }
        }
        return found;
    }

    fn resolveVarObligation(
        self: *EvidencePass,
        dispatcher_root: Var,
        dispatcher_ty: CheckedTypeId,
        constraints: types.StaticDispatchConstraint.SafeList.Range,
        method: canonical.MethodNameId,
        structural_kind: ?static_dispatch.StructuralKind,
        constraint_fn_var: ?Var,
        chain: []const []const EvidenceParam,
        commit_unpinned: bool,
    ) Allocator.Error!?static_dispatch.CheckedCallResolution {
        if (try self.chainParamIndex(chain, dispatcher_root, method)) |ref| {
            // A constraint(k) resolution consumes evidence entry k, whose
            // callable is the scheme's pristine constraint fn type. The
            // obligation's own callable must be that same type: same-named
            // constraints on a shared dispatcher var unify their fn vars, so
            // a mismatched root here means the site's callable was pinned to
            // one instantiation's concrete type.
            if (constraint_fn_var) |fn_var| {
                const chain_fn_var = chain[ref.depth][ref.index].constraint.fn_var;
                if (self.types.resolveVar(fn_var).var_ != self.types.resolveVar(chain_fn_var).var_) {
                    checkedArtifactInvariant("constraint-resolved dispatch callable was not the scheme-pristine constraint fn type", .{});
                }
            }
            return .{ .evidence_dependent = ref };
        }

        // Not bound by this chain. During template walks another template's
        // scheme may bind it (plan-ref spans can overlap); only the final
        // sweep commits unpinned classifications.
        if (!commit_unpinned) return null;

        // Not an evidence param of any enclosing callable, so no edge pins it
        // and monotype materializes it by `numericDefaultPhaseForConstraints`—
        // the same rule that stamps `numeric_default_phase` on published
        // type variables (Dec for numerals and defaultable arithmetic
        // operators, Str for quotes and interpolations). Every obligation on
        // the var resolves against that default owner now, while retaining the
        // checker's exact callable relation for nested evidence.
        if (numericDefaultPhaseForConstraints(self.module, constraints)) |phase| {
            const owner: static_dispatch.MethodOwner = switch (phase) {
                .mono_specialization => .{ .builtin = .dec },
                .mono_specialization_str => .{ .builtin = .str },
                // `checking_finalized` is stamped only on vars checking already
                // resolved; an unresolved one cannot carry it.
                .checking_finalized => return .checked_error,
            };
            if (self.lookupMethodTargetAcrossViews(owner, method)) |target| {
                return try self.resolutionForMethodTarget(target, structural_kind, dispatcher_ty, constraint_fn_var);
            }
        }

        // No edge can ever supply this dispatcher (not a param of any
        // enclosing callable, no defaulting literal). Equality and hashing of
        // the vacuous shape remain structural. Generated codecs require the
        // explicit checker snapshot handled above; without one, parser,
        // encoder, map, and value dispatches are statically unreachable.
        if (structural_kind) |kind| switch (kind) {
            .equality, .hash => return .{ .structural = try self.structuralDerivation(kind, constraint_fn_var) },
            .parser, .encoder, .map, .map_effectful => return .@"unreachable",
        };
        return .@"unreachable";
    }

    fn structuralDerivation(
        self: *EvidencePass,
        kind: static_dispatch.StructuralKind,
        constraint_fn_var: ?Var,
    ) Allocator.Error!static_dispatch.StructuralDerivation {
        return switch (kind) {
            .equality => .equality,
            .hash => .hash,
            .parser => .parser,
            .encoder => .encoder,
            .map, .map_effectful => blk: {
                const fn_var = constraint_fn_var orelse checkedArtifactInvariant("derived map evidence had no constraint function", .{});
                const fn_root = self.types.resolveVar(fn_var).var_;
                var source_plan: ?types.DerivedMapPlan = null;
                for (self.types.static_dispatch_constraints.items.items) |constraint| {
                    if (self.types.resolveVar(constraint.fn_var).var_ != fn_root) continue;
                    source_plan = constraint.derived_map_plan orelse continue;
                    break;
                }
                const plan = source_plan orelse checkedArtifactInvariant("derived map evidence had no checked payload selection", .{});
                const canonical_plan = static_dispatch.DerivedMapPlan{
                    .tag = try self.names.internTagIdent(self.module.identStoreConst(), plan.tag_name),
                    .payload_index = plan.payload_index,
                };
                break :blk if (kind == .map)
                    .{ .map = canonical_plan }
                else
                    .{ .map_effectful = canonical_plan };
            },
        };
    }

    /// The method owner of a settled source var, walking alias content
    /// transparently (the source-var analog of monotype lowering's
    /// dispatch-head read of published type identity).
    fn methodOwnerForSourceContent(self: *EvidencePass, var_: Var) Allocator.Error!?static_dispatch.MethodOwner {
        var current = var_;
        var remaining: u64 = self.types.len();
        while (true) {
            const resolved = self.types.resolveVar(current);
            switch (resolved.desc.content) {
                .alias => |alias| {
                    if (remaining == 0) {
                        checkedArtifactInvariant("checked evidence source alias chain was cyclic", .{});
                    }
                    remaining -= 1;
                    current = self.types.getAliasBackingVar(alias);
                },
                .structure => |flat_type| switch (flat_type) {
                    .nominal_type => |nominal| {
                        if (categorizeBuiltinNominal(self.module, self.import_views, nominal)) |builtin_nominal| {
                            if (builtin_nominal == .try_) {
                                const idents = self.module.identStoreConst();
                                const module_identity_id = try self.names.internModuleIdentity(self.module.moduleEnvConst().moduleIdentityHash(nominal.origin_module));
                                const type_name = try self.names.internTypeIdent(idents, nominal.ident.ident_idx);
                                return .{ .nominal = .{
                                    .module = module_identity_id,
                                    .type_name = type_name,
                                    .source_decl = nominal.sourceDeclOptional(),
                                } };
                            }
                            return .{ .builtin = static_dispatch.builtinOwnerForCheckedBuiltin(builtin_nominal) };
                        }
                        const idents = self.module.identStoreConst();
                        const module_identity_id = try self.names.internModuleIdentity(self.module.moduleEnvConst().moduleIdentityHash(nominal.origin_module));
                        const type_name = try self.names.internTypeIdent(idents, nominal.ident.ident_idx);
                        return .{ .nominal = .{
                            .module = module_identity_id,
                            .type_name = type_name,
                            .source_decl = nominal.sourceDeclOptional(),
                        } };
                    },
                    .record,
                    .record_unbound,
                    .tuple,
                    .fn_pure,
                    .fn_effectful,
                    .fn_unbound,
                    .empty_record,
                    .tag_union,
                    .empty_tag_union,
                    => return null,
                },
                .flex, .rigid, .field_presence, .err => return null,
            }
        }
    }

    /// Preserve the checked registry's semantic resolution. Compiler-derived
    /// structural declarations are evidence themselves and must never enter a
    /// callable target's evidence-node graph.
    fn resolutionForMethodTarget(
        self: *EvidencePass,
        target: static_dispatch.MethodTarget,
        structural_kind: ?static_dispatch.StructuralKind,
        dispatcher_ty: ?CheckedTypeId,
        constraint_fn_var: ?Var,
    ) Allocator.Error!static_dispatch.CheckedCallResolution {
        return switch (target.kind) {
            .structural => |kind| blk: {
                if (structural_kind == null or structural_kind.? != kind) {
                    checkedArtifactInvariant("structural method registry result did not match the checked dispatch result mode", .{});
                }
                break :blk .{ .structural = try self.structuralDerivation(kind, constraint_fn_var) };
            },
            .procedure, .local_proc => .{ .direct_pending = try self.evidenceNodeForTarget(target, dispatcher_ty, constraint_fn_var, .dispatch_edge) },
        };
    }

    const ProcedureEvidenceSchema = enum {
        none,
        from_callable,
        requires_record,
    };

    const ProcedureEvidenceView = struct {
        table: *const CheckedProcedureTemplateTable,
        template: CheckedProcedureTemplate,
    };

    fn procedureEvidenceView(self: *EvidencePass, target: static_dispatch.MethodTarget) ProcedureEvidenceView {
        const procedure = switch (target.kind) {
            .procedure => |procedure| procedure,
            .local_proc, .structural => checkedArtifactInvariant("procedure evidence view requested for a non-procedure target", .{}),
        };
        const target_key = checkedArtifactKeyFromArtifactRef(procedure.template.artifact);
        const table: *const CheckedProcedureTemplateTable = imported: {
            for (self.import_views.direct) |import| {
                if (checkedArtifactKeyEql(import.key, target_key)) {
                    return .{ .table = import.view.checked_procedure_templates, .template = import.view.checked_procedure_templates.get(procedure.template.template) };
                }
            }
            for (self.import_views.available) |view| {
                if (checkedArtifactKeyEql(view.key, target_key)) {
                    return .{ .table = view.checked_procedure_templates, .template = view.checked_procedure_templates.get(procedure.template.template) };
                }
            }
            for (self.import_views.relations) |view| {
                if (checkedArtifactKeyEql(view.key, target_key)) {
                    return .{ .table = view.checked_procedure_templates, .template = view.checked_procedure_templates.get(procedure.template.template) };
                }
            }
            if (target.module_idx != self.module.moduleIndex()) {
                checkedArtifactInvariant("procedure evidence target artifact was unavailable during checked publication", .{});
            }
            break :imported self.templates;
        };
        return .{ .table = table, .template = table.get(procedure.template.template) };
    }

    fn procedureEvidenceSchemaForTemplate(
        table: *const CheckedProcedureTemplateTable,
        template: *const CheckedProcedureTemplate,
    ) ProcedureEvidenceSchema {
        return procedureEvidenceSchemaFromSlices(table.evidenceParams(template), table.evidence_param_paths);
    }

    fn procedureEvidenceSchemaFromSlices(
        params: []const static_dispatch.EvidenceParamRecord,
        paths: []const static_dispatch.EvidencePathStep,
    ) ProcedureEvidenceSchema {
        if (params.len == 0) return .none;
        for (params) |param| {
            const path = paths[param.path.start .. param.path.start + param.path.len];
            if (path.len == 0 and param.pathless_default_phase == null) return .requires_record;
        }
        return .from_callable;
    }

    fn procedureEvidenceSchema(self: *EvidencePass, target: static_dispatch.MethodTarget) ProcedureEvidenceSchema {
        const target_view = self.procedureEvidenceView(target);
        return procedureEvidenceSchemaForTemplate(target_view.table, &target_view.template);
    }

    /// Build the evidence node for `target`. A checker-recorded dispatch-target
    /// record is the exact evidence selected at the discharge edge; compiler-
    /// generated edges that have no record derive evidence from the target
    /// schema and concrete callable relation.
    /// How a method target was selected, which decides whether a checked
    /// instantiation record must exist for it. A `dispatch_edge` target was
    /// chosen by resolving a static-dispatch constraint, and that resolution
    /// records the instantiation it performed. A `derivation` target was
    /// chosen by a generated codec deriving over a type's fields: there is no
    /// dispatch edge behind it, so no such record was ever written.
    const MethodTargetSelection = enum { dispatch_edge, derivation };

    fn evidenceNodeForTarget(
        self: *EvidencePass,
        target: static_dispatch.MethodTarget,
        dispatcher_ty: ?CheckedTypeId,
        constraint_fn_var: ?Var,
        selection: MethodTargetSelection,
    ) Allocator.Error!static_dispatch.EvidenceNodeId {
        if (target.kind == .structural) {
            checkedArtifactInvariant("structural method registry result reached the callable evidence-node graph", .{});
        }
        const callable_ty = if (constraint_fn_var) |fn_var|
            self.checked_types.rootForSourceVar(self.module, fn_var) orelse
                checkedArtifactInvariant("checked direct evidence callable type was not published", .{})
        else
            null;
        const record_idx: ?u32 = if (constraint_fn_var) |fn_var|
            self.target_by_fn_var.get(@intFromEnum(fn_var))
        else
            null;
        const generated_codec_derivation: ?static_dispatch.GeneratedCodecDerivationId = null;

        const procedure_schema: ?ProcedureEvidenceSchema = switch (target.kind) {
            .procedure => self.procedureEvidenceSchema(target),
            .local_proc, .structural => null,
        };
        if (record_idx) |idx| {
            if (self.node_by_record.get(idx)) |memoized| {
                const existing = self.evidence_nodes.items[@intFromEnum(memoized)];
                const callable_matches = switch (existing.instantiation) {
                    .monomorphic => false,
                    .callable => |existing_callable| existing_callable == callable_ty.?,
                };
                if (existing.dispatcher_ty != dispatcher_ty or
                    existing.generated_codec_derivation != generated_codec_derivation or
                    !callable_matches)
                {
                    checkedArtifactInvariant("one checked dispatch evidence record resolved at two checked call identities", .{});
                }
                return memoized;
            }
            if ((try self.record_in_progress.getOrPut(idx)).found_existing) {
                checkedArtifactInvariant("checked dispatch evidence chain was cyclic", .{});
            }
            defer _ = self.record_in_progress.remove(idx);

            const instantiated_callable_ty = self.checked_types.rootForSourceVar(self.module, constraint_fn_var.?) orelse
                checkedArtifactInvariant("dispatch target instantiated callable was missing from checked type output", .{});
            const nested = (try self.evidenceRefsForRecord(idx, true)).?;
            if (procedure_schema == .requires_record) {
                const target_view = self.procedureEvidenceView(target);
                if (nested.len != target_view.template.evidence_params.len) {
                    checkedArtifactInvariant("recorded procedure target evidence length differed from its declared params", .{});
                }
            }
            const node_id = try self.internEvidenceNode(.{
                .target = target,
                .dispatcher_ty = dispatcher_ty,
                .generated_codec_derivation = generated_codec_derivation,
                .instantiation = .{ .callable = instantiated_callable_ty },
                .nested = .{ .resolved = nested },
            });
            try self.node_by_record.put(idx, node_id);
            return node_id;
        }

        if (procedure_schema == .from_callable) {
            const fn_var = constraint_fn_var orelse
                checkedArtifactInvariant("callable-derived procedure evidence had no checked callable relation", .{});
            const callable = self.checked_types.rootForSourceVar(self.module, fn_var) orelse
                checkedArtifactInvariant("callable-derived dispatch target was missing from checked type output", .{});
            return try self.internEvidenceNode(.{
                .target = target,
                .dispatcher_ty = dispatcher_ty,
                .generated_codec_derivation = generated_codec_derivation,
                .instantiation = .{ .callable = callable },
                .nested = .from_callable,
            });
        }

        if (procedure_schema == .requires_record) {
            checkedArtifactInvariant("pathless procedure target evidence had no checked instantiation record", .{});
        }
        if (target.kind == .local_proc and constraint_fn_var != null and selection == .dispatch_edge) {
            checkedArtifactInvariant("constrained local-procedure target evidence had no checked instantiation record", .{});
        }

        const instantiation: static_dispatch.EvidenceTargetInstantiation = if (constraint_fn_var) |fn_var| .{
            .callable = self.checked_types.rootForSourceVar(self.module, fn_var) orelse
                checkedArtifactInvariant("dispatch target callable was missing from checked type output", .{}),
        } else .monomorphic;
        return try self.internEvidenceNode(.{
            .target = target,
            .dispatcher_ty = dispatcher_ty,
            .generated_codec_derivation = generated_codec_derivation,
            .instantiation = instantiation,
            .nested = .{ .resolved = .{} },
        });
    }

    fn internEvidenceNode(
        self: *EvidencePass,
        candidate: static_dispatch.EvidenceNode,
    ) Allocator.Error!static_dispatch.EvidenceNodeId {
        var hasher = std.hash.Wyhash.init(0);
        std.hash.autoHash(&hasher, candidate.target);
        std.hash.autoHash(&hasher, candidate.dispatcher_ty);
        std.hash.autoHash(&hasher, candidate.generated_codec_derivation);
        std.hash.autoHash(&hasher, candidate.instantiation);
        switch (candidate.nested) {
            .from_callable => std.hash.autoHash(&hasher, @as(u8, 0)),
            .resolved => |span| {
                std.hash.autoHash(&hasher, @as(u8, 1));
                const refs = self.evidence_refs.items[span.start .. span.start + span.len];
                std.hash.autoHash(&hasher, refs.len);
                for (refs) |ref| std.hash.autoHash(&hasher, ref);
            },
        }
        const hash = hasher.final();
        var existing = self.evidence_node_buckets.get(hash);
        while (existing) |node_id| {
            if (self.evidenceNodesEql(self.evidence_nodes.items[@intFromEnum(node_id)], candidate)) {
                return node_id;
            }
            existing = self.evidence_node_next.items[@intFromEnum(node_id)];
        }

        const node_id: static_dispatch.EvidenceNodeId = @enumFromInt(@as(u32, @intCast(self.evidence_nodes.items.len)));
        try self.evidence_nodes.append(self.allocator, candidate);
        try self.evidence_node_next.append(self.allocator, self.evidence_node_buckets.get(hash));
        try self.evidence_node_buckets.put(hash, node_id);
        return node_id;
    }

    fn evidenceNodesEql(
        self: *const EvidencePass,
        left: static_dispatch.EvidenceNode,
        right: static_dispatch.EvidenceNode,
    ) bool {
        if (!std.meta.eql(left.target, right.target) or
            left.dispatcher_ty != right.dispatcher_ty or
            left.generated_codec_derivation != right.generated_codec_derivation or
            !std.meta.eql(left.instantiation, right.instantiation)) return false;
        return switch (left.nested) {
            .from_callable => right.nested == .from_callable,
            .resolved => |left_span| switch (right.nested) {
                .from_callable => false,
                .resolved => |right_span| blk: {
                    const left_refs = self.evidence_refs.items[left_span.start .. left_span.start + left_span.len];
                    const right_refs = self.evidence_refs.items[right_span.start .. right_span.start + right_span.len];
                    if (left_refs.len != right_refs.len) break :blk false;
                    for (left_refs, right_refs) |left_ref, right_ref| {
                        if (!std.meta.eql(left_ref, right_ref)) break :blk false;
                    }
                    break :blk true;
                },
            },
        };
    }

    /// Resolve one scheme-use record's obligations (in the scheme's canonical
    /// order) into a contiguous `evidence_refs` range.
    fn evidenceRefsForRecord(self: *EvidencePass, record_idx: u32, commit_unpinned: bool) Allocator.Error!?artifact_serialize.Span {
        const module_env = self.module.moduleEnvConst();
        const record = module_env.scheme_uses.items.items[record_idx];
        const pairs = module_env.scheme_use_pairs.items.items[record.pairs_start .. record.pairs_start + record.pairs_len];

        var params = std.ArrayListUnmanaged(EvidenceParam).empty;
        defer params.deinit(self.allocator);
        try self.enumerateParams(@enumFromInt(record.scheme_root), &params);

        var entries = std.ArrayListUnmanaged(static_dispatch.CheckedEvidence).empty;
        defer entries.deinit(self.allocator);
        try entries.ensureTotalCapacity(self.allocator, params.items.len);

        for (params.items) |param| {
            const evidence = (try self.evidenceForRecordParam(pairs, param, commit_unpinned)) orelse return null;
            entries.appendAssumeCapacity(evidence);
        }

        return @as(?artifact_serialize.Span, try self.appendEvidenceRefs(entries.items));
    }

    fn evidenceForRecordParam(
        self: *EvidencePass,
        pairs: []const ModuleEnv.SchemeUsePair,
        param: EvidenceParam,
        commit_unpinned: bool,
    ) Allocator.Error!?static_dispatch.CheckedEvidence {
        const dispatcher_root = self.types.resolveVar(param.dispatcher_var).var_;
        const fresh_dispatcher = self.pairForResolved(pairs, dispatcher_root) orelse {
            // The scheme var was not copied at this instantiation (it was
            // already monomorphic there); resolve the pristine var directly.
            return try self.evidenceForVar(param, param.dispatcher_var, null, commit_unpinned);
        };
        const fn_root = self.types.resolveVar(param.constraint.fn_var).var_;
        const fresh_fn = self.pairForResolved(pairs, fn_root);
        return try self.evidenceForVar(param, fresh_dispatcher, fresh_fn, commit_unpinned);
    }

    /// Resolve one obligation of an instantiated scheme: the fresh dispatcher
    /// var either settled to a concrete type (direct or structural evidence),
    /// or is one of the *enclosing* callable's params (forwarded). The
    /// enclosing params here are the ones of the template whose body contains
    /// the instantiation site; the caller of `siteEvidence`/nested-node
    /// construction passes them contextually via `current_site_params`.
    fn evidenceForVar(
        self: *EvidencePass,
        param: EvidenceParam,
        var_: Var,
        fresh_fn_var: ?Var,
        commit_unpinned: bool,
    ) Allocator.Error!?static_dispatch.CheckedEvidence {
        const idents = self.module.identStoreConst();
        const method = try self.names.internMethodIdent(idents, param.constraint.fn_name);
        const structural_kind = self.structuralKindForMethodIdent(param.constraint.fn_name);
        const dispatcher_ty = self.checked_types.rootForSourceVar(self.module, var_) orelse
            checkedArtifactInvariant("checked scheme evidence dispatcher type was not published", .{});

        const resolution = (try self.resolveObligation(var_, dispatcher_ty, method, structural_kind, fresh_fn_var, self.current_chain, commit_unpinned)) orelse return null;
        return .{
            .dispatcher_ty = dispatcher_ty,
            .runtime_dictionary = param.constraint.origin.literalKind() == null,
            .resolution = switch (resolution) {
                .direct_pending => |node| .{ .direct = node },
                .direct_closed, .direct_parametric => checkedArtifactInvariant("call resolution was finalized before evidence publication completed", .{}),
                .evidence_dependent => |ref| .{ .constraint = ref },
                .structural => |kind| blk: {
                    const callable_var = fresh_fn_var orelse param.constraint.fn_var;
                    const callable_ty = self.checked_types.rootForSourceVar(self.module, callable_var) orelse
                        checkedArtifactInvariant("checked structural evidence callable type was not published", .{});
                    break :blk .{ .structural = .{
                        .derivation = kind,
                        .dispatcher_ty = dispatcher_ty,
                        .callable_ty = callable_ty,
                        .generated_codec_derivation = switch (kind) {
                            .parser => self.generatedCodecDerivationForSourceConstraint(
                                callable_var,
                                .parser,
                            ) orelse checkedArtifactInvariant(
                                "structural parser evidence had no generated derivation for its checked constraint",
                                .{},
                            ),
                            .encoder => self.generatedCodecDerivationForSourceConstraint(
                                callable_var,
                                .encoder,
                            ) orelse checkedArtifactInvariant(
                                "structural encoder evidence had no generated derivation for its checked constraint",
                                .{},
                            ),
                            .equality, .hash, .map, .map_effectful => null,
                        },
                    } };
                },
                .checked_error => blk: {
                    if (@import("builtin").mode == .Debug) {
                        std.log.scoped(.checked_evidence).debug("evidence entry checked_error: method={s} content={s}", .{
                            self.module.identStoreConst().getText(param.constraint.fn_name),
                            @tagName(self.types.resolveVar(var_).desc.content),
                        });
                    }
                    break :blk .checked_error;
                },
                .@"unreachable" => .unreachable_value,
            },
        };
    }

    fn generatedCodecDerivationsSemanticallyEql(
        self: *EvidencePass,
        a: static_dispatch.GeneratedCodecDerivation,
        b: static_dispatch.GeneratedCodecDerivation,
    ) bool {
        if (a.kind != b.kind) return false;
        inline for (.{
            "constructor_ty",
            "runtime_ty",
            "shape_ty",
            "encoding_ty",
            "state_ty",
            "error_ty",
        }) |field| {
            const a_key = self.checked_types.store.view().rootKey(@field(a, field));
            const b_key = self.checked_types.store.view().rootKey(@field(b, field));
            if (!std.meta.eql(a_key, b_key)) return false;
        }
        const a_calls = a.callsSlice(self.plan_table);
        const b_calls = b.callsSlice(self.plan_table);
        if (a_calls.len != b_calls.len) return false;
        for (a_calls, b_calls) |a_call, b_call| {
            if (a_call.method != b_call.method) return false;
            inline for (.{ "dispatcher_ty", "callable_ty" }) |field| {
                const a_key = self.checked_types.store.view().rootKey(@field(a_call, field));
                const b_key = self.checked_types.store.view().rootKey(@field(b_call, field));
                if (!std.meta.eql(a_key, b_key)) return false;
            }
            if ((a_call.subject_ty == null) != (b_call.subject_ty == null)) return false;
            if (a_call.subject_ty) |a_subject| {
                const b_subject = b_call.subject_ty.?;
                if (!std.meta.eql(
                    self.checked_types.store.view().rootKey(a_subject),
                    self.checked_types.store.view().rootKey(b_subject),
                )) return false;
            }
        }
        return true;
    }

    /// Link a structural codec call to the frozen derivation validated for the
    /// same nested shape and enclosing codec context. Callable type ids are not
    /// the identity here: the registry declaration, instantiated call, and
    /// frozen validation snapshot deliberately publish distinct callable roots.
    fn generatedCodecDerivationForCall(
        self: *EvidencePass,
        expected_kind: static_dispatch.GeneratedCodecDerivationKind,
        dispatcher_ty: CheckedTypeId,
        enclosing: static_dispatch.GeneratedCodecDerivation,
    ) Allocator.Error!?static_dispatch.GeneratedCodecDerivationId {
        const dispatcher_key = self.checked_types.store.view().rootKey(dispatcher_ty);
        const view = self.checked_types.store.view();
        const encoding_key = view.rootKey(enclosing.encoding_ty);
        const state_key = view.rootKey(enclosing.state_ty);
        const error_key = view.rootKey(enclosing.error_ty);
        var found: ?static_dispatch.GeneratedCodecDerivationId = null;
        for (self.plan_table.generated_codec_derivations, 0..) |derivation, index| {
            if (derivation.kind != expected_kind or
                !std.meta.eql(dispatcher_key, view.rootKey(derivation.shape_ty)) or
                !std.meta.eql(encoding_key, view.rootKey(derivation.encoding_ty)) or
                !std.meta.eql(state_key, view.rootKey(derivation.state_ty)) or
                !std.meta.eql(error_key, view.rootKey(derivation.error_ty)))
            {
                continue;
            }
            const candidate: static_dispatch.GeneratedCodecDerivationId = @enumFromInt(@as(u32, @intCast(index)));
            if (found) |existing| {
                if (!self.generatedCodecDerivationsSemanticallyEql(
                    self.plan_table.generated_codec_derivations[@intFromEnum(existing)],
                    derivation,
                )) {
                    checkedArtifactInvariant("generated codec method target matched multiple derivation contracts", .{});
                }
            } else {
                found = candidate;
            }
        }
        return found;
    }

    /// The derived-structural kind a constraint method admits, if any.
    /// Ident-keyed view of `static_dispatch.structural_method_kinds`: each
    /// table entry's name doubles as the matching `CommonIdents` field.
    fn structuralKindForMethodIdent(self: *EvidencePass, fn_name: anytype) ?static_dispatch.StructuralKind {
        const common = self.module.commonIdents();
        inline for (static_dispatch.structural_method_kinds) |entry| {
            if (fn_name.eql(@field(common, entry.common_ident))) return entry.kind;
        }
        return null;
    }

    fn appendEvidenceRefs(self: *EvidencePass, entries: []const static_dispatch.CheckedEvidence) Allocator.Error!artifact_serialize.Span {
        const start: u32 = @intCast(self.evidence_refs.items.len);
        try self.evidence_refs.appendSlice(self.allocator, entries);
        return .{ .start = start, .len = @intCast(entries.len) };
    }

    /// Publish site evidence for one value reference within the current
    /// template: how each of the referenced scheme's obligations was
    /// satisfied at that use.
    fn emitSiteEvidence(self: *EvidencePass, ref_id: ResolvedValueRefId, chain: []const []const EvidenceParam) Allocator.Error!void {
        const rec = self.resolved_value_refs.records[@intFromEnum(ref_id)];
        const site_key = @intFromEnum(rec.expr);
        if (self.site_seen.contains(site_key)) return;

        const source_node = self.source_by_checked_expr.get(site_key) orelse return;

        if (self.value_use_by_node.get(source_node)) |record_idx| {
            try self.emitSchemeUseSiteEvidence(record_idx, site_key, chain);
            return;
        }

        // A monomorphic local procedure use does not instantiate a scheme, so
        // checking has no SchemeUseRecord for it. Its declaration scope still
        // owns an explicit evidence schema; publish that schema's finished
        // vector from the settled source variables now.
        if (rec.ref == .local_proc) {
            const local = rec.ref.local_proc;
            const scope_id = local.dispatch_scope orelse return;
            const raw_scope = @intFromEnum(scope_id);
            if (raw_scope >= self.templates.dispatch_scopes.len) {
                checkedArtifactInvariant("local procedure use named an evidence scope outside the checked template table", .{});
            }
            const scope = self.templates.dispatch_scopes[raw_scope];
            if (scope.checked_expr != local.expr) {
                checkedArtifactInvariant("local procedure use evidence scope belonged to a different checked expression", .{});
            }
            const params = try self.paramsForScope(scope_id, scope.scheme_var);
            if (params.len == 0) return;

            self.current_chain = chain;
            defer self.current_chain = &.{};
            var entries = std.ArrayListUnmanaged(static_dispatch.CheckedEvidence).empty;
            defer entries.deinit(self.allocator);
            try entries.ensureTotalCapacity(self.allocator, params.len);
            for (params) |param| {
                const evidence = (try self.evidenceForVar(
                    param,
                    param.dispatcher_var,
                    param.constraint.fn_var,
                    true,
                )) orelse checkedArtifactInvariant(
                    "monomorphic local procedure evidence remained unresolved after checking",
                    .{},
                );
                entries.appendAssumeCapacity(evidence);
            }
            const span = try self.appendEvidenceRefs(entries.items);
            try self.site_seen.put(site_key, {});
            try self.site_evidence.append(self.allocator, .{ .key = site_key, .start = span.start, .len = span.len });
        }

        // References that do not become specialization edges intentionally
        // have no site evidence. Shared recursive uses are explicit records
        // and therefore returned through the branch above.
        return;
    }

    fn emitSchemeUseSiteEvidence(
        self: *EvidencePass,
        record_idx: u32,
        site_key: u32,
        chain: []const []const EvidenceParam,
    ) Allocator.Error!void {
        if (self.site_seen.contains(site_key)) return;

        self.current_chain = chain;
        defer self.current_chain = &.{};

        const record = self.module.moduleEnvConst().scheme_uses.items.items[record_idx];
        const shared = record.slot_kind == @intFromEnum(ModuleEnv.SchemeUseRecord.Slot.shared_value_use);
        const span = (try self.evidenceRefsForRecord(record_idx, !shared)) orelse {
            try self.deferred_use_sites.append(self.allocator, .{ .record_idx = record_idx, .site_key = site_key });
            return;
        };
        try self.site_seen.put(site_key, {});
        try self.site_evidence.append(self.allocator, .{ .key = site_key, .start = span.start, .len = span.len });
    }

    /// Publish the complete construction recipe for a generalized nested
    /// procedure that checking did not instantiate through a SchemeUseRecord.
    /// Path-bearing parameters explicitly project from the eventual callable;
    /// pathless parameters are resolved now against the enclosing checked
    /// evidence chain.
    fn emitScopeConstructionEvidence(
        self: *EvidencePass,
        site: CollectedScopeConstructionSite,
        template_params: []const EvidenceParam,
    ) Allocator.Error!void {
        const site_key = @intFromEnum(site.checked_expr);
        if (self.site_seen.contains(site_key)) return;

        const raw_scope = @intFromEnum(site.scope);
        if (raw_scope >= self.template_iterator_refs.scopes.len) {
            checkedArtifactInvariant("nested procedure construction named an unknown checked scope", .{});
        }
        const scope = self.template_iterator_refs.scopes[raw_scope];
        if (scope.checked_expr != site.checked_expr) {
            checkedArtifactInvariant("nested procedure construction scope belonged to a different checked expression", .{});
        }

        const parent_scope: DispatchScope = if (scope.parent) |parent|
            .{ .generalized = parent }
        else
            .root;
        self.current_chain = try self.chainFor(parent_scope, template_params);
        defer self.current_chain = &.{};

        const scope_params = try self.paramsForScope(site.scope, scope.scheme_var);
        var entries = std.ArrayListUnmanaged(static_dispatch.CheckedEvidence).empty;
        defer entries.deinit(self.allocator);
        try entries.ensureTotalCapacity(self.allocator, scope_params.len);
        for (scope_params) |param| {
            if (param.path.len > 0) {
                const dispatcher_ty = self.checked_types.rootForSourceVar(self.module, param.dispatcher_var) orelse
                    checkedArtifactInvariant("checked nested-procedure evidence dispatcher type was not published", .{});
                entries.appendAssumeCapacity(.{
                    .dispatcher_ty = dispatcher_ty,
                    .runtime_dictionary = param.constraint.origin.literalKind() == null,
                    .resolution = .from_callable,
                });
                continue;
            }
            const evidence = (try self.evidenceForVar(
                param,
                param.dispatcher_var,
                param.constraint.fn_var,
                true,
            )) orelse checkedArtifactInvariant(
                "pathless nested procedure evidence remained unresolved after checking",
                .{},
            );
            entries.appendAssumeCapacity(evidence);
        }

        const span = try self.appendEvidenceRefs(entries.items);
        try self.site_seen.put(site_key, {});
        try self.site_evidence.append(self.allocator, .{ .key = site_key, .start = span.start, .len = span.len });
    }

    /// `pairFor`, but comparing RESOLVED roots on both sides: finalization
    /// after record time can move the pristine var's root.
    fn pairForResolved(self: *EvidencePass, pairs: []const ModuleEnv.SchemeUsePair, old_root: Var) ?Var {
        for (pairs) |pair| {
            if (self.types.resolveVar(@enumFromInt(pair.old_var)).var_ == old_root) return @enumFromInt(pair.fresh_var);
        }
        return null;
    }
};

test "procedure evidence schema positively classifies callable paths and pathless requirements" {
    var path_steps = [_]static_dispatch.EvidencePathStep{ undefined, undefined };
    var params = [_]static_dispatch.EvidenceParamRecord{
        .{ .method = @enumFromInt(1), .dispatcher_ty = @enumFromInt(1), .runtime_dictionary = true, .structural = .encoder, .path = .{ .start = 0, .len = 1 } },
        .{ .method = @enumFromInt(2), .dispatcher_ty = @enumFromInt(2), .runtime_dictionary = true, .path = .{ .start = 1, .len = 1 } },
    };
    const table = CheckedProcedureTemplateTable{
        .evidence_params_pool = params[0..],
        .evidence_param_paths = path_steps[0..],
    };
    var template: CheckedProcedureTemplate = undefined;
    template.evidence_params = .{ .start = 0, .len = 2 };
    try std.testing.expectEqual(
        EvidencePass.ProcedureEvidenceSchema.from_callable,
        EvidencePass.procedureEvidenceSchemaFromSlices(table.evidenceParams(&template), table.evidence_param_paths),
    );

    var pathless_params = params;
    pathless_params[1].path = .{};
    const pathless_table = CheckedProcedureTemplateTable{
        .evidence_params_pool = pathless_params[0..],
        .evidence_param_paths = path_steps[0..],
    };
    try std.testing.expectEqual(
        EvidencePass.ProcedureEvidenceSchema.requires_record,
        EvidencePass.procedureEvidenceSchemaFromSlices(pathless_table.evidenceParams(&template), pathless_table.evidence_param_paths),
    );

    var defaulted_pathless_params = pathless_params;
    defaulted_pathless_params[1].pathless_default_phase = .mono_specialization;
    const defaulted_pathless_table = CheckedProcedureTemplateTable{
        .evidence_params_pool = defaulted_pathless_params[0..],
        .evidence_param_paths = path_steps[0..],
    };
    try std.testing.expectEqual(
        EvidencePass.ProcedureEvidenceSchema.from_callable,
        EvidencePass.procedureEvidenceSchemaFromSlices(defaulted_pathless_table.evidenceParams(&template), defaulted_pathless_table.evidence_param_paths),
    );

    template.evidence_params = .{};
    try std.testing.expectEqual(
        EvidencePass.ProcedureEvidenceSchema.none,
        EvidencePass.procedureEvidenceSchemaFromSlices(table.evidenceParams(&template), table.evidence_param_paths),
    );
}

fn siteEvidenceLessThan(_: void, a: static_dispatch.SiteEvidenceEntry, b: static_dispatch.SiteEvidenceEntry) bool {
    return a.key < b.key;
}

fn resolveTotalDispatchPlans(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    checked_types: *const CheckedTypePublication,
    checked_bodies: *const CheckedBodyStore,
    local_method_registry: *const static_dispatch.MethodRegistry,
    import_views: CheckedImportViews,
    plan_table: *static_dispatch.StaticDispatchPlanTable,
    templates: *CheckedProcedureTemplateTable,
    resolved_value_refs: *const ResolvedValueRefTable,
    build_data: *const static_dispatch.PlanTableBuildData,
    template_iterator_refs: *const TemplateIteratorRefs,
    entry_wrappers: *const EntryWrapperTable,
    compile_time_roots: *const CompileTimeRootTable,
    platform_requirement_solutions: []const requirement_solution.SolutionInput,
    platform_requirement_root_evidence: []artifact_serialize.Span,
    template_root_evidence: []artifact_serialize.Span,
) Allocator.Error!void {
    var pass = EvidencePass.init(
        allocator,
        module,
        names,
        checked_types,
        checked_bodies,
        local_method_registry,
        import_views,
        plan_table,
        templates,
        resolved_value_refs,
        build_data,
        template_iterator_refs,
        entry_wrappers,
        compile_time_roots,
        platform_requirement_solutions,
        platform_requirement_root_evidence,
        template_root_evidence,
    );
    defer pass.deinit();
    try pass.run();
}

fn sealConstEvalTemplatesForRoots(
    const_templates: *ConstTemplateTable,
    compile_time_roots: *const CompileTimeRootTable,
    checked_const_bodies: *const CheckedConstBodyTable,
    entry_wrappers: *const EntryWrapperTable,
    checked_procedure_templates: *const CheckedProcedureTemplateTable,
    top_level_values: *const TopLevelValueTable,
    hoisted_constants: *const HoistedConstTable,
) void {
    for (compile_time_roots.roots) |root| {
        if (!compileTimeRootHasConstBody(root.kind)) continue;
        const const_ref = switch (root.kind) {
            .constant => blk: {
                const pattern = root.pattern orelse checkedArtifactInvariant("constant root has no top-level pattern", .{});
                const top_level = top_level_values.lookupByPattern(pattern) orelse {
                    checkedArtifactInvariant("constant root has no top-level value entry", .{});
                };
                break :blk switch (top_level.value) {
                    .const_ref => |ref| ref,
                    .procedure_binding => checkedArtifactInvariant("constant root top-level value is not a ConstRef", .{}),
                };
            },
            .hoisted_constant => blk: {
                const hoisted = hoisted_constants.lookupByRoot(root.id) orelse {
                    checkedArtifactInvariant("hoisted constant root has no hoisted const entry", .{});
                };
                break :blk hoisted.const_ref;
            },
            .callable_binding,
            .expect,
            .numeral_conversion,
            .quote_conversion,
            .field_default,
            => checkedArtifactInvariant("non-constant root reached const eval template sealing", .{}),
        };
        const body = checked_const_bodies.bodyForRoot(root.id) orelse {
            checkedArtifactInvariant("constant root has no checked const body", .{});
        };
        const wrapper = entryWrapperForRoot(entry_wrappers, root.id);
        const template = checked_procedure_templates.get(wrapper.template.template);
        const_templates.fillEval(const_ref, .{
            .body = body,
            .entry_template = wrapper.template,
            .source_scheme = const_ref.source_scheme,
            .resolved_value_refs = template.resolved_value_refs,
            .static_dispatch_plans = template.static_dispatch_plans,
            .nested_proc_sites = template.nested_proc_sites,
        });
    }
}

const CheckedTemplateRefCollector = struct {
    allocator: Allocator,
    module: TypedCIR.Module,
    checked_types: *const CheckedTypePublication,
    checked_bodies: *const CheckedBodyStore,
    static_dispatch_plans: *const static_dispatch.StaticDispatchPlanTable,
    /// Generalized-with-obligations local function decls (checked lambda expr
    /// id -> decl pattern var), prebuilt by the seal pass; entering one pushes
    /// an evidence scope.
    local_schemes: *const std.AutoHashMap(u32, Var),
    /// Checked nested function expr -> `SchemeUseRecord` index for the
    /// construction edge that instantiated it.
    nested_function_uses: *const std.AutoHashMap(u32, u32),
    value_refs: std.ArrayList(ResolvedValueRefId),
    dispatch_refs: std.ArrayList(static_dispatch.StaticDispatchPlanId),
    iterator_refs: std.ArrayList(static_dispatch.IteratorForPlanId),
    /// Scope of each collected ref, parallel to the three ref lists.
    value_ref_scopes: std.ArrayList(DispatchScope),
    dispatch_ref_scopes: std.ArrayList(DispatchScope),
    iterator_ref_scopes: std.ArrayList(DispatchScope),
    scheme_use_sites: std.ArrayList(CollectedSchemeUseSite),
    scheme_use_scopes: std.ArrayList(DispatchScope),
    scope_sites: std.ArrayList(CollectedScopeConstructionSite),
    specialization_relations: std.ArrayList(SpecializationInterfaceRelation),
    specialization_types: std.ArrayList(CheckedTypeId),
    template_root_expr: ?CheckedExprId = null,
    /// Pooled across templates (ids are global); the stack resets per template.
    scopes: std.ArrayList(DispatchRefScope),
    scope_by_checked_expr: collections.DenseMap(CheckedExprId, DispatchScopeId),
    scope_stack: std.ArrayList(DispatchScopeId),
    visited_exprs: collections.DenseMap(CheckedExprId, void),
    visited_patterns: collections.DenseMap(CheckedPatternId, void),
    visited_statements: collections.DenseMap(CheckedStatementId, void),

    fn init(
        allocator: Allocator,
        module: TypedCIR.Module,
        checked_types: *const CheckedTypePublication,
        checked_bodies: *const CheckedBodyStore,
        static_dispatch_plans: *const static_dispatch.StaticDispatchPlanTable,
        local_schemes: *const std.AutoHashMap(u32, Var),
        nested_function_uses: *const std.AutoHashMap(u32, u32),
    ) CheckedTemplateRefCollector {
        return .{
            .allocator = allocator,
            .module = module,
            .checked_types = checked_types,
            .checked_bodies = checked_bodies,
            .static_dispatch_plans = static_dispatch_plans,
            .local_schemes = local_schemes,
            .nested_function_uses = nested_function_uses,
            .value_refs = .empty,
            .dispatch_refs = .empty,
            .iterator_refs = .empty,
            .value_ref_scopes = .empty,
            .dispatch_ref_scopes = .empty,
            .iterator_ref_scopes = .empty,
            .scheme_use_sites = .empty,
            .scheme_use_scopes = .empty,
            .scope_sites = .empty,
            .specialization_relations = .empty,
            .specialization_types = .empty,
            .scopes = .empty,
            .scope_by_checked_expr = collections.DenseMap(CheckedExprId, DispatchScopeId).init(allocator),
            .scope_stack = .empty,
            .visited_exprs = collections.DenseMap(CheckedExprId, void).init(allocator),
            .visited_patterns = collections.DenseMap(CheckedPatternId, void).init(allocator),
            .visited_statements = collections.DenseMap(CheckedStatementId, void).init(allocator),
        };
    }

    fn deinit(self: *CheckedTemplateRefCollector) void {
        self.visited_statements.deinit();
        self.visited_patterns.deinit();
        self.visited_exprs.deinit();
        self.dispatch_refs.deinit(self.allocator);
        self.iterator_refs.deinit(self.allocator);
        self.value_refs.deinit(self.allocator);
        self.value_ref_scopes.deinit(self.allocator);
        self.dispatch_ref_scopes.deinit(self.allocator);
        self.iterator_ref_scopes.deinit(self.allocator);
        self.scheme_use_sites.deinit(self.allocator);
        self.scheme_use_scopes.deinit(self.allocator);
        self.scope_sites.deinit(self.allocator);
        self.specialization_relations.deinit(self.allocator);
        self.specialization_types.deinit(self.allocator);
        self.scopes.deinit(self.allocator);
        self.scope_by_checked_expr.deinit();
        self.scope_stack.deinit(self.allocator);
    }

    fn clear(self: *CheckedTemplateRefCollector) void {
        self.value_refs.clearRetainingCapacity();
        self.dispatch_refs.clearRetainingCapacity();
        self.iterator_refs.clearRetainingCapacity();
        self.value_ref_scopes.clearRetainingCapacity();
        self.dispatch_ref_scopes.clearRetainingCapacity();
        self.iterator_ref_scopes.clearRetainingCapacity();
        self.scheme_use_sites.clearRetainingCapacity();
        self.scheme_use_scopes.clearRetainingCapacity();
        self.scope_sites.clearRetainingCapacity();
        self.specialization_relations.clearRetainingCapacity();
        self.specialization_types.clearRetainingCapacity();
        self.template_root_expr = null;
        // `scopes` pools across templates; only the stack resets.
        self.scope_stack.clearRetainingCapacity();
        self.visited_exprs.clearRetainingCapacity();
        self.visited_patterns.clearRetainingCapacity();
        self.visited_statements.clearRetainingCapacity();
    }

    fn currentScopeId(self: *const CheckedTemplateRefCollector) ?DispatchScopeId {
        if (self.scope_stack.items.len == 0) return null;
        return self.scope_stack.items[self.scope_stack.items.len - 1];
    }

    fn currentScope(self: *const CheckedTemplateRefCollector) DispatchScope {
        return if (self.currentScopeId()) |id| .{ .generalized = id } else .root;
    }

    fn appendValueRef(self: *CheckedTemplateRefCollector, ref_id: ResolvedValueRefId) Allocator.Error!void {
        try self.value_refs.append(self.allocator, ref_id);
        try self.value_ref_scopes.append(self.allocator, self.currentScope());
    }

    fn appendDispatchRef(self: *CheckedTemplateRefCollector, plan_id: static_dispatch.StaticDispatchPlanId) Allocator.Error!void {
        try self.dispatch_refs.append(self.allocator, plan_id);
        try self.dispatch_ref_scopes.append(self.allocator, self.currentScope());
    }

    fn appendProcedureRelation(
        self: *CheckedTemplateRefCollector,
        expr_id: CheckedExprId,
        fn_ty: CheckedTypeId,
        body_ret_ty: CheckedTypeId,
        owns_scope: bool,
    ) Allocator.Error!void {
        if (self.checked_bodies.exprContainsDiagnosticError(expr_id)) return;
        try self.specialization_relations.append(self.allocator, .{
            .scope = self.currentScope(),
            .data = .{ .procedure = .{
                .fn_ty = fn_ty,
                .body_ret_ty = body_ret_ty,
                .owns_scope = owns_scope,
            } },
        });
    }

    fn appendCallRelation(
        self: *CheckedTemplateRefCollector,
        expr_id: CheckedExprId,
        expr: CheckedExpr,
        call: anytype,
    ) Allocator.Error!void {
        if (self.checked_bodies.exprContainsDiagnosticError(expr_id)) return;
        const start: u32 = @intCast(self.specialization_types.items.len);
        try self.specialization_types.ensureUnusedCapacity(self.allocator, call.args.len);
        for (call.args) |arg| {
            self.specialization_types.appendAssumeCapacity(self.checked_bodies.expr(arg).ty);
        }
        try self.specialization_relations.append(self.allocator, .{
            .scope = self.currentScope(),
            .data = .{ .call = .{
                .callable_ty = call.source_fn_ty_payload,
                .callee_ty = self.checked_bodies.expr(call.func).ty,
                .ret_ty = expr.ty,
                .args = .{ .start = start, .len = @intCast(call.args.len) },
                .direct_target = call.direct_target,
            } },
        });
    }

    fn collectExpr(self: *CheckedTemplateRefCollector, expr_id: CheckedExprId) Allocator.Error!void {
        const entry = try self.visited_exprs.getOrPut(expr_id);
        if (entry.found_existing) return;

        const raw_expr = @intFromEnum(expr_id);
        if (self.nested_function_uses.get(raw_expr)) |record_idx| {
            try self.scheme_use_sites.append(self.allocator, .{
                .record_idx = record_idx,
                .checked_expr = expr_id,
            });
            // The construction edge lives in the enclosing scope; the nested
            // function's own evidence scope begins below.
            try self.scheme_use_scopes.append(self.allocator, self.currentScope());
        }

        const local_scheme = self.local_schemes.get(raw_expr);
        if (local_scheme) |scheme_var| {
            const parent = self.currentScopeId();
            const scheme_root = self.checked_types.rootForSourceVar(self.module, scheme_var) orelse
                checkedArtifactInvariant("generalized local dispatch scope had no published checked scheme root", .{});
            const scope_entry = try self.scope_by_checked_expr.getOrPut(expr_id);
            const scope_id = if (scope_entry.found_existing) blk: {
                const existing = self.scopes.items[@intFromEnum(scope_entry.value_ptr.*)];
                if (existing.parent != parent or existing.scheme_var != scheme_var or existing.scheme_root != scheme_root) {
                    checkedArtifactInvariant("generalized local dispatch scope has inconsistent checked ownership", .{});
                }
                break :blk scope_entry.value_ptr.*;
            } else blk: {
                const id: DispatchScopeId = @enumFromInt(@as(u32, @intCast(self.scopes.items.len)));
                scope_entry.value_ptr.* = id;
                try self.scopes.append(self.allocator, .{
                    .parent = parent,
                    .scheme_var = scheme_var,
                    .scheme_root = scheme_root,
                    .checked_expr = expr_id,
                });
                break :blk id;
            };
            try self.scope_sites.append(self.allocator, .{
                .scope = scope_id,
                .checked_expr = expr_id,
            });
            try self.scope_stack.append(self.allocator, scope_id);
        }
        defer {
            if (local_scheme != null) _ = self.scope_stack.pop();
        }

        const expr = self.checked_bodies.expr(expr_id);
        if (expr.data == .lambda) {
            const lambda = expr.data.lambda;
            try self.appendProcedureRelation(
                expr_id,
                expr.ty,
                self.checked_bodies.expr(lambda.body).ty,
                self.template_root_expr == expr_id or local_scheme != null,
            );
        } else if (expr.data == .closure) {
            const closure = expr.data.closure;
            const lambda_data = self.checked_bodies.expr(closure.lambda).data;
            if (lambda_data != .lambda) {
                checkedArtifactInvariant("checked closure specialization relation did not reference a lambda", .{});
            }
            try self.appendProcedureRelation(
                expr_id,
                expr.ty,
                self.checked_bodies.expr(lambda_data.lambda.body).ty,
                self.template_root_expr == expr_id or local_scheme != null,
            );
        }
        switch (expr.data) {
            .lookup_local => |lookup| {
                if (lookup.resolved) |ref_id| try self.appendValueRef(ref_id);
            },
            .lookup_external => |ref_id| {
                if (ref_id) |id| try self.appendValueRef(id);
            },
            .lookup_required => |ref_id| {
                if (ref_id) |id| try self.appendValueRef(id);
            },
            .dispatch_call,
            .method_eq,
            .type_dispatch_call,
            => |plan_id| {
                const id = plan_id orelse checkedArtifactInvariant("checked dispatch expression reached template closure collection without a static-dispatch plan", .{});
                try self.appendDispatchRef(id);
                try self.collectStaticDispatchPlanArgs(id);
            },
            .interpolation => |interpolation| {
                const id = interpolation.plan orelse checkedArtifactInvariant("checked interpolation expression reached template closure collection without a static-dispatch plan", .{});
                try self.appendDispatchRef(id);
                try self.collectStaticDispatchPlanArgs(id);
            },
            .numeral => |numeral| {
                // Builtin-targeted literals carry no plan (their bits are
                // produced at monotype lowering); only custom conversions do.
                if (numeral.plan) |id| {
                    try self.appendDispatchRef(id);
                    try self.collectStaticDispatchPlanArgs(id);
                }
            },
            .str_from_quote => |quote| {
                const id = quote.plan orelse checkedArtifactInvariant("checked from_quote expression reached template closure collection without a dispatch plan", .{});
                try self.appendDispatchRef(id);
                try self.collectStaticDispatchPlanArgs(id);
            },
            .str,
            .list,
            .tuple,
            => |items| {
                for (items) |item| try self.collectExpr(item);
            },
            .match_ => |match| {
                try self.collectExpr(match.cond);
                for (match.branches) |branch| {
                    for (branch.patternsSlice(self.checked_bodies)) |branch_pattern| try self.collectPattern(branch_pattern.pattern);
                    if (branch.guard) |guard| try self.collectExpr(guard);
                    try self.collectExpr(branch.value);
                }
            },
            .if_ => |if_| {
                for (if_.branches) |branch| {
                    try self.collectExpr(branch.cond);
                    try self.collectExpr(branch.body);
                }
                try self.collectExpr(if_.final_else);
            },
            .call => |call| {
                if (call.direct_target) |target| try self.appendValueRef(target);
                try self.collectExpr(call.func);
                for (call.args) |arg| try self.collectExpr(arg);
                try self.appendCallRelation(expr_id, expr, call);
            },
            .record => |record| {
                if (record.ext) |ext| try self.collectExpr(ext);
                for (record.fields) |field| try self.collectExpr(field.value);
            },
            .block => |block| {
                for (block.statements) |statement| try self.collectStatement(statement);
                try self.collectExpr(block.final_expr);
            },
            .tag => |tag| {
                for (tag.args) |arg| try self.collectExpr(arg);
            },
            .nominal => |nominal| try self.collectExpr(nominal.backing_expr),
            .closure => |closure| try self.collectExpr(closure.lambda),
            .lambda => |lambda| {
                for (lambda.args) |arg| try self.collectPattern(arg);
                try self.collectExpr(lambda.body);
            },
            .binop => |binop| {
                try self.collectExpr(binop.lhs);
                try self.collectExpr(binop.rhs);
            },
            .unary_minus => |child| try self.collectExpr(child),
            .unary_not => |child| try self.collectExpr(child),
            .field_access => |field| try self.collectExpr(field.receiver),
            .structural_eq => |eq| {
                try self.collectExpr(eq.lhs);
                try self.collectExpr(eq.rhs);
            },
            .structural_hash => |h| {
                try self.collectExpr(h.value);
                try self.collectExpr(h.hasher);
            },
            .tuple_access => |access| try self.collectExpr(access.tuple),
            .dbg => |child| try self.collectExpr(child),
            .expect_err => |expect_err| try self.collectExpr(expect_err.expr),
            .expect => |child| try self.collectExpr(child),
            .break_ => {},
            .return_ => |ret| {
                try self.collectExpr(ret.expr);
                // `ret.lambda` is the enclosing lambda context for early-return
                // lowering, not an owned child expression.
            },
            .for_ => |for_| {
                const plan_id = for_.plan orelse checkedArtifactInvariant("checked for expression reached template closure collection without an iterator-for plan", .{});
                try self.collectIteratorForPlan(plan_id);
                try self.collectPattern(for_.pattern);
                try self.collectExpr(for_.expr);
                try self.collectExpr(for_.body);
            },
            .hosted_lambda => |hosted| {
                for (hosted.args) |arg| try self.collectPattern(arg);
            },
            .run_low_level => |run| {
                for (run.args) |arg| try self.collectExpr(arg);
            },
            .str_segment,
            .bytes_literal,
            .empty_list,
            .empty_record,
            .zero_argument_tag,
            .runtime_error,
            .crash,
            .ellipsis,
            .anno_only,
            .pending,
            => {},
        }
    }

    fn collectStaticDispatchPlanArgs(
        self: *CheckedTemplateRefCollector,
        plan_id: static_dispatch.StaticDispatchPlanId,
    ) Allocator.Error!void {
        const raw = @intFromEnum(plan_id);
        if (raw >= self.static_dispatch_plans.plans.len) {
            checkedArtifactInvariant("checked template static-dispatch plan id was outside the plan table", .{});
        }
        const plan = self.static_dispatch_plans.plans[raw];
        for (plan.argsSlice(self.static_dispatch_plans)) |arg| switch (arg) {
            .checked_expr => |expr| try self.collectExpr(expr),
            .generated_interpolation_iter => |expr| try self.collectGeneratedInterpolationIter(expr),
            .generated_numeral, .generated_quote => {},
        };
    }

    fn collectGeneratedInterpolationIter(self: *CheckedTemplateRefCollector, expr_id: CheckedExprId) Allocator.Error!void {
        const expr = self.checked_bodies.expr(expr_id);
        if (expr.data != .interpolation) {
            checkedArtifactInvariant("generated interpolation iterator operand pointed at non-interpolation expression", .{});
        }
        const interpolation = expr.data.interpolation;
        for (interpolation.parts) |part| {
            try self.collectExpr(part.value);
            try self.collectExpr(part.following_segment);
        }
    }

    fn collectIteratorForPlan(
        self: *CheckedTemplateRefCollector,
        plan_id: static_dispatch.IteratorForPlanId,
    ) Allocator.Error!void {
        const raw = @intFromEnum(plan_id);
        if (raw >= self.static_dispatch_plans.iterator_for_plans.len) {
            checkedArtifactInvariant("checked template iterator-for plan id was outside the plan table", .{});
        }
        try self.iterator_refs.append(self.allocator, plan_id);
        try self.iterator_ref_scopes.append(self.allocator, self.currentScope());
        const plan = self.static_dispatch_plans.iterator_for_plans[raw];
        try self.collectIteratorDispatchCall(plan.iter);
        try self.collectIteratorDispatchCall(plan.next);
    }

    fn collectIteratorDispatchCall(
        self: *CheckedTemplateRefCollector,
        call: static_dispatch.IteratorDispatchCall,
    ) Allocator.Error!void {
        for (call.argsSlice(self.static_dispatch_plans)) |arg| switch (arg) {
            .checked_expr => |expr| try self.collectExpr(expr),
            .loop_iterator_state => {},
        };
    }

    fn collectPattern(self: *CheckedTemplateRefCollector, pattern_id: CheckedPatternId) Allocator.Error!void {
        const entry = try self.visited_patterns.getOrPut(pattern_id);
        if (entry.found_existing) return;

        const pattern = self.checked_bodies.pattern(pattern_id);
        switch (pattern.data) {
            .as => |as| try self.collectPattern(as.pattern),
            .applied_tag => |tag| {
                for (tag.args) |arg| try self.collectPattern(arg);
            },
            .nominal => |nominal| try self.collectPattern(nominal.backing_pattern),
            .record_destructure => |destructs| {
                for (destructs) |destruct| switch (destruct.kind) {
                    .required => |child| try self.collectPattern(child),
                    .sub_pattern => |child| try self.collectPattern(child),
                    .rest => |child| try self.collectPattern(child),
                };
            },
            .list => |list| {
                for (list.patterns) |child| try self.collectPattern(child);
                if (list.rest) |rest| {
                    if (rest.pattern) |child| try self.collectPattern(child);
                }
            },
            .tuple => |items| {
                for (items) |child| try self.collectPattern(child);
            },
            .str_interpolation => |str| {
                for (str.steps) |step| {
                    if (step.capture) |capture| try self.collectPattern(capture);
                }
            },
            .pending,
            .assign,
            .numeral_literal,
            .str_literal,
            .underscore,
            .runtime_error,
            => {},
        }
    }

    fn collectStatement(self: *CheckedTemplateRefCollector, statement_id: CheckedStatementId) Allocator.Error!void {
        const entry = try self.visited_statements.getOrPut(statement_id);
        if (entry.found_existing) return;

        const statement = self.checked_bodies.statement(statement_id);
        switch (statement.data) {
            .decl => |decl| {
                try self.collectPattern(decl.pattern);
                try self.collectExpr(decl.expr);
            },
            .var_ => |var_| {
                try self.collectPattern(var_.pattern);
                try self.collectExpr(var_.expr);
            },
            .var_uninitialized => |var_| {
                try self.collectPattern(var_.pattern);
            },
            .reassign => |reassign| {
                try self.collectPattern(reassign.pattern);
                try self.collectExpr(reassign.expr);
            },
            .dbg => |child| try self.collectExpr(child),
            .expr => |child| try self.collectExpr(child),
            .expect => |child| try self.collectExpr(child),
            .return_ => |ret| {
                try self.collectExpr(ret.expr);
                // `ret.lambda` is the enclosing lambda context for early-return
                // lowering, not an owned child expression.
            },
            .for_ => |for_| {
                const plan_id = for_.plan orelse checkedArtifactInvariant("checked for statement reached template closure collection without an iterator-for plan", .{});
                try self.collectIteratorForPlan(plan_id);
                try self.collectPattern(for_.pattern);
                try self.collectExpr(for_.expr);
                try self.collectExpr(for_.body);
            },
            .while_ => |while_| {
                try self.collectExpr(while_.cond);
                try self.collectExpr(while_.body);
            },
            .infinite_loop => |loop| {
                try self.collectExpr(loop.cond);
                try self.collectExpr(loop.body);
            },
            .breakable_loop => |loop| {
                try self.collectExpr(loop.cond);
                try self.collectExpr(loop.body);
            },
            .pending,
            .crash,
            .break_,
            .import_,
            .alias_decl,
            .where_alias_decl,
            .nominal_decl,
            .type_anno,
            .type_var_alias,
            .runtime_error,
            => {},
        }
    }
};

/// Public `TopLevelUseSummaryRef` declaration.
pub const TopLevelUseSummaryRef = struct {
    start: u32 = 0,
    len: u32 = 0,
};

/// Public `NestedProcSiteTableRef` declaration.
pub const NestedProcSiteTableRef = struct {
    start: u32 = 0,
    len: u32 = 0,
};

/// Public `NestedProcKind` declaration.
pub const NestedProcKind = enum {
    local_function,
    closure,
    desugared_closure,
};

/// Producer-authored source of a nested procedure's evidence vector.
pub const NestedProcEvidenceSource = enum {
    /// The site does not introduce a dispatch scope and inherits its lexical
    /// evidence unchanged.
    inherited,
    /// Checking recorded an exact scheme-instantiation edge for the site.
    checked_site,
};

/// Public `NestedProcPathComponent` declaration.
pub const NestedProcPathComponent = union(enum) {
    expr: CheckedExprId,
    pattern: CheckedPatternId,
    statement: CheckedStatementId,
    branch: u32,
    desugar: u32,
};

/// Public `NestedProcSite` declaration.
pub const NestedProcSite = struct {
    site: canonical.NestedProcSiteId,
    owner_template: canonical.ProcedureTemplateRef,
    /// Exact generalized-local scope lexically owning this site, or the
    /// template root when the site is outside every generalized local.
    lexical_scope: DispatchScope,
    evidence_source: NestedProcEvidenceSource,
    /// Exact range in `StaticDispatchPlanTable.evidence_refs` when
    /// `evidence_source == .checked_site`; empty otherwise.
    evidence: artifact_serialize.Span,
    /// Range into the owning `NestedProcSiteTable.path_components` pool. Stored as
    /// a POD `(start,len)` (transform B) instead of an embedded slice so the
    /// element relocates with a single fixup.
    path_start: u32,
    path_len: u32,
    kind: NestedProcKind,
    checked_expr: ?CheckedExprId,
    checked_pattern: ?CheckedPatternId,

    /// The site's path components within its table's pool.
    pub fn sitePath(self: NestedProcSite, table: *const NestedProcSiteTable) []const NestedProcPathComponent {
        return table.path_components[self.path_start .. self.path_start + self.path_len];
    }
};

/// Public `NestedProcSiteTable` declaration.
pub const NestedProcSiteTable = struct {
    sites: []NestedProcSite = &.{},
    template_refs: []canonical.NestedProcSiteId = &.{},
    /// Flat pool of all sites' path components (transform-B side list). Each site
    /// holds a `(path_start, path_len)` range into this.
    path_components: []const NestedProcPathComponent = &.{},

    pub const Serialized = extern struct {
        sites: SerializedSlice(NestedProcSite) = .{},
        template_refs: SerializedSlice(canonical.NestedProcSiteId) = .{},
        path_components: SerializedSlice(NestedProcPathComponent) = .{},
        const Serde = artifact_serialize.SliceStoreSerde(NestedProcSiteTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    pub fn fromTemplates(
        allocator: Allocator,
        checked_bodies: *const CheckedBodyStore,
        static_dispatch_plans: *const static_dispatch.StaticDispatchPlanTable,
        method_registry: *const static_dispatch.MethodRegistry,
        entry_wrappers: *const EntryWrapperTable,
        templates: *CheckedProcedureTemplateTable,
    ) Allocator.Error!NestedProcSiteTable {
        var scope_by_checked_expr = try nestedProcScopeMap(allocator, templates.dispatch_scopes);
        defer scope_by_checked_expr.deinit();
        var builder = NestedProcSiteBuilder.init(
            allocator,
            checked_bodies,
            static_dispatch_plans,
            method_registry,
            templates.dispatch_scopes,
            &scope_by_checked_expr,
        );
        defer builder.deinitScratch();
        errdefer builder.deinitAll();

        for (templates.templates) |*template| {
            const start: u32 = @intCast(builder.template_refs.items.len);
            switch (template.body) {
                .checked_body => |body_id| try builder.scanCheckedBody(body_id, template),
                .entry_wrapper => |wrapper_id| try builder.scanEntryWrapper(entry_wrappers.get(wrapper_id), template),
                .intrinsic_wrapper => {},
            }
            template.nested_proc_sites = .{
                .start = start,
                .len = @intCast(builder.template_refs.items.len - start),
            };
        }

        const sites = try builder.sites.toOwnedSlice(allocator);
        errdefer allocator.free(sites);
        const path_components = try builder.path_pool.toOwnedSlice(allocator);
        errdefer allocator.free(path_components);

        return .{
            .sites = sites,
            .template_refs = try builder.template_refs.toOwnedSlice(allocator),
            .path_components = path_components,
        };
    }

    pub fn deinit(self: *NestedProcSiteTable, allocator: Allocator) void {
        allocator.free(self.sites);
        allocator.free(self.template_refs);
        allocator.free(@constCast(self.path_components));
        self.* = .{};
    }
};

/// Public `ProcTarget` declaration.
pub const ProcTarget = union(enum) {
    roc,
    hosted,
    intrinsic,
    entry,
    comptime_only,
};

/// Checker-owned capability for adapting a hosted function whose exact
/// `Builtin.Try` result has a closed structural error row and is requested with
/// a wider error row. The nominal, tags, and type argument positions are
/// explicit so postcheck never recognizes Try by names or backing shape.
pub const HostedTryAdapterCapability = struct {
    nominal: canonical.NominalTypeKey,
    ok_tag: canonical.TagLabelId,
    err_tag: canonical.TagLabelId,
    ok_type_arg_index: u8,
    err_type_arg_index: u8,
};

/// Public `CheckedProcedureTemplate` declaration.
pub const CheckedProcedureTemplate = struct {
    proc_base: canonical.ProcBaseKeyRef,
    template_id: canonical.CheckedProcedureTemplateId,
    body: CheckedProcedureBody,
    checked_fn_scheme: canonical.CanonicalTypeSchemeKey,
    checked_fn_root: CheckedTypeId,
    /// Build/publication traversal span containing every call plan in the
    /// template. Post-check consumers use the classified spans below.
    static_dispatch_plans: StaticDispatchPlanTableRef,
    /// Range into `StaticDispatchPlanTable.direct_template_refs`.
    direct_dispatch_plans: StaticDispatchPlanTableRef,
    /// Range into `StaticDispatchPlanTable.dispatch_relation_refs`.
    dispatch_relations: StaticDispatchPlanTableRef,
    /// Range into
    /// `CheckedProcedureTemplateTable.specialization_interface_relations`.
    specialization_interface_relations: artifact_serialize.Span = .{},
    resolved_value_refs: ResolvedValueRefTableRef,
    top_level_value_uses: TopLevelUseSummaryRef,
    nested_proc_sites: NestedProcSiteTableRef,
    target: ProcTarget,
    hosted_try_adapter: ?HostedTryAdapterCapability = null,
    /// The scheme's dispatch obligations in canonical order (a range into
    /// `CheckedProcedureTemplateTable.evidence_params_pool`). Every
    /// specialization of this template receives one evidence entry per param.
    evidence_params: artifact_serialize.Span = .{},
};

fn checkedTypeIsClosedTagRow(
    checked_types: *const CheckedTypeStore,
    root: CheckedTypeId,
) bool {
    var remaining = checked_types.payloads.items.len;
    var current = root;
    while (true) {
        switch (checked_types.payload(current)) {
            .alias => |alias| current = alias.backing,
            .tag_union => |tag_union| current = tag_union.ext,
            .empty_tag_union => return true,
            .flex, .rigid => |variable| return variable.row_default == .empty_tag_union,
            .pending,
            .err,
            .record,
            .record_unbound,
            .tuple,
            .nominal,
            .function,
            .empty_record,
            => return false,
        }
        if (remaining == 0) {
            checkedArtifactInvariant("hosted Try error row chain was cyclic", .{});
        }
        remaining -= 1;
    }
}

test "hosted Try adapter capability recognizes only closed structural error rows" {
    const allocator = std.testing.allocator;

    var names = canonical.CanonicalNameStore.init(allocator);
    defer names.deinit();

    var store = CheckedTypeStore{};
    defer store.deinit(allocator);

    const empty_row = try store.appendSyntheticPayloadRoot(allocator, &names, .empty_tag_union);
    const non_row = try store.appendSyntheticPayloadRoot(allocator, &names, .empty_record);
    const open_tail = try store.reserveSyntheticTypeRoot(allocator, testCanonicalTypeKey(105), true);
    try store.fillSyntheticTypeRoot(allocator, open_tail, .{ .flex = .{} });
    const defaulted_tail = try store.reserveSyntheticTypeRoot(allocator, testCanonicalTypeKey(106), true);
    try store.fillSyntheticTypeRoot(allocator, defaulted_tail, .{ .flex = .{ .row_default = .empty_tag_union } });

    const error_tag = try names.internTagLabel("HostErr");
    const closed_tags = try allocator.alloc(CheckedTagBuild, 1);
    closed_tags[0] = .{ .name = error_tag };
    const closed_row = try store.appendSyntheticPayloadRoot(allocator, &names, .{ .tag_union = .{
        .tags = closed_tags,
        .ext = empty_row,
    } });

    const open_tags = try allocator.alloc(CheckedTagBuild, 1);
    open_tags[0] = .{ .name = error_tag };
    const open_row = try store.appendSyntheticPayloadRoot(allocator, &names, .{ .tag_union = .{
        .tags = open_tags,
        .ext = open_tail,
    } });

    const defaulted_tags = try allocator.alloc(CheckedTagBuild, 1);
    defaulted_tags[0] = .{ .name = error_tag };
    const defaulted_row = try store.appendSyntheticPayloadRoot(allocator, &names, .{ .tag_union = .{
        .tags = defaulted_tags,
        .ext = defaulted_tail,
    } });

    const alias_name = try names.internTypeName("HostErrors");
    const module_identity = try names.internModuleIdentity(&([_]u8{0x69} ** 32));
    const aliased_row = try store.appendSyntheticPayloadRoot(allocator, &names, .{ .alias = .{
        .name = alias_name,
        .origin_module = module_identity,
        .owner_module = testCheckedModuleKey(105),
        .backing = closed_row,
    } });

    try std.testing.expect(checkedTypeIsClosedTagRow(&store, empty_row));
    try std.testing.expect(checkedTypeIsClosedTagRow(&store, closed_row));
    try std.testing.expect(checkedTypeIsClosedTagRow(&store, defaulted_row));
    try std.testing.expect(checkedTypeIsClosedTagRow(&store, aliased_row));
    try std.testing.expect(!checkedTypeIsClosedTagRow(&store, open_row));
    try std.testing.expect(!checkedTypeIsClosedTagRow(&store, non_row));
}

fn hostedTryAdapterCapabilityForRoot(
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    checked_types: *const CheckedTypeStore,
    checked_fn_root: CheckedTypeId,
) Allocator.Error!?HostedTryAdapterCapability {
    var remaining = checked_types.payloads.items.len;
    var current = checked_fn_root;
    const function = while (true) {
        switch (checked_types.payload(current)) {
            .alias => |alias| current = alias.backing,
            .function => |function| break function,
            .pending,
            .err,
            .flex,
            .rigid,
            .record,
            .record_unbound,
            .tuple,
            .nominal,
            .empty_record,
            .tag_union,
            .empty_tag_union,
            => return null,
        }
        if (remaining == 0) {
            checkedArtifactInvariant("hosted function type alias chain was cyclic", .{});
        }
        remaining -= 1;
    };
    remaining = checked_types.payloads.items.len;
    current = function.ret;
    const nominal = while (true) {
        switch (checked_types.payload(current)) {
            .alias => |alias| current = alias.backing,
            .nominal => |nominal| break nominal,
            .pending,
            .err,
            .flex,
            .rigid,
            .record,
            .record_unbound,
            .tuple,
            .function,
            .empty_record,
            .tag_union,
            .empty_tag_union,
            => return null,
        }
        if (remaining == 0) {
            checkedArtifactInvariant("hosted result type alias chain was cyclic", .{});
        }
        remaining -= 1;
    };
    if (nominal.builtin != .try_) return null;
    if (nominal.args.len != 2) {
        checkedArtifactInvariant("Builtin.Try checked type did not have exactly two type arguments", .{});
    }
    if (!checkedTypeIsClosedTagRow(checked_types, nominal.args[1])) return null;
    const idents = module.commonIdents();
    return .{
        .nominal = checkedNominalTypeKey(nominal),
        .ok_tag = try names.internTagIdent(module.identStoreConst(), idents.ok),
        .err_tag = try names.internTagIdent(module.identStoreConst(), idents.err),
        .ok_type_arg_index = 0,
        .err_type_arg_index = 1,
    };
}

/// Public `CheckedProcedureTemplateTable` declaration.
pub const CheckedProcedureTemplateTable = struct {
    templates: []CheckedProcedureTemplate = &.{},
    by_def: []static_dispatch.ProcedureTemplateLookupEntry = &.{},
    /// Flat pool backing each template's `evidence_params` span.
    evidence_params_pool: []static_dispatch.EvidenceParamRecord = &.{},
    /// Flat pool backing each evidence param's `path` span.
    evidence_param_paths: []static_dispatch.EvidencePathStep = &.{},
    /// Scope of each `StaticDispatchPlanTable.dispatch_relation_refs` entry.
    dispatch_ref_scopes: []DispatchScope = &.{},
    /// Relation semantics of each
    /// `StaticDispatchPlanTable.dispatch_relation_refs` entry.
    dispatch_relation_kinds: []DispatchRelationKind = &.{},
    /// Generalized-local scopes referenced by `dispatch_ref_scopes`.
    dispatch_scopes: []DispatchRefScope = &.{},
    /// Flat pool of checker-authored relations that complete callable
    /// interfaces before specialization keys are sealed.
    specialization_interface_relations: []SpecializationInterfaceRelation = &.{},
    /// Checked argument types backing call-relation spans.
    specialization_interface_types: []CheckedTypeId = &.{},

    pub const Serialized = extern struct {
        templates: SerializedSlice(CheckedProcedureTemplate) = .{},
        by_def: SerializedSlice(static_dispatch.ProcedureTemplateLookupEntry) = .{},
        evidence_params_pool: SerializedSlice(static_dispatch.EvidenceParamRecord) = .{},
        evidence_param_paths: SerializedSlice(static_dispatch.EvidencePathStep) = .{},
        dispatch_ref_scopes: SerializedSlice(DispatchScope) = .{},
        dispatch_relation_kinds: SerializedSlice(DispatchRelationKind) = .{},
        dispatch_scopes: SerializedSlice(DispatchRefScope) = .{},
        specialization_interface_relations: SerializedSlice(SpecializationInterfaceRelation) = .{},
        specialization_interface_types: SerializedSlice(CheckedTypeId) = .{},
        const Serde = artifact_serialize.SliceStoreSerde(CheckedProcedureTemplateTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    pub fn fromModule(
        allocator: Allocator,
        module: TypedCIR.Module,
        global_value_defs: []const CIR.Def.Idx,
        names: *canonical.CanonicalNameStore,
        owner_artifact: canonical.ArtifactRef,
        checked_type_publication: *CheckedTypePublication,
        relation_substitutions: *const PlatformRelationTypeSubstitutions,
        checked_bodies: *CheckedBodyStore,
        intrinsic_wrappers: *IntrinsicWrapperTable,
    ) Allocator.Error!CheckedProcedureTemplateTable {
        var templates = std.ArrayList(CheckedProcedureTemplate).empty;
        errdefer templates.deinit(allocator);
        var by_def = std.ArrayList(static_dispatch.ProcedureTemplateLookupEntry).empty;
        errdefer by_def.deinit(allocator);

        const module_name = try names.internModuleIdent(module.identStoreConst(), module.qualifiedModuleIdent());

        for (global_value_defs) |def_idx| {
            const def = module.def(def_idx);
            if (!topLevelExprIsAlreadyProcedure(def.expr.data)) continue;

            const export_name = if (def.patternName()) |name|
                try names.internExportIdent(module.identStoreConst(), name)
            else
                null;
            const intrinsic = intrinsicForProcedureDef(module, def_idx);
            const proc_base = try names.internProcBase(.{
                .module_name = module_name,
                .export_name = export_name,
                .kind = if (intrinsic != null) .intrinsic_wrapper else if (isHostedProcedureExpr(def.expr.data)) .hosted_wrapper else .checked_source,
                .ordinal = @intFromEnum(def_idx),
                .source_def_idx = @intFromEnum(def_idx),
            });
            const template_id: canonical.CheckedProcedureTemplateId = @enumFromInt(@as(u32, @intCast(templates.items.len)));
            const template_ref = canonical.ProcedureTemplateRef{
                .artifact = owner_artifact,
                .proc_base = proc_base,
                .template = template_id,
            };
            try by_def.append(allocator, .{
                .def = def_idx,
                .template = template_ref,
                .kind = if (intrinsic) |intrinsic_id| switch (intrinsic_id) {
                    .structural_eq => .{ .structural = .equality },
                    .str_inspect,
                    .parse_tag_union,
                    .field_names_rename_fields,
                    .field_names_shortest_name,
                    .field_names_longest_name,
                    .field_names_iter,
                    .field_names_for_size,
                    .field_name,
                    => .callable,
                } else .callable,
            });
            const source_checked_fn_root = checked_type_publication.rootForSourceVar(module, module.defType(def_idx)) orelse {
                if (builtin.mode == .Debug) {
                    std.debug.panic("checked artifact invariant violated: checked procedure function root was not published", .{});
                }
                unreachable;
            };
            const source_checked_fn_scheme = try canonical_type_keys.schemeFromVar(
                allocator,
                module.typeStoreConst(),
                module.moduleEnvConst(),
                module.defType(def_idx),
            );
            const checked_fn_root = try relation_substitutions.specializeRoot(
                allocator,
                names,
                &checked_type_publication.store,
                source_checked_fn_root,
            );
            const checked_fn_scheme = if (checked_fn_root == source_checked_fn_root)
                source_checked_fn_scheme
            else
                syntheticSchemeKeyForType(checked_type_publication.store.roots.items[@intFromEnum(checked_fn_root)].key);
            const body: CheckedProcedureBody = if (intrinsic) |intrinsic_id| blk: {
                const wrapper_id = try intrinsic_wrappers.append(allocator, template_ref, checked_fn_root, intrinsic_id);
                break :blk .{ .intrinsic_wrapper = wrapper_id };
            } else blk: {
                const root_expr = checked_bodies.exprIdForSource(def.expr.idx) orelse {
                    if (builtin.mode == .Debug) {
                        std.debug.panic("checked artifact invariant violated: checked procedure body root expression was not published", .{});
                    }
                    unreachable;
                };
                break :blk .{ .checked_body = try checked_bodies.appendBody(allocator, root_expr, template_ref) };
            };

            try templates.append(allocator, .{
                .proc_base = proc_base,
                .template_id = template_id,
                .body = body,
                .checked_fn_scheme = checked_fn_scheme,
                .checked_fn_root = checked_fn_root,
                .static_dispatch_plans = .{},
                .direct_dispatch_plans = .{},
                .dispatch_relations = .{},
                .resolved_value_refs = .{},
                .top_level_value_uses = .{},
                .nested_proc_sites = .{},
                .target = if (intrinsic != null)
                    .intrinsic
                else if (isHostedProcedureExpr(def.expr.data))
                    .hosted
                else
                    .roc,
                .hosted_try_adapter = if (isHostedProcedureExpr(def.expr.data))
                    try hostedTryAdapterCapabilityForRoot(module, names, &checked_type_publication.store, checked_fn_root)
                else
                    null,
            });
        }

        std.mem.sort(static_dispatch.ProcedureTemplateLookupEntry, by_def.items, {}, static_dispatch.ProcedureTemplateLookupEntry.lessThan);
        const template_slice = try templates.toOwnedSlice(allocator);
        errdefer allocator.free(template_slice);
        const by_def_slice = try by_def.toOwnedSlice(allocator);
        return .{
            .templates = template_slice,
            .by_def = by_def_slice,
        };
    }

    pub fn lookupByDef(self: *const CheckedProcedureTemplateTable, def_idx: CIR.Def.Idx) ?canonical.ProcedureTemplateRef {
        var lo: usize = 0;
        var hi: usize = self.by_def.len;
        const target = @intFromEnum(def_idx);
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            const candidate = @intFromEnum(self.by_def[mid].def);
            if (candidate < target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        if (lo >= self.by_def.len or self.by_def[lo].def != def_idx) return null;
        return self.by_def[lo].template;
    }

    pub fn appendEntryWrappersForRoots(
        self: *CheckedProcedureTemplateTable,
        allocator: Allocator,
        module: TypedCIR.Module,
        names: *canonical.CanonicalNameStore,
        owner_artifact: canonical.ArtifactRef,
        checked_types: *CheckedTypeStore,
        entry_wrappers: *EntryWrapperTable,
        compile_time_roots: *const CompileTimeRootTable,
    ) Allocator.Error!void {
        const module_name = try names.internModuleIdent(module.identStoreConst(), module.qualifiedModuleIdent());

        for (compile_time_roots.roots) |root| {
            const checked_fn_root = try checked_types.appendSyntheticFunctionRoot(
                allocator,
                .pure,
                &.{},
                root.checked_type,
            );
            const checked_fn_scheme = syntheticSchemeKeyForType(checked_types.roots.items[@intFromEnum(checked_fn_root)].key);
            const proc_base = try names.internProcBase(.{
                .module_name = module_name,
                .export_name = null,
                .kind = .entry_wrapper,
                .ordinal = @intFromEnum(root.id),
                .source_def_idx = null,
            });
            const template_id: canonical.CheckedProcedureTemplateId = @enumFromInt(@as(u32, @intCast(self.templates.len)));
            const template_ref = canonical.ProcedureTemplateRef{
                .artifact = owner_artifact,
                .proc_base = proc_base,
                .template = template_id,
            };
            const wrapper_id = try entry_wrappers.append(allocator, root.id, template_ref, checked_fn_root, root.expr);
            try self.appendTemplate(allocator, .{
                .proc_base = proc_base,
                .template_id = template_id,
                .body = .{ .entry_wrapper = wrapper_id },
                .checked_fn_scheme = checked_fn_scheme,
                .checked_fn_root = checked_fn_root,
                .static_dispatch_plans = .{},
                .direct_dispatch_plans = .{},
                .dispatch_relations = .{},
                .resolved_value_refs = .{},
                .top_level_value_uses = .{},
                .nested_proc_sites = .{},
                .target = switch (root.kind) {
                    .expect => .entry,
                    .constant, .hoisted_constant, .callable_binding, .numeral_conversion, .quote_conversion, .field_default => .comptime_only,
                },
            });
        }
    }

    fn appendTemplate(
        self: *CheckedProcedureTemplateTable,
        allocator: Allocator,
        template: CheckedProcedureTemplate,
    ) Allocator.Error!void {
        const old = self.templates;
        const next = try allocator.alloc(CheckedProcedureTemplate, old.len + 1);
        @memcpy(next[0..old.len], old);
        next[old.len] = template;
        allocator.free(old);
        self.templates = next;
    }

    pub fn get(self: *const CheckedProcedureTemplateTable, id: canonical.CheckedProcedureTemplateId) CheckedProcedureTemplate {
        return self.templates[@intFromEnum(id)];
    }

    pub fn view(self: *const CheckedProcedureTemplateTable) CheckedProcedureTemplateTableView {
        return .{ .templates = self.templates };
    }

    pub fn asLookup(self: *const CheckedProcedureTemplateTable, module_idx: u32) static_dispatch.ProcedureTemplateLookup {
        return .{
            .module_idx = module_idx,
            .by_def = self.by_def,
        };
    }

    pub fn deinit(self: *CheckedProcedureTemplateTable, allocator: Allocator) void {
        allocator.free(self.by_def);
        allocator.free(self.templates);
        allocator.free(self.evidence_params_pool);
        allocator.free(self.evidence_param_paths);
        allocator.free(self.dispatch_ref_scopes);
        allocator.free(self.dispatch_relation_kinds);
        allocator.free(self.dispatch_scopes);
        allocator.free(self.specialization_interface_relations);
        allocator.free(self.specialization_interface_types);
        self.* = .{};
    }

    /// The template's evidence params, in canonical order.
    pub fn evidenceParams(self: *const CheckedProcedureTemplateTable, template: *const CheckedProcedureTemplate) []const static_dispatch.EvidenceParamRecord {
        return self.evidence_params_pool[template.evidence_params.start .. template.evidence_params.start + template.evidence_params.len];
    }

    /// The param's dispatcher path over the scheme callable (empty =
    /// pathless).
    pub fn evidenceParamPath(self: *const CheckedProcedureTemplateTable, param: static_dispatch.EvidenceParamRecord) []const static_dispatch.EvidencePathStep {
        return self.evidence_param_paths[param.path.start .. param.path.start + param.path.len];
    }

    pub fn specializationRelations(self: *const CheckedProcedureTemplateTable, template: *const CheckedProcedureTemplate) []const SpecializationInterfaceRelation {
        const span = template.specialization_interface_relations;
        return self.specialization_interface_relations[span.start .. span.start + span.len];
    }

    pub fn specializationRelationTypes(self: *const CheckedProcedureTemplateTable, span: artifact_serialize.Span) []const CheckedTypeId {
        return self.specialization_interface_types[span.start .. span.start + span.len];
    }
};

/// Public `CheckedProcedureTemplateTableView` declaration.
pub const CheckedProcedureTemplateTableView = struct {
    templates: []const CheckedProcedureTemplate = &.{},
};

fn nestedProcScopeMap(
    allocator: Allocator,
    scopes: []const DispatchRefScope,
) Allocator.Error!collections.DenseMap(CheckedExprId, DispatchScopeId) {
    var by_checked_expr = collections.DenseMap(CheckedExprId, DispatchScopeId).init(allocator);
    errdefer by_checked_expr.deinit();
    try by_checked_expr.ensureTotalCapacity(@intCast(scopes.len));
    for (scopes, 0..) |scope, raw_scope| {
        const entry = by_checked_expr.getOrPutAssumeCapacity(scope.checked_expr);
        if (entry.found_existing) {
            checkedArtifactInvariant("checked expression owned more than one generalized dispatch scope", .{});
        }
        entry.value_ptr.* = @enumFromInt(@as(u32, @intCast(raw_scope)));
    }
    return by_checked_expr;
}

fn nestedProcLexicalScope(
    current: DispatchScope,
    expr: CheckedExprId,
    by_checked_expr: *const collections.DenseMap(CheckedExprId, DispatchScopeId),
    scopes: []const DispatchRefScope,
) DispatchScope {
    const scope_id = by_checked_expr.get(expr) orelse return current;
    const raw_scope = @intFromEnum(scope_id);
    if (raw_scope >= scopes.len or scopes[raw_scope].checked_expr != expr) {
        checkedArtifactInvariant("nested procedure lexical scope map disagreed with the checked scope table", .{});
    }
    const expected_parent: DispatchScope = if (scopes[raw_scope].parent) |parent|
        .{ .generalized = parent }
    else
        .root;
    if (!std.meta.eql(current, expected_parent)) {
        checkedArtifactInvariant("generalized nested procedure site had the wrong lexical parent scope", .{});
    }
    return .{ .generalized = scope_id };
}

const NestedProcSiteBuilder = struct {
    allocator: Allocator,
    checked_bodies: *const CheckedBodyStore,
    static_dispatch_plans: *const static_dispatch.StaticDispatchPlanTable,
    method_registry: *const static_dispatch.MethodRegistry,
    dispatch_scopes: []const DispatchRefScope,
    scope_by_checked_expr: *const collections.DenseMap(CheckedExprId, DispatchScopeId),
    current_scope: DispatchScope,
    sites: std.ArrayList(NestedProcSite),
    template_refs: std.ArrayList(canonical.NestedProcSiteId),
    path: std.ArrayList(NestedProcPathComponent),
    /// Accumulated flat pool of every site's path; moved into the finished table.
    path_pool: std.ArrayList(NestedProcPathComponent),

    fn init(
        allocator: Allocator,
        checked_bodies: *const CheckedBodyStore,
        static_dispatch_plans: *const static_dispatch.StaticDispatchPlanTable,
        method_registry: *const static_dispatch.MethodRegistry,
        dispatch_scopes: []const DispatchRefScope,
        scope_by_checked_expr: *const collections.DenseMap(CheckedExprId, DispatchScopeId),
    ) NestedProcSiteBuilder {
        return .{
            .allocator = allocator,
            .checked_bodies = checked_bodies,
            .static_dispatch_plans = static_dispatch_plans,
            .method_registry = method_registry,
            .dispatch_scopes = dispatch_scopes,
            .scope_by_checked_expr = scope_by_checked_expr,
            .current_scope = .root,
            .sites = .empty,
            .template_refs = .empty,
            .path = .empty,
            .path_pool = .empty,
        };
    }

    fn deinitScratch(self: *NestedProcSiteBuilder) void {
        self.path.deinit(self.allocator);
    }

    fn deinitAll(self: *NestedProcSiteBuilder) void {
        self.sites.deinit(self.allocator);
        self.template_refs.deinit(self.allocator);
        self.path.deinit(self.allocator);
        self.path_pool.deinit(self.allocator);
        self.* = NestedProcSiteBuilder.init(
            self.allocator,
            self.checked_bodies,
            self.static_dispatch_plans,
            self.method_registry,
            self.dispatch_scopes,
            self.scope_by_checked_expr,
        );
    }

    fn scanCheckedBody(
        self: *NestedProcSiteBuilder,
        body_id: CheckedBodyId,
        _: *const CheckedProcedureTemplate,
    ) Allocator.Error!void {
        const body = self.checked_bodies.body(body_id);
        self.path.clearRetainingCapacity();
        self.current_scope = .root;
        try self.scanExpr(body.root_expr, body.owner_template, true);
    }

    fn scanEntryWrapper(
        self: *NestedProcSiteBuilder,
        wrapper: EntryWrapper,
        _: *const CheckedProcedureTemplate,
    ) Allocator.Error!void {
        self.path.clearRetainingCapacity();
        self.current_scope = .root;
        try self.scanExpr(wrapper.body_expr, wrapper.template, false);
    }

    fn addSite(
        self: *NestedProcSiteBuilder,
        owner: canonical.ProcedureTemplateRef,
        kind: NestedProcKind,
        checked_expr: ?CheckedExprId,
        checked_pattern: ?CheckedPatternId,
    ) Allocator.Error!void {
        const site: canonical.NestedProcSiteId = @enumFromInt(@as(u32, @intCast(self.sites.items.len)));
        const path_start: u32 = @intCast(self.path_pool.items.len);
        try self.path_pool.appendSlice(self.allocator, self.path.items);

        const evidence_source, const evidence = switch (self.current_scope) {
            .root => .{ NestedProcEvidenceSource.inherited, artifact_serialize.Span{} },
            .generalized => |scope_id| blk: {
                const raw_scope = @intFromEnum(scope_id);
                if (raw_scope >= self.dispatch_scopes.len) {
                    checkedArtifactInvariant("nested procedure site owned an unknown checked dispatch scope", .{});
                }
                const scope = self.dispatch_scopes[raw_scope];
                if (checked_expr == null or scope.checked_expr != checked_expr.?) {
                    break :blk .{ NestedProcEvidenceSource.inherited, artifact_serialize.Span{} };
                }
                const span = self.static_dispatch_plans.siteEvidenceSpan(checked_expr.?) orelse
                    checkedArtifactInvariant("nested procedure scope had no producer-authored construction evidence", .{});
                break :blk .{ NestedProcEvidenceSource.checked_site, span };
            },
        };

        try self.sites.append(self.allocator, .{
            .site = site,
            .owner_template = owner,
            .lexical_scope = self.current_scope,
            .evidence_source = evidence_source,
            .evidence = evidence,
            .path_start = path_start,
            .path_len = @intCast(self.path.items.len),
            .kind = kind,
            .checked_expr = checked_expr,
            .checked_pattern = checked_pattern,
        });
        try self.template_refs.append(self.allocator, site);
    }

    fn scanExpr(
        self: *NestedProcSiteBuilder,
        expr_id: CheckedExprId,
        owner: canonical.ProcedureTemplateRef,
        suppress_current_site: bool,
    ) Allocator.Error!void {
        try self.path.append(self.allocator, .{ .expr = expr_id });
        defer self.path.items.len -= 1;

        const previous_scope = self.current_scope;
        self.current_scope = nestedProcLexicalScope(
            previous_scope,
            expr_id,
            self.scope_by_checked_expr,
            self.dispatch_scopes,
        );
        defer self.current_scope = previous_scope;

        const expr = self.checked_bodies.expr(expr_id);
        switch (expr.data) {
            .closure => |closure| {
                if (!suppress_current_site) {
                    try self.addSite(owner, .closure, expr_id, null);
                }
                try self.scanExpr(closure.lambda, owner, true);
            },
            .lambda => |lambda| {
                if (!suppress_current_site) {
                    try self.addSite(owner, .local_function, expr_id, null);
                }
                for (lambda.args) |arg| try self.scanPattern(arg, owner);
                try self.scanExpr(lambda.body, owner, false);
            },
            .str,
            .list,
            .tuple,
            => |items| {
                for (items) |item| try self.scanExpr(item, owner, false);
            },
            .match_ => |match| {
                try self.scanExpr(match.cond, owner, false);
                for (match.branches, 0..) |branch, i| {
                    try self.path.append(self.allocator, .{ .branch = @intCast(i) });
                    for (branch.patternsSlice(self.checked_bodies)) |branch_pattern| try self.scanPattern(branch_pattern.pattern, owner);
                    if (branch.guard) |guard| try self.scanExpr(guard, owner, false);
                    try self.scanExpr(branch.value, owner, false);
                    self.path.items.len -= 1;
                }
            },
            .if_ => |if_| {
                for (if_.branches) |branch| {
                    try self.scanExpr(branch.cond, owner, false);
                    try self.scanExpr(branch.body, owner, false);
                }
                try self.scanExpr(if_.final_else, owner, false);
            },
            .call => |call| {
                try self.scanExpr(call.func, owner, false);
                for (call.args) |arg| try self.scanExpr(arg, owner, false);
            },
            .record => |record| {
                if (record.ext) |ext| try self.scanExpr(ext, owner, false);
                for (record.fields) |field| try self.scanExpr(field.value, owner, false);
            },
            .block => |block| {
                for (block.statements) |statement| try self.scanStatement(statement, owner);
                try self.scanExpr(block.final_expr, owner, false);
            },
            .tag => |tag| {
                for (tag.args) |arg| try self.scanExpr(arg, owner, false);
            },
            .nominal => |nominal| try self.scanExpr(nominal.backing_expr, owner, false),
            .binop => |binop| {
                try self.scanExpr(binop.lhs, owner, false);
                try self.scanExpr(binop.rhs, owner, false);
            },
            .unary_minus => |child| try self.scanExpr(child, owner, false),
            .unary_not => |child| try self.scanExpr(child, owner, false),
            .dbg => |child| try self.scanExpr(child, owner, false),
            .expect_err => |expect_err| try self.scanExpr(expect_err.expr, owner, false),
            .expect => |child| try self.scanExpr(child, owner, false),
            .break_ => {},
            .return_ => |ret| {
                try self.scanExpr(ret.expr, owner, false);
                // `ret.lambda` is the enclosing lambda context for early-return
                // lowering, not an owned child expression.
            },
            .field_access => |field| try self.scanExpr(field.receiver, owner, false),
            .dispatch_call,
            .method_eq,
            .type_dispatch_call,
            => |plan_id| try self.scanStaticDispatchPlanArgs(plan_id orelse checkedArtifactInvariant("checked dispatch expression reached nested procedure site collection without a static-dispatch plan", .{}), owner),
            .interpolation => |interpolation| try self.scanStaticDispatchPlanArgs(interpolation.plan orelse checkedArtifactInvariant("checked interpolation expression reached nested procedure site collection without a static-dispatch plan", .{}), owner),
            .numeral => |numeral| if (numeral.plan) |plan_id| try self.scanStaticDispatchPlanArgs(plan_id, owner),
            .str_from_quote => |quote| try self.scanStaticDispatchPlanArgs(quote.plan orelse checkedArtifactInvariant("checked from_quote expression reached nested procedure site collection without a dispatch plan", .{}), owner),
            .structural_eq => |eq| {
                try self.scanExpr(eq.lhs, owner, false);
                try self.scanExpr(eq.rhs, owner, false);
            },
            .structural_hash => |h| {
                try self.scanExpr(h.value, owner, false);
                try self.scanExpr(h.hasher, owner, false);
            },
            .tuple_access => |access| try self.scanExpr(access.tuple, owner, false),
            .for_ => |for_| {
                try self.scanPattern(for_.pattern, owner);
                try self.scanExpr(for_.expr, owner, false);
                try self.scanExpr(for_.body, owner, false);
            },
            .hosted_lambda => |hosted| {
                if (!suppress_current_site) {
                    try self.addSite(owner, .local_function, expr_id, null);
                }
                for (hosted.args) |arg| try self.scanPattern(arg, owner);
            },
            .run_low_level => |run| {
                for (run.args) |arg| try self.scanExpr(arg, owner, false);
            },
            .str_segment,
            .bytes_literal,
            .lookup_local,
            .lookup_external,
            .lookup_required,
            .empty_list,
            .empty_record,
            .zero_argument_tag,
            .runtime_error,
            .crash,
            .ellipsis,
            .anno_only,
            .pending,
            => {},
        }
    }

    fn scanStaticDispatchPlanArgs(
        self: *NestedProcSiteBuilder,
        plan_id: static_dispatch.StaticDispatchPlanId,
        owner: canonical.ProcedureTemplateRef,
    ) Allocator.Error!void {
        const raw = @intFromEnum(plan_id);
        if (raw >= self.static_dispatch_plans.plans.len) {
            checkedArtifactInvariant("checked template static-dispatch plan id was outside the plan table", .{});
        }
        const plan = self.static_dispatch_plans.plans[raw];
        for (plan.argsSlice(self.static_dispatch_plans)) |arg| switch (arg) {
            .checked_expr => |expr| try self.scanExpr(expr, owner, false),
            .generated_interpolation_iter => |expr| try self.scanGeneratedInterpolationIter(expr, owner),
            .generated_numeral, .generated_quote => {},
        };
    }

    fn scanGeneratedInterpolationIter(
        self: *NestedProcSiteBuilder,
        expr_id: CheckedExprId,
        owner: canonical.ProcedureTemplateRef,
    ) Allocator.Error!void {
        const expr = self.checked_bodies.expr(expr_id);
        if (expr.data != .interpolation) {
            checkedArtifactInvariant("generated interpolation iterator operand pointed at non-interpolation expression", .{});
        }
        const interpolation = expr.data.interpolation;
        for (interpolation.parts) |part| {
            try self.scanExpr(part.value, owner, false);
            try self.scanExpr(part.following_segment, owner, false);
        }
    }

    fn scanPattern(
        self: *NestedProcSiteBuilder,
        pattern_id: CheckedPatternId,
        owner: canonical.ProcedureTemplateRef,
    ) Allocator.Error!void {
        try self.path.append(self.allocator, .{ .pattern = pattern_id });
        defer self.path.items.len -= 1;

        const pattern = self.checked_bodies.pattern(pattern_id);
        switch (pattern.data) {
            .as => |as| try self.scanPattern(as.pattern, owner),
            .applied_tag => |tag| {
                for (tag.args) |arg| try self.scanPattern(arg, owner);
            },
            .nominal => |nominal| try self.scanPattern(nominal.backing_pattern, owner),
            .record_destructure => |destructs| {
                for (destructs) |destruct| switch (destruct.kind) {
                    .required => |child| try self.scanPattern(child, owner),
                    .sub_pattern => |child| try self.scanPattern(child, owner),
                    .rest => |child| try self.scanPattern(child, owner),
                };
            },
            .list => |list| {
                for (list.patterns) |child| try self.scanPattern(child, owner);
                if (list.rest) |rest| {
                    if (rest.pattern) |child| try self.scanPattern(child, owner);
                }
            },
            .tuple => |items| {
                for (items) |child| try self.scanPattern(child, owner);
            },
            .str_interpolation => |str| {
                for (str.steps) |step| {
                    if (step.capture) |capture| try self.scanPattern(capture, owner);
                }
            },
            .pending,
            .assign,
            .numeral_literal,
            .str_literal,
            .underscore,
            .runtime_error,
            => {},
        }
    }

    fn scanStatement(
        self: *NestedProcSiteBuilder,
        statement_id: CheckedStatementId,
        owner: canonical.ProcedureTemplateRef,
    ) Allocator.Error!void {
        try self.path.append(self.allocator, .{ .statement = statement_id });
        defer self.path.items.len -= 1;

        const statement = self.checked_bodies.statement(statement_id);
        switch (statement.data) {
            .decl => |decl| {
                try self.scanPattern(decl.pattern, owner);
                try self.scanExpr(decl.expr, owner, false);
            },
            .var_ => |var_| {
                try self.scanPattern(var_.pattern, owner);
                try self.scanExpr(var_.expr, owner, false);
            },
            .var_uninitialized => |var_| {
                try self.scanPattern(var_.pattern, owner);
            },
            .reassign => |reassign| {
                try self.scanPattern(reassign.pattern, owner);
                try self.scanExpr(reassign.expr, owner, false);
            },
            .dbg => |child| try self.scanExpr(child, owner, false),
            .expr => |child| try self.scanExpr(child, owner, false),
            .expect => |child| try self.scanExpr(child, owner, false),
            .return_ => |ret| {
                try self.scanExpr(ret.expr, owner, false);
                // `ret.lambda` is the enclosing lambda context for early-return
                // lowering, not an owned child expression.
            },
            .for_ => |for_| {
                try self.scanPattern(for_.pattern, owner);
                try self.scanExpr(for_.expr, owner, false);
                try self.scanExpr(for_.body, owner, false);
            },
            .while_ => |while_| {
                try self.scanExpr(while_.cond, owner, false);
                try self.scanExpr(while_.body, owner, false);
            },
            .infinite_loop => |loop| {
                try self.scanExpr(loop.cond, owner, false);
                try self.scanExpr(loop.body, owner, false);
            },
            .breakable_loop => |loop| {
                try self.scanExpr(loop.cond, owner, false);
                try self.scanExpr(loop.body, owner, false);
            },
            .alias_decl,
            .where_alias_decl,
            .nominal_decl,
            => try self.scanAttachedLocalProcedures(statement_id, owner),
            .pending,
            .crash,
            .break_,
            .import_,
            .type_anno,
            .type_var_alias,
            .runtime_error,
            => {},
        }
    }

    fn scanAttachedLocalProcedures(
        self: *NestedProcSiteBuilder,
        statement_id: CheckedStatementId,
        owner: canonical.ProcedureTemplateRef,
    ) Allocator.Error!void {
        for (self.method_registry.entries) |entry| switch (entry.target.kind) {
            .local_proc => |local| {
                if (local.context_anchor == statement_id) {
                    try self.scanExpr(local.expr, owner, false);
                }
            },
            .procedure, .structural => {},
        };
    }
};

/// Public `HostedProc` declaration.
pub const HostedProc = struct {
    module_idx: u32,
    def_idx: CIR.Def.Idx,
    expr_idx: CIR.Expr.Idx,
    external_symbol_name: canonical.ExternalSymbolNameId,
    deterministic_index: u32,
    /// Range into `HostedProcTable.order_key_bytes` (transform-B side list).
    order_key_start: u32,
    order_key_len: u32,
    proc: canonical.ProcedureValueRef,
    template: canonical.ProcedureTemplateRef,

    /// The proc's deterministic ordering key bytes within its table's pool.
    pub fn orderKey(self: HostedProc, table: *const HostedProcTable) []const u8 {
        return table.order_key_bytes[self.order_key_start .. self.order_key_start + self.order_key_len];
    }
};

/// Public `HostedProcTable` declaration.
pub const HostedProcTable = struct {
    procs: []HostedProc = &.{},
    /// Flat pool of all procs' order-key bytes (transform-B side list).
    order_key_bytes: []const u8 = &.{},

    pub const Serialized = extern struct {
        procs: SerializedSlice(HostedProc) = .{},
        order_key_bytes: SerializedSlice(u8) = .{},
        const Serde = artifact_serialize.SliceStoreSerde(HostedProcTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    const Candidate = struct {
        module_idx: u32,
        def_idx: CIR.Def.Idx,
        expr_idx: CIR.Expr.Idx,
        external_symbol_name: canonical.ExternalSymbolNameId,
        proc: canonical.ProcedureValueRef,
        template: canonical.ProcedureTemplateRef,
        sort_key: []const u8,
    };

    pub fn fromModule(
        allocator: Allocator,
        module: TypedCIR.Module,
        hosted_defs: []const CIR.Def.Idx,
        names: *canonical.CanonicalNameStore,
        templates: *const CheckedProcedureTemplateTable,
    ) Allocator.Error!HostedProcTable {
        var candidates = std.ArrayList(Candidate).empty;
        defer {
            for (candidates.items) |candidate| allocator.free(candidate.sort_key);
            candidates.deinit(allocator);
        }

        var procs = std.ArrayList(HostedProc).empty;
        errdefer procs.deinit(allocator);
        var order_key_bytes = std.ArrayList(u8).empty;
        errdefer order_key_bytes.deinit(allocator);

        for (hosted_defs) |def_idx| {
            const def = module.def(def_idx);
            if (def.expr.data == .e_hosted_lambda) {
                const hosted = def.expr.data.e_hosted_lambda;
                const template_ref = templates.lookupByDef(def_idx) orelse {
                    if (builtin.mode == .Debug) {
                        std.debug.panic("checked artifact invariant violated: hosted procedure def has no checked template", .{});
                    }
                    unreachable;
                };

                try candidates.append(allocator, .{
                    .module_idx = module.moduleIndex(),
                    .def_idx = def_idx,
                    .expr_idx = def.expr.idx,
                    .external_symbol_name = try names.internExternalSymbolIdent(module.identStoreConst(), hosted.symbol_name),
                    .proc = .{
                        .artifact = template_ref.artifact,
                        .proc_base = template_ref.proc_base,
                    },
                    .template = template_ref,
                    .sort_key = try hostedProcSortKey(allocator, module, hosted.symbol_name),
                });
            }
        }

        const SortContext = struct {
            pub fn lessThan(_: void, a: Candidate, b: Candidate) bool {
                return switch (std.mem.order(u8, a.sort_key, b.sort_key)) {
                    .lt => true,
                    .gt => false,
                    .eq => @intFromEnum(a.def_idx) < @intFromEnum(b.def_idx),
                };
            }
        };
        std.mem.sort(Candidate, candidates.items, {}, SortContext.lessThan);

        for (candidates.items, 0..) |candidate, index| {
            const order_key_start: u32 = @intCast(order_key_bytes.items.len);
            try order_key_bytes.appendSlice(allocator, candidate.sort_key);
            try procs.append(allocator, .{
                .module_idx = candidate.module_idx,
                .def_idx = candidate.def_idx,
                .expr_idx = candidate.expr_idx,
                .external_symbol_name = candidate.external_symbol_name,
                .deterministic_index = @intCast(index),
                .order_key_start = order_key_start,
                .order_key_len = @intCast(candidate.sort_key.len),
                .proc = candidate.proc,
                .template = candidate.template,
            });
        }

        return .{
            .procs = try procs.toOwnedSlice(allocator),
            .order_key_bytes = try order_key_bytes.toOwnedSlice(allocator),
        };
    }

    fn hostedProcSortKey(
        allocator: Allocator,
        module: TypedCIR.Module,
        symbol_name: Ident.Idx,
    ) Allocator.Error![]const u8 {
        const module_env = module.moduleEnvConst();
        var module_name = module_env.module_name;
        if (Ident.textEndsWith(module_name, ".roc")) {
            module_name = module_name[0 .. module_name.len - 4];
        }

        const local_name = module.getIdent(symbol_name);
        const qualified_name = try std.fmt.allocPrint(allocator, "{s}.{s}", .{ module_name, local_name });
        if (!Ident.textEndsWith(qualified_name, "!")) return qualified_name;

        const stripped = try allocator.dupe(u8, qualified_name[0 .. qualified_name.len - 1]);
        allocator.free(qualified_name);
        return stripped;
    }

    /// Build-time-only teardown (see `StaticDispatchPlanTable.deinit`): a frozen table's
    /// slices alias the artifact buffer and are freed wholesale by the artifact, never here.
    pub fn deinit(self: *HostedProcTable, allocator: Allocator) void {
        allocator.free(self.procs);
        allocator.free(@constCast(self.order_key_bytes));
        self.* = .{};
    }
};

/// One platform-header hosted binding. Slice order is the host dispatch index.
pub const HostedBinding = struct {
    target_checked_module: CheckedModuleArtifactKey,
    target_def: CIR.Def.Idx,
    external_symbol_name: canonical.ExternalSymbolNameId,
};

/// Exact platform-header bindings from external symbols to checked hosted defs.
pub const HostedBindingTable = struct {
    bindings: []HostedBinding = &.{},

    pub const Serialized = extern struct {
        bindings: SerializedSlice(HostedBinding) = .{},
        const Serde = artifact_serialize.SliceStoreSerde(HostedBindingTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    pub fn fromModule(
        allocator: Allocator,
        module: TypedCIR.Module,
        names: *canonical.CanonicalNameStore,
        imports: []const PublishImportArtifact,
    ) Allocator.Error!HostedBindingTable {
        if (module.moduleEnvConst().module_kind != .platform) return .{};

        var bindings = std.ArrayList(HostedBinding).empty;
        errdefer bindings.deinit(allocator);

        const Target = struct {
            module_idx: u32,
            def: CIR.Def.Idx,
        };
        var hosted_targets = std.AutoHashMap(Target, usize).init(allocator);
        defer hosted_targets.deinit();
        var hosted_target_count: usize = 0;
        for (imports) |imported| hosted_target_count += imported.view.hosted_procs.procs.len;
        try hosted_targets.ensureTotalCapacity(@intCast(hosted_target_count));
        for (imports, 0..) |imported, import_index| {
            for (imported.view.hosted_procs.procs) |proc| {
                hosted_targets.putAssumeCapacityNoClobber(.{
                    .module_idx = imported.module_idx,
                    .def = proc.def_idx,
                }, import_index);
            }
        }

        for (module.moduleEnvConst().hosted_entries.items.items) |entry| {
            if (entry.target_status != .resolved) continue;
            const import_idx = entry.target_import orelse continue;
            const target_def = entry.target_def orelse continue;
            const resolved_module_idx = module.resolvedImportModule(import_idx) orelse continue;
            const import_index = hosted_targets.get(.{
                .module_idx = resolved_module_idx,
                .def = target_def,
            }) orelse continue;
            const imported = imports[import_index];

            try bindings.append(allocator, .{
                .target_checked_module = imported.key,
                .target_def = target_def,
                .external_symbol_name = try names.internExternalSymbolName(module.moduleEnvConst().getString(entry.symbol)),
            });
        }

        return .{ .bindings = try bindings.toOwnedSlice(allocator) };
    }

    pub fn deinit(self: *HostedBindingTable, allocator: Allocator) void {
        allocator.free(self.bindings);
        self.* = .{};
    }
};

/// Public `PlatformAppRelationKey` declaration.
pub const PlatformAppRelationKey = struct {
    bytes: [32]u8 = [_]u8{0} ** 32,

    pub fn compute(
        app_artifact: CheckedModuleArtifactKey,
        requirement_context: PlatformRequirementContextKey,
    ) PlatformAppRelationKey {
        var hasher = std.crypto.hash.sha2.Sha256.init(.{});
        hasher.update(&app_artifact.bytes);
        hasher.update(&requirement_context.bytes);
        return .{ .bytes = hasher.finalResult() };
    }
};

/// Public `PlatformRequiredDeclarationId` declaration.
pub const PlatformRequiredDeclarationId = enum(u32) { _ };
/// Public `PlatformRequiredBindingId` declaration.
pub const PlatformRequiredBindingId = enum(u32) { _ };
/// Public `PlatformRequirementRelationId` declaration.
pub const PlatformRequirementRelationId = enum(u32) { _ };

/// Public `PlatformRequiredValueKind` declaration.
pub const PlatformRequiredValueKind = enum {
    const_value,
    procedure_value,
};

/// Public `PlatformRequiredDeclaration` declaration.
pub const PlatformRequiredDeclaration = struct {
    id: PlatformRequiredDeclarationId,
    module_idx: u32,
    requires_idx: u32,
    platform_name: canonical.ExportNameId,
    declared_source_ty: canonical.CanonicalTypeSchemeKey,
    type_anno: CIR.TypeAnno.Idx,
    for_clause_aliases_hash: [32]u8,
};

/// Public `PlatformRequiredDeclarationTable` declaration.
pub const PlatformRequiredDeclarationTable = struct {
    declarations: []PlatformRequiredDeclaration = &.{},

    pub const Serialized = extern struct {
        declarations: SerializedSlice(PlatformRequiredDeclaration) = .{},
        const Serde = artifact_serialize.SliceStoreSerde(PlatformRequiredDeclarationTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    pub fn fromModule(
        allocator: Allocator,
        module: TypedCIR.Module,
        names: *canonical.CanonicalNameStore,
    ) Allocator.Error!PlatformRequiredDeclarationTable {
        return fromEnv(allocator, module.moduleEnvConst(), names, module.moduleIndex());
    }

    /// Build the required declaration table from a platform module's checked
    /// `ModuleEnv`. `fromModule` delegates here so the artifact-derived and
    /// env-derived declaration hashes share a single implementation.
    pub fn fromEnv(
        allocator: Allocator,
        module_env: *const ModuleEnv,
        names: *canonical.CanonicalNameStore,
        module_idx: u32,
    ) Allocator.Error!PlatformRequiredDeclarationTable {
        const required_types = module_env.requires_types.items.items;
        const declarations = try allocator.alloc(PlatformRequiredDeclaration, required_types.len);
        errdefer allocator.free(declarations);

        for (required_types, 0..) |required_type, i| {
            declarations[i] = .{
                .id = @enumFromInt(@as(u32, @intCast(i))),
                .module_idx = module_idx,
                .requires_idx = @intCast(i),
                .platform_name = try names.internExportIdent(module_env.getIdentStoreConst(), required_type.ident),
                .declared_source_ty = try canonical_type_keys.schemeFromVar(
                    allocator,
                    &module_env.types,
                    module_env,
                    ModuleEnv.varFrom(required_type.type_anno),
                ),
                .type_anno = required_type.type_anno,
                .for_clause_aliases_hash = hashRequiredTypeForClauseAliases(module_env, required_type),
            };
        }

        return .{ .declarations = declarations };
    }

    pub fn lookupByRequiredIndex(
        self: *const PlatformRequiredDeclarationTable,
        requires_idx: u32,
    ) ?PlatformRequiredDeclaration {
        for (self.declarations) |declaration| {
            if (declaration.requires_idx == requires_idx) return declaration;
        }
        return null;
    }

    pub fn lookupByDeclarationId(
        self: *const PlatformRequiredDeclarationTable,
        declaration_id: PlatformRequiredDeclarationId,
    ) ?PlatformRequiredDeclaration {
        const raw = @intFromEnum(declaration_id);
        if (raw >= self.declarations.len) return null;
        return self.declarations[raw];
    }

    pub fn identityHash(
        self: *const PlatformRequiredDeclarationTable,
        names: *const canonical.CanonicalNameStore,
    ) [32]u8 {
        var hasher = std.crypto.hash.sha2.Sha256.init(.{});
        hashByteSlice(&hasher, "platform_required_declarations");
        hashU32(&hasher, @intCast(self.declarations.len));
        for (self.declarations) |declaration| {
            hashU32(&hasher, declaration.requires_idx);
            hashByteSlice(&hasher, names.exportNameText(declaration.platform_name));
            hasher.update(&declaration.declared_source_ty.bytes);
            hasher.update(&declaration.for_clause_aliases_hash);
        }
        return hasher.finalResult();
    }

    pub fn deinit(self: *PlatformRequiredDeclarationTable, allocator: Allocator) void {
        allocator.free(self.declarations);
        self.* = .{};
    }
};

fn hashRequiredTypeForClauseAliases(
    module_env: *const ModuleEnv,
    required_type: ModuleEnv.RequiredType,
) [32]u8 {
    var hasher = std.crypto.hash.sha2.Sha256.init(.{});
    hashByteSlice(&hasher, "platform_required_for_clause_aliases");
    const aliases = module_env.for_clause_aliases.sliceRange(required_type.type_aliases);
    hashU32(&hasher, @intCast(aliases.len));
    for (aliases) |alias| {
        hashByteSlice(&hasher, module_env.getIdent(alias.alias_name));
        hashByteSlice(&hasher, module_env.getIdent(alias.rigid_name));
    }
    return hasher.finalResult();
}

/// Public `PlatformRequiredProcedureUse` declaration.
pub const PlatformRequiredProcedureUse = struct {
    procedure: ProcedureUseTemplate,
    root_evidence: ?CheckedEvidenceSpan = null,
    relation_template_closure: ImportedTemplateClosureView = .{},
};

/// Public `PlatformRequiredConstUse` declaration.
pub const PlatformRequiredConstUse = struct {
    const_use: ConstUseTemplate,
    relation_template_closure: ImportedTemplateClosureView = .{},
};

/// Public `PlatformRequiredValueUse` declaration.
pub const PlatformRequiredValueUse = union(enum) {
    const_value: PlatformRequiredConstUse,
    procedure_value: PlatformRequiredProcedureUse,

    pub fn tag(self: PlatformRequiredValueUse) PlatformRequiredValueUseKind {
        return switch (self) {
            .const_value => .const_value,
            .procedure_value => .procedure_value,
        };
    }
};

/// Discriminant of `PlatformRequiredValueUse` / `StoredPlatformRequiredValueUse`.
pub const PlatformRequiredValueUseKind = enum { const_value, procedure_value };

/// Relocation-invariant (POD) mirror of `PlatformRequiredProcedureUse`.
pub const StoredPlatformRequiredProcedureUse = struct {
    procedure: ProcedureUseTemplate,
    root_evidence: ?CheckedEvidenceSpan = null,
    relation_template_closure: StoredImportedTemplateClosure = .{},
};

/// Relocation-invariant (POD) mirror of `PlatformRequiredConstUse`.
pub const StoredPlatformRequiredConstUse = struct {
    const_use: ConstUseTemplate,
    relation_template_closure: StoredImportedTemplateClosure = .{},
};

/// POD mirror of `PlatformRequiredValueUse`: closures live as ranges into the
/// owning `PlatformRequiredBindingTable`'s `ClosurePool`. Stored by value in each
/// `PlatformRequiredBinding` row. A real tagged union (not a discriminant + two fixed
/// fields), so only the active variant's bytes exist—there is no inactive field to
/// leave `undefined`, and the serializer's union-padding zeroing keeps the blob
/// byte-deterministic.
pub const StoredPlatformRequiredValueUse = union(PlatformRequiredValueUseKind) {
    const_value: StoredPlatformRequiredConstUse,
    procedure_value: StoredPlatformRequiredProcedureUse,
};

/// Public `PlatformRequirementRelationInput` declaration.
pub const PlatformRequirementRelationInput = struct {
    id: PlatformRequirementRelationId,
    declaration: PlatformRequiredDeclarationId,
    requires_idx: u32,
    app_value: TopLevelValueRef,
    requested_source_ty: canonical.CanonicalTypeKey,
    value_kind: PlatformRequiredValueKind,
    /// The app-store checked root the checker solved this requirement's type to.
    solved_root_app: CheckedTypeId,
    /// Root-call dispatch evidence in the app artifact's evidence table.
    root_evidence: artifact_serialize.Span = .{},
    /// Range into the owning `PlatformAppRelation.identity_solutions_app`: the
    /// app-store solved roots of this requirement's identity variables, in
    /// canonical identity-slot order.
    identity_start: u32,
    identity_len: u32,
};

/// Public `PlatformRequiredBindingInput` declaration.
pub const PlatformRequiredBindingInput = struct {
    declaration: PlatformRequiredDeclarationId,
    requires_idx: u32,
    app_value: TopLevelValueRef,
    requested_source_ty: canonical.CanonicalTypeKey,
    checked_relation: PlatformRequirementRelationId,
    value_use: PlatformRequiredValueUse,
};

/// Public `PlatformAppRelation` declaration.
pub const PlatformAppRelation = struct {
    key: PlatformAppRelationKey,
    requirement_context: PlatformRequirementContextKey,
    platform_module_idx: u32,
    app_artifact: CheckedModuleArtifactKey,
    relations: []const PlatformRequirementRelationInput,
    bindings: []const PlatformRequiredBindingInput,
    /// Requires-clause indices whose app-side requirement check failed. These
    /// are explicit checked-error facts: platform required lookups at these
    /// indices lower to a runtime crash, while successful sibling bindings
    /// remain fully linked.
    checked_error_requires: []const u32,
    /// The app-store checked roots the checker solved requirement identity
    /// variables to, flattened in canonical identity-slot order and indexed by
    /// each relation's `identity_start`/`identity_len` range.
    identity_solutions_app: []const CheckedTypeId,

    pub fn deinit(self: *PlatformAppRelation, allocator: Allocator) void {
        for (self.bindings) |*binding| {
            var value_use = binding.value_use;
            deinitPlatformRequiredValueUse(allocator, &value_use);
        }
        allocator.free(self.relations);
        allocator.free(self.bindings);
        allocator.free(self.checked_error_requires);
        allocator.free(self.identity_solutions_app);
        self.* = .{
            .key = .{},
            .requirement_context = .{},
            .platform_module_idx = 0,
            .app_artifact = .{},
            .relations = &.{},
            .bindings = &.{},
            .checked_error_requires = &.{},
            .identity_solutions_app = &.{},
        };
    }
};

const PlatformRelationTypeSubstitutions = struct {
    formals: []CheckedTypeId = &.{},
    actuals: []CheckedTypeId = &.{},

    fn fromRelation(
        allocator: Allocator,
        module: TypedCIR.Module,
        module_identity: ModuleIdentity,
        names: *canonical.CanonicalNameStore,
        checked_types: *CheckedTypePublication,
        declarations: *const PlatformRequiredDeclarationTable,
        relation_artifacts: []const ImportedModuleView,
        relation: ?PlatformAppRelation,
    ) Allocator.Error!PlatformRelationTypeSubstitutions {
        const active_relation = relation orelse return .{};
        validatePlatformAppRelationForModule(
            module,
            module_identity,
            names,
            declarations,
            active_relation,
        );

        const app_view = relationArtifactByKey(relation_artifacts, active_relation.app_artifact) orelse {
            checkedArtifactInvariant("platform/app relation substitution missing app relation artifact", .{});
        };

        var formals = std.ArrayList(CheckedTypeId).empty;
        errdefer formals.deinit(allocator);
        var actuals = std.ArrayList(CheckedTypeId).empty;
        errdefer actuals.deinit(allocator);

        for (active_relation.relations) |input| {
            const declaration = declarations.lookupByDeclarationId(input.declaration) orelse {
                checkedArtifactInvariant("platform/app relation substitution referenced unknown requirement declaration", .{});
            };

            // Each requirement identity variable's platform-owned checked
            // payload, in the same canonical slot order the checker recorded its
            // solved app types under. Slot i's formal pairs with slot i's actual.
            const platform_root = platformRequiredPayloadForDeclaration(module, checked_types, declaration);
            const identity_formals = try collectCheckedIdentityRootsInKeyOrder(allocator, &checked_types.store, names, platform_root);
            defer allocator.free(identity_formals);
            if (identity_formals.len != input.identity_len) {
                checkedArtifactInvariant("platform/app relation substitution identity slot count disagrees with the recorded solution", .{});
            }

            const app_identity_roots = active_relation.identity_solutions_app[input.identity_start .. input.identity_start + input.identity_len];

            var projector = CheckedTypeStoreImportProjector.initPreservingSourceInstance(allocator, &checked_types.store, names, app_view);
            defer projector.deinit();

            for (identity_formals, app_identity_roots) |formal, app_identity_root| {
                if (builtin.mode == .Debug) {
                    std.debug.assert(checkedTypePayloadIsIdentity(checked_types.store.payload(formal)));
                }
                const actual = try projector.project(app_identity_root);
                try recordRelationSubstitution(allocator, names, &checked_types.store, &formals, &actuals, formal, actual);
            }

            try appendForClauseAliasSubstitutions(
                allocator,
                module,
                names,
                checked_types,
                declaration,
                &formals,
                &actuals,
            );
        }

        return .{
            .formals = try formals.toOwnedSlice(allocator),
            .actuals = try actuals.toOwnedSlice(allocator),
        };
    }

    fn specializeRoot(
        self: *const PlatformRelationTypeSubstitutions,
        allocator: Allocator,
        names: *const canonical.CanonicalNameStore,
        store: *CheckedTypeStore,
        root: CheckedTypeId,
    ) Allocator.Error!CheckedTypeId {
        if (self.formals.len == 0) return root;
        var active = collections.DenseMap(CheckedTypeId, CheckedTypeId).init(allocator);
        defer active.deinit();
        return try store.cloneCheckedTypeRootSubstituting(
            allocator,
            names,
            root,
            self.formals,
            self.actuals,
            &active,
        );
    }

    fn deinit(self: *PlatformRelationTypeSubstitutions, allocator: Allocator) void {
        allocator.free(self.actuals);
        allocator.free(self.formals);
        self.* = .{};
    }
};

/// Append a `formal -> actual` substitution. Repeated equivalent bindings keep
/// the first root; conflicting bindings violate the checked relation invariant.
fn recordRelationSubstitution(
    allocator: Allocator,
    names: *const canonical.CanonicalNameStore,
    store: *const CheckedTypeStore,
    formals: *std.ArrayList(CheckedTypeId),
    actuals: *std.ArrayList(CheckedTypeId),
    formal: CheckedTypeId,
    actual: CheckedTypeId,
) Allocator.Error!void {
    if (formal == actual) return;
    try appendUniqueCheckedTypeSubstitution(formals, actuals, allocator, names, store, formal, actual);
}

/// The recorded actual paired with `formal`, or null if `formal` is unbound.
fn relationSubstitutionActual(
    formals: []const CheckedTypeId,
    actuals: []const CheckedTypeId,
    formal: CheckedTypeId,
) ?CheckedTypeId {
    for (formals, actuals) |existing, actual| {
        if (existing == formal) return actual;
    }
    return null;
}

/// Record substitutions for a requirement's for-clause type aliases: a use of a
/// for-clause alias name (e.g. `Model` in `[Model : model]`) inside a
/// provided-export root specializes to whatever its backing identity variable
/// solved to. The alias declaration root, its backing, and the alias annotation
/// root all map to the identity's recorded actual.
fn appendForClauseAliasSubstitutions(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *const canonical.CanonicalNameStore,
    checked_types: *const CheckedTypePublication,
    declaration: PlatformRequiredDeclaration,
    formals: *std.ArrayList(CheckedTypeId),
    actuals: *std.ArrayList(CheckedTypeId),
) Allocator.Error!void {
    const module_env = module.moduleEnvConst();
    if (declaration.requires_idx >= module_env.requires_types.items.items.len) {
        checkedArtifactInvariant("platform/app relation alias substitution referenced an out-of-range requirement", .{});
    }
    const required_type = module_env.requires_types.items.items[declaration.requires_idx];
    const aliases = module_env.for_clause_aliases.sliceRange(required_type.type_aliases);
    for (aliases) |alias| {
        const alias_statement = module_env.store.getStatement(alias.alias_stmt_idx);
        if (alias_statement != .s_alias_decl) {
            checkedArtifactInvariant("platform/app relation alias substitution referenced a non-alias statement", .{});
        }
        const alias_anno = alias_statement.s_alias_decl.anno;
        const alias_anno_root = checked_types.rootForSourceVar(module, ModuleEnv.varFrom(alias_anno)) orelse {
            checkedArtifactInvariant("platform/app relation alias substitution could not find alias backing checked root", .{});
        };
        const resolved = relationSubstitutionActual(formals.items, actuals.items, alias_anno_root) orelse continue;

        const alias_root = checked_types.rootForSourceVar(module, ModuleEnv.varFrom(alias.alias_stmt_idx)) orelse {
            checkedArtifactInvariant("platform/app relation alias substitution could not find alias checked root", .{});
        };
        try recordRelationSubstitution(allocator, names, &checked_types.store, formals, actuals, alias_root, resolved);
        const alias_payload = checked_types.store.payload(alias_root);
        if (alias_payload == .alias) {
            try recordRelationSubstitution(allocator, names, &checked_types.store, formals, actuals, alias_payload.alias.backing, resolved);
        }
        try recordRelationSubstitution(allocator, names, &checked_types.store, formals, actuals, alias_anno_root, resolved);
    }
}

/// Public `PlatformRequirementRelation` declaration.
pub const PlatformRequirementRelation = struct {
    id: PlatformRequirementRelationId,
    relation: PlatformAppRelationKey,
    module_idx: u32,
    declaration: PlatformRequiredDeclarationId,
    requires_idx: u32,
    app_value: TopLevelValueRef,
    requested_source_ty: canonical.CanonicalTypeKey,
    requested_source_ty_payload: CheckedTypeId,
    /// Root-call dispatch evidence in `app_value.artifact`.
    root_evidence: artifact_serialize.Span = .{},
    value_kind: PlatformRequiredValueKind,
};

/// Public `PlatformRequirementRelationTable` declaration.
pub const PlatformRequirementRelationTable = struct {
    relations: []PlatformRequirementRelation = &.{},

    pub const Serialized = extern struct {
        relations: SerializedSlice(PlatformRequirementRelation) = .{},
        const Serde = artifact_serialize.SliceStoreSerde(PlatformRequirementRelationTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    pub fn fromRelation(
        allocator: Allocator,
        module: TypedCIR.Module,
        module_identity: ModuleIdentity,
        names: *canonical.CanonicalNameStore,
        checked_types: *CheckedTypePublication,
        declarations: *const PlatformRequiredDeclarationTable,
        relation_artifacts: []const ImportedModuleView,
        relation: ?PlatformAppRelation,
    ) Allocator.Error!PlatformRequirementRelationTable {
        const active_relation = relation orelse return .{};
        validatePlatformAppRelationForModule(
            module,
            module_identity,
            names,
            declarations,
            active_relation,
        );
        if (active_relation.relations.len != active_relation.bindings.len) {
            if (builtin.mode == .Debug) {
                std.debug.panic(
                    "checked artifact invariant violated: platform/app relation has {d} checked relation rows for {d} bindings",
                    .{ active_relation.relations.len, active_relation.bindings.len },
                );
            }
            unreachable;
        }

        var seen_declarations: []bool = &.{};
        if (builtin.mode == .Debug) {
            seen_declarations = try allocator.alloc(bool, declarations.declarations.len);
            @memset(seen_declarations, false);
        }
        defer {
            if (builtin.mode == .Debug) allocator.free(seen_declarations);
        }

        const app_view = relationArtifactByKey(relation_artifacts, active_relation.app_artifact) orelse {
            checkedArtifactInvariant("platform/app relation missing app relation artifact", .{});
        };

        const rows = try allocator.alloc(PlatformRequirementRelation, active_relation.relations.len);
        errdefer allocator.free(rows);

        for (active_relation.relations, 0..) |input, i| {
            const declaration = declarations.lookupByDeclarationId(input.declaration) orelse {
                if (builtin.mode == .Debug) {
                    std.debug.panic(
                        "checked artifact invariant violated: platform/app checked relation {d} references unknown requirement declaration",
                        .{i},
                    );
                }
                unreachable;
            };
            const declaration_index: usize = @intCast(@intFromEnum(input.declaration));
            if (builtin.mode == .Debug) {
                if (seen_declarations[declaration_index]) {
                    std.debug.panic(
                        "checked artifact invariant violated: platform/app checked relation binds declaration {d} more than once",
                        .{declaration_index},
                    );
                }
                seen_declarations[declaration_index] = true;
            }
            if (input.requires_idx != declaration.requires_idx) {
                if (builtin.mode == .Debug) {
                    std.debug.panic(
                        "checked artifact invariant violated: platform/app checked relation {d} maps declaration {d} to required index {d}, expected {d}",
                        .{ i, declaration_index, input.requires_idx, declaration.requires_idx },
                    );
                }
                unreachable;
            }
            if (!std.meta.eql(input.app_value.artifact.bytes, active_relation.app_artifact.bytes)) {
                if (builtin.mode == .Debug) {
                    std.debug.panic(
                        "checked artifact invariant violated: platform/app checked relation {d} points at a value outside the app artifact",
                        .{i},
                    );
                }
                unreachable;
            }
            // The requirement type as the checker solved it, recorded on the
            // app's artifact and projected into this publication's store.
            var projector = CheckedTypeStoreImportProjector.initPreservingSourceInstance(allocator, &checked_types.store, names, app_view);
            defer projector.deinit();
            const payload = try projector.project(input.solved_root_app);
            const payload_key = checked_types.store.roots.items[@intFromEnum(payload)].key;

            rows[i] = .{
                .id = input.id,
                .relation = active_relation.key,
                .module_idx = module.moduleIndex(),
                .declaration = input.declaration,
                .requires_idx = input.requires_idx,
                .app_value = input.app_value,
                .requested_source_ty = payload_key,
                .requested_source_ty_payload = payload,
                .root_evidence = input.root_evidence,
                .value_kind = input.value_kind,
            };
        }

        return .{ .relations = rows };
    }

    pub fn deinit(self: *PlatformRequirementRelationTable, allocator: Allocator) void {
        allocator.free(self.relations);
        self.* = .{};
    }

    pub fn lookupByRelationId(self: *const PlatformRequirementRelationTable, relation_id: PlatformRequirementRelationId) ?PlatformRequirementRelation {
        const raw = @intFromEnum(relation_id);
        if (raw >= self.relations.len) return null;
        return self.relations[raw];
    }
};

/// Public `PlatformRequirementSolution` declaration.
///
/// One row of the check-time platform/app correspondence carried on the APP's
/// checked artifact: the exported app value a platform requirement resolved to
/// during checking, the requirement type as solved in the app's env, and the
/// solved types of the requirement's identity variables.
pub const PlatformRequirementSolution = struct {
    /// requires-clause index; equals the platform-side
    /// `PlatformRequiredDeclarationId` by construction (both are assigned
    /// positionally over the platform's `requires_types`).
    requires_idx: u32,
    def: CIR.Def.Idx,
    pattern: CheckedPatternId,
    /// The requirement type as solved in the app env, in the app's store.
    solved_root: CheckedTypeId,
    /// Root-call dispatch evidence in this app artifact's evidence table.
    root_evidence: artifact_serialize.Span = .{},
    value_kind: PlatformRequiredValueKind,
    /// Range into the table's `identity_solutions`; the offset within the
    /// range is the canonical identity slot of the platform requirement
    /// payload (the first-encounter order the canonical key digest assigns).
    identity_start: u32,
    identity_len: u32,
};

/// Public `PlatformRequirementSolutionTable` declaration.
///
/// The relation is recorded here, where it is proven: when an app checks
/// against a platform's requirement surface, each successful unification's
/// output travels as these rows. Finalization builds the platform/app
/// relation by reading them—it never re-resolves app exports by name and
/// never re-derives identity substitutions structurally. Empty for every
/// module that is not an app root checked against a platform.
pub const PlatformRequirementSolutionTable = struct {
    solutions: []PlatformRequirementSolution = &.{},
    /// Solved app types for requirement identity variables, slot-ordered per
    /// solution row (`identity_start`/`identity_len` ranges).
    identity_solutions: []CheckedTypeId = &.{},

    pub const Serialized = extern struct {
        solutions: SerializedSlice(PlatformRequirementSolution) = .{},
        identity_solutions: SerializedSlice(CheckedTypeId) = .{},
        const Serde = artifact_serialize.SliceStoreSerde(PlatformRequirementSolutionTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    pub fn lookupByRequiredIndex(
        self: *const PlatformRequirementSolutionTable,
        requires_idx: u32,
    ) ?PlatformRequirementSolution {
        for (self.solutions) |solution| {
            if (solution.requires_idx == requires_idx) return solution;
        }
        return null;
    }

    pub fn identitySlice(
        self: *const PlatformRequirementSolutionTable,
        solution: PlatformRequirementSolution,
    ) []const CheckedTypeId {
        return self.identity_solutions[solution.identity_start .. solution.identity_start + solution.identity_len];
    }

    pub fn deinit(self: *PlatformRequirementSolutionTable, allocator: Allocator) void {
        allocator.free(self.identity_solutions);
        allocator.free(self.solutions);
        self.* = .{};
    }
};

/// Materialize the checker-recorded successful requirement solutions into
/// checked type roots in the app's store. A row whose types contain an error
/// is omitted here; platform/app relation construction converts that exact
/// absent requires index into an explicit checked-error requirement outcome.
fn platformRequirementSolutionTableFromInputs(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    current_owner: ModuleId,
    imports: []const PublishImportArtifact,
    available: []const ImportedModuleView,
    checked_types: *CheckedTypeStore,
    top_level_values: *const TopLevelValueTable,
    exported_procedure_bindings: *const ExportedProcedureBindingTable,
    exported_const_templates: *const ExportedConstTemplateTable,
    inputs: []const requirement_solution.SolutionInput,
    root_evidence: []const artifact_serialize.Span,
) Allocator.Error!PlatformRequirementSolutionTable {
    if (inputs.len != root_evidence.len) {
        checkedArtifactInvariant("platform requirement solutions and root evidence had different lengths", .{});
    }
    if (inputs.len == 0) return .{};

    const import_views = CheckedImportViews{
        .current_owner = current_owner,
        .direct = imports,
        .available = available,
    };
    var active = CheckedSourceTypeRoots.init(allocator);
    defer active.deinit();

    var solutions = std.ArrayList(PlatformRequirementSolution).empty;
    errdefer solutions.deinit(allocator);
    var identity_solutions = std.ArrayList(CheckedTypeId).empty;
    errdefer identity_solutions.deinit(allocator);

    for (inputs, root_evidence) |input, evidence| {
        if (try solutionVarsReachErr(allocator, module, input)) continue;

        const top_level = top_level_values.lookupByDef(input.def) orelse {
            checkedArtifactInvariant("platform requirement solution references a def with no published top-level value", .{});
        };
        const value_kind: PlatformRequiredValueKind = if (input.is_function) .procedure_value else .const_value;
        const kind_matches = switch (top_level.value) {
            .procedure_binding => value_kind == .procedure_value,
            .const_ref => value_kind == .const_value,
        };
        if (!kind_matches) {
            checkedArtifactInvariant("platform requirement solution value kind disagrees with the published app value", .{});
        }
        if (builtin.mode == .Debug) {
            const is_exported = switch (top_level.value) {
                .procedure_binding => blk: {
                    for (exported_procedure_bindings.bindings) |binding| {
                        if (binding.binding.def == top_level.def and binding.binding.pattern == top_level.pattern) break :blk true;
                    }
                    break :blk false;
                },
                .const_ref => blk: {
                    for (exported_const_templates.templates) |template| {
                        if (template.def == top_level.def and template.pattern == top_level.pattern) break :blk true;
                    }
                    break :blk false;
                },
            };
            if (!is_exported) {
                std.debug.panic("checked artifact invariant violated: platform requirement solution references an unexported app value", .{});
            }
        }

        const identity_start: u32 = @intCast(identity_solutions.items.len);
        for (input.identity_vars) |identity_var| {
            const identity_root = try appendCheckedTypeRoot(allocator, module, names, import_views, checked_types, &active, identity_var);
            try identity_solutions.append(allocator, identity_root);
        }
        const solved_root = try appendCheckedTypeRoot(allocator, module, names, import_views, checked_types, &active, input.solved_var);
        try solutions.append(allocator, .{
            .requires_idx = input.requires_idx,
            .def = input.def,
            .pattern = top_level.pattern,
            .solved_root = solved_root,
            .root_evidence = evidence,
            .value_kind = value_kind,
            .identity_start = identity_start,
            .identity_len = @intCast(input.identity_vars.len),
        });
    }

    return .{
        .solutions = try solutions.toOwnedSlice(allocator),
        .identity_solutions = try identity_solutions.toOwnedSlice(allocator),
    };
}

fn solutionVarsReachErr(
    allocator: Allocator,
    module: TypedCIR.Module,
    input: requirement_solution.SolutionInput,
) Allocator.Error!bool {
    if (try canonical_type_keys.containsError(
        allocator,
        module.typeStoreConst(),
        module.moduleEnvConst(),
        input.solved_var,
    )) return true;
    for (input.identity_vars) |identity_var| {
        if (try canonical_type_keys.containsError(
            allocator,
            module.typeStoreConst(),
            module.moduleEnvConst(),
            identity_var,
        )) return true;
    }
    return false;
}

/// Public `PlatformRequiredBinding` declaration.
pub const PlatformRequiredBinding = struct {
    id: PlatformRequiredBindingId,
    relation: PlatformAppRelationKey,
    module_idx: u32,
    declaration: PlatformRequiredDeclarationId,
    requires_idx: u32,
    app_value: TopLevelValueRef,
    requested_source_ty: canonical.CanonicalTypeKey,
    checked_relation: PlatformRequirementRelationId,
    value_use: StoredPlatformRequiredValueUse,
};

/// Public `PlatformRequiredBindingTable` declaration.
pub const PlatformRequiredBindingTable = struct {
    bindings: []PlatformRequiredBinding = &.{},
    checked_error_requires: []u32 = &.{},
    closure_pool: ClosurePool = ClosurePool.empty,

    pub fn fromRelation(
        allocator: Allocator,
        module: TypedCIR.Module,
        module_identity: ModuleIdentity,
        names: *const canonical.CanonicalNameStore,
        declarations: *const PlatformRequiredDeclarationTable,
        relations: *const PlatformRequirementRelationTable,
        relation: ?PlatformAppRelation,
    ) Allocator.Error!PlatformRequiredBindingTable {
        const active_relation = relation orelse return .{};
        validatePlatformAppRelationForModule(
            module,
            module_identity,
            names,
            declarations,
            active_relation,
        );
        if (active_relation.bindings.len + active_relation.checked_error_requires.len != declarations.declarations.len) {
            if (builtin.mode == .Debug) {
                std.debug.panic(
                    "checked artifact invariant violated: platform/app relation has {d} bindings and {d} checked errors for {d} platform requirements",
                    .{ active_relation.bindings.len, active_relation.checked_error_requires.len, declarations.declarations.len },
                );
            }
            unreachable;
        }
        var seen_declarations: []bool = &.{};
        if (builtin.mode == .Debug) {
            seen_declarations = try allocator.alloc(bool, declarations.declarations.len);
            @memset(seen_declarations, false);
        }
        defer {
            if (builtin.mode == .Debug) allocator.free(seen_declarations);
        }

        const bindings = try allocator.alloc(PlatformRequiredBinding, active_relation.bindings.len);
        const checked_error_requires = try allocator.dupe(u32, active_relation.checked_error_requires);
        var closure_pool = ClosurePool.empty;
        errdefer {
            allocator.free(bindings);
            allocator.free(checked_error_requires);
            closure_pool.deinit(allocator);
        }

        if (builtin.mode == .Debug) {
            for (checked_error_requires) |requires_idx| {
                const declaration = declarations.lookupByRequiredIndex(requires_idx) orelse {
                    std.debug.panic(
                        "checked artifact invariant violated: platform checked-error requirement {d} has no declaration",
                        .{requires_idx},
                    );
                };
                const declaration_index: usize = @intCast(@intFromEnum(declaration.id));
                if (seen_declarations[declaration_index]) {
                    std.debug.panic(
                        "checked artifact invariant violated: platform requirement declaration {d} has multiple outcomes",
                        .{declaration_index},
                    );
                }
                seen_declarations[declaration_index] = true;
            }
        }

        for (active_relation.bindings, 0..) |binding, i| {
            const declaration = declarations.lookupByDeclarationId(binding.declaration) orelse {
                if (builtin.mode == .Debug) {
                    std.debug.panic(
                        "checked artifact invariant violated: platform/app binding {d} references unknown requirement declaration",
                        .{i},
                    );
                }
                unreachable;
            };
            const declaration_index: usize = @intCast(@intFromEnum(binding.declaration));
            if (builtin.mode == .Debug) {
                if (seen_declarations[declaration_index]) {
                    std.debug.panic(
                        "checked artifact invariant violated: platform/app relation binds platform requirement declaration {d} more than once",
                        .{declaration_index},
                    );
                }
                seen_declarations[declaration_index] = true;
            }
            if (declaration.requires_idx != binding.requires_idx) {
                if (builtin.mode == .Debug) {
                    std.debug.panic(
                        "checked artifact invariant violated: platform/app binding {d} maps declaration {d} to required index {d}, expected {d}",
                        .{ i, declaration_index, binding.requires_idx, declaration.requires_idx },
                    );
                }
                unreachable;
            }
            if (!std.meta.eql(binding.app_value.artifact.bytes, active_relation.app_artifact.bytes)) {
                if (builtin.mode == .Debug) {
                    std.debug.panic(
                        "checked artifact invariant violated: platform/app binding {d} points at a value outside the app artifact",
                        .{i},
                    );
                }
                unreachable;
            }
            const checked_relation = relations.lookupByRelationId(binding.checked_relation) orelse {
                if (builtin.mode == .Debug) {
                    std.debug.panic(
                        "checked artifact invariant violated: platform/app binding {d} references missing checked relation",
                        .{i},
                    );
                }
                unreachable;
            };
            validatePlatformBindingRelation(binding.declaration, binding.requires_idx, binding.app_value, binding.value_use.tag(), checked_relation, i);
            var value_use = try clonePlatformRequiredValueUseWithRelation(allocator, binding.value_use, checked_relation);
            errdefer deinitPlatformRequiredValueUse(allocator, &value_use);
            const stored_value_use = try commitPlatformRequiredValueUse(&closure_pool, allocator, value_use);
            value_use = undefined;
            bindings[i] = .{
                .id = @enumFromInt(@as(u32, @intCast(i))),
                .relation = active_relation.key,
                .module_idx = module.moduleIndex(),
                .declaration = binding.declaration,
                .requires_idx = binding.requires_idx,
                .app_value = binding.app_value,
                .requested_source_ty = checked_relation.requested_source_ty,
                .checked_relation = binding.checked_relation,
                .value_use = stored_value_use,
            };
        }

        return .{
            .bindings = bindings,
            .checked_error_requires = checked_error_requires,
            .closure_pool = closure_pool,
        };
    }

    pub fn deinit(self: *PlatformRequiredBindingTable, allocator: Allocator) void {
        if (!self.closure_pool.serialized) {
            allocator.free(self.bindings);
            allocator.free(self.checked_error_requires);
        }
        self.closure_pool.deinit(allocator);
        self.* = .{};
    }

    /// Materialize a binding's relation template closure from this table's pool.
    pub fn relationClosure(self: *const PlatformRequiredBindingTable, binding: PlatformRequiredBinding) ImportedTemplateClosureView {
        return self.closure_pool.reconstruct(switch (binding.value_use) {
            .const_value => |const_use| const_use.relation_template_closure,
            .procedure_value => |procedure_use| procedure_use.relation_template_closure,
        });
    }

    /// Relocatable serialized form: the POD row slice plus the closure pool.
    pub const Serialized = extern struct {
        bindings: SerializedSlice(PlatformRequiredBinding) = .{},
        checked_error_requires: SerializedSlice(u32) = .{},
        closure_pool: ClosurePool.Serialized = .{},

        comptime {
            std.debug.assert(artifact_serialize.relocatablePointerCount(Serialized) == 15);
        }

        const Serde = artifact_serialize.SliceStoreSerde(PlatformRequiredBindingTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    pub fn lookupByRequiredIndex(self: *const PlatformRequiredBindingTable, requires_idx: u32) ?PlatformRequiredBinding {
        for (self.bindings) |binding| {
            if (binding.requires_idx == requires_idx) return binding;
        }
        return null;
    }

    pub fn isCheckedError(self: *const PlatformRequiredBindingTable, requires_idx: u32) bool {
        for (self.checked_error_requires) |checked_error_requires_idx| {
            if (checked_error_requires_idx == requires_idx) return true;
        }
        return false;
    }

    pub fn lookupByBindingId(self: *const PlatformRequiredBindingTable, binding_id: u32) ?PlatformRequiredBinding {
        if (binding_id >= self.bindings.len) return null;
        return self.bindings[binding_id];
    }
};

fn validatePlatformAppRelationForModule(
    module: TypedCIR.Module,
    module_identity: ModuleIdentity,
    names: *const canonical.CanonicalNameStore,
    declarations: *const PlatformRequiredDeclarationTable,
    active_relation: PlatformAppRelation,
) void {
    if (active_relation.platform_module_idx != module.moduleIndex()) {
        if (builtin.mode == .Debug) {
            std.debug.panic(
                "checked artifact invariant violated: platform/app relation belongs to module {d}, not platform module {d}",
                .{ active_relation.platform_module_idx, module.moduleIndex() },
            );
        }
        unreachable;
    }
    const expected_requirement_context = PlatformRequirementContextKey.compute(
        module_identity,
        declarations.identityHash(names),
    );
    if (!std.meta.eql(active_relation.requirement_context.bytes, expected_requirement_context.bytes)) {
        if (builtin.mode == .Debug) {
            std.debug.panic(
                "checked artifact invariant violated: platform/app relation requirement context does not match the current platform requirement declarations",
                .{},
            );
        }
        unreachable;
    }
    const expected_key = PlatformAppRelationKey.compute(
        active_relation.app_artifact,
        active_relation.requirement_context,
    );
    if (!std.meta.eql(active_relation.key.bytes, expected_key.bytes)) {
        if (builtin.mode == .Debug) {
            std.debug.panic(
                "checked artifact invariant violated: platform/app relation key does not match the current platform requirement declarations",
                .{},
            );
        }
        unreachable;
    }
}

fn platformRequiredPayloadForDeclaration(
    module: TypedCIR.Module,
    checked_types: *const CheckedTypePublication,
    declaration: PlatformRequiredDeclaration,
) CheckedTypeId {
    const module_env = module.moduleEnvConst();
    if (declaration.requires_idx >= module_env.requires_types.items.items.len) {
        if (builtin.mode == .Debug) {
            std.debug.panic(
                "checked artifact invariant violated: platform requirement declaration {d} has out-of-range required index {d}",
                .{ @intFromEnum(declaration.id), declaration.requires_idx },
            );
        }
        unreachable;
    }
    const required_type = module_env.requires_types.items.items[declaration.requires_idx];
    return checked_types.rootForSourceVar(module, ModuleEnv.varFrom(required_type.type_anno)) orelse {
        if (builtin.mode == .Debug) {
            std.debug.panic(
                "checked artifact invariant violated: platform requirement declaration {d} has no platform-owned checked payload",
                .{@intFromEnum(declaration.id)},
            );
        }
        unreachable;
    };
}

fn specializeResolvedStaticDispatchPlanCallables(
    allocator: Allocator,
    names: *canonical.CanonicalNameStore,
    store: *CheckedTypeStore,
    artifact_key: CheckedModuleArtifactKey,
    direct_imports: []const PublishImportArtifact,
    available_artifacts: []const ImportedModuleView,
    plans: *static_dispatch.StaticDispatchPlanTable,
) Allocator.Error!void {
    var instantiated_pairs: std.AutoHashMapUnmanaged(ResolvedDispatchCallablePair, CheckedTypeId) = .empty;
    defer instantiated_pairs.deinit(allocator);
    const evidence_closure = try allocator.alloc(DirectEvidenceClosure, plans.evidence_nodes.len);
    defer allocator.free(evidence_closure);
    @memset(evidence_closure, .unknown);

    for (plans.plans) |*plan| {
        const node_id = switch (plan.resolution) {
            .direct_pending => |node_id| node_id,
            .direct_closed, .direct_parametric => checkedArtifactInvariant("static dispatch plan was finalized more than once", .{}),
            .evidence_dependent, .structural, .checked_error, .@"unreachable" => continue,
        };
        const target = plans.evidenceNode(node_id).target;
        const target_callable = try projectResolvedDispatchTargetCallable(
            allocator,
            names,
            store,
            artifact_key,
            direct_imports,
            available_artifacts,
            target,
        );
        plan.callable_ty = try instantiateResolvedDispatchTargetCallableMemoized(
            allocator,
            names,
            store,
            target_callable,
            plan.callable_ty,
            &instantiated_pairs,
        );
        const direct: static_dispatch.DirectCall = .{ .evidence = node_id };
        plan.resolution = if (store.rootContainsIdentityVariables(plan.callable_ty) or
            !directEvidenceIsClosed(plans, node_id, evidence_closure))
            .{ .direct_parametric = direct }
        else
            .{ .direct_closed = direct };
    }
    for (plans.iterator_for_plans) |*iterator_plan| {
        inline for (.{ &iterator_plan.iter, &iterator_plan.next }) |call| {
            switch (call.resolution) {
                .direct_pending => |node_id| {
                    const target = plans.evidenceNode(node_id).target;
                    const target_callable = try projectResolvedDispatchTargetCallable(
                        allocator,
                        names,
                        store,
                        artifact_key,
                        direct_imports,
                        available_artifacts,
                        target,
                    );
                    call.callable_ty = try instantiateResolvedDispatchTargetCallableMemoized(
                        allocator,
                        names,
                        store,
                        target_callable,
                        call.callable_ty,
                        &instantiated_pairs,
                    );
                    const direct: static_dispatch.DirectCall = .{ .evidence = node_id };
                    call.resolution = if (store.rootContainsIdentityVariables(call.callable_ty) or
                        !directEvidenceIsClosed(plans, node_id, evidence_closure))
                        .{ .direct_parametric = direct }
                    else
                        .{ .direct_closed = direct };
                },
                .direct_closed, .direct_parametric => checkedArtifactInvariant("iterator dispatch plan was finalized more than once", .{}),
                .evidence_dependent, .structural, .checked_error, .@"unreachable" => {},
            }
        }
    }
}

const DirectEvidenceClosure = enum(u8) {
    unknown,
    visiting,
    closed,
    parametric,
};

/// Whether a concrete target's entire nested evidence tree is independent of
/// the enclosing specialization. This is the evidence half of
/// `direct_closed`: a structurally closed callable whose nested evidence still
/// forwards a constraint is parametric, not closed.
fn directEvidenceIsClosed(
    plans: *const static_dispatch.StaticDispatchPlanTable,
    node_id: static_dispatch.EvidenceNodeId,
    states: []DirectEvidenceClosure,
) bool {
    const raw_node = @intFromEnum(node_id);
    if (raw_node >= states.len) checkedArtifactInvariant("direct evidence closure referenced a missing node", .{});
    switch (states[raw_node]) {
        .closed => return true,
        .parametric => return false,
        .visiting => checkedArtifactInvariant("direct evidence closure contained a cycle", .{}),
        .unknown => states[raw_node] = .visiting,
    }
    const node = plans.evidenceNode(node_id);
    switch (node.target.kind) {
        .local_proc => {
            // The declaration identity is checked data, but its capture/context
            // identity belongs to the enclosing Monotype specialization.
            states[raw_node] = .parametric;
            return false;
        },
        .procedure => {},
        .structural => checkedArtifactInvariant("direct evidence closure contained a structural target", .{}),
    }
    const nested = switch (node.nested) {
        .from_callable => {
            states[raw_node] = .parametric;
            return false;
        },
        .resolved => |span| plans.evidence_refs[span.start .. span.start + span.len],
    };
    for (nested) |evidence| switch (evidence.resolution) {
        .direct => |child| if (!directEvidenceIsClosed(plans, child, states)) {
            states[raw_node] = .parametric;
            return false;
        },
        .constraint, .from_callable => {
            states[raw_node] = .parametric;
            return false;
        },
        .structural, .checked_error, .unreachable_value => {},
    };
    states[raw_node] = .closed;
    return true;
}

fn checkedDispatchPlanNeedsRelation(
    plans: *const static_dispatch.StaticDispatchPlanTable,
    plan: static_dispatch.StaticDispatchCallPlan,
) bool {
    return switch (plan.resolution) {
        .direct_closed, .direct_parametric => |direct| switch (plans.evidenceNode(direct.evidence).target.kind) {
            .procedure => |procedure| switch (procedure.runtime_target) {
                .graph_participating, .intrinsic => true,
                .procedure, .low_level => false,
            },
            .local_proc => false,
            .structural => checkedArtifactInvariant("direct checked call targeted a structural derivation", .{}),
        },
        .direct_pending => checkedArtifactInvariant("unfinalized direct call reached template classification", .{}),
        .evidence_dependent, .structural, .@"unreachable", .checked_error => true,
    };
}

/// Publish category-specific per-template call spans after every checked call
/// has its final classification. Monotype's evidence replay consumes only the
/// relation pool, so a template with thousands of closed direct calls performs
/// no scan over those calls during specialization setup.
fn classifyTemplateDispatchPlanRefs(
    allocator: Allocator,
    plans: *static_dispatch.StaticDispatchPlanTable,
    templates: *CheckedProcedureTemplateTable,
) Allocator.Error!void {
    var direct_refs = std.ArrayList(static_dispatch.StaticDispatchPlanId).empty;
    errdefer direct_refs.deinit(allocator);
    var relation_refs = std.ArrayList(static_dispatch.StaticDispatchPlanId).empty;
    errdefer relation_refs.deinit(allocator);
    var relation_scopes = std.ArrayList(DispatchScope).empty;
    errdefer relation_scopes.deinit(allocator);
    var relation_kinds = std.ArrayList(DispatchRelationKind).empty;
    errdefer relation_kinds.deinit(allocator);

    for (templates.templates) |*template| {
        const original = template.static_dispatch_plans;
        const refs = plans.template_refs[original.start .. original.start + original.len];
        const scopes = templates.dispatch_ref_scopes[original.start .. original.start + original.len];
        const kinds = templates.dispatch_relation_kinds[original.start .. original.start + original.len];
        if (refs.len != scopes.len or refs.len != kinds.len) {
            checkedArtifactInvariant("template dispatch refs and publication metadata differed in length", .{});
        }

        const direct_start: u32 = @intCast(direct_refs.items.len);
        const relation_start: u32 = @intCast(relation_refs.items.len);
        for (refs, scopes, kinds) |plan_id, scope, kind| {
            const plan = plans.plans[@intFromEnum(plan_id)];
            if (checkedDispatchPlanNeedsRelation(plans, plan)) {
                try relation_refs.append(allocator, plan_id);
                try relation_scopes.append(allocator, scope);
                try relation_kinds.append(allocator, kind);
            } else {
                try direct_refs.append(allocator, plan_id);
            }
        }
        template.direct_dispatch_plans = .{
            .start = direct_start,
            .len = @intCast(direct_refs.items.len - direct_start),
        };
        template.dispatch_relations = .{
            .start = relation_start,
            .len = @intCast(relation_refs.items.len - relation_start),
        };
    }

    plans.direct_template_refs = try direct_refs.toOwnedSlice(allocator);
    plans.dispatch_relation_refs = try relation_refs.toOwnedSlice(allocator);
    allocator.free(templates.dispatch_ref_scopes);
    templates.dispatch_ref_scopes = try relation_scopes.toOwnedSlice(allocator);
    allocator.free(templates.dispatch_relation_kinds);
    templates.dispatch_relation_kinds = try relation_kinds.toOwnedSlice(allocator);
}

const ResolvedDispatchCallablePair = struct {
    target: CheckedTypeId,
    plan: CheckedTypeId,
};

fn instantiateResolvedDispatchTargetCallableMemoized(
    allocator: Allocator,
    names: *const canonical.CanonicalNameStore,
    store: *CheckedTypeStore,
    target_callable: CheckedTypeId,
    plan_callable: CheckedTypeId,
    memo: *std.AutoHashMapUnmanaged(ResolvedDispatchCallablePair, CheckedTypeId),
) Allocator.Error!CheckedTypeId {
    const key = ResolvedDispatchCallablePair{
        .target = target_callable,
        .plan = plan_callable,
    };
    if (memo.get(key)) |existing| return existing;

    const instantiated = try instantiateResolvedDispatchTargetCallable(
        allocator,
        names,
        store,
        target_callable,
        plan_callable,
    );
    try memo.put(allocator, key, instantiated);
    return instantiated;
}

fn projectResolvedDispatchTargetCallable(
    allocator: Allocator,
    names: *canonical.CanonicalNameStore,
    store: *CheckedTypeStore,
    artifact_key: CheckedModuleArtifactKey,
    direct_imports: []const PublishImportArtifact,
    available_artifacts: []const ImportedModuleView,
    target: static_dispatch.MethodTarget,
) Allocator.Error!CheckedTypeId {
    const target_key = switch (target.kind) {
        .local_proc => return target.callable_ty,
        .structural => checkedArtifactInvariant("structural method registry result was published as a direct callable target", .{}),
        .procedure => |procedure| checkedArtifactKeyFromArtifactRef(procedure.template.artifact),
    };
    if (checkedArtifactKeyEql(target_key, artifact_key)) return target.callable_ty;

    // Snapshot-style compiles pass the builtin module only as a DIRECT
    // import; total resolution makes builtin-owned direct targets ubiquitous,
    // so search both view sets.
    const imported = importedModuleViewByKey(available_artifacts, target_key) orelse direct: {
        for (direct_imports) |import| {
            if (checkedArtifactKeyEql(import.key, target_key)) break :direct import.view;
        }
        checkedArtifactInvariant("resolved dispatch target artifact was not available during checked publication", .{});
    };
    var projector = CheckedTypeStoreImportProjector.init(allocator, store, names, imported);
    defer projector.deinit();
    return try projector.project(target.callable_ty);
}

fn instantiateResolvedDispatchTargetCallable(
    allocator: Allocator,
    names: *const canonical.CanonicalNameStore,
    store: *CheckedTypeStore,
    target_callable: CheckedTypeId,
    plan_callable: CheckedTypeId,
) Allocator.Error!CheckedTypeId {
    const target_fn = checkedFunctionPayload(store, target_callable, "resolved dispatch target callable");
    const plan_fn = checkedFunctionPayload(store, plan_callable, "resolved dispatch plan callable");
    if (target_fn.args.len != plan_fn.args.len) {
        checkedArtifactInvariant("resolved dispatch target arity differed from plan arity", .{});
    }
    const target_args = try allocator.dupe(CheckedTypeId, target_fn.args);
    defer allocator.free(target_args);
    const plan_args = try allocator.dupe(CheckedTypeId, plan_fn.args);
    defer allocator.free(plan_args);
    const plan_ret = plan_fn.ret;

    var target_formals = std.ArrayList(CheckedTypeId).empty;
    defer target_formals.deinit(allocator);
    var target_actuals = std.ArrayList(CheckedTypeId).empty;
    defer target_actuals.deinit(allocator);
    var active = std.AutoHashMap(PlatformRequirementTypePair, void).init(allocator);
    defer active.deinit();
    var target_conflicts = collections.DenseMap(CheckedTypeId, void).init(allocator);
    defer target_conflicts.deinit();

    for (target_args, plan_args) |target_arg, plan_arg| {
        try collectResolvedDispatchTargetSubstitutions(
            allocator,
            names,
            store,
            target_arg,
            plan_arg,
            &target_formals,
            &target_actuals,
            &active,
            &target_conflicts,
        );
    }

    var clone_active = collections.DenseMap(CheckedTypeId, CheckedTypeId).init(allocator);
    defer clone_active.deinit();
    const instantiated_target = try store.cloneCheckedTypeRootSubstituting(
        allocator,
        names,
        target_callable,
        target_formals.items,
        target_actuals.items,
        &clone_active,
    );
    const target_instantiated_fn = checkedFunctionPayload(store, instantiated_target, "instantiated resolved dispatch target callable");
    const target_instantiated_args = try allocator.dupe(CheckedTypeId, target_instantiated_fn.args);
    defer allocator.free(target_instantiated_args);
    const target_instantiated_ret = target_instantiated_fn.ret;

    var plan_formals = std.ArrayList(CheckedTypeId).empty;
    defer plan_formals.deinit(allocator);
    var plan_actuals = std.ArrayList(CheckedTypeId).empty;
    defer plan_actuals.deinit(allocator);

    active.clearRetainingCapacity();
    for (target_instantiated_args, plan_args) |target_arg, plan_arg| {
        try collectDispatchPlanIdentitySubstitutions(
            allocator,
            names,
            store,
            target_arg,
            plan_arg,
            &plan_formals,
            &plan_actuals,
            &active,
        );
    }
    active.clearRetainingCapacity();
    try collectDispatchPlanIdentitySubstitutions(
        allocator,
        names,
        store,
        target_instantiated_ret,
        plan_ret,
        &plan_formals,
        &plan_actuals,
        &active,
    );

    clone_active.clearRetainingCapacity();
    return try store.cloneCheckedTypeRootSubstituting(
        allocator,
        names,
        plan_callable,
        plan_formals.items,
        plan_actuals.items,
        &clone_active,
    );
}

fn checkedFunctionPayload(
    store: *const CheckedTypeStore,
    root: CheckedTypeId,
    comptime context: []const u8,
) CheckedFunctionType {
    var current = root;
    var remaining = store.payloads.items.len;
    while (true) {
        const payload = store.payload(current);
        if (payload == .alias) {
            current = payload.alias.backing;
        } else if (payload == .function) {
            return payload.function;
        } else {
            checkedArtifactInvariant(context ++ " was not a function", .{});
        }
        if (remaining == 0) {
            checkedArtifactInvariant(context ++ " alias chain was cyclic", .{});
        }
        remaining -= 1;
    }
}

fn collectResolvedDispatchTargetSubstitutions(
    allocator: Allocator,
    names: *const canonical.CanonicalNameStore,
    store: *CheckedTypeStore,
    target: CheckedTypeId,
    plan: CheckedTypeId,
    formals: *std.ArrayList(CheckedTypeId),
    actuals: *std.ArrayList(CheckedTypeId),
    active: *std.AutoHashMap(PlatformRequirementTypePair, void),
    conflicts: *collections.DenseMap(CheckedTypeId, void),
) Allocator.Error!void {
    if (target == plan) return;

    const pair = PlatformRequirementTypePair{
        .expected = @intFromEnum(target),
        .actual = @intFromEnum(plan),
    };
    if (active.contains(pair)) return;
    try active.put(pair, {});
    defer _ = active.remove(pair);

    const target_payload = store.payload(target);
    const plan_payload = store.payload(plan);

    if (checkedTypePayloadIsIdentity(target_payload)) {
        try appendConsistentDispatchTargetSubstitution(formals, actuals, conflicts, allocator, target, plan);
        return;
    }
    if (checkedTypePayloadIsIdentity(plan_payload)) return;

    if (target_payload == .alias) {
        return try collectResolvedDispatchTargetSubstitutions(
            allocator,
            names,
            store,
            target_payload.alias.backing,
            plan,
            formals,
            actuals,
            active,
            conflicts,
        );
    }
    if (plan_payload == .alias) {
        return try collectResolvedDispatchTargetSubstitutions(
            allocator,
            names,
            store,
            target,
            plan_payload.alias.backing,
            formals,
            actuals,
            active,
            conflicts,
        );
    }

    switch (target_payload) {
        .function => |target_fn| {
            const plan_fn = switch (plan_payload) {
                .function => |function| function,
                .pending,
                .err,
                .flex,
                .rigid,
                .alias,
                .record,
                .record_unbound,
                .tuple,
                .nominal,
                .empty_record,
                .tag_union,
                .empty_tag_union,
                => return,
            };
            if (target_fn.args.len != plan_fn.args.len) return;
            for (target_fn.args, plan_fn.args) |target_arg, plan_arg| {
                try collectResolvedDispatchTargetSubstitutions(
                    allocator,
                    names,
                    store,
                    target_arg,
                    plan_arg,
                    formals,
                    actuals,
                    active,
                    conflicts,
                );
            }
        },
        .nominal => |target_nominal| {
            const plan_nominal = switch (plan_payload) {
                .nominal => |nominal| nominal,
                .pending,
                .err,
                .flex,
                .rigid,
                .alias,
                .record,
                .record_unbound,
                .tuple,
                .function,
                .empty_record,
                .tag_union,
                .empty_tag_union,
                => {
                    if (!target_nominal.is_opaque) {
                        const target_backing = (try store.ensureInstantiatedNominalBackingRootForPayload(
                            allocator,
                            names,
                            target_nominal,
                        )) orelse return;
                        try collectResolvedDispatchTargetSubstitutions(
                            allocator,
                            names,
                            store,
                            target_backing,
                            plan,
                            formals,
                            actuals,
                            active,
                            conflicts,
                        );
                    }
                    return;
                },
            };
            if (target_nominal.name != plan_nominal.name or
                target_nominal.origin_module != plan_nominal.origin_module or
                !checkedArtifactKeyEql(target_nominal.owner_module, plan_nominal.owner_module) or
                target_nominal.source_decl != plan_nominal.source_decl or
                target_nominal.builtin != plan_nominal.builtin or
                target_nominal.args.len != plan_nominal.args.len)
            {
                return;
            }
            var target_nominal_copy = target_nominal;
            var plan_nominal_copy = plan_nominal;
            target_nominal_copy.args = try allocator.dupe(CheckedTypeId, target_nominal.args);
            defer allocator.free(target_nominal_copy.args);
            plan_nominal_copy.args = try allocator.dupe(CheckedTypeId, plan_nominal.args);
            defer allocator.free(plan_nominal_copy.args);

            for (target_nominal_copy.args, plan_nominal_copy.args) |target_arg, plan_arg| {
                try collectResolvedDispatchTargetSubstitutions(
                    allocator,
                    names,
                    store,
                    target_arg,
                    plan_arg,
                    formals,
                    actuals,
                    active,
                    conflicts,
                );
            }
            // Matching nominal applications are completely related by their
            // arguments. Their shared declaration backing is representation
            // data and is opened only for nominal-versus-structural relations.
        },
        .tuple => |target_items| {
            const plan_items = switch (plan_payload) {
                .tuple => |items| items,
                .pending,
                .err,
                .flex,
                .rigid,
                .alias,
                .record,
                .record_unbound,
                .nominal,
                .function,
                .empty_record,
                .tag_union,
                .empty_tag_union,
                => return,
            };
            if (target_items.len != plan_items.len) return;
            for (target_items, plan_items) |target_item, plan_item| {
                try collectResolvedDispatchTargetSubstitutions(
                    allocator,
                    names,
                    store,
                    target_item,
                    plan_item,
                    formals,
                    actuals,
                    active,
                    conflicts,
                );
            }
        },
        .empty_record,
        .record,
        .record_unbound,
        => try collectResolvedDispatchRecordSubstitutions(
            allocator,
            names,
            store,
            target_payload,
            plan_payload,
            formals,
            actuals,
            active,
            conflicts,
        ),
        .empty_tag_union,
        .tag_union,
        => try collectResolvedDispatchTagSubstitutions(
            allocator,
            names,
            store,
            target_payload,
            plan_payload,
            formals,
            actuals,
            active,
            conflicts,
        ),
        .pending, .err, .flex, .rigid, .alias => {},
    }
}

fn collectResolvedDispatchRecordSubstitutions(
    allocator: Allocator,
    names: *const canonical.CanonicalNameStore,
    store: *CheckedTypeStore,
    target_payload: CheckedTypePayload,
    plan_payload: CheckedTypePayload,
    formals: *std.ArrayList(CheckedTypeId),
    actuals: *std.ArrayList(CheckedTypeId),
    active: *std.AutoHashMap(PlatformRequirementTypePair, void),
    conflicts: *collections.DenseMap(CheckedTypeId, void),
) Allocator.Error!void {
    const target_parts = recordParts(target_payload) orelse return;
    const plan_parts = recordParts(plan_payload) orelse return;
    const target_row = try flattenPlatformRequirementRecordRow(allocator, store, target_parts.fields, target_parts.ext);
    defer target_row.deinit(allocator);
    const plan_row = try flattenPlatformRequirementRecordRow(allocator, store, plan_parts.fields, plan_parts.ext);
    defer plan_row.deinit(allocator);

    for (target_row.fields) |target_field| {
        const plan_field = findRecordField(names, plan_row.fields, target_field.name) orelse continue;
        try collectResolvedDispatchTargetSubstitutions(
            allocator,
            names,
            store,
            target_field.ty,
            plan_field.ty,
            formals,
            actuals,
            active,
            conflicts,
        );
    }

    if (target_row.tail) |target_tail| {
        if (plan_row.tail) |plan_tail| {
            try collectResolvedDispatchTargetSubstitutions(
                allocator,
                names,
                store,
                target_tail,
                plan_tail,
                formals,
                actuals,
                active,
                conflicts,
            );
        }
    }
}

fn collectResolvedDispatchTagSubstitutions(
    allocator: Allocator,
    names: *const canonical.CanonicalNameStore,
    store: *CheckedTypeStore,
    target_payload: CheckedTypePayload,
    plan_payload: CheckedTypePayload,
    formals: *std.ArrayList(CheckedTypeId),
    actuals: *std.ArrayList(CheckedTypeId),
    active: *std.AutoHashMap(PlatformRequirementTypePair, void),
    conflicts: *collections.DenseMap(CheckedTypeId, void),
) Allocator.Error!void {
    const target_union = tagUnionParts(target_payload) orelse return;
    const plan_union = tagUnionParts(plan_payload) orelse return;
    const target_row = try flattenPlatformRequirementTagRow(allocator, store, target_union.tags, target_union.ext);
    defer target_row.deinit(allocator);
    const plan_row = try flattenPlatformRequirementTagRow(allocator, store, plan_union.tags, plan_union.ext);
    defer plan_row.deinit(allocator);

    for (target_row.tags) |target_tag| {
        const plan_tag = findTag(names, plan_row.tags, target_tag.name) orelse continue;
        const target_args = target_tag.argsSlice(store);
        const plan_args = plan_tag.argsSlice(store);
        if (target_args.len != plan_args.len) continue;
        for (target_args, plan_args) |target_arg, plan_arg| {
            try collectResolvedDispatchTargetSubstitutions(
                allocator,
                names,
                store,
                target_arg,
                plan_arg,
                formals,
                actuals,
                active,
                conflicts,
            );
        }
    }

    if (target_row.tail) |target_tail| {
        if (plan_row.tail) |plan_tail| {
            try collectResolvedDispatchTargetSubstitutions(
                allocator,
                names,
                store,
                target_tail,
                plan_tail,
                formals,
                actuals,
                active,
                conflicts,
            );
        }
    }
}

fn collectDispatchPlanIdentitySubstitutions(
    allocator: Allocator,
    names: *const canonical.CanonicalNameStore,
    store: *CheckedTypeStore,
    target: CheckedTypeId,
    plan: CheckedTypeId,
    formals: *std.ArrayList(CheckedTypeId),
    actuals: *std.ArrayList(CheckedTypeId),
    active: *std.AutoHashMap(PlatformRequirementTypePair, void),
) Allocator.Error!void {
    if (target == plan) return;

    const pair = PlatformRequirementTypePair{
        .expected = @intFromEnum(target),
        .actual = @intFromEnum(plan),
    };
    if (active.contains(pair)) return;
    try active.put(pair, {});
    defer _ = active.remove(pair);

    const target_payload = store.payload(target);
    const plan_payload = store.payload(plan);

    if (checkedTypePayloadIsIdentity(plan_payload)) {
        if (!checkedTypePayloadIsIdentity(target_payload)) {
            try appendUniqueCheckedTypeSubstitution(formals, actuals, allocator, names, store, plan, target);
        }
        return;
    }
    if (checkedTypePayloadIsIdentity(target_payload)) return;

    if (target_payload == .alias) {
        return try collectDispatchPlanIdentitySubstitutions(
            allocator,
            names,
            store,
            target_payload.alias.backing,
            plan,
            formals,
            actuals,
            active,
        );
    }
    if (plan_payload == .alias) {
        return try collectDispatchPlanIdentitySubstitutions(
            allocator,
            names,
            store,
            target,
            plan_payload.alias.backing,
            formals,
            actuals,
            active,
        );
    }

    switch (target_payload) {
        .function => |target_fn| {
            const plan_fn = switch (plan_payload) {
                .function => |function| function,
                .pending,
                .err,
                .flex,
                .rigid,
                .alias,
                .record,
                .record_unbound,
                .tuple,
                .nominal,
                .empty_record,
                .tag_union,
                .empty_tag_union,
                => return,
            };
            if (target_fn.args.len != plan_fn.args.len) return;
            for (target_fn.args, plan_fn.args) |target_arg, plan_arg| {
                try collectDispatchPlanIdentitySubstitutions(
                    allocator,
                    names,
                    store,
                    target_arg,
                    plan_arg,
                    formals,
                    actuals,
                    active,
                );
            }
            try collectDispatchPlanIdentitySubstitutions(
                allocator,
                names,
                store,
                target_fn.ret,
                plan_fn.ret,
                formals,
                actuals,
                active,
            );
        },
        .nominal => |target_nominal| {
            const plan_nominal = switch (plan_payload) {
                .nominal => |nominal| nominal,
                .pending,
                .err,
                .flex,
                .rigid,
                .alias,
                .record,
                .record_unbound,
                .tuple,
                .function,
                .empty_record,
                .tag_union,
                .empty_tag_union,
                => {
                    if (!target_nominal.is_opaque) {
                        const target_backing = (try store.ensureInstantiatedNominalBackingRootForPayload(
                            allocator,
                            names,
                            target_nominal,
                        )) orelse return;
                        try collectDispatchPlanIdentitySubstitutions(
                            allocator,
                            names,
                            store,
                            target_backing,
                            plan,
                            formals,
                            actuals,
                            active,
                        );
                    }
                    return;
                },
            };
            if (target_nominal.name != plan_nominal.name or
                target_nominal.origin_module != plan_nominal.origin_module or
                !checkedArtifactKeyEql(target_nominal.owner_module, plan_nominal.owner_module) or
                target_nominal.source_decl != plan_nominal.source_decl or
                target_nominal.builtin != plan_nominal.builtin or
                target_nominal.args.len != plan_nominal.args.len)
            {
                return;
            }
            var target_nominal_copy = target_nominal;
            var plan_nominal_copy = plan_nominal;
            target_nominal_copy.args = try allocator.dupe(CheckedTypeId, target_nominal.args);
            defer allocator.free(target_nominal_copy.args);
            plan_nominal_copy.args = try allocator.dupe(CheckedTypeId, plan_nominal.args);
            defer allocator.free(plan_nominal_copy.args);

            for (target_nominal_copy.args, plan_nominal_copy.args) |target_arg, plan_arg| {
                try collectDispatchPlanIdentitySubstitutions(
                    allocator,
                    names,
                    store,
                    target_arg,
                    plan_arg,
                    formals,
                    actuals,
                    active,
                );
            }
            // Matching nominal applications are completely related by their
            // arguments. Their shared declaration backing is representation
            // data and is opened only for nominal-versus-structural relations.
        },
        .tuple => |target_items| {
            const plan_items = switch (plan_payload) {
                .tuple => |items| items,
                .pending,
                .err,
                .flex,
                .rigid,
                .alias,
                .record,
                .record_unbound,
                .nominal,
                .function,
                .empty_record,
                .tag_union,
                .empty_tag_union,
                => return,
            };
            if (target_items.len != plan_items.len) return;
            for (target_items, plan_items) |target_item, plan_item| {
                try collectDispatchPlanIdentitySubstitutions(
                    allocator,
                    names,
                    store,
                    target_item,
                    plan_item,
                    formals,
                    actuals,
                    active,
                );
            }
        },
        .empty_record,
        .record,
        .record_unbound,
        => try collectDispatchPlanRecordIdentitySubstitutions(
            allocator,
            names,
            store,
            target_payload,
            plan_payload,
            formals,
            actuals,
            active,
        ),
        .empty_tag_union,
        .tag_union,
        => try collectDispatchPlanTagIdentitySubstitutions(
            allocator,
            names,
            store,
            target_payload,
            plan_payload,
            formals,
            actuals,
            active,
        ),
        .pending, .err, .flex, .rigid, .alias => {},
    }
}

fn collectDispatchPlanRecordIdentitySubstitutions(
    allocator: Allocator,
    names: *const canonical.CanonicalNameStore,
    store: *CheckedTypeStore,
    target_payload: CheckedTypePayload,
    plan_payload: CheckedTypePayload,
    formals: *std.ArrayList(CheckedTypeId),
    actuals: *std.ArrayList(CheckedTypeId),
    active: *std.AutoHashMap(PlatformRequirementTypePair, void),
) Allocator.Error!void {
    const target_parts = recordParts(target_payload) orelse return;
    const plan_parts = recordParts(plan_payload) orelse return;
    const target_row = try flattenPlatformRequirementRecordRow(allocator, store, target_parts.fields, target_parts.ext);
    defer target_row.deinit(allocator);
    const plan_row = try flattenPlatformRequirementRecordRow(allocator, store, plan_parts.fields, plan_parts.ext);
    defer plan_row.deinit(allocator);

    for (target_row.fields) |target_field| {
        const plan_field = findRecordField(names, plan_row.fields, target_field.name) orelse continue;
        try collectDispatchPlanIdentitySubstitutions(
            allocator,
            names,
            store,
            target_field.ty,
            plan_field.ty,
            formals,
            actuals,
            active,
        );
    }

    if (target_row.tail) |target_tail| {
        if (plan_row.tail) |plan_tail| {
            try collectDispatchPlanIdentitySubstitutions(
                allocator,
                names,
                store,
                target_tail,
                plan_tail,
                formals,
                actuals,
                active,
            );
        }
    }
}

fn collectDispatchPlanTagIdentitySubstitutions(
    allocator: Allocator,
    names: *const canonical.CanonicalNameStore,
    store: *CheckedTypeStore,
    target_payload: CheckedTypePayload,
    plan_payload: CheckedTypePayload,
    formals: *std.ArrayList(CheckedTypeId),
    actuals: *std.ArrayList(CheckedTypeId),
    active: *std.AutoHashMap(PlatformRequirementTypePair, void),
) Allocator.Error!void {
    const target_union = tagUnionParts(target_payload) orelse return;
    const plan_union = tagUnionParts(plan_payload) orelse return;
    const target_row = try flattenPlatformRequirementTagRow(allocator, store, target_union.tags, target_union.ext);
    defer target_row.deinit(allocator);
    const plan_row = try flattenPlatformRequirementTagRow(allocator, store, plan_union.tags, plan_union.ext);
    defer plan_row.deinit(allocator);

    for (target_row.tags) |target_tag| {
        const plan_tag = findTag(names, plan_row.tags, target_tag.name) orelse continue;
        const target_args = target_tag.argsSlice(store);
        const plan_args = plan_tag.argsSlice(store);
        if (target_args.len != plan_args.len) continue;
        for (target_args, plan_args) |target_arg, plan_arg| {
            try collectDispatchPlanIdentitySubstitutions(
                allocator,
                names,
                store,
                target_arg,
                plan_arg,
                formals,
                actuals,
                active,
            );
        }
    }

    if (target_row.tail) |target_tail| {
        if (plan_row.tail) |plan_tail| {
            try collectDispatchPlanIdentitySubstitutions(
                allocator,
                names,
                store,
                target_tail,
                plan_tail,
                formals,
                actuals,
                active,
            );
        }
    }
}

fn appendConsistentDispatchTargetSubstitution(
    formals: *std.ArrayList(CheckedTypeId),
    actuals: *std.ArrayList(CheckedTypeId),
    conflicts: *collections.DenseMap(CheckedTypeId, void),
    allocator: Allocator,
    formal: CheckedTypeId,
    actual: CheckedTypeId,
) Allocator.Error!void {
    if (conflicts.contains(formal)) return;

    for (formals.items, actuals.items, 0..) |existing_formal, existing_actual, i| {
        if (existing_formal != formal) continue;
        if (existing_actual == actual) return;

        try conflicts.put(formal, {});
        _ = formals.orderedRemove(i);
        _ = actuals.orderedRemove(i);
        return;
    }

    try formals.append(allocator, formal);
    try actuals.append(allocator, actual);
}

fn appendUniqueCheckedTypeSubstitution(
    formals: *std.ArrayList(CheckedTypeId),
    actuals: *std.ArrayList(CheckedTypeId),
    allocator: Allocator,
    names: *const canonical.CanonicalNameStore,
    store: *const CheckedTypeStore,
    formal: CheckedTypeId,
    actual: CheckedTypeId,
) Allocator.Error!void {
    for (formals.items, actuals.items) |existing_formal, existing_actual| {
        if (existing_formal != formal) continue;
        if (existing_actual != actual) {
            // A store can hold two roots for one concrete type: publication
            // and the substituted-clone path key identical content in
            // different formats, so a partially rebuilt instantiation can
            // reference the original root in one position and the clone's
            // root in another. Two ids for identical content are one actual,
            // not a conflict—keep the first. Only genuinely different
            // contents (compared in the substituted-key space, which is
            // format-uniform) violate the invariant.
            const existing_key = try substitutedCheckedTypeKey(allocator, names, store, existing_actual, &.{}, &.{});
            const new_key = try substitutedCheckedTypeKey(allocator, names, store, actual, &.{}, &.{});
            if (!std.meta.eql(existing_key.bytes, new_key.bytes)) {
                checkedArtifactInvariant("checked type substitution mapped one formal to multiple actuals", .{});
            }
        }
        return;
    }
    try formals.append(allocator, formal);
    try actuals.append(allocator, actual);
}

fn importedModuleViewByKey(
    artifacts: []const ImportedModuleView,
    key: CheckedModuleArtifactKey,
) ?ImportedModuleView {
    for (artifacts) |artifact| {
        if (std.meta.eql(artifact.key.bytes, key.bytes)) return artifact;
    }
    return null;
}

fn relationArtifactByKey(
    relation_artifacts: []const ImportedModuleView,
    key: CheckedModuleArtifactKey,
) ?ImportedModuleView {
    return importedModuleViewByKey(relation_artifacts, key);
}

fn validatePlatformBindingRelation(
    declaration: PlatformRequiredDeclarationId,
    requires_idx: u32,
    app_value: TopLevelValueRef,
    value_use_kind: PlatformRequiredValueUseKind,
    relation: PlatformRequirementRelation,
    binding_index: usize,
) void {
    if (relation.declaration != declaration or relation.requires_idx != requires_idx) {
        if (builtin.mode == .Debug) {
            std.debug.panic(
                "checked artifact invariant violated: platform/app binding {d} points at a checked relation for a different requirement",
                .{binding_index},
            );
        }
        unreachable;
    }
    if (!std.meta.eql(relation.app_value.artifact.bytes, app_value.artifact.bytes) or
        relation.app_value.pattern != app_value.pattern)
    {
        if (builtin.mode == .Debug) {
            std.debug.panic(
                "checked artifact invariant violated: platform/app binding {d} points at a checked relation for a different app value",
                .{binding_index},
            );
        }
        unreachable;
    }
    switch (value_use_kind) {
        .const_value => if (relation.value_kind != .const_value) {
            if (builtin.mode == .Debug) {
                std.debug.panic(
                    "checked artifact invariant violated: platform/app binding {d} has const value use but procedure checked relation",
                    .{binding_index},
                );
            }
            unreachable;
        },
        .procedure_value => if (relation.value_kind != .procedure_value) {
            if (builtin.mode == .Debug) {
                std.debug.panic(
                    "checked artifact invariant violated: platform/app binding {d} has procedure value use but const checked relation",
                    .{binding_index},
                );
            }
            unreachable;
        },
    }
}

fn clonePlatformRequiredValueUseWithRelation(
    allocator: Allocator,
    value_use: PlatformRequiredValueUse,
    relation: PlatformRequirementRelation,
) Allocator.Error!PlatformRequiredValueUse {
    return switch (value_use) {
        .const_value => |const_use| .{ .const_value = .{
            .const_use = .{
                .const_ref = const_use.const_use.const_ref,
                .requested_source_ty_template = relation.requested_source_ty,
                .requested_source_ty_payload = relation.requested_source_ty_payload,
            },
            .relation_template_closure = try cloneImportedTemplateClosure(allocator, const_use.relation_template_closure),
        } },
        .procedure_value => |proc_use| .{ .procedure_value = .{
            .procedure = .{
                .binding = proc_use.procedure.binding,
                .source_fn_ty_template = relation.requested_source_ty,
                .source_fn_ty_payload = relation.requested_source_ty_payload,
                .intrinsic = proc_use.procedure.intrinsic,
                .iterator_procedure = proc_use.procedure.iterator_procedure,
                .runtime_result_provenance = proc_use.procedure.runtime_result_provenance,
            },
            .root_evidence = .{
                .checked_module = relation.app_value.artifact,
                .span = relation.root_evidence,
            },
            .relation_template_closure = try cloneImportedTemplateClosure(allocator, proc_use.relation_template_closure),
        } },
    };
}

/// Commit a slice-form `PlatformRequiredValueUse` into `pool`, returning the POD
/// stored form. Takes ownership of the value_use's closure slices (copied into
/// the pool and freed), mirroring `deinitPlatformRequiredValueUse`.
fn commitPlatformRequiredValueUse(
    pool: *ClosurePool,
    allocator: Allocator,
    value_use: PlatformRequiredValueUse,
) Allocator.Error!StoredPlatformRequiredValueUse {
    return switch (value_use) {
        .const_value => |const_use| .{
            .const_value = .{
                .const_use = const_use.const_use,
                .relation_template_closure = try pool.commit(allocator, const_use.relation_template_closure),
            },
        },
        .procedure_value => |proc_use| .{
            .procedure_value = .{
                .procedure = proc_use.procedure,
                .root_evidence = proc_use.root_evidence,
                .relation_template_closure = try pool.commit(allocator, proc_use.relation_template_closure),
            },
        },
    };
}

/// Public `platformRequirementContextKey` function.
pub fn platformRequirementContextKey(artifact: *const CheckedModuleArtifact) PlatformRequirementContextKey {
    return PlatformRequirementContextKey.compute(
        artifact.module_identity,
        artifact.platform_required_declarations.identityHash(&artifact.canonical_names),
    );
}

/// Public `buildPlatformAppRelation` function.
pub fn buildPlatformAppRelation(
    allocator: Allocator,
    platform_module: TypedCIR.Module,
    app_artifact: *const CheckedModuleArtifact,
) Allocator.Error!PlatformAppRelation {
    const platform_module_env = platform_module.moduleEnvConst();

    // Derive the platform's required declarations and requirement context from the
    // typed platform module directly (a scratch name store the table interns into),
    // so finalization consumes the platform root's checked module rather than a
    // previously-published declaration artifact.
    var declaration_names = canonical.CanonicalNameStore.init(allocator);
    defer declaration_names.deinit();
    var declaration_table = try PlatformRequiredDeclarationTable.fromModule(allocator, platform_module, &declaration_names);
    defer declaration_table.deinit(allocator);
    const declarations = declaration_table.declarations;

    var relations = std.ArrayList(PlatformRequirementRelationInput).empty;
    errdefer relations.deinit(allocator);
    var bindings = std.ArrayList(PlatformRequiredBindingInput).empty;
    errdefer {
        for (bindings.items) |*binding| deinitPlatformRequiredValueUse(allocator, &binding.value_use);
        bindings.deinit(allocator);
    }
    var checked_error_requires = std.ArrayList(u32).empty;
    errdefer checked_error_requires.deinit(allocator);

    var identity_solutions_app = std.ArrayList(CheckedTypeId).empty;
    errdefer identity_solutions_app.deinit(allocator);

    const requirement_context = PlatformRequirementContextKey.computeFromParts(
        computeStableModuleIdentityHash(platform_module_env),
        declaration_table.identityHash(&declaration_names),
    );
    const relation_key = PlatformAppRelationKey.compute(app_artifact.key, requirement_context);

    for (declarations) |declaration| {
        // The checker records successful solutions as exact app value/type
        // facts. A missing row is recorded explicitly as a checked-error
        // requirement so publication stays total without inventing a binding.
        const solution = app_artifact.platform_requirement_solutions.lookupByRequiredIndex(declaration.requires_idx) orelse {
            try checked_error_requires.append(allocator, declaration.requires_idx);
            continue;
        };

        const requested_source_ty = try canonical_type_keys.fromVar(
            allocator,
            &platform_module_env.types,
            platform_module_env,
            ModuleEnv.varFrom(declaration.type_anno),
        );
        const app_value_ref = TopLevelValueRef{
            .artifact = app_artifact.key,
            .pattern = solution.pattern,
        };

        const required_ty_is_function = platform_module_env.types.varResolvesToFunction(ModuleEnv.varFrom(declaration.type_anno));
        if (builtin.mode == .Debug) {
            const derived_kind: PlatformRequiredValueKind = if (required_ty_is_function) .procedure_value else .const_value;
            std.debug.assert(derived_kind == solution.value_kind);
        }
        const value_kind = solution.value_kind;

        const top_level = app_artifact.top_level_values.lookupByDef(solution.def) orelse {
            checkedArtifactInvariant("platform requirement solution references a def with no published top-level value", .{});
        };
        if (builtin.mode == .Debug) {
            std.debug.assert(top_level.pattern == solution.pattern);
        }

        const app_identity_slice = app_artifact.platform_requirement_solutions.identitySlice(solution);
        const identity_start: u32 = @intCast(identity_solutions_app.items.len);
        try identity_solutions_app.appendSlice(allocator, app_identity_slice);
        const identity_len: u32 = @intCast(app_identity_slice.len);

        const relation_id: PlatformRequirementRelationId = @enumFromInt(@as(u32, @intCast(relations.items.len)));
        try relations.append(allocator, .{
            .id = relation_id,
            .declaration = declaration.id,
            .requires_idx = declaration.requires_idx,
            .app_value = app_value_ref,
            .requested_source_ty = requested_source_ty,
            .value_kind = value_kind,
            .solved_root_app = solution.solved_root,
            .root_evidence = solution.root_evidence,
            .identity_start = identity_start,
            .identity_len = identity_len,
        });

        try bindings.append(allocator, .{
            .declaration = declaration.id,
            .requires_idx = declaration.requires_idx,
            .app_value = app_value_ref,
            .requested_source_ty = requested_source_ty,
            .checked_relation = relation_id,
            .value_use = if (value_kind == .procedure_value) blk: {
                const procedure_binding = switch (top_level.value) {
                    .procedure_binding => |binding| binding,
                    .const_ref => checkedArtifactInvariant("platform requirement solution needs a procedure but the app value is a const", .{}),
                };
                _ = app_artifact.top_level_procedure_bindings.get(procedure_binding);
                const exported_binding = exportedProcedureBindingForAppValue(
                    app_artifact.exported_procedure_bindings.view(),
                    top_level,
                );
                var template_closure = try cloneImportedTemplateClosure(
                    allocator,
                    exportedProcedureBindingClosureForAppValue(app_artifact, exported_binding),
                );
                errdefer deinitImportedTemplateClosure(allocator, &template_closure);

                break :blk .{ .procedure_value = .{
                    .procedure = platformRequiredProcedureUse(
                        app_artifact.key,
                        app_value_ref,
                        procedure_binding,
                        requested_source_ty,
                        exported_binding,
                    ),
                    .root_evidence = .{
                        .checked_module = app_artifact.key,
                        .span = solution.root_evidence,
                    },
                    .relation_template_closure = template_closure,
                } };
            } else blk: {
                const const_ref = switch (top_level.value) {
                    .const_ref => |ref| ref,
                    .procedure_binding => checkedArtifactInvariant("platform requirement solution needs a const but the app value is a procedure", .{}),
                };
                var template_closure = try cloneImportedTemplateClosure(
                    allocator,
                    exportedConstTemplateClosureForAppValue(app_artifact, app_value_ref, const_ref),
                );
                errdefer deinitImportedTemplateClosure(allocator, &template_closure);

                break :blk .{ .const_value = .{
                    .const_use = .{
                        .const_ref = const_ref,
                        .requested_source_ty_template = requested_source_ty,
                        .requested_source_ty_payload = null,
                    },
                    .relation_template_closure = template_closure,
                } };
            },
        });
    }

    const owned_relations = try relations.toOwnedSlice(allocator);
    errdefer allocator.free(owned_relations);
    const owned_bindings = try bindings.toOwnedSlice(allocator);
    errdefer {
        for (owned_bindings) |*binding| deinitPlatformRequiredValueUse(allocator, &binding.value_use);
        allocator.free(owned_bindings);
    }
    const owned_checked_errors = try checked_error_requires.toOwnedSlice(allocator);
    errdefer allocator.free(owned_checked_errors);
    const owned_identity_solutions = try identity_solutions_app.toOwnedSlice(allocator);
    errdefer allocator.free(owned_identity_solutions);

    return .{
        .key = relation_key,
        .requirement_context = requirement_context,
        .platform_module_idx = platform_module.moduleIndex(),
        .app_artifact = app_artifact.key,
        .relations = owned_relations,
        .bindings = owned_bindings,
        .checked_error_requires = owned_checked_errors,
        .identity_solutions_app = owned_identity_solutions,
    };
}

const FlattenedPlatformRequirementRecordRow = struct {
    fields: []const CheckedRecordField,
    tail: ?CheckedTypeId,

    fn deinit(self: @This(), allocator: Allocator) void {
        if (self.fields.len > 0) allocator.free(self.fields);
    }
};

fn flattenPlatformRequirementRecordRow(
    allocator: Allocator,
    store: *const CheckedTypeStore,
    head: []const CheckedRecordField,
    ext: ?CheckedTypeId,
) Allocator.Error!FlattenedPlatformRequirementRecordRow {
    var fields = std.ArrayList(CheckedRecordField).empty;
    errdefer fields.deinit(allocator);
    try fields.appendSlice(allocator, head);
    var tail = ext;
    var seen = collections.DenseMap(CheckedTypeId, void).init(allocator);
    defer seen.deinit();
    while (tail) |tail_id| {
        if (seen.contains(tail_id)) {
            tail = null;
            break;
        }
        try seen.put(tail_id, {});
        switch (platformRequirementPayload(store, tail_id)) {
            .empty_record => {
                tail = null;
                break;
            },
            .record => |record| {
                try fields.appendSlice(allocator, record.fields);
                tail = record.ext;
            },
            .record_unbound => |tail_fields| {
                try fields.appendSlice(allocator, tail_fields);
                tail = null;
                break;
            },
            .alias => |alias| tail = alias.backing,
            .pending,
            .err,
            .flex,
            .rigid,
            .tuple,
            .nominal,
            .function,
            .tag_union,
            .empty_tag_union,
            => break,
        }
    }
    return .{ .fields = try fields.toOwnedSlice(allocator), .tail = tail };
}

const FlattenedPlatformRequirementTagRow = struct {
    tags: []const CheckedTag,
    tail: ?CheckedTypeId,

    fn deinit(self: @This(), allocator: Allocator) void {
        if (self.tags.len > 0) allocator.free(self.tags);
    }
};

fn flattenPlatformRequirementTagRow(
    allocator: Allocator,
    store: *const CheckedTypeStore,
    head: []const CheckedTag,
    ext: ?CheckedTypeId,
) Allocator.Error!FlattenedPlatformRequirementTagRow {
    var tags = std.ArrayList(CheckedTag).empty;
    errdefer tags.deinit(allocator);
    try tags.appendSlice(allocator, head);
    var tail = ext;
    var seen = collections.DenseMap(CheckedTypeId, void).init(allocator);
    defer seen.deinit();
    while (tail) |tail_id| {
        if (seen.contains(tail_id)) {
            tail = null;
            break;
        }
        try seen.put(tail_id, {});
        switch (platformRequirementPayload(store, tail_id)) {
            .empty_tag_union => {
                tail = null;
                break;
            },
            .tag_union => |tag_union| {
                try tags.appendSlice(allocator, tag_union.tags);
                tail = tag_union.ext;
            },
            .alias => |alias| tail = alias.backing,
            .pending,
            .err,
            .flex,
            .rigid,
            .record,
            .record_unbound,
            .tuple,
            .nominal,
            .function,
            .empty_record,
            => break,
        }
    }
    return .{ .tags = try tags.toOwnedSlice(allocator), .tail = tail };
}

fn platformRequirementPayload(store: *const CheckedTypeStore, root: CheckedTypeId) CheckedTypePayload {
    const index: usize = @intFromEnum(root);
    if (index >= store.payloads.items.len) {
        checkedArtifactInvariant("platform requirement referenced missing checked type payload", .{});
    }
    return store.payload(@enumFromInt(index));
}

const RelationTagUnionParts = struct {
    tags: []const CheckedTag,
    ext: ?CheckedTypeId,
};

fn tagUnionParts(payload: CheckedTypePayload) ?RelationTagUnionParts {
    return switch (payload) {
        .tag_union => |tag_union| .{ .tags = tag_union.tags, .ext = tag_union.ext },
        .empty_tag_union => .{ .tags = &.{}, .ext = null },
        .pending,
        .err,
        .flex,
        .rigid,
        .alias,
        .record,
        .record_unbound,
        .tuple,
        .nominal,
        .function,
        .empty_record,
        => null,
    };
}

/// A visited pair of checked type roots, keyed by their raw ids. Used as the
/// cycle guard while walking two structurally-parallel checked types in
/// lock-step (resolved dispatch target substitution collection).
const PlatformRequirementTypePair = struct {
    expected: u32,
    actual: u32,
};

fn checkedTypePayloadIsIdentity(payload: CheckedTypePayload) bool {
    return payload == .flex or payload == .rigid;
}

const RelationRecordParts = struct {
    fields: []const CheckedRecordField,
    ext: ?CheckedTypeId,
};

fn recordParts(payload: CheckedTypePayload) ?RelationRecordParts {
    return switch (payload) {
        .record => |record| .{ .fields = record.fields, .ext = record.ext },
        .record_unbound => |fields| .{ .fields = fields, .ext = null },
        .empty_record => .{ .fields = &.{}, .ext = null },
        .pending,
        .err,
        .flex,
        .rigid,
        .alias,
        .tuple,
        .nominal,
        .function,
        .tag_union,
        .empty_tag_union,
        => null,
    };
}

fn findRecordField(
    names: *const canonical.CanonicalNameStore,
    fields: []const CheckedRecordField,
    name: canonical.RecordFieldLabelId,
) ?CheckedRecordField {
    for (fields) |field| {
        if (names.recordFieldLabelTextEql(field.name, name)) return field;
    }
    return null;
}

fn findTag(
    names: *const canonical.CanonicalNameStore,
    tags: []const CheckedTag,
    name: canonical.TagLabelId,
) ?CheckedTag {
    for (tags) |tag| {
        if (names.tagLabelTextEql(tag.name, name)) return tag;
    }
    return null;
}

fn exportedProcedureBindingClosureForAppValue(
    app_artifact: *const CheckedModuleArtifact,
    binding: ImportedProcedureBindingView,
) ImportedTemplateClosureView {
    switch (binding.body) {
        .direct_template => |direct| {
            if (checkedTemplateFromCallableTemplateForClosure(direct.template)) |template_ref| {
                return exportedProcedureTemplateClosureForRef(app_artifact, template_ref);
            }
        },
        .callable_eval_template => {},
    }
    return app_artifact.exported_procedure_bindings.rowClosure(binding);
}

fn exportedProcedureBindingForAppValue(
    bindings: ExportedProcedureBindingView,
    app_value: TopLevelValueEntry,
) ImportedProcedureBindingView {
    for (bindings.bindings) |binding| {
        if (binding.binding.def == app_value.def and binding.binding.pattern == app_value.pattern) return binding;
    }
    checkedArtifactInvariant("platform-required app procedure was not exported by the app artifact", .{});
}

fn platformRequiredProcedureUse(
    app_artifact: CheckedModuleArtifactKey,
    app_value: TopLevelValueRef,
    procedure_binding: TopLevelProcedureBindingRef,
    requested_source_ty: canonical.CanonicalTypeKey,
    exported_binding: ImportedProcedureBindingView,
) ProcedureUseTemplate {
    if (!checkedArtifactKeyEql(exported_binding.binding.artifact, app_artifact) or
        exported_binding.binding.pattern != app_value.pattern)
    {
        checkedArtifactInvariant("platform-required app procedure use disagreed with its exported binding", .{});
    }
    return .{
        .binding = .{ .platform_required = .{
            .artifact = app_artifact,
            .app_value = app_value,
            .procedure_binding = procedure_binding,
        } },
        .source_fn_ty_template = requested_source_ty,
        .source_fn_ty_payload = null,
        .intrinsic = null,
        .iterator_procedure = exported_binding.iterator_procedure,
        .runtime_result_provenance = exported_binding.runtime_result_provenance,
    };
}

fn exportedProcedureTemplateClosureForRef(
    app_artifact: *const CheckedModuleArtifact,
    template_ref: canonical.ProcedureTemplateRef,
) ImportedTemplateClosureView {
    for (app_artifact.exported_procedure_templates.templates) |template| {
        if (canonical.procedureTemplateRefEql(template.template, template_ref)) return app_artifact.exported_procedure_templates.rowClosure(template);
    }
    checkedArtifactInvariant("platform-required app procedure template was not exported by the app artifact", .{});
}

fn exportedConstTemplateClosureForAppValue(
    app_artifact: *const CheckedModuleArtifact,
    app_value: TopLevelValueRef,
    const_ref: ConstRef,
) ImportedTemplateClosureView {
    for (app_artifact.exported_const_templates.templates) |template| {
        if (template.pattern != app_value.pattern) continue;
        if (!constRefEql(template.const_ref, const_ref)) {
            checkedArtifactInvariant("platform-required app const export disagreed with top-level const ref", .{});
        }
        return app_artifact.exported_const_templates.rowClosure(template);
    }
    checkedArtifactInvariant("platform-required app const was not exported by the app artifact", .{});
}

fn topLevelDefSourceName(
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    def: TypedCIR.Def,
) Allocator.Error!?canonical.ExportNameId {
    const ident = topLevelDefSourceIdent(def) orelse return null;
    return try names.internExportIdent(module.identStoreConst(), ident);
}

fn topLevelDefSourceIdent(def: TypedCIR.Def) ?base.Ident.Idx {
    return if (def.pattern.data == .assign) def.pattern.data.assign.ident else null;
}

fn publishProvidesMetadata(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
) Allocator.Error![]ProvidesEntry {
    const module_env = module.moduleEnvConst();
    const source = module_env.provides_entries.items.items;
    var provides = std.ArrayList(ProvidesEntry).empty;
    errdefer provides.deinit(allocator);

    for (source) |entry| {
        const def = entry.local_def orelse continue;
        try provides.append(allocator, .{
            .source_name = try names.internExportIdent(module_env.getIdentStoreConst(), entry.ident),
            .ffi_symbol = try names.internExternalSymbolName(module_env.getString(entry.ffi_symbol)),
            .def = def,
        });
    }

    return provides.toOwnedSlice(allocator);
}

fn publishRequiresMetadata(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
) Allocator.Error![]RequiresEntry {
    const source = module.requiresTypes();
    const requires = try allocator.alloc(RequiresEntry, source.len);
    errdefer allocator.free(requires);

    for (source, 0..) |entry, i| {
        requires[i] = .{
            .platform_name = try names.internExportIdent(module.identStoreConst(), entry.ident),
            .declared_source_ty = try canonical_type_keys.schemeFromVar(
                allocator,
                module.typeStoreConst(),
                module.moduleEnvConst(),
                ModuleEnv.varFrom(entry.type_anno),
            ),
        };
    }

    return requires;
}

/// Public `BoxPayloadCapabilityId` declaration.
pub const BoxPayloadCapabilityId = enum(u32) { _ };
/// Public `OpaqueAtomicProofId` declaration.
pub const OpaqueAtomicProofId = enum(u32) { _ };
/// Public `HostedRepresentationCapabilityId` declaration.
pub const HostedRepresentationCapabilityId = enum(u32) { _ };
/// Public `PlatformRepresentationCapabilityId` declaration.
pub const PlatformRepresentationCapabilityId = enum(u32) { _ };
/// Public `ExportedNominalRepresentationId` declaration.
pub const ExportedNominalRepresentationId = enum(u32) { _ };

/// Public `BoxPayloadCapabilityEntry` declaration.
pub const BoxPayloadCapabilityEntry = struct {
    id: BoxPayloadCapabilityId,
    nominal: canonical.NominalTypeKey,
    source_ty_payload: CheckedTypeId,
    source_ty: canonical.CanonicalTypeKey,
    backing_ty: CheckedTypeId,
    backing_ty_key: canonical.CanonicalTypeKey,
    /// Range into `ModuleInterfaceCapabilities.args_pool` (transform B).
    args_start: u32 = 0,
    args_len: u32 = 0,
    /// Range into `ModuleInterfaceCapabilities.padding_pool` for this instance's
    /// unnamed padding field types, instantiated with its type arguments (in
    /// declared order). Empty for nominals with no unnamed fields.
    padding_start: u32 = 0,
    padding_len: u32 = 0,
    is_opaque: bool,

    /// This entry's instantiated padding field types within `caps.padding_pool`.
    pub fn paddingFieldTys(self: BoxPayloadCapabilityEntry, caps: *const ModuleInterfaceCapabilities) []const CheckedTypeId {
        return caps.padding_pool[self.padding_start .. self.padding_start + self.padding_len];
    }
};

/// Public `OpaqueAtomicProofEntry` declaration.
pub const OpaqueAtomicProofEntry = struct {
    id: OpaqueAtomicProofId,
    nominal: canonical.NominalTypeKey,
    source_ty_payload: CheckedTypeId,
    source_ty: canonical.CanonicalTypeKey,
    /// Range into `ModuleInterfaceCapabilities.args_pool` (transform B).
    args_start: u32 = 0,
    args_len: u32 = 0,
};

/// Public `HostedRepresentationCapability` declaration.
pub const HostedRepresentationCapability = struct {
    id: HostedRepresentationCapabilityId,
    external_symbol_name: canonical.ExternalSymbolNameId,
    proc: canonical.ProcedureValueRef,
    template: canonical.ProcedureTemplateRef,
    host_checked_fn_root: CheckedTypeId,
};

/// Public `PlatformRepresentationCapability` declaration.
pub const PlatformRepresentationCapability = struct {
    id: PlatformRepresentationCapabilityId,
    requirement: PlatformRequiredDeclarationId,
    platform_name: canonical.ExportNameId,
    declared_source_ty: canonical.CanonicalTypeSchemeKey,
};

/// Public `ExportedNominalRepresentation` declaration.
pub const ExportedNominalRepresentation = struct {
    id: ExportedNominalRepresentationId,
    nominal: canonical.NominalTypeKey,
    source_ty: canonical.CanonicalTypeKey,
    box_payload_capability: BoxPayloadCapabilityId,
    opaque_atomic_proof: ?OpaqueAtomicProofId = null,
};

/// Public `ModuleInterfaceCapabilities` declaration.
pub const ModuleInterfaceCapabilities = struct {
    boxed_payload_templates: []const BoxPayloadCapabilityEntry = &.{},
    opaque_atomic_proofs: []const OpaqueAtomicProofEntry = &.{},
    hosted_representations: []const HostedRepresentationCapability = &.{},
    platform_representations: []const PlatformRepresentationCapability = &.{},
    exported_nominal_representations: []const ExportedNominalRepresentation = &.{},
    /// Shared flat pool of instantiated type args referenced by box/opaque
    /// entries' `(args_start, args_len)` ranges (transform-B side list).
    args_pool: []const canonical.CanonicalTypeKey = &.{},
    /// Shared flat pool of instantiated padding field types referenced by box
    /// entries' `(padding_start, padding_len)` ranges.
    padding_pool: []const CheckedTypeId = &.{},

    pub const Serialized = extern struct {
        boxed_payload_templates: SerializedSlice(BoxPayloadCapabilityEntry) = .{},
        opaque_atomic_proofs: SerializedSlice(OpaqueAtomicProofEntry) = .{},
        hosted_representations: SerializedSlice(HostedRepresentationCapability) = .{},
        platform_representations: SerializedSlice(PlatformRepresentationCapability) = .{},
        exported_nominal_representations: SerializedSlice(ExportedNominalRepresentation) = .{},
        args_pool: SerializedSlice(canonical.CanonicalTypeKey) = .{},
        padding_pool: SerializedSlice(CheckedTypeId) = .{},
        const Serde = artifact_serialize.SliceStoreSerde(ModuleInterfaceCapabilities, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    pub fn fromModule(
        allocator: Allocator,
        module: TypedCIR.Module,
        checked_types: *CheckedTypeStore,
        hosted_procs: *const HostedProcTable,
        checked_procedure_templates: *const CheckedProcedureTemplateTable,
        platform_required_declarations: *const PlatformRequiredDeclarationTable,
        names: *const canonical.CanonicalNameStore,
    ) Allocator.Error!ModuleInterfaceCapabilities {
        const current_module_hash = module.moduleEnvConst().contentIdentityHash() orelse {
            if (builtin.mode == .Debug) {
                std.debug.panic("checked artifact invariant violated: module content identity missing during interface capability publication", .{});
            }
            unreachable;
        };
        const current_module = names.lookupModuleIdentity(current_module_hash) orelse {
            if (builtin.mode == .Debug) {
                std.debug.panic("checked artifact invariant violated: module identity was not interned before interface capability publication", .{});
            }
            unreachable;
        };

        var boxed_payload_templates = std.ArrayList(BoxPayloadCapabilityEntry).empty;
        errdefer boxed_payload_templates.deinit(allocator);
        var opaque_atomic_proofs = std.ArrayList(OpaqueAtomicProofEntry).empty;
        errdefer opaque_atomic_proofs.deinit(allocator);
        var exported_nominal_representations = std.ArrayList(ExportedNominalRepresentation).empty;
        errdefer exported_nominal_representations.deinit(allocator);
        // Shared pool of instantiated args; box + opaque entries reference ranges.
        var args_pool = std.ArrayList(canonical.CanonicalTypeKey).empty;
        errdefer args_pool.deinit(allocator);
        // Shared pool of instantiated padding field types; box entries reference ranges.
        var padding_pool = std.ArrayList(CheckedTypeId).empty;
        errdefer padding_pool.deinit(allocator);

        var seen_nominals = std.AutoHashMap(NominalCapabilitySeenKey, void).init(allocator);
        defer seen_nominals.deinit();

        const published_payload_count = checked_types.payloads.items.len;
        var i: usize = 0;
        while (i < published_payload_count) : (i += 1) {
            const payload = checked_types.payload(@enumFromInt(@as(u32, @intCast(i))));
            if (payload != .nominal) continue;
            const nominal = payload.nominal;
            if (nominal.builtin != null) continue;
            if (nominal.origin_module != current_module) continue;
            const source_key = checked_types.roots.items[i].key;
            const nominal_key = canonical.NominalTypeKey{
                .module = nominal.origin_module,
                .type_name = nominal.name,
                .source_decl = nominal.source_decl,
            };
            const seen_key = NominalCapabilitySeenKey{
                .source_ty = source_key,
                .nominal = nominal_key,
            };
            if (seen_nominals.contains(seen_key)) continue;
            try seen_nominals.put(seen_key, {});

            // nominal.args aliases type_id_pool; copy before any pool growth.
            const nominal_args = try allocator.dupe(CheckedTypeId, nominal.args);
            defer allocator.free(nominal_args);

            const args = try checkedTypeKeysForIds(allocator, checked_types, nominal_args);
            defer allocator.free(args);
            const args_start: u32 = @intCast(args_pool.items.len);
            const args_len: u32 = @intCast(args.len);
            try args_pool.appendSlice(allocator, args);

            const declaration = checked_types.nominalDeclaration(nominal_key) orelse {
                checkedArtifactInvariant("nominal representation publication could not find the checked nominal declaration", .{});
            };
            const backing_ty = try checked_types.ensureInstantiatedNominalBackingRoot(
                allocator,
                names,
                declaration,
                nominal_args,
            );
            const padding_field_tys = try checked_types.ensureInstantiatedPaddingFieldTypes(
                allocator,
                names,
                declaration,
                nominal_args,
            );
            defer allocator.free(padding_field_tys);
            const padding_start: u32 = @intCast(padding_pool.items.len);
            const padding_len: u32 = @intCast(padding_field_tys.len);
            try padding_pool.appendSlice(allocator, padding_field_tys);

            const capability_id: BoxPayloadCapabilityId = @enumFromInt(@as(u32, @intCast(boxed_payload_templates.items.len)));
            try boxed_payload_templates.append(allocator, .{
                .id = capability_id,
                .nominal = nominal_key,
                .source_ty_payload = checked_types.roots.items[i].id,
                .source_ty = source_key,
                .backing_ty = backing_ty,
                .backing_ty_key = checkedTypeKeyForId(checked_types, backing_ty),
                .args_start = args_start,
                .args_len = args_len,
                .padding_start = padding_start,
                .padding_len = padding_len,
                .is_opaque = nominal.is_opaque,
            });

            const proof_id: ?OpaqueAtomicProofId = blk: {
                if (!nominal.is_opaque) break :blk null;
                if (!try checkedTypeHasNoReachableCallableSlots(allocator, checked_types, backing_ty)) break :blk null;

                // Reuse the boxed entry's args range (same pool).
                const id: OpaqueAtomicProofId = @enumFromInt(@as(u32, @intCast(opaque_atomic_proofs.items.len)));
                try opaque_atomic_proofs.append(allocator, .{
                    .id = id,
                    .nominal = nominal_key,
                    .source_ty_payload = checked_types.roots.items[i].id,
                    .source_ty = source_key,
                    .args_start = args_start,
                    .args_len = args_len,
                });
                break :blk id;
            };

            checked_types.setNominalRepresentation(@enumFromInt(@as(u32, @intCast(i))), .{ .local_box_payload_capability = .{
                .capability = capability_id,
                .opaque_atomic_proof = proof_id,
            } });

            const exported_id: ExportedNominalRepresentationId = @enumFromInt(@as(u32, @intCast(exported_nominal_representations.items.len)));
            try exported_nominal_representations.append(allocator, .{
                .id = exported_id,
                .nominal = nominal_key,
                .source_ty = source_key,
                .box_payload_capability = capability_id,
                .opaque_atomic_proof = proof_id,
            });
        }

        const hosted_representations = try allocator.alloc(HostedRepresentationCapability, hosted_procs.procs.len);
        errdefer allocator.free(hosted_representations);
        for (hosted_procs.procs, 0..) |hosted, hosted_index| {
            const template = checked_procedure_templates.get(hosted.template.template);
            if (template.target != .hosted) {
                checkedArtifactInvariant("hosted representation capability referenced a non-hosted procedure template", .{});
            }
            hosted_representations[hosted_index] = .{
                .id = @enumFromInt(@as(u32, @intCast(hosted_index))),
                .external_symbol_name = hosted.external_symbol_name,
                .proc = hosted.proc,
                .template = hosted.template,
                .host_checked_fn_root = template.checked_fn_root,
            };
        }

        const platform_representations = try allocator.alloc(PlatformRepresentationCapability, platform_required_declarations.declarations.len);
        errdefer allocator.free(platform_representations);
        for (platform_required_declarations.declarations, 0..) |declaration, platform_index| {
            platform_representations[platform_index] = .{
                .id = @enumFromInt(@as(u32, @intCast(platform_index))),
                .requirement = declaration.id,
                .platform_name = declaration.platform_name,
                .declared_source_ty = declaration.declared_source_ty,
            };
        }

        return .{
            .boxed_payload_templates = try boxed_payload_templates.toOwnedSlice(allocator),
            .opaque_atomic_proofs = try opaque_atomic_proofs.toOwnedSlice(allocator),
            .hosted_representations = hosted_representations,
            .platform_representations = platform_representations,
            .exported_nominal_representations = try exported_nominal_representations.toOwnedSlice(allocator),
            .args_pool = try args_pool.toOwnedSlice(allocator),
            .padding_pool = try padding_pool.toOwnedSlice(allocator),
        };
    }

    pub fn deinit(self: *ModuleInterfaceCapabilities, allocator: Allocator) void {
        freeConstSlice(allocator, self.boxed_payload_templates);
        freeConstSlice(allocator, self.opaque_atomic_proofs);
        freeConstSlice(allocator, self.hosted_representations);
        freeConstSlice(allocator, self.platform_representations);
        freeConstSlice(allocator, self.exported_nominal_representations);
        freeConstSlice(allocator, self.args_pool);
        freeConstSlice(allocator, self.padding_pool);
        self.* = .{};
    }

    pub fn boxPayloadCapability(
        self: *const ModuleInterfaceCapabilities,
        id: BoxPayloadCapabilityId,
    ) BoxPayloadCapabilityEntry {
        const index: usize = @intFromEnum(id);
        if (index >= self.boxed_payload_templates.len) {
            checkedArtifactInvariant("interface capability lookup referenced missing boxed payload capability", .{});
        }
        return self.boxed_payload_templates[index];
    }

    pub fn opaqueAtomicProof(
        self: *const ModuleInterfaceCapabilities,
        id: OpaqueAtomicProofId,
    ) OpaqueAtomicProofEntry {
        const index: usize = @intFromEnum(id);
        if (index >= self.opaque_atomic_proofs.len) {
            checkedArtifactInvariant("interface capability lookup referenced missing opaque atomic proof", .{});
        }
        return self.opaque_atomic_proofs[index];
    }

    pub fn verifyComplete(self: *const ModuleInterfaceCapabilities) void {
        if (builtin.mode != .Debug) return;

        for (self.boxed_payload_templates, 0..) |entry, i| {
            std.debug.assert(@intFromEnum(entry.id) == i);
            if (entry.is_opaque) {
                for (self.exported_nominal_representations) |representation| {
                    if (representation.box_payload_capability == entry.id) break;
                } else {
                    std.debug.panic("checked artifact invariant violated: opaque boxed-payload capability has no nominal representation row", .{});
                }
            }
        }
        for (self.opaque_atomic_proofs, 0..) |entry, i| {
            std.debug.assert(@intFromEnum(entry.id) == i);
        }
        for (self.hosted_representations, 0..) |entry, i| {
            std.debug.assert(@intFromEnum(entry.id) == i);
        }
        for (self.platform_representations, 0..) |entry, i| {
            std.debug.assert(@intFromEnum(entry.id) == i);
        }
        for (self.exported_nominal_representations, 0..) |entry, i| {
            std.debug.assert(@intFromEnum(entry.id) == i);
            const capability_index: usize = @intFromEnum(entry.box_payload_capability);
            if (capability_index >= self.boxed_payload_templates.len) {
                std.debug.panic("checked artifact invariant violated: nominal representation references missing boxed-payload capability", .{});
            }
            const capability = self.boxed_payload_templates[capability_index];
            if (!canonicalNominalTypeKeyEql(entry.nominal, capability.nominal) or
                !canonicalTypeKeyEql(entry.source_ty, capability.source_ty))
            {
                std.debug.panic("checked artifact invariant violated: nominal representation disagrees with boxed-payload capability identity", .{});
            }
            if (entry.opaque_atomic_proof) |proof| {
                const proof_index: usize = @intFromEnum(proof);
                if (proof_index >= self.opaque_atomic_proofs.len) {
                    std.debug.panic("checked artifact invariant violated: nominal representation references missing opaque atomic proof", .{});
                }
                const proof_entry = self.opaque_atomic_proofs[proof_index];
                if (!canonicalNominalTypeKeyEql(entry.nominal, proof_entry.nominal) or
                    !canonicalTypeKeyEql(entry.source_ty, proof_entry.source_ty))
                {
                    std.debug.panic("checked artifact invariant violated: nominal representation disagrees with opaque atomic proof identity", .{});
                }
            }
        }
    }
};

const NominalCapabilitySeenKey = struct {
    source_ty: canonical.CanonicalTypeKey,
    nominal: canonical.NominalTypeKey,
};

fn canonicalTypeKeyEql(a: canonical.CanonicalTypeKey, b: canonical.CanonicalTypeKey) bool {
    return std.meta.eql(a.bytes, b.bytes);
}

fn canonicalNominalTypeKeyEql(a: canonical.NominalTypeKey, b: canonical.NominalTypeKey) bool {
    return a.module == b.module and a.type_name == b.type_name and a.source_decl == b.source_decl;
}

fn testCanonicalTypeKey(byte: u8) canonical.CanonicalTypeKey {
    if (!builtin.is_test) unreachable;

    var key = canonical.CanonicalTypeKey{};
    key.bytes[0] = byte;
    return key;
}

fn testCheckedModuleKey(byte: u8) CheckedModuleArtifactKey {
    if (!builtin.is_test) unreachable;

    var key = CheckedModuleArtifactKey{};
    key.bytes[0] = byte;
    return key;
}

fn checkedTypeKeyForId(
    checked_types: *const CheckedTypeStore,
    id: CheckedTypeId,
) canonical.CanonicalTypeKey {
    const index: usize = @intFromEnum(id);
    if (index >= checked_types.roots.items.len) {
        checkedArtifactInvariant("checked type key lookup referenced a missing root", .{});
    }
    return checked_types.roots.items[index].key;
}

fn checkedTypeKeysForIds(
    allocator: Allocator,
    checked_types: *const CheckedTypeStore,
    ids: []const CheckedTypeId,
) Allocator.Error![]const canonical.CanonicalTypeKey {
    if (ids.len == 0) return &.{};
    const out = try allocator.alloc(canonical.CanonicalTypeKey, ids.len);
    errdefer allocator.free(out);
    for (ids, 0..) |id, i| {
        out[i] = checkedTypeKeyForId(checked_types, id);
    }
    return out;
}

fn checkedTypeHasNoReachableCallableSlots(
    allocator: Allocator,
    checked_types: *const CheckedTypeStore,
    root: CheckedTypeId,
) Allocator.Error!bool {
    var active = collections.DenseMap(CheckedTypeId, void).init(allocator);
    defer active.deinit();
    return try checkedTypeHasNoReachableCallableSlotsInner(checked_types, root, &active);
}

fn checkedTypeHasNoReachableCallableSlotsInner(
    checked_types: *const CheckedTypeStore,
    root: CheckedTypeId,
    active: *collections.DenseMap(CheckedTypeId, void),
) Allocator.Error!bool {
    const index: usize = @intFromEnum(root);
    if (index >= checked_types.payloads.items.len) {
        checkedArtifactInvariant("callable-slot proof referenced a missing checked type", .{});
    }
    if (active.contains(root)) return true;
    try active.put(root, {});
    defer _ = active.remove(root);

    return switch (checked_types.payload(@enumFromInt(index))) {
        .pending => checkedArtifactInvariant("callable-slot proof reached pending checked type", .{}),
        .err => true,
        .flex,
        .rigid,
        .function,
        => false,
        .empty_record,
        .empty_tag_union,
        => true,
        .alias => |alias| try checkedTypeHasNoReachableCallableSlotsInner(checked_types, alias.backing, active),
        .nominal => |nominal| blk: {
            if (nominal.builtin) |builtin_nominal| {
                switch (builtin_nominal) {
                    .str,
                    .u8,
                    .i8,
                    .u16,
                    .i16,
                    .u32,
                    .i32,
                    .u64,
                    .i64,
                    .u128,
                    .i128,
                    .f32,
                    .f64,
                    .dec,
                    .u8x16,
                    .i8x16,
                    .u16x8,
                    .i16x8,
                    .u32x4,
                    .i32x4,
                    .u64x2,
                    .i64x2,
                    .bool,
                    .parse_tag_union_spec,
                    .fields,
                    .field,
                    .crypto_sha256_digest,
                    .crypto_sha256_hasher,
                    .crypto_blake3_digest,
                    .crypto_blake3_hasher,
                    => break :blk true,
                    .list,
                    .box,
                    => {
                        if (nominal.args.len != 1) checkedArtifactInvariant("builtin container nominal had non-unary args", .{});
                        break :blk try checkedTypeHasNoReachableCallableSlotsInner(checked_types, nominal.args[0], active);
                    },
                    .try_ => {
                        if (nominal.args.len != 2) checkedArtifactInvariant("builtin Try nominal had non-binary args", .{});
                        if (!try checkedTypeHasNoReachableCallableSlotsInner(checked_types, nominal.args[0], active)) break :blk false;
                        break :blk try checkedTypeHasNoReachableCallableSlotsInner(checked_types, nominal.args[1], active);
                    },
                    .set => {
                        if (nominal.args.len != 1) checkedArtifactInvariant("builtin Set nominal had non-unary args", .{});
                        break :blk try checkedTypeHasNoReachableCallableSlotsInner(checked_types, nominal.args[0], active);
                    },
                    .dict => {
                        if (nominal.args.len != 2) checkedArtifactInvariant("builtin Dict nominal had non-binary args", .{});
                        if (!try checkedTypeHasNoReachableCallableSlotsInner(checked_types, nominal.args[0], active)) break :blk false;
                        break :blk try checkedTypeHasNoReachableCallableSlotsInner(checked_types, nominal.args[1], active);
                    },
                    .iter => {
                        const backing = checked_types.nominalBackingTemplateForPayload(nominal) orelse break :blk true;
                        break :blk try checkedTypeHasNoReachableCallableSlotsInner(checked_types, backing, active);
                    },
                }
            }
            const backing = checked_types.nominalBackingTemplateForPayload(nominal) orelse break :blk true;
            break :blk try checkedTypeHasNoReachableCallableSlotsInner(checked_types, backing, active);
        },
        .record => |record| blk: {
            if (!try checkedRecordHasNoReachableCallableSlots(checked_types, record.fields, active)) break :blk false;
            break :blk try checkedTypeHasNoReachableCallableSlotsInner(checked_types, record.ext, active);
        },
        .record_unbound => |fields| try checkedRecordHasNoReachableCallableSlots(checked_types, fields, active),
        .tuple => |items| try checkedTypeSpanHasNoReachableCallableSlots(checked_types, items, active),
        .tag_union => |tag_union| blk: {
            if (!try checkedTagsHaveNoReachableCallableSlots(checked_types, tag_union.tags, active)) break :blk false;
            break :blk try checkedTypeHasNoReachableCallableSlotsInner(checked_types, tag_union.ext, active);
        },
    };
}

fn checkedRecordHasNoReachableCallableSlots(
    checked_types: *const CheckedTypeStore,
    fields: []const CheckedRecordField,
    active: *collections.DenseMap(CheckedTypeId, void),
) Allocator.Error!bool {
    for (fields) |field| {
        if (!try checkedTypeHasNoReachableCallableSlotsInner(checked_types, field.ty, active)) return false;
    }
    return true;
}

fn checkedTypeSpanHasNoReachableCallableSlots(
    checked_types: *const CheckedTypeStore,
    items: []const CheckedTypeId,
    active: *collections.DenseMap(CheckedTypeId, void),
) Allocator.Error!bool {
    for (items) |item| {
        if (!try checkedTypeHasNoReachableCallableSlotsInner(checked_types, item, active)) return false;
    }
    return true;
}

fn checkedTagsHaveNoReachableCallableSlots(
    checked_types: *const CheckedTypeStore,
    tags: []const CheckedTag,
    active: *collections.DenseMap(CheckedTypeId, void),
) Allocator.Error!bool {
    for (tags) |tag| {
        if (!try checkedTypeSpanHasNoReachableCallableSlots(checked_types, tag.argsSlice(checked_types), active)) return false;
    }
    return true;
}

/// Public `ComptimeRootId` declaration.
pub const ComptimeRootId = enum(u32) { _ };

/// Public `CompileTimeRootKind` declaration.
pub const CompileTimeRootKind = enum {
    /// Ordinary top-level value constant.
    constant,
    /// A selected top-level-equivalent expression inside a runtime body.
    hoisted_constant,
    callable_binding,
    expect,
    /// A `from_numeral` conversion of a numeric literal whose target is a
    /// non-builtin nominal type. The root body evaluates the dispatch call's
    /// `Try` result; finalization unwraps `Ok` into the stored constant and
    /// reports `Err(InvalidNumeral(..))` as a checking problem.
    numeral_conversion,
    /// A `from_quote` conversion of a string literal whose target is a
    /// non-builtin nominal type; works exactly like `numeral_conversion` with
    /// `Err(BadQuotedBytes(..))` reported as the checking problem.
    quote_conversion,
    /// A record field default (`a : U8 ?? expr`, design.md "Defaulted
    /// Fields"): the declaring module evaluates the pure default once, and
    /// construction sites—local and cross-module—restore the archived
    /// constant instead of re-lowering the expression.
    field_default,
};

/// A field-default root can also own the checked literal conversion for its
/// body. In that case its wrapper returns the conversion's `Try` and
/// finalization archives the `Ok` payload as the field default constant.
pub const CompileTimeLiteralConversionKind = enum(u8) {
    numeral,
    quote,
};

/// Public `CompileTimeRootPayload` declaration.
pub const CompileTimeRootPayload = union(enum) {
    pending,
    const_node: ConstNodeId,
    fn_value: ConstFnId,
    expect,
};

/// Whether a selected compile-time root may become a root request.
pub const CompileTimeRootRequestEligibility = enum(u8) {
    pending,
    eligible,
    ineligible,
};

/// Public `CompileTimeRoot` declaration.
pub const CompileTimeRoot = struct {
    id: ComptimeRootId,
    module_idx: u32,
    kind: CompileTimeRootKind,
    source: RootSource,
    source_pattern: ?CIR.Pattern.Idx = null,
    hoisted_body: ?hoist_roots.Body = null,
    pattern: ?CheckedPatternId,
    expr: CheckedExprId,
    checked_type: CheckedTypeId,
    literal_conversion: ?CompileTimeLiteralConversionKind = null,
    request_eligibility: CompileTimeRootRequestEligibility,
    payload: CompileTimeRootPayload,

    pub fn literalConversionKind(self: CompileTimeRoot) ?CompileTimeLiteralConversionKind {
        return switch (self.kind) {
            .numeral_conversion => .numeral,
            .quote_conversion => .quote,
            .field_default => self.literal_conversion,
            .constant, .hoisted_constant, .callable_binding, .expect => null,
        };
    }
};

fn topLevelDefHasValueImplementation(
    module: TypedCIR.Module,
    names: *canonical.CanonicalNameStore,
    global_value_defs: []const CIR.Def.Idx,
    source_name: canonical.ExportNameId,
) Allocator.Error!bool {
    for (global_value_defs) |other_def_idx| {
        const other_def = module.def(other_def_idx);
        if (other_def.expr.data == .e_anno_only) continue;
        const other_name = (try topLevelDefSourceName(module, names, other_def)) orelse continue;
        if (other_name == source_name) return true;
    }
    return false;
}

/// Public `CompileTimeRootTable` declaration.
///
/// This is the durable compile-time root schedule and payload table. It stores
/// root identities and selected root bodies only; it deliberately does not
/// store dependency edges, readiness state, request membership caches, or
/// per-expression/per-pattern hoistability facts. Ordinary top-level roots are
/// published first in canonical order, then sparse selected hoisted roots are
/// appended in checker-selected dependency-first order. Finalization consumes
/// the sorted request stream and validates this order with temporary scratch.
pub const CompileTimeRootTable = struct {
    roots: []CompileTimeRoot = &.{},

    pub const Serialized = extern struct {
        roots: SerializedSlice(CompileTimeRoot) = .{},
        const Serde = artifact_serialize.SliceStoreSerde(CompileTimeRootTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    pub fn fromModule(
        allocator: Allocator,
        module: TypedCIR.Module,
        names: *canonical.CanonicalNameStore,
        global_value_defs: []const CIR.Def.Idx,
        selected_hoisted_roots: []const hoist_roots.SelectedHoistedRoot,
        checked_types: *const CheckedTypePublication,
        checked_body_builder: *CheckedBodyStoreBuilder,
        procedure_templates: *const CheckedProcedureTemplateTable,
    ) Allocator.Error!CompileTimeRootTable {
        const checked_bodies = checked_body_builder.storePtr();
        var roots = std.ArrayList(CompileTimeRoot).empty;
        errdefer {
            deinitCompileTimeRootSlice(allocator, roots.items);
            roots.deinit(allocator);
        }

        var field_default_root_by_expr = std.AutoHashMapUnmanaged(CheckedExprId, usize){};
        defer field_default_root_by_expr.deinit(allocator);

        // Every archived field default is a compile-time constant root
        // (design.md "Defaulted Fields"): the declaring module evaluates the
        // pure default once, and construction sites—local and
        // cross-module—restore the archived constant. Registered FIRST:
        // defaults are closed literals with no dependencies (literals-only
        // rule), and derived parsers restore them from within OTHER roots'
        // compile-time evaluation, so every default must finalize before
        // any ordinary root evaluates.
        for (checked_bodies.default_exprs.items) |entry| {
            try appendCompileTimeRoot(&roots, allocator, .{
                .module_idx = module.moduleIndex(),
                .kind = .field_default,
                .source = .{ .expr = @enumFromInt(entry.expr_node) },
                .pattern = null,
                .expr = entry.checked_expr,
                .checked_type = checked_bodies.expr(entry.checked_expr).ty,
                .payload = .pending,
            });
            const inserted = try field_default_root_by_expr.getOrPut(allocator, entry.checked_expr);
            if (inserted.found_existing) {
                checkedArtifactInvariant("field default expression was registered as more than one root", .{});
            }
            inserted.value_ptr.* = roots.items.len - 1;
        }

        var seen_source_names = std.AutoHashMapUnmanaged(canonical.ExportNameId, void){};
        defer seen_source_names.deinit(allocator);

        const module_env = module.moduleEnvConst();
        for (global_value_defs) |def_idx| {
            const def = module.def(def_idx);
            if (topLevelDefSourceIdent(def) == null) continue;
            if (procedure_templates.lookupByDef(def_idx) != null) continue;

            const source_name = try topLevelDefSourceName(module, names, def) orelse continue;
            if (def.expr.data == .e_anno_only and try topLevelDefHasValueImplementation(module, names, global_value_defs, source_name)) continue;
            const seen_source_name = try seen_source_names.getOrPut(allocator, source_name);
            if (seen_source_name.found_existing) continue;
            seen_source_name.value_ptr.* = {};

            const source_ty = module.defType(def_idx);
            if (sourceTypeIsFunction(module, source_ty)) {
                try appendCompileTimeRoot(&roots, allocator, .{
                    .module_idx = module.moduleIndex(),
                    .kind = .callable_binding,
                    .source = .{ .def = def_idx },
                    .pattern = checkedPatternIdForSource(checked_bodies, def.pattern.idx),
                    .expr = checkedExprIdForSource(checked_bodies, def.expr.idx),
                    .checked_type = try checkedTypeIdForVar(allocator, module, checked_types, source_ty),
                    .payload = .pending,
                });
            } else {
                try appendCompileTimeRoot(&roots, allocator, .{
                    .module_idx = module.moduleIndex(),
                    .kind = .constant,
                    .source = .{ .def = def_idx },
                    .pattern = checkedPatternIdForSource(checked_bodies, def.pattern.idx),
                    .expr = checkedExprIdForSource(checked_bodies, def.expr.idx),
                    .checked_type = try checkedTypeIdForVar(allocator, module, checked_types, source_ty),
                    .payload = .pending,
                });
            }
        }

        for (selected_hoisted_roots, 0..) |selected, selected_index| {
            const source_ty = if (selected.pattern) |pattern|
                ModuleEnv.varFrom(pattern)
            else
                module.exprType(selected.expr);
            if (sourceTypeIsFunction(module, source_ty)) {
                checkedArtifactInvariant("function-typed selected hoisted root reached data-constant publication", .{});
            }
            const checked_expr = try checkedExprIdForSelectedHoistedRoot(
                allocator,
                module,
                checked_types,
                checked_body_builder,
                @intCast(selected_index),
                selected,
            );
            const hoisted_body = try hoist_roots.cloneBody(allocator, selected.body);
            try appendCompileTimeRoot(&roots, allocator, .{
                .module_idx = module.moduleIndex(),
                .kind = .hoisted_constant,
                .source = .{ .hoisted = .{
                    .index = @intCast(selected_index),
                    .expr = selected.expr,
                } },
                .source_pattern = selected.pattern,
                .hoisted_body = hoisted_body,
                .pattern = if (selected.pattern) |pattern| checkedPatternIdForSource(checked_bodies, pattern) else null,
                .expr = checked_expr,
                .checked_type = try checkedTypeIdForVar(allocator, module, checked_types, source_ty),
                .payload = .pending,
            });
        }

        for (module_env.store.literalDispatchPlans()) |numeral_plan| {
            if (numeral_plan.dispatchKind() != .numeral) continue;
            switch (numeral_plan.dispatchResolution()) {
                .builtin_direct, .specialization_dispatch, .checked_error => continue,
                .custom_dispatch => {},
                .unresolved => checkedArtifactInvariant(
                    "unresolved numeral dispatch reached compile-time root publication",
                    .{},
                ),
            }
            const checked_expr = checked_bodies.exprIdAtRawNode(numeral_plan.node_idx) orelse
                checked_bodies.numeralConversionExprAtRawNode(numeral_plan.node_idx) orelse
                continue;
            if (checked_bodies.expr(checked_expr).data != .numeral) continue;
            const fn_ty = try checkedTypeIdForVar(allocator, module, checked_types, @enumFromInt(numeral_plan.fn_var));
            const fn_payload = checked_types.store.payload(fn_ty);
            if (fn_payload != .function) {
                checkedArtifactInvariant("from_numeral dispatch plan type was not a function", .{});
            }
            const try_ty = fn_payload.function.ret;
            const expr_idx: CIR.Expr.Idx = @enumFromInt(numeral_plan.node_idx);
            if (field_default_root_by_expr.get(checked_expr)) |root_index| {
                roots.items[root_index].checked_type = try_ty;
                roots.items[root_index].literal_conversion = .numeral;
                continue;
            }
            try appendCompileTimeRoot(&roots, allocator, .{
                .module_idx = module.moduleIndex(),
                .kind = .numeral_conversion,
                .source = .{ .expr = expr_idx },
                .pattern = null,
                .expr = checked_expr,
                .checked_type = try_ty,
                .payload = .pending,
            });
        }

        for (module_env.store.literalDispatchPlans()) |quote_plan| {
            if (quote_plan.dispatchKind() != .quote) continue;
            switch (quote_plan.dispatchResolution()) {
                .builtin_direct, .specialization_dispatch, .checked_error => continue,
                .custom_dispatch => {},
                .unresolved => checkedArtifactInvariant(
                    "unresolved quote dispatch reached compile-time root publication",
                    .{},
                ),
            }
            const checked_expr = checked_bodies.exprIdAtRawNode(quote_plan.node_idx) orelse
                checked_bodies.numeralConversionExprAtRawNode(quote_plan.node_idx) orelse
                continue;
            if (checked_bodies.expr(checked_expr).data != .str_from_quote) continue;
            const fn_ty = try checkedTypeIdForVar(allocator, module, checked_types, @enumFromInt(quote_plan.fn_var));
            const fn_payload = checked_types.store.payload(fn_ty);
            if (fn_payload != .function) {
                checkedArtifactInvariant("from_quote dispatch plan type was not a function", .{});
            }
            const try_ty = fn_payload.function.ret;
            const expr_idx: CIR.Expr.Idx = @enumFromInt(quote_plan.node_idx);
            if (field_default_root_by_expr.get(checked_expr)) |root_index| {
                roots.items[root_index].checked_type = try_ty;
                roots.items[root_index].literal_conversion = .quote;
                continue;
            }
            try appendCompileTimeRoot(&roots, allocator, .{
                .module_idx = module.moduleIndex(),
                .kind = .quote_conversion,
                .source = .{ .expr = expr_idx },
                .pattern = null,
                .expr = checked_expr,
                .checked_type = try_ty,
                .payload = .pending,
            });
        }

        for (module_env.store.sliceStatements(module_env.all_statements)) |statement_idx| {
            const stmt = module_env.store.getStatement(statement_idx);
            if (stmt != .s_expect) continue;
            try collectExpectRoot(
                &roots,
                allocator,
                module,
                checked_types,
                checked_bodies,
                statement_idx,
                stmt.s_expect.body,
            );
        }

        try publishCompileTimeRootRequestEligibility(allocator, checked_types, checked_bodies, roots.items);

        return .{ .roots = try roots.toOwnedSlice(allocator) };
    }

    pub fn lookupIdByPattern(self: *const CompileTimeRootTable, pattern: CheckedPatternId) ?ComptimeRootId {
        for (self.roots) |entry| {
            if (entry.pattern != null and entry.pattern.? == pattern) return entry.id;
        }
        return null;
    }

    /// Look up the field-default root (design.md "Defaulted Fields") whose
    /// body is the given checked expression.
    pub fn lookupFieldDefaultRootByExpr(self: *const CompileTimeRootTable, expr: CheckedExprId) ?CompileTimeRoot {
        for (self.roots) |entry| {
            if (entry.expr != expr) continue;
            if (entry.kind == .field_default) return entry;
        }
        return null;
    }

    /// Look up the literal-conversion (from_numeral or from_quote) root whose
    /// body is the given checked expression.
    pub fn lookupNumeralRootByExpr(self: *const CompileTimeRootTable, expr: CheckedExprId) ?CompileTimeRoot {
        for (self.roots) |entry| {
            if (entry.expr != expr) continue;
            if (entry.literalConversionKind() != null) {
                return entry;
            }
        }
        return null;
    }

    /// Look up a selected hoisted constant root by its checked source expression.
    pub fn lookupHoistedRootByExpr(self: *const CompileTimeRootTable, expr: CheckedExprId) ?CompileTimeRoot {
        for (self.roots) |entry| {
            if (entry.kind == .hoisted_constant and entry.expr == expr) return entry;
        }
        return null;
    }

    pub fn root(self: *const CompileTimeRootTable, id: ComptimeRootId) CompileTimeRoot {
        return self.roots[@intFromEnum(id)];
    }

    pub fn fillPayload(
        self: *CompileTimeRootTable,
        id: ComptimeRootId,
        payload: CompileTimeRootPayload,
    ) void {
        const index = @intFromEnum(id);
        if (index >= self.roots.len) {
            checkedArtifactInvariant("compile-time root id is out of range", .{});
        }
        verifyCompileTimeRootPayloadMatchesKind(self.roots[index].kind, payload);
        self.roots[index].payload = payload;
    }

    pub fn deinit(self: *CompileTimeRootTable, allocator: Allocator) void {
        deinitCompileTimeRootSlice(allocator, self.roots);
        allocator.free(self.roots);
        self.* = .{};
    }

    const RootWithoutId = struct {
        module_idx: u32,
        kind: CompileTimeRootKind,
        source: RootSource,
        source_pattern: ?CIR.Pattern.Idx = null,
        hoisted_body: ?hoist_roots.Body = null,
        pattern: ?CheckedPatternId,
        expr: CheckedExprId,
        checked_type: CheckedTypeId,
        request_eligibility: CompileTimeRootRequestEligibility = .pending,
        payload: CompileTimeRootPayload,
    };

    /// Collect a single `expect` statement as a standalone compile-time root, then
    /// recurse into its body when that body is a block: nested `expect` statements
    /// that appear directly in an enclosing `expect`'s block body are themselves
    /// standalone test roots (issue #9733). Crucially, we never descend into lambda
    /// bodies or into ordinary value blocks that are not an `expect`'s body, so inline
    /// assertions that close over enclosing local bindings are not over-collected.
    fn collectExpectRoot(
        roots: *std.ArrayList(CompileTimeRoot),
        allocator: Allocator,
        module: TypedCIR.Module,
        checked_types: *const CheckedTypePublication,
        checked_bodies: *const CheckedBodyStore,
        statement_idx: CIR.Statement.Idx,
        body_expr: CIR.Expr.Idx,
    ) Allocator.Error!void {
        try appendCompileTimeRoot(roots, allocator, .{
            .module_idx = module.moduleIndex(),
            .kind = .expect,
            .source = .{ .statement = statement_idx },
            .pattern = null,
            .expr = checkedExprIdForSource(checked_bodies, body_expr),
            .checked_type = try checkedTypeIdForVar(allocator, module, checked_types, ModuleEnv.varFrom(body_expr)),
            .payload = .expect,
        });

        const module_env = module.moduleEnvConst();
        const body = module_env.store.getExpr(body_expr);
        if (body != .e_block) return;
        for (module_env.store.sliceStatements(body.e_block.stmts)) |nested_idx| {
            const nested_stmt = module_env.store.getStatement(nested_idx);
            if (nested_stmt != .s_expect) continue;
            try collectExpectRoot(
                roots,
                allocator,
                module,
                checked_types,
                checked_bodies,
                nested_idx,
                nested_stmt.s_expect.body,
            );
        }
    }

    fn appendCompileTimeRoot(
        roots: *std.ArrayList(CompileTimeRoot),
        allocator: Allocator,
        entry: RootWithoutId,
    ) Allocator.Error!void {
        const id: ComptimeRootId = @enumFromInt(@as(u32, @intCast(roots.items.len)));
        roots.append(allocator, .{
            .id = id,
            .module_idx = entry.module_idx,
            .kind = entry.kind,
            .source = entry.source,
            .source_pattern = entry.source_pattern,
            .hoisted_body = entry.hoisted_body,
            .pattern = entry.pattern,
            .expr = entry.expr,
            .checked_type = entry.checked_type,
            .request_eligibility = entry.request_eligibility,
            .payload = entry.payload,
        }) catch |err| {
            if (entry.hoisted_body) |body| hoist_roots.deinitBody(allocator, body);
            return err;
        };
    }
};

fn publishCompileTimeRootRequestEligibility(
    allocator: Allocator,
    checked_types: *const CheckedTypePublication,
    checked_bodies: *const CheckedBodyStore,
    roots: []CompileTimeRoot,
) Allocator.Error!void {
    for (roots) |*root| {
        const concrete = try checkedTypeIsConcreteCompileTimeRoot(allocator, &checked_types.store, root.checked_type);
        // The checker already owns this diagnostic; evaluating the root would
        // only add a secondary compile-time crash for its replacement node.
        const eligible = concrete and !checked_bodies.exprContainsDiagnosticError(root.expr);
        root.request_eligibility = if (eligible) .eligible else .ineligible;
    }
}

fn deinitCompileTimeRootSlice(allocator: Allocator, roots: []CompileTimeRoot) void {
    for (roots) |*root| {
        if (root.hoisted_body) |body| {
            hoist_roots.deinitBody(allocator, body);
            root.hoisted_body = null;
        }
    }
}

fn verifyCompileTimeRootPayloadMatchesKind(kind: CompileTimeRootKind, payload: CompileTimeRootPayload) void {
    const matches = switch (kind) {
        .constant, .hoisted_constant => switch (payload) {
            .const_node => true,
            .pending, .fn_value, .expect => false,
        },
        .callable_binding => switch (payload) {
            // A callable initializer that reaches an explicit checked error is
            // stored as a divergent ConstStore node. Monotype restores that
            // node at the callable's expected type, so execution crashes at
            // the exact invalid binding while independent roots remain usable.
            .fn_value, .const_node => true,
            .pending, .expect => false,
        },
        .expect => switch (payload) {
            .expect => true,
            .pending, .const_node, .fn_value => false,
        },
        .numeral_conversion, .quote_conversion, .field_default => switch (payload) {
            .const_node => true,
            .pending, .fn_value, .expect => false,
        },
    };
    if (matches) return;
    checkedArtifactInvariant("compile-time root payload does not match root kind", .{});
}

fn verifyCompileTimeRootLiteralConversion(root: CompileTimeRoot) void {
    switch (root.kind) {
        .field_default => {},
        .constant,
        .hoisted_constant,
        .callable_binding,
        .expect,
        .numeral_conversion,
        .quote_conversion,
        => std.debug.assert(root.literal_conversion == null),
    }
}

fn compileTimeRootHasConstBody(kind: CompileTimeRootKind) bool {
    return switch (kind) {
        .constant, .hoisted_constant => true,
        // A field default's constant is restored by expression lookup at
        // construction sites, never exported as a named data constant.
        .callable_binding, .expect, .numeral_conversion, .quote_conversion, .field_default => false,
    };
}

const ExhaustivenessTemplateReachability = struct {
    allocator: Allocator,
    artifact_key: CheckedModuleArtifactKey,
    procedure_templates: *const CheckedProcedureTemplateTable,
    entry_wrappers: *const EntryWrapperTable,
    callable_eval_templates: *const CallableEvalTemplateTable,
    top_level_procedure_bindings: *const TopLevelProcedureBindingTable,
    platform_required_bindings: *const PlatformRequiredBindingTable,
    resolved_value_refs: *const ResolvedValueRefTable,
    runtime_templates: []bool,
    compile_time_templates: []bool,

    fn init(
        allocator: Allocator,
        artifact_key: CheckedModuleArtifactKey,
        procedure_templates: *const CheckedProcedureTemplateTable,
        entry_wrappers: *const EntryWrapperTable,
        callable_eval_templates: *const CallableEvalTemplateTable,
        top_level_procedure_bindings: *const TopLevelProcedureBindingTable,
        platform_required_bindings: *const PlatformRequiredBindingTable,
        resolved_value_refs: *const ResolvedValueRefTable,
    ) Allocator.Error!ExhaustivenessTemplateReachability {
        const runtime_templates = try allocator.alloc(bool, procedure_templates.templates.len);
        errdefer allocator.free(runtime_templates);
        const compile_time_templates = try allocator.alloc(bool, procedure_templates.templates.len);
        errdefer allocator.free(compile_time_templates);
        @memset(runtime_templates, false);
        @memset(compile_time_templates, false);
        return .{
            .allocator = allocator,
            .artifact_key = artifact_key,
            .procedure_templates = procedure_templates,
            .entry_wrappers = entry_wrappers,
            .callable_eval_templates = callable_eval_templates,
            .top_level_procedure_bindings = top_level_procedure_bindings,
            .platform_required_bindings = platform_required_bindings,
            .resolved_value_refs = resolved_value_refs,
            .runtime_templates = runtime_templates,
            .compile_time_templates = compile_time_templates,
        };
    }

    fn deinit(self: *ExhaustivenessTemplateReachability) void {
        self.allocator.free(self.compile_time_templates);
        self.allocator.free(self.runtime_templates);
        self.* = undefined;
    }

    fn build(
        allocator: Allocator,
        artifact_key: CheckedModuleArtifactKey,
        root_requests: *const RootRequestTable,
        procedure_templates: *const CheckedProcedureTemplateTable,
        entry_wrappers: *const EntryWrapperTable,
        callable_eval_templates: *const CallableEvalTemplateTable,
        top_level_procedure_bindings: *const TopLevelProcedureBindingTable,
        platform_required_bindings: *const PlatformRequiredBindingTable,
        resolved_value_refs: *const ResolvedValueRefTable,
    ) Allocator.Error!ExhaustivenessTemplateReachability {
        var reachability = try ExhaustivenessTemplateReachability.init(
            allocator,
            artifact_key,
            procedure_templates,
            entry_wrappers,
            callable_eval_templates,
            top_level_procedure_bindings,
            platform_required_bindings,
            resolved_value_refs,
        );
        errdefer reachability.deinit();

        for (root_requests.runtime_requests) |request| {
            try reachability.markRootRequest(.runtime, request);
        }
        for (root_requests.compile_time_requests) |request| {
            try reachability.markRootRequest(.compile_time, request);
        }

        return reachability;
    }

    fn templateIsRuntimeReachable(self: *const ExhaustivenessTemplateReachability, template_ref: canonical.ProcedureTemplateRef) bool {
        const idx = self.localTemplateIndex(template_ref) orelse return false;
        return self.runtime_templates[idx];
    }

    fn templateIsCompileTimeReachable(self: *const ExhaustivenessTemplateReachability, template_ref: canonical.ProcedureTemplateRef) bool {
        const idx = self.localTemplateIndex(template_ref) orelse return false;
        return self.compile_time_templates[idx];
    }

    const ReachabilityKind = enum {
        runtime,
        compile_time,
    };

    fn markRootRequest(
        self: *ExhaustivenessTemplateReachability,
        kind: ReachabilityKind,
        request: RootRequest,
    ) Allocator.Error!void {
        switch (request.source) {
            .required_binding => |binding_id| try self.markPlatformRequiredBindingClosure(kind, @enumFromInt(binding_id)),
            .def,
            .expr,
            .statement,
            .hoisted,
            => {},
        }
        if (request.procedure_template) |template_ref| {
            try self.markProcedureTemplate(kind, template_ref);
        }
        if (request.procedure_use) |procedure| {
            try self.markProcedureUse(kind, procedure);
        }
        if (request.procedure_binding) |binding| {
            try self.markTopLevelProcedureBinding(kind, .{
                .artifact = self.artifact_key,
                .binding = binding,
            });
        }
    }

    fn markProcedureTemplate(
        self: *ExhaustivenessTemplateReachability,
        kind: ReachabilityKind,
        template_ref: canonical.ProcedureTemplateRef,
    ) Allocator.Error!void {
        const idx = self.localTemplateIndex(template_ref) orelse return;
        const seen = switch (kind) {
            .runtime => &self.runtime_templates[idx],
            .compile_time => &self.compile_time_templates[idx],
        };
        if (seen.*) return;
        seen.* = true;

        const template = self.procedure_templates.templates[idx];
        if (template.proc_base != template_ref.proc_base) {
            checkedArtifactInvariant("reachable procedure template ref disagreed with template row", .{});
        }

        const end = template.resolved_value_refs.start + template.resolved_value_refs.len;
        if (end > self.resolved_value_refs.template_refs.len) {
            checkedArtifactInvariant("reachable procedure template resolved-ref span was outside table", .{});
        }
        for (self.resolved_value_refs.template_refs[template.resolved_value_refs.start..end]) |ref_id| {
            const raw = @intFromEnum(ref_id);
            if (raw >= self.resolved_value_refs.records.len) {
                checkedArtifactInvariant("reachable procedure template resolved-ref id was outside table", .{});
            }
            try self.markResolvedValueRef(kind, self.resolved_value_refs.records[raw].ref);
        }
    }

    fn markResolvedValueRef(
        self: *ExhaustivenessTemplateReachability,
        kind: ReachabilityKind,
        ref: ResolvedValueRef,
    ) Allocator.Error!void {
        switch (ref) {
            .top_level_proc,
            .hosted_proc,
            .promoted_top_level_proc,
            => |procedure| try self.markProcedureUse(kind, procedure),
            .platform_required_proc => |required| {
                try self.markProcedureUse(kind, required.procedure);
                try self.markPlatformRequiredBindingClosure(kind, required.binding);
            },
            .platform_required_const => |required| try self.markPlatformRequiredBindingClosure(kind, required.binding),
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            .selected_hoisted_const,
            .local_proc,
            .top_level_const,
            .imported_const,
            .imported_proc,
            .platform_required_declaration,
            .platform_required_checked_error,
            => {},
        }
    }

    fn markProcedureUse(
        self: *ExhaustivenessTemplateReachability,
        kind: ReachabilityKind,
        procedure: ProcedureUseTemplate,
    ) Allocator.Error!void {
        switch (procedure.binding) {
            .top_level => |top_level| try self.markTopLevelProcedureBinding(kind, top_level),
            .hosted => |hosted| try self.markProcedureTemplate(kind, hosted.template),
            .platform_required => |required| try self.markTopLevelProcedureBinding(kind, .{
                .artifact = required.artifact,
                .binding = required.procedure_binding,
            }),
            .imported => {},
        }
    }

    fn markTopLevelProcedureBinding(
        self: *ExhaustivenessTemplateReachability,
        kind: ReachabilityKind,
        binding_ref: ArtifactTopLevelProcedureBindingRef,
    ) Allocator.Error!void {
        if (!checkedArtifactKeyEql(binding_ref.artifact, self.artifact_key)) return;
        const binding = self.top_level_procedure_bindings.get(binding_ref.binding);
        try self.markProcedureBindingBody(kind, binding.body);
    }

    fn markProcedureBindingBody(
        self: *ExhaustivenessTemplateReachability,
        kind: ReachabilityKind,
        body: ProcedureBindingBody,
    ) Allocator.Error!void {
        switch (body) {
            .direct_template => |direct| try self.markCallableProcedureTemplate(kind, direct.template),
            .callable_eval_template => |template_id| try self.markCallableEvalTemplate(kind, template_id),
        }
    }

    fn markCallableEvalTemplate(
        self: *ExhaustivenessTemplateReachability,
        kind: ReachabilityKind,
        template_id: CallableEvalTemplateId,
    ) Allocator.Error!void {
        const raw = @intFromEnum(template_id);
        if (raw >= self.callable_eval_templates.templates.len) {
            checkedArtifactInvariant("reachable callable-eval template id was outside table", .{});
        }
        const template = self.callable_eval_templates.get(template_id);
        try self.markProcedureTemplate(kind, entryWrapperForRoot(self.entry_wrappers, template.root).template);
    }

    fn markPlatformRequiredBindingClosure(
        self: *ExhaustivenessTemplateReachability,
        kind: ReachabilityKind,
        binding_id: PlatformRequiredBindingId,
    ) Allocator.Error!void {
        const binding = self.platform_required_bindings.lookupByBindingId(@intFromEnum(binding_id)) orelse {
            checkedArtifactInvariant("reachable platform-required binding id was outside table", .{});
        };
        const closure = self.platform_required_bindings.relationClosure(binding);
        try self.markImportedTemplateClosure(kind, closure);
    }

    fn markImportedTemplateClosure(
        self: *ExhaustivenessTemplateReachability,
        kind: ReachabilityKind,
        closure: ImportedTemplateClosureView,
    ) Allocator.Error!void {
        for (closure.checked_procedure_templates) |template_ref| {
            try self.markProcedureTemplate(kind, template_ref);
        }
        for (closure.callable_eval_templates) |template_ref| {
            try self.markArtifactCallableEvalTemplate(kind, template_ref);
        }
    }

    fn markArtifactCallableEvalTemplate(
        self: *ExhaustivenessTemplateReachability,
        kind: ReachabilityKind,
        template_ref: ArtifactCallableEvalTemplateRef,
    ) Allocator.Error!void {
        if (!checkedArtifactKeyEql(template_ref.artifact, self.artifact_key)) return;
        try self.markCallableEvalTemplate(kind, template_ref.template);
    }

    fn markCallableProcedureTemplate(
        self: *ExhaustivenessTemplateReachability,
        kind: ReachabilityKind,
        template: canonical.CallableProcedureTemplateRef,
    ) Allocator.Error!void {
        switch (template) {
            .checked => |checked| try self.markProcedureTemplate(kind, checked),
            .synthetic => |synthetic| try self.markProcedureTemplate(kind, synthetic.template),
            .lifted => checkedArtifactInvariant("reachable procedure template reached lifted procedure before post-check lowering", .{}),
        }
    }

    fn localTemplateIndex(
        self: *const ExhaustivenessTemplateReachability,
        template_ref: canonical.ProcedureTemplateRef,
    ) ?usize {
        if (!checkedArtifactKeyEql(checkedArtifactKeyFromArtifactRef(template_ref.artifact), self.artifact_key)) return null;
        const idx = @intFromEnum(template_ref.template);
        if (idx >= self.procedure_templates.templates.len) {
            checkedArtifactInvariant("reachable procedure template ref was outside table", .{});
        }
        return idx;
    }
};

fn publishCheckedExhaustivenessSites(
    allocator: Allocator,
    maybe_problem_store: ?*problem.Store,
    checked_bodies: *const CheckedBodyStore,
    compile_time_roots: *const CompileTimeRootTable,
    reachability: *const ExhaustivenessTemplateReachability,
) Allocator.Error!CheckedExhaustivenessSiteTable {
    const problem_store = maybe_problem_store orelse return .{};
    var sites = std.ArrayList(CheckedExhaustivenessSite).empty;
    errdefer sites.deinit(allocator);

    for (problem_store.pending_static_exhaustiveness.items) |pending| {
        const source_is_published = switch (pending.source) {
            .match_expr => |source_expr| checked_bodies.exprIdForSource(source_expr) != null,
            .destructure_pattern => |source_pattern| checked_bodies.patternIdForSource(source_pattern) != null,
        };
        if (!source_is_published) {
            // Checking may replace an erroneous enclosing expression with a
            // runtime-error node. Its child source occurrences are then
            // intentionally absent from the checked body graph. Leave the
            // diagnostic pending: static failures are flushed after
            // compile-time finalization, while an empirical-only site under a
            // runtime error can never execute and needs no publication.
            continue;
        }

        const id: CheckedExhaustivenessSiteId = @enumFromInt(@as(u32, @intCast(sites.items.len)));
        const owner_template = exhaustivenessOwnerTemplateForSource(checked_bodies, pending.source);
        const replacing_root = exhaustivenessReplacingRootForSource(checked_bodies, compile_time_roots, pending.source);
        const policy: ExhaustivenessResolutionPolicy = if (replacing_root) |root|
            .{ .compile_time_replaced_by_root = root.id }
        else if (owner_template) |template_ref|
            if (reachability.templateIsRuntimeReachable(template_ref))
                .runtime_reachable
            else if (reachability.templateIsCompileTimeReachable(template_ref))
                .compile_time_only
            else switch (pending.mode) {
                .static => .runtime_reachable,
                .empirical => .compile_time_only,
            }
        else switch (pending.mode) {
            .empirical => .compile_time_only,
            .static => .runtime_reachable,
        };
        const owner: ?CheckedExhaustivenessSiteOwner = if (replacing_root) |root|
            .{ .root = root.id }
        else if (owner_template) |template_ref|
            .{ .procedure_template = template_ref }
        else
            null;
        const site = switch (pending.source) {
            .match_expr => |source_expr| blk: {
                const checked_expr = checkedExprIdForSource(checked_bodies, source_expr);
                break :blk CheckedExhaustivenessSite{
                    .id = id,
                    .kind = .match,
                    .region = pending.region,
                    .owner = owner,
                    .checked_expr = checked_expr,
                    .policy = policy,
                };
            },
            .destructure_pattern => |source_pattern| blk: {
                const checked_pattern = checkedPatternIdForSource(checked_bodies, source_pattern);
                break :blk CheckedExhaustivenessSite{
                    .id = id,
                    .kind = .destructure,
                    .region = pending.region,
                    .owner = owner,
                    .checked_pattern = checked_pattern,
                    .policy = policy,
                };
            },
        };
        try sites.append(allocator, site);
        problem_store.assignPendingStaticExhaustivenessSite(pending.source, id);
    }

    return .{ .sites = try sites.toOwnedSlice(allocator) };
}

fn exhaustivenessOwnerTemplateForSource(
    checked_bodies: *const CheckedBodyStore,
    source: problem.Store.ExhaustivenessSiteSource,
) ?canonical.ProcedureTemplateRef {
    for (checked_bodies.bodies.items) |body| {
        const contains = switch (source) {
            .match_expr => |source_expr| blk: {
                const checked_expr = checked_bodies.exprIdForSource(source_expr) orelse break :blk false;
                break :blk checkedExprContainsExpr(checked_bodies, body.root_expr, checked_expr);
            },
            .destructure_pattern => |source_pattern| blk: {
                const checked_pattern = checked_bodies.patternIdForSource(source_pattern) orelse break :blk false;
                break :blk checkedExprContainsPattern(checked_bodies, body.root_expr, checked_pattern);
            },
        };
        if (contains) return body.owner_template;
    }
    return null;
}

fn exhaustivenessReplacingRootForSource(
    checked_bodies: *const CheckedBodyStore,
    compile_time_roots: *const CompileTimeRootTable,
    source: problem.Store.ExhaustivenessSiteSource,
) ?CompileTimeRoot {
    for (compile_time_roots.roots) |root| {
        if (!compileTimeRootReplacesSourceOccurrence(root.kind)) continue;
        const contains = switch (source) {
            .match_expr => |source_expr| blk: {
                const checked_expr = checked_bodies.exprIdForSource(source_expr) orelse break :blk false;
                break :blk checkedExprContainsExpr(checked_bodies, root.expr, checked_expr);
            },
            .destructure_pattern => |source_pattern| blk: {
                const checked_pattern = checked_bodies.patternIdForSource(source_pattern) orelse break :blk false;
                break :blk checkedExprContainsPattern(checked_bodies, root.expr, checked_pattern);
            },
        };
        if (contains) return root;
    }
    return null;
}

fn compileTimeRootReplacesSourceOccurrence(kind: CompileTimeRootKind) bool {
    return switch (kind) {
        .constant,
        .hoisted_constant,
        .numeral_conversion,
        .quote_conversion,
        // A default expression never occurs in a runtime body: any
        // exhaustiveness site inside it belongs to its compile-time
        // evaluation (design.md "Defaulted Fields").
        .field_default,
        => true,
        .callable_binding,
        .expect,
        => false,
    };
}

fn checkedExprSpanContainsExpr(
    checked_bodies: *const CheckedBodyStore,
    exprs: []const CheckedExprId,
    needle: CheckedExprId,
) bool {
    for (exprs) |expr| {
        if (checkedExprContainsExpr(checked_bodies, expr, needle)) return true;
    }
    return false;
}

fn checkedExprContainsExpr(
    checked_bodies: *const CheckedBodyStore,
    haystack: CheckedExprId,
    needle: CheckedExprId,
) bool {
    if (haystack == needle) return true;
    const expr = checked_bodies.expr(haystack);
    return switch (expr.data) {
        .str, .list, .tuple => |items| checkedExprSpanContainsExpr(checked_bodies, items, needle),
        .match_ => |match| blk: {
            if (checkedExprContainsExpr(checked_bodies, match.cond, needle)) break :blk true;
            for (match.branches) |branch| {
                if (branch.guard) |guard| {
                    if (checkedExprContainsExpr(checked_bodies, guard, needle)) break :blk true;
                }
                if (checkedExprContainsExpr(checked_bodies, branch.value, needle)) break :blk true;
            }
            break :blk false;
        },
        .if_ => |if_| blk: {
            for (if_.branches) |branch| {
                if (checkedExprContainsExpr(checked_bodies, branch.cond, needle)) break :blk true;
                if (checkedExprContainsExpr(checked_bodies, branch.body, needle)) break :blk true;
            }
            break :blk checkedExprContainsExpr(checked_bodies, if_.final_else, needle);
        },
        .call => |call| checkedExprContainsExpr(checked_bodies, call.func, needle) or
            checkedExprSpanContainsExpr(checked_bodies, call.args, needle),
        .record => |record| blk: {
            if (record.ext) |ext| {
                if (checkedExprContainsExpr(checked_bodies, ext, needle)) break :blk true;
            }
            for (record.fields) |field| {
                if (checkedExprContainsExpr(checked_bodies, field.value, needle)) break :blk true;
            }
            break :blk false;
        },
        .block => |block| blk: {
            for (block.statements) |statement| {
                if (checkedStatementContainsExpr(checked_bodies, statement, needle)) break :blk true;
            }
            break :blk checkedExprContainsExpr(checked_bodies, block.final_expr, needle);
        },
        .tag => |tag| checkedExprSpanContainsExpr(checked_bodies, tag.args, needle),
        .nominal => |nominal| checkedExprContainsExpr(checked_bodies, nominal.backing_expr, needle),
        .closure => |closure| checkedExprContainsExpr(checked_bodies, closure.lambda, needle),
        .lambda => |lambda| checkedExprContainsExpr(checked_bodies, lambda.body, needle),
        .binop => |binop| checkedExprContainsExpr(checked_bodies, binop.lhs, needle) or
            checkedExprContainsExpr(checked_bodies, binop.rhs, needle),
        .unary_minus, .unary_not, .dbg, .expect => |child| checkedExprContainsExpr(checked_bodies, child, needle),
        .tuple_access => |access| checkedExprContainsExpr(checked_bodies, access.tuple, needle),
        .field_access => |field| checkedExprContainsExpr(checked_bodies, field.receiver, needle),
        .interpolation => |interpolation| blk: {
            if (checkedExprContainsExpr(checked_bodies, interpolation.first, needle)) break :blk true;
            for (interpolation.parts) |part| {
                if (checkedExprContainsExpr(checked_bodies, part.value, needle)) break :blk true;
                if (checkedExprContainsExpr(checked_bodies, part.following_segment, needle)) break :blk true;
            }
            break :blk false;
        },
        .structural_eq => |eq| checkedExprContainsExpr(checked_bodies, eq.lhs, needle) or
            checkedExprContainsExpr(checked_bodies, eq.rhs, needle),
        .structural_hash => |h| checkedExprContainsExpr(checked_bodies, h.value, needle) or
            checkedExprContainsExpr(checked_bodies, h.hasher, needle),
        .expect_err => |expect_err| checkedExprContainsExpr(checked_bodies, expect_err.expr, needle),
        .return_ => |ret| checkedExprContainsExpr(checked_bodies, ret.expr, needle),
        .for_ => |for_| checkedExprContainsExpr(checked_bodies, for_.expr, needle) or
            checkedExprContainsExpr(checked_bodies, for_.body, needle),
        .run_low_level => |run| checkedExprSpanContainsExpr(checked_bodies, run.args, needle),
        .numeral,
        .str_from_quote,
        .str_segment,
        .bytes_literal,
        .lookup_local,
        .lookup_external,
        .lookup_required,
        .empty_list,
        .empty_record,
        .zero_argument_tag,
        .dispatch_call,
        .method_eq,
        .type_dispatch_call,
        .hosted_lambda,
        .runtime_error,
        .crash,
        .break_,
        .ellipsis,
        .anno_only,
        .pending,
        => false,
    };
}

fn checkedStatementContainsExpr(
    checked_bodies: *const CheckedBodyStore,
    statement_id: CheckedStatementId,
    needle: CheckedExprId,
) bool {
    const statement = checked_bodies.statement(statement_id);
    return switch (statement.data) {
        .decl => |decl| checkedExprContainsExpr(checked_bodies, decl.expr, needle),
        .var_ => |var_| checkedExprContainsExpr(checked_bodies, var_.expr, needle),
        .reassign => |reassign| checkedExprContainsExpr(checked_bodies, reassign.expr, needle),
        .dbg, .expr, .expect => |expr| checkedExprContainsExpr(checked_bodies, expr, needle),
        .for_ => |for_| checkedExprContainsExpr(checked_bodies, for_.expr, needle) or
            checkedExprContainsExpr(checked_bodies, for_.body, needle),
        .while_ => |while_| checkedExprContainsExpr(checked_bodies, while_.cond, needle) or
            checkedExprContainsExpr(checked_bodies, while_.body, needle),
        .infinite_loop => |loop| checkedExprContainsExpr(checked_bodies, loop.cond, needle) or
            checkedExprContainsExpr(checked_bodies, loop.body, needle),
        .breakable_loop => |loop| checkedExprContainsExpr(checked_bodies, loop.cond, needle) or
            checkedExprContainsExpr(checked_bodies, loop.body, needle),
        .return_ => |ret| checkedExprContainsExpr(checked_bodies, ret.expr, needle),
        .var_uninitialized,
        .crash,
        .break_,
        .import_,
        .alias_decl,
        .where_alias_decl,
        .nominal_decl,
        .type_anno,
        .type_var_alias,
        .runtime_error,
        .pending,
        => false,
    };
}

fn checkedExprContainsPattern(
    checked_bodies: *const CheckedBodyStore,
    expr_id: CheckedExprId,
    needle: CheckedPatternId,
) bool {
    const expr = checked_bodies.expr(expr_id);
    return switch (expr.data) {
        .match_ => |match| blk: {
            for (match.branches) |branch| {
                for (branch.patternsSlice(checked_bodies)) |branch_pattern| {
                    if (checkedPatternContainsPattern(checked_bodies, branch_pattern.pattern, needle)) break :blk true;
                }
                if (branch.guard) |guard| {
                    if (checkedExprContainsPattern(checked_bodies, guard, needle)) break :blk true;
                }
                if (checkedExprContainsPattern(checked_bodies, branch.value, needle)) break :blk true;
            }
            break :blk checkedExprContainsPattern(checked_bodies, match.cond, needle);
        },
        .lambda => |lambda| blk: {
            for (lambda.args) |arg| {
                if (checkedPatternContainsPattern(checked_bodies, arg, needle)) break :blk true;
            }
            break :blk checkedExprContainsPattern(checked_bodies, lambda.body, needle);
        },
        .for_ => |for_| checkedPatternContainsPattern(checked_bodies, for_.pattern, needle) or
            checkedExprContainsPattern(checked_bodies, for_.expr, needle) or
            checkedExprContainsPattern(checked_bodies, for_.body, needle),
        .block => |block| blk: {
            for (block.statements) |statement| {
                if (checkedStatementContainsPattern(checked_bodies, statement, needle)) break :blk true;
            }
            break :blk checkedExprContainsPattern(checked_bodies, block.final_expr, needle);
        },
        .str, .list, .tuple => |items| blk: {
            for (items) |item| {
                if (checkedExprContainsPattern(checked_bodies, item, needle)) break :blk true;
            }
            break :blk false;
        },
        .if_ => |if_| blk: {
            for (if_.branches) |branch| {
                if (checkedExprContainsPattern(checked_bodies, branch.cond, needle)) break :blk true;
                if (checkedExprContainsPattern(checked_bodies, branch.body, needle)) break :blk true;
            }
            break :blk checkedExprContainsPattern(checked_bodies, if_.final_else, needle);
        },
        .call => |call| checkedExprContainsPattern(checked_bodies, call.func, needle) or
            checkedExprSpanContainsPattern(checked_bodies, call.args, needle),
        .record => |record| blk: {
            if (record.ext) |ext| {
                if (checkedExprContainsPattern(checked_bodies, ext, needle)) break :blk true;
            }
            for (record.fields) |field| {
                if (checkedExprContainsPattern(checked_bodies, field.value, needle)) break :blk true;
            }
            break :blk false;
        },
        .tag => |tag| checkedExprSpanContainsPattern(checked_bodies, tag.args, needle),
        .nominal => |nominal| checkedExprContainsPattern(checked_bodies, nominal.backing_expr, needle),
        .closure => |closure| checkedExprContainsPattern(checked_bodies, closure.lambda, needle),
        .binop => |binop| checkedExprContainsPattern(checked_bodies, binop.lhs, needle) or
            checkedExprContainsPattern(checked_bodies, binop.rhs, needle),
        .unary_minus, .unary_not, .dbg, .expect => |child| checkedExprContainsPattern(checked_bodies, child, needle),
        .tuple_access => |access| checkedExprContainsPattern(checked_bodies, access.tuple, needle),
        .field_access => |field| checkedExprContainsPattern(checked_bodies, field.receiver, needle),
        .interpolation => |interpolation| blk: {
            if (checkedExprContainsPattern(checked_bodies, interpolation.first, needle)) break :blk true;
            for (interpolation.parts) |part| {
                if (checkedExprContainsPattern(checked_bodies, part.value, needle)) break :blk true;
                if (checkedExprContainsPattern(checked_bodies, part.following_segment, needle)) break :blk true;
            }
            break :blk false;
        },
        .structural_eq => |eq| checkedExprContainsPattern(checked_bodies, eq.lhs, needle) or
            checkedExprContainsPattern(checked_bodies, eq.rhs, needle),
        .structural_hash => |h| checkedExprContainsPattern(checked_bodies, h.value, needle) or
            checkedExprContainsPattern(checked_bodies, h.hasher, needle),
        .expect_err => |expect_err| checkedExprContainsPattern(checked_bodies, expect_err.expr, needle),
        .return_ => |ret| checkedExprContainsPattern(checked_bodies, ret.expr, needle),
        .run_low_level => |run| checkedExprSpanContainsPattern(checked_bodies, run.args, needle),
        .hosted_lambda => |hosted| checkedPatternSpanContainsPattern(checked_bodies, hosted.args, needle),
        .numeral,
        .str_from_quote,
        .str_segment,
        .bytes_literal,
        .lookup_local,
        .lookup_external,
        .lookup_required,
        .empty_list,
        .empty_record,
        .zero_argument_tag,
        .dispatch_call,
        .method_eq,
        .type_dispatch_call,
        .runtime_error,
        .crash,
        .break_,
        .ellipsis,
        .anno_only,
        .pending,
        => false,
    };
}

fn checkedExprSpanContainsPattern(
    checked_bodies: *const CheckedBodyStore,
    exprs: []const CheckedExprId,
    needle: CheckedPatternId,
) bool {
    for (exprs) |expr| {
        if (checkedExprContainsPattern(checked_bodies, expr, needle)) return true;
    }
    return false;
}

fn checkedStatementContainsPattern(
    checked_bodies: *const CheckedBodyStore,
    statement_id: CheckedStatementId,
    needle: CheckedPatternId,
) bool {
    const statement = checked_bodies.statement(statement_id);
    return switch (statement.data) {
        .decl => |decl| checkedPatternContainsPattern(checked_bodies, decl.pattern, needle) or
            checkedExprContainsPattern(checked_bodies, decl.expr, needle),
        .var_ => |var_| checkedPatternContainsPattern(checked_bodies, var_.pattern, needle) or
            checkedExprContainsPattern(checked_bodies, var_.expr, needle),
        .var_uninitialized => |var_| checkedPatternContainsPattern(checked_bodies, var_.pattern, needle),
        .reassign => |reassign| checkedPatternContainsPattern(checked_bodies, reassign.pattern, needle) or
            checkedExprContainsPattern(checked_bodies, reassign.expr, needle),
        .dbg, .expr, .expect => |expr| checkedExprContainsPattern(checked_bodies, expr, needle),
        .for_ => |for_| checkedPatternContainsPattern(checked_bodies, for_.pattern, needle) or
            checkedExprContainsPattern(checked_bodies, for_.expr, needle) or
            checkedExprContainsPattern(checked_bodies, for_.body, needle),
        .while_ => |while_| checkedExprContainsPattern(checked_bodies, while_.cond, needle) or
            checkedExprContainsPattern(checked_bodies, while_.body, needle),
        .infinite_loop => |loop| checkedExprContainsPattern(checked_bodies, loop.cond, needle) or
            checkedExprContainsPattern(checked_bodies, loop.body, needle),
        .breakable_loop => |loop| checkedExprContainsPattern(checked_bodies, loop.cond, needle) or
            checkedExprContainsPattern(checked_bodies, loop.body, needle),
        .return_ => |ret| checkedExprContainsPattern(checked_bodies, ret.expr, needle),
        .crash,
        .break_,
        .import_,
        .alias_decl,
        .where_alias_decl,
        .nominal_decl,
        .type_anno,
        .type_var_alias,
        .runtime_error,
        .pending,
        => false,
    };
}

fn checkedPatternContainsPattern(
    checked_bodies: *const CheckedBodyStore,
    haystack: CheckedPatternId,
    needle: CheckedPatternId,
) bool {
    if (haystack == needle) return true;
    const pattern = checked_bodies.pattern(haystack);
    return switch (pattern.data) {
        .as => |as| checkedPatternContainsPattern(checked_bodies, as.pattern, needle),
        .applied_tag => |tag| checkedPatternSpanContainsPattern(checked_bodies, tag.args, needle),
        .nominal => |nominal| checkedPatternContainsPattern(checked_bodies, nominal.backing_pattern, needle),
        .record_destructure => |destructs| blk: {
            for (destructs) |destruct| {
                const child = switch (destruct.kind) {
                    .required => |required| required,
                    .sub_pattern => |sub_pattern| sub_pattern,
                    .rest => |rest| rest,
                };
                if (checkedPatternContainsPattern(checked_bodies, child, needle)) break :blk true;
            }
            break :blk false;
        },
        .list => |list| blk: {
            if (checkedPatternSpanContainsPattern(checked_bodies, list.patterns, needle)) break :blk true;
            if (list.rest) |rest| {
                if (rest.pattern) |rest_pattern| {
                    if (checkedPatternContainsPattern(checked_bodies, rest_pattern, needle)) break :blk true;
                }
            }
            break :blk false;
        },
        .tuple => |items| checkedPatternSpanContainsPattern(checked_bodies, items, needle),
        .str_interpolation => |str| blk: {
            for (str.steps) |step| {
                if (step.capture) |capture| {
                    if (checkedPatternContainsPattern(checked_bodies, capture, needle)) break :blk true;
                }
            }
            break :blk false;
        },
        .pending,
        .assign,
        .numeral_literal,
        .str_literal,
        .underscore,
        .runtime_error,
        => false,
    };
}

fn checkedPatternSpanContainsPattern(
    checked_bodies: *const CheckedBodyStore,
    patterns: []const CheckedPatternId,
    needle: CheckedPatternId,
) bool {
    for (patterns) |pattern| {
        if (checkedPatternContainsPattern(checked_bodies, pattern, needle)) return true;
    }
    return false;
}

fn syntheticExprCapacityForHoistedRoots(selected_hoisted_roots: []const hoist_roots.SelectedHoistedRoot) usize {
    var count: usize = 0;
    for (selected_hoisted_roots) |root| {
        count += switch (root.body) {
            .expr => 0,
            .pattern_extraction => 2,
        };
    }
    return count;
}

fn checkedExprIdForSource(checked_bodies: *const CheckedBodyStore, expr: CIR.Expr.Idx) CheckedExprId {
    return checked_bodies.exprIdForSource(expr) orelse {
        checkedArtifactInvariant(
            "checked artifact publication could not map CIR expression {d} to a checked expression id",
            .{@intFromEnum(expr)},
        );
    };
}

fn checkedExprIdForSelectedHoistedRoot(
    allocator: Allocator,
    module: TypedCIR.Module,
    checked_types: *const CheckedTypePublication,
    checked_body_builder: *CheckedBodyStoreBuilder,
    selected_index: u32,
    selected: hoist_roots.SelectedHoistedRoot,
) Allocator.Error!CheckedExprId {
    const checked_bodies = checked_body_builder.storePtr();
    return switch (selected.body) {
        .expr => checkedExprIdForSource(checked_bodies, selected.expr),
        .pattern_extraction => |extraction| try appendCheckedPatternExtractionRootExpr(
            allocator,
            module,
            checked_body_builder,
            selected_index,
            extraction,
            try checkedTypeIdForVar(allocator, module, checked_types, ModuleEnv.varFrom(extraction.result_pattern)),
        ),
    };
}

fn appendCheckedPatternExtractionRootExpr(
    allocator: Allocator,
    module: TypedCIR.Module,
    checked_body_builder: *CheckedBodyStoreBuilder,
    selected_index: u32,
    extraction: hoist_roots.PatternExtraction,
    checked_type: CheckedTypeId,
) Allocator.Error!CheckedExprId {
    const checked_bodies = checked_body_builder.storePtr();
    const scrutinee = checkedExprIdForSource(checked_bodies, extraction.base_expr);
    const checked_result_pattern = checkedPatternIdForSource(checked_bodies, extraction.result_pattern);
    const result_region = module.regionAt(ModuleEnv.nodeIdxFrom(extraction.result_pattern));
    const result_lookup = try checked_body_builder.appendSyntheticExpr(allocator, .{ .pattern_extraction_result_lookup = .{
        .selected_root_index = selected_index,
        .result_pattern = checked_result_pattern,
    } }, checked_type, result_region, .{ .lookup_local = .{
        .pattern = checked_result_pattern,
        .resolved = null,
    } });

    try checked_bodies.match_branch_pattern_pool.ensureUnusedCapacity(allocator, 1);
    const checked_scrutinee_pattern = checkedPatternIdForSource(checked_bodies, extraction.scrutinee_pattern);
    const pattern_start: u32 = @intCast(checked_bodies.match_branch_pattern_pool.items.len);
    checked_bodies.match_branch_pattern_pool.appendAssumeCapacity(.{
        .pattern = checked_scrutinee_pattern,
        .degenerate = false,
        .bn_start = 0,
        .bn_len = 0,
    });
    errdefer _ = checked_bodies.match_branch_pattern_pool.pop();

    const branches = try allocator.alloc(CheckedMatchBranch, 1);
    var branches_owned = true;
    errdefer if (branches_owned) allocator.free(branches);
    branches[0] = .{
        .pt_start = pattern_start,
        .pt_len = 1,
        .value = result_lookup,
        .guard = null,
    };

    var data: CheckedExprData = .{ .match_ = .{
        .cond = scrutinee,
        .branches = branches,
        .is_try_suffix = false,
        .skip_exhaustiveness = false,
        .comptime_site_kind = .destructure,
    } };
    branches_owned = false;
    defer deinitCheckedExprData(allocator, &data);

    const match_region = module.regionAt(ModuleEnv.nodeIdxFrom(extraction.scrutinee_pattern));
    return try checked_body_builder.appendSyntheticExpr(allocator, .{ .pattern_extraction_wrapper = .{
        .selected_root_index = selected_index,
        .scrutinee_pattern = checked_scrutinee_pattern,
    } }, checked_type, match_region, data);
}

fn checkedPatternIdForSource(checked_bodies: *const CheckedBodyStore, pattern: CIR.Pattern.Idx) CheckedPatternId {
    return checked_bodies.patternIdForSource(pattern) orelse {
        checkedArtifactInvariant(
            "checked artifact publication could not map CIR pattern {d} to a checked pattern id",
            .{@intFromEnum(pattern)},
        );
    };
}

