/// Public `ImportedTemplateClosureView` declaration.
pub const ImportedTemplateClosureView = struct {
    checked_bodies: []const ArtifactCheckedBodyRef = &.{},
    checked_type_roots: []const ArtifactCheckedTypeRef = &.{},
    checked_type_schemes: []const ArtifactCheckedTypeSchemeRef = &.{},
    checked_callable_bodies: []const ArtifactCheckedCallableBodyRef = &.{},
    checked_const_bodies: []const ArtifactCheckedConstBodyRef = &.{},
    checked_procedure_templates: []const ArtifactProcedureTemplateRef = &.{},
    callable_eval_templates: []const ArtifactCallableEvalTemplateRef = &.{},
    const_templates: []const ConstRef = &.{},
    nested_proc_sites: []const ArtifactNestedProcSiteTableRef = &.{},
    resolved_value_refs: []const ArtifactResolvedValueRefTableRef = &.{},
    static_dispatch_plans: []const ArtifactStaticDispatchPlanTableRef = &.{},
    method_registry_entries: []const MethodRegistryEntryRef = &.{},
    interface_capabilities: []const ArtifactModuleInterfaceCapabilitiesRef = &.{},
};

/// `(start, len)` range into one of a `ClosurePool`'s flat side pools.
pub const ClosureRange = extern struct { start: u32 = 0, len: u32 = 0 };

/// Relocation-invariant (POD) mirror of `ImportedTemplateClosureView`: each of
/// the 13 closure slices is replaced by a `ClosureRange` into the owning
/// `ClosurePool`. Stored by value in closure-bearing table rows so each row
/// relocates with a constant number of base-pointer fixups. The public
/// `ImportedTemplateClosureView` (with slices) is reconstructed on demand.
pub const StoredImportedTemplateClosure = extern struct {
    checked_bodies: ClosureRange = .{},
    checked_type_roots: ClosureRange = .{},
    checked_type_schemes: ClosureRange = .{},
    checked_callable_bodies: ClosureRange = .{},
    checked_const_bodies: ClosureRange = .{},
    checked_procedure_templates: ClosureRange = .{},
    callable_eval_templates: ClosureRange = .{},
    const_templates: ClosureRange = .{},
    nested_proc_sites: ClosureRange = .{},
    resolved_value_refs: ClosureRange = .{},
    static_dispatch_plans: ClosureRange = .{},
    method_registry_entries: ClosureRange = .{},
    interface_capabilities: ClosureRange = .{},
};

/// Flat side pools backing every `StoredImportedTemplateClosure` of a single
/// closure-bearing table. Each public closure slice has its own pool of POD ref
/// elements; `commit` copies an owned `ImportedTemplateClosureView` into the
/// pools and `materialize` returns the public view aliasing them (zero-alloc).
pub const ClosurePool = struct {
    checked_bodies: std.ArrayList(ArtifactCheckedBodyRef),
    checked_type_roots: std.ArrayList(ArtifactCheckedTypeRef),
    checked_type_schemes: std.ArrayList(ArtifactCheckedTypeSchemeRef),
    checked_callable_bodies: std.ArrayList(ArtifactCheckedCallableBodyRef),
    checked_const_bodies: std.ArrayList(ArtifactCheckedConstBodyRef),
    checked_procedure_templates: std.ArrayList(ArtifactProcedureTemplateRef),
    callable_eval_templates: std.ArrayList(ArtifactCallableEvalTemplateRef),
    const_templates: std.ArrayList(ConstRef),
    nested_proc_sites: std.ArrayList(ArtifactNestedProcSiteTableRef),
    resolved_value_refs: std.ArrayList(ArtifactResolvedValueRefTableRef),
    static_dispatch_plans: std.ArrayList(ArtifactStaticDispatchPlanTableRef),
    method_registry_entries: std.ArrayList(MethodRegistryEntryRef),
    interface_capabilities: std.ArrayList(ArtifactModuleInterfaceCapabilitiesRef),
    /// True when the pools alias a serialized buffer and must not be freed.
    serialized: bool = false,

    pub const empty: ClosurePool = .{
        .checked_bodies = .empty,
        .checked_type_roots = .empty,
        .checked_type_schemes = .empty,
        .checked_callable_bodies = .empty,
        .checked_const_bodies = .empty,
        .checked_procedure_templates = .empty,
        .callable_eval_templates = .empty,
        .const_templates = .empty,
        .nested_proc_sites = .empty,
        .resolved_value_refs = .empty,
        .static_dispatch_plans = .empty,
        .method_registry_entries = .empty,
        .interface_capabilities = .empty,
    };

    fn appendPool(
        comptime T: type,
        pool: *std.ArrayList(T),
        allocator: Allocator,
        slice: []const T,
    ) Allocator.Error!ClosureRange {
        return artifact_serialize.appendSpan(ClosureRange, T, pool, allocator, slice);
    }

    fn poolSlice(comptime T: type, pool: *const std.ArrayList(T), range: ClosureRange) []const T {
        return pool.items[range.start .. range.start + range.len];
    }

    /// Copy each closure slice into its pool, returning the POD ranges, then
    /// free the input view's owned slices. Mirrors `deinitImportedTemplateClosure`.
    pub fn commit(
        self: *ClosurePool,
        allocator: Allocator,
        closure: ImportedTemplateClosureView,
    ) Allocator.Error!StoredImportedTemplateClosure {
        var owned = closure;
        defer deinitImportedTemplateClosure(allocator, &owned);
        return .{
            .checked_bodies = try appendPool(ArtifactCheckedBodyRef, &self.checked_bodies, allocator, closure.checked_bodies),
            .checked_type_roots = try appendPool(ArtifactCheckedTypeRef, &self.checked_type_roots, allocator, closure.checked_type_roots),
            .checked_type_schemes = try appendPool(ArtifactCheckedTypeSchemeRef, &self.checked_type_schemes, allocator, closure.checked_type_schemes),
            .checked_callable_bodies = try appendPool(ArtifactCheckedCallableBodyRef, &self.checked_callable_bodies, allocator, closure.checked_callable_bodies),
            .checked_const_bodies = try appendPool(ArtifactCheckedConstBodyRef, &self.checked_const_bodies, allocator, closure.checked_const_bodies),
            .checked_procedure_templates = try appendPool(ArtifactProcedureTemplateRef, &self.checked_procedure_templates, allocator, closure.checked_procedure_templates),
            .callable_eval_templates = try appendPool(ArtifactCallableEvalTemplateRef, &self.callable_eval_templates, allocator, closure.callable_eval_templates),
            .const_templates = try appendPool(ConstRef, &self.const_templates, allocator, closure.const_templates),
            .nested_proc_sites = try appendPool(ArtifactNestedProcSiteTableRef, &self.nested_proc_sites, allocator, closure.nested_proc_sites),
            .resolved_value_refs = try appendPool(ArtifactResolvedValueRefTableRef, &self.resolved_value_refs, allocator, closure.resolved_value_refs),
            .static_dispatch_plans = try appendPool(ArtifactStaticDispatchPlanTableRef, &self.static_dispatch_plans, allocator, closure.static_dispatch_plans),
            .method_registry_entries = try appendPool(MethodRegistryEntryRef, &self.method_registry_entries, allocator, closure.method_registry_entries),
            .interface_capabilities = try appendPool(ArtifactModuleInterfaceCapabilitiesRef, &self.interface_capabilities, allocator, closure.interface_capabilities),
        };
    }

    /// Materialize the public 13-slice view aliasing this pool's flat storage.
    pub fn reconstruct(self: *const ClosurePool, stored: StoredImportedTemplateClosure) ImportedTemplateClosureView {
        return .{
            .checked_bodies = poolSlice(ArtifactCheckedBodyRef, &self.checked_bodies, stored.checked_bodies),
            .checked_type_roots = poolSlice(ArtifactCheckedTypeRef, &self.checked_type_roots, stored.checked_type_roots),
            .checked_type_schemes = poolSlice(ArtifactCheckedTypeSchemeRef, &self.checked_type_schemes, stored.checked_type_schemes),
            .checked_callable_bodies = poolSlice(ArtifactCheckedCallableBodyRef, &self.checked_callable_bodies, stored.checked_callable_bodies),
            .checked_const_bodies = poolSlice(ArtifactCheckedConstBodyRef, &self.checked_const_bodies, stored.checked_const_bodies),
            .checked_procedure_templates = poolSlice(ArtifactProcedureTemplateRef, &self.checked_procedure_templates, stored.checked_procedure_templates),
            .callable_eval_templates = poolSlice(ArtifactCallableEvalTemplateRef, &self.callable_eval_templates, stored.callable_eval_templates),
            .const_templates = poolSlice(ConstRef, &self.const_templates, stored.const_templates),
            .nested_proc_sites = poolSlice(ArtifactNestedProcSiteTableRef, &self.nested_proc_sites, stored.nested_proc_sites),
            .resolved_value_refs = poolSlice(ArtifactResolvedValueRefTableRef, &self.resolved_value_refs, stored.resolved_value_refs),
            .static_dispatch_plans = poolSlice(ArtifactStaticDispatchPlanTableRef, &self.static_dispatch_plans, stored.static_dispatch_plans),
            .method_registry_entries = poolSlice(MethodRegistryEntryRef, &self.method_registry_entries, stored.method_registry_entries),
            .interface_capabilities = poolSlice(ArtifactModuleInterfaceCapabilitiesRef, &self.interface_capabilities, stored.interface_capabilities),
        };
    }

    pub fn deinit(self: *ClosurePool, allocator: Allocator) void {
        if (!self.serialized) {
            self.checked_bodies.deinit(allocator);
            self.checked_type_roots.deinit(allocator);
            self.checked_type_schemes.deinit(allocator);
            self.checked_callable_bodies.deinit(allocator);
            self.checked_const_bodies.deinit(allocator);
            self.checked_procedure_templates.deinit(allocator);
            self.callable_eval_templates.deinit(allocator);
            self.const_templates.deinit(allocator);
            self.nested_proc_sites.deinit(allocator);
            self.resolved_value_refs.deinit(allocator);
            self.static_dispatch_plans.deinit(allocator);
            self.method_registry_entries.deinit(allocator);
            self.interface_capabilities.deinit(allocator);
        }
        self.* = ClosurePool.empty;
    }

    /// Relocatable serialized form: one `SerializedSlice` per flat pool (13
    /// base-pointer fixups, independent of stored data size).
    pub const Serialized = extern struct {
        checked_bodies: SerializedSlice(ArtifactCheckedBodyRef) = .{},
        checked_type_roots: SerializedSlice(ArtifactCheckedTypeRef) = .{},
        checked_type_schemes: SerializedSlice(ArtifactCheckedTypeSchemeRef) = .{},
        checked_callable_bodies: SerializedSlice(ArtifactCheckedCallableBodyRef) = .{},
        checked_const_bodies: SerializedSlice(ArtifactCheckedConstBodyRef) = .{},
        checked_procedure_templates: SerializedSlice(ArtifactProcedureTemplateRef) = .{},
        callable_eval_templates: SerializedSlice(ArtifactCallableEvalTemplateRef) = .{},
        const_templates: SerializedSlice(ConstRef) = .{},
        nested_proc_sites: SerializedSlice(ArtifactNestedProcSiteTableRef) = .{},
        resolved_value_refs: SerializedSlice(ArtifactResolvedValueRefTableRef) = .{},
        static_dispatch_plans: SerializedSlice(ArtifactStaticDispatchPlanTableRef) = .{},
        method_registry_entries: SerializedSlice(MethodRegistryEntryRef) = .{},
        interface_capabilities: SerializedSlice(ArtifactModuleInterfaceCapabilitiesRef) = .{},

        comptime {
            std.debug.assert(artifact_serialize.relocatablePointerCount(Serialized) == 13);
        }

        const Serde = artifact_serialize.SliceStoreSerde(ClosurePool, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };
};

test "ClosurePool: commit/reconstruct then serialize/relocate round-trip" {
    const gpa = std.testing.allocator;

    const key_a = CheckedModuleArtifactKey{ .bytes = [_]u8{1} ** 32 };
    const key_b = CheckedModuleArtifactKey{ .bytes = [_]u8{2} ** 32 };

    // An owned closure view (slices allocated by the caller, freed by commit).
    var closure = ImportedTemplateClosureView{};
    closure.checked_bodies = try gpa.dupe(ArtifactCheckedBodyRef, &.{
        .{ .artifact = key_a, .body = @enumFromInt(7) },
        .{ .artifact = key_b, .body = @enumFromInt(9) },
    });
    closure.interface_capabilities = try gpa.dupe(ArtifactModuleInterfaceCapabilitiesRef, &.{
        .{ .artifact = key_a },
    });

    var pool = ClosurePool.empty;
    defer pool.deinit(gpa);
    const stored = try pool.commit(gpa, closure);

    // Reconstructed view aliases the pool.
    const reconstructed = pool.reconstruct(stored);
    try std.testing.expectEqual(@as(usize, 2), reconstructed.checked_bodies.len);
    try std.testing.expectEqual(@as(u32, 7), @intFromEnum(reconstructed.checked_bodies[0].body));
    try std.testing.expectEqual(@as(usize, 1), reconstructed.interface_capabilities.len);

    // Serialize → aligned buffer → deserialize, then materialize again.
    var rt = try artifact_serialize.roundTripForTest(gpa, ClosurePool, &pool);
    defer gpa.free(rt.buffer);
    defer rt.loaded.deinit(gpa);

    const loaded = rt.loaded.reconstruct(stored);
    try std.testing.expectEqual(@as(usize, 2), loaded.checked_bodies.len);
    try std.testing.expectEqual(@as(u32, 9), @intFromEnum(loaded.checked_bodies[1].body));
    try std.testing.expectEqualSlices(u8, &key_b.bytes, &loaded.checked_bodies[1].artifact.bytes);
    try std.testing.expectEqual(@as(usize, 1), loaded.interface_capabilities.len);
    try std.testing.expectEqualSlices(u8, &key_a.bytes, &loaded.interface_capabilities[0].artifact.bytes);
}

test "ExportedProcedureBindingTable: serialize/relocate preserves rows and closures" {
    const gpa = std.testing.allocator;

    const key_a = CheckedModuleArtifactKey{ .bytes = [_]u8{3} ** 32 };

    var closure = ImportedTemplateClosureView{};
    closure.checked_type_roots = try gpa.dupe(ArtifactCheckedTypeRef, &.{
        .{ .artifact = key_a, .ty = @enumFromInt(4) },
    });

    var table = ExportedProcedureBindingTable{};
    const stored = try table.closure_pool.commit(gpa, closure);
    var bindings = std.ArrayList(ImportedProcedureBindingView).empty;
    try bindings.append(gpa, .{
        .binding = .{ .artifact = key_a, .def = @enumFromInt(1), .pattern = @enumFromInt(2) },
        .source_scheme = .{},
        .body = .{ .callable_eval_template = @enumFromInt(3) },
        .intrinsic = .str_inspect,
        .iterator_procedure = .iter_map,
        .runtime_result_provenance = .list_element_read,
        .template_closure = stored,
    });
    table.bindings = try bindings.toOwnedSlice(gpa);
    defer table.deinit(gpa);

    var rt = try artifact_serialize.roundTripForTest(gpa, ExportedProcedureBindingTable, &table);
    defer gpa.free(rt.buffer);
    defer rt.loaded.deinit(gpa);

    try std.testing.expectEqual(@as(usize, 1), rt.loaded.bindings.len);
    try std.testing.expectEqual(IntrinsicId.str_inspect, rt.loaded.bindings[0].intrinsic.?);
    try std.testing.expectEqual(IteratorProcedureId.iter_map, rt.loaded.bindings[0].iterator_procedure.?);
    try std.testing.expectEqual(
        RuntimeResultProvenance.list_element_read,
        rt.loaded.bindings[0].runtime_result_provenance.?,
    );
    const loaded_closure = rt.loaded.rowClosure(rt.loaded.bindings[0]);
    try std.testing.expectEqual(@as(usize, 1), loaded_closure.checked_type_roots.len);
    try std.testing.expectEqual(@as(u32, 4), @intFromEnum(loaded_closure.checked_type_roots[0].ty));
    try std.testing.expectEqualSlices(u8, &key_a.bytes, &loaded_closure.checked_type_roots[0].artifact.bytes);
}

test "platform relation procedure use preserves exported runtime result provenance" {
    const gpa = std.testing.allocator;
    const app_key = CheckedModuleArtifactKey{ .bytes = [_]u8{0xA7} ** 32 };
    const app_pattern: CheckedPatternId = @enumFromInt(2);
    const procedure_binding: TopLevelProcedureBindingRef = @enumFromInt(3);
    const required_binding_id: PlatformRequiredBindingId = @enumFromInt(8);
    const required_declaration_id: PlatformRequiredDeclarationId = @enumFromInt(9);
    const required_relation_id: PlatformRequirementRelationId = @enumFromInt(10);
    const requested_source_ty = canonical.CanonicalTypeKey{ .bytes = [_]u8{0xC1} ** 32 };
    const exported = ImportedProcedureBindingView{
        .binding = .{
            .artifact = app_key,
            .def = @enumFromInt(1),
            .pattern = app_pattern,
        },
        .source_scheme = .{},
        .body = .{ .callable_eval_template = @enumFromInt(4) },
        .runtime_result_provenance = .list_element_read,
    };
    const app_value = TopLevelValueEntry{
        .module_idx = 5,
        .def = exported.binding.def,
        .pattern = app_pattern,
        .source_name = @enumFromInt(6),
        .source_scheme = .{},
        .value = .{ .procedure_binding = procedure_binding },
    };
    const app_value_ref = TopLevelValueRef{
        .artifact = app_key,
        .pattern = app_pattern,
    };
    const resolved_export = exportedProcedureBindingForAppValue(
        .{ .bindings = &.{exported} },
        app_value,
    );
    const procedure = platformRequiredProcedureUse(
        app_key,
        app_value_ref,
        procedure_binding,
        requested_source_ty,
        resolved_export,
    );

    var table = PlatformRequiredBindingTable{};
    defer table.deinit(gpa);
    const stored_use = try commitPlatformRequiredValueUse(&table.closure_pool, gpa, .{
        .procedure_value = .{ .procedure = procedure },
    });
    table.bindings = try gpa.dupe(PlatformRequiredBinding, &.{.{
        .id = required_binding_id,
        .relation = .{},
        .module_idx = 7,
        .declaration = required_declaration_id,
        .requires_idx = 0,
        .app_value = app_value_ref,
        .requested_source_ty = requested_source_ty,
        .checked_relation = required_relation_id,
        .value_use = stored_use,
    }});

    var rt = try artifact_serialize.roundTripForTest(gpa, PlatformRequiredBindingTable, &table);
    defer gpa.free(rt.buffer);
    defer rt.loaded.deinit(gpa);
    try std.testing.expectEqual(required_binding_id, rt.loaded.bindings[0].id);
    try std.testing.expectEqual(required_declaration_id, rt.loaded.bindings[0].declaration);
    try std.testing.expectEqual(required_relation_id, rt.loaded.bindings[0].checked_relation);
    const loaded_procedure = switch (rt.loaded.bindings[0].value_use) {
        .procedure_value => |procedure_use| procedure_use.procedure,
        .const_value => return error.TestExpectedEqual,
    };
    try std.testing.expectEqual(
        RuntimeResultProvenance.list_element_read,
        loaded_procedure.runtime_result_provenance.?,
    );
}

/// Public `appendImportedTemplateClosureArtifactKeys` function.
///
/// Appends every checked-artifact key explicitly referenced by an imported
/// template closure. This is used when an executable root needs to assemble the
/// complete set of read-only artifact views required by platform/app relation
/// closures without scanning source or rediscovering dependencies from syntax.
pub fn appendImportedTemplateClosureArtifactKeys(
    allocator: Allocator,
    keys: *std.ArrayList(CheckedModuleArtifactKey),
    closure: ImportedTemplateClosureView,
) Allocator.Error!void {
    for (closure.checked_bodies) |value| try appendClosureArtifactKey(allocator, keys, value.artifact);
    for (closure.checked_type_roots) |value| try appendClosureArtifactKey(allocator, keys, value.artifact);
    for (closure.checked_type_schemes) |value| try appendClosureArtifactKey(allocator, keys, value.artifact);
    for (closure.checked_callable_bodies) |value| try appendClosureArtifactKey(allocator, keys, value.artifact);
    for (closure.checked_const_bodies) |value| try appendClosureArtifactKey(allocator, keys, value.artifact);
    for (closure.checked_procedure_templates) |value| try appendClosureArtifactKey(allocator, keys, checkedArtifactKeyFromArtifactRef(value.artifact));
    for (closure.callable_eval_templates) |value| try appendClosureArtifactKey(allocator, keys, value.artifact);
    for (closure.const_templates) |value| try appendClosureArtifactKey(allocator, keys, value.artifact);
    for (closure.nested_proc_sites) |value| try appendClosureArtifactKey(allocator, keys, value.artifact);
    for (closure.resolved_value_refs) |value| try appendClosureArtifactKey(allocator, keys, value.artifact);
    for (closure.static_dispatch_plans) |value| try appendClosureArtifactKey(allocator, keys, value.artifact);
    for (closure.interface_capabilities) |value| try appendClosureArtifactKey(allocator, keys, value.artifact);
}

/// Public `appendPlatformRelationDependencyArtifactKeys` function.
///
/// Appends every checked-artifact key a platform/app relation row may need
/// during post-check lowering. The source is the already-published relation row
/// plus the relation artifact's exported closure data; callers must not derive
/// these dependencies from source imports or declaration scans.
pub fn appendPlatformRelationDependencyArtifactKeys(
    allocator: Allocator,
    keys: *std.ArrayList(CheckedModuleArtifactKey),
    relation_artifact: *const CheckedModuleArtifact,
    binding: PlatformRequiredBinding,
    binding_relation_closure: ImportedTemplateClosureView,
) Allocator.Error!void {
    try appendPlatformRelationDependencyArtifactKeysFromView(
        allocator,
        keys,
        importedView(relation_artifact),
        binding,
        binding_relation_closure,
    );
}

/// Public `appendPlatformRelationDependencyArtifactKeysFromView` function.
///
/// Same dependency collection as `appendPlatformRelationDependencyArtifactKeys`,
/// but consumes the read-only relation artifact view already passed across the
/// post-check lowering boundary.
pub fn appendPlatformRelationDependencyArtifactKeysFromView(
    allocator: Allocator,
    keys: *std.ArrayList(CheckedModuleArtifactKey),
    relation_artifact: ImportedModuleView,
    binding: PlatformRequiredBinding,
    binding_relation_closure: ImportedTemplateClosureView,
) Allocator.Error!void {
    for (relation_artifact.direct_import_artifact_keys) |key| {
        try appendClosureArtifactKey(allocator, keys, key);
    }

    try appendImportedTemplateClosureArtifactKeys(allocator, keys, binding_relation_closure);
    try appendRelationArtifactExportedValueClosureKeysFromView(allocator, keys, relation_artifact, binding);
}

fn appendRelationArtifactExportedValueClosureKeysFromView(
    allocator: Allocator,
    keys: *std.ArrayList(CheckedModuleArtifactKey),
    relation_artifact: ImportedModuleView,
    binding: PlatformRequiredBinding,
) Allocator.Error!void {
    switch (binding.value_use) {
        .procedure_value => {
            var found = false;
            for (relation_artifact.exported_procedure_bindings.bindings) |exported| {
                if (exported.binding.pattern != binding.app_value.pattern) continue;
                found = true;
                try appendImportedTemplateClosureArtifactKeys(allocator, keys, relation_artifact.exported_procedure_bindings.rowClosure(exported));
                for (relation_artifact.exported_procedure_templates.templates) |template| {
                    if (template.def == exported.binding.def) {
                        try appendImportedTemplateClosureArtifactKeys(allocator, keys, relation_artifact.exported_procedure_templates.rowClosure(template));
                    }
                }
            }
            if (!found) {
                checkedArtifactInvariant("platform relation dependency collection could not find exported app procedure binding", .{});
            }
        },
        .const_value => |const_use| {
            var found = false;
            for (relation_artifact.exported_const_templates.templates) |template| {
                if (template.pattern != binding.app_value.pattern) continue;
                if (!constRefEql(template.const_ref, const_use.const_use.const_ref)) continue;
                found = true;
                try appendImportedTemplateClosureArtifactKeys(allocator, keys, relation_artifact.exported_const_templates.rowClosure(template));
            }
            if (!found) {
                checkedArtifactInvariant("platform relation dependency collection could not find exported app const template", .{});
            }
        },
    }
}

fn checkedArtifactKeyFromArtifactRef(ref: canonical.ArtifactRef) CheckedModuleArtifactKey {
    return .{ .bytes = ref.bytes };
}

fn appendClosureArtifactKey(
    allocator: Allocator,
    keys: *std.ArrayList(CheckedModuleArtifactKey),
    key: CheckedModuleArtifactKey,
) Allocator.Error!void {
    for (keys.items) |existing| {
        if (checkedArtifactKeyEql(existing, key)) return;
    }
    try keys.append(allocator, key);
}

const ArtifactKeyAccumulator = UniqueList(CheckedModuleArtifactKey);

fn collectPublicApiDependencies(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *const canonical.CanonicalNameStore,
    module_identity: ModuleIdentity,
    artifact_key: CheckedModuleArtifactKey,
    exported_defs: []const CIR.Def.Idx,
    checked_type_publication: *const CheckedTypePublication,
    checked_types: *const CheckedTypeStore,
    checked_templates: *const CheckedProcedureTemplateTable,
    callable_eval_templates: *const CallableEvalTemplateTable,
    entry_wrappers: *const EntryWrapperTable,
    const_templates: *const ConstTemplateTable,
    resolved_value_refs: *const ResolvedValueRefTable,
    top_level_bindings: *const TopLevelProcedureBindingTable,
    platform_required_declarations: *const PlatformRequiredDeclarationTable,
    platform_required_bindings: *const PlatformRequiredBindingTable,
    imports: []const PublishImportArtifact,
    available_artifacts: []const ImportedModuleView,
    exported_procedure_templates: *const ExportedProcedureTemplateTable,
    exported_procedure_bindings: *const ExportedProcedureBindingTable,
    exported_const_templates: *const ExportedConstTemplateTable,
) Allocator.Error!PublicApiDependencies {
    var keys = ArtifactKeyAccumulator.empty;
    defer keys.deinit(allocator);
    var type_owner_keys = ArtifactKeyAccumulator.empty;
    defer type_owner_keys.deinit(allocator);

    var active_types = collections.DenseMap(CheckedTypeId, void).init(allocator);
    defer active_types.deinit();

    for (exported_defs) |def_idx| {
        const root = checked_type_publication.rootForSourceVar(module, module.defType(def_idx)) orelse {
            checkedArtifactInvariant("exported def type root was not published", .{});
        };
        try appendPublicApiTypeDependencies(
            allocator,
            names,
            module_identity,
            artifact_key,
            checked_types,
            root,
            &active_types,
            imports,
            available_artifacts,
            &keys,
            &type_owner_keys,
        );
    }

    // Platform requirement signatures are public API too: requirement
    // unification copies them into each app's store, so nominals they mention
    // (e.g. a hosted-interface type from a sibling module) must be reachable
    // through this artifact's type-owner dependencies (issue 9911).
    for (module.requiresTypes()) |required_type| {
        const root = checked_type_publication.rootForSourceVar(module, ModuleEnv.varFrom(required_type.type_anno)) orelse continue;
        try appendPublicApiTypeDependencies(
            allocator,
            names,
            module_identity,
            artifact_key,
            checked_types,
            root,
            &active_types,
            imports,
            available_artifacts,
            &keys,
            &type_owner_keys,
        );
    }

    try appendExposedTypeDeclarationPublicApiDependencies(
        allocator,
        module,
        names,
        module_identity,
        artifact_key,
        checked_type_publication,
        checked_types,
        imports,
        available_artifacts,
        &active_types,
        &keys,
        &type_owner_keys,
    );

    try appendPlatformRequiredDeclarationPublicApiDependencies(
        allocator,
        module,
        names,
        module_identity,
        artifact_key,
        checked_type_publication,
        checked_types,
        platform_required_declarations,
        imports,
        available_artifacts,
        &active_types,
        &keys,
        &type_owner_keys,
    );

    var closure_dependencies = PublicApiClosureDependencyCollector.init(
        allocator,
        artifact_key,
        imports,
        available_artifacts,
        checked_templates,
        callable_eval_templates,
        entry_wrappers,
        const_templates,
        resolved_value_refs,
        top_level_bindings,
        platform_required_bindings,
        &keys,
        &type_owner_keys,
    );
    defer closure_dependencies.deinit();

    try closure_dependencies.appendExportedProcedureTemplates(exported_procedure_templates);
    for (exported_procedure_bindings.bindings) |binding| {
        try closure_dependencies.appendClosure(exported_procedure_bindings.rowClosure(binding));
    }
    for (exported_const_templates.templates) |template| {
        try closure_dependencies.appendClosure(exported_const_templates.rowClosure(template));
    }

    const artifacts = try keys.toOwnedSlice(allocator);
    errdefer allocator.free(artifacts);
    const type_owner_artifacts = try type_owner_keys.toOwnedSlice(allocator);

    return .{
        .artifacts = artifacts,
        .type_owner_artifacts = type_owner_artifacts,
    };
}

fn appendExposedTypeDeclarationPublicApiDependencies(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *const canonical.CanonicalNameStore,
    module_identity: ModuleIdentity,
    artifact_key: CheckedModuleArtifactKey,
    checked_type_publication: *const CheckedTypePublication,
    checked_types: *const CheckedTypeStore,
    imports: []const PublishImportArtifact,
    available_artifacts: []const ImportedModuleView,
    active_types: *collections.DenseMap(CheckedTypeId, void),
    keys: *ArtifactKeyAccumulator,
    type_owner_keys: *ArtifactKeyAccumulator,
) Allocator.Error!void {
    const module_env = module.moduleEnvConst();
    var exposed_iter = module_env.common.exposed_items.iterator();
    while (exposed_iter.next()) |entry| {
        const raw_node_idx: u32 = entry.target.typeDeclNode() orelse continue;
        if (raw_node_idx >= module.nodeCount()) {
            checkedArtifactInvariant("exposed type item points at out-of-range node", .{});
        }

        const node_idx: CIR.Node.Idx = @enumFromInt(raw_node_idx);
        if (!isStatementNodeTag(module.nodeTag(node_idx))) continue;

        const statement_idx: CIR.Statement.Idx = @enumFromInt(raw_node_idx);
        switch (module.getStatement(statement_idx)) {
            .s_alias_decl => {},
            .s_nominal_decl => if (!localNominalDeclarationIsValid(module, statement_idx)) continue,
            .s_decl,
            .s_var,
            .s_var_uninitialized,
            .s_reassign,
            .s_crash,
            .s_dbg,
            .s_expr,
            .s_expect,
            .s_for,
            .s_while,
            .s_infinite_loop,
            .s_breakable_loop,
            .s_break,
            .s_return,
            .s_import,
            .s_where_alias_decl,
            .s_type_anno,
            .s_type_var_alias,
            .s_runtime_error,
            => continue,
        }

        const root = checked_type_publication.rootForSourceVar(module, ModuleEnv.varFrom(statement_idx)) orelse {
            checkedArtifactInvariant("exposed type declaration root was not published", .{});
        };
        try appendPublicApiTypeDependencies(
            allocator,
            names,
            module_identity,
            artifact_key,
            checked_types,
            root,
            active_types,
            imports,
            available_artifacts,
            keys,
            type_owner_keys,
        );
    }
}

fn appendPlatformRequiredDeclarationPublicApiDependencies(
    allocator: Allocator,
    module: TypedCIR.Module,
    names: *const canonical.CanonicalNameStore,
    module_identity: ModuleIdentity,
    artifact_key: CheckedModuleArtifactKey,
    checked_type_publication: *const CheckedTypePublication,
    checked_types: *const CheckedTypeStore,
    platform_required_declarations: *const PlatformRequiredDeclarationTable,
    imports: []const PublishImportArtifact,
    available_artifacts: []const ImportedModuleView,
    active_types: *collections.DenseMap(CheckedTypeId, void),
    keys: *ArtifactKeyAccumulator,
    type_owner_keys: *ArtifactKeyAccumulator,
) Allocator.Error!void {
    for (platform_required_declarations.declarations) |declaration| {
        const root = platformRequiredPayloadForDeclaration(module, checked_type_publication, declaration);
        try appendPublicApiTypeDependencies(
            allocator,
            names,
            module_identity,
            artifact_key,
            checked_types,
            root,
            active_types,
            imports,
            available_artifacts,
            keys,
            type_owner_keys,
        );
    }
}

fn appendPublicApiTypeDependencies(
    allocator: Allocator,
    names: *const canonical.CanonicalNameStore,
    module_identity: ModuleIdentity,
    artifact_key: CheckedModuleArtifactKey,
    checked_types: *const CheckedTypeStore,
    root: CheckedTypeId,
    active: *collections.DenseMap(CheckedTypeId, void),
    imports: []const PublishImportArtifact,
    available_artifacts: []const ImportedModuleView,
    keys: *ArtifactKeyAccumulator,
    type_owner_keys: *ArtifactKeyAccumulator,
) Allocator.Error!void {
    const index: usize = @intFromEnum(root);
    if (index >= checked_types.payloads.items.len) {
        checkedArtifactInvariant("public API dependency scan referenced a missing checked type payload", .{});
    }
    if (active.contains(root)) return;
    try active.put(root, {});
    defer _ = active.remove(root);

    switch (checked_types.payload(@enumFromInt(index))) {
        .pending => checkedArtifactInvariant("public API dependency scan reached pending checked type payload", .{}),
        .err, .empty_record, .empty_tag_union => {},
        .flex => |flex| try appendPublicApiConstraintDependencies(
            allocator,
            names,
            module_identity,
            artifact_key,
            checked_types,
            flex.constraints,
            active,
            imports,
            available_artifacts,
            keys,
            type_owner_keys,
        ),
        .rigid => |rigid| try appendPublicApiConstraintDependencies(
            allocator,
            names,
            module_identity,
            artifact_key,
            checked_types,
            rigid.constraints,
            active,
            imports,
            available_artifacts,
            keys,
            type_owner_keys,
        ),
        .alias => |alias| {
            try appendPublicApiOwnerDependency(
                allocator,
                artifact_key,
                alias.owner_module,
                imports,
                available_artifacts,
                keys,
                type_owner_keys,
            );
            try appendPublicApiTypeDependencies(allocator, names, module_identity, artifact_key, checked_types, alias.backing, active, imports, available_artifacts, keys, type_owner_keys);
            try appendPublicApiTypeDependencyRange(allocator, names, module_identity, artifact_key, checked_types, alias.args, active, imports, available_artifacts, keys, type_owner_keys);
        },
        .nominal => |nominal| {
            try appendPublicApiOwnerDependency(
                allocator,
                artifact_key,
                nominal.owner_module,
                imports,
                available_artifacts,
                keys,
                type_owner_keys,
            );
            if (checked_types.nominalBackingTemplateForPayload(nominal)) |backing| {
                try appendPublicApiTypeDependencies(allocator, names, module_identity, artifact_key, checked_types, backing, active, imports, available_artifacts, keys, type_owner_keys);
            }
            try appendPublicApiTypeDependencyRange(allocator, names, module_identity, artifact_key, checked_types, nominal.args, active, imports, available_artifacts, keys, type_owner_keys);
        },
        .record => |record| {
            for (record.fields) |field| {
                try appendPublicApiTypeDependencies(allocator, names, module_identity, artifact_key, checked_types, field.ty, active, imports, available_artifacts, keys, type_owner_keys);
            }
            try appendPublicApiTypeDependencies(allocator, names, module_identity, artifact_key, checked_types, record.ext, active, imports, available_artifacts, keys, type_owner_keys);
        },
        .record_unbound => |fields| {
            for (fields) |field| {
                try appendPublicApiTypeDependencies(allocator, names, module_identity, artifact_key, checked_types, field.ty, active, imports, available_artifacts, keys, type_owner_keys);
            }
        },
        .tuple => |items| try appendPublicApiTypeDependencyRange(allocator, names, module_identity, artifact_key, checked_types, items, active, imports, available_artifacts, keys, type_owner_keys),
        .function => |function| {
            try appendPublicApiTypeDependencyRange(allocator, names, module_identity, artifact_key, checked_types, function.args, active, imports, available_artifacts, keys, type_owner_keys);
            try appendPublicApiTypeDependencies(allocator, names, module_identity, artifact_key, checked_types, function.ret, active, imports, available_artifacts, keys, type_owner_keys);
        },
        .tag_union => |tag_union| {
            for (tag_union.tags) |tag| {
                try appendPublicApiTypeDependencyRange(allocator, names, module_identity, artifact_key, checked_types, tag.argsSlice(checked_types), active, imports, available_artifacts, keys, type_owner_keys);
            }
            try appendPublicApiTypeDependencies(allocator, names, module_identity, artifact_key, checked_types, tag_union.ext, active, imports, available_artifacts, keys, type_owner_keys);
        },
    }
}

fn appendPublicApiConstraintDependencies(
    allocator: Allocator,
    names: *const canonical.CanonicalNameStore,
    module_identity: ModuleIdentity,
    artifact_key: CheckedModuleArtifactKey,
    checked_types: *const CheckedTypeStore,
    constraints: []const CheckedStaticDispatchConstraint,
    active: *collections.DenseMap(CheckedTypeId, void),
    imports: []const PublishImportArtifact,
    available_artifacts: []const ImportedModuleView,
    keys: *ArtifactKeyAccumulator,
    type_owner_keys: *ArtifactKeyAccumulator,
) Allocator.Error!void {
    for (constraints) |constraint| {
        try appendPublicApiTypeDependencies(allocator, names, module_identity, artifact_key, checked_types, constraint.fn_ty, active, imports, available_artifacts, keys, type_owner_keys);
    }
}

fn appendPublicApiTypeDependencyRange(
    allocator: Allocator,
    names: *const canonical.CanonicalNameStore,
    module_identity: ModuleIdentity,
    artifact_key: CheckedModuleArtifactKey,
    checked_types: *const CheckedTypeStore,
    roots: []const CheckedTypeId,
    active: *collections.DenseMap(CheckedTypeId, void),
    imports: []const PublishImportArtifact,
    available_artifacts: []const ImportedModuleView,
    keys: *ArtifactKeyAccumulator,
    type_owner_keys: *ArtifactKeyAccumulator,
) Allocator.Error!void {
    for (roots) |child| {
        try appendPublicApiTypeDependencies(allocator, names, module_identity, artifact_key, checked_types, child, active, imports, available_artifacts, keys, type_owner_keys);
    }
}

fn appendPublicApiOwnerDependency(
    allocator: Allocator,
    artifact_key: CheckedModuleArtifactKey,
    owner_key: CheckedModuleArtifactKey,
    imports: []const PublishImportArtifact,
    available_artifacts: []const ImportedModuleView,
    keys: *ArtifactKeyAccumulator,
    type_owner_keys: *ArtifactKeyAccumulator,
) Allocator.Error!void {
    if (checkedArtifactKeyEql(owner_key, artifact_key)) return;
    if (publicApiDependencyKeyIsKnownBuiltin(owner_key, imports, available_artifacts)) return;
    _ = try keys.append(allocator, owner_key);
    _ = try type_owner_keys.append(allocator, owner_key);
}

fn importedViewIdentityMatches(view: ImportedModuleView, origin_hash: *const [32]u8) bool {
    return base.ModuleIdentity.eql(&view.module_identity.stable_hash, origin_hash);
}

fn appendPublicApiClosureDependencyKey(
    allocator: Allocator,
    artifact_key: CheckedModuleArtifactKey,
    imports: []const PublishImportArtifact,
    available_artifacts: []const ImportedModuleView,
    keys: *ArtifactKeyAccumulator,
    key: CheckedModuleArtifactKey,
) Allocator.Error!void {
    if (checkedArtifactKeyEql(key, artifact_key)) return;
    if (publicApiDependencyKeyIsKnownBuiltin(key, imports, available_artifacts)) return;
    _ = try keys.append(allocator, key);
}

fn publicApiDependencyKeyIsKnownBuiltin(
    key: CheckedModuleArtifactKey,
    imports: []const PublishImportArtifact,
    available_artifacts: []const ImportedModuleView,
) bool {
    if (publicApiDependencyViewByKey(key, imports, available_artifacts)) |view| {
        return view.module_env.module_role == .builtin;
    }
    return false;
}

const PublicApiClosureDependencyCollector = struct {
    allocator: Allocator,
    artifact_key: CheckedModuleArtifactKey,
    imports: []const PublishImportArtifact,
    available_artifacts: []const ImportedModuleView,
    checked_templates: *const CheckedProcedureTemplateTable,
    callable_eval_templates: *const CallableEvalTemplateTable,
    entry_wrappers: *const EntryWrapperTable,
    const_templates: *const ConstTemplateTable,
    resolved_value_refs: *const ResolvedValueRefTable,
    top_level_bindings: *const TopLevelProcedureBindingTable,
    platform_required_bindings: *const PlatformRequiredBindingTable,
    keys: *ArtifactKeyAccumulator,
    type_owner_keys: *ArtifactKeyAccumulator,
    visited_templates: std.AutoHashMap(canonical.ProcedureTemplateRef, void),
    visited_consts: std.AutoHashMap(ConstRef, void),
    visited_callable_eval_templates: std.AutoHashMap(ArtifactCallableEvalTemplateRef, void),

    fn init(
        allocator: Allocator,
        artifact_key: CheckedModuleArtifactKey,
        imports: []const PublishImportArtifact,
        available_artifacts: []const ImportedModuleView,
        checked_templates: *const CheckedProcedureTemplateTable,
        callable_eval_templates: *const CallableEvalTemplateTable,
        entry_wrappers: *const EntryWrapperTable,
        const_templates: *const ConstTemplateTable,
        resolved_value_refs: *const ResolvedValueRefTable,
        top_level_bindings: *const TopLevelProcedureBindingTable,
        platform_required_bindings: *const PlatformRequiredBindingTable,
        keys: *ArtifactKeyAccumulator,
        type_owner_keys: *ArtifactKeyAccumulator,
    ) PublicApiClosureDependencyCollector {
        return .{
            .allocator = allocator,
            .artifact_key = artifact_key,
            .imports = imports,
            .available_artifacts = available_artifacts,
            .checked_templates = checked_templates,
            .callable_eval_templates = callable_eval_templates,
            .entry_wrappers = entry_wrappers,
            .const_templates = const_templates,
            .resolved_value_refs = resolved_value_refs,
            .top_level_bindings = top_level_bindings,
            .platform_required_bindings = platform_required_bindings,
            .keys = keys,
            .type_owner_keys = type_owner_keys,
            .visited_templates = std.AutoHashMap(canonical.ProcedureTemplateRef, void).init(allocator),
            .visited_consts = std.AutoHashMap(ConstRef, void).init(allocator),
            .visited_callable_eval_templates = std.AutoHashMap(ArtifactCallableEvalTemplateRef, void).init(allocator),
        };
    }

    fn deinit(self: *PublicApiClosureDependencyCollector) void {
        self.visited_callable_eval_templates.deinit();
        self.visited_consts.deinit();
        self.visited_templates.deinit();
    }

    fn appendExportedProcedureTemplates(
        self: *PublicApiClosureDependencyCollector,
        exported_procedure_templates: *const ExportedProcedureTemplateTable,
    ) Allocator.Error!void {
        for (exported_procedure_templates.templates) |template| {
            try self.appendClosure(exported_procedure_templates.rowClosure(template));
        }
    }

    fn appendClosure(
        self: *PublicApiClosureDependencyCollector,
        closure: ImportedTemplateClosureView,
    ) Allocator.Error!void {
        for (closure.checked_bodies) |value| try self.appendArtifactKey(value.artifact);
        for (closure.checked_type_roots) |value| {
            try self.appendArtifactKey(value.artifact);
            try self.appendTypeOwnerArtifactKey(value.artifact);
        }
        for (closure.checked_type_schemes) |value| {
            try self.appendArtifactKey(value.artifact);
            try self.appendTypeOwnerArtifactKey(value.artifact);
        }
        for (closure.checked_callable_bodies) |value| try self.appendArtifactKey(value.artifact);
        for (closure.checked_const_bodies) |value| try self.appendArtifactKey(value.artifact);
        for (closure.checked_procedure_templates) |value| try self.appendProcedureTemplateRef(value);
        for (closure.callable_eval_templates) |value| try self.appendCallableEvalTemplateRef(value);
        for (closure.const_templates) |value| try self.appendConstRef(value);
        for (closure.nested_proc_sites) |value| try self.appendArtifactKey(value.artifact);
        for (closure.resolved_value_refs) |value| try self.appendArtifactKey(value.artifact);
        for (closure.static_dispatch_plans) |value| try self.appendArtifactKey(value.artifact);
        for (closure.interface_capabilities) |value| try self.appendArtifactKey(value.artifact);
    }

    fn appendArtifactKey(
        self: *PublicApiClosureDependencyCollector,
        key: CheckedModuleArtifactKey,
    ) Allocator.Error!void {
        try appendPublicApiClosureDependencyKey(
            self.allocator,
            self.artifact_key,
            self.imports,
            self.available_artifacts,
            self.keys,
            key,
        );
    }

    fn appendTypeOwnerArtifactKey(
        self: *PublicApiClosureDependencyCollector,
        key: CheckedModuleArtifactKey,
    ) Allocator.Error!void {
        try appendPublicApiClosureDependencyKey(
            self.allocator,
            self.artifact_key,
            self.imports,
            self.available_artifacts,
            self.type_owner_keys,
            key,
        );
    }

    fn appendProcedureTemplateRef(
        self: *PublicApiClosureDependencyCollector,
        template_ref: canonical.ProcedureTemplateRef,
    ) Allocator.Error!void {
        const key = checkedArtifactKeyFromArtifactRef(template_ref.artifact);
        try self.appendArtifactKey(key);
        if (!checkedArtifactKeyEql(key, self.artifact_key)) return;

        const entry = try self.visited_templates.getOrPut(template_ref);
        if (entry.found_existing) return;
        entry.value_ptr.* = {};

        const index: usize = @intFromEnum(template_ref.template);
        if (index >= self.checked_templates.templates.len) {
            checkedArtifactInvariant("public API closure dependency referenced missing local procedure template", .{});
        }
        const template = self.checked_templates.get(template_ref.template);
        if (template.proc_base != template_ref.proc_base) {
            checkedArtifactInvariant("public API closure dependency procedure template ref disagreed with template row", .{});
        }
        try self.appendResolvedValueRefs(template.resolved_value_refs);
    }

    fn appendCallableEvalTemplateRef(
        self: *PublicApiClosureDependencyCollector,
        template_ref: ArtifactCallableEvalTemplateRef,
    ) Allocator.Error!void {
        try self.appendArtifactKey(template_ref.artifact);
        if (!checkedArtifactKeyEql(template_ref.artifact, self.artifact_key)) return;

        const entry = try self.visited_callable_eval_templates.getOrPut(template_ref);
        if (entry.found_existing) return;
        entry.value_ptr.* = {};

        const index: usize = @intFromEnum(template_ref.template);
        if (index >= self.callable_eval_templates.templates.len) {
            checkedArtifactInvariant("public API closure dependency referenced missing callable-eval template", .{});
        }
        const template = self.callable_eval_templates.get(template_ref.template);
        const wrapper = entryWrapperForRoot(self.entry_wrappers, template.root);
        try self.appendProcedureTemplateRef(wrapper.template);
    }

    fn appendConstRef(
        self: *PublicApiClosureDependencyCollector,
        const_ref: ConstRef,
    ) Allocator.Error!void {
        try self.appendArtifactKey(const_ref.artifact);
        if (!checkedArtifactKeyEql(const_ref.artifact, self.artifact_key)) return;

        const entry = try self.visited_consts.getOrPut(const_ref);
        if (entry.found_existing) return;
        entry.value_ptr.* = {};

        const template = self.const_templates.get(const_ref);
        switch (template.state) {
            .eval_template => |eval| {
                try self.appendResolvedValueRefs(eval.resolved_value_refs);
                try self.appendProcedureTemplateRef(eval.entry_template);
            },
            .stored_const => {},
            .reserved => checkedArtifactInvariant("public API closure dependency reached unsealed const template", .{}),
        }
    }

    fn appendResolvedValueRefs(
        self: *PublicApiClosureDependencyCollector,
        table: ResolvedValueRefTableRef,
    ) Allocator.Error!void {
        const end = table.start + table.len;
        if (end > self.resolved_value_refs.template_refs.len) {
            checkedArtifactInvariant("public API closure resolved-ref span was outside table", .{});
        }
        for (self.resolved_value_refs.template_refs[table.start..end]) |ref_id| {
            const raw = @intFromEnum(ref_id);
            if (raw >= self.resolved_value_refs.records.len) {
                checkedArtifactInvariant("public API closure resolved-ref id was outside table", .{});
            }
            try self.appendResolvedValueRef(self.resolved_value_refs.records[raw].ref);
        }
    }

    fn appendResolvedValueRef(
        self: *PublicApiClosureDependencyCollector,
        ref: ResolvedValueRef,
    ) Allocator.Error!void {
        switch (ref) {
            .top_level_const,
            .imported_const,
            => |const_use| try self.appendConstRef(const_use.const_ref),
            .selected_hoisted_const => |selected| try self.appendConstRef(selected.const_use.const_ref),
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .promoted_top_level_proc,
            => |procedure| try self.appendProcedureUse(procedure),
            .platform_required_const => |required| {
                try self.appendConstRef(required.const_use.const_ref);
                try self.appendPlatformRequiredBindingClosure(required.binding);
            },
            .platform_required_proc => |required| {
                try self.appendProcedureUse(required.procedure);
                try self.appendPlatformRequiredBindingClosure(required.binding);
            },
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            .local_proc,
            .platform_required_declaration,
            .platform_required_checked_error,
            => {},
        }
    }

    fn appendProcedureUse(
        self: *PublicApiClosureDependencyCollector,
        procedure: ProcedureUseTemplate,
    ) Allocator.Error!void {
        switch (procedure.binding) {
            .top_level => |top_level| try self.appendTopLevelProcedureBinding(top_level),
            .imported => |imported| try self.appendArtifactKey(imported.artifact),
            .hosted => |hosted| try self.appendProcedureTemplateRef(hosted.template),
            .platform_required => |required| try self.appendArtifactKey(required.artifact),
        }
    }

    fn appendTopLevelProcedureBinding(
        self: *PublicApiClosureDependencyCollector,
        binding_ref: ArtifactTopLevelProcedureBindingRef,
    ) Allocator.Error!void {
        try self.appendArtifactKey(binding_ref.artifact);
        if (!checkedArtifactKeyEql(binding_ref.artifact, self.artifact_key)) return;

        const binding = self.top_level_bindings.get(binding_ref.binding);
        try self.appendProcedureBindingBody(binding.body);
    }

    fn appendProcedureBindingBody(
        self: *PublicApiClosureDependencyCollector,
        body: ProcedureBindingBody,
    ) Allocator.Error!void {
        switch (body) {
            .direct_template => |direct| try self.appendCallableProcedureTemplateRef(direct.template),
            .callable_eval_template => |template| try self.appendCallableEvalTemplateRef(.{
                .artifact = self.artifact_key,
                .template = template,
            }),
        }
    }

    fn appendCallableProcedureTemplateRef(
        self: *PublicApiClosureDependencyCollector,
        template: canonical.CallableProcedureTemplateRef,
    ) Allocator.Error!void {
        switch (template) {
            .checked => |checked| try self.appendProcedureTemplateRef(checked),
            .synthetic => |synthetic| try self.appendProcedureTemplateRef(synthetic.template),
            .lifted => checkedArtifactInvariant("public API closure reached lifted procedure template before mono", .{}),
        }
    }

    fn appendPlatformRequiredBindingClosure(
        self: *PublicApiClosureDependencyCollector,
        binding_id: PlatformRequiredBindingId,
    ) Allocator.Error!void {
        const binding = self.platform_required_bindings.lookupByBindingId(@intFromEnum(binding_id)) orelse {
            checkedArtifactInvariant("public API closure referenced missing platform-required binding", .{});
        };
        try self.appendClosure(self.platform_required_bindings.relationClosure(binding));
    }
};

const LoweringVisibilityTypeVisit = struct {
    artifact: [32]u8,
    ty: u32,
};

const LoweringVisibilityBuilder = struct {
    allocator: Allocator,
    artifact_key: CheckedModuleArtifactKey,
    checked_types: *const CheckedTypeStore,
    imports: []const PublishImportArtifact,
    available_artifacts: []const ImportedModuleView,
    relation_artifacts: []const ImportedModuleView,
    keys: ArtifactKeyAccumulator = .empty,
    active_types: std.AutoHashMap(LoweringVisibilityTypeVisit, void),
    visited_public_api: std.AutoHashMap(CheckedModuleArtifactKey, void),

    fn init(
        allocator: Allocator,
        artifact_key: CheckedModuleArtifactKey,
        checked_types: *const CheckedTypeStore,
        imports: []const PublishImportArtifact,
        available_artifacts: []const ImportedModuleView,
        relation_artifacts: []const ImportedModuleView,
    ) LoweringVisibilityBuilder {
        return .{
            .allocator = allocator,
            .artifact_key = artifact_key,
            .checked_types = checked_types,
            .imports = imports,
            .available_artifacts = available_artifacts,
            .relation_artifacts = relation_artifacts,
            .active_types = std.AutoHashMap(LoweringVisibilityTypeVisit, void).init(allocator),
            .visited_public_api = std.AutoHashMap(CheckedModuleArtifactKey, void).init(allocator),
        };
    }

    fn deinit(self: *LoweringVisibilityBuilder) void {
        self.visited_public_api.deinit();
        self.active_types.deinit();
        self.keys.deinit(self.allocator);
    }

    fn finish(self: *LoweringVisibilityBuilder) Allocator.Error!LoweringVisibility {
        std.mem.sort(CheckedModuleArtifactKey, self.keys.items.items, {}, checkedArtifactKeyLessThan);
        return .{ .module_ids = try self.keys.toOwnedSlice(self.allocator) };
    }

    fn appendKey(self: *LoweringVisibilityBuilder, key: CheckedModuleArtifactKey) Allocator.Error!void {
        if (checkedArtifactKeyEql(key, self.artifact_key)) return;
        if (self.viewByKey(key)) |view| {
            if (view.module_env.module_role == .builtin) return;
        }

        _ = try self.keys.append(self.allocator, key);
        try self.appendPublicApiDependenciesForKey(key);
    }

    fn appendPublicApiDependenciesForKey(self: *LoweringVisibilityBuilder, key: CheckedModuleArtifactKey) Allocator.Error!void {
        if (checkedArtifactKeyEql(key, self.artifact_key)) return;
        const entry = try self.visited_public_api.getOrPut(key);
        if (entry.found_existing) return;
        entry.value_ptr.* = {};

        const view = self.viewByKey(key) orelse {
            checkedArtifactInvariant("lowering visibility referenced a checked artifact not available to publication", .{});
        };
        for (view.public_api_dependencies.artifacts) |dependency| try self.appendKey(dependency);
        for (view.public_api_dependencies.type_owner_artifacts) |dependency| try self.appendKey(dependency);
        for (view.method_lookup_scope) |dependency| try self.appendKey(dependency);
    }

    fn appendRootRequest(self: *LoweringVisibilityBuilder, request: RootRequest) Allocator.Error!void {
        try self.appendTypeRoot(self.artifact_key, request.checked_type);
    }

    fn appendTypeRoot(self: *LoweringVisibilityBuilder, artifact: CheckedModuleArtifactKey, root: CheckedTypeId) Allocator.Error!void {
        const visit = LoweringVisibilityTypeVisit{
            .artifact = artifact.bytes,
            .ty = @intFromEnum(root),
        };
        const entry = try self.active_types.getOrPut(visit);
        if (entry.found_existing) return;
        entry.value_ptr.* = {};
        defer _ = self.active_types.remove(visit);

        if (checkedArtifactKeyEql(artifact, self.artifact_key)) {
            try self.appendTypePayload(self.artifact_key, self.checked_types, root);
            return;
        }

        const view = self.viewByKey(artifact) orelse {
            checkedArtifactInvariant("lowering visibility type root referenced unavailable checked artifact", .{});
        };
        try self.appendKey(artifact);
        try self.appendTypePayload(artifact, view.checked_types, root);
    }

    fn appendTypePayload(
        self: *LoweringVisibilityBuilder,
        artifact: CheckedModuleArtifactKey,
        store: anytype,
        root: CheckedTypeId,
    ) Allocator.Error!void {
        const index: usize = @intFromEnum(root);
        if (index >= store.payloadCount()) {
            checkedArtifactInvariant("lowering visibility type traversal referenced a missing payload", .{});
        }
        switch (store.payload(root)) {
            .pending => checkedArtifactInvariant("lowering visibility type traversal reached pending payload", .{}),
            .err, .empty_record, .empty_tag_union => {},
            .flex => |flex| try self.appendConstraintTypes(artifact, flex.constraints),
            .rigid => |rigid| try self.appendConstraintTypes(artifact, rigid.constraints),
            .alias => |alias| {
                try self.appendKey(alias.owner_module);
                try self.appendTypeRoot(artifact, alias.backing);
                try self.appendTypeRoots(artifact, alias.args);
            },
            .nominal => |nominal| {
                try self.appendKey(nominal.owner_module);
                if (store.nominalBackingTemplateForPayload(nominal)) |backing| {
                    try self.appendTypeRoot(artifact, backing);
                }
                try self.appendTypeRoots(artifact, nominal.args);
                try self.appendTypeRoots(artifact, nominal.padding_field_types);
            },
            .record => |record| {
                for (record.fields) |field| {
                    if (field.kind.undeterminedVariable()) |variable| try self.appendTypeRoot(artifact, variable);
                    try self.appendTypeRoot(artifact, field.ty);
                }
                try self.appendTypeRoot(artifact, record.ext);
            },
            .record_unbound => |fields| {
                for (fields) |field| {
                    if (field.kind.undeterminedVariable()) |variable| try self.appendTypeRoot(artifact, variable);
                    try self.appendTypeRoot(artifact, field.ty);
                }
            },
            .tuple => |items| try self.appendTypeRoots(artifact, items),
            .function => |function| {
                try self.appendTypeRoots(artifact, function.args);
                try self.appendTypeRoot(artifact, function.ret);
            },
            .tag_union => |tag_union| {
                for (tag_union.tags) |tag| try self.appendTypeRoots(artifact, tag.argsSlice(store));
                try self.appendTypeRoot(artifact, tag_union.ext);
            },
        }
    }

    fn appendConstraintTypes(
        self: *LoweringVisibilityBuilder,
        artifact: CheckedModuleArtifactKey,
        constraints: []const CheckedStaticDispatchConstraint,
    ) Allocator.Error!void {
        for (constraints) |constraint| try self.appendTypeRoot(artifact, constraint.fn_ty);
    }

    fn appendTypeRoots(
        self: *LoweringVisibilityBuilder,
        artifact: CheckedModuleArtifactKey,
        roots: []const CheckedTypeId,
    ) Allocator.Error!void {
        for (roots) |root| try self.appendTypeRoot(artifact, root);
    }

    fn viewByKey(self: *LoweringVisibilityBuilder, key: CheckedModuleArtifactKey) ?ImportedModuleView {
        return dependencyViewByKey(key, self.imports, self.available_artifacts, self.relation_artifacts);
    }
};

fn collectLoweringVisibility(
    allocator: Allocator,
    artifact_key: CheckedModuleArtifactKey,
    direct_import_artifact_keys: []const CheckedModuleArtifactKey,
    method_lookup_scope: MethodLookupScope,
    public_api_dependencies: PublicApiDependencies,
    checked_types: *const CheckedTypeStore,
    checked_templates: *const CheckedProcedureTemplateTable,
    callable_eval_templates: *const CallableEvalTemplateTable,
    entry_wrappers: *const EntryWrapperTable,
    const_templates: *const ConstTemplateTable,
    resolved_value_refs: *const ResolvedValueRefTable,
    top_level_bindings: *const TopLevelProcedureBindingTable,
    platform_required_bindings: *const PlatformRequiredBindingTable,
    root_requests: *const RootRequestTable,
    imports: []const PublishImportArtifact,
    available_artifacts: []const ImportedModuleView,
    relation_artifacts: []const ImportedModuleView,
    exported_procedure_templates: *const ExportedProcedureTemplateTable,
    exported_procedure_bindings: *const ExportedProcedureBindingTable,
    exported_const_templates: *const ExportedConstTemplateTable,
) Allocator.Error!LoweringVisibility {
    var builder = LoweringVisibilityBuilder.init(
        allocator,
        artifact_key,
        checked_types,
        imports,
        available_artifacts,
        relation_artifacts,
    );
    defer builder.deinit();

    for (direct_import_artifact_keys) |key| try builder.appendKey(key);
    for (method_lookup_scope.module_ids) |key| try builder.appendKey(key);
    for (public_api_dependencies.artifacts) |key| try builder.appendKey(key);
    for (public_api_dependencies.type_owner_artifacts) |key| try builder.appendKey(key);
    for (root_requests.requests) |request| try builder.appendRootRequest(request);

    var closure_dependencies = PublicApiClosureDependencyCollector.init(
        allocator,
        artifact_key,
        imports,
        available_artifacts,
        checked_templates,
        callable_eval_templates,
        entry_wrappers,
        const_templates,
        resolved_value_refs,
        top_level_bindings,
        platform_required_bindings,
        &builder.keys,
        &builder.keys,
    );
    defer closure_dependencies.deinit();

    for (root_requests.requests) |request| {
        if (request.procedure_template) |template| try closure_dependencies.appendProcedureTemplateRef(template);
        if (request.procedure_binding) |binding| try closure_dependencies.appendTopLevelProcedureBinding(.{
            .artifact = artifact_key,
            .binding = binding,
        });
        if (request.procedure_use) |procedure| try closure_dependencies.appendProcedureUse(procedure);
    }

    try closure_dependencies.appendExportedProcedureTemplates(exported_procedure_templates);
    for (exported_procedure_bindings.bindings) |binding| {
        try closure_dependencies.appendClosure(exported_procedure_bindings.rowClosure(binding));
    }
    for (exported_const_templates.templates) |template| {
        try closure_dependencies.appendClosure(exported_const_templates.rowClosure(template));
    }

    for (platform_required_bindings.bindings) |binding| {
        const relation_view = dependencyViewByKey(binding.app_value.artifact, imports, available_artifacts, relation_artifacts) orelse {
            checkedArtifactInvariant("lowering visibility relation binding referenced unavailable relation artifact", .{});
        };
        var relation_keys = std.ArrayList(CheckedModuleArtifactKey).empty;
        defer relation_keys.deinit(allocator);
        try appendPlatformRelationDependencyArtifactKeysFromView(
            allocator,
            &relation_keys,
            relation_view,
            binding,
            platform_required_bindings.relationClosure(binding),
        );
        for (relation_keys.items) |key| try builder.appendKey(key);
    }

    var visibility_index: usize = 0;
    while (visibility_index < builder.keys.items.items.len) : (visibility_index += 1) {
        try builder.appendPublicApiDependenciesForKey(builder.keys.items.items[visibility_index]);
    }

    return try builder.finish();
}

fn publicApiDependencyViewByKey(
    key: CheckedModuleArtifactKey,
    imports: []const PublishImportArtifact,
    available_artifacts: []const ImportedModuleView,
) ?ImportedModuleView {
    return dependencyViewByKey(key, imports, available_artifacts, &.{});
}

fn dependencyViewByKey(
    key: CheckedModuleArtifactKey,
    imports: []const PublishImportArtifact,
    available_artifacts: []const ImportedModuleView,
    relation_artifacts: []const ImportedModuleView,
) ?ImportedModuleView {
    for (imports) |import_artifact| {
        if (checkedArtifactKeyEql(import_artifact.key, key)) return import_artifact.view;
    }
    for (available_artifacts) |view| {
        if (checkedArtifactKeyEql(view.key, key)) return view;
    }
    for (relation_artifacts) |view| {
        if (checkedArtifactKeyEql(view.key, key)) return view;
    }
    return null;
}

/// Public `ExportedProcedureTemplate` declaration.
pub const ExportedProcedureTemplate = struct {
    export_name: ?canonical.ExportNameId,
    def: CIR.Def.Idx,
    source_scheme: canonical.CanonicalTypeSchemeKey,
    template: canonical.ProcedureTemplateRef,
    template_data: CheckedProcedureTemplate,
    template_closure: StoredImportedTemplateClosure = .{},
};

/// Public `ExportedProcedureTemplateView` declaration.
pub const ExportedProcedureTemplateView = struct {
    templates: []const ExportedProcedureTemplate = &.{},
    closure_pool: *const ClosurePool = &empty_closure_pool,

    /// Materialize a row's imported template closure from the backing pool.
    pub fn rowClosure(self: ExportedProcedureTemplateView, row: ExportedProcedureTemplate) ImportedTemplateClosureView {
        return self.closure_pool.reconstruct(row.template_closure);
    }
};

const empty_closure_pool: ClosurePool = ClosurePool.empty;

/// Public `ExportedProcedureTemplateTable` declaration.
pub const ExportedProcedureTemplateTable = struct {
    templates: []ExportedProcedureTemplate = &.{},
    closure_pool: ClosurePool = ClosurePool.empty,

    pub fn fromModule(
        allocator: Allocator,
        module: TypedCIR.Module,
        published_exports: []const CIR.Def.Idx,
        names: *canonical.CanonicalNameStore,
        artifact_key: CheckedModuleArtifactKey,
        checked_types: *const CheckedTypeStore,
        checked_templates: *const CheckedProcedureTemplateTable,
        callable_eval_templates: *const CallableEvalTemplateTable,
        entry_wrappers: *const EntryWrapperTable,
        const_templates: *const ConstTemplateTable,
        resolved_value_refs: *const ResolvedValueRefTable,
        top_level_bindings: *const TopLevelProcedureBindingTable,
        platform_required_bindings: *const PlatformRequiredBindingTable,
        imports: []const PublishImportArtifact,
        available_artifacts: []const ImportedModuleView,
    ) Allocator.Error!ExportedProcedureTemplateTable {
        var templates = std.ArrayList(ExportedProcedureTemplate).empty;
        var closure_pool = ClosurePool.empty;
        errdefer {
            templates.deinit(allocator);
            closure_pool.deinit(allocator);
        }

        for (published_exports) |def_idx| {
            const template = checked_templates.lookupByDef(def_idx) orelse continue;
            const def = module.def(def_idx);
            const export_name = if (def.patternName()) |name|
                try names.internExportIdent(module.identStoreConst(), name)
            else
                null;
            const source_scheme = try canonical_type_keys.schemeFromVar(
                allocator,
                module.typeStoreConst(),
                module.moduleEnvConst(),
                module.defType(def_idx),
            );
            const template_data = checked_templates.get(template.template);
            var template_closure = try buildImportedTemplateClosure(
                allocator,
                artifact_key,
                checked_types,
                checked_templates,
                callable_eval_templates,
                entry_wrappers,
                const_templates,
                resolved_value_refs,
                top_level_bindings,
                platform_required_bindings,
                imports,
                available_artifacts,
                template,
                template_data,
            );
            errdefer deinitImportedTemplateClosure(allocator, &template_closure);

            const stored_closure = try closure_pool.commit(allocator, template_closure);
            template_closure = .{};

            try templates.append(allocator, .{
                .export_name = export_name,
                .def = def_idx,
                .source_scheme = source_scheme,
                .template = template,
                .template_data = template_data,
                .template_closure = stored_closure,
            });
        }

        return .{
            .templates = try templates.toOwnedSlice(allocator),
            .closure_pool = closure_pool,
        };
    }

    pub fn view(self: *const ExportedProcedureTemplateTable) ExportedProcedureTemplateView {
        return .{ .templates = self.templates, .closure_pool = &self.closure_pool };
    }

    /// Materialize a row's imported template closure from this table's pool.
    pub fn rowClosure(self: *const ExportedProcedureTemplateTable, row: ExportedProcedureTemplate) ImportedTemplateClosureView {
        return self.view().rowClosure(row);
    }

    pub fn deinit(self: *ExportedProcedureTemplateTable, allocator: Allocator) void {
        if (!self.closure_pool.serialized) allocator.free(self.templates);
        self.closure_pool.deinit(allocator);
        self.* = .{};
    }

    /// Relocatable serialized form: the POD row slice plus the closure pool.
    pub const Serialized = extern struct {
        templates: SerializedSlice(ExportedProcedureTemplate) = .{},
        closure_pool: ClosurePool.Serialized = .{},

        comptime {
            std.debug.assert(artifact_serialize.relocatablePointerCount(Serialized) == 14);
        }

        const Serde = artifact_serialize.SliceStoreSerde(ExportedProcedureTemplateTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };
};

fn buildImportedTemplateClosure(
    allocator: Allocator,
    artifact_key: CheckedModuleArtifactKey,
    checked_types: *const CheckedTypeStore,
    checked_templates: *const CheckedProcedureTemplateTable,
    callable_eval_templates: *const CallableEvalTemplateTable,
    entry_wrappers: *const EntryWrapperTable,
    const_templates: *const ConstTemplateTable,
    resolved_value_refs: *const ResolvedValueRefTable,
    top_level_bindings: *const TopLevelProcedureBindingTable,
    platform_required_bindings: *const PlatformRequiredBindingTable,
    imports: []const PublishImportArtifact,
    available_artifacts: []const ImportedModuleView,
    template_ref: canonical.ProcedureTemplateRef,
    template: CheckedProcedureTemplate,
) Allocator.Error!ImportedTemplateClosureView {
    var builder = ImportedTemplateClosureBuilder.init(
        allocator,
        artifact_key,
        checked_types,
        checked_templates,
        callable_eval_templates,
        entry_wrappers,
        const_templates,
        resolved_value_refs,
        top_level_bindings,
        platform_required_bindings,
        imports,
        available_artifacts,
    );
    defer builder.deinit();

    try builder.appendInterfaceCapabilities(.{ .artifact = artifact_key });
    try builder.appendTemplate(template_ref, template);

    return .{
        .checked_bodies = try builder.checked_bodies.toOwnedSlice(allocator),
        .checked_type_roots = try builder.checked_type_roots.toOwnedSlice(allocator),
        .checked_type_schemes = try builder.checked_type_schemes.toOwnedSlice(allocator),
        .checked_callable_bodies = try builder.checked_callable_bodies.toOwnedSlice(allocator),
        .checked_const_bodies = try builder.checked_const_bodies.toOwnedSlice(allocator),
        .checked_procedure_templates = try builder.checked_procedure_templates.toOwnedSlice(allocator),
        .callable_eval_templates = try builder.callable_eval_templates.toOwnedSlice(allocator),
        .const_templates = try builder.const_templates.toOwnedSlice(allocator),
        .nested_proc_sites = try builder.nested_proc_sites.toOwnedSlice(allocator),
        .resolved_value_refs = try builder.resolved_value_refs.toOwnedSlice(allocator),
        .static_dispatch_plans = try builder.static_dispatch_plans.toOwnedSlice(allocator),
        .method_registry_entries = try builder.method_registry_entries.toOwnedSlice(allocator),
        .interface_capabilities = try builder.interface_capabilities.toOwnedSlice(allocator),
    };
}

fn UniqueList(comptime T: type) type {
    return struct {
        items: std.ArrayList(T) = .empty,
        seen: std.AutoHashMapUnmanaged(T, void) = .{},

        const Self = @This();
        const empty: Self = .{};

        fn append(self: *Self, allocator: Allocator, value: T) Allocator.Error!bool {
            const entry = try self.seen.getOrPut(allocator, value);
            if (entry.found_existing) return false;

            entry.value_ptr.* = {};
            errdefer _ = self.seen.remove(value);

            try self.items.append(allocator, value);
            return true;
        }

        fn toOwnedSlice(self: *Self, allocator: Allocator) Allocator.Error![]T {
            return try self.items.toOwnedSlice(allocator);
        }

        fn deinit(self: *Self, allocator: Allocator) void {
            self.seen.deinit(allocator);
            self.items.deinit(allocator);
            self.* = .{};
        }
    };
}

const ImportedTemplateClosureBuilder = struct {
    allocator: Allocator,
    artifact_key: CheckedModuleArtifactKey,
    checked_types: *const CheckedTypeStore,
    checked_templates: *const CheckedProcedureTemplateTable,
    callable_eval_template_table: *const CallableEvalTemplateTable,
    entry_wrappers: *const EntryWrapperTable,
    const_templates_table: *const ConstTemplateTable,
    resolved_value_refs_table: *const ResolvedValueRefTable,
    top_level_bindings: *const TopLevelProcedureBindingTable,
    platform_required_bindings: *const PlatformRequiredBindingTable,
    imports: []const PublishImportArtifact,
    available_artifacts: []const ImportedModuleView,
    checked_bodies: UniqueList(ArtifactCheckedBodyRef),
    checked_type_roots: UniqueList(ArtifactCheckedTypeRef),
    checked_type_schemes: UniqueList(ArtifactCheckedTypeSchemeRef),
    checked_callable_bodies: UniqueList(ArtifactCheckedCallableBodyRef),
    checked_const_bodies: UniqueList(ArtifactCheckedConstBodyRef),
    checked_procedure_templates: UniqueList(ArtifactProcedureTemplateRef),
    callable_eval_templates: UniqueList(ArtifactCallableEvalTemplateRef),
    const_templates: UniqueList(ConstRef),
    nested_proc_sites: UniqueList(ArtifactNestedProcSiteTableRef),
    resolved_value_refs: UniqueList(ArtifactResolvedValueRefTableRef),
    static_dispatch_plans: UniqueList(ArtifactStaticDispatchPlanTableRef),
    method_registry_entries: UniqueList(MethodRegistryEntryRef),
    interface_capabilities: UniqueList(ArtifactModuleInterfaceCapabilitiesRef),

    fn init(
        allocator: Allocator,
        artifact_key: CheckedModuleArtifactKey,
        checked_types: *const CheckedTypeStore,
        checked_templates: *const CheckedProcedureTemplateTable,
        callable_eval_templates: *const CallableEvalTemplateTable,
        entry_wrappers: *const EntryWrapperTable,
        const_templates: *const ConstTemplateTable,
        resolved_value_refs: *const ResolvedValueRefTable,
        top_level_bindings: *const TopLevelProcedureBindingTable,
        platform_required_bindings: *const PlatformRequiredBindingTable,
        imports: []const PublishImportArtifact,
        available_artifacts: []const ImportedModuleView,
    ) ImportedTemplateClosureBuilder {
        return .{
            .allocator = allocator,
            .artifact_key = artifact_key,
            .checked_types = checked_types,
            .checked_templates = checked_templates,
            .callable_eval_template_table = callable_eval_templates,
            .entry_wrappers = entry_wrappers,
            .const_templates_table = const_templates,
            .resolved_value_refs_table = resolved_value_refs,
            .top_level_bindings = top_level_bindings,
            .platform_required_bindings = platform_required_bindings,
            .imports = imports,
            .available_artifacts = available_artifacts,
            .checked_bodies = .empty,
            .checked_type_roots = .empty,
            .checked_type_schemes = .empty,
            .checked_callable_bodies = .empty,
            .checked_const_bodies = .empty,
            .checked_procedure_templates = .empty,
            .callable_eval_templates = .empty,
            .const_templates = .empty,
            .nested_proc_sites = .empty,
            .resolved_value_refs = .empty,
            .static_dispatch_plans = .empty,
            .method_registry_entries = .empty,
            .interface_capabilities = .empty,
        };
    }

    fn deinit(self: *ImportedTemplateClosureBuilder) void {
        self.interface_capabilities.deinit(self.allocator);
        self.method_registry_entries.deinit(self.allocator);
        self.static_dispatch_plans.deinit(self.allocator);
        self.resolved_value_refs.deinit(self.allocator);
        self.nested_proc_sites.deinit(self.allocator);
        self.const_templates.deinit(self.allocator);
        self.callable_eval_templates.deinit(self.allocator);
        self.checked_procedure_templates.deinit(self.allocator);
        self.checked_const_bodies.deinit(self.allocator);
        self.checked_callable_bodies.deinit(self.allocator);
        self.checked_type_schemes.deinit(self.allocator);
        self.checked_type_roots.deinit(self.allocator);
        self.checked_bodies.deinit(self.allocator);
    }

    fn appendTemplate(
        self: *ImportedTemplateClosureBuilder,
        template_ref: canonical.ProcedureTemplateRef,
        template: CheckedProcedureTemplate,
    ) Allocator.Error!void {
        if (!try self.checked_procedure_templates.append(self.allocator, template_ref)) return;

        switch (template.body) {
            .checked_body => |body| try self.appendCheckedBody(body),
            .intrinsic_wrapper,
            .entry_wrapper,
            => {},
        }
        try self.appendCheckedTypeRoot(template.checked_fn_root);
        try self.appendCheckedTypeScheme(template.checked_fn_scheme);
        try self.appendNestedProcSites(template.nested_proc_sites);
        try self.appendResolvedValueRefs(template.resolved_value_refs);
        try self.appendStaticDispatchPlans(template.static_dispatch_plans);
        try self.appendDirectProcedureDependencies(template.resolved_value_refs);
    }

    fn appendCheckedBody(self: *ImportedTemplateClosureBuilder, body: CheckedBodyId) Allocator.Error!void {
        const ref = ArtifactCheckedBodyRef{ .artifact = self.artifact_key, .body = body };
        _ = try self.checked_bodies.append(self.allocator, ref);
    }

    fn appendCheckedConstBody(self: *ImportedTemplateClosureBuilder, body: CheckedConstBodyRef) Allocator.Error!void {
        const ref = ArtifactCheckedConstBodyRef{ .artifact = self.artifact_key, .body = body };
        _ = try self.checked_const_bodies.append(self.allocator, ref);
    }

    fn appendCheckedTypeRoot(self: *ImportedTemplateClosureBuilder, ty: CheckedTypeId) Allocator.Error!void {
        const ref = ArtifactCheckedTypeRef{ .artifact = self.artifact_key, .ty = ty };
        _ = try self.checked_type_roots.append(self.allocator, ref);
    }

    fn appendCheckedTypeScheme(
        self: *ImportedTemplateClosureBuilder,
        scheme_key: canonical.CanonicalTypeSchemeKey,
    ) Allocator.Error!void {
        const scheme = self.checked_types.schemeForKey(scheme_key) orelse {
            if (builtin.mode == .Debug) {
                std.debug.panic("checked artifact invariant violated: exported template references missing checked type scheme", .{});
            }
            unreachable;
        };
        const ref = ArtifactCheckedTypeSchemeRef{ .artifact = self.artifact_key, .scheme = scheme.id };
        _ = try self.checked_type_schemes.append(self.allocator, ref);
    }

    fn appendNestedProcSites(
        self: *ImportedTemplateClosureBuilder,
        table: NestedProcSiteTableRef,
    ) Allocator.Error!void {
        if (table.len == 0) return;
        const ref = ArtifactNestedProcSiteTableRef{ .artifact = self.artifact_key, .table = table };
        _ = try self.nested_proc_sites.append(self.allocator, ref);
    }

    fn appendResolvedValueRefs(
        self: *ImportedTemplateClosureBuilder,
        table: ResolvedValueRefTableRef,
    ) Allocator.Error!void {
        if (table.len == 0) return;
        const ref = ArtifactResolvedValueRefTableRef{ .artifact = self.artifact_key, .table = table };
        _ = try self.resolved_value_refs.append(self.allocator, ref);
    }

    fn appendStaticDispatchPlans(
        self: *ImportedTemplateClosureBuilder,
        table: StaticDispatchPlanTableRef,
    ) Allocator.Error!void {
        if (table.len == 0) return;
        const ref = ArtifactStaticDispatchPlanTableRef{ .artifact = self.artifact_key, .table = table };
        _ = try self.static_dispatch_plans.append(self.allocator, ref);
    }

    fn appendInterfaceCapabilities(
        self: *ImportedTemplateClosureBuilder,
        ref: ArtifactModuleInterfaceCapabilitiesRef,
    ) Allocator.Error!void {
        _ = try self.interface_capabilities.append(self.allocator, ref);
    }

    fn appendImportedTemplateClosure(
        self: *ImportedTemplateClosureBuilder,
        closure: ImportedTemplateClosureView,
    ) Allocator.Error!void {
        for (closure.checked_bodies) |value| _ = try self.checked_bodies.append(self.allocator, value);
        for (closure.checked_type_roots) |value| _ = try self.checked_type_roots.append(self.allocator, value);
        for (closure.checked_type_schemes) |value| _ = try self.checked_type_schemes.append(self.allocator, value);
        for (closure.checked_callable_bodies) |value| _ = try self.checked_callable_bodies.append(self.allocator, value);
        for (closure.checked_const_bodies) |value| _ = try self.checked_const_bodies.append(self.allocator, value);
        for (closure.checked_procedure_templates) |value| _ = try self.checked_procedure_templates.append(self.allocator, value);
        for (closure.callable_eval_templates) |value| _ = try self.callable_eval_templates.append(self.allocator, value);
        for (closure.const_templates) |value| _ = try self.const_templates.append(self.allocator, value);
        for (closure.nested_proc_sites) |value| _ = try self.nested_proc_sites.append(self.allocator, value);
        for (closure.resolved_value_refs) |value| _ = try self.resolved_value_refs.append(self.allocator, value);
        for (closure.static_dispatch_plans) |value| _ = try self.static_dispatch_plans.append(self.allocator, value);
        for (closure.method_registry_entries) |value| _ = try self.method_registry_entries.append(self.allocator, value);
        for (closure.interface_capabilities) |value| _ = try self.interface_capabilities.append(self.allocator, value);
    }

    fn appendDirectProcedureDependencies(
        self: *ImportedTemplateClosureBuilder,
        table: ResolvedValueRefTableRef,
    ) Allocator.Error!void {
        const end = table.start + table.len;
        if (end > self.resolved_value_refs_table.template_refs.len) checkedArtifactInvariant("checked template resolved-ref span was outside table", .{});
        for (self.resolved_value_refs_table.template_refs[table.start..end]) |ref_id| {
            const raw = @intFromEnum(ref_id);
            if (raw >= self.resolved_value_refs_table.records.len) checkedArtifactInvariant("checked template resolved-ref id was outside table", .{});
            const resolved = self.resolved_value_refs_table.records[raw].ref;
            if (try self.appendImportedTemplateClosureForResolvedRef(resolved)) continue;
            if (try self.appendPlatformRequiredRelationClosureForResolvedRef(resolved)) continue;
            if (try self.appendCallableEvalBindingClosureForResolvedRef(resolved)) continue;
            if (self.templateForResolvedValueRef(resolved)) |dependency_ref| {
                _ = try self.checked_procedure_templates.append(self.allocator, dependency_ref);
            }
            if (self.constRefForResolvedValueRef(resolved)) |dependency_ref| {
                _ = try self.const_templates.append(self.allocator, dependency_ref);
            }
        }
    }

    fn appendImportedTemplateClosureForResolvedRef(
        self: *ImportedTemplateClosureBuilder,
        ref: ResolvedValueRef,
    ) Allocator.Error!bool {
        return switch (ref) {
            .imported_const => |const_use| blk: {
                _ = try self.const_templates.append(self.allocator, const_use.const_ref);
                break :blk true;
            },
            .imported_proc => |proc_use| blk: {
                const imported = switch (proc_use.binding) {
                    .imported => |imported| imported,
                    .top_level,
                    .hosted,
                    .platform_required,
                    => checkedArtifactInvariant("imported procedure ref did not carry imported binding", .{}),
                };
                const binding = self.importedProcedureBinding(imported);
                try self.appendImportedProcedureBindingDependency(binding);
                break :blk true;
            },
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            .local_proc,
            .selected_hoisted_const,
            .top_level_const,
            .top_level_proc,
            .hosted_proc,
            .platform_required_declaration,
            .platform_required_checked_error,
            .platform_required_const,
            .platform_required_proc,
            .promoted_top_level_proc,
            => false,
        };
    }

    fn appendImportedProcedureBindingDependency(
        self: *ImportedTemplateClosureBuilder,
        binding: ImportedProcedureBindingView,
    ) Allocator.Error!void {
        switch (binding.body) {
            .direct_template => |direct| {
                const template_ref = checkedTemplateFromCallableTemplateForClosure(direct.template) orelse {
                    checkedArtifactInvariant("imported procedure binding referenced a post-check template before mono", .{});
                };
                _ = try self.checked_procedure_templates.append(self.allocator, template_ref);
            },
            .callable_eval_template => |template_id| {
                _ = try self.callable_eval_templates.append(self.allocator, .{
                    .artifact = binding.binding.artifact,
                    .template = template_id,
                });
            },
        }
    }

    fn importedProcedureBinding(
        self: *ImportedTemplateClosureBuilder,
        ref: ImportedProcedureBindingRef,
    ) ImportedProcedureBindingView {
        for (self.imports) |import| {
            if (!std.meta.eql(import.key.bytes, ref.artifact.bytes)) continue;
            for (import.view.exported_procedure_bindings.bindings) |binding| {
                if (binding.binding.def == ref.def and
                    binding.binding.pattern == ref.pattern)
                {
                    return binding;
                }
            }
        }
        for (self.available_artifacts) |view| {
            if (!std.meta.eql(view.key.bytes, ref.artifact.bytes)) continue;
            for (view.exported_procedure_bindings.bindings) |binding| {
                if (binding.binding.def == ref.def and
                    binding.binding.pattern == ref.pattern)
                {
                    return binding;
                }
            }
        }
        checkedArtifactInvariant("imported procedure dependency had no published imported closure", .{});
    }

    fn appendPlatformRequiredRelationClosureForResolvedRef(
        self: *ImportedTemplateClosureBuilder,
        ref: ResolvedValueRef,
    ) Allocator.Error!bool {
        return switch (ref) {
            .platform_required_const => |required| blk: {
                const binding = self.platformRequiredBinding(required.binding);
                switch (binding.value_use) {
                    .const_value => {},
                    .procedure_value => checkedArtifactInvariant("platform-required const ref pointed at procedure binding {d}", .{@intFromEnum(required.binding)}),
                }
                try self.appendImportedTemplateClosure(self.platform_required_bindings.relationClosure(binding));
                break :blk true;
            },
            .platform_required_proc => |required| blk: {
                const binding = self.platformRequiredBinding(required.binding);
                switch (binding.value_use) {
                    .procedure_value => {},
                    .const_value => checkedArtifactInvariant("platform-required procedure ref pointed at const binding {d}", .{@intFromEnum(required.binding)}),
                }
                try self.appendImportedTemplateClosure(self.platform_required_bindings.relationClosure(binding));
                break :blk true;
            },
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            .local_proc,
            .selected_hoisted_const,
            .top_level_const,
            .imported_const,
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .platform_required_declaration,
            .platform_required_checked_error,
            .promoted_top_level_proc,
            => false,
        };
    }

    fn platformRequiredBinding(
        self: *ImportedTemplateClosureBuilder,
        binding_id: PlatformRequiredBindingId,
    ) PlatformRequiredBinding {
        return self.platform_required_bindings.lookupByBindingId(@intFromEnum(binding_id)) orelse {
            checkedArtifactInvariant("resolved platform-required value referenced missing binding {d}", .{@intFromEnum(binding_id)});
        };
    }

    fn appendConstTemplate(
        self: *ImportedTemplateClosureBuilder,
        const_ref: ConstRef,
    ) Allocator.Error!void {
        if (!try self.const_templates.append(self.allocator, const_ref)) return;

        if (!std.meta.eql(const_ref.artifact.bytes, self.artifact_key.bytes)) return;

        const scheme = self.checked_types.schemeForKey(const_ref.source_scheme) orelse {
            if (builtin.mode == .Debug) {
                std.debug.panic("checked artifact invariant violated: const template references missing checked type scheme", .{});
            }
            unreachable;
        };
        try self.appendCheckedTypeRoot(scheme.root);
        try self.appendCheckedTypeScheme(const_ref.source_scheme);

        const template = self.const_templates_table.get(const_ref);
        switch (template.state) {
            .eval_template => |eval| {
                try self.appendCheckedConstBody(eval.body);
                try self.appendNestedProcSites(eval.nested_proc_sites);
                try self.appendResolvedValueRefs(eval.resolved_value_refs);
                try self.appendStaticDispatchPlans(eval.static_dispatch_plans);
                try self.appendDirectProcedureDependencies(eval.resolved_value_refs);
                const entry_template = self.checked_templates.get(eval.entry_template.template);
                try self.appendTemplate(eval.entry_template, entry_template);
            },
            .stored_const => {},
            .reserved => checkedArtifactInvariant("imported template closure reached unsealed const template", .{}),
        }
    }

    fn templateForResolvedValueRef(
        self: *ImportedTemplateClosureBuilder,
        ref: ResolvedValueRef,
    ) ?canonical.ProcedureTemplateRef {
        const use: ProcedureUseTemplate = switch (ref) {
            .top_level_proc,
            .hosted_proc,
            .promoted_top_level_proc,
            => |procedure| procedure,
            .platform_required_proc => |required| required.procedure,
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            .local_proc,
            .selected_hoisted_const,
            .top_level_const,
            .imported_const,
            .imported_proc,
            .platform_required_declaration,
            .platform_required_checked_error,
            .platform_required_const,
            => return null,
        };
        return switch (use.binding) {
            .top_level => |binding_ref| self.templateForTopLevelBinding(binding_ref),
            .hosted => |hosted| hosted.template,
            .platform_required => checkedArtifactInvariant("platform-required procedure dependency must be provided by its relation template closure", .{}),
            .imported => null,
        };
    }

    fn appendCallableEvalBindingClosureForResolvedRef(
        self: *ImportedTemplateClosureBuilder,
        ref: ResolvedValueRef,
    ) Allocator.Error!bool {
        const use: ProcedureUseTemplate = switch (ref) {
            .top_level_proc,
            .promoted_top_level_proc,
            => |procedure| procedure,
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            .local_proc,
            .selected_hoisted_const,
            .top_level_const,
            .imported_const,
            .imported_proc,
            .hosted_proc,
            .platform_required_declaration,
            .platform_required_checked_error,
            .platform_required_const,
            .platform_required_proc,
            => return false,
        };
        const top_level = switch (use.binding) {
            .top_level => |binding| binding,
            .imported, .hosted, .platform_required => return false,
        };
        if (!std.meta.eql(top_level.artifact.bytes, self.artifact_key.bytes)) {
            checkedArtifactInvariant("top-level callable-eval closure dependency referenced a different artifact", .{});
        }
        const binding = self.top_level_bindings.get(top_level.binding);
        const template_id = switch (binding.body) {
            .direct_template => return false,
            .callable_eval_template => |template| template,
        };
        try self.appendCallableEvalBindingTemplate(template_id);
        return true;
    }

    fn appendCallableEvalBindingTemplate(
        self: *ImportedTemplateClosureBuilder,
        template_id: CallableEvalTemplateId,
    ) Allocator.Error!void {
        const template = self.callable_eval_template_table.get(template_id);
        const wrapper = entryWrapperForRoot(self.entry_wrappers, template.root);
        const entry_template = self.checked_templates.get(wrapper.template.template);

        try self.appendCheckedTypeRoot(template.checked_fn_root);
        try self.appendCheckedTypeScheme(template.source_scheme);
        try self.appendTemplate(wrapper.template, entry_template);
        _ = try self.callable_eval_templates.append(self.allocator, .{
            .artifact = self.artifact_key,
            .template = template_id,
        });
    }

    fn constRefForResolvedValueRef(
        _: *ImportedTemplateClosureBuilder,
        ref: ResolvedValueRef,
    ) ?ConstRef {
        return switch (ref) {
            .top_level_const => |const_use| const_use.const_ref,
            .selected_hoisted_const => |selected| selected.const_use.const_ref,
            .local_param,
            .local_value,
            .local_mutable_version,
            .pattern_binder,
            .local_proc,
            .imported_const,
            .top_level_proc,
            .imported_proc,
            .hosted_proc,
            .platform_required_declaration,
            .platform_required_checked_error,
            .platform_required_const,
            .platform_required_proc,
            .promoted_top_level_proc,
            => null,
        };
    }

    fn templateForTopLevelBinding(
        self: *ImportedTemplateClosureBuilder,
        binding_ref: ArtifactTopLevelProcedureBindingRef,
    ) ?canonical.ProcedureTemplateRef {
        if (!std.meta.eql(binding_ref.artifact.bytes, self.artifact_key.bytes)) {
            checkedArtifactInvariant("top-level procedure closure dependency referenced a different artifact", .{});
        }
        const binding = self.top_level_bindings.get(binding_ref.binding);
        return switch (binding.body) {
            .direct_template => |direct| checkedTemplateFromCallableTemplateForClosure(direct.template),
            .callable_eval_template => null,
        };
    }
};

fn checkedTemplateFromCallableTemplateForClosure(
    template: canonical.CallableProcedureTemplateRef,
) ?canonical.ProcedureTemplateRef {
    return switch (template) {
        .checked => |checked| checked,
        .synthetic => |synthetic| synthetic.template,
        .lifted => null,
    };
}

fn buildImportedConstTemplateClosure(
    allocator: Allocator,
    artifact_key: CheckedModuleArtifactKey,
    checked_types: *const CheckedTypeStore,
    checked_templates: *const CheckedProcedureTemplateTable,
    callable_eval_templates: *const CallableEvalTemplateTable,
    entry_wrappers: *const EntryWrapperTable,
    const_templates: *const ConstTemplateTable,
    resolved_value_refs: *const ResolvedValueRefTable,
    top_level_bindings: *const TopLevelProcedureBindingTable,
    platform_required_bindings: *const PlatformRequiredBindingTable,
    imports: []const PublishImportArtifact,
    available_artifacts: []const ImportedModuleView,
    const_ref: ConstRef,
) Allocator.Error!ImportedTemplateClosureView {
    var builder = ImportedTemplateClosureBuilder.init(
        allocator,
        artifact_key,
        checked_types,
        checked_templates,
        callable_eval_templates,
        entry_wrappers,
        const_templates,
        resolved_value_refs,
        top_level_bindings,
        platform_required_bindings,
        imports,
        available_artifacts,
    );
    defer builder.deinit();

    try builder.appendInterfaceCapabilities(.{ .artifact = artifact_key });
    try builder.appendConstTemplate(const_ref);

    return .{
        .checked_bodies = try builder.checked_bodies.toOwnedSlice(allocator),
        .checked_type_roots = try builder.checked_type_roots.toOwnedSlice(allocator),
        .checked_type_schemes = try builder.checked_type_schemes.toOwnedSlice(allocator),
        .checked_callable_bodies = try builder.checked_callable_bodies.toOwnedSlice(allocator),
        .checked_const_bodies = try builder.checked_const_bodies.toOwnedSlice(allocator),
        .checked_procedure_templates = try builder.checked_procedure_templates.toOwnedSlice(allocator),
        .callable_eval_templates = try builder.callable_eval_templates.toOwnedSlice(allocator),
        .const_templates = try builder.const_templates.toOwnedSlice(allocator),
        .nested_proc_sites = try builder.nested_proc_sites.toOwnedSlice(allocator),
        .resolved_value_refs = try builder.resolved_value_refs.toOwnedSlice(allocator),
        .static_dispatch_plans = try builder.static_dispatch_plans.toOwnedSlice(allocator),
        .method_registry_entries = try builder.method_registry_entries.toOwnedSlice(allocator),
        .interface_capabilities = try builder.interface_capabilities.toOwnedSlice(allocator),
    };
}

fn freeConstSlice(allocator: Allocator, slice: anytype) void {
    if (slice.len > 0) allocator.free(slice);
}

pub fn deinitImportedTemplateClosure(
    allocator: Allocator,
    closure: *ImportedTemplateClosureView,
) void {
    freeConstSlice(allocator, closure.checked_bodies);
    freeConstSlice(allocator, closure.checked_type_roots);
    freeConstSlice(allocator, closure.checked_type_schemes);
    freeConstSlice(allocator, closure.checked_callable_bodies);
    freeConstSlice(allocator, closure.checked_const_bodies);
    freeConstSlice(allocator, closure.checked_procedure_templates);
    freeConstSlice(allocator, closure.callable_eval_templates);
    freeConstSlice(allocator, closure.const_templates);
    freeConstSlice(allocator, closure.nested_proc_sites);
    freeConstSlice(allocator, closure.resolved_value_refs);
    freeConstSlice(allocator, closure.static_dispatch_plans);
    freeConstSlice(allocator, closure.method_registry_entries);
    freeConstSlice(allocator, closure.interface_capabilities);
    closure.* = .{};
}

/// Clone an imported-template closure view so it can be owned by a new artifact record.
pub fn cloneImportedTemplateClosure(
    allocator: Allocator,
    closure: ImportedTemplateClosureView,
) Allocator.Error!ImportedTemplateClosureView {
    var out = ImportedTemplateClosureView{};
    errdefer deinitImportedTemplateClosure(allocator, &out);

    out.checked_bodies = try cloneConstSlice(allocator, ArtifactCheckedBodyRef, closure.checked_bodies);
    out.checked_type_roots = try cloneConstSlice(allocator, ArtifactCheckedTypeRef, closure.checked_type_roots);
    out.checked_type_schemes = try cloneConstSlice(allocator, ArtifactCheckedTypeSchemeRef, closure.checked_type_schemes);
    out.checked_callable_bodies = try cloneConstSlice(allocator, ArtifactCheckedCallableBodyRef, closure.checked_callable_bodies);
    out.checked_const_bodies = try cloneConstSlice(allocator, ArtifactCheckedConstBodyRef, closure.checked_const_bodies);
    out.checked_procedure_templates = try cloneConstSlice(allocator, ArtifactProcedureTemplateRef, closure.checked_procedure_templates);
    out.callable_eval_templates = try cloneConstSlice(allocator, ArtifactCallableEvalTemplateRef, closure.callable_eval_templates);
    out.const_templates = try cloneConstSlice(allocator, ConstRef, closure.const_templates);
    out.nested_proc_sites = try cloneConstSlice(allocator, ArtifactNestedProcSiteTableRef, closure.nested_proc_sites);
    out.resolved_value_refs = try cloneConstSlice(allocator, ArtifactResolvedValueRefTableRef, closure.resolved_value_refs);
    out.static_dispatch_plans = try cloneConstSlice(allocator, ArtifactStaticDispatchPlanTableRef, closure.static_dispatch_plans);
    out.method_registry_entries = try cloneConstSlice(allocator, MethodRegistryEntryRef, closure.method_registry_entries);
    out.interface_capabilities = try cloneConstSlice(allocator, ArtifactModuleInterfaceCapabilitiesRef, closure.interface_capabilities);

    return out;
}

fn cloneConstSlice(
    allocator: Allocator,
    comptime T: type,
    slice: []const T,
) Allocator.Error![]const T {
    if (slice.len == 0) return &.{};
    return try allocator.dupe(T, slice);
}

fn deinitPlatformRequiredValueUse(
    allocator: Allocator,
    value_use: *PlatformRequiredValueUse,
) void {
    switch (value_use.*) {
        .const_value => |*const_use| deinitImportedTemplateClosure(allocator, &const_use.relation_template_closure),
        .procedure_value => |*procedure| deinitImportedTemplateClosure(allocator, &procedure.relation_template_closure),
    }
    value_use.* = undefined;
}

/// Public `ImportedProcedureBindingBody` declaration.
pub const ImportedProcedureBindingBody = union(enum) {
    direct_template: DirectProcedureBinding,
    callable_eval_template: CallableEvalTemplateId,
};

/// Public `ImportedProcedureBindingView` declaration.
pub const ImportedProcedureBindingView = struct {
    binding: ImportedProcedureBindingRef,
    source_scheme: canonical.CanonicalTypeSchemeKey,
    body: ImportedProcedureBindingBody,
    intrinsic: ?IntrinsicId = null,
    iterator_procedure: ?IteratorProcedureId = null,
    runtime_result_provenance: ?RuntimeResultProvenance,
    template_closure: StoredImportedTemplateClosure = .{},
};

/// Public `ExportedProcedureBindingView` declaration.
pub const ExportedProcedureBindingView = struct {
    bindings: []const ImportedProcedureBindingView = &.{},
    closure_pool: *const ClosurePool = &empty_closure_pool,

    /// Materialize a row's imported template closure from the backing pool.
    pub fn rowClosure(self: ExportedProcedureBindingView, row: ImportedProcedureBindingView) ImportedTemplateClosureView {
        return self.closure_pool.reconstruct(row.template_closure);
    }
};

/// Public `ExportedProcedureBindingTable` declaration.
pub const ExportedProcedureBindingTable = struct {
    bindings: []ImportedProcedureBindingView = &.{},
    closure_pool: ClosurePool = ClosurePool.empty,

    pub fn fromModule(
        allocator: Allocator,
        module: TypedCIR.Module,
        published_exports: []const CIR.Def.Idx,
        checked_types: *const CheckedTypeStore,
        checked_templates: *const CheckedProcedureTemplateTable,
        const_templates: *const ConstTemplateTable,
        top_level_values: *const TopLevelValueTable,
        procedure_bindings: *const TopLevelProcedureBindingTable,
        callable_eval_templates: *const CallableEvalTemplateTable,
        entry_wrappers: *const EntryWrapperTable,
        resolved_value_refs: *const ResolvedValueRefTable,
        platform_required_bindings: *const PlatformRequiredBindingTable,
        imports: []const PublishImportArtifact,
        available_artifacts: []const ImportedModuleView,
        artifact_key: CheckedModuleArtifactKey,
    ) Allocator.Error!ExportedProcedureBindingTable {
        var bindings = std.ArrayList(ImportedProcedureBindingView).empty;
        var closure_pool = ClosurePool.empty;
        errdefer {
            bindings.deinit(allocator);
            closure_pool.deinit(allocator);
        }

        for (published_exports) |def_idx| {
            const top_level = top_level_values.lookupByDef(def_idx) orelse continue;
            const binding_ref = switch (top_level.value) {
                .procedure_binding => |binding| binding,
                .const_ref => continue,
            };
            const binding = procedure_bindings.get(binding_ref);
            const body: ImportedProcedureBindingBody = switch (binding.body) {
                .direct_template => |direct| .{ .direct_template = direct },
                .callable_eval_template => |template| .{ .callable_eval_template = template },
            };
            var template_closure = try buildProcedureBindingClosure(
                allocator,
                artifact_key,
                checked_types,
                checked_templates,
                callable_eval_templates,
                entry_wrappers,
                const_templates,
                resolved_value_refs,
                procedure_bindings,
                platform_required_bindings,
                imports,
                available_artifacts,
                binding.body,
            );
            errdefer deinitImportedTemplateClosure(allocator, &template_closure);

            const stored_closure = try closure_pool.commit(allocator, template_closure);
            template_closure = .{};

            try bindings.append(allocator, .{
                .binding = .{
                    .artifact = artifact_key,
                    .def = def_idx,
                    .pattern = top_level.pattern,
                },
                .source_scheme = binding.source_scheme,
                .body = body,
                .intrinsic = intrinsicForProcedureDef(module, def_idx),
                .iterator_procedure = iteratorProcedureForDef(module, def_idx),
                .runtime_result_provenance = runtimeResultProvenanceForProcedureDef(module, def_idx),
                .template_closure = stored_closure,
            });
        }

        return .{
            .bindings = try bindings.toOwnedSlice(allocator),
            .closure_pool = closure_pool,
        };
    }

    pub fn view(self: *const ExportedProcedureBindingTable) ExportedProcedureBindingView {
        return .{ .bindings = self.bindings, .closure_pool = &self.closure_pool };
    }

    /// Materialize a row's imported template closure from this table's pool.
    pub fn rowClosure(self: *const ExportedProcedureBindingTable, row: ImportedProcedureBindingView) ImportedTemplateClosureView {
        return self.view().rowClosure(row);
    }

    pub fn deinit(self: *ExportedProcedureBindingTable, allocator: Allocator) void {
        if (!self.closure_pool.serialized) allocator.free(self.bindings);
        self.closure_pool.deinit(allocator);
        self.* = .{};
    }

    /// Relocatable serialized form: the POD row slice plus the closure pool.
    pub const Serialized = extern struct {
        bindings: SerializedSlice(ImportedProcedureBindingView) = .{},
        closure_pool: ClosurePool.Serialized = .{},

        comptime {
            std.debug.assert(artifact_serialize.relocatablePointerCount(Serialized) == 14);
        }

        const Serde = artifact_serialize.SliceStoreSerde(ExportedProcedureBindingTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };
};

fn buildProcedureBindingClosure(
    allocator: Allocator,
    artifact_key: CheckedModuleArtifactKey,
    checked_types: *const CheckedTypeStore,
    checked_templates: *const CheckedProcedureTemplateTable,
    callable_eval_templates: *const CallableEvalTemplateTable,
    entry_wrappers: *const EntryWrapperTable,
    const_templates: *const ConstTemplateTable,
    resolved_value_refs: *const ResolvedValueRefTable,
    top_level_bindings: *const TopLevelProcedureBindingTable,
    platform_required_bindings: *const PlatformRequiredBindingTable,
    imports: []const PublishImportArtifact,
    available_artifacts: []const ImportedModuleView,
    body: ProcedureBindingBody,
) Allocator.Error!ImportedTemplateClosureView {
    return switch (body) {
        .direct_template => |direct| switch (direct.template) {
            .checked => |template_ref| buildImportedTemplateClosure(
                allocator,
                artifact_key,
                checked_types,
                checked_templates,
                callable_eval_templates,
                entry_wrappers,
                const_templates,
                resolved_value_refs,
                top_level_bindings,
                platform_required_bindings,
                imports,
                available_artifacts,
                template_ref,
                checked_templates.get(template_ref.template),
            ),
            .synthetic => |synthetic| buildImportedTemplateClosure(
                allocator,
                artifact_key,
                checked_types,
                checked_templates,
                callable_eval_templates,
                entry_wrappers,
                const_templates,
                resolved_value_refs,
                top_level_bindings,
                platform_required_bindings,
                imports,
                available_artifacts,
                synthetic.template,
                checked_templates.get(synthetic.template.template),
            ),
            .lifted => {
                if (builtin.mode == .Debug) {
                    std.debug.panic("checked artifact invariant violated: exported checked binding cannot reference lifted templates before mono", .{});
                }
                unreachable;
            },
        },
        .callable_eval_template => |template_id| blk: {
            const template = callable_eval_templates.get(template_id);
            const wrapper = entryWrapperForRoot(entry_wrappers, template.root);
            const entry_template = checked_templates.get(wrapper.template.template);

            var builder = ImportedTemplateClosureBuilder.init(
                allocator,
                artifact_key,
                checked_types,
                checked_templates,
                callable_eval_templates,
                entry_wrappers,
                const_templates,
                resolved_value_refs,
                top_level_bindings,
                platform_required_bindings,
                imports,
                available_artifacts,
            );
            defer builder.deinit();

            try builder.appendInterfaceCapabilities(.{ .artifact = artifact_key });
            try builder.appendCheckedTypeRoot(template.checked_fn_root);
            try builder.appendCheckedTypeScheme(template.source_scheme);
            try builder.appendTemplate(wrapper.template, entry_template);

            _ = try builder.callable_eval_templates.append(allocator, .{
                .artifact = artifact_key,
                .template = template_id,
            });

            break :blk .{
                .checked_bodies = try builder.checked_bodies.toOwnedSlice(allocator),
                .checked_type_roots = try builder.checked_type_roots.toOwnedSlice(allocator),
                .checked_type_schemes = try builder.checked_type_schemes.toOwnedSlice(allocator),
                .checked_callable_bodies = try builder.checked_callable_bodies.toOwnedSlice(allocator),
                .checked_const_bodies = try builder.checked_const_bodies.toOwnedSlice(allocator),
                .checked_procedure_templates = try builder.checked_procedure_templates.toOwnedSlice(allocator),
                .callable_eval_templates = try builder.callable_eval_templates.toOwnedSlice(allocator),
                .const_templates = try builder.const_templates.toOwnedSlice(allocator),
                .nested_proc_sites = try builder.nested_proc_sites.toOwnedSlice(allocator),
                .resolved_value_refs = try builder.resolved_value_refs.toOwnedSlice(allocator),
                .static_dispatch_plans = try builder.static_dispatch_plans.toOwnedSlice(allocator),
                .method_registry_entries = try builder.method_registry_entries.toOwnedSlice(allocator),
                .interface_capabilities = try builder.interface_capabilities.toOwnedSlice(allocator),
            };
        },
    };
}

/// Public `ConstEvalTemplate` declaration.
pub const ConstEvalTemplate = struct {
    body: CheckedConstBodyRef,
    entry_template: canonical.ProcedureTemplateRef,
    source_scheme: canonical.CanonicalTypeSchemeKey,
    resolved_value_refs: ResolvedValueRefTableRef = .{},
    static_dispatch_plans: StaticDispatchPlanTableRef = .{},
    nested_proc_sites: NestedProcSiteTableRef = .{},
};

/// Public `StoredConstTemplate` declaration.
pub const StoredConstTemplate = struct {
    node: ConstNodeId,
    /// Exact producer-owned Monotype representation used to evaluate `node`.
    /// This is explicit post-check evidence, stored in `ConstStore.type_store`.
    root_type: const_store.ConstTypeId,
};

/// Public `ConstTemplateState` declaration.
pub const ConstTemplateState = union(enum) {
    reserved,
    eval_template: ConstEvalTemplate,
    stored_const: StoredConstTemplate,
};

/// Public `ConstTemplate` declaration.
pub const ConstTemplate = struct {
    id: ConstTemplateId,
    owner: ConstOwner,
    source_scheme: canonical.CanonicalTypeSchemeKey,
    state: ConstTemplateState,
};

/// Public `ConstTemplateTable` declaration.
pub const ConstTemplateTable = struct {
    templates: std.ArrayList(ConstTemplate) = .empty,

    pub const Serialized = extern struct {
        templates: SerializedSlice(ConstTemplate) = .{},
        const Serde = artifact_serialize.SliceStoreSerde(ConstTemplateTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    pub fn reserveTopLevel(
        self: *ConstTemplateTable,
        allocator: Allocator,
        artifact_key: CheckedModuleArtifactKey,
        module_idx: u32,
        pattern: CheckedPatternId,
        source_scheme: canonical.CanonicalTypeSchemeKey,
    ) Allocator.Error!ConstRef {
        const id: ConstTemplateId = @enumFromInt(@as(u32, @intCast(self.templates.items.len)));
        const owner: ConstOwner = .{ .top_level_binding = .{
            .module_idx = module_idx,
            .pattern = pattern,
        } };
        try self.templates.append(allocator, .{
            .id = id,
            .owner = owner,
            .source_scheme = source_scheme,
            .state = .reserved,
        });
        return .{
            .artifact = artifact_key,
            .owner = owner,
            .template = id,
            .source_scheme = source_scheme,
        };
    }

    pub fn reserveHoisted(
        self: *ConstTemplateTable,
        allocator: Allocator,
        artifact_key: CheckedModuleArtifactKey,
        module_idx: u32,
        expr: CheckedExprId,
        source_scheme: canonical.CanonicalTypeSchemeKey,
    ) Allocator.Error!ConstRef {
        const id: ConstTemplateId = @enumFromInt(@as(u32, @intCast(self.templates.items.len)));
        const owner: ConstOwner = .{ .hoisted_expr = .{
            .module_idx = module_idx,
            .expr = expr,
        } };
        try self.templates.append(allocator, .{
            .id = id,
            .owner = owner,
            .source_scheme = source_scheme,
            .state = .reserved,
        });
        return .{
            .artifact = artifact_key,
            .owner = owner,
            .template = id,
            .source_scheme = source_scheme,
        };
    }

    pub fn fillEval(
        self: *ConstTemplateTable,
        ref: ConstRef,
        template: ConstEvalTemplate,
    ) void {
        const record = self.recordForRef(ref);
        if (!std.meta.eql(record.source_scheme.bytes, template.source_scheme.bytes)) {
            checkedArtifactInvariant("constant eval template source scheme does not match reserved ConstRef", .{});
        }
        switch (record.state) {
            .reserved => record.state = .{ .eval_template = template },
            .eval_template, .stored_const => checkedArtifactInvariant("constant template was filled twice", .{}),
        }
    }

    pub fn fillStoredConst(
        self: *ConstTemplateTable,
        ref: ConstRef,
        template: StoredConstTemplate,
    ) void {
        const record = self.recordForRef(ref);
        switch (record.state) {
            .reserved, .eval_template => record.state = .{ .stored_const = template },
            .stored_const => checkedArtifactInvariant("constant template was filled twice", .{}),
        }
    }

    pub fn get(self: *const ConstTemplateTable, ref: ConstRef) ConstTemplate {
        const idx = @intFromEnum(ref.template);
        if (idx >= self.templates.items.len) {
            checkedArtifactInvariant("ConstRef template id is out of range", .{});
        }
        const template = self.templates.items[idx];
        if (!constOwnerEql(template.owner, ref.owner) or
            !std.meta.eql(template.source_scheme.bytes, ref.source_scheme.bytes))
        {
            checkedArtifactInvariant("ConstRef does not match constant template row", .{});
        }
        return template;
    }

    pub fn verifySealed(self: *const ConstTemplateTable) void {
        if (builtin.mode != .Debug) return;

        for (self.templates.items, 0..) |template, i| {
            std.debug.assert(@intFromEnum(template.id) == i);
            switch (template.state) {
                .eval_template, .stored_const => {},
                .reserved => std.debug.panic(
                    "checked artifact invariant violated: constant template {d} was not sealed before publication",
                    .{i},
                ),
            }
        }
    }

    fn recordForRef(self: *ConstTemplateTable, ref: ConstRef) *ConstTemplate {
        const idx = @intFromEnum(ref.template);
        if (idx >= self.templates.items.len) {
            checkedArtifactInvariant("ConstRef template id is out of range", .{});
        }
        const record = &self.templates.items[idx];
        if (!constOwnerEql(record.owner, ref.owner) or
            !std.meta.eql(record.source_scheme.bytes, ref.source_scheme.bytes))
        {
            checkedArtifactInvariant("ConstRef does not match constant template row", .{});
        }
        return record;
    }

    pub fn deinit(self: *ConstTemplateTable, allocator: Allocator) void {
        self.templates.deinit(allocator);
        self.* = .{};
    }
};

/// Public `ImportedConstTemplateView` declaration.
pub const ImportedConstTemplateView = struct {
    module_idx: u32,
    def: CIR.Def.Idx,
    pattern: CheckedPatternId,
    const_ref: ConstRef,
    source_scheme: canonical.CanonicalTypeSchemeKey,
    template: ConstTemplate,
    template_closure: StoredImportedTemplateClosure = .{},
};

/// Public `ExportedConstTemplateView` declaration.
pub const ExportedConstTemplateView = struct {
    templates: []const ImportedConstTemplateView = &.{},
    closure_pool: *const ClosurePool = &empty_closure_pool,

    /// Materialize a row's imported template closure from the backing pool.
    pub fn rowClosure(self: ExportedConstTemplateView, row: ImportedConstTemplateView) ImportedTemplateClosureView {
        return self.closure_pool.reconstruct(row.template_closure);
    }
};

/// Public `ExportedConstTemplateTable` declaration.
pub const ExportedConstTemplateTable = struct {
    templates: []ImportedConstTemplateView = &.{},
    closure_pool: ClosurePool = ClosurePool.empty,

    pub fn fromModule(
        allocator: Allocator,
        module: TypedCIR.Module,
        published_exports: []const CIR.Def.Idx,
        artifact_key: CheckedModuleArtifactKey,
        checked_types: *const CheckedTypeStore,
        checked_templates: *const CheckedProcedureTemplateTable,
        callable_eval_templates: *const CallableEvalTemplateTable,
        entry_wrappers: *const EntryWrapperTable,
        top_level_values: *const TopLevelValueTable,
        const_templates: *const ConstTemplateTable,
        resolved_value_refs: *const ResolvedValueRefTable,
        top_level_bindings: *const TopLevelProcedureBindingTable,
        platform_required_bindings: *const PlatformRequiredBindingTable,
        imports: []const PublishImportArtifact,
        available_artifacts: []const ImportedModuleView,
    ) Allocator.Error!ExportedConstTemplateTable {
        var templates = std.ArrayList(ImportedConstTemplateView).empty;
        var closure_pool = ClosurePool.empty;
        errdefer {
            templates.deinit(allocator);
            closure_pool.deinit(allocator);
        }

        for (published_exports) |def_idx| {
            const top_level = top_level_values.lookupByDef(def_idx) orelse continue;
            const const_ref = switch (top_level.value) {
                .const_ref => |ref| ref,
                .procedure_binding => continue,
            };
            const template = const_templates.get(const_ref);
            var template_closure = try buildImportedConstTemplateClosure(
                allocator,
                artifact_key,
                checked_types,
                checked_templates,
                callable_eval_templates,
                entry_wrappers,
                const_templates,
                resolved_value_refs,
                top_level_bindings,
                platform_required_bindings,
                imports,
                available_artifacts,
                const_ref,
            );
            errdefer deinitImportedTemplateClosure(allocator, &template_closure);
            const stored_closure = try closure_pool.commit(allocator, template_closure);
            template_closure = .{};
            try templates.append(allocator, .{
                .module_idx = module.moduleIndex(),
                .def = def_idx,
                .pattern = top_level.pattern,
                .const_ref = const_ref,
                .source_scheme = top_level.source_scheme,
                .template = template,
                .template_closure = stored_closure,
            });
        }

        return .{
            .templates = try templates.toOwnedSlice(allocator),
            .closure_pool = closure_pool,
        };
    }

    pub fn deinit(self: *ExportedConstTemplateTable, allocator: Allocator) void {
        if (!self.closure_pool.serialized) allocator.free(self.templates);
        self.closure_pool.deinit(allocator);
        self.* = .{};
    }

    /// Materialize a row's imported template closure from this table's pool.
    pub fn rowClosure(self: *const ExportedConstTemplateTable, row: ImportedConstTemplateView) ImportedTemplateClosureView {
        return self.view().rowClosure(row);
    }

    /// Relocatable serialized form: the POD row slice plus the closure pool.
    pub const Serialized = extern struct {
        templates: SerializedSlice(ImportedConstTemplateView) = .{},
        closure_pool: ClosurePool.Serialized = .{},

        comptime {
            std.debug.assert(artifact_serialize.relocatablePointerCount(Serialized) == 14);
        }

        const Serde = artifact_serialize.SliceStoreSerde(ExportedConstTemplateTable, @This());
        pub const serialize = Serde.serialize;
        pub const deserialize = Serde.deserialize;
    };

    pub fn fillStoredConst(
        self: *ExportedConstTemplateTable,
        ref: ConstRef,
        template: StoredConstTemplate,
    ) void {
        for (self.templates) |*entry| {
            if (!constRefEql(entry.const_ref, ref)) continue;
            entry.template.state = .{ .stored_const = template };
            return;
        }
    }

    pub fn view(self: *const ExportedConstTemplateTable) ExportedConstTemplateView {
        return .{ .templates = self.templates, .closure_pool = &self.closure_pool };
    }
};

fn checkedArtifactInvariant(comptime message: []const u8, args: anytype) noreturn {
    if (builtin.mode == .Debug) {
        std.debug.panic("checked artifact invariant violated: " ++ message, args);
    }
    unreachable;
}

fn checkedArtifactKeyEql(a: CheckedModuleArtifactKey, b: CheckedModuleArtifactKey) bool {
    return std.meta.eql(a.bytes, b.bytes);
}

fn checkedArtifactKeyLessThan(_: void, a: CheckedModuleArtifactKey, b: CheckedModuleArtifactKey) bool {
    for (a.bytes, b.bytes) |left, right| {
        if (left < right) return true;
        if (left > right) return false;
    }
    return false;
}

fn closureArtifactRefIsLocal(
    artifact: *const CheckedModuleArtifact,
    referenced: CheckedModuleArtifactKey,
) bool {
    return checkedArtifactKeyEql(referenced, artifact.key);
}

fn constRefEql(a: ConstRef, b: ConstRef) bool {
    return std.meta.eql(a.artifact.bytes, b.artifact.bytes) and
        constOwnerEql(a.owner, b.owner) and
        a.template == b.template and
        std.meta.eql(a.source_scheme.bytes, b.source_scheme.bytes);
}

fn importedProcedureBindingRefEql(a: ImportedProcedureBindingRef, b: ImportedProcedureBindingRef) bool {
    return std.meta.eql(a.artifact.bytes, b.artifact.bytes) and
        a.def == b.def and
        a.pattern == b.pattern;
}

fn artifactTopLevelProcedureBindingRefEql(a: ArtifactTopLevelProcedureBindingRef, b: ArtifactTopLevelProcedureBindingRef) bool {
    return std.meta.eql(a.artifact.bytes, b.artifact.bytes) and a.binding == b.binding;
}

fn topLevelValueRefEql(a: TopLevelValueRef, b: TopLevelValueRef) bool {
    return std.meta.eql(a.artifact.bytes, b.artifact.bytes) and a.pattern == b.pattern;
}

fn hostedProcRefEql(a: HostedProcRef, b: HostedProcRef) bool {
    return a.module_idx == b.module_idx and
        a.def == b.def and
        canonical.procedureValueRefEql(a.proc, b.proc) and
        canonical.procedureTemplateRefEql(a.template, b.template);
}

fn requiredAppProcedureRefEql(a: RequiredAppProcedureRef, b: RequiredAppProcedureRef) bool {
    return std.meta.eql(a.artifact.bytes, b.artifact.bytes) and
        topLevelValueRefEql(a.app_value, b.app_value) and
        a.procedure_binding == b.procedure_binding;
}

fn constOwnerEql(a: ConstOwner, b: ConstOwner) bool {
    if (std.meta.activeTag(a) != std.meta.activeTag(b)) return false;
    return switch (a) {
        .top_level_binding => |left| blk: {
            const right = b.top_level_binding;
            break :blk left.module_idx == right.module_idx and left.pattern == right.pattern;
        },
        .hoisted_expr => |left| blk: {
            const right = b.hoisted_expr;
            break :blk left.module_idx == right.module_idx and left.expr == right.expr;
        },
    };
}

fn constRefTopLevelOwner(ref: ConstRef) ?ConstTopLevelOwner {
    return switch (ref.owner) {
        .top_level_binding => |owner| owner,
        .hoisted_expr => null,
    };
}

/// Public `procedureBindingRefEql` function.
pub fn procedureBindingRefEql(a: ProcedureBindingRef, b: ProcedureBindingRef) bool {
    if (std.meta.activeTag(a) != std.meta.activeTag(b)) return false;
    return switch (a) {
        .top_level => |left| artifactTopLevelProcedureBindingRefEql(left, b.top_level),
        .imported => |left| importedProcedureBindingRefEql(left, b.imported),
        .hosted => |left| hostedProcRefEql(left, b.hosted),
        .platform_required => |left| requiredAppProcedureRefEql(left, b.platform_required),
    };
}

/// Public `DispatchEvidenceFailure` declaration.
///
/// One dispatch-evidence totality violation found at the check/postcheck
/// boundary by `CheckedModuleArtifact.validateDispatchEvidence`: which rule
/// the artifact breaks and where. `expr` anchors expression-keyed failures,
/// `index` anchors table-keyed ones, and `method` names the dispatch
/// requirement when the anchor carries one.
pub const DispatchEvidenceFailure = struct {
    /// The totality rule the artifact violates.
    pub const Kind = enum {
        dispatch_expr_missing_plan,
        dispatch_expr_plan_out_of_bounds,
        iterator_for_missing_plan,
        iterator_for_plan_out_of_bounds,
        plan_unfinalized_direct,
        plan_evidence_node_out_of_bounds,
        evidence_node_nested_refs_out_of_bounds,
        evidence_ref_node_out_of_bounds,
        site_evidence_key_out_of_bounds,
        site_evidence_refs_out_of_bounds,
        site_evidence_keys_unsorted,
        template_plan_ref_out_of_bounds,
        template_direct_plan_ref_out_of_bounds,
        template_relation_plan_ref_out_of_bounds,
        template_plan_refs_out_of_bounds,
        template_direct_plan_refs_out_of_bounds,
        template_relation_plan_refs_out_of_bounds,
        template_dispatch_partition_mismatch,
        template_relation_metadata_length_mismatch,
        template_specialization_relations_out_of_bounds,
        template_evidence_params_out_of_bounds,
        specialization_scope_parent_invalid,
        specialization_scope_scheme_root_out_of_bounds,
        specialization_scope_expr_out_of_bounds,
        specialization_scope_evidence_params_out_of_bounds,
        specialization_relation_scope_out_of_bounds,
        specialization_relation_type_out_of_bounds,
        specialization_relation_call_args_out_of_bounds,
        specialization_relation_value_ref_out_of_bounds,
        specialization_relation_direct_target_invalid,
        specialization_relation_local_proc_use_invalid,
        evidence_param_path_out_of_bounds,
        evidence_param_path_invalid_kind,
        evidence_param_path_invalid_shape,
        evidence_param_path_diverges_from_checked_type,
    };

    kind: Kind,
    /// Checked expression anchoring an expression-keyed failure.
    expr: ?CheckedExprId = null,
    /// Offending index into the violated rule's table, for table-keyed failures.
    index: ?u32 = null,
    /// The dispatch method the requirement names, when known.
    method: ?canonical.MethodNameId = null,
};

/// Public `CheckedModuleArtifact` declaration.
pub const CheckedModuleArtifact = struct {
    key: CheckedModuleArtifactKey,
    canonical_names: canonical.CanonicalNameStore,
    module_identity: ModuleIdentity,
    checking_context_identity: CheckingContextIdentity,
    direct_import_artifact_keys: []CheckedModuleArtifactKey = &.{},
    public_api_dependencies: PublicApiDependencies = .{},
    lowering_visibility: LoweringVisibility = .{},
    method_lookup_scope: MethodLookupScope = .{},
    module_env: ModuleEnvStorage,
    exports: ExportTable,
    checked_types: CheckedTypeStore = .{},
    checked_bodies: CheckedBodyStore = .{},
    exhaustiveness_sites: CheckedExhaustivenessSiteTable = .{},
    checked_const_bodies: CheckedConstBodyTable = .{},
    exported_procedure_templates: ExportedProcedureTemplateTable = .{},
    exported_procedure_bindings: ExportedProcedureBindingTable = .{},
    exported_const_templates: ExportedConstTemplateTable = .{},
    provides_requires: ProvidesRequiresMetadata,
    provided_exports: ProvidedExportTable = .{},
    method_registry: static_dispatch.MethodRegistry,
    static_dispatch_plans: static_dispatch.StaticDispatchPlanTable,
    resolved_value_refs: ResolvedValueRefTable,
    nested_proc_sites: NestedProcSiteTable = .{},
    checked_procedure_templates: CheckedProcedureTemplateTable,
    entry_wrappers: EntryWrapperTable = .{},
    intrinsic_wrappers: IntrinsicWrapperTable = .{},
    top_level_procedure_bindings: TopLevelProcedureBindingTable,
    callable_eval_templates: CallableEvalTemplateTable = .{},
    root_requests: RootRequestTable,
    hosted_procs: HostedProcTable,
    hosted_bindings: HostedBindingTable = .{},
    platform_required_declarations: PlatformRequiredDeclarationTable,
    platform_requirement_relations: PlatformRequirementRelationTable = .{},
    platform_requirement_solutions: PlatformRequirementSolutionTable = .{},
    platform_required_bindings: PlatformRequiredBindingTable,
    interface_capabilities: ModuleInterfaceCapabilities,
    compile_time_roots: CompileTimeRootTable,
    top_level_values: TopLevelValueTable,
    hoisted_constants: HoistedConstTable,
    const_templates: ConstTemplateTable,
    const_store: ConstStore,
    /// 16-byte-aligned buffer backing a relocated (frozen) artifact loaded from
    /// the disk cache or the compiler's static builtin data. When set, every
    /// sub-store's slices alias this buffer, so `deinit` handles this buffer plus
    /// the injected `module_env` storage and must NOT run the per-sub-store frees
    /// (which would free into the buffer or double-free). `null` for freshly
    /// published artifacts, which own their sub-store allocations individually.
    serialized_backing: ?[]align(CompactWriter.SERIALIZATION_ALIGNMENT.toByteUnits()) u8 = null,
    serialized_backing_is_static: bool = false,

    pub fn moduleEnv(self: *CheckedModuleArtifact) *ModuleEnv {
        return self.module_env.env();
    }

    pub fn moduleEnvConst(self: *const CheckedModuleArtifact) *const ModuleEnv {
        return self.module_env.envConst();
    }

    pub fn platformRequirementContextKey(self: *const CheckedModuleArtifact) PlatformRequirementContextKey {
        return PlatformRequirementContextKey.compute(
            self.module_identity,
            self.platform_required_declarations.identityHash(&self.canonical_names),
        );
    }

    /// A platform with declared app requirements is runtime-lowerable only
    /// after checking has published its exact app relation.
    pub fn hasUnboundPlatformRequirements(self: *const CheckedModuleArtifact) bool {
        return self.module_identity.kind == .platform and
            self.platform_required_declarations.declarations.len > 0 and
            self.checking_context_identity.platform_app_relation == null;
    }

    /// Look up the root request with the given metadata order.
    /// Returns null if not found (callers that rely on an invariant can assert).
    pub fn lookupRootRequestByOrder(self: *const CheckedModuleArtifact, order: u32) ?RootRequest {
        for (self.root_requests.requests) |request| {
            if (request.order == order) return request;
        }
        return null;
    }

    /// Name of a `provided_export` root's published FFI symbol, or null if absent.
    pub fn providedEntrypointName(self: *const CheckedModuleArtifact, root: RootRequest) ?[]const u8 {
        const def_idx = switch (root.source) {
            .def => |def| def,
            .expr,
            .statement,
            .required_binding,
            .hoisted,
            => return null,
        };
        const top_level = self.top_level_values.lookupByDef(def_idx) orelse return null;
        for (self.provides_requires.provides) |entry| {
            if (entry.source_name == top_level.source_name) {
                return self.canonical_names.externalSymbolNameText(entry.ffi_symbol);
            }
        }
        return null;
    }

    /// Name of a `platform_required_binding` root's exported symbol, or null if absent.
    pub fn requiredEntrypointName(self: *const CheckedModuleArtifact, root: RootRequest) ?[]const u8 {
        const binding_id = switch (root.source) {
            .required_binding => |id| id,
            .def,
            .expr,
            .statement,
            .hoisted,
            => return null,
        };
        const binding = self.platform_required_bindings.lookupByBindingId(binding_id) orelse return null;
        const declaration = self.platform_required_declarations.lookupByDeclarationId(binding.declaration) orelse return null;
        return self.canonical_names.exportNameText(declaration.platform_name);
    }

    /// Dispatch to the right name lookup based on the root kind. Returns null
    /// if the root kind isn't an entrypoint kind or the lookup fails.
    pub fn entrypointNameForRoot(self: *const CheckedModuleArtifact, root: RootRequest) ?[]const u8 {
        return switch (root.kind) {
            .provided_export => self.providedEntrypointName(root),
            .platform_required_binding => self.requiredEntrypointName(root),
            .runtime_entrypoint, .hosted_export, .test_expect, .repl_expr, .dev_expr, .compile_time_constant, .compile_time_callable => null,
        };
    }

    /// Extern-compatible inline mirror of `ModuleIdentity`. `ModuleIdentity`
    /// itself is relocation-invariant POD but its `kind` is an ordinary tagged
    /// union, which an `extern struct` cannot embed directly, so the kind is
    /// stored as `ModuleEnv.ModuleKind.Serialized` (a POD `(tag, payload)`
    /// pair). Carries no relocatable pointers.
    pub const ModuleIdentitySerialized = extern struct {
        stable_hash: [32]u8,
        module_idx: u32,
        module_name: canonical.ModuleNameId,
        display_module_name: canonical.ModuleNameId,
        qualified_module_name: canonical.ModuleNameId,
        kind: ModuleEnv.ModuleKind.Serialized,

        pub fn encode(identity: ModuleIdentity) ModuleIdentitySerialized {
            return .{
                .stable_hash = identity.stable_hash,
                .module_idx = identity.module_idx,
                .module_name = identity.module_name,
                .display_module_name = identity.display_module_name,
                .qualified_module_name = identity.qualified_module_name,
                .kind = ModuleEnv.ModuleKind.Serialized.encode(identity.kind),
            };
        }

        pub fn decode(self: ModuleIdentitySerialized) ModuleIdentity {
            return .{
                .stable_hash = self.stable_hash,
                .module_idx = self.module_idx,
                .module_name = self.module_name,
                .display_module_name = self.display_module_name,
                .qualified_module_name = self.qualified_module_name,
                .kind = self.kind.decode(),
            };
        }
    };

    /// Relocatable serialized form of a whole `CheckedModuleArtifact`. Each
    /// sub-store contributes its own `Serialized` form in a fixed field order;
    /// the buffer write order matches this field order. `module_env` is NOT
    /// serialized here (transform E): the env relocates as its own blob and is
    /// injected by the caller at `deserialize` time. `key` and `module_identity`
    /// are relocation-invariant POD stored inline.
    pub const Serialized = extern struct {
        // No field defaults: `Serialized` is only ever produced by `serialize`,
        // which sets every field. Some nested `Serialized` forms (those carrying
        // a `NameInterner`/`SafeList` header) are not default-constructible, so a
        // uniform "no defaults" rule keeps this struct valid.
        key: CheckedModuleArtifactKey,
        module_identity: ModuleIdentitySerialized,
        direct_import_artifact_keys: SerializedSlice(CheckedModuleArtifactKey),
        canonical_names: canonical.CanonicalNameStore.Serialized,
        checking_context_identity: CheckingContextIdentity.Serialized,
        public_api_dependencies: PublicApiDependencies.Serialized,
        lowering_visibility: LoweringVisibility.Serialized,
        method_lookup_scope: MethodLookupScope.Serialized,
        exports: ExportTable.Serialized,
        checked_types: CheckedTypeStore.Serialized,
        checked_bodies: CheckedBodyStore.Serialized,
        checked_const_bodies: CheckedConstBodyTable.Serialized,
        exhaustiveness_sites: CheckedExhaustivenessSiteTable.Serialized,
        exported_procedure_templates: ExportedProcedureTemplateTable.Serialized,
        exported_procedure_bindings: ExportedProcedureBindingTable.Serialized,
        exported_const_templates: ExportedConstTemplateTable.Serialized,
        provides_requires: ProvidesRequiresMetadata.Serialized,
        provided_exports: ProvidedExportTable.Serialized,
        method_registry: static_dispatch.MethodRegistry.Serialized,
        static_dispatch_plans: static_dispatch.StaticDispatchPlanTable.Serialized,
        resolved_value_refs: ResolvedValueRefTable.Serialized,
        nested_proc_sites: NestedProcSiteTable.Serialized,
        checked_procedure_templates: CheckedProcedureTemplateTable.Serialized,
        entry_wrappers: EntryWrapperTable.Serialized,
        intrinsic_wrappers: IntrinsicWrapperTable.Serialized,
        top_level_procedure_bindings: TopLevelProcedureBindingTable.Serialized,
        callable_eval_templates: CallableEvalTemplateTable.Serialized,
        root_requests: RootRequestTable.Serialized,
        hosted_procs: HostedProcTable.Serialized,
        hosted_bindings: HostedBindingTable.Serialized,
        platform_required_declarations: PlatformRequiredDeclarationTable.Serialized,
        platform_requirement_relations: PlatformRequirementRelationTable.Serialized,
        platform_requirement_solutions: PlatformRequirementSolutionTable.Serialized,
        platform_required_bindings: PlatformRequiredBindingTable.Serialized,
        interface_capabilities: ModuleInterfaceCapabilities.Serialized,
        compile_time_roots: CompileTimeRootTable.Serialized,
        top_level_values: TopLevelValueTable.Serialized,
        hoisted_constants: HoistedConstTable.Serialized,
        const_templates: ConstTemplateTable.Serialized,
        const_store: ConstStore.Serialized,

        comptime {
            const owner_only_fields = [_][]const u8{
                "module_env", // Written as the checked-cache env blob and injected during artifact deserialize.
                "serialized_backing", // Runtime ownership for relocated cache/static bytes, not checked data.
                "serialized_backing_is_static", // Runtime ownership mode for `serialized_backing`.
            };
            collections.serde_validation.assertBidirectionalFieldSet(
                CheckedModuleArtifact,
                Serialized,
                &owner_only_fields,
                &.{},
                &.{},
            );

            // The TRUE total relocation fixup count: 1 (`direct_import_artifact_keys`)
            // + the recursive sum of every sub-store, now including the `SafeList`/
            // interner base pointers (`canonical_names` = 22 via its 7 interners +
            // `proc_bases`; `checked_types` includes its `var_names` interner = 3).
            // POD inline `key`/`module_identity` contribute 0. Fixed at compile time,
            // independent of stored data size. The optional-field body tables
            // add three pointers beyond the current-main count.
            std.debug.assert(artifact_serialize.relocatablePointerCount(Serialized) == 212);
        }

        /// Append every sub-store's bytes to `writer` in field order, recording
        /// each one's relocatable offsets. `module_env` is intentionally not
        /// written (transform E); its bytes live in a separate env blob.
        pub fn serialize(
            self: *Serialized,
            artifact: *const CheckedModuleArtifact,
            gpa: Allocator,
            writer: *CompactWriter,
        ) Allocator.Error!void {
            self.key = artifact.key;
            self.module_identity = ModuleIdentitySerialized.encode(artifact.module_identity);
            try self.direct_import_artifact_keys.serialize(artifact.direct_import_artifact_keys, gpa, writer);
            try self.canonical_names.serialize(&artifact.canonical_names, gpa, writer);
            try self.checking_context_identity.serialize(&artifact.checking_context_identity, gpa, writer);
            try self.public_api_dependencies.serialize(&artifact.public_api_dependencies, gpa, writer);
            try self.lowering_visibility.serialize(&artifact.lowering_visibility, gpa, writer);
            try self.method_lookup_scope.serialize(&artifact.method_lookup_scope, gpa, writer);
            try self.exports.serialize(&artifact.exports, gpa, writer);
            try self.checked_types.serialize(&artifact.checked_types, gpa, writer);
            try self.checked_bodies.serialize(&artifact.checked_bodies, gpa, writer);
            try self.checked_const_bodies.serialize(&artifact.checked_const_bodies, gpa, writer);
            try self.exhaustiveness_sites.serialize(&artifact.exhaustiveness_sites, gpa, writer);
            try self.exported_procedure_templates.serialize(&artifact.exported_procedure_templates, gpa, writer);
            try self.exported_procedure_bindings.serialize(&artifact.exported_procedure_bindings, gpa, writer);
            try self.exported_const_templates.serialize(&artifact.exported_const_templates, gpa, writer);
            try self.provides_requires.serialize(&artifact.provides_requires, gpa, writer);
            try self.provided_exports.serialize(&artifact.provided_exports, gpa, writer);
            try self.method_registry.serialize(&artifact.method_registry, gpa, writer);
            try self.static_dispatch_plans.serialize(&artifact.static_dispatch_plans, gpa, writer);
            try self.resolved_value_refs.serialize(&artifact.resolved_value_refs, gpa, writer);
            try self.nested_proc_sites.serialize(&artifact.nested_proc_sites, gpa, writer);
            try self.checked_procedure_templates.serialize(&artifact.checked_procedure_templates, gpa, writer);
            try self.entry_wrappers.serialize(&artifact.entry_wrappers, gpa, writer);
            try self.intrinsic_wrappers.serialize(&artifact.intrinsic_wrappers, gpa, writer);
            try self.top_level_procedure_bindings.serialize(&artifact.top_level_procedure_bindings, gpa, writer);
            try self.callable_eval_templates.serialize(&artifact.callable_eval_templates, gpa, writer);
            try self.root_requests.serialize(&artifact.root_requests, gpa, writer);
            try self.hosted_procs.serialize(&artifact.hosted_procs, gpa, writer);
            try self.hosted_bindings.serialize(&artifact.hosted_bindings, gpa, writer);
            try self.platform_required_declarations.serialize(&artifact.platform_required_declarations, gpa, writer);
            try self.platform_requirement_relations.serialize(&artifact.platform_requirement_relations, gpa, writer);
            try self.platform_requirement_solutions.serialize(&artifact.platform_requirement_solutions, gpa, writer);
            try self.platform_required_bindings.serialize(&artifact.platform_required_bindings, gpa, writer);
            try self.interface_capabilities.serialize(&artifact.interface_capabilities, gpa, writer);
            try self.compile_time_roots.serialize(&artifact.compile_time_roots, gpa, writer);
            try self.top_level_values.serialize(&artifact.top_level_values, gpa, writer);
            try self.hoisted_constants.serialize(&artifact.hoisted_constants, gpa, writer);
            try self.const_templates.serialize(&artifact.const_templates, gpa, writer);
            try self.const_store.serialize(&artifact.const_store, gpa, writer);
        }

        /// Materialize a frozen artifact from its relocated `backing` buffer (whose
        /// start IS this `Serialized` header). The artifact is SELF-DESCRIBING: it
        /// stores `backing` in `serialized_backing`, so a single `deinit` frees the
        /// buffer (and the injected env) correctly for every caller—no per-call-site
        /// teardown contract. `module_env` is supplied by the caller (transform E): the
        /// env blob is relocated/owned separately and injected here, never serialized.
        /// `gpa` is retained only by the sub-stores that keep an allocator for their
        /// build-only fields (`canonical_names`, `const_store`).
        /// L-10 whole-artifact validation pass. Bounds-check every relocatable
        /// marker's `(offset, len)` against the `backing`-buffer length BEFORE
        /// `deserialize` materializes any aliasing slice, so a truncated or corrupt
        /// blob (builtin trailer / disk cache) fails cleanly instead of producing
        /// dangling out-of-bounds slices. Callers run this immediately after casting
        /// the buffer to `*const Serialized` and before `deserialize`.
        pub fn validate(self: *const Serialized, backing_len: usize) error{CorruptArtifact}!void {
            if (backing_len < @sizeOf(Serialized)) return error.CorruptArtifact;
            try artifact_serialize.validateSerialized(Serialized, self, backing_len);
        }

        pub fn deserialize(
            self: *const Serialized,
            backing: []align(CompactWriter.SERIALIZATION_ALIGNMENT.toByteUnits()) u8,
            gpa: Allocator,
            module_env: ModuleEnvStorage,
        ) CheckedModuleArtifact {
            return self.deserializeWithBacking(backing, gpa, module_env, false);
        }

        pub fn deserializeStatic(
            self: *const Serialized,
            backing: []align(CompactWriter.SERIALIZATION_ALIGNMENT.toByteUnits()) u8,
            gpa: Allocator,
            module_env: ModuleEnvStorage,
        ) CheckedModuleArtifact {
            return self.deserializeWithBacking(backing, gpa, module_env, true);
        }

        fn deserializeWithBacking(
            self: *const Serialized,
            backing: []align(CompactWriter.SERIALIZATION_ALIGNMENT.toByteUnits()) u8,
            gpa: Allocator,
            module_env: ModuleEnvStorage,
            backing_is_static: bool,
        ) CheckedModuleArtifact {
            const base_addr = @intFromPtr(backing.ptr);
            return .{
                .key = self.key,
                .module_identity = self.module_identity.decode(),
                .module_env = module_env,
                .serialized_backing = backing,
                .serialized_backing_is_static = backing_is_static,
                .direct_import_artifact_keys = self.direct_import_artifact_keys.deserialize(base_addr),
                .canonical_names = self.canonical_names.deserialize(base_addr, gpa),
                .checking_context_identity = self.checking_context_identity.deserialize(base_addr),
                .public_api_dependencies = self.public_api_dependencies.deserialize(base_addr),
                .lowering_visibility = self.lowering_visibility.deserialize(base_addr),
                .method_lookup_scope = self.method_lookup_scope.deserialize(base_addr),
                .exports = self.exports.deserialize(base_addr),
                .checked_types = self.checked_types.deserialize(base_addr),
                .checked_bodies = self.checked_bodies.deserialize(base_addr),
                .checked_const_bodies = self.checked_const_bodies.deserialize(base_addr),
                .exhaustiveness_sites = self.exhaustiveness_sites.deserialize(base_addr),
                .exported_procedure_templates = self.exported_procedure_templates.deserialize(base_addr),
                .exported_procedure_bindings = self.exported_procedure_bindings.deserialize(base_addr),
                .exported_const_templates = self.exported_const_templates.deserialize(base_addr),
                .provides_requires = self.provides_requires.deserialize(base_addr),
                .provided_exports = self.provided_exports.deserialize(base_addr),
                .method_registry = self.method_registry.deserialize(base_addr),
                .static_dispatch_plans = self.static_dispatch_plans.deserialize(base_addr),
                .resolved_value_refs = self.resolved_value_refs.deserialize(base_addr),
                .nested_proc_sites = self.nested_proc_sites.deserialize(base_addr),
                .checked_procedure_templates = self.checked_procedure_templates.deserialize(base_addr),
                .entry_wrappers = self.entry_wrappers.deserialize(base_addr),
                .intrinsic_wrappers = self.intrinsic_wrappers.deserialize(base_addr),
                .top_level_procedure_bindings = self.top_level_procedure_bindings.deserialize(base_addr),
                .callable_eval_templates = self.callable_eval_templates.deserialize(base_addr),
                .root_requests = self.root_requests.deserialize(base_addr),
                .hosted_procs = self.hosted_procs.deserialize(base_addr),
                .hosted_bindings = self.hosted_bindings.deserialize(base_addr),
                .platform_required_declarations = self.platform_required_declarations.deserialize(base_addr),
                .platform_requirement_relations = self.platform_requirement_relations.deserialize(base_addr),
                .platform_requirement_solutions = self.platform_requirement_solutions.deserialize(base_addr),
                .platform_required_bindings = self.platform_required_bindings.deserialize(base_addr),
                .interface_capabilities = self.interface_capabilities.deserialize(base_addr),
                .compile_time_roots = self.compile_time_roots.deserialize(base_addr),
                .top_level_values = self.top_level_values.deserialize(base_addr),
                .hoisted_constants = self.hoisted_constants.deserialize(base_addr),
                .const_templates = self.const_templates.deserialize(base_addr),
                .const_store = self.const_store.deserialize(base_addr, gpa),
            };
        }
    };

    /// Manual discriminant for `SERIALIZED_VERSION_HASH`: bump to force a cache /
    /// baked-blob invalidation for a layout change the structural fingerprint below
    /// cannot observe (e.g. a semantic change to how a field is interpreted).
    // Version 57 (over upstream 56) publishes the optional/defaulted record
    // field machinery: checked record-field access paths as ordered segment
    // ranges with explicit successful-prefix types, source regions, access
    // modes (`CheckedFieldAccessSegment.mode`—`.?` segments reach checked
    // bodies), and per-segment backing access; the field-kind axis on
    // checked record fields (`CheckedRecordField.kind`:
    // required/optional/defaulted plus the defaulted identity, design.md
    // "Field Kinds (All-Dynamic Optional Fields)"); the body store's
    // default-expression table (`default_exprs`); and `checked_ids.OptionalId`
    // encodings for inline optional ids. Version 58: const-store record type
    // evidence carries the `??` default identity
    // (`ConstStore.TypeField.default`), mirroring the Monotype
    // `Type.FieldDefault` axis (design.md "Defaulted Fields").
    // Version 59 combines the optional/defaulted field layouts above with
    // upstream's version-57 artifact change.
    // Version 60 preserves generalized field-kind variable identities and
    // optional source-value types in stored const evidence.
    // Version 61 gives every compile-time request its exact checked-root ID.
    // Version 62 publishes exact record-construction omission defaults.
    // Version 63 lets a field-default root own its literal conversion instead
    // of publishing a second root for the same checked expression.
    const serialized_layout_version: u32 = 63;

    /// Comptime fingerprint of `Serialized`'s layout, mirroring
    /// `cache_module.MODULE_ENV_VERSION_HASH`. It is appended to the baked builtin
    /// artifact blob and stored in the on-disk module-cache header, then validated
    /// on load (`expectSerializedVersion`), so an artifact serialized by a compiler
    /// with a different `Serialized` layout is rejected rather than relocated into a
    /// mismatched struct (a real hazard during development, where
    /// `build_options.compiler_version` is a fixed release string that does not move
    /// between rebuilds).
    pub const SERIALIZED_VERSION_HASH: [32]u8 =
        artifact_serialize.layoutVersionHash(Serialized, serialized_layout_version);

    // A-11: validate the entire serialized sub-store tree at compile time—every
    // field must be a relocatable marker or relocation-invariant POD (a raw pointer
    // embedded outside a marker would silently dangle after relocation).
    comptime {
        artifact_serialize.assertSerializedRelocatable(Serialized);
    }

    /// Validate a version hash read from a serialized artifact (builtin blob trailer
    /// or cache header) against the running compiler's `SERIALIZED_VERSION_HASH`.
    pub fn expectSerializedVersion(found: *const [32]u8) bool {
        // Manual byte compare: `std.mem.eql` is banned in src/check (raw byte
        // comparison is a type-checker-identity footgun); a fixed-length hash
        // compare here is unambiguous.
        for (found, &SERIALIZED_VERSION_HASH) |a, b| {
            if (a != b) return false;
        }
        return true;
    }

    /// Length of the version trailer the builtin baker appends to its blob.
    pub const VERSION_TRAILER_LEN = SERIALIZED_VERSION_HASH.len;

    /// The baked builtin blob is laid out `[serialized bytes][version trailer]`: the
    /// baker (`builtin_compiler`) writes the `Serialized` at offset 0 and appends
    /// `SERIALIZED_VERSION_HASH` as a trailer. This validates that trailer against the
    /// running compiler's layout hash and returns the serialized prefix to relocate,
    /// keeping the one place that knows the trailer's position. A stale or truncated
    /// blob is rejected rather than relocated into a mismatched struct.
    pub fn splitVersionTrailer(blob: []const u8) error{ CorruptBuiltinArtifact, BuiltinArtifactVersionMismatch }![]const u8 {
        if (blob.len < VERSION_TRAILER_LEN) return error.CorruptBuiltinArtifact;
        const serialized_len = blob.len - VERSION_TRAILER_LEN;
        // The serialized prefix must be at least a whole `Serialized` header—the loader
        // `@ptrCast`s it to `*const Serialized`. This mirrors the disk-cache loader's
        // `< @sizeOf(Serialized)` floor so a truncated builtin blob is a clean error, not
        // an out-of-bounds read.
        if (serialized_len < @sizeOf(Serialized)) return error.CorruptBuiltinArtifact;
        if (!expectSerializedVersion(blob[serialized_len..][0..VERSION_TRAILER_LEN])) {
            return error.BuiltinArtifactVersionMismatch;
        }
        return blob[0..serialized_len];
    }

    pub fn deinit(self: *CheckedModuleArtifact, allocator: Allocator) void {
        self.deinitInternal(allocator, true);
    }

    pub fn deinitRetainingModuleEnv(self: *CheckedModuleArtifact, allocator: Allocator) void {
        self.deinitInternal(allocator, false);
    }

    fn deinitInternal(self: *CheckedModuleArtifact, allocator: Allocator, comptime deinit_module_env: bool) void {
        if (self.serialized_backing) |backing| {
            // Frozen artifact: every sub-store aliases `backing`, so running the
            // per-sub-store frees would free into the buffer (and the unconditional
            // `direct_import_artifact_keys` free below points into it too). Free
            // only the buffer and the injected env storage, mirroring how a
            // `cached_buffer`/`static_builtin`-backed module is torn down.
            if (deinit_module_env) {
                self.module_env.deinit();
            } else {
                self.module_env = undefined;
            }
            if (!self.serialized_backing_is_static) {
                // `deserialize` allocated `backing` with the same gpa it recorded in
                // `canonical_names.allocator`, and every teardown site passes that
                // allocator back here. Assert the coupling so a caller freeing the
                // frozen buffer with a different allocator trips in Debug rather than
                // corrupting an unrelated heap.
                std.debug.assert(allocator.ptr == self.canonical_names.allocator.ptr and
                    allocator.vtable == self.canonical_names.allocator.vtable);
                allocator.free(backing);
            }
            self.* = undefined;
            return;
        }
        self.const_store.deinit();
        self.const_templates.deinit(allocator);
        self.hoisted_constants.deinit(allocator);
        self.top_level_values.deinit(allocator);
        self.compile_time_roots.deinit(allocator);
        self.interface_capabilities.deinit(allocator);
        self.platform_required_bindings.deinit(allocator);
        self.platform_requirement_solutions.deinit(allocator);
        self.platform_requirement_relations.deinit(allocator);
        self.platform_required_declarations.deinit(allocator);
        self.hosted_bindings.deinit(allocator);
        self.hosted_procs.deinit(allocator);
        self.root_requests.deinit(allocator);
        self.callable_eval_templates.deinit(allocator);
        self.top_level_procedure_bindings.deinit(allocator);
        self.intrinsic_wrappers.deinit(allocator);
        self.entry_wrappers.deinit(allocator);
        self.checked_procedure_templates.deinit(allocator);
        self.nested_proc_sites.deinit(allocator);
        self.resolved_value_refs.deinit(allocator);
        self.static_dispatch_plans.deinit(allocator);
        self.method_registry.deinit(allocator);
        self.provided_exports.deinit(allocator);
        self.provides_requires.deinit(allocator);
        self.exported_const_templates.deinit(allocator);
        self.exported_procedure_bindings.deinit(allocator);
        self.exported_procedure_templates.deinit(allocator);
        self.checked_const_bodies.deinit(allocator);
        self.exhaustiveness_sites.deinit(allocator);
        self.checked_bodies.deinit(allocator);
        self.checked_types.deinit(allocator);
        self.exports.deinit(allocator);
        self.method_lookup_scope.deinit(allocator);
        self.lowering_visibility.deinit(allocator);
        self.public_api_dependencies.deinit(allocator);
        allocator.free(self.direct_import_artifact_keys);
        self.checking_context_identity.deinit(allocator);
        self.canonical_names.deinit();
        if (deinit_module_env) {
            self.module_env.deinit();
        } else {
            self.module_env = undefined;
        }
    }

    pub fn verifyReadyForCompileTimeLowering(self: *const CheckedModuleArtifact) void {
        if (builtin.mode != .Debug) return;

        std.debug.assert(self.module_identity.module_idx != std.math.maxInt(u32));
        std.debug.assert(self.checked_types.roots.items.len == self.checked_types.payloads.items.len);
        verifyRootRequestSubsets(self.root_requests);

        for (self.checked_types.payloads.items, 0..) |payload, i| {
            switch (payload) {
                .pending => std.debug.panic("checked artifact invariant violated: checked type payload {d} was not filled before compile-time lowering", .{i}),
                .err,
                .flex,
                .rigid,
                .alias,
                .record,
                .record_unbound,
                .tuple,
                .nominal,
                .function,
                .empty_record,
                .tag_union,
                .empty_tag_union,
                => {},
            }
        }

        for (self.checked_bodies.stored_exprs.items, 0..) |expr, i| {
            std.debug.assert(@intFromEnum(expr.id) == i);
            std.debug.assert(@intFromEnum(expr.ty) < self.checked_types.roots.items.len);
            verifyCheckedExprDataComplete(expr.data, &self.checked_bodies, self.checked_types.roots.items.len);
        }

        for (self.checked_const_bodies.bodies, 0..) |body, i| {
            std.debug.assert(@intFromEnum(body.id) == i);
            std.debug.assert(@intFromEnum(body.root) < self.compile_time_roots.roots.len);
            const root = self.compile_time_roots.root(body.root);
            std.debug.assert(compileTimeRootHasConstBody(root.kind));
            std.debug.assert(root.expr == body.body_expr);
            std.debug.assert(root.checked_type == body.checked_type);
            std.debug.assert(@intFromEnum(body.body_expr) < self.checked_bodies.exprCount());
            std.debug.assert(@intFromEnum(body.checked_type) < self.checked_types.roots.items.len);
        }

        for (self.root_requests.requests, 0..) |request, i| {
            std.debug.assert(request.order == i);
            std.debug.assert(request.module_idx == self.module_identity.module_idx);
            std.debug.assert(@intFromEnum(request.checked_type) < self.checked_types.roots.items.len);
            if (request.abi == .compile_time) {
                const template_ref = request.procedure_template orelse {
                    std.debug.panic("checked artifact invariant violated: compile-time root has no private wrapper template", .{});
                };
                std.debug.assert(@intFromEnum(template_ref.template) < self.checked_procedure_templates.templates.len);
                const template = self.checked_procedure_templates.get(template_ref.template);
                switch (template.target) {
                    .comptime_only => {},
                    .roc, .hosted, .intrinsic, .entry => std.debug.panic("checked artifact invariant violated: compile-time root wrapper was not marked comptime_only", .{}),
                }
            }
        }

        for (self.compile_time_roots.roots, 0..) |root, i| {
            std.debug.assert(@intFromEnum(root.id) == i);
            std.debug.assert(root.module_idx == self.module_identity.module_idx);
            std.debug.assert(@intFromEnum(root.expr) < self.checked_bodies.exprCount());
            verifyCompileTimeRootLiteralConversion(root);
            if (root.pattern) |pattern| std.debug.assert(@intFromEnum(pattern) < self.checked_bodies.patternCount());
            switch (root.kind) {
                .constant, .hoisted_constant, .callable_binding, .numeral_conversion, .quote_conversion, .field_default => switch (root.payload) {
                    .pending => {},
                    .const_node,
                    .fn_value,
                    .expect,
                    => verifyCompileTimeRootPayloadMatchesKind(root.kind, root.payload),
                },
                .expect => switch (root.payload) {
                    .expect => {},
                    .pending,
                    .const_node,
                    .fn_value,
                    => std.debug.panic("checked artifact invariant violated: expect root has non-expect payload before compile-time lowering", .{}),
                },
            }
        }
    }

    /// One dispatch-expression plan reference checked for the boundary
    /// validator: `required` distinguishes expressions that must always name
    /// a plan from the numeral/quote fast paths, where a null plan means the
    /// concrete-builtin route that never consults one.
    fn dispatchPlanFailure(
        table: *const static_dispatch.StaticDispatchPlanTable,
        maybe_plan: ?StaticDispatchPlanId,
        expr: CheckedExprId,
        required: bool,
    ) ?DispatchEvidenceFailure {
        const plan = maybe_plan orelse
            return if (required) .{ .kind = .dispatch_expr_missing_plan, .expr = expr } else null;
        if (@intFromEnum(plan) >= table.plans.len) {
            return .{ .kind = .dispatch_expr_plan_out_of_bounds, .expr = expr };
        }
        return null;
    }

    /// The iterator-plan twin of `dispatchPlanFailure`; `for_` always
    /// requires a plan, anchored by expression or statement index.
    fn iteratorPlanFailure(
        table: *const static_dispatch.StaticDispatchPlanTable,
        maybe_plan: ?static_dispatch.IteratorForPlanId,
        expr: ?CheckedExprId,
        index: ?u32,
    ) ?DispatchEvidenceFailure {
        const plan = maybe_plan orelse
            return .{ .kind = .iterator_for_missing_plan, .expr = expr, .index = index };
        if (@intFromEnum(plan) >= table.iterator_for_plans.len) {
            return .{ .kind = .iterator_for_plan_out_of_bounds, .expr = expr, .index = index };
        }
        return null;
    }

    fn evidencePathGrammarFailure(path: []const static_dispatch.EvidencePathStep) ?DispatchEvidenceFailure.Kind {
        var path_index: usize = 0;
        while (path_index < path.len) {
            const path_step = path[path_index];
            const kind = path_step.kindOrNull() orelse return .evidence_param_path_invalid_kind;
            path_index += 1;
            switch (kind) {
                .fn_ret, .alias_backing, .nominal_backing => {
                    if (path_step.data != 0) return .evidence_param_path_invalid_shape;
                },
                .tag_payload_tag => {
                    if (path_index >= path.len) return .evidence_param_path_invalid_shape;
                    const payload_kind = path[path_index].kindOrNull() orelse return .evidence_param_path_invalid_kind;
                    if (payload_kind != .tag_payload_index) return .evidence_param_path_invalid_shape;
                    path_index += 1;
                },
                .tag_payload_index => return .evidence_param_path_invalid_shape,
                .fn_arg, .alias_arg, .nominal_arg, .tuple_elem, .record_field => {},
            }
        }
        return null;
    }

    fn checkedPayloadOrNull(view: CheckedTypeStoreView, ty: CheckedTypeId) ?CheckedTypePayload {
        if (@intFromEnum(ty) >= view.payloadCount()) return null;
        return view.payload(ty);
    }

    /// Resolve one logical record-field selection over the published checked
    /// row. Aliases and row extensions are transparent producer topology; a
    /// nominal is not, matching the durable path and Monotype consumer.
    fn checkedEvidenceRecordFieldChild(
        view: CheckedTypeStoreView,
        names: *const canonical.CanonicalNameStore,
        root: CheckedTypeId,
        label: canonical.RecordFieldLabelId,
    ) ?CheckedTypeId {
        var current = root;
        var remaining = view.payloadCount() + 1;
        while (remaining > 0) : (remaining -= 1) {
            switch (checkedPayloadOrNull(view, current) orelse return null) {
                .alias => |alias| current = alias.backing,
                .record => |record| {
                    for (record.fields) |field| {
                        if (names.recordFieldLabelTextEql(field.name, label)) return field.ty;
                    }
                    current = record.ext;
                },
                .record_unbound => |fields| {
                    for (fields) |field| {
                        if (names.recordFieldLabelTextEql(field.name, label)) return field.ty;
                    }
                    return null;
                },
                .pending,
                .err,
                .flex,
                .rigid,
                .tuple,
                .nominal,
                .function,
                .empty_record,
                .tag_union,
                .empty_tag_union,
                => return null,
            }
        }
        return null;
    }

    /// Resolve one logical tag-payload selection over the published checked
    /// row, with the same alias/extension normalization as record fields.
    fn checkedEvidenceTagPayloadChild(
        view: CheckedTypeStoreView,
        names: *const canonical.CanonicalNameStore,
        root: CheckedTypeId,
        label: canonical.TagLabelId,
        payload_index: u32,
    ) ?CheckedTypeId {
        var current = root;
        var remaining = view.payloadCount() + 1;
        while (remaining > 0) : (remaining -= 1) {
            switch (checkedPayloadOrNull(view, current) orelse return null) {
                .alias => |alias| current = alias.backing,
                .tag_union => |tag_union| {
                    for (tag_union.tags) |tag| {
                        if (!names.tagLabelTextEql(tag.name, label)) continue;
                        const payloads = tag.argsSlice(view);
                        if (payload_index >= payloads.len) return null;
                        return payloads[payload_index];
                    }
                    current = tag_union.ext;
                },
                .pending,
                .err,
                .flex,
                .rigid,
                .record,
                .record_unbound,
                .tuple,
                .nominal,
                .function,
                .empty_record,
                .empty_tag_union,
                => return null,
            }
        }
        return null;
    }

    /// Verify that a normalized path selects a real component of the
    /// template's published checked callable. This mirrors Monotype's path
    /// vocabulary while resolving row labels across complete logical rows.
    fn checkedEvidencePathResolves(
        self: *const CheckedModuleArtifact,
        start_ty: CheckedTypeId,
        path: []const static_dispatch.EvidencePathStep,
    ) bool {
        const view = self.checked_types.view();
        var ty = start_ty;
        var path_index: usize = 0;
        while (path_index < path.len) {
            const path_step = path[path_index];
            const kind = path_step.kindOrNull() orelse return false;
            path_index += 1;
            const payload = checkedPayloadOrNull(view, ty) orelse return false;
            switch (kind) {
                .fn_arg => {
                    if (payload != .function) return false;
                    if (path_step.data >= payload.function.args.len) return false;
                    ty = payload.function.args[path_step.data];
                },
                .fn_ret => {
                    if (payload != .function) return false;
                    ty = payload.function.ret;
                },
                .alias_arg => {
                    if (payload != .alias) return false;
                    if (path_step.data >= payload.alias.args.len) return false;
                    ty = payload.alias.args[path_step.data];
                },
                .alias_backing => {
                    if (payload != .alias) return false;
                    ty = payload.alias.backing;
                },
                .nominal_arg => {
                    if (payload != .nominal) return false;
                    if (path_step.data >= payload.nominal.args.len) return false;
                    ty = payload.nominal.args[path_step.data];
                },
                .nominal_backing => {
                    if (payload != .nominal) return false;
                    ty = view.nominalBackingTemplateForPayload(payload.nominal) orelse return false;
                },
                .tuple_elem => {
                    if (payload != .tuple) return false;
                    if (path_step.data >= payload.tuple.len) return false;
                    ty = payload.tuple[path_step.data];
                },
                .record_field => {
                    if (path_step.data >= self.canonical_names.recordFieldLabelCount()) return false;
                    ty = checkedEvidenceRecordFieldChild(
                        view,
                        &self.canonical_names,
                        ty,
                        @enumFromInt(path_step.data),
                    ) orelse return false;
                },
                .tag_payload_tag => {
                    if (path_index >= path.len) return false;
                    const payload_step = path[path_index];
                    if (payload_step.kindOrNull() != .tag_payload_index) return false;
                    path_index += 1;
                    if (path_step.data >= self.canonical_names.tagLabelCount()) return false;
                    ty = checkedEvidenceTagPayloadChild(
                        view,
                        &self.canonical_names,
                        ty,
                        @enumFromInt(path_step.data),
                        payload_step.data,
                    ) orelse return false;
                },
                .tag_payload_index => return false,
            }
        }
        return true;
    }

    /// Public `validateDispatchEvidence` function.
    ///
    /// Dispatch-evidence totality at the check/postcheck boundary: every
    /// dispatch-bearing checked expression names a plan, every plan and
    /// evidence reference lands inside the artifact's evidence tables, and
    /// the site-evidence index is sound. Monotype lowering consumes these
    /// records without re-deriving targets, so a violation is a compiler bug
    /// reported here at the boundary (in debug builds, where `verifyComplete`
    /// runs)—not a lowering panic. Returns the first failure found, or
    /// null when the artifact is total.
    pub fn validateDispatchEvidence(self: *const CheckedModuleArtifact) ?DispatchEvidenceFailure {
        const table = &self.static_dispatch_plans;

        for (self.checked_bodies.stored_exprs.items) |expr| {
            const expr_failure: ?DispatchEvidenceFailure = if (expr.data == .dispatch_call)
                dispatchPlanFailure(table, expr.data.dispatch_call, expr.id, true)
            else if (expr.data == .type_dispatch_call)
                dispatchPlanFailure(table, expr.data.type_dispatch_call, expr.id, true)
            else if (expr.data == .method_eq)
                dispatchPlanFailure(table, expr.data.method_eq, expr.id, true)
            else if (expr.data == .interpolation)
                dispatchPlanFailure(table, expr.data.interpolation.plan, expr.id, true)
            else if (expr.data == .numeral)
                dispatchPlanFailure(table, expr.data.numeral.plan, expr.id, false)
            else if (expr.data == .str_from_quote)
                dispatchPlanFailure(table, expr.data.str_from_quote.plan, expr.id, false)
            else if (expr.data == .for_)
                iteratorPlanFailure(table, expr.data.for_.plan, expr.id, null)
            else
                null;
            if (expr_failure) |failure| return failure;
        }

        for (self.checked_bodies.stored_statements.items, 0..) |statement, i| {
            const statement_failure: ?DispatchEvidenceFailure = if (statement.data == .for_)
                iteratorPlanFailure(table, statement.data.for_.plan, null, @intCast(i))
            else
                null;
            if (statement_failure) |failure| return failure;
        }

        for (table.plans, 0..) |plan, i| {
            switch (plan.resolution) {
                .direct_pending => return .{
                    .kind = .plan_unfinalized_direct,
                    .expr = plan.expr,
                    .index = @intCast(i),
                    .method = plan.method,
                },
                .direct_closed, .direct_parametric => |direct| if (@intFromEnum(direct.evidence) >= table.evidence_nodes.len) {
                    return .{
                        .kind = .plan_evidence_node_out_of_bounds,
                        .expr = plan.expr,
                        .index = @intCast(i),
                        .method = plan.method,
                    };
                },
                .evidence_dependent, .structural, .checked_error, .@"unreachable" => {},
            }
        }
        for (table.iterator_for_plans, 0..) |plan, i| {
            for ([2]static_dispatch.IteratorDispatchCall{ plan.iter, plan.next }) |call| {
                switch (call.resolution) {
                    .direct_pending => return .{
                        .kind = .plan_unfinalized_direct,
                        .index = @intCast(i),
                        .method = call.method,
                    },
                    .direct_closed, .direct_parametric => |direct| if (@intFromEnum(direct.evidence) >= table.evidence_nodes.len) {
                        return .{
                            .kind = .plan_evidence_node_out_of_bounds,
                            .index = @intCast(i),
                            .method = call.method,
                        };
                    },
                    .evidence_dependent, .structural, .checked_error, .@"unreachable" => {},
                }
            }
        }

        for (table.evidence_nodes, 0..) |node, i| {
            switch (node.nested) {
                .resolved => |nested| if (@as(u64, nested.start) + nested.len > table.evidence_refs.len) {
                    return .{ .kind = .evidence_node_nested_refs_out_of_bounds, .index = @intCast(i) };
                },
                .from_callable => {},
            }
        }
        for (table.evidence_refs, 0..) |ref, i| {
            switch (ref.resolution) {
                .direct => |node| if (@intFromEnum(node) >= table.evidence_nodes.len) {
                    return .{ .kind = .evidence_ref_node_out_of_bounds, .index = @intCast(i) };
                },
                .constraint, .structural, .from_callable, .checked_error, .unreachable_value => {},
            }
        }

        for (table.site_evidence, 0..) |entry, i| {
            if (entry.key >= self.checked_bodies.exprCount()) {
                return .{ .kind = .site_evidence_key_out_of_bounds, .index = @intCast(i) };
            }
            if (@as(u64, entry.start) + entry.len > table.evidence_refs.len) {
                return .{ .kind = .site_evidence_refs_out_of_bounds, .index = @intCast(i) };
            }
            if (i > 0 and table.site_evidence[i - 1].key >= entry.key) {
                return .{ .kind = .site_evidence_keys_unsorted, .index = @intCast(i) };
            }
        }

        for (table.template_refs, 0..) |plan_id, i| {
            if (@intFromEnum(plan_id) >= table.plans.len) {
                return .{ .kind = .template_plan_ref_out_of_bounds, .index = @intCast(i) };
            }
        }
        for (table.direct_template_refs, 0..) |plan_id, i| {
            if (@intFromEnum(plan_id) >= table.plans.len) {
                return .{ .kind = .template_direct_plan_ref_out_of_bounds, .index = @intCast(i) };
            }
        }
        for (table.dispatch_relation_refs, 0..) |plan_id, i| {
            if (@intFromEnum(plan_id) >= table.plans.len) {
                return .{ .kind = .template_relation_plan_ref_out_of_bounds, .index = @intCast(i) };
            }
        }

        const templates = &self.checked_procedure_templates;
        if (templates.dispatch_ref_scopes.len != table.dispatch_relation_refs.len or
            templates.dispatch_relation_kinds.len != table.dispatch_relation_refs.len)
        {
            return .{ .kind = .template_relation_metadata_length_mismatch };
        }
        for (templates.templates, 0..) |template, i| {
            if (@as(u64, template.static_dispatch_plans.start) + template.static_dispatch_plans.len > table.template_refs.len) {
                return .{ .kind = .template_plan_refs_out_of_bounds, .index = @intCast(i) };
            }
            if (@as(u64, template.direct_dispatch_plans.start) + template.direct_dispatch_plans.len > table.direct_template_refs.len) {
                return .{ .kind = .template_direct_plan_refs_out_of_bounds, .index = @intCast(i) };
            }
            if (@as(u64, template.dispatch_relations.start) + template.dispatch_relations.len > table.dispatch_relation_refs.len) {
                return .{ .kind = .template_relation_plan_refs_out_of_bounds, .index = @intCast(i) };
            }
            if (@as(u64, template.specialization_interface_relations.start) + template.specialization_interface_relations.len > templates.specialization_interface_relations.len) {
                return .{ .kind = .template_specialization_relations_out_of_bounds, .index = @intCast(i) };
            }
            if (template.direct_dispatch_plans.len + template.dispatch_relations.len != template.static_dispatch_plans.len) {
                return .{ .kind = .template_dispatch_partition_mismatch, .index = @intCast(i) };
            }
            const all_refs = table.template_refs[template.static_dispatch_plans.start .. template.static_dispatch_plans.start + template.static_dispatch_plans.len];
            const direct_refs = table.direct_template_refs[template.direct_dispatch_plans.start .. template.direct_dispatch_plans.start + template.direct_dispatch_plans.len];
            const relation_refs = table.dispatch_relation_refs[template.dispatch_relations.start .. template.dispatch_relations.start + template.dispatch_relations.len];
            var direct_index: usize = 0;
            var relation_index: usize = 0;
            for (all_refs) |plan_id| {
                const classified = if (checkedDispatchPlanNeedsRelation(table, table.plans[@intFromEnum(plan_id)])) blk: {
                    if (relation_index >= relation_refs.len) {
                        return .{ .kind = .template_dispatch_partition_mismatch, .index = @intCast(i) };
                    }
                    defer relation_index += 1;
                    break :blk relation_refs[relation_index];
                } else blk: {
                    if (direct_index >= direct_refs.len) {
                        return .{ .kind = .template_dispatch_partition_mismatch, .index = @intCast(i) };
                    }
                    defer direct_index += 1;
                    break :blk direct_refs[direct_index];
                };
                if (classified != plan_id) {
                    return .{ .kind = .template_dispatch_partition_mismatch, .index = @intCast(i) };
                }
            }
            if (@as(u64, template.evidence_params.start) + template.evidence_params.len > templates.evidence_params_pool.len) {
                return .{ .kind = .template_evidence_params_out_of_bounds, .index = @intCast(i) };
            }
        }
        for (templates.dispatch_scopes, 0..) |scope, i| {
            if (scope.parent) |parent| {
                if (@intFromEnum(parent) >= i) {
                    return .{ .kind = .specialization_scope_parent_invalid, .index = @intCast(i) };
                }
            }
            if (@intFromEnum(scope.scheme_root) >= self.checked_types.payloadCount()) {
                return .{ .kind = .specialization_scope_scheme_root_out_of_bounds, .index = @intCast(i) };
            }
            if (@intFromEnum(scope.checked_expr) >= self.checked_bodies.exprCount()) {
                return .{ .kind = .specialization_scope_expr_out_of_bounds, .index = @intCast(i) };
            }
            if (@as(u64, scope.evidence_params.start) + scope.evidence_params.len > templates.evidence_params_pool.len) {
                return .{ .kind = .specialization_scope_evidence_params_out_of_bounds, .index = @intCast(i) };
            }
        }
        for (templates.specialization_interface_relations, 0..) |relation, i| {
            switch (relation.scope) {
                .root => {},
                .generalized => |scope| if (@intFromEnum(scope) >= templates.dispatch_scopes.len) {
                    return .{ .kind = .specialization_relation_scope_out_of_bounds, .index = @intCast(i) };
                },
            }
            switch (relation.data) {
                .type_equality => |equality| {
                    if (@intFromEnum(equality.left) >= self.checked_types.payloadCount() or
                        @intFromEnum(equality.right) >= self.checked_types.payloadCount())
                    {
                        return .{ .kind = .specialization_relation_type_out_of_bounds, .index = @intCast(i) };
                    }
                },
                .procedure => |procedure| {
                    if (@intFromEnum(procedure.fn_ty) >= self.checked_types.payloadCount() or
                        @intFromEnum(procedure.body_ret_ty) >= self.checked_types.payloadCount())
                    {
                        return .{ .kind = .specialization_relation_type_out_of_bounds, .index = @intCast(i) };
                    }
                },
                .call => |call| {
                    if (@intFromEnum(call.callable_ty) >= self.checked_types.payloadCount() or
                        @intFromEnum(call.callee_ty) >= self.checked_types.payloadCount() or
                        @intFromEnum(call.ret_ty) >= self.checked_types.payloadCount())
                    {
                        return .{ .kind = .specialization_relation_type_out_of_bounds, .index = @intCast(i) };
                    }
                    if (@as(u64, call.args.start) + call.args.len > templates.specialization_interface_types.len) {
                        return .{ .kind = .specialization_relation_call_args_out_of_bounds, .index = @intCast(i) };
                    }
                    for (templates.specializationRelationTypes(call.args)) |arg_ty| {
                        if (@intFromEnum(arg_ty) >= self.checked_types.payloadCount()) {
                            return .{ .kind = .specialization_relation_type_out_of_bounds, .index = @intCast(i) };
                        }
                    }
                    if (call.direct_target) |target| {
                        const raw_target = @intFromEnum(target);
                        if (raw_target >= self.resolved_value_refs.records.len) {
                            return .{ .kind = .specialization_relation_value_ref_out_of_bounds, .index = @intCast(i) };
                        }
                        switch (self.resolved_value_refs.records[raw_target].ref) {
                            .top_level_proc,
                            .imported_proc,
                            .hosted_proc,
                            .promoted_top_level_proc,
                            .local_proc,
                            => {},
                            .platform_required_proc => |required| {
                                const source_fn_ty = required.procedure.source_fn_ty_payload orelse {
                                    return .{ .kind = .specialization_relation_direct_target_invalid, .index = @intCast(i) };
                                };
                                if (@intFromEnum(source_fn_ty) >= self.checked_types.payloadCount()) {
                                    return .{ .kind = .specialization_relation_type_out_of_bounds, .index = @intCast(i) };
                                }
                            },
                            .local_param,
                            .local_value,
                            .local_mutable_version,
                            .pattern_binder,
                            .selected_hoisted_const,
                            .top_level_const,
                            .imported_const,
                            .platform_required_declaration,
                            .platform_required_checked_error,
                            .platform_required_const,
                            => return .{ .kind = .specialization_relation_direct_target_invalid, .index = @intCast(i) },
                        }
                    }
                },
                .local_proc_use => |ref_id| {
                    const raw_ref = @intFromEnum(ref_id);
                    if (raw_ref >= self.resolved_value_refs.records.len) {
                        return .{ .kind = .specialization_relation_value_ref_out_of_bounds, .index = @intCast(i) };
                    }
                    const record = self.resolved_value_refs.records[raw_ref];
                    if (@intFromEnum(record.checked_ty) >= self.checked_types.payloadCount()) {
                        return .{ .kind = .specialization_relation_type_out_of_bounds, .index = @intCast(i) };
                    }
                    const local = switch (record.ref) {
                        .local_proc => |local| local,
                        .local_param,
                        .local_value,
                        .local_mutable_version,
                        .pattern_binder,
                        .selected_hoisted_const,
                        .top_level_const,
                        .imported_const,
                        .top_level_proc,
                        .imported_proc,
                        .hosted_proc,
                        .platform_required_declaration,
                        .platform_required_checked_error,
                        .platform_required_const,
                        .platform_required_proc,
                        .promoted_top_level_proc,
                        => return .{ .kind = .specialization_relation_local_proc_use_invalid, .index = @intCast(i) },
                    };
                    const local_scope = local.dispatch_scope orelse {
                        return .{ .kind = .specialization_relation_local_proc_use_invalid, .index = @intCast(i) };
                    };
                    if (@intFromEnum(local_scope) >= templates.dispatch_scopes.len) {
                        return .{ .kind = .specialization_relation_local_proc_use_invalid, .index = @intCast(i) };
                    }
                    if (templates.dispatch_scopes[@intFromEnum(local_scope)].checked_expr != local.expr) {
                        return .{ .kind = .specialization_relation_local_proc_use_invalid, .index = @intCast(i) };
                    }
                },
            }
        }
        for (templates.evidence_params_pool, 0..) |param, i| {
            if (@as(u64, param.path.start) + param.path.len > templates.evidence_param_paths.len) {
                return .{ .kind = .evidence_param_path_out_of_bounds, .index = @intCast(i), .method = param.method };
            }
            const path = templates.evidenceParamPath(param);
            if (evidencePathGrammarFailure(path)) |kind| {
                return .{ .kind = kind, .index = @intCast(i), .method = param.method };
            }
        }
        for (templates.templates) |template| {
            const params = templates.evidenceParams(&template);
            for (params, 0..) |param, param_offset| {
                const path = templates.evidenceParamPath(param);
                if (path.len == 0) continue;
                if (!self.checkedEvidencePathResolves(template.checked_fn_root, path)) {
                    return .{
                        .kind = .evidence_param_path_diverges_from_checked_type,
                        .index = template.evidence_params.start + @as(u32, @intCast(param_offset)),
                        .method = param.method,
                    };
                }
            }
        }
        for (templates.dispatch_scopes) |scope| {
            const params = templates.evidence_params_pool[scope.evidence_params.start .. scope.evidence_params.start + scope.evidence_params.len];
            for (params, 0..) |param, param_offset| {
                const path = templates.evidenceParamPath(param);
                if (path.len == 0) continue;
                if (!self.checkedEvidencePathResolves(scope.scheme_root, path)) {
                    return .{
                        .kind = .evidence_param_path_diverges_from_checked_type,
                        .index = scope.evidence_params.start + @as(u32, @intCast(param_offset)),
                        .method = param.method,
                    };
                }
            }
        }

        return null;
    }

    /// Verify the producer-authored runtime category for every method whose
    /// checked template is an annotation-only intrinsic wrapper. This runs only
    /// from the debug artifact verifier; release consumers trust the serialized
    /// category without repeating the classification work.
    fn verifyMethodIntrinsicRuntimeTargets(self: *const CheckedModuleArtifact) void {
        for (self.method_registry.entries, 0..) |entry, entry_index| {
            const procedure = switch (entry.target.kind) {
                .procedure => |procedure| procedure,
                .local_proc, .structural => continue,
            };
            if (!std.meta.eql(procedure.template.artifact.bytes, self.key.bytes)) {
                std.debug.panic(
                    "checked artifact invariant violated: method registry procedure {d} referenced a foreign checked template",
                    .{entry_index},
                );
            }
            const template_index = @intFromEnum(procedure.template.template);
            if (template_index >= self.checked_procedure_templates.templates.len) {
                std.debug.panic(
                    "checked artifact invariant violated: method registry procedure {d} referenced a missing checked template",
                    .{entry_index},
                );
            }
            const template = self.checked_procedure_templates.templates[template_index];
            const template_intrinsic: ?IntrinsicId = switch (template.body) {
                .intrinsic_wrapper => |wrapper_id| blk: {
                    const wrapper_index = @intFromEnum(wrapper_id);
                    if (wrapper_index >= self.intrinsic_wrappers.wrappers.len) {
                        std.debug.panic(
                            "checked artifact invariant violated: method registry procedure {d} referenced a missing intrinsic wrapper",
                            .{entry_index},
                        );
                    }
                    const wrapper = self.intrinsic_wrappers.wrappers[wrapper_index];
                    if (wrapper.template.template != procedure.template.template) {
                        std.debug.panic(
                            "checked artifact invariant violated: method registry procedure {d} referenced the wrong intrinsic wrapper template",
                            .{entry_index},
                        );
                    }
                    break :blk wrapper.intrinsic;
                },
                .checked_body, .entry_wrapper => null,
            };

            switch (procedure.runtime_target) {
                .intrinsic => |runtime_intrinsic| {
                    if (runtime_intrinsic.callsiteArity() == null or
                        template_intrinsic == null or
                        template_intrinsic.? != runtime_intrinsic)
                    {
                        std.debug.panic(
                            "checked artifact invariant violated: method registry procedure {d} had inconsistent call-site intrinsic metadata",
                            .{entry_index},
                        );
                    }
                },
                .procedure, .low_level, .graph_participating => {
                    if (template_intrinsic) |intrinsic| {
                        if (intrinsic.callsiteArity() != null) {
                            std.debug.panic(
                                "checked artifact invariant violated: method registry procedure {d} lost its call-site intrinsic runtime target",
                                .{entry_index},
                            );
                        }
                    }
                },
            }
        }
    }

    pub fn verifyComplete(self: *const CheckedModuleArtifact) Allocator.Error!void {
        if (builtin.mode != .Debug) return;

        std.debug.assert(self.module_identity.module_idx != std.math.maxInt(u32));
        verifyRootRequestSubsets(self.root_requests);
        self.verifyMethodIntrinsicRuntimeTargets();

        if (self.hasUnboundPlatformRequirements()) {
            for (self.root_requests.runtime_requests) |request| {
                if (request.kind == .provided_export) {
                    std.debug.panic(
                        "checked artifact invariant violated: relationless required platform published a provided runtime root",
                        .{},
                    );
                }
            }
        }

        if (self.validateDispatchEvidence()) |failure| {
            const expr_idx: ?u32 = if (failure.expr) |expr| @intFromEnum(expr) else null;
            const method_text: []const u8 = if (failure.method) |method| self.canonical_names.methodNameText(method) else "<none>";
            std.debug.panic(
                "checked artifact invariant violated: dispatch evidence boundary: {s} (expr {?d}, index {?d}, method {s})",
                .{ @tagName(failure.kind), expr_idx, failure.index, method_text },
            );
        }

        for (self.root_requests.requests, 0..) |request, i| {
            std.debug.assert(request.order == i);
            std.debug.assert(request.module_idx == self.module_identity.module_idx);
            std.debug.assert(@intFromEnum(request.checked_type) < self.checked_types.roots.items.len);
            if (request.procedure_template) |template_ref| {
                std.debug.assert(checkedArtifactKeyEql(
                    checkedArtifactKeyFromArtifactRef(template_ref.artifact),
                    self.key,
                ));
                std.debug.assert(@intFromEnum(template_ref.template) < self.checked_procedure_templates.templates.len);
                const evidence = request.root_evidence orelse {
                    std.debug.panic("checked artifact invariant violated: procedure template root has no checked evidence vector", .{});
                };
                std.debug.assert(checkedArtifactKeyEql(evidence.checked_module, self.key));
                if (@as(u64, evidence.span.start) + evidence.span.len > self.static_dispatch_plans.evidence_refs.len) {
                    std.debug.panic("checked artifact invariant violated: procedure template root evidence was outside the app evidence table", .{});
                }
            }
            if (request.kind == .test_expect or
                request.kind == .compile_time_constant or
                request.kind == .compile_time_callable)
            {
                const template_ref = request.procedure_template orelse {
                    std.debug.panic("checked artifact invariant violated: compile-time/test root has no entry wrapper template", .{});
                };
                std.debug.assert(@intFromEnum(template_ref.template) < self.checked_procedure_templates.templates.len);
            }
            if (request.kind == .platform_required_binding and request.procedure_use != null) {
                _ = request.root_evidence orelse {
                    std.debug.panic("checked artifact invariant violated: platform procedure root has no checked evidence vector", .{});
                };
            }
        }

        for (self.platform_requirement_solutions.solutions) |solution| {
            if (solution.value_kind != .procedure_value) continue;
            if (@as(u64, solution.root_evidence.start) + solution.root_evidence.len > self.static_dispatch_plans.evidence_refs.len) {
                std.debug.panic("checked artifact invariant violated: platform requirement root evidence was outside the app evidence table", .{});
            }
        }

        for (self.compile_time_roots.roots, 0..) |root, i| {
            std.debug.assert(@intFromEnum(root.id) == i);
            std.debug.assert(root.module_idx == self.module_identity.module_idx);
            std.debug.assert(@intFromEnum(root.expr) < self.checked_bodies.exprCount());
            verifyCompileTimeRootLiteralConversion(root);
            if (root.pattern) |pattern| std.debug.assert(@intFromEnum(pattern) < self.checked_bodies.patternCount());
            if (root.kind == .expect) {
                switch (root.payload) {
                    .expect => {},
                    .pending, .const_node, .fn_value => std.debug.panic("checked artifact invariant violated: expect root has non-expect payload", .{}),
                }
                continue;
            }
            const has_request = compileTimeRootHasRootRequest(self.root_requests.requests, root);
            switch (root.payload) {
                .pending => {
                    if (has_request) {
                        std.debug.panic("checked artifact invariant violated: requested compile-time root has pending payload", .{});
                    }
                },
                .const_node, .fn_value, .expect => {
                    if (!has_request) {
                        std.debug.panic("checked artifact invariant violated: non-requested compile-time root has concrete payload", .{});
                    }
                    verifyCompileTimeRootPayloadMatchesKind(root.kind, root.payload);
                },
            }
        }

        std.debug.assert(std.meta.eql(self.key.direct_import_artifact_keys_hash, hashDirectImportArtifactKeys(self.direct_import_artifact_keys)));

        for (self.hosted_procs.procs, 0..) |proc, i| {
            std.debug.assert(proc.deterministic_index == i);
            std.debug.assert(proc.module_idx == self.module_identity.module_idx);
        }

        for (self.checked_types.roots.items, 0..) |root, i| {
            std.debug.assert(@intFromEnum(root.id) == i);
            std.debug.assert(self.checked_types.payloads.items.len == self.checked_types.roots.items.len);
            switch (self.checked_types.payloads.items[i]) {
                .pending => std.debug.panic("checked artifact invariant violated: checked type payload {d} was not filled", .{i}),
                .err,
                .flex,
                .rigid,
                .alias,
                .record,
                .record_unbound,
                .tuple,
                .nominal,
                .function,
                .empty_record,
                .tag_union,
                .empty_tag_union,
                => {},
            }
        }

        for (self.checked_bodies.stored_exprs.items, 0..) |expr, i| {
            std.debug.assert(@intFromEnum(expr.id) == i);
            std.debug.assert(@intFromEnum(expr.ty) < self.checked_types.roots.items.len);
            verifyCheckedExprDataComplete(expr.data, &self.checked_bodies, self.checked_types.roots.items.len);
        }

        for (self.checked_bodies.stored_patterns.items, 0..) |pattern, i| {
            std.debug.assert(@intFromEnum(pattern.id) == i);
            std.debug.assert(@intFromEnum(pattern.ty) < self.checked_types.roots.items.len);
            verifyCheckedPatternDataComplete(pattern.data);
        }

        for (self.checked_bodies.pattern_binders.items, 0..) |binder, i| {
            std.debug.assert(@intFromEnum(binder.id) == i);
            std.debug.assert(@intFromEnum(binder.pattern) < self.checked_bodies.patternCount());
            const indexed = self.checked_bodies.pattern_binder_by_pattern.items[@intFromEnum(binder.pattern)] orelse {
                std.debug.panic("checked artifact invariant violated: pattern binder was not indexed by pattern", .{});
            };
            std.debug.assert(indexed == binder.id);
        }

        for (self.checked_bodies.stored_statements.items, 0..) |statement, i| {
            std.debug.assert(@intFromEnum(statement.id) == i);
            verifyCheckedStatementDataComplete(statement.data);
        }

        for (self.checked_const_bodies.bodies, 0..) |body, i| {
            std.debug.assert(@intFromEnum(body.id) == i);
            std.debug.assert(@intFromEnum(body.root) < self.compile_time_roots.roots.len);
            const root = self.compile_time_roots.root(body.root);
            std.debug.assert(compileTimeRootHasConstBody(root.kind));
            std.debug.assert(root.expr == body.body_expr);
            std.debug.assert(root.checked_type == body.checked_type);
            std.debug.assert(@intFromEnum(body.body_expr) < self.checked_bodies.exprCount());
            std.debug.assert(@intFromEnum(body.checked_type) < self.checked_types.roots.items.len);
        }

        for (self.checked_procedure_templates.templates, 0..) |template, i| {
            std.debug.assert(@intFromEnum(template.template_id) == i);
            std.debug.assert(@intFromEnum(template.checked_fn_root) < self.checked_types.roots.items.len);
            _ = self.checked_types.schemeForKey(template.checked_fn_scheme) orelse {
                std.debug.panic("checked artifact invariant violated: checked procedure template references missing type scheme", .{});
            };
            switch (template.body) {
                .checked_body => |body| {
                    const checked_body = self.checked_bodies.body(body);
                    std.debug.assert(checked_body.owner_template.template == template.template_id);
                    std.debug.assert(checked_body.owner_template.proc_base == template.proc_base);
                    std.debug.assert(@intFromEnum(checked_body.root_expr) < self.checked_bodies.exprCount());
                },
                .intrinsic_wrapper => |wrapper_id| {
                    const wrapper = self.intrinsic_wrappers.get(wrapper_id);
                    std.debug.assert(wrapper.checked_fn_root == template.checked_fn_root);
                    std.debug.assert(wrapper.template.template == template.template_id);
                    std.debug.assert(wrapper.template.proc_base == template.proc_base);
                    std.debug.assert(std.meta.eql(wrapper.template.artifact.bytes, self.key.bytes));
                },
                .entry_wrapper => |wrapper_id| {
                    const wrapper = self.entry_wrappers.get(wrapper_id);
                    std.debug.assert(@intFromEnum(wrapper.body_expr) < self.checked_bodies.exprCount());
                    std.debug.assert(@intFromEnum(wrapper.checked_fn_root) < self.checked_types.roots.items.len);
                    std.debug.assert(wrapper.checked_fn_root == template.checked_fn_root);
                    std.debug.assert(wrapper.template.template == template.template_id);
                    std.debug.assert(wrapper.template.proc_base == template.proc_base);
                    std.debug.assert(std.meta.eql(wrapper.template.artifact.bytes, self.key.bytes));
                },
            }

            const nested_end = template.nested_proc_sites.start + template.nested_proc_sites.len;
            std.debug.assert(nested_end <= self.nested_proc_sites.template_refs.len);
            for (self.nested_proc_sites.template_refs[template.nested_proc_sites.start..nested_end]) |site_id| {
                std.debug.assert(@intFromEnum(site_id) < self.nested_proc_sites.sites.len);
                const site = self.nested_proc_sites.sites[@intFromEnum(site_id)];
                std.debug.assert(site.owner_template.template == template.template_id);
                std.debug.assert(site.owner_template.proc_base == template.proc_base);
                std.debug.assert(std.meta.eql(site.owner_template.artifact.bytes, self.key.bytes));
            }
        }

        for (self.nested_proc_sites.sites, 0..) |site, i| {
            std.debug.assert(@intFromEnum(site.site) == i);
            std.debug.assert(site.path_len > 0);
            std.debug.assert(site.path_start + site.path_len <= self.nested_proc_sites.path_components.len);
            std.debug.assert(@intFromEnum(site.owner_template.template) < self.checked_procedure_templates.templates.len);
            switch (site.lexical_scope) {
                .root => {},
                .generalized => |scope| std.debug.assert(@intFromEnum(scope) < self.checked_procedure_templates.dispatch_scopes.len),
            }
            switch (site.evidence_source) {
                .inherited => std.debug.assert(site.evidence.len == 0),
                .checked_site => std.debug.assert(
                    site.evidence.start <= self.static_dispatch_plans.evidence_refs.len and
                        site.evidence.len <= self.static_dispatch_plans.evidence_refs.len - site.evidence.start,
                ),
            }
            if (site.checked_expr) |expr| std.debug.assert(@intFromEnum(expr) < self.checked_bodies.exprCount());
            if (site.checked_pattern) |pattern| std.debug.assert(@intFromEnum(pattern) < self.checked_bodies.patternCount());
        }

        for (self.exported_procedure_templates.templates) |exported| {
            const closure = self.exported_procedure_templates.rowClosure(exported);
            std.debug.assert(std.meta.eql(exported.template.artifact.bytes, self.key.bytes));
            std.debug.assert(@intFromEnum(exported.template.template) < self.checked_procedure_templates.templates.len);
            std.debug.assert(closure.checked_procedure_templates.len > 0);
            std.debug.assert(closure.checked_type_roots.len > 0);
            std.debug.assert(closure.checked_type_schemes.len > 0);
            std.debug.assert(closure.interface_capabilities.len > 0);
            for (closure.checked_bodies) |body_ref| {
                if (closureArtifactRefIsLocal(self, body_ref.artifact)) {
                    std.debug.assert(@intFromEnum(body_ref.body) < self.checked_bodies.bodyCount());
                }
            }
            for (closure.checked_type_roots) |type_ref| {
                if (closureArtifactRefIsLocal(self, type_ref.artifact)) {
                    std.debug.assert(@intFromEnum(type_ref.ty) < self.checked_types.roots.items.len);
                }
            }
            for (closure.checked_type_schemes) |scheme_ref| {
                if (closureArtifactRefIsLocal(self, scheme_ref.artifact)) {
                    std.debug.assert(@intFromEnum(scheme_ref.scheme) < self.checked_types.schemes.items.len);
                }
            }
        }

        for (self.exported_procedure_bindings.bindings) |exported| {
            const closure = self.exported_procedure_bindings.rowClosure(exported);
            std.debug.assert(std.meta.eql(exported.binding.artifact.bytes, self.key.bytes));
            switch (exported.body) {
                .direct_template => {
                    std.debug.assert(closure.checked_procedure_templates.len > 0);
                    std.debug.assert(closure.checked_type_roots.len > 0);
                    std.debug.assert(closure.interface_capabilities.len > 0);
                },
                .callable_eval_template => |template_id| {
                    std.debug.assert(@intFromEnum(template_id) < self.callable_eval_templates.templates.len);
                    std.debug.assert(closure.callable_eval_templates.len > 0);
                    std.debug.assert(closure.checked_type_roots.len > 0);
                    std.debug.assert(closure.interface_capabilities.len > 0);
                },
            }
        }

        for (self.exported_const_templates.templates) |exported| {
            const closure = self.exported_const_templates.rowClosure(exported);
            std.debug.assert(std.meta.eql(exported.const_ref.artifact.bytes, self.key.bytes));
            std.debug.assert(@intFromEnum(exported.const_ref.template) < self.const_templates.templates.items.len);
            std.debug.assert(closure.const_templates.len > 0);
            std.debug.assert(closure.checked_type_roots.len > 0);
            std.debug.assert(closure.checked_type_schemes.len > 0);
            std.debug.assert(closure.interface_capabilities.len > 0);
            switch (exported.template.state) {
                .eval_template => |eval| {
                    std.debug.assert(@intFromEnum(eval.body) < self.checked_const_bodies.bodies.len);
                    std.debug.assert(std.meta.eql(eval.entry_template.artifact.bytes, self.key.bytes));
                    std.debug.assert(@intFromEnum(eval.entry_template.template) < self.checked_procedure_templates.templates.len);
                    std.debug.assert(closure.checked_const_bodies.len > 0);
                    std.debug.assert(closure.checked_procedure_templates.len > 0);
                },
                .stored_const => |stored| {
                    std.debug.assert(@intFromEnum(stored.node) < self.const_store.values.items.len);
                    std.debug.assert(@intFromEnum(stored.root_type) < self.const_store.type_store.types.items.len);
                },
                .reserved => std.debug.panic(
                    "checked artifact invariant violated: exported const template was not sealed",
                    .{},
                ),
            }
            for (closure.const_templates) |const_ref| {
                if (closureArtifactRefIsLocal(self, const_ref.artifact)) {
                    std.debug.assert(@intFromEnum(const_ref.template) < self.const_templates.templates.items.len);
                }
            }
            for (closure.checked_type_roots) |type_ref| {
                if (closureArtifactRefIsLocal(self, type_ref.artifact)) {
                    std.debug.assert(@intFromEnum(type_ref.ty) < self.checked_types.roots.items.len);
                }
            }
            for (closure.checked_type_schemes) |scheme_ref| {
                if (closureArtifactRefIsLocal(self, scheme_ref.artifact)) {
                    std.debug.assert(@intFromEnum(scheme_ref.scheme) < self.checked_types.schemes.items.len);
                }
            }
            for (closure.checked_const_bodies) |body_ref| {
                if (closureArtifactRefIsLocal(self, body_ref.artifact)) {
                    std.debug.assert(@intFromEnum(body_ref.body) < self.checked_const_bodies.bodies.len);
                }
            }
        }

        for (self.platform_required_declarations.declarations, 0..) |declaration, i| {
            std.debug.assert(@intFromEnum(declaration.id) == i);
            std.debug.assert(declaration.requires_idx == i);
            std.debug.assert(declaration.module_idx == self.module_identity.module_idx);
        }

        for (self.platform_requirement_relations.relations, 0..) |relation, i| {
            std.debug.assert(@intFromEnum(relation.id) == i);
            std.debug.assert(relation.module_idx == self.module_identity.module_idx);
            const declaration = self.platform_required_declarations.lookupByDeclarationId(relation.declaration) orelse {
                std.debug.panic(
                    "checked artifact invariant violated: platform requirement relation {d} has no declaration",
                    .{i},
                );
            };
            std.debug.assert(declaration.requires_idx == relation.requires_idx);
            const payload_index = @intFromEnum(relation.requested_source_ty_payload);
            if (payload_index >= self.checked_types.roots.items.len) {
                std.debug.panic(
                    "checked artifact invariant violated: platform requirement relation {d} requested payload is out of range",
                    .{i},
                );
            }
            if (!canonicalTypeKeyEql(self.checked_types.roots.items[payload_index].key, relation.requested_source_ty)) {
                std.debug.panic(
                    "checked artifact invariant violated: platform requirement relation {d} requested payload key disagrees with relation key",
                    .{i},
                );
            }
            switch (relation.value_kind) {
                .const_value, .procedure_value => {},
            }
        }

        for (self.platform_required_bindings.bindings, 0..) |binding, i| {
            std.debug.assert(@intFromEnum(binding.id) == i);
            std.debug.assert(binding.module_idx == self.module_identity.module_idx);
            _ = self.platform_required_declarations.lookupByRequiredIndex(binding.requires_idx) orelse {
                std.debug.panic(
                    "checked artifact invariant violated: platform required binding {d} has no declaration",
                    .{i},
                );
            };
            const relation = self.platform_requirement_relations.lookupByRelationId(binding.checked_relation) orelse {
                std.debug.panic(
                    "checked artifact invariant violated: platform required binding {d} has no checked relation",
                    .{i},
                );
            };
            validatePlatformBindingRelation(binding.declaration, binding.requires_idx, binding.app_value, std.meta.activeTag(binding.value_use), relation, i);
            verifyPlatformRequiredValueUse(self, binding);
        }
        for (self.platform_required_bindings.checked_error_requires) |requires_idx| {
            _ = self.platform_required_declarations.lookupByRequiredIndex(requires_idx) orelse {
                std.debug.panic(
                    "checked artifact invariant violated: platform checked-error requirement {d} has no declaration",
                    .{requires_idx},
                );
            };
            if (self.platform_required_bindings.lookupByRequiredIndex(requires_idx) != null) {
                std.debug.panic(
                    "checked artifact invariant violated: platform requirement {d} is both bound and a checked error",
                    .{requires_idx},
                );
            }
        }

        for (self.callable_eval_templates.templates, 0..) |template, i| {
            std.debug.assert(@intFromEnum(template.id) == i);
            std.debug.assert(template.module_idx == self.module_identity.module_idx);
            std.debug.assert(@intFromEnum(template.pattern) < self.checked_bodies.patternCount());
            std.debug.assert(@intFromEnum(template.root) < self.compile_time_roots.roots.len);
            const root = self.compile_time_roots.root(template.root);
            std.debug.assert(root.kind == .callable_binding);
            std.debug.assert(root.pattern != null and root.pattern.? == template.pattern);
            std.debug.assert(@intFromEnum(template.checked_fn_root) < self.checked_types.roots.items.len);
            _ = self.checked_types.schemeForKey(template.source_scheme) orelse {
                std.debug.panic("checked artifact invariant violated: callable eval template references missing type scheme", .{});
            };
        }

        for (self.top_level_values.entries) |entry| {
            std.debug.assert(@intFromEnum(entry.pattern) < self.checked_bodies.patternCount());
            _ = self.canonical_names.exportNameText(entry.source_name);
            switch (entry.value) {
                .const_ref => |const_ref| {
                    const owner = constRefTopLevelOwner(const_ref) orelse {
                        std.debug.panic("checked artifact invariant violated: top-level value table referenced a non-top-level ConstRef", .{});
                    };
                    std.debug.assert(owner.module_idx == self.module_identity.module_idx);
                    std.debug.assert(owner.pattern == entry.pattern);
                    std.debug.assert(std.meta.eql(const_ref.source_scheme.bytes, entry.source_scheme.bytes));
                },
                .procedure_binding => |binding_ref| {
                    const binding = self.top_level_procedure_bindings.get(binding_ref);
                    switch (binding.body) {
                        .direct_template => |direct| {
                            _ = self.canonical_names.procBase(direct.proc_value.proc_base);
                            switch (direct.template) {
                                .checked => |template| {
                                    std.debug.assert(template.proc_base == direct.proc_value.proc_base);
                                    std.debug.assert(std.meta.eql(template.artifact.bytes, direct.proc_value.artifact.bytes));
                                },
                                .synthetic => |synthetic| {
                                    std.debug.assert(synthetic.template.proc_base == direct.proc_value.proc_base);
                                    std.debug.assert(std.meta.eql(synthetic.template.artifact.bytes, direct.proc_value.artifact.bytes));
                                    std.debug.assert(@intFromEnum(synthetic.template.template) < self.checked_procedure_templates.templates.len);
                                },
                                .lifted => std.debug.panic(
                                    "checked artifact invariant violated: direct top-level binding cannot use lifted template before mono",
                                    .{},
                                ),
                            }
                        },
                        .callable_eval_template => |template| {
                            std.debug.assert(@intFromEnum(template) < self.callable_eval_templates.templates.len);
                        },
                    }
                },
            }
        }

        for (self.provides_requires.requires) |entry| {
            _ = self.canonical_names.exportNameText(entry.platform_name);
            _ = self.checked_types.schemeForKey(entry.declared_source_ty) orelse {
                std.debug.panic("checked artifact invariant violated: require metadata source type was not published", .{});
            };
        }

        if (self.provided_exports.exports.len != self.provides_requires.provides.len) {
            std.debug.panic("checked artifact invariant violated: provided export table does not match provides metadata", .{});
        }
        for (self.provided_exports.exports, self.provides_requires.provides) |provided, metadata| {
            switch (provided) {
                .procedure => |procedure| {
                    std.debug.assert(procedure.source_name == metadata.source_name);
                    std.debug.assert(procedure.ffi_symbol == metadata.ffi_symbol);
                    std.debug.assert(procedure.def == metadata.def);
                    std.debug.assert(@intFromEnum(procedure.checked_type) < self.checked_types.roots.items.len);
                    const top_level = self.top_level_values.lookupByDef(procedure.def) orelse {
                        std.debug.panic("checked artifact invariant violated: provided procedure export references missing top-level value", .{});
                    };
                    std.debug.assert(top_level.pattern == procedure.pattern);
                    std.debug.assert(top_level.source_name == procedure.source_name);
                    std.debug.assert(std.meta.eql(top_level.source_scheme.bytes, procedure.source_scheme.bytes));
                    switch (top_level.value) {
                        .procedure_binding => |binding| std.debug.assert(binding == procedure.binding),
                        .const_ref => std.debug.panic("checked artifact invariant violated: provided procedure export references const top-level value", .{}),
                    }
                },
                .data => |data| {
                    std.debug.assert(data.source_name == metadata.source_name);
                    std.debug.assert(data.ffi_symbol == metadata.ffi_symbol);
                    std.debug.assert(data.def == metadata.def);
                    std.debug.assert(@intFromEnum(data.checked_type) < self.checked_types.roots.items.len);
                    const top_level = self.top_level_values.lookupByDef(data.def) orelse {
                        std.debug.panic("checked artifact invariant violated: provided data export references missing top-level value", .{});
                    };
                    std.debug.assert(top_level.pattern == data.pattern);
                    std.debug.assert(top_level.source_name == data.source_name);
                    std.debug.assert(std.meta.eql(top_level.source_scheme.bytes, data.source_scheme.bytes));
                    switch (top_level.value) {
                        .const_ref => |const_ref| std.debug.assert(constRefEql(const_ref, data.const_ref)),
                        .procedure_binding => std.debug.panic("checked artifact invariant violated: provided data export references procedure top-level value", .{}),
                    }
                },
            }
        }

        for (self.const_templates.templates.items) |template| {
            switch (template.state) {
                .stored_const => |stored| {
                    std.debug.assert(@intFromEnum(stored.node) < self.const_store.values.items.len);
                    std.debug.assert(@intFromEnum(stored.root_type) < self.const_store.type_store.types.items.len);
                },
                .eval_template, .reserved => {},
            }
        }
        self.const_templates.verifySealed();
        try self.const_store.verifyComplete();
        self.interface_capabilities.verifyComplete();
        for (self.interface_capabilities.hosted_representations) |entry| {
            if (@intFromEnum(entry.host_checked_fn_root) >= self.checked_types.roots.items.len) {
                std.debug.panic("checked artifact invariant violated: hosted representation references missing host checked function root", .{});
            }
        }
        for (self.resolved_value_refs.records) |record| {
            std.debug.assert(@intFromEnum(record.expr) < self.checked_bodies.exprCount());
            if (self.checking_context_identity.platform_app_relation != null) {
                switch (record.ref) {
                    .platform_required_declaration => std.debug.panic(
                        "checked artifact invariant violated: executable platform artifact kept a declaration-only required lookup",
                        .{},
                    ),
                    .local_param,
                    .local_value,
                    .local_mutable_version,
                    .pattern_binder,
                    .local_proc,
                    .selected_hoisted_const,
                    .top_level_const,
                    .imported_const,
                    .top_level_proc,
                    .imported_proc,
                    .hosted_proc,
                    .platform_required_checked_error,
                    .platform_required_const,
                    .platform_required_proc,
                    .promoted_top_level_proc,
                    => {},
                }
            }
        }

        verifyLoweringVisibleNamesInterned(self.moduleEnvConst(), &self.canonical_names);
    }
};
/// Short name for checked module data.
pub const Module = CheckedModuleArtifact;

fn verifyPlatformRequiredValueUse(self: *const CheckedModuleArtifact, binding: PlatformRequiredBinding) void {
    if (builtin.mode != .Debug) return;

    switch (binding.value_use) {
        .const_value => |const_use| {
            std.debug.assert(std.meta.eql(const_use.const_use.const_ref.artifact.bytes, binding.app_value.artifact.bytes));
            const owner = constRefTopLevelOwner(const_use.const_use.const_ref) orelse {
                std.debug.panic("checked artifact invariant violated: platform-required const use referenced a non-top-level ConstRef", .{});
            };
            std.debug.assert(owner.pattern == binding.app_value.pattern);
        },
        .procedure_value => |procedure_use| switch (procedure_use.procedure.binding) {
            .platform_required => |required| {
                std.debug.assert(std.meta.eql(required.artifact.bytes, binding.app_value.artifact.bytes));
                std.debug.assert(required.app_value.pattern == binding.app_value.pattern);
                if (self.platform_required_bindings.relationClosure(binding).interface_capabilities.len == 0) {
                    std.debug.panic(
                        "checked artifact invariant violated: platform-required procedure use has no relation template closure",
                        .{},
                    );
                }
                const evidence = procedure_use.root_evidence orelse {
                    std.debug.panic("checked artifact invariant violated: platform-required procedure use has no root evidence", .{});
                };
                std.debug.assert(std.meta.eql(evidence.checked_module.bytes, binding.app_value.artifact.bytes));
            },
            .top_level,
            .imported,
            .hosted,
            => std.debug.panic(
                "checked artifact invariant violated: platform-required procedure use must reference the app requirement binding explicitly",
                .{},
            ),
        },
    }
}

/// Public `ImportedModuleView` declaration.
